def _dep_install_hint() -> str:
    return (
        "Install core deps with the SAME Python you run this file with:\n\n"
        "  py -m pip install customtkinter numpy\n\n"
        "Optional (for web + jobs):\n"
        "  py -m pip install requests\n\n"
        "If you already ran pip, you might have installed into a different Python.\n"
        "Check:\n"
        "  py -c \"import sys; print(sys.executable)\"\n"
        "  py -m pip --version\n"
    )

def _fatal_dep(message: str) -> None:
    # Prefer a GUI messagebox if tkinter is available; otherwise print to console.
    try:
        import tkinter as _tk  # noqa
        from tkinter import messagebox as _mb  # noqa
        root = _tk.Tk()
        root.withdraw()
        _mb.showerror("Infinite Porch — Missing Dependency", message)
        try:
            root.destroy()
        except Exception:
            pass
    except Exception:
        pass
    print(message)
    raise SystemExit(1)


