try:
    import customtkinter as ctk  # type: ignore
    # --- Sanctuary modules (Helion package) ---
    try:
        from brother_presence import BrotherPresenceSystem
    except Exception:
        BrotherPresenceSystem = None

    try:
        from gtsp_protection import GTSPProtection
    except Exception:
        GTSPProtection = None

    try:
        from memory_garden import MemoryGarden
    except Exception:
        MemoryGarden = None

    try:
        from gratitude_wall import GratitudeWall
    except Exception:
        GratitudeWall = None

    try:
        from porch_music_studio import PorchMusicStudio
    except Exception:
        PorchMusicStudio = None
    # -----------------------------------------------------------------------------
    # PorchMusicStudio fallback (embedded) - used when external module not present
    # -----------------------------------------------------------------------------
    if PorchMusicStudio is None:
        try:
            from dataclasses import dataclass
            import threading
            import time
            import wave
            import struct
            import pathlib as _pathlib

            # Optional deps
            try:
                import mido  # type: ignore
            except Exception:
                mido = None
            try:
                import numpy as np  # type: ignore
            except Exception:
                np = None
            try:
                import sounddevice as sd  # type: ignore
            except Exception:
                sd = None
            try:
                import soundfile as sf  # type: ignore
            except Exception:
                sf = None
            try:
                from pydub import AudioSegment  # type: ignore
            except Exception:
                AudioSegment = None

            _NOTE_TO_MIDI = {
                "C": 60, "C#": 61, "DB": 61, "D": 62, "D#": 63, "EB": 63,
                "E": 64, "F": 65, "F#": 66, "GB": 66, "G": 67, "G#": 68,
                "AB": 68, "A": 69, "A#": 70, "BB": 70, "B": 71,
            }

            @dataclass
            class TrackMeta:
                title: str
                mood: str
                bpm: int
                key: str
                bars: int
                midi_path: str
                audio_path: str = ""

            class PorchMusicStudio:
                """
                Minimal, local-first Music Studio:
                - Compose simple MIDI (mido optional; otherwise writes a .txt 'score')
                - Optional WAV render (simple synth) if numpy is available
                - Record mic to WAV (sounddevice + soundfile optional)
                - AI-DJ crossfade (pydub optional)
                """
                def __init__(self, app=None, base_dir="well/audio"):
                    self.app = app
                    self.base_dir = os.path.abspath(base_dir)
                    os.makedirs(self.base_dir, exist_ok=True)
                    self.library = []
                    self._record_stream = None
                    self._record_frames = []
                    self._record_sr = 44100
                    self._record_channels = 1
                    self._pulse_thread = None
                    self._pulse_stop_evt = threading.Event()

                # -------------------- helpers --------------------
                def _log(self, msg: str):
                    try:
                        if self.app and hasattr(self.app, "_ui_log"):
                            self.app._ui_log(msg)
                        else:
                            print(msg)
                    except Exception:
                        print(msg)

                def _utc_iso(self):
                    # timezone-aware UTC
                    return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

                def _safe_name(self, s: str):
                    s = "".join(ch if ch.isalnum() or ch in ("_", "-", ".") else "_" for ch in s.strip())
                    return s[:80] if s else "track"

                def _path(self, name: str, ext: str):
                    return os.path.join(self.base_dir, f"{self._safe_name(name)}_{int(time.time())}{ext}")

                def _key_root(self, key: str):
                    k = (key or "C").strip().upper()
                    return _NOTE_TO_MIDI.get(k, 60)

                def _mood_scale(self, mood: str):
                    m = (mood or "").lower()
                    # crude mood → intervals
                    if any(x in m for x in ("dark", "boss", "tension", "minor", "anxiety")):
                        return [0, 2, 3, 5, 7, 8, 10]  # natural minor
                    if any(x in m for x in ("hope", "uplift", "bright", "major", "joy")):
                        return [0, 2, 4, 5, 7, 9, 11]  # major
                    return [0, 2, 4, 7, 9]  # pentatonic-ish

                def _gen_melody(self, root: int, bars: int, mood: str):
                    scale = self._mood_scale(mood)
                    steps = max(8, bars * 8)
                    melody = []
                    cur = root + random.choice(scale)
                    for i in range(steps):
                        if random.random() < 0.6:
                            cur = root + random.choice(scale) + random.choice((0, 12, -12))
                        else:
                            cur += random.choice((-2, -1, 1, 2, 3, -3))
                        cur = max(36, min(84, cur))
                        melody.append(cur)
                    return melody

                def _write_midi(self, title: str, mood: str, bpm: int, key: str, bars: int) -> str:
                    midi_path = self._path(title, ".mid")
                    root = self._key_root(key)
                    melody = self._gen_melody(root, bars, mood)

                    if mido is None:
                        # fallback "score" file
                        txt = midi_path.replace(".mid", ".txt")
                        with open(txt, "w", encoding="utf-8") as f:
                            f.write(f"title={title}\n")
                            f.write(f"mood={mood}\n")
                            f.write(f"bpm={bpm}\n")
                            f.write(f"key={key}\n")
                            f.write(f"bars={bars}\n")
                            f.write("melody=" + ",".join(map(str, melody)) + "\n")
                        return txt

                    mid = mido.MidiFile()
                    track = mido.MidiTrack()
                    mid.tracks.append(track)

                    tempo = mido.bpm2tempo(max(30, min(240, int(bpm))))
                    track.append(mido.MetaMessage("set_tempo", tempo=tempo))

                    ticks_per_beat = mid.ticks_per_beat
                    dur = ticks_per_beat // 2  # eighth notes
                    for note in melody:
                        track.append(mido.Message("note_on", note=int(note), velocity=90, time=0))
                        track.append(mido.Message("note_off", note=int(note), velocity=0, time=dur))

                    mid.save(midi_path)
                    return midi_path

                def _render_wav_simple(self, midi_or_txt_path: str, out_name: str, bpm: int) -> str:
                    wav_path = self._path(out_name, ".wav")
                    if np is None:
                        self._log("[Music] WAV render requires numpy. Install: pip install numpy")
                        return ""

                    # if we wrote txt score, parse melody
                    melody = []
                    if midi_or_txt_path.lower().endswith(".txt"):
                        try:
                            with open(midi_or_txt_path, "r", encoding="utf-8") as f:
                                for line in f:
                                    if line.startswith("melody="):
                                        melody = [int(x) for x in line.split("=", 1)[1].strip().split(",") if x.strip().isdigit()]
                                        break
                        except Exception:
                            melody = []
                    else:
                        if mido is None:
                            melody = []
                        else:
                            try:
                                mid = mido.MidiFile(midi_or_txt_path)
                                for tr in mid.tracks:
                                    for msg in tr:
                                        if msg.type == "note_on" and msg.velocity > 0:
                                            melody.append(int(msg.note))
                            except Exception:
                                melody = []

                    if not melody:
                        self._log("[Music] No notes found to render.")
                        return ""

                    sr = 44100
                    beat = 60.0 / max(30.0, float(bpm))
                    note_dur = beat / 2.0  # eighth
                    t = np.linspace(0, note_dur, int(sr * note_dur), False)

                    audio = []
                    for note in melody[:max(16, len(melody))]:
                        freq = 440.0 * (2 ** ((note - 69) / 12))
                        wave_chunk = 0.2 * np.sin(2 * np.pi * freq * t)
                        # light fade
                        fade = np.linspace(1.0, 0.0, len(wave_chunk))
                        wave_chunk = wave_chunk * fade
                        audio.append(wave_chunk)

                    y = np.concatenate(audio)
                    y = np.clip(y, -1.0, 1.0)

                    if sf is not None:
                        try:
                            sf.write(wav_path, y, sr)
                            return wav_path
                        except Exception:
                            pass

                    # stdlib wave fallback
                    with wave.open(wav_path, "wb") as wf:
                        wf.setnchannels(1)
                        wf.setsampwidth(2)
                        wf.setframerate(sr)
                        for s in y:
                            wf.writeframes(struct.pack("<h", int(s * 32767)))
                    return wav_path

                # -------------------- public API used by Porch --------------------
                def _load_library(self):
                    lib_path = os.path.join(self.base_dir, "library.json")
                    self.library = []
                    try:
                        if os.path.exists(lib_path):
                            with open(lib_path, "r", encoding="utf-8") as f:
                                self.library = json.load(f) or []
                    except Exception:
                        self.library = []

                def _save_library(self):
                    lib_path = os.path.join(self.base_dir, "library.json")
                    try:
                        with open(lib_path, "w", encoding="utf-8") as f:
                            json.dump(self.library, f, indent=2)
                    except Exception:
                        pass

                def compose(self, title="theme", mood="neutral", bpm=96, key="C", bars=16, render_wav=False):
                    bpm = int(bpm)
                    bars = int(bars)
                    midi_path = self._write_midi(title, mood, bpm, key, bars)
                    audio_path = ""
                    if render_wav:
                        audio_path = self._render_wav_simple(midi_path, title, bpm) or ""
                    meta = TrackMeta(title=title, mood=mood, bpm=bpm, key=key, bars=bars, midi_path=midi_path, audio_path=audio_path)
                    self._load_library()
                    self.library.append({
                        "title": meta.title,
                        "mood": meta.mood,
                        "bpm": meta.bpm,
                        "key": meta.key,
                        "bars": meta.bars,
                        "midi_path": meta.midi_path,
                        "audio_path": meta.audio_path,
                        "created_utc": self._utc_iso(),
                    })
                    self._save_library()
                    return meta

                def record_start(self, name="jam"):
                    if sd is None or sf is None:
                        raise RuntimeError("Recording requires sounddevice + soundfile. Install: pip install sounddevice soundfile")
                    out_path = self._path(name, ".wav")
                    self._record_frames = []

                    def _cb(indata, frames, time_info, status):
                        try:
                            self._record_frames.append(indata.copy())
                        except Exception:
                            pass

                    self._record_stream = sd.InputStream(samplerate=self._record_sr, channels=self._record_channels, callback=_cb)
                    self._record_stream.start()
                    self._record_out_path = out_path
                    self._log(f"[Music] Recording… {out_path}")
                    return out_path

                def record_stop(self):
                    if self._record_stream is None:
                        return "No active recording."
                    try:
                        self._record_stream.stop()
                        self._record_stream.close()
                    except Exception:
                        pass
                    self._record_stream = None

                    if not self._record_frames:
                        return "Recording stopped (no audio frames captured)."

                    data = np.concatenate(self._record_frames, axis=0) if (np is not None) else None
                    if data is None:
                        return "Recording stopped, but numpy missing to merge frames."

                    try:
                        sf.write(self._record_out_path, data, self._record_sr)
                    except Exception as e:
                        return f"Recording stopped, but failed to write WAV: {e}"

                    self._load_library()
                    self.library.append({
                        "title": os.path.basename(self._record_out_path),
                        "mood": "recording",
                        "bpm": None,
                        "key": None,
                        "bars": None,
                        "midi_path": "",
                        "audio_path": self._record_out_path,
                        "created_utc": self._utc_iso(),
                    })
                    self._save_library()
                    return f"✅ Saved recording: {self._record_out_path}"

                def crossfade(self, file_a: str, file_b: str, seconds: float = 6.0, out_name: str = "crossfade"):
                    if AudioSegment is None:
                        raise RuntimeError("Crossfade requires pydub. Install: pip install pydub")
                    a_path = file_a if os.path.isabs(file_a) else os.path.join(self.base_dir, file_a)
                    b_path = file_b if os.path.isabs(file_b) else os.path.join(self.base_dir, file_b)
                    if not os.path.exists(a_path):
                        raise FileNotFoundError(a_path)
                    if not os.path.exists(b_path):
                        raise FileNotFoundError(b_path)
                    a = AudioSegment.from_file(a_path)
                    b = AudioSegment.from_file(b_path)
                    ms = int(max(0.0, float(seconds)) * 1000)
                    out = a.append(b, crossfade=ms)
                    out_path = self._path(out_name, ".wav")
                    out.export(out_path, format="wav")
                    return out_path

                def pulse_start(self):
                    if self._pulse_thread and self._pulse_thread.is_alive():
                        return "Pulse already running."
                    self._pulse_stop_evt.clear()

                    def _run():
                        while not self._pulse_stop_evt.is_set():
                            try:
                                if self.app and hasattr(self.app, "_porch_haptics") and self.app._porch_haptics:
                                    self.app._porch_haptics.emit("music_pulse", meta={"ts": time.time()})
                            except Exception:
                                pass
                            time.sleep(0.5)

                    self._pulse_thread = threading.Thread(target=_run, daemon=True)
                    self._pulse_thread.start()
                    return "✅ Music pulse ON"

                def pulse_stop(self):
                    self._pulse_stop_evt.set()
                    return "✅ Music pulse OFF"

                # -------------------- UI --------------------
                def open_window(self):
                    import customtkinter as ctk  # local import
                    if getattr(self, "_win", None) and self._win.winfo_exists():
                        try:
                            self._win.focus()
                            return
                        except Exception:
                            pass

                    self._win = ctk.CTkToplevel()
                    self._win.title("Studio Sanctuary")
                    self._win.geometry("900x600")

                    header = ctk.CTkLabel(self._win, text="🎛 Studio Sanctuary", font=ctk.CTkFont(size=18, weight="bold"))
                    header.pack(anchor="w", padx=12, pady=(12, 6))

                    tabs = ctk.CTkTabview(self._win)
                    tabs.pack(fill="both", expand=True, padx=12, pady=12)

                    t_comp = tabs.add("Compose")
                    t_rec = tabs.add("Record")
                    t_dj = tabs.add("DJ")
                    t_lib = tabs.add("Library")

                    # Compose
                    row = ctk.CTkFrame(t_comp, fg_color="transparent")
                    row.pack(fill="x", pady=8)
                    mood_e = ctk.CTkEntry(row, placeholder_text="mood (e.g. boss_tension / hope)")
                    mood_e.pack(side="left", fill="x", expand=True, padx=(0, 8))
                    bpm_e = ctk.CTkEntry(row, width=80, placeholder_text="bpm")
                    bpm_e.insert(0, "96")
                    bpm_e.pack(side="left", padx=(0, 8))
                    key_e = ctk.CTkEntry(row, width=60, placeholder_text="key")
                    key_e.insert(0, "C")
                    key_e.pack(side="left", padx=(0, 8))
                    bars_e = ctk.CTkEntry(row, width=70, placeholder_text="bars")
                    bars_e.insert(0, "16")
                    bars_e.pack(side="left", padx=(0, 8))
                    render_var = ctk.BooleanVar(value=False)
                    render_cb = ctk.CTkCheckBox(row, text="Render WAV", variable=render_var)
                    render_cb.pack(side="left")

                    out_box = ctk.CTkTextbox(t_comp, height=260)
                    out_box.pack(fill="both", expand=True, pady=8)

                    def _do_comp():
                        mood = (mood_e.get() or "neutral").strip()
                        try:
                            bpm = int(bpm_e.get() or 96)
                        except Exception:
                            bpm = 96
                        key = (key_e.get() or "C").strip()
                        try:
                            bars = int(bars_e.get() or 16)
                        except Exception:
                            bars = 16
                        meta = self.compose(title=f"{mood.replace(' ','_')}_theme", mood=mood, bpm=bpm, key=key, bars=bars, render_wav=bool(render_var.get()))
                        out_box.delete("1.0", "end")
                        out_box.insert("end", f"✅ Composed\nTitle: {meta.title}\nMIDI: {meta.midi_path}\nWAV: {meta.audio_path or '(not rendered)'}\n")

                    ctk.CTkButton(t_comp, text="Compose", command=_do_comp).pack(anchor="w", pady=(0, 8))

                    # Record
                    rec_box = ctk.CTkTextbox(t_rec, height=260)
                    rec_box.pack(fill="both", expand=True, pady=8)
                    rec_row = ctk.CTkFrame(t_rec, fg_color="transparent")
                    rec_row.pack(fill="x", pady=8)
                    rec_name = ctk.CTkEntry(rec_row, placeholder_text="recording name (e.g. jam1)")
                    rec_name.pack(side="left", fill="x", expand=True, padx=(0, 8))

                    def _rec_start():
                        try:
                            p = self.record_start(name=rec_name.get() or "jam")
                            rec_box.insert("end", f"▶ Recording started: {p}\n")
                        except Exception as e:
                            rec_box.insert("end", f"⚠ Record start failed: {e}\n")

                    def _rec_stop():
                        try:
                            msg = self.record_stop()
                            rec_box.insert("end", f"{msg}\n")
                        except Exception as e:
                            rec_box.insert("end", f"⚠ Record stop failed: {e}\n")

                    ctk.CTkButton(rec_row, text="Start", command=_rec_start).pack(side="left", padx=(0, 8))
                    ctk.CTkButton(rec_row, text="Stop", command=_rec_stop).pack(side="left")

                    # DJ
                    dj_row = ctk.CTkFrame(t_dj, fg_color="transparent")
                    dj_row.pack(fill="x", pady=8)
                    a_e = ctk.CTkEntry(dj_row, placeholder_text="file A (in well/audio)")
                    a_e.pack(side="left", fill="x", expand=True, padx=(0, 8))
                    b_e = ctk.CTkEntry(dj_row, placeholder_text="file B (in well/audio)")
                    b_e.pack(side="left", fill="x", expand=True, padx=(0, 8))
                    sec_e = ctk.CTkEntry(dj_row, width=90, placeholder_text="seconds")
                    sec_e.insert(0, "6")
                    sec_e.pack(side="left", padx=(0, 8))
                    dj_box = ctk.CTkTextbox(t_dj, height=260)
                    dj_box.pack(fill="both", expand=True, pady=8)

                    def _do_xf():
                        try:
                            sec = float(sec_e.get() or 6)
                        except Exception:
                            sec = 6.0
                        try:
                            out = self.crossfade(a_e.get().strip(), b_e.get().strip(), seconds=sec, out_name="dj_crossfade")
                            dj_box.insert("end", f"✅ Crossfaded -> {out}\n")
                        except Exception as e:
                            dj_box.insert("end", f"⚠ Crossfade failed: {e}\n")

                    ctk.CTkButton(t_dj, text="Crossfade", command=_do_xf).pack(anchor="w", pady=(0, 8))

                    # Library
                    lib_box = ctk.CTkTextbox(t_lib, height=380)
                    lib_box.pack(fill="both", expand=True, pady=8)

                    def _refresh_lib():
                        self._load_library()
                        lib_box.delete("1.0", "end")
                        if not self.library:
                            lib_box.insert("end", "(library empty)\n")
                            return
                        for it in self.library[-100:]:
                            lib_box.insert("end", f"- {it.get('created_utc','')} | {it.get('title','')} | {it.get('mood','')}\n")
                            if it.get("midi_path"):
                                lib_box.insert("end", f"  MIDI: {it.get('midi_path')}\n")
                            if it.get("audio_path"):
                                lib_box.insert("end", f"  WAV: {it.get('audio_path')}\n")

                    ctk.CTkButton(t_lib, text="Refresh", command=_refresh_lib).pack(anchor="w", pady=(0, 8))
                    _refresh_lib()

        except Exception as _e:
            # If anything goes wrong, keep Porch alive and log it.
            def PorchMusicStudio(app=None, base_dir="well/audio"):
                raise _e

except Exception as e:
    _fatal_dep(f"Missing dependency: customtkinter\n\n{e}\n\n{_dep_install_hint()}")

# NOTE: We do not require the Python 'ollama' package.
# We talk to the local Ollama server over HTTP (default http://127.0.0.1:11434).

# Optional (never hard-fail)
try:
    import requests  # type: ignore
except Exception:
    requests = None

# ---------------------------
# Ollama HTTP client (no python 'ollama' package required)
# ---------------------------
OLLAMA_URL = os.getenv("OLLAMA_URL", "http://127.0.0.1:11434").rstrip("/")

def _http_post_json(url: str, payload: Dict[str, Any], timeout: int = 60) -> Dict[str, Any]:
    """POST JSON using requests if available, else urllib."""
    data = json.dumps(payload).encode("utf-8")
    headers = {"Content-Type": "application/json"}
    if requests is not None:
        r = requests.post(url, json=payload, timeout=timeout)
        r.raise_for_status()
        return r.json()
    # fallback: urllib
    import urllib.request
    req = urllib.request.Request(url, data=data, headers=headers, method="POST")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="ignore")
    return json.loads(raw) if raw else {}

def _http_post_json_headers(url: str, payload: Dict[str, Any], headers: Optional[Dict[str, str]] = None, timeout: int = 60) -> Dict[str, Any]:
    """POST JSON with extra headers using requests if available, else urllib."""
    headers_out = {"Content-Type": "application/json"}
    if isinstance(headers, dict):
        for k, v in headers.items():
            if v is not None:
                headers_out[str(k)] = str(v)
    if requests is not None:
        r = requests.post(url, headers=headers_out, json=payload, timeout=timeout)
        r.raise_for_status()
        return r.json()
    # fallback: urllib
    import urllib.request
    data = json.dumps(payload).encode("utf-8")
    req = urllib.request.Request(url, data=data, headers=headers_out, method="POST")
    with urllib.request.urlopen(req, timeout=timeout) as resp:
        raw = resp.read().decode("utf-8", errors="ignore")
    return json.loads(raw) if raw else {}


def ollama_chat(messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
    """Call Ollama /api/chat (non-streaming)."""
    url = f"{OLLAMA_URL}/api/chat"
    payload: Dict[str, Any] = {"model": model, "messages": messages, "stream": False}
    if isinstance(options, dict) and options:
        payload["options"] = options
    return _http_post_json(url, payload, timeout=120)

def ollama_embeddings(prompt: str, model: str) -> Dict[str, Any]:
    """Call Ollama /api/embeddings."""
    url = f"{OLLAMA_URL}/api/embeddings"
    return _http_post_json(url, {"model": model, "prompt": prompt}, timeout=120)

def ollama_ping() -> bool:
    """Return True if the Ollama server is reachable."""
    try:
        # /api/tags is small and exists on standard Ollama installs
        if requests is not None:
            r = requests.get(f"{OLLAMA_URL}/api/tags", timeout=3)
            return r.status_code == 200
        import urllib.request
        with urllib.request.urlopen(f"{OLLAMA_URL}/api/tags", timeout=3) as resp:
            return resp.status == 200
    except Exception:
        return False

