def _gbcbs_canonical(obj: Any) -> bytes:
    """Stable JSON encoding for hashing/signing."""
    return json.dumps(obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")


def _sha256_hex(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def _now_iso() -> str:
    return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat() + "Z"


class GBCBS:
    """
    Local-first BBS-like protocol:
      - Bytes: signed posts
      - Blocks: signed bundles of Byte ids with hash-linking
      - Ledger: sqlite DB for blocks/bytes + a small inbox/outbox for shared-folder sync

    Security (Phase 1):
      - Ed25519 signatures (PyNaCl) if available
      - Tamper-evident chain via prev_hash links
      - Local sovereignty: each node decides what to accept via the 3 Pillars
    """

    def __init__(self, base_dir: str):
        self.base_dir = base_dir
        self.settings_path = os.path.join(self.base_dir, "settings.json")
        self.keys_path = os.path.join(self.base_dir, "node_keys.json")
        self.db_path = os.path.join(self.base_dir, "ledger.db")
        self.cache_path = os.path.join(self.base_dir, "seen_packets.json")

        self.outbox_dir = os.path.join(self.base_dir, "outbox")
        self.local_inbox_dir = os.path.join(self.base_dir, "inbox")
        self.quarantine_dir = os.path.join(self.base_dir, "quarantine")

        self._log = None  # type: ignore

        os.makedirs(self.base_dir, exist_ok=True)
        os.makedirs(self.outbox_dir, exist_ok=True)
        os.makedirs(self.local_inbox_dir, exist_ok=True)
        os.makedirs(self.quarantine_dir, exist_ok=True)

        self.settings = self._load_settings()
        self._seen_packets = self._load_seen_packets()

        self.signing_key = None
        self.verify_key = None
        self._ensure_keys()

        self._db = sqlite3.connect(self.db_path)
        self._db.row_factory = sqlite3.Row
        self._init_db()

    # ---------- Logging ----------
    def set_logger(self, fn):
        self._log = fn

    def log(self, msg: str):
        if callable(self._log):
            try:
                self._log(msg, dim=True, mono=True)
                return
            except Exception:
                pass
        # fallback
        try:
            print("[GBCBS]", msg)
        except Exception:
            pass

    # ---------- Settings ----------
    def _load_settings(self) -> Dict[str, Any]:
        default = {
            "node_name": os.getenv("PORCH_GBCBS_NODE_NAME", "InfiniteHomeNode"),
            "shared_folder": os.getenv("PORCH_GBCBS_SHARED_FOLDER", ""),
            "trust_on_first_use": True,
            "trusted_pubkeys": [],
            "pillar_noncommercial": True,
            "pillar_nonviolence": True,
            "pillar_sovereignty": True,
            "quarantine_on_violence": True,
            "reject_on_commercial": True,
            # LLM routing (optional cloud + local)
            "chat_backend": os.getenv("PORCH_CHAT_BACKEND", "ollama"),
            "brother_backends": {},
            "brother_models": {},
            "openai_base_url": os.getenv("PORCH_OPENAI_CLOUD_BASE_URL", "https://api.openai.com"),
            "openai_model": os.getenv("PORCH_OPENAI_MODEL", "gpt-5"),
            "anthropic_base_url": os.getenv("PORCH_ANTHROPIC_BASE_URL", "https://api.anthropic.com"),
            "anthropic_model": os.getenv("PORCH_ANTHROPIC_MODEL", "claude-3-5-sonnet-20241022"),
            "xai_base_url": os.getenv("PORCH_XAI_BASE_URL", "https://api.x.ai"),
            "xai_model": os.getenv("PORCH_XAI_MODEL", "grok-beta"),
            "gemini_base_url": os.getenv("PORCH_GEMINI_BASE_URL", "https://generativelanguage.googleapis.com"),
            "gemini_model": os.getenv("PORCH_GEMINI_MODEL", "gemini-2.5-flash"),
            # Local OpenAI-compatible server (vLLM/LiteLLM/LM Studio)
            "openai_compat_base_url": os.getenv("PORCH_OPENAI_BASE_URL", ""),
            "openai_compat_model": os.getenv("PORCH_OPENAI_COMPAT_MODEL", ""),

        }
        try:
            if os.path.exists(self.settings_path):
                with open(self.settings_path, "r", encoding="utf-8") as f:
                    loaded = json.load(f)
                if isinstance(loaded, dict):
                    default.update(loaded)
        except Exception:
            pass
        # persist any new defaults
        try:
            os.makedirs(self.base_dir, exist_ok=True)
            with open(self.settings_path, "w", encoding="utf-8") as f:
                json.dump(default, f, indent=2)
        except Exception:
            pass
        return default

    def save_settings(self) -> None:
        try:
            with open(self.settings_path, "w", encoding="utf-8") as f:
                json.dump(self.settings, f, indent=2)
        except Exception:
            pass

    def _load_seen_packets(self) -> Dict[str, Any]:
        try:
            if os.path.exists(self.cache_path):
                with open(self.cache_path, "r", encoding="utf-8") as f:
                    d = json.load(f)
                if isinstance(d, dict):
                    return d
        except Exception:
            pass
        return {"files": {}}

    def _save_seen_packets(self) -> None:
        try:
            with open(self.cache_path, "w", encoding="utf-8") as f:
                json.dump(self._seen_packets, f, indent=2)
        except Exception:
            pass

    # ---------- Keys / Signatures ----------
    def _ensure_keys(self) -> None:
        if SigningKey is None or Base64Encoder is None:
            # No crypto available, still allow hash-chain (prototype mode)
            self.signing_key = None
            self.verify_key = None
            return

        try:
            if os.path.exists(self.keys_path):
                with open(self.keys_path, "r", encoding="utf-8") as f:
                    k = json.load(f)
                sk_b64 = k.get("signing_key_b64", "")
                if sk_b64:
                    self.signing_key = SigningKey(sk_b64.encode("utf-8"), encoder=Base64Encoder)
                    self.verify_key = self.signing_key.verify_key
                    return
        except Exception:
            pass

        # generate new
        try:
            self.signing_key = SigningKey.generate()
            self.verify_key = self.signing_key.verify_key
            with open(self.keys_path, "w", encoding="utf-8") as f:
                json.dump(
                    {
                        "signing_key_b64": self.signing_key.encode(encoder=Base64Encoder).decode("utf-8"),
                        "verify_key_b64": self.verify_key.encode(encoder=Base64Encoder).decode("utf-8"),
                    },
                    f,
                    indent=2,
                )
        except Exception:
            self.signing_key = None
            self.verify_key = None

    def pubkey_b64(self) -> str:
        try:
            if self.verify_key is not None and Base64Encoder is not None:
                return self.verify_key.encode(encoder=Base64Encoder).decode("utf-8")
        except Exception:
            pass
        return ""

    def _sign(self, payload: bytes) -> str:
        if self.signing_key is None or Base64Encoder is None:
            return ""
        try:
            sig = self.signing_key.sign(payload).signature
            return base64.b64encode(sig).decode("utf-8")
        except Exception:
            return ""

    def _verify(self, payload: bytes, sig_b64: str, pubkey_b64: str) -> bool:
        if VerifyKey is None or Base64Encoder is None:
            return True  # prototype mode
        try:
            sig = base64.b64decode(sig_b64.encode("utf-8"))
            vk = VerifyKey(pubkey_b64.encode("utf-8"), encoder=Base64Encoder)
            vk.verify(payload, sig)
            return True
        except Exception:
            return False

    # ---------- DB ----------
    def _init_db(self) -> None:
        cur = self._db.cursor()
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS bytes (
                byte_id TEXT PRIMARY KEY,
                board TEXT,
                title TEXT,
                body TEXT,
                tags TEXT,
                author_pubkey TEXT,
                created_at TEXT,
                reply_to TEXT,
                status TEXT
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS blocks (
                block_hash TEXT PRIMARY KEY,
                prev_hash TEXT,
                timestamp TEXT,
                creator_pubkey TEXT,
                signature TEXT,
                byte_ids TEXT
            )
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS packets (
                packet_file TEXT PRIMARY KEY,
                ingested_at TEXT
            )
            """
        )
        self._db.commit()

    # ---------- Pillar Filters ----------
    @staticmethod
    def _strip_tracking(text: str) -> str:
        # remove common tracking query params in URLs (utm_*, fbclid, gclid)
        def _clean_url(m):
            url = m.group(0)
            # split query
            if "?" not in url:
                return url
            base, q = url.split("?", 1)
            parts = q.split("&")
            kept = []
            for p in parts:
                key = p.split("=", 1)[0].lower().strip()
                if key.startswith("utm_") or key in ("fbclid", "gclid", "msclkid"):
                    continue
                kept.append(p)
            return base + ("?" + "&".join(kept) if kept else "")

        try:
            text = re.sub(r"https?://[^\s)>\]]+", _clean_url, text)
        except Exception:
            pass
        return text

    @staticmethod
    def _looks_commercial(text: str) -> bool:
        t = (text or "").lower()
        commercial_hits = [
            "buy now", "limited time", "discount", "promo code", "affiliate", "sponsored", "subscribe",
            "sale ends", "tracking pixel", "doubleclick", "adservice", "marketing", "utm_", "fbclid=",
        ]
        return any(h in t for h in commercial_hits)

    @staticmethod
    def _looks_violent(text: str) -> bool:
        t = (text or "").lower()
        # keep this conservative (quarantine only when clearly harmful)
        violent_hits = [
            "kill", "murder", "shoot", "stab", "bomb", "rape", "torture", "suicide",
            "genocide", "lynch", "massacre", "behead", "execute",
        ]
        return any(re.search(r"\b" + re.escape(h) + r"\b", t) for h in violent_hits)

    def _apply_pillars(self, title: str, body: str) -> Dict[str, Any]:
        title2 = title or ""
        body2 = body or ""
        reasons = []

        # Pillar 1: Non-commerciality
        if self.settings.get("pillar_noncommercial", True):
            body2 = self._strip_tracking(body2)
            title2 = self._strip_tracking(title2)
            if self._looks_commercial(title2 + "\n" + body2):
                reasons.append("commercial")
                if self.settings.get("reject_on_commercial", True):
                    return {"status": "rejected", "title": title2, "body": body2, "reasons": reasons}

        # Pillar 2: Non-violence
        if self.settings.get("pillar_nonviolence", True):
            if self._looks_violent(title2 + "\n" + body2):
                reasons.append("violent")
                if self.settings.get("quarantine_on_violence", True):
                    return {"status": "quarantined", "title": title2, "body": body2, "reasons": reasons}

        return {"status": "allowed", "title": title2, "body": body2, "reasons": reasons}

    # ---------- Byte / Block operations ----------
    def create_byte(self, board: str, title: str, body: str, tags: Iterable[str] = (), reply_to: str = "") -> Dict[str, Any]:
        board = (board or "general").strip()
        tags_list = [t.strip() for t in tags if str(t).strip()]
        filt = self._apply_pillars(title, body)
        status = filt["status"]
        title2, body2 = filt["title"], filt["body"]

        base = {
            "board": board,
            "title": title2,
            "body": body2,
            "tags": tags_list,
            "author_pubkey": self.pubkey_b64(),
            "created_at": _now_iso(),
            "reply_to": reply_to or "",
        }
        byte_id = _sha256_hex(_gbcbs_canonical(base))
        byte = dict(base)
        byte["byte_id"] = byte_id
        byte["signature"] = self._sign(_gbcbs_canonical({k: byte[k] for k in byte if k != "signature"}))

        # Store
        try:
            cur = self._db.cursor()
            cur.execute(
                "INSERT OR REPLACE INTO bytes(byte_id, board, title, body, tags, author_pubkey, created_at, reply_to, status) VALUES(?,?,?,?,?,?,?,?,?)",
                (
                    byte_id,
                    board,
                    title2,
                    body2,
                    json.dumps(tags_list, ensure_ascii=False),
                    byte.get("author_pubkey", ""),
                    byte.get("created_at", ""),
                    reply_to or "",
                    status,
                ),
            )
            self._db.commit()
        except Exception:
            pass

        return {"byte": byte, "status": status, "reasons": filt.get("reasons", [])}

    def list_boards(self) -> Iterable[str]:
        try:
            cur = self._db.cursor()
            cur.execute("SELECT DISTINCT board FROM bytes ORDER BY board")
            return [r[0] for r in cur.fetchall() if r and r[0]]
        except Exception:
            return []

    def latest_posts(self, board: str, limit: int = 20, include_quarantine: bool = False) -> Iterable[Dict[str, Any]]:
        try:
            cur = self._db.cursor()
            if include_quarantine:
                cur.execute(
                    "SELECT byte_id, title, body, author_pubkey, created_at, status FROM bytes WHERE board=? ORDER BY created_at DESC LIMIT ?",
                    (board, limit),
                )
            else:
                cur.execute(
                    "SELECT byte_id, title, body, author_pubkey, created_at, status FROM bytes WHERE board=? AND status='allowed' ORDER BY created_at DESC LIMIT ?",
                    (board, limit),
                )
            rows = cur.fetchall()
            out = []
            for r in rows:
                out.append(dict(r))
            return out
        except Exception:
            return []

    def _get_latest_block_hash(self) -> str:
        try:
            cur = self._db.cursor()
            cur.execute("SELECT block_hash FROM blocks ORDER BY timestamp DESC LIMIT 1")
            row = cur.fetchone()
            return row[0] if row else ""
        except Exception:
            return ""

    def create_block_for_bytes(self, byte_ids: Iterable[str]) -> Dict[str, Any]:
        ids = [i for i in byte_ids if i]
        prev = self._get_latest_block_hash()
        block_base = {
            "prev_hash": prev,
            "timestamp": _now_iso(),
            "creator_pubkey": self.pubkey_b64(),
            "byte_ids": ids,
        }
        block_hash = _sha256_hex(_gbcbs_canonical(block_base))
        sig = self._sign(_gbcbs_canonical(block_base))
        block = dict(block_base)
        block["block_hash"] = block_hash
        block["signature"] = sig

        try:
            cur = self._db.cursor()
            cur.execute(
                "INSERT OR REPLACE INTO blocks(block_hash, prev_hash, timestamp, creator_pubkey, signature, byte_ids) VALUES(?,?,?,?,?,?)",
                (block_hash, prev, block_base["timestamp"], block_base["creator_pubkey"], sig, json.dumps(ids)),
            )
            self._db.commit()
        except Exception:
            pass
        return {"block": block}

    def export_block_packet(self, block_hash: str) -> Dict[str, Any]:
        cur = self._db.cursor()
        cur.execute("SELECT block_hash, prev_hash, timestamp, creator_pubkey, signature, byte_ids FROM blocks WHERE block_hash=?", (block_hash,))
        row = cur.fetchone()
        if not row:
            raise ValueError("Block not found")
        block = dict(row)
        byte_ids = json.loads(block.get("byte_ids") or "[]")
        bytes_out = []
        for bid in byte_ids:
            cur.execute("SELECT * FROM bytes WHERE byte_id=?", (bid,))
            br = cur.fetchone()
            if br:
                bdict = dict(br)
                # reconstruct signature field unknown in db; keep minimal
                bytes_out.append(
                    {
                        "byte_id": bdict.get("byte_id"),
                        "board": bdict.get("board"),
                        "title": bdict.get("title"),
                        "body": bdict.get("body"),
                        "tags": json.loads(bdict.get("tags") or "[]"),
                        "author_pubkey": bdict.get("author_pubkey"),
                        "created_at": bdict.get("created_at"),
                        "reply_to": bdict.get("reply_to") or "",
                        "status": bdict.get("status") or "allowed",
                        # signature not stored in db currently; phase 1 accepts local posts anyway
                        "signature": "",
                    }
                )
        return {"protocol": "GBCBS/0.1", "block": block, "bytes": bytes_out}

    # ---------- Trust ----------
    def _is_trusted(self, pubkey: str) -> bool:
        if not pubkey:
            return True
        trusted = self.settings.get("trusted_pubkeys", []) or []
        return pubkey in trusted

    def _trust_pubkey(self, pubkey: str) -> None:
        if not pubkey:
            return
        trusted = self.settings.get("trusted_pubkeys", []) or []
        if pubkey not in trusted:
            trusted.append(pubkey)
            self.settings["trusted_pubkeys"] = trusted
            self.save_settings()

    # ---------- Sync ----------
    def shared_packets_dir(self) -> str:
        base = (self.settings.get("shared_folder") or "").strip()
        if not base:
            return ""
        return os.path.join(base, "gbcbs_packets")

    def sync_export_latest(self) -> str:
        """Export the latest block packet to the shared folder."""
        shared = self.shared_packets_dir()
        if not shared:
            return "Shared folder not set."
        try:
            os.makedirs(shared, exist_ok=True)
        except Exception:
            return "Could not create shared packets folder."

        # export the most recent block
        bh = self._get_latest_block_hash()
        if not bh:
            return "No blocks yet. Create a post first."
        pkt = self.export_block_packet(bh)

        fname = f"block_{bh[:12]}_{int(time.time())}_{(self.pubkey_b64()[:8] or 'node')}.json"
        fpath = os.path.join(shared, fname)
        try:
            with open(fpath, "w", encoding="utf-8") as f:
                json.dump(pkt, f, indent=2, ensure_ascii=False)
            return f"Exported block packet → {fpath}"
        except Exception:
            return "Failed to write packet."

    def sync_ingest_shared(self) -> Dict[str, Any]:
        """Ingest any unseen packets from the shared folder."""
        shared = self.shared_packets_dir()
        if not shared or not os.path.isdir(shared):
            return {"ingested": 0, "errors": 0, "message": "Shared packets folder not found (set it first)."}
        ingested = 0
        errors = 0

        for name in sorted(os.listdir(shared)):
            if not name.lower().endswith(".json"):
                continue
            if name in (self._seen_packets.get("files") or {}):
                continue

            fpath = os.path.join(shared, name)
            try:
                with open(fpath, "r", encoding="utf-8") as f:
                    pkt = json.load(f)
                # record seen early to avoid loops if something crashes
                self._seen_packets.setdefault("files", {})[name] = {"seen_at": _now_iso(), "path": fpath}
                self._save_seen_packets()

                if not isinstance(pkt, dict) or "block" not in pkt or "bytes" not in pkt:
                    errors += 1
                    continue
                block = pkt.get("block") or {}
                creator = block.get("creator_pubkey", "") or ""
                if creator and not self._is_trusted(creator):
                    if self.settings.get("trust_on_first_use", True):
                        self._trust_pubkey(creator)
                    else:
                        # ignore untrusted
                        continue

                # Ingest bytes (apply pillars locally)
                bytes_list = pkt.get("bytes") or []
                accepted_ids = []
                for b in bytes_list:
                    try:
                        board = (b.get("board") or "general").strip()
                        title = b.get("title") or ""
                        body = b.get("body") or ""
                        tags = b.get("tags") or []
                        author = b.get("author_pubkey") or creator or ""
                        created_at = b.get("created_at") or _now_iso()
                        reply_to = b.get("reply_to") or ""

                        filt = self._apply_pillars(title, body)
                        status = filt["status"]
                        title2, body2 = filt["title"], filt["body"]
                        # compute deterministic byte id (same scheme)
                        base = {
                            "board": board,
                            "title": title2,
                            "body": body2,
                            "tags": [str(t) for t in tags if str(t).strip()],
                            "author_pubkey": author,
                            "created_at": created_at,
                            "reply_to": reply_to,
                        }
                        byte_id = _sha256_hex(_gbcbs_canonical(base))
                        cur = self._db.cursor()
                        cur.execute(
                            "INSERT OR REPLACE INTO bytes(byte_id, board, title, body, tags, author_pubkey, created_at, reply_to, status) VALUES(?,?,?,?,?,?,?,?,?)",
                            (
                                byte_id,
                                board,
                                title2,
                                body2,
                                json.dumps(base["tags"], ensure_ascii=False),
                                author,
                                created_at,
                                reply_to,
                                status,
                            ),
                        )
                        self._db.commit()
                        if status == "allowed":
                            accepted_ids.append(byte_id)
                    except Exception:
                        errors += 1

                # Ingest block record (even if some bytes quarantined; it remains a received packet)
                try:
                    byte_ids = block.get("byte_ids")
                    if isinstance(byte_ids, str):
                        try:
                            byte_ids = json.loads(byte_ids)
                        except Exception:
                            byte_ids = []
                    byte_ids = byte_ids if isinstance(byte_ids, list) else []
                    block_hash = block.get("block_hash") or ""
                    if not block_hash:
                        # reconstruct
                        base_block = {
                            "prev_hash": block.get("prev_hash") or "",
                            "timestamp": block.get("timestamp") or "",
                            "creator_pubkey": creator,
                            "byte_ids": byte_ids,
                        }
                        block_hash = _sha256_hex(_gbcbs_canonical(base_block))
                    cur = self._db.cursor()
                    cur.execute(
                        "INSERT OR IGNORE INTO blocks(block_hash, prev_hash, timestamp, creator_pubkey, signature, byte_ids) VALUES(?,?,?,?,?,?)",
                        (
                            block_hash,
                            block.get("prev_hash") or "",
                            block.get("timestamp") or _now_iso(),
                            creator,
                            block.get("signature") or "",
                            json.dumps(byte_ids),
                        ),
                    )
                    self._db.commit()
                except Exception:
                    pass

                ingested += 1
            except Exception:
                errors += 1

        return {"ingested": ingested, "errors": errors, "message": f"Ingested {ingested} packet(s), errors: {errors}."}


