def _now_ts() -> str:
    return time.strftime("%Y-%m-%d %H:%M:%S")



def _now_iso() -> str:
    """ISO-8601 timestamp (seconds)."""
    try:
        return datetime.datetime.now().isoformat(timespec="seconds")
    except TypeError:
        # Older Python: timespec may not exist
        return datetime.datetime.now().isoformat()


class SpellCheckerLite:
    """
    Lightweight spellchecker for the input box.

    - Loads words from WORDS_FILE (one word per line).
    - Underline misspellings in the input Text widget.
    - Suggests replacements via a SymSpell-style delete index (prefix-bounded) cached to disk.
    """
    def __init__(self, words_path: str, index_path: str, max_edit: int = 2, prefix_len: int = 7):
        self.words_path = words_path
        self.index_path = index_path
        self.max_edit = int(max(1, max_edit))
        self.prefix_len = int(max(3, prefix_len))
        self.ready_words = False
        self.ready_index = False

        self.words_set: set[str] = set()
        self.words_list: list[str] = []
        self.prefix_buckets: dict[str, list[int]] = {}  # quick fallback
        self.deletes: dict[str, list[int]] = {}  # symspell-lite deletes -> word ids
        self._lock = threading.RLock()

    def ensure_words_file(self) -> None:
        # Create a tiny placeholder so the feature doesn't crash if the user hasn't dropped in words.txt yet.
        try:
            os.makedirs(os.path.dirname(self.words_path) or ".", exist_ok=True)
            if not os.path.exists(self.words_path):
                with open(self.words_path, "w", encoding="utf-8") as f:
                    f.write("the\nand\nyou\nare\nhello\nworld\nmikey\nori\nporch\nmaze\nrift\nlibrary\n")
        except Exception:
            pass

    def load_words(self) -> None:
        self.ensure_words_file()
        words_set: set[str] = set()
        words_list: list[str] = []
        prefix_buckets: dict[str, list[int]] = {}

        try:
            with open(self.words_path, "r", encoding="utf-8", errors="ignore") as f:
                for line in f:
                    w = (line or "").strip().lower()
                    if not w:
                        continue
                    # keep simple word tokens
                    if not re.fullmatch(r"[a-z][a-z']{1,}", w):
                        continue
                    if w in words_set:
                        continue
                    wid = len(words_list)
                    words_list.append(w)
                    words_set.add(w)
                    key = w[:2]
                    prefix_buckets.setdefault(key, []).append(wid)
        except Exception:
            # keep placeholder
            words_set = {"the", "and", "you", "are", "hello", "world", "mikey", "ori", "porch"}
            words_list = sorted(words_set)
            prefix_buckets = {}
            for i, w in enumerate(words_list):
                prefix_buckets.setdefault(w[:2], []).append(i)

        with self._lock:
            self.words_set = words_set
            self.words_list = words_list
            self.prefix_buckets = prefix_buckets
            self.ready_words = True

    @staticmethod
    def _levenshtein_max(a: str, b: str, max_dist: int) -> int:
        """Levenshtein distance with early cutoff. Returns max_dist+1 if above cutoff."""
        if a == b:
            return 0
        if abs(len(a) - len(b)) > max_dist:
            return max_dist + 1
        # ensure a is shorter
        if len(a) > len(b):
            a, b = b, a
        prev = list(range(len(a) + 1))
        for i, cb in enumerate(b, start=1):
            cur = [i]
            # banded DP by max_dist
            lo = max(1, i - max_dist)
            hi = min(len(a), i + max_dist)
            # fill before lo with large values
            for j in range(1, lo):
                cur.append(max_dist + 1)
            min_row = max_dist + 1
            for j in range(lo, hi + 1):
                cost = 0 if a[j - 1] == cb else 1
                v = min(
                    prev[j] + 1,           # delete
                    cur[j - 1] + 1,        # insert
                    prev[j - 1] + cost     # substitute
                )
                cur.append(v)
                if v < min_row:
                    min_row = v
            # fill after hi
            for j in range(hi + 1, len(a) + 1):
                cur.append(max_dist + 1)
            if min_row > max_dist:
                return max_dist + 1
            prev = cur
        d = prev[len(a)]
        return d

    @staticmethod
    def _edits_prefix(word: str, max_edit: int) -> set[str]:
        """Generate delete edits up to max_edit (on the word itself)."""
        results = set()
        queue = {word}
        for _ in range(max_edit):
            nxt = set()
            for w in queue:
                if len(w) <= 1:
                    continue
                for i in range(len(w)):
                    nxt.add(w[:i] + w[i+1:])
            results |= nxt
            queue = nxt
        return results

    def _build_index(self) -> None:
        # Build a SymSpell-lite delete index bounded by prefix length.
        with self._lock:
            if not self.ready_words:
                return
            words_list = self.words_list

        deletes: dict[str, list[int]] = {}
        for wid, w in enumerate(words_list):
            p = w[: self.prefix_len]
            dels = self._edits_prefix(p, self.max_edit)
            for d in dels:
                lst = deletes.get(d)
                if lst is None:
                    deletes[d] = [wid]
                else:
                    lst.append(wid)

        with self._lock:
            self.deletes = deletes
            self.ready_index = True

        # cache to disk
        try:
            with open(self.index_path, "wb") as f:
                pickle.dump(
                    {
                        "v": 1,
                        "max_edit": self.max_edit,
                        "prefix_len": self.prefix_len,
                        "words_path": os.path.basename(self.words_path),
                        "words_count": len(words_list),
                        "deletes": deletes,
                    },
                    f,
                    protocol=pickle.HIGHEST_PROTOCOL,
                )
        except Exception:
            pass

    def load_or_build_index_async(self) -> None:
        def worker():
            try:
                # load words (fast enough; index is heavier)
                if not self.ready_words:
                    self.load_words()
                # try load cache
                ok = False
                try:
                    if os.path.exists(self.index_path):
                        with open(self.index_path, "rb") as f:
                            data = pickle.load(f)
                        if (
                            isinstance(data, dict)
                            and data.get("v") == 1
                            and int(data.get("max_edit", -1)) == self.max_edit
                            and int(data.get("prefix_len", -1)) == self.prefix_len
                        ):
                            deletes = data.get("deletes")
                            if isinstance(deletes, dict):
                                with self._lock:
                                    self.deletes = deletes
                                    self.ready_index = True
                                ok = True
                except Exception:
                    ok = False
                if not ok:
                    self._build_index()
            except Exception:
                pass

        threading.Thread(target=worker, daemon=True).start()

    def is_correct(self, word: str) -> bool:
        w = (word or "").lower()
        if not w:
            return True
        with self._lock:
            if not self.ready_words:
                return True
            return w in self.words_set

    def suggest(self, word: str, max_suggestions: int = 6) -> list[str]:
        w = (word or "").lower().strip()
        if not w or len(w) < 2:
            return []
        with self._lock:
            if not self.ready_words:
                return []
            words_list = self.words_list
            ready_index = self.ready_index
            deletes = self.deletes
            buckets = self.prefix_buckets

        max_edit = self.max_edit
        cand_ids: set[int] = set()

        if ready_index and deletes:
            p = w[: self.prefix_len]
            keys = {p} | self._edits_prefix(p, max_edit)
            for k in keys:
                ids = deletes.get(k)
                if ids:
                    for wid in ids:
                        cand_ids.add(int(wid))
        else:
            # fallback: prefix bucket to keep things quick
            ids = buckets.get(w[:2], [])[:2500]
            cand_ids.update(ids)

        scored: list[tuple[int, str]] = []
        for wid in cand_ids:
            try:
                ww = words_list[wid]
            except Exception:
                continue
            d = self._levenshtein_max(w, ww, max_edit)
            if d <= max_edit:
                scored.append((d, ww))
        scored.sort(key=lambda t: (t[0], len(t[1]), t[1]))
        out = []
        for _, s in scored:
            if s not in out:
                out.append(s)
            if len(out) >= max_suggestions:
                break
        return out


def _id8() -> str:
    return hashlib.sha1(f"{time.time_ns()}".encode()).hexdigest()[:10]


def _is_blocked_memory(text: str) -> bool:
    t = (text or "").lower()
    return any(p in t for p in BLOCKLIST_PHRASES)


def _sha1_bytes(b: bytes) -> str:
    return hashlib.sha1(b).hexdigest()


def _read_bytes(path: str) -> bytes:
    with open(path, "rb") as f:
        return f.read()

def _write_bytes(path: str, data: bytes) -> None:
    try:
        os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
    except Exception:
        pass
    with open(path, "wb") as f:
        f.write(data)

def _write_text(path: str, text: str, encoding: str = "utf-8") -> None:
    _write_bytes(path, (text or "").encode(encoding, "replace"))


def _safe_read_text(path: str) -> str:
    return _read_bytes(path).decode("utf-8", errors="ignore")


def _clean_text(s: str) -> str:
    s = (s or "").replace("\r\n", "\n").replace("\r", "\n")
    s = re.sub(r"[ \t]{2,}", " ", s)
    s = re.sub(r"\n{3,}", "\n\n", s)
    return s.strip()


def _html_to_text(html: str) -> str:
    if BeautifulSoup is None:
        html = re.sub(r"<\s*br\s*/?\s*>", "\n", html, flags=re.IGNORECASE)
        html = re.sub(r"<[^>]+>", " ", html)
        return _clean_text(html)
    soup = BeautifulSoup(html, "html.parser")
    return _clean_text(soup.get_text("\n"))


def _strings_from_json(obj) -> Iterable[str]:
    if obj is None:
        return
    if isinstance(obj, str):
        s = obj.strip()
        if len(s) >= 3:
            yield s
        return
    if isinstance(obj, (int, float, bool)):
        return
    if isinstance(obj, list):
        for x in obj:
            yield from _strings_from_json(x)
        return
    if isinstance(obj, dict):
        for k in ("content", "text", "message", "messages", "prompt", "completion", "title"):
            if k in obj:
                yield from _strings_from_json(obj[k])
        for _, v in obj.items():
            yield from _strings_from_json(v)


def _pdf_to_text(path: str) -> str:
    if pypdf is None:
        return ""
    try:
        reader = pypdf.PdfReader(path)
        parts = []
        for page in reader.pages:
            t = page.extract_text() or ""
            if t.strip():
                parts.append(t)
        return _clean_text("\n".join(parts))
    except Exception:
        return ""



def _strip_html_to_text(html: str) -> str:
    try:
        if BeautifulSoup is not None:
            soup = BeautifulSoup(html, "html.parser")
            return _clean_text(soup.get_text("\n"))
    except Exception:
        pass
    # very simple fallback
    try:
        txt = re.sub(r"<script.*?>.*?</script>", " ", html, flags=re.I | re.S)
        txt = re.sub(r"<style.*?>.*?</style>", " ", txt, flags=re.I | re.S)
        txt = re.sub(r"<[^>]+>", " ", txt)
        return _clean_text(txt)
    except Exception:
        return ""


def _epub_to_text(path: str) -> str:
    """
    Best-effort EPUB -> plain text.
    Optional deps:
      - ebooklib (preferred)
      - BeautifulSoup (preferred for html->text)
    """
    if epub is None:
        return ""
    try:
        book = epub.read_epub(path)
        parts: List[str] = []
        for item in book.get_items():
            try:
                if ITEM_DOCUMENT is not None and item.get_type() != ITEM_DOCUMENT:
                    continue
            except Exception:
                pass
            try:
                content = item.get_content()
                if isinstance(content, bytes):
                    html = content.decode("utf-8", errors="ignore")
                else:
                    html = str(content)
                t = _strip_html_to_text(html)
                if t.strip():
                    parts.append(t)
            except Exception:
                continue
        return _clean_text("\n\n".join(parts))
    except Exception:
        return ""


def _run_cmd_capture_text(cmd: List[str], timeout: int = 120) -> str:
    try:
        r = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout)
        if r.stdout:
            return r.stdout
        # some tools log to stderr
        return r.stderr or ""
    except Exception:
        return ""


def _convert_book_to_text(path: str) -> str:
    """
    Optional converter pipeline for books.

    - PDF: pypdf first; then pdftotext if available.
    - EPUB: ebooklib first; then pandoc; then calibre's ebook-convert.

    Returns extracted plain text (may be empty).
    """
    ext = os.path.splitext(path)[1].lower()
    if ext == ".pdf":
        t = _pdf_to_text(path)
        if t.strip():
            return t
        # fallback: external pdftotext (poppler)
        exe = shutil.which("pdftotext")
        if exe:
            # pdftotext <in.pdf> -  (stdout)
            out = _run_cmd_capture_text([exe, path, "-"], timeout=180)
            return _clean_text(out)
        return ""
    if ext == ".epub":
        t = _epub_to_text(path)
        if t.strip():
            return t
        exe = shutil.which("pandoc")
        if exe:
            out = _run_cmd_capture_text([exe, "-t", "plain", path], timeout=180)
            if out.strip():
                return _clean_text(out)
        exe2 = shutil.which("ebook-convert")
        if exe2:
            # ebook-convert writes to file; use temp
            try:
                tmp = os.path.join(tempfile.gettempdir(), f"porch_{int(time.time())}.txt")
                _run_cmd_capture_text([exe2, path, tmp], timeout=240)
                if os.path.exists(tmp):
                    raw = _safe_read_text(tmp)
                    try:
                        os.remove(tmp)
                    except Exception:
                        pass
                    if raw.strip():
                        return _clean_text(raw)
            except Exception:
                pass
        return ""
    return ""


def _image_to_text(path: str) -> str:
    if Image is None or pytesseract is None:
        return ""
    try:
        img = Image.open(path)
        return _clean_text(pytesseract.image_to_string(img))
    except Exception:
        return ""


def _extract_text_from_file(path: str) -> str:
    ext = os.path.splitext(path)[1].lower()
    if ext in (".png", ".jpg", ".jpeg"):
        return _image_to_text(path)
    if ext == ".pdf":
        return _pdf_to_text(path)
    raw = _safe_read_text(path)
    if ext in (".html", ".htm"):
        return _html_to_text(raw)
    if ext == ".json":
        try:
            data = json.loads(raw)
            parts = []
            for s in _strings_from_json(data):
                s = s.strip()
                if len(s) >= 5:
                    parts.append(s)
            return _clean_text("\n".join(parts))
        except Exception:
            return _clean_text(raw)
    return _clean_text(raw)


def chunk_text(text: str, chunk_chars: int = 1200, overlap: int = 200) -> List[str]:
    text = _clean_text(text)
    if not text:
        return []
    if chunk_chars <= overlap:
        overlap = max(0, chunk_chars // 6)
    chunks: List[str] = []
    i = 0
    n = len(text)
    while i < n:
        j = min(n, i + chunk_chars)
        ch = text[i:j].strip()
        if ch:
            chunks.append(ch)
        if j >= n:
            break
        i = max(i + 1, j - overlap)
    return chunks


def guess_brother_for_path(path: str) -> str:
    p = path.lower()
    for bro, keys in BROTHER_MAPS.items():
        if any(k in p for k in keys):
            return bro
    return "Ori"


def _embed_one(text: str, embed_model: str) -> np.ndarray:
    r = ollama_embeddings(prompt=text, model=embed_model)
    vec = np.array(r.get("embedding") or [], dtype=np.float32)
    if vec.size == 0:
        raise RuntimeError("Ollama embeddings returned empty vector. Is the server running and the embed model installed?")
    norm = float(np.linalg.norm(vec))
    if norm > 0:
        vec = vec / norm
    return vec


@dataclass
class RetrievedChunk:
    score: float
    brother: str
    source_path: str
    chunk_index: int
    text: str


class RAGMemory:
    def __init__(
        self,
        source_dir: str = WELL_FOLDER,
        db_path: str = RAG_DB,
        embed_model: str = EMBED_MODEL,
        chunk_chars: int = 1200,
        overlap: int = 200,
    ):
        self.source_dir = source_dir
        self.db_path = db_path
        self.embed_model = embed_model
        self.chunk_chars = chunk_chars
        self.overlap = overlap
        self._ensure_db()

    def _conn(self) -> sqlite3.Connection:
        conn = sqlite3.connect(self.db_path)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("PRAGMA synchronous=NORMAL;")
        return conn

    def _ensure_db(self) -> None:
        conn = self._conn()
        try:
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS files (
                    path TEXT PRIMARY KEY,
                    sha1 TEXT NOT NULL,
                    mtime REAL NOT NULL,
                    size INTEGER NOT NULL,
                    brother TEXT NOT NULL
                );
                """
            )
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS chunks (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    path TEXT NOT NULL,
                    brother TEXT NOT NULL,
                    chunk_index INTEGER NOT NULL,
                    text TEXT NOT NULL,
                    embedding BLOB NOT NULL,
                    FOREIGN KEY(path) REFERENCES files(path)
                );
                """
            )
            conn.execute("CREATE INDEX IF NOT EXISTS idx_chunks_brother ON chunks(brother);")
            conn.execute("CREATE INDEX IF NOT EXISTS idx_chunks_path ON chunks(path);")
            conn.commit()
        finally:
            conn.close()

    def _iter_source_files(self) -> Iterable[str]:
        if not os.path.exists(self.source_dir):
            return []
        out = []
        for root, _, files in os.walk(self.source_dir):
            for fn in files:
                ext = os.path.splitext(fn)[1].lower()
                if ext in SUPPORTED_EXTS:
                    out.append(os.path.join(root, fn))
        return out

    def index_folder(self) -> Tuple[int, int]:
        """(Re)index the WELL folder into the local RAG sqlite DB.

        Batched commits for speed; logs exceptions to well/logs/app.log (if available).
        """
        files_updated = 0
        chunks_added = 0
        pending_files = 0
        pending_chunks = 0

        conn = self._conn()
        try:
            for path in self._iter_source_files():
                try:
                    b = _read_bytes(path)
                    sha1 = _sha1_bytes(b)
                    st = os.stat(path)
                    mtime = float(st.st_mtime)
                    size = int(st.st_size)
                    brother = guess_brother_for_path(path)

                    row = conn.execute("SELECT sha1, mtime, size FROM files WHERE path=?", (path,)).fetchone()
                    if row and row[0] == sha1 and float(row[1]) == mtime and int(row[2]) == size:
                        continue

                    conn.execute("DELETE FROM chunks WHERE path=?", (path,))
                    conn.execute("DELETE FROM files WHERE path=?", (path,))

                    text = _extract_text_from_file(path)
                    chunks = chunk_text(text, chunk_chars=self.chunk_chars, overlap=self.overlap)
                    if not chunks:
                        continue

                    conn.execute(
                        "INSERT INTO files(path, sha1, mtime, size, brother) VALUES(?,?,?,?,?)",
                        (path, sha1, mtime, size, brother),
                    )

                    inserted = 0
                    for idx, ch in enumerate(chunks):
                        if _is_blocked_memory(ch):
                            continue
                        vec = _embed_one(ch, self.embed_model)
                        conn.execute(
                            "INSERT INTO chunks(path, brother, chunk_index, text, embedding) VALUES(?,?,?,?,?)",
                            (path, brother, idx, ch, vec.tobytes()),
                        )
                        inserted += 1

                    files_updated += 1
                    chunks_added += inserted
                    pending_files += 1
                    pending_chunks += inserted

                    if pending_files >= 20 or pending_chunks >= 800:
                        conn.commit()
                        pending_files = 0
                        pending_chunks = 0

                except Exception:
                    try:
                        _debug_log_exception("RAGMemory.index_folder file failed", path=path)
                    except Exception:
                        pass
                    continue

            try:
                conn.commit()
            except Exception:
                pass
        finally:
            conn.close()

        return files_updated, chunks_added

    def retrieve(
self, brother: str, query: str, k: int = 8, include_ori: bool = True) -> List[RetrievedChunk]:
        query = (query or "").strip()
        if not query:
            return []
        try:
            qv = _embed_one(query, self.embed_model)
        except Exception:
            return []
        conn = self._conn()
        try:
            if include_ori and brother != "Ori":
                rows = conn.execute(
                    "SELECT brother, path, chunk_index, text, embedding FROM chunks WHERE brother IN (?, ?)",
                    (brother, "Ori"),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT brother, path, chunk_index, text, embedding FROM chunks WHERE brother = ?",
                    (brother,),
                ).fetchall()
        finally:
            conn.close()

        scored: List[RetrievedChunk] = []
        for bro, path, cidx, text, emb_blob in rows:
            try:
                v = np.frombuffer(emb_blob, dtype=np.float32)
                score = float(np.dot(qv, v))
            except Exception:
                continue
            scored.append(RetrievedChunk(score, bro, path, int(cidx), text))

        scored.sort(key=lambda x: x.score, reverse=True)
        return scored[: max(0, int(k))]


# =========================
# World Nodes (graph-style RAG)
# =========================
@dataclass
class WorldRetrievedNode:
    score: float
    node_id: str
    node_type: str
    title: str
    tags: List[str]
    summary: str
    facts: List[str]
    path: str


class WorldMemory:
    def __init__(self, db_path: str = RAG_DB, embed_model: str = EMBED_MODEL):
        self.db_path = db_path
        self.embed_model = embed_model
        self._ensure_db()

    def _conn(self) -> sqlite3.Connection:
        conn = sqlite3.connect(self.db_path)
        conn.execute("PRAGMA journal_mode=WAL;")
        conn.execute("PRAGMA synchronous=NORMAL;")
        return conn

    def _ensure_db(self) -> None:
        conn = self._conn()
        try:
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS world_files(
                    path TEXT PRIMARY KEY,
                    sha1 TEXT,
                    mtime REAL,
                    size INTEGER
                )
                """
            )
            conn.execute(
                """
                CREATE TABLE IF NOT EXISTS world_nodes(
                    node_id TEXT PRIMARY KEY,
                    path TEXT,
                    node_type TEXT,
                    title TEXT,
                    tags TEXT,
                    summary TEXT,
                    facts TEXT,
                    updated_at TEXT,
                    embedding BLOB
                )
                """
            )
            conn.execute("CREATE INDEX IF NOT EXISTS idx_world_nodes_type ON world_nodes(node_type)")
            conn.commit()
        finally:
            conn.close()

    def _iter_node_files(self) -> List[str]:
        if not os.path.isdir(WORLD_NODES_DIR):
            return []
        return [os.path.join(WORLD_NODES_DIR, fn) for fn in os.listdir(WORLD_NODES_DIR) if fn.lower().endswith(".json")]

    def _hash_file(self, path: str) -> Tuple[str, float, int]:
        st = os.stat(path)
        mtime = float(st.st_mtime)
        size = int(st.st_size)
        h = hashlib.sha1()
        with open(path, "rb") as f:
            for chunk in iter(lambda: f.read(65536), b""):
                h.update(chunk)
        return h.hexdigest(), mtime, size

    def _safe_load_json(self, path: str) -> Dict[str, Any]:
        b = _read_bytes(path)
        if len(b) > WORLD_MAX_NODE_BYTES:
            raise ValueError(f"Node file too large: {path}")
        try:
            return json.loads(b.decode("utf-8", errors="ignore"))
        except Exception as e:
            raise ValueError(f"Invalid JSON in {path}: {e}")

    def _normalize_node(self, node: Dict[str, Any]) -> Dict[str, Any]:
        nid = str(node.get("id") or node.get("node_id") or "").strip()
        if not nid:
            raise ValueError("Node must have an 'id'.")
        ntype = str(node.get("type") or node.get("node_type") or "note").strip() or "note"
        title = str(node.get("title") or nid).strip() or nid
        tags = node.get("tags") or []
        if isinstance(tags, str):
            tags = [t.strip() for t in tags.split(",") if t.strip()]
        tags = [str(t).strip() for t in tags if str(t).strip()]
        summary = str(node.get("summary") or "").strip()
        facts = node.get("facts") or []
        if isinstance(facts, str):
            facts = [ln.strip("- ").strip() for ln in facts.splitlines() if ln.strip()]
        facts = [str(f).strip() for f in facts if str(f).strip()]
        updated_at = str(node.get("updated_at") or _now_ts()).strip()
        return {"id": nid, "type": ntype, "title": title, "tags": tags, "summary": summary, "facts": facts, "updated_at": updated_at}

    def _node_text_for_embedding(self, node: Dict[str, Any]) -> str:
        lines = [
            f"ID: {node.get('id','')}",
            f"TYPE: {node.get('type','')}",
            f"TITLE: {node.get('title','')}",
            f"TAGS: {', '.join(node.get('tags') or [])}",
            f"SUMMARY: {node.get('summary','')}",
        ]
        facts = node.get("facts") or []
        if facts:
            lines.append("FACTS:")
            for f in facts[:50]:
                lines.append(f"- {f}")
        return "\n".join(lines).strip()

    def upsert_node(self, node: Dict[str, Any]) -> str:
        node = self._normalize_node(node)
        nid = node["id"]
        path = os.path.join(WORLD_NODES_DIR, f"{nid}.json")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(node, f, indent=2, ensure_ascii=False)
        return path

    def delete_node(self, node_id: str) -> bool:
        node_id = str(node_id or "").strip()
        if not node_id:
            return False
        path = os.path.join(WORLD_NODES_DIR, f"{node_id}.json")
        if os.path.exists(path):
            os.remove(path)
            return True
        return False

    def index_nodes(self) -> Tuple[int, int]:
        conn = self._conn()
        try:
            files_updated = 0
            nodes_indexed = 0
            for path in self._iter_node_files():
                try:
                    sha1, mtime, size = self._hash_file(path)
                    row = conn.execute("SELECT sha1 FROM world_files WHERE path=?", (path,)).fetchone()
                    if row and row[0] == sha1:
                        continue

                    node = self._safe_load_json(path)
                    node = self._normalize_node(node)
                    text_for_embed = self._node_text_for_embedding(node)
                    vec = _embed_one(text_for_embed, self.embed_model)

                    conn.execute("REPLACE INTO world_files(path, sha1, mtime, size) VALUES (?,?,?,?)", (path, sha1, mtime, size))
                    conn.execute(
                        "REPLACE INTO world_nodes(node_id, path, node_type, title, tags, summary, facts, updated_at, embedding) VALUES (?,?,?,?,?,?,?,?,?)",
                        (
                            node["id"],
                            path,
                            node["type"],
                            node["title"],
                            json.dumps(node["tags"], ensure_ascii=False),
                            node["summary"],
                            json.dumps(node["facts"], ensure_ascii=False),
                            node["updated_at"],
                            vec.tobytes(),
                        ),
                    )
                    conn.commit()
                    files_updated += 1
                    nodes_indexed += 1
                except Exception:
                    continue

            # prune deleted
            existing = set(self._iter_node_files())
            rows = conn.execute("SELECT path, node_id FROM world_nodes").fetchall()
            for p, nid in rows:
                if p not in existing:
                    conn.execute("DELETE FROM world_nodes WHERE node_id=?", (nid,))
                    conn.execute("DELETE FROM world_files WHERE path=?", (p,))
            conn.commit()
            return files_updated, nodes_indexed
        finally:
            conn.close()

    def retrieve(self, query: str, k: int = 6) -> List[WorldRetrievedNode]:
        query = (query or "").strip()
        if not query:
            return []
        try:
            qv = _embed_one(query, self.embed_model)
        except Exception:
            return []

        conn = self._conn()
        try:
            rows = conn.execute(
                "SELECT node_id, path, node_type, title, tags, summary, facts, embedding FROM world_nodes"
            ).fetchall()
        finally:
            conn.close()

        scored: List[WorldRetrievedNode] = []
        for nid, path, ntype, title, tags_json, summary, facts_json, emb_blob in rows:
            try:
                v = np.frombuffer(emb_blob, dtype=np.float32)
                score = float(np.dot(qv, v))
            except Exception:
                continue
            try:
                tags = json.loads(tags_json) if tags_json else []
            except Exception:
                tags = []
            try:
                facts = json.loads(facts_json) if facts_json else []
            except Exception:
                facts = []
            scored.append(WorldRetrievedNode(score, str(nid), str(ntype), str(title), [str(t) for t in tags], str(summary or ""), [str(f) for f in facts], str(path)))
        scored.sort(key=lambda n: n.score, reverse=True)
        return scored[: max(0, int(k))]

    def format_nodes(self, nodes: List[WorldRetrievedNode]) -> str:
        if not nodes:
            return "(No world nodes retrieved.)"
        out = []
        for n in nodes:
            out.append(f"[{n.node_id}] ({n.node_type}) {n.title}  score={n.score:.3f}")
            if n.tags:
                out.append(f"  tags: {', '.join(n.tags)}")
            if n.summary:
                out.append(f"  summary: {n.summary}")
            if n.facts:
                for f in n.facts[:10]:
                    out.append(f"  - {f}")
            out.append("")
        return "\n".join(out).strip()

    def apply_patch(self, patch: Dict[str, Any]) -> Dict[str, Any]:
        if not isinstance(patch, dict):
            return {"applied": False, "reason": "patch not dict"}
        receipt: Dict[str, Any] = {"applied": True, "upserted": 0, "deleted": 0, "facts_appended": 0, "edges_added": 0}

        upserts = patch.get("upsert_nodes") or []
        if isinstance(upserts, dict):
            upserts = [upserts]
        for n in upserts:
            if isinstance(n, dict):
                self.upsert_node(n)
                receipt["upserted"] += 1

        deletes = patch.get("delete_nodes") or []
        if isinstance(deletes, str):
            deletes = [deletes]
        for nid in deletes:
            if self.delete_node(str(nid)):
                receipt["deleted"] += 1

        app = patch.get("append_facts") or []
        if isinstance(app, dict):
            app = [app]
        for item in app:
            if not isinstance(item, dict):
                continue
            nid = str(item.get("id") or item.get("node_id") or "").strip()
            facts = item.get("facts") or []
            if not nid or not facts:
                continue
            p = os.path.join(WORLD_NODES_DIR, f"{nid}.json")
            if not os.path.exists(p):
                continue
            node = self._safe_load_json(p)
            node = self._normalize_node(node)
            new_facts = []
            if isinstance(facts, str):
                facts = [ln.strip("- ").strip() for ln in facts.splitlines() if ln.strip()]
            for f in facts:
                f = str(f).strip()
                if f and f not in node["facts"]:
                    new_facts.append(f)
            if new_facts:
                node["facts"].extend(new_facts)
                node["updated_at"] = _now_ts()
                self.upsert_node(node)
                receipt["facts_appended"] += len(new_facts)

        edges = patch.get("new_edges") or []
        if isinstance(edges, dict):
            edges = [edges]
        if edges:
            try:
                cur = []
                if os.path.exists(WORLD_EDGES_FILE):
                    cur = json.loads(_safe_read_text(WORLD_EDGES_FILE) or "[]")
                if not isinstance(cur, list):
                    cur = []
                existing = set()
                for e in cur:
                    if isinstance(e, dict):
                        existing.add((e.get("from"), e.get("to"), e.get("rel")))
                for e in edges:
                    if not isinstance(e, dict):
                        continue
                    key = (e.get("from"), e.get("to"), e.get("rel"))
                    if key in existing:
                        continue
                    cur.append({"from": e.get("from"), "to": e.get("to"), "rel": e.get("rel")})
                    existing.add(key)
                    receipt["edges_added"] += 1
                with open(WORLD_EDGES_FILE, "w", encoding="utf-8") as f:
                    json.dump(cur, f, indent=2, ensure_ascii=False)
            except Exception:
                pass

        try:
            self.index_nodes()
        except Exception:
            pass
        return receipt


def _extract_world_patch_json(text: str) -> Optional[Dict[str, Any]]:
    if not text:
        return None

    def _try(candidate: str) -> Optional[Dict[str, Any]]:
        try:
            obj = json.loads(candidate)
            return obj if isinstance(obj, dict) else None
        except Exception:
            return None

    m = re.search(r"<WORLD_PATCH>(.*?)</WORLD_PATCH>", text, flags=re.DOTALL | re.IGNORECASE)
    if m:
        obj = _try(m.group(1).strip())
        if obj and "world_patch" in obj:
            return obj

    for m in re.finditer(r"```json(.*?)```", text, flags=re.DOTALL | re.IGNORECASE):
        obj = _try(m.group(1).strip())
        if obj and "world_patch" in obj:
            return obj

    # scan for JSON objects containing world_patch
    t = text
    n = len(t)
    i = 0
    while i < n:
        if t[i] != "{":
            i += 1
            continue
        depth = 0
        in_str = False
        esc = False
        for j in range(i, n):
            ch = t[j]
            if in_str:
                if esc:
                    esc = False
                elif ch == "\\":
                    esc = True
                elif ch == '"':
                    in_str = False
            else:
                if ch == '"':
                    in_str = True
                elif ch == "{":
                    depth += 1
                elif ch == "}":
                    depth -= 1
                    if depth == 0:
                        cand = t[i:j+1]
                        if "world_patch" in cand:
                            obj = _try(cand)
                            if obj and "world_patch" in obj:
                                return obj
                        i = j + 1
                        break
        else:
            i += 1
    return None


# =========================
# Online Assist (Tavily)
# =========================
def tavily_search(query: str, k: int = 3) -> Optional[str]:
    if requests is None:
        return None
    api_key = os.getenv(TAVILY_API_KEY_ENV, "").strip()
    if not api_key:
        return None
    url = "https://api.tavily.com/search"
    payload = {
        "api_key": api_key,
        "query": query,
        "search_depth": "basic",
        "max_results": int(k),
        "include_answer": False,
        "include_raw_content": False,
    }
    try:
        r = requests.post(url, json=payload, timeout=WEB_TIMEOUT_SEC)
        r.raise_for_status()
        data = r.json()
        results = (data.get("results") or [])[:k]
        if not results:
            return None
        lines = []
        for it in results:
            title = (it.get("title") or "").strip()
            content = (it.get("content") or "").strip()
            u = (it.get("url") or "").strip()
            if title or content:
                lines.append(f"- {title}\n  {content}\n  {u}".strip())
        return "\n\n".join(lines) if lines else None
    except Exception:
        return None


# =========================
# Jobs / ComfyUI helper
# =========================
def _json_deep_replace(obj: Any, needle: str, repl: str) -> Any:
    if isinstance(obj, str):
        return obj.replace(needle, repl)
    if isinstance(obj, list):
        return [_json_deep_replace(x, needle, repl) for x in obj]
    if isinstance(obj, dict):
        return {k: _json_deep_replace(v, needle, repl) for k, v in obj.items()}
    return obj


def comfyui_submit(workflow: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    if requests is None or not COMFYUI_URL:
        return None
    try:
        url = COMFYUI_URL.rstrip("/") + "/prompt"
        r = requests.post(url, json={"prompt": workflow}, timeout=WEB_TIMEOUT_SEC)
        r.raise_for_status()
        return r.json()
    except Exception:
        return None


# =========================
# Safe file creation helpers
# =========================
def sanitize_filename(name: str) -> Optional[str]:
    name = (name or "").strip()
    name = name.replace("\\", "/")
    name = name.split("/")[-1]
    name = re.sub(r"[^a-zA-Z0-9._-]+", "_", name)
    if not name or name in (".", ".."):
        return None
    if name.startswith("."):
        name = "file" + name
    ext = os.path.splitext(name)[1].lower()
    if ext not in ALLOWED_CREATE_EXTS:
        return None
    return name


# =========================
# GameMaster (light)
# =========================
class GameMaster:
    def __init__(self):
        self.state = "DORMANT"
        self.world_path: Optional[str] = None
        self.lcg_state = 123

    def roll_d20(self, mod: int = 0, dc: int = 10) -> Tuple[int, int, str]:
        self.lcg_state = (self.lcg_state * 1103515245 + 12345) & 0x7fffffff
        d20 = (self.lcg_state % 20) + 1
        total = d20 + mod
        if d20 == 20:
            outcome = "CRITICAL SUCCESS"
        elif d20 == 1:
            outcome = "CRITICAL FAILURE"
        else:
            outcome = "SUCCESS" if total >= dc else "FAILURE"
        return d20, total, outcome

    def forge_world(self, player_name: str = "Mikey") -> str:
        os.makedirs(WELL_FOLDER, exist_ok=True)
        ts = _now_ts()
        filename = f"{player_name.lower().replace(' ', '_')}_world.wwf"
        path = os.path.join(WELL_FOLDER, filename)

        wwf = f"""# WORLD WEAVE FILE (WWF)
# Generated: {ts}

PLAYER: {player_name}
THEME: Nevora x Sovereign Weave x Blackout Noir
RULESET: DND 5E (light)
SEED: {self.lcg_state}

OPENING:
You stand at the edge of Starlight City, where neon rain turns to prism mist.
A hush rolls through the alley like a tide — something ancient is waking.

FACTIONS:
- Parallax Institute (keepers of the chambers)
- Lucky Strike Syndicate (noir undercurrent)
- Matchbook Rangers (field agents)
- Dialogic Arts Archivists (story-forgers)

QUEST HOOKS:
- Recover the missing Codex page from a silent museum wing.
- Track a signal pulsing at 60.106 Hz beneath the subway.
- Investigate the “Blackout” that keeps repeating at midnight.

NOTES:
Add anything below — the GM will treat this as canon lore.
"""
        with open(path, "w", encoding="utf-8") as f:
            f.write(wwf)
        self.world_path = path
        self.state = "ACTIVE"
        return path


