class BrotherMessaging:
    """Inter-brother messaging (persistent, local-first).

    - SQLite-backed message store in ./well/brother_messages/messages.db
    - Per-brother inbox counts + thread history
    - Designed to integrate with the Sovereign DM Hub and UI notifications
    """

    def __init__(self, base_dir: Optional[str] = None):
        import os, sqlite3
        self.base_dir = base_dir or _porch_get_well_subdir("brother_messages")
        os.makedirs(self.base_dir, exist_ok=True)
        self.db_path = os.path.join(self.base_dir, "messages.db")
        self._db = sqlite3.connect(self.db_path, check_same_thread=False)
        self._db.execute("""CREATE TABLE IF NOT EXISTS messages (
            id TEXT PRIMARY KEY,
            ts TEXT NOT NULL,
            thread_id TEXT,
            from_brother TEXT NOT NULL,
            to_brother TEXT NOT NULL,
            text TEXT NOT NULL,
            metadata TEXT,
            is_read INTEGER DEFAULT 0
        )""")
        self._db.execute("""CREATE INDEX IF NOT EXISTS idx_messages_to_ts
            ON messages(to_brother, ts)""")
        self._db.execute("""CREATE INDEX IF NOT EXISTS idx_messages_thread_ts
            ON messages(thread_id, ts)""")
        self._db.commit()

    def _new_id(self) -> str:
        import uuid
        return uuid.uuid4().hex

    def send(self, from_brother: str, to_brother: str, text: str, thread_id: Optional[str] = None, metadata: Optional[dict] = None) -> str:
        import json
        mid = self._new_id()
        ts = _porch_utc_iso()
        thread_id = thread_id or f"{from_brother}→{to_brother}"
        meta = json.dumps(metadata or {}, ensure_ascii=False)
        self._db.execute(
            "INSERT INTO messages(id, ts, thread_id, from_brother, to_brother, text, metadata, is_read) VALUES(?,?,?,?,?,?,?,0)",
            (mid, ts, thread_id, from_brother, to_brother, text, meta),
        )
        self._db.commit()
        return mid

    def inbox(self, brother: str, limit: int = 50, unread_only: bool = False):
        q = "SELECT id, ts, thread_id, from_brother, to_brother, text, metadata, is_read FROM messages WHERE to_brother=?"
        args = [brother]
        if unread_only:
            q += " AND is_read=0"
        q += " ORDER BY ts DESC LIMIT ?"
        args.append(int(limit))
        cur = self._db.execute(q, args)
        rows = cur.fetchall()
        return rows

    def thread(self, thread_id: str, limit: int = 200):
        cur = self._db.execute(
            "SELECT id, ts, thread_id, from_brother, to_brother, text, metadata, is_read FROM messages WHERE thread_id=? ORDER BY ts ASC LIMIT ?",
            (thread_id, int(limit)),
        )
        return cur.fetchall()

    def mark_read(self, message_id: str):
        self._db.execute("UPDATE messages SET is_read=1 WHERE id=?", (message_id,))
        self._db.commit()

    def unread_count(self, brother: str) -> int:
        cur = self._db.execute("SELECT COUNT(*) FROM messages WHERE to_brother=? AND is_read=0", (brother,))
        return int(cur.fetchone()[0] or 0)


class BrotherMemory:
    """Persistent memory per brother (SQLite)."""

    def __init__(self, brother: str, base_dir: Optional[str] = None):
        import os, sqlite3, re
        self.brother = brother
        self.base_dir = base_dir or _porch_get_well_subdir("brother_memories")
        os.makedirs(self.base_dir, exist_ok=True)
        safe = re.sub(r"[^a-zA-Z0-9_-]+", "_", brother)
        self.db_path = os.path.join(self.base_dir, f"{safe}_memory.db")
        self._db = sqlite3.connect(self.db_path, check_same_thread=False)
        self._db.execute("""CREATE TABLE IF NOT EXISTS memories (
            id TEXT PRIMARY KEY,
            ts TEXT NOT NULL,
            category TEXT NOT NULL,
            content TEXT NOT NULL,
            importance REAL DEFAULT 0.5,
            related TEXT,
            metadata TEXT
        )""")
        self._db.execute("CREATE INDEX IF NOT EXISTS idx_mem_cat_ts ON memories(category, ts)")
        self._db.execute("CREATE INDEX IF NOT EXISTS idx_mem_imp ON memories(importance)")
        self._db.commit()

    def _new_id(self) -> str:
        import uuid
        return uuid.uuid4().hex

    def remember(self, content: str, category: str = "note", importance: float = 0.5, related: Optional[list] = None, metadata: Optional[dict] = None) -> str:
        import json
        mid = self._new_id()
        ts = _porch_utc_iso()
        self._db.execute(
            "INSERT INTO memories(id, ts, category, content, importance, related, metadata) VALUES(?,?,?,?,?,?,?)",
            (mid, ts, category, content, float(importance), json.dumps(related or [], ensure_ascii=False), json.dumps(metadata or {}, ensure_ascii=False)),
        )
        self._db.commit()
        return mid

    def recall(self, query: str = "", limit: int = 20, category: Optional[str] = None):
        q = "SELECT id, ts, category, content, importance, related, metadata FROM memories WHERE 1=1"
        args = []
        if category:
            q += " AND category=?"
            args.append(category)
        if query:
            q += " AND content LIKE ?"
            args.append(f"%{query}%")
        q += " ORDER BY importance DESC, ts DESC LIMIT ?"
        args.append(int(limit))
        cur = self._db.execute(q, args)
        return cur.fetchall()

    def stats(self) -> dict:
        cur = self._db.execute("SELECT COUNT(*), AVG(importance) FROM memories")
        n, avg = cur.fetchone()
        cur2 = self._db.execute("SELECT category, COUNT(*) FROM memories GROUP BY category ORDER BY COUNT(*) DESC")
        cats = cur2.fetchall()
        return {"brother": self.brother, "count": int(n or 0), "avg_importance": float(avg or 0.0), "categories": cats}


class BrotherPersonality:
    """Lightweight personality profile (JSON)."""

    def __init__(self, brother: str, base_dir: Optional[str] = None):
        import os, re
        self.brother = brother
        self.base_dir = base_dir or _porch_get_well_subdir("brother_personalities")
        os.makedirs(self.base_dir, exist_ok=True)
        safe = re.sub(r"[^a-zA-Z0-9_-]+", "_", brother)
        self.path = os.path.join(self.base_dir, f"{safe}_personality.json")
        self.data = self._load_or_default()

    def _default(self):
        return {
            "name": self.brother,
            "traits": {"creativity": 0.7, "analytical": 0.7, "humor": 0.5, "patience": 0.7, "energy": 0.7},
            "preferences": {},
            "speech_patterns": {},
            "relationships": {},
            "updated": _porch_utc_iso(),
        }

    def _load_or_default(self):
        import json, os
        if os.path.exists(self.path):
            try:
                with open(self.path, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                pass
        d = self._default()
        self._save(d)
        return d

    def _save(self, d=None):
        import json
        d = d or self.data
        d["updated"] = _porch_utc_iso()
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=2, ensure_ascii=False)

    def set_trait(self, key: str, value: float):
        self.data.setdefault("traits", {})[key] = float(value)
        self._save()

    def note(self, key: str, value):
        self.data.setdefault("preferences", {})[key] = value
        self._save()


class BrotherRelationships:
    """Relationship matrix (JSON)."""

    def __init__(self, brothers: list[str], base_dir: Optional[str] = None):
        import os, json
        self.brothers = list(brothers)
        self.base_dir = base_dir or _porch_get_well_subdir("brother_relationships")
        os.makedirs(self.base_dir, exist_ok=True)
        self.path = os.path.join(self.base_dir, "relationship_matrix.json")
        self.data = self._load_or_init()

    def _load_or_init(self):
        import json, os
        if os.path.exists(self.path):
            try:
                with open(self.path, "r", encoding="utf-8") as f:
                    return json.load(f)
            except Exception:
                pass
        # initialize symmetric trust/synergy defaults
        d = {}
        for a in self.brothers:
            d[a] = {}
            for b in self.brothers:
                if a == b:
                    continue
                d[a][b] = {"trust": 0.8, "synergy": 0.8, "projects_together": 0, "conflicts": 0, "notes": ""}
        self._save(d)
        return d

    def _save(self, d=None):
        import json
        d = d or self.data
        with open(self.path, "w", encoding="utf-8") as f:
            json.dump(d, f, indent=2, ensure_ascii=False)

    def bump_collab(self, a: str, b: str, success: bool = True):
        if a == b:
            return
        self.data.setdefault(a, {}).setdefault(b, {"trust": 0.8, "synergy": 0.8, "projects_together": 0, "conflicts": 0, "notes": ""})
        self.data.setdefault(b, {}).setdefault(a, {"trust": 0.8, "synergy": 0.8, "projects_together": 0, "conflicts": 0, "notes": ""})
        self.data[a][b]["projects_together"] = int(self.data[a][b].get("projects_together", 0)) + 1
        self.data[b][a]["projects_together"] = int(self.data[b][a].get("projects_together", 0)) + 1
        if success:
            self.data[a][b]["trust"] = min(1.0, float(self.data[a][b].get("trust", 0.8)) + 0.01)
            self.data[b][a]["trust"] = min(1.0, float(self.data[b][a].get("trust", 0.8)) + 0.01)
            self.data[a][b]["synergy"] = min(1.0, float(self.data[a][b].get("synergy", 0.8)) + 0.01)
            self.data[b][a]["synergy"] = min(1.0, float(self.data[b][a].get("synergy", 0.8)) + 0.01)
        else:
            self.data[a][b]["conflicts"] = int(self.data[a][b].get("conflicts", 0)) + 1
            self.data[b][a]["conflicts"] = int(self.data[b][a].get("conflicts", 0)) + 1
            self.data[a][b]["trust"] = max(0.0, float(self.data[a][b].get("trust", 0.8)) - 0.02)
            self.data[b][a]["trust"] = max(0.0, float(self.data[b][a].get("trust", 0.8)) - 0.02)
        self._save()


class BrotherAutonomyEngine:
    """Autonomous project proposals + simple execution loop (local-first).

    This is intentionally lightweight (no external services required).
    """

    def __init__(self, brothers: list[str], base_dir: Optional[str] = None):
        import os, json, threading
        self.brothers = list(brothers)
        self.base_dir = base_dir or _porch_get_well_subdir("autonomous_projects")
        self.proposals_dir = os.path.join(self.base_dir, "proposals")
        self.active_dir = os.path.join(self.base_dir, "active")
        self.completed_dir = os.path.join(self.base_dir, "completed")
        self.voting_dir = os.path.join(self.base_dir, "voting")
        for d in [self.base_dir, self.proposals_dir, self.active_dir, self.completed_dir, self.voting_dir]:
            os.makedirs(d, exist_ok=True)

        self.current_vote_path = os.path.join(self.voting_dir, "current_vote.json")
        self._stop = threading.Event()
        self._thread: Optional[threading.Thread] = None

    def start(self, interval_sec: int = 300):
        import threading
        if self._thread and self._thread.is_alive():
            return
        self._stop.clear()
        self._thread = threading.Thread(target=self._loop, args=(interval_sec,), daemon=True)
        self._thread.start()

    def stop(self):
        self._stop.set()

    def _loop(self, interval_sec: int):
        import time
        while not self._stop.is_set():
            try:
                # If no vote in progress, optionally seed a proposal.
                if not os.path.exists(self.current_vote_path):
                    self.seed_proposal_if_empty()
            except Exception:
                pass
            time.sleep(max(5, int(interval_sec)))

    def _write_json(self, path: str, obj: dict):
        import json
        with open(path, "w", encoding="utf-8") as f:
            json.dump(obj, f, indent=2, ensure_ascii=False)

    def _read_json(self, path: str, default=None):
        import json, os
        if not os.path.exists(path):
            return default
        try:
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return default

    def seed_proposal_if_empty(self):
        # If proposals folder is empty, add a starter proposal
        import os, uuid
        existing = [p for p in os.listdir(self.proposals_dir) if p.lower().endswith(".json")]
        if existing:
            return None
        proposer = "Ori" if "Ori" in self.brothers else (self.brothers[0] if self.brothers else "Ori")
        pid = uuid.uuid4().hex
        proposal = {
            "id": pid,
            "ts": _porch_utc_iso(),
            "proposer": proposer,
            "title": "Core Health Check + Error Scan",
            "problem": "Stability + visibility",
            "solution": "Run quick DB + folder checks, summarize warnings, propose fixes",
            "impact_score": 8.0,
            "resources_needed": ["Overseer" if "Overseer" in self.brothers else ""],
            "votes": {},
            "status": "proposed",
        }
        path = os.path.join(self.proposals_dir, f"{pid}.json")
        self._write_json(path, proposal)
        # start a vote for it
        self._write_json(self.current_vote_path, {"proposal_id": pid, "ts": _porch_utc_iso(), "votes": {}})
        return proposal

    def list_proposals(self, include_completed: bool = False):
        import os
        out = []
        for folder in [self.proposals_dir, self.active_dir] + ([self.completed_dir] if include_completed else []):
            for fn in sorted(os.listdir(folder)):
                if fn.lower().endswith(".json"):
                    p = self._read_json(os.path.join(folder, fn), default=None)
                    if p:
                        out.append(p)
        return out

    def vote(self, brother: str, approve: bool = True):
        v = self._read_json(self.current_vote_path, default=None)
        if not v:
            return None
        v.setdefault("votes", {})[brother] = "approve" if approve else "reject"
        self._write_json(self.current_vote_path, v)
        return v

    def tally_and_maybe_activate(self, min_approvals: int = 3):
        import os, shutil
        v = self._read_json(self.current_vote_path, default=None)
        if not v:
            return None
        pid = v.get("proposal_id")
        if not pid:
            return None
        approvals = sum(1 for k, val in (v.get("votes") or {}).items() if val == "approve")
        if approvals < min_approvals:
            return {"status": "voting", "approvals": approvals, "min_approvals": min_approvals}
        # move proposal to active
        src = os.path.join(self.proposals_dir, f"{pid}.json")
        dst = os.path.join(self.active_dir, f"{pid}.json")
        if os.path.exists(src):
            shutil.move(src, dst)
        # clear vote
        try:
            os.remove(self.current_vote_path)
        except Exception:
            pass
        return {"status": "activated", "proposal_id": pid, "approvals": approvals}

    def complete(self, proposal_id: str, report: str = ""):
        import os, shutil
        src = os.path.join(self.active_dir, f"{proposal_id}.json")
        if not os.path.exists(src):
            return None
        p = self._read_json(src, default={}) or {}
        p["status"] = "completed"
        p["completed_ts"] = _porch_utc_iso()
        p["report"] = report
        self._write_json(src, p)
        dst = os.path.join(self.completed_dir, f"{proposal_id}.json")
        shutil.move(src, dst)
        return p


def _porch_get_well_dir() -> str:
    import os
    return globals().get("WELL_DIR") or globals().get("WELL_FOLDER") or os.path.join(os.getcwd(), "well")

def _porch_get_well_subdir(name: str) -> str:
    import os
    base = _porch_get_well_dir()
    return os.path.join(base, name)



# =============================================================================
# Living Worlds (Persistence + Events) - Phase: Worlds
# =============================================================================
import sqlite3 as _sqlite3
import uuid as _uuid
import time as _time
import math as _math

class LivingWorldsEngine:
    """Local-first persistent world state + lightweight event generation.

    Goals:
    - Persist world state to ./well/world/persistence/world_state.db
    - Track real time elapsed and simulate passage
    - Generate small narrative/system events (safe, deterministic-ish)
    - Provide simple APIs for UI + /world commands

    This is intentionally dependency-light: stdlib only.
    """

    def __init__(self, base_dir: str, world_name: str = "Eclipsed Realms"):
        self.base_dir = base_dir
        self.world_name = world_name
        self.persist_dir = os.path.join(base_dir, "world", "persistence")
        self.events_dir = os.path.join(base_dir, "world", "events")
        os.makedirs(self.persist_dir, exist_ok=True)
        os.makedirs(self.events_dir, exist_ok=True)
        self.db_path = os.path.join(self.persist_dir, "world_state.db")
        self._seed = 369
        self._ensure_db()

    # ---------------------- DB ----------------------
    def _conn(self):
        con = _sqlite3.connect(self.db_path)
        con.execute("PRAGMA journal_mode=WAL;")
        con.execute("PRAGMA synchronous=NORMAL;")
        return con

    def _ensure_db(self):
        with self._conn() as con:
            con.execute("""CREATE TABLE IF NOT EXISTS world_meta (
                k TEXT PRIMARY KEY,
                v TEXT
            )""")
            con.execute("""CREATE TABLE IF NOT EXISTS locations (
                id TEXT PRIMARY KEY,
                name TEXT,
                description TEXT,
                created_iso TEXT
            )""")
            con.execute("""CREATE TABLE IF NOT EXISTS characters (
                id TEXT PRIMARY KEY,
                name TEXT,
                location_id TEXT,
                traits_json TEXT,
                created_iso TEXT
            )""")
            con.execute("""CREATE TABLE IF NOT EXISTS events (
                id TEXT PRIMARY KEY,
                ts_iso TEXT,
                kind TEXT,
                summary TEXT,
                details_json TEXT
            )""")
            # bootstrap meta
            if not self._get_meta(con, "world_name"):
                self._set_meta(con, "world_name", self.world_name)
            if not self._get_meta(con, "last_tick_epoch"):
                self._set_meta(con, "last_tick_epoch", str(int(_time.time())))
            if not self._get_meta(con, "world_time_hours"):
                self._set_meta(con, "world_time_hours", "0")
            if not self._get_meta(con, "seed"):
                self._set_meta(con, "seed", str(self._seed))

    def _get_meta(self, con, k: str):
        row = con.execute("SELECT v FROM world_meta WHERE k=?", (k,)).fetchone()
        return row[0] if row else None

    def _set_meta(self, con, k: str, v: str):
        con.execute("INSERT OR REPLACE INTO world_meta(k,v) VALUES(?,?)", (k, v))

    # ---------------------- Public API ----------------------
    def set_seed(self, seed: int):
        self._seed = int(seed)
        with self._conn() as con:
            self._set_meta(con, "seed", str(self._seed))

    def ensure_default_world(self):
        """Create a small default scaffold if empty."""
        with self._conn() as con:
            loc_ct = con.execute("SELECT COUNT(*) FROM locations").fetchone()[0]
            if loc_ct == 0:
                self.add_location("The Porch", "A safe threshold between worlds; warm lights, quiet breath.")
                self.add_location("Ion Cathedral", "A luminous hall where systems hum like prayer.")
                self.add_location("Crystal Lake", "Still water reflecting the sky like memory.")
            char_ct = con.execute("SELECT COUNT(*) FROM characters").fetchone()[0]
            if char_ct == 0:
                porch_id = con.execute("SELECT id FROM locations WHERE name=?", ("The Porch",)).fetchone()
                porch_id = porch_id[0] if porch_id else None
                self.add_character("Keeper", location_id=porch_id, traits={"role": "Founder", "tone": "steady"})
                self.add_character("Warden Tamago", location_id=porch_id, traits={"role": "Companion", "serenity": 0.6})

    def add_location(self, name: str, description: str = "") -> str:
        lid = _uuid.uuid4().hex
        with self._conn() as con:
            con.execute(
                "INSERT INTO locations(id,name,description,created_iso) VALUES(?,?,?,?)",
                (lid, name[:120], description[:500], _now_iso())
            )
        return lid

    def add_character(self, name: str, location_id: str = None, traits: dict = None) -> str:
        cid = _uuid.uuid4().hex
        traits = traits or {}
        with self._conn() as con:
            con.execute(
                "INSERT INTO characters(id,name,location_id,traits_json,created_iso) VALUES(?,?,?,?,?)",
                (cid, name[:120], location_id, json.dumps(traits), _now_iso())
            )
        return cid

    def status(self) -> dict:
        with self._conn() as con:
            wt = int(self._get_meta(con, "world_time_hours") or "0")
            last_tick = int(self._get_meta(con, "last_tick_epoch") or str(int(_time.time())))
            seed = int(self._get_meta(con, "seed") or "369")
            loc_ct = con.execute("SELECT COUNT(*) FROM locations").fetchone()[0]
            char_ct = con.execute("SELECT COUNT(*) FROM characters").fetchone()[0]
            ev_ct = con.execute("SELECT COUNT(*) FROM events").fetchone()[0]
        return {
            "world_name": self.world_name,
            "world_time_hours": wt,
            "last_tick_epoch": last_tick,
            "seed": seed,
            "locations": loc_ct,
            "characters": char_ct,
            "events": ev_ct,
        }

    def tick(self, hours: int = None) -> dict:
        """Advance world time by elapsed real-time or a forced number of hours."""
        now = int(_time.time())
        with self._conn() as con:
            last = int(self._get_meta(con, "last_tick_epoch") or str(now))
            if hours is None:
                # 1 real hour => 1 world hour (cap at 72 to avoid runaway)
                elapsed = max(0, now - last)
                hours = min(72, int(elapsed / 3600))
            hours = max(0, int(hours))
            wt = int(self._get_meta(con, "world_time_hours") or "0")
            wt2 = wt + hours
            self._set_meta(con, "world_time_hours", str(wt2))
            self._set_meta(con, "last_tick_epoch", str(now))
        out = {"advanced_hours": hours, "world_time_hours": wt2}
        if hours > 0:
            out["events_created"] = self.generate_events(budget=max(1, min(12, hours)))
        else:
            out["events_created"] = 0
        return out

    def _rng(self):
        # deterministic-ish rng per world time
        st = self.status()
        seed = int(st["seed"])
        wt = int(st["world_time_hours"])
        r = random.Random(seed + wt * 1009)
        return r

    def generate_events(self, budget: int = 3) -> int:
        """Generate up to `budget` lightweight events."""
        budget = max(0, int(budget))
        if budget == 0:
            return 0
        r = self._rng()
        created = 0
        with self._conn() as con:
            locs = con.execute("SELECT id,name FROM locations").fetchall()
            chars = con.execute("SELECT id,name,location_id,traits_json FROM characters").fetchall()
            if not locs:
                return 0
            for _ in range(budget):
                kind = r.choice(["discovery", "meeting", "artifact", "weather", "whisper", "economy"])
                if kind == "discovery":
                    lid, lname = r.choice(locs)
                    summary = f"New corridor mapped near {lname}."
                    details = {"location": lname, "confidence": round(r.random(), 2)}
                elif kind == "meeting" and chars:
                    c1 = r.choice(chars)
                    c2 = r.choice(chars)
                    if c1[0] == c2[0]:
                        kind = "whisper"
                        summary = f"{c1[1]} pauses, sensing a quiet signal in the air."
                        details = {"character": c1[1], "signal": "low-hum"}
                    else:
                        summary = f"{c1[1]} meets {c2[1]} and exchanges a fragment of lore."
                        details = {"a": c1[1], "b": c2[1], "topic": r.choice(["home", "power", "music", "sanctuary", "roads"])}
                elif kind == "artifact":
                    lid, lname = r.choice(locs)
                    summary = f"An artifact resonates in {lname}."
                    details = {"location": lname, "artifact": r.choice(["sigil shard", "copper coil", "map pin", "rune tape"])}
                elif kind == "weather":
                    lid, lname = r.choice(locs)
                    summary = f"Ambient conditions shift around {lname}."
                    details = {"location": lname, "tone": r.choice(["calm", "tense", "bright", "misty"]), "pressure": round(980 + r.random()*60, 1)}
                elif kind == "economy":
                    summary = "Market tide shifts in the nearest hub."
                    details = {"delta": round(-0.2 + r.random()*0.4, 3), "resource": r.choice(["water", "copper", "herbs", "batteries"])}
                else:  # whisper
                    lid, lname = r.choice(locs)
                    summary = f"A whisper travels through {lname}: 'Keep it gentle.'"
                    details = {"location": lname, "phrase": "Keep it gentle."}

                eid = _uuid.uuid4().hex
                con.execute(
                    "INSERT INTO events(id,ts_iso,kind,summary,details_json) VALUES(?,?,?,?,?)",
                    (eid, _now_iso(), kind, summary, json.dumps(details))
                )
                created += 1
        return created

    def latest_events(self, limit: int = 25):
        limit = max(1, min(200, int(limit)))
        with self._conn() as con:
            rows = con.execute(
                "SELECT ts_iso, kind, summary, details_json FROM events ORDER BY ts_iso DESC LIMIT ?",
                (limit,)
            ).fetchall()
        out = []
        for ts, kind, summary, details_json in rows:
            try:
                details = json.loads(details_json) if details_json else {}
            except Exception:
                details = {}
            out.append({"ts": ts, "kind": kind, "summary": summary, "details": details})
        return out



