    # ---------- UI ----------
    def _build_ui(self) -> None:
        self.grid_columnconfigure(1, weight=1)
        self.grid_rowconfigure(0, weight=0)
        self.grid_rowconfigure(1, weight=1)
        self.grid_rowconfigure(2, weight=0)

        # Topbar (status indicators restored across the very top)
        self.topbar = ctk.CTkFrame(self, corner_radius=0, fg_color=PALETTE["panel"])
        self.topbar.grid(row=0, column=0, columnspan=2, sticky="ew")
        self.topbar.grid_columnconfigure(0, weight=1)

        self.pill_frame = ctk.CTkFrame(self.topbar, fg_color="transparent")
        self.pill_frame.grid(row=0, column=0, sticky="w", padx=12, pady=10)
        def _pill(label_text: str) -> ctk.CTkLabel:
            return ctk.CTkLabel(
                self.pill_frame,
                text=label_text,
                font=ctk.CTkFont(size=12, weight="bold"),
                corner_radius=999,
                fg_color="#1B274A",
                text_color=PALETTE["muted"],
                padx=10,
                pady=4,
            )

        self.pill_online = _pill("ONLINE: OFF")
        self.pill_online.pack(side="left", padx=(0, 6))
        self.pill_tavily = _pill("TAVILY: OFF")
        self.pill_tavily.pack(side="left", padx=(0, 6))
        self.pill_comfy = _pill("COMFYUI: OFF")
        self.pill_comfy.pack(side="left", padx=(0, 6))
        self.pill_autosnap = _pill("AUTOSNAP: OFF (0)")
        self.pill_autosnap.pack(side="left", padx=(0, 6))
        self.pill_scene = _pill(self._scene_pill_text())
        self.pill_scene.pack(side="left", padx=(0, 6))
        self.pill_world = _pill("WORLD: OFF")
        self.pill_world.pack(side="left", padx=(0, 6))

        # Online toggle back on the topbar
        self.online_var = ctk.BooleanVar(value=bool(getattr(self, "online_enabled", False)))
        self.online_switch = ctk.CTkSwitch(
            self.topbar,
            text="🌐 Online Assist",
            variable=self.online_var,
            command=self._toggle_online,
            progress_color=PALETTE["accent"],
        )
        self.online_switch.grid(row=0, column=1, sticky="e", padx=12, pady=10)

        # Sidebar (scrollable)
        self.sidebar = ctk.CTkScrollableFrame(self, width=360, corner_radius=0, fg_color=PALETTE["panel"])
        self.sidebar.grid(row=1, column=0, rowspan=2, sticky="nsew")
        try:
            self.sidebar.grid_propagate(False)
        except TypeError:
            # Some CustomTkinter versions define grid_propagate() without args.
            pass
        except Exception:
            pass

        # Main middle stack (House Map + Chat)
        self.main_mid = ctk.CTkFrame(self, fg_color="transparent")
        self.main_mid.grid(row=1, column=1, padx=18, pady=(18, 10), sticky="nsew")
        self.main_mid.grid_columnconfigure(0, weight=1)
        self.main_mid.grid_rowconfigure(1, weight=1)

        # House Map panel (collapsible)
        self.house_map_panel = ctk.CTkFrame(
            self.main_mid,
            corner_radius=14,
            fg_color=PALETTE["panel2"],
            border_width=1,
            border_color="#1B274A",
        )
        self.house_map_panel.grid(row=0, column=0, sticky="ew", pady=(0, 10))
        self._build_house_map_panel(self.house_map_panel)
        if not getattr(self, "house_map_visible", True):
            self.house_map_panel.grid_remove()


        # Chat (tabs per mode)
        self._mode_textboxes: Dict[str, ctk.CTkTextbox] = {}
        self._mode_tktexts: Dict[str, Any] = {}
        self._mode_rendered: Dict[str, bool] = {}

        self.mode_tabs = ctk.CTkTabview(
            self.main_mid,
            fg_color=PALETTE["panel2"],
            segmented_button_fg_color=PALETTE["panel"],
            segmented_button_selected_color=PALETTE["accent"],
            segmented_button_selected_hover_color=PALETTE["accent"],
            segmented_button_unselected_color=PALETTE["panel"],
            command=self._on_mode_tab_changed,
        )
        self.mode_tabs.grid(row=1, column=0, sticky="nsew", padx=18, pady=(0, 8))

        for mode in getattr(self, "_mode_names", ["Porch"]):
            tab = self.mode_tabs.add(mode)
            tb = ctk.CTkTextbox(
                tab,
                font=ctk.CTkFont(size=self.font_size),
                fg_color=PALETTE["panel2"],
                text_color=PALETTE["text"],
                border_color="#1B274A",
                border_width=1,
            )
            tb.pack(fill="both", expand=True)
            tb.configure(state="disabled")

            t = tb._textbox  # internal tk.Text for tags/search
            try:
                t.configure(wrap="word")
            except Exception:
                pass
            for name, bro in BROTHERS.items():
                t.tag_configure(f"color_{name}", foreground=bro.color)
            t.tag_configure("color_default", foreground=PALETTE["text"])
            t.tag_configure("color_error", foreground=PALETTE["danger"])
            t.tag_configure("color_dim", foreground=PALETTE["muted"])
            t.tag_configure("mono", font=("Consolas", 11))
            t.tag_configure("search_hit", underline=0)

            self._mode_textboxes[mode] = tb
            self._mode_tktexts[mode] = t
            self._mode_rendered[mode] = False

        # Default active mode (do NOT auto-render old chat on startup)
        try:
            self._suppress_mode_render = True
            self.mode_tabs.set(getattr(self, "active_mode", "Porch"))
        except Exception:
            pass
        finally:
            try:
                self._suppress_mode_render = False
            except Exception:
                pass
        self._apply_mode_context(getattr(self, "active_mode", "Porch"), render=False)

        # Attach GBCBS logger after UI is ready
        try:
            if getattr(self, "gbcbs", None) is not None:
                self.gbcbs.set_logger(self._ui_log)
                self._ui_log("🌐 GBCBS ready (local-first). Use /gbcbs to open the console.", dim=True, mono=True)
        except Exception:
            pass


        # Entry (Text widget so we can underline misspellings)
        self.entry_frame = ctk.CTkFrame(self, fg_color="transparent")
        self.entry_frame.grid(row=2, column=1, padx=18, pady=(0, 18), sticky="ew")
        self.entry_frame.grid_columnconfigure(0, weight=1)

        self.entry = ctk.CTkTextbox(
            self.entry_frame,
            height=74,
            fg_color=PALETTE["panel2"],
            text_color=PALETTE["text"],
            border_color="#1B274A",
            border_width=1,
        )
        self.entry.grid(row=0, column=0, sticky="ew", padx=(0, 10))

        # Placeholder label (CTkTextbox doesn't support placeholder_text)
        self._entry_placeholder = ctk.CTkLabel(
            self.entry_frame,
            text="Speak to the porch… (try: /help, /write, /job, /world on)  •  Shift+Enter = newline",
            text_color=PALETTE["muted"],
        )
        try:
            self._entry_placeholder.place(x=16, y=22)
        except Exception:
            pass

        # internal tk textbox
        self._entry_t = self.entry._textbox
        try:
            self._entry_t.configure(undo=True, maxundo=500, autoseparators=True)
            try:
                self._entry_t.configure(wrap="word")
            except Exception:
                pass
            self._entry_t.tag_configure("misspell", underline=1, foreground=PALETTE["danger"])
        except Exception:
            pass

        # Keybinds
        self.entry.bind("<Return>", self._on_input_return)
        self.entry.bind("<Up>", self._on_entry_up)
        self.entry.bind("<Down>", self._on_entry_down)
        self.entry.bind("<KeyRelease>", self._on_input_changed)
        self.entry.bind("<Button-3>", self._on_input_right_click)

        # Global binds
        try:
            self.bind_all("<Control-f>", lambda e: self._open_chat_search())
            self.bind_all("<Control-End>", lambda e: self._scroll_chat_to_end())
        except Exception:
            pass

        self.send_btn = ctk.CTkButton(
            self.entry_frame,
            text="Send",
            height=74,
            fg_color=PALETTE["accent"],
            text_color="#081018",
            command=self._send_message,
        )
        self.send_btn.grid(row=0, column=1, sticky="e")


        self._build_sidebar()


    # ---------- Settings / Profiles / Legacy ----------
    def _load_json(self, path: str, default):
        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    return json.load(f)
        except Exception:
            return default
        return default

    def _save_json(self, path: str, obj) -> None:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(obj, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def _load_settings(self) -> Dict:
        s = self._load_json(SETTINGS_FILE, {})
        # defaults
        s.setdefault("focus_mode", False)
        s.setdefault("font_size", 15)
        s.setdefault("auto_backup_daily", True)
        s.setdefault("last_backup_iso", "")
        s.setdefault("glyph_enabled", False)
        s.setdefault("rain_mode", False)
        s.setdefault("music_autoplay", False)
        s.setdefault("ui_show_history", False)
        s.setdefault("harmonius_steps_out", 96)
        s.setdefault("harmonius_epochs", 25)
        s.setdefault("harmonius_temperature", 1.0)
        s.setdefault("harmonius_last_midi", "")
        s.setdefault("harmonius_panel_collapsed", True)
        s.setdefault("chat_model", os.getenv("PORCH_CHAT_MODEL", CHAT_MODEL))

        s.setdefault("last_open_iso", "")
        # Ghost-in-the-Machine (Autonomous Reflection)
        s.setdefault("autonomous_reflection_enabled", True)
        s.setdefault("autonomous_reflection_interval_sec", 900)
        s.setdefault("autonomous_reflection_idle_sec", 180)
        s.setdefault("autonomous_reflection_board", "deep_thought")
        s.setdefault("autonomous_reflection_max_sources", 4)
        s.setdefault("autonomous_reflection_max_chars", 9000)

        # Body-Link (Telemetry → Haptics)
        s.setdefault("bodylink_enabled", False)
        s.setdefault("bodylink_poll_ms", 50)
        s.setdefault("bodylink_device", "gen_e_wrist")
        s.setdefault(
            "bodylink_map",
            {
                "collision": {"intensity": 0.25, "duration_ms": 28},
                "rain_drop": {"intensity": 0.12, "duration_ms": 18},
                "impact": {"intensity": 0.35, "duration_ms": 35},
            },
        )

        # Infinite Web (Scout)
        s.setdefault("scout_max_sources", 3)
        s.setdefault("scout_max_chars_per_source", 6000)
        s.setdefault("scout_save_dir", os.path.join(CREATED_DIR, "scout"))
        return s

    def _save_settings(self) -> None:
        self.settings["focus_mode"] = bool(getattr(self, "focus_mode", False))
        self.settings["font_size"] = int(getattr(self, "font_size", 15))
        self.settings["auto_backup_daily"] = bool(getattr(self, "auto_backup_daily", True))
        self.settings["glyph_enabled"] = bool(getattr(self, "glyph_enabled", False))
        self.settings["rain_mode"] = bool(getattr(self, "rain_mode", False))
        self.settings["music_autoplay"] = bool(getattr(self, "music_autoplay", False))
        self.settings["chat_model"] = str(getattr(self, "chat_model", CHAT_MODEL)).strip() or CHAT_MODEL
        self._save_json(SETTINGS_FILE, self.settings)


    # ---------- Model selection (Ollama) ----------
    def _list_ollama_models(self) -> List[str]:
        """Return installed local models from Ollama (/api/tags)."""
        host = os.getenv("OLLAMA_URL", OLLAMA_URL).rstrip("/")
        url = host + "/api/tags"
        try:
            if requests is not None:
                r = requests.get(url, timeout=2.5)
                r.raise_for_status()
                data = r.json() if r.text else {}
            else:
                import urllib.request
                req = urllib.request.Request(url, headers={"Accept": "application/json"})
                with urllib.request.urlopen(req, timeout=2.5) as resp:
                    raw = resp.read().decode("utf-8", errors="replace")
                data = json.loads(raw) if raw else {}
            models = [m.get("name", "").strip() for m in (data.get("models") or [])]
            models = [m for m in models if m]
            models = sorted(set(models), key=lambda s: s.lower())
            return models
        except Exception:
            return []

    def _apply_model_list(self, models: List[str], silent: bool = False) -> None:
        if not models:
            if not silent:
                self._ui_log("⚠️ Could not fetch models from Ollama. Is it running? (run: ollama serve)", dim=True)
            return

        cur = str(getattr(self, "chat_model", "")).strip() or CHAT_MODEL
        if cur not in models:
            models = [cur] + models

        self.available_models = models
        try:
            if hasattr(self, "model_menu"):
                self.model_menu.configure(values=models)
        except Exception:
            pass

        try:
            if hasattr(self, "model_var"):
                self.model_var.set(cur)
        except Exception:
            pass

        if not silent:
            self._ui_log(f"🧠 Local models: {len(models)}. Current: {cur}", dim=True)

    def _refresh_models_async(self, silent: bool = False) -> None:
        def work():
            models = self._list_ollama_models()
            try:
                self.after(0, lambda: self._apply_model_list(models, silent=silent))
            except Exception:
                pass
        threading.Thread(target=work, daemon=True).start()

    def _on_chat_model_selected(self, value: str) -> None:
        value = (value or "").strip()
        if not value:
            return
        self.chat_model = value
        try:
            self.settings["chat_model"] = self.chat_model
            self._save_settings()
        except Exception:
            pass
        self._ui_log(f"✅ Chat model set: {self.chat_model}", dim=True)


