    # ---------- Experiences / Studios ----------
    def _llm_quick(self, system: str, user: str, max_chars: int = 1800) -> str:
        """Small helper: tries local Ollama; always returns something."""
        try:
            msgs = [
                {"role": "system", "content": system},
                {"role": "user", "content": user},
            ]
            resp = ollama_chat(msgs, self.chat_model)
            out = (resp or {}).get("message", {}).get("content", "") or ""
            out = out.strip()
            if not out:
                return ""
            if len(out) > max_chars:
                out = out[: max_chars - 3].rstrip() + "..."
            return out
        except Exception:
            return ""

    def _read_textfile(self, path: str, default: str = "") -> str:
        try:
            if os.path.exists(path):
                return open(path, "r", encoding="utf-8", errors="ignore").read()
        except Exception:
            pass
        return default

    def _write_textfile(self, path: str, content: str) -> None:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                f.write(content)
        except Exception as e:
            self._ui_log(f"⚠️ Could not write file: {e}", error=True)

    def _append_textfile(self, path: str, content: str) -> None:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "a", encoding="utf-8") as f:
                f.write(content)
        except Exception as e:
            self._ui_log(f"⚠️ Could not append file: {e}", error=True)

