    # -----------------
    # Maverick's Maze
    # -----------------
    def _maze_default(self) -> Dict[str, Any]:
        return {
            "w": 10,
            "h": 10,
            "seed": int(time.time()) & 0xFFFFFFFF,
            "x": 0,
            "y": 0,
            "goal": [9, 9],
            "cells": {},
            "visited": [],
            "steps": 0,
            "start_ts": time.time(),
            "won": False,
            "opts": {
                "fog": True,
                "shifting": False,
                "moving_goal": False,
                "keys_lock": False,
                "cursed": False,
            },
            "keys_needed": 0,
            "keys_found": 0,
            "keys": [],
            "cursed_tiles": [],
            "curse": 0,
        }

    def _maze_save(self) -> None:
        try:
            os.makedirs(EXPERIENCES_DIR, exist_ok=True)
            with open(MAZE_STATE_FILE, "w", encoding="utf-8") as f:
                json.dump(self._maze_state, f, indent=2)
        except Exception:
            pass

    def _maze_load(self) -> Dict[str, Any]:
        try:
            if os.path.exists(MAZE_STATE_FILE):
                st = json.load(open(MAZE_STATE_FILE, "r", encoding="utf-8"))
                if isinstance(st, dict) and "w" in st and "h" in st and "cells" in st:
                    return st
        except Exception:
            pass
        return self._maze_default()

    def _maze_generate(self, w: int, h: int, seed: int, opts: Optional[Dict[str, bool]] = None) -> Dict[str, Any]:
        rng = random.Random(seed)
        N, E, S, W = 1, 2, 4, 8
        DX = {E: 1, W: -1, N: 0, S: 0}
        DY = {E: 0, W: 0, N: -1, S: 1}
        OPP = {E: W, W: E, N: S, S: N}

        cells = {(x, y): 0 for y in range(h) for x in range(w)}
        stack = [(0, 0)]
        visited = set([(0, 0)])

        def neighbors(cx, cy):
            dirs = [N, E, S, W]
            rng.shuffle(dirs)
            for d in dirs:
                nx, ny = cx + DX[d], cy + DY[d]
                if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in visited:
                    yield d, nx, ny

        while stack:
            cx, cy = stack[-1]
            found = False
            for d, nx, ny in neighbors(cx, cy):
                # carve
                cells[(cx, cy)] |= d
                cells[(nx, ny)] |= OPP[d]
                visited.add((nx, ny))
                stack.append((nx, ny))
                found = True
                break
            if not found:
                stack.pop()

                # Serialize cells to json-friendly mapping
        cellmap = {f"{x},{y}": cells[(x, y)] for y in range(h) for x in range(w)}

        # Options (variants)
        o = dict(opts or {})
        defaults = {"fog": True, "shifting": False, "moving_goal": False, "keys_lock": False, "cursed": False}
        for k, v in defaults.items():
            if k not in o:
                o[k] = v

        # Place keys / cursed tiles deterministically
        rng2 = random.Random(seed ^ 0xA5A5A5A5)
        all_cells = [(x, y) for y in range(h) for x in range(w)]
        all_cells_no_start_goal = [(x, y) for (x, y) in all_cells if (x, y) not in [(0, 0), (w - 1, h - 1)]]

        keys_needed = 0
        keys = []
        if bool(o.get("keys_lock")):
            keys_needed = 3 if (w * h) >= 36 else 2
            rng2.shuffle(all_cells_no_start_goal)
            keys = all_cells_no_start_goal[:keys_needed]

        cursed_tiles = []
        if bool(o.get("cursed")):
            rng2.shuffle(all_cells_no_start_goal)
            cursed_tiles = all_cells_no_start_goal[: max(1, min(5, (w * h) // 20))]

        st = {
            "w": w,
            "h": h,
            "seed": seed,
            "x": 0,
            "y": 0,
            "goal": [w - 1, h - 1],
            "cells": cellmap,
            "visited": [[0, 0]],
            "steps": 0,
            "start_ts": time.time(),
            "won": False,
            "opts": o,
            "keys_needed": keys_needed,
            "keys_found": 0,
            "keys": [[x, y] for (x, y) in keys],
            "cursed_tiles": [[x, y] for (x, y) in cursed_tiles],
            "curse": 0,
        }
        return st

    def _maze_render(self, st: Dict[str, Any]) -> str:
        w, h = int(st.get("w", 10)), int(st.get("h", 10))
        px, py = int(st.get("x", 0)), int(st.get("y", 0))
        gx, gy = (st.get("goal") or [w - 1, h - 1])[:2]
        gx, gy = int(gx), int(gy)

        # char grid (2h+1)x(2w+1)
        H, Wd = 2 * h + 1, 2 * w + 1
        g = [["#" for _ in range(Wd)] for __ in range(H)]
        for y in range(h):
            for x in range(w):
                g[2 * y + 1][2 * x + 1] = " "
                mask = int((st.get("cells") or {}).get(f"{x},{y}", 0))
                # open corridors
                if mask & 1:  # N
                    g[2 * y][2 * x + 1] = " "
                if mask & 2:  # E
                    g[2 * y + 1][2 * x + 2] = " "
                if mask & 4:  # S
                    g[2 * y + 2][2 * x + 1] = " "
                if mask & 8:  # W
                    g[2 * y + 1][2 * x] = " "

        g[2 * py + 1][2 * px + 1] = "P"
        g[2 * gy + 1][2 * gx + 1] = "G"

        lines = ["".join(row) for row in g]
        return "\n".join(lines)

    def _maze_can_move(self, st: Dict[str, Any], dx: int, dy: int) -> bool:
        w, h = int(st.get("w", 10)), int(st.get("h", 10))
        x, y = int(st.get("x", 0)), int(st.get("y", 0))
        nx, ny = x + dx, y + dy
        if not (0 <= nx < w and 0 <= ny < h):
            return False
        mask = int((st.get("cells") or {}).get(f"{x},{y}", 0))
        if dx == 1:
            return bool(mask & 2)
        if dx == -1:
            return bool(mask & 8)
        if dy == -1:
            return bool(mask & 1)
        if dy == 1:
            return bool(mask & 4)
        return False

    def _maze_move(self, st: Dict[str, Any], dx: int, dy: int) -> None:
        if not self._maze_can_move(st, dx, dy):
            return

        st["x"] = int(st.get("x", 0)) + dx
        st["y"] = int(st.get("y", 0)) + dy

        # steps / visited
        st["steps"] = int(st.get("steps", 0)) + 1
        vx, vy = int(st.get("x", 0)), int(st.get("y", 0))
        visited = st.get("visited") or []
        if [vx, vy] not in visited:
            visited.append([vx, vy])
        st["visited"] = visited

        # Keys
        keys = st.get("keys") or []
        if [vx, vy] in keys:
            keys.remove([vx, vy])
            st["keys"] = keys
            st["keys_found"] = int(st.get("keys_found", 0)) + 1
            self._ui_log(f"🗝️ Key found! ({st['keys_found']}/{int(st.get('keys_needed', 0) or 0)})", dim=True)
            self._meta_grant_items({"Maze Key": 1})

        # Cursed tiles
        if [vx, vy] in (st.get("cursed_tiles") or []):
            st["curse"] = int(st.get("curse", 0)) + 1
            self._ui_log(f"🕯️ A cursed tile chills the air… Curse +1 (now {st['curse']}).", dim=True)
            if st["curse"] >= 3:
                st["curse"] = 0
                st["x"], st["y"] = 0, 0
                self._ui_log("💀 The curse snaps you back to the start!", dim=True)

        # Moving goal (every 7 steps)
        opts = st.get("opts") or {}
        if bool(opts.get("moving_goal")) and st["steps"] % 7 == 0:
            rng = random.Random(int(st.get("seed", 0)) ^ st["steps"])
            w, h = int(st.get("w", 10)), int(st.get("h", 10))
            gx, gy = rng.randrange(w), rng.randrange(h)
            st["goal"] = [gx, gy]
            self._ui_log(f"🎯 The goal shifts to ({gx},{gy}).", dim=True)

        # Shifting walls (every 9 steps)
        if bool(opts.get("shifting")) and st["steps"] % 9 == 0:
            w, h = int(st.get("w", 10)), int(st.get("h", 10))
            new_seed = (int(st.get("seed", 0)) + st["steps"] * 1337) & 0xFFFFFFFF
            new_st = self._maze_generate(w, h, new_seed, opts=opts)
            new_st["x"], new_st["y"] = st["x"], st["y"]
            new_st["goal"] = st.get("goal", [w - 1, h - 1])
            new_st["visited"] = st.get("visited", [[0, 0]])
            new_st["steps"] = st["steps"]
            new_st["start_ts"] = st.get("start_ts", time.time())
            new_st["keys_needed"] = st.get("keys_needed", 0)
            new_st["keys_found"] = st.get("keys_found", 0)
            new_st["keys"] = st.get("keys", [])
            new_st["cursed_tiles"] = st.get("cursed_tiles", [])
            new_st["curse"] = st.get("curse", 0)
            new_st["won"] = st.get("won", False)
            st.clear()
            st.update(new_st)
            self._ui_log("🌀 The maze shifts around you…", dim=True)

        # Encounters (light chance)
        if random.random() < 0.15:
            self._open_encounter_window(context="Maverick's Maze")

    def _open_mavericks_maze(self) -> None:
        self._maze_state = getattr(self, "_maze_state", None) or self._maze_load()
        try:
            self._meta_record("maze_open")
        except Exception:
            pass

        win = ctk.CTkToplevel(self)
        win.title("🧩 Maverick's Maze")
        win.geometry("980x720")
        try:
            win.grab_set()
        except Exception:
            pass

        header = ctk.CTkFrame(win, fg_color="transparent")
        header.pack(fill="x", padx=14, pady=10)
        ctk.CTkLabel(header, text="Maverick's Maze", font=ctk.CTkFont(size=18, weight="bold"), text_color=PALETTE["text"]).pack(anchor="w")
        ctk.CTkLabel(
            header, text="A dynamic, ever-changing puzzle. Reach the goal (G). You are P.", text_color=PALETTE["muted"]
        ).pack(anchor="w", pady=(4, 0))

        body = ctk.CTkFrame(win, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=14, pady=(0, 14))

        left = ctk.CTkFrame(body, fg_color="transparent")
        left.pack(side="left", fill="both", expand=True, padx=(0, 10))

        self._maze_text = ctk.CTkTextbox(left, wrap="none", font=("Consolas", 12))
        self._maze_text.pack(fill="both", expand=True)

        right = ctk.CTkFrame(body, fg_color="transparent", width=220)
        right.pack(side="right", fill="y")

        # Variants (saved into maze state)
        variants = ctk.CTkFrame(right, fg_color="transparent")
        variants.pack(fill="x", pady=(0, 10))
        ctk.CTkLabel(variants, text="Variants", text_color=PALETTE["muted"]).pack(anchor="w", pady=(0, 6))

        opts = self._maze_state.get("opts") or {}
        def _opt(name: str, default: bool) -> bool:
            return bool(opts.get(name, default))

        var_fog = ctk.BooleanVar(value=_opt("fog", True))
        var_shift = ctk.BooleanVar(value=_opt("shifting", False))
        var_goal = ctk.BooleanVar(value=_opt("moving_goal", False))
        var_keys = ctk.BooleanVar(value=_opt("keys_lock", False))
        var_curse = ctk.BooleanVar(value=_opt("cursed", False))

        def apply_variants():
            self._maze_state["opts"] = {
                "fog": bool(var_fog.get()),
                "shifting": bool(var_shift.get()),
                "moving_goal": bool(var_goal.get()),
                "keys_lock": bool(var_keys.get()),
                "cursed": bool(var_curse.get()),
            }
            self._maze_save()

        for label, var in [
            ("Fog of War", var_fog),
            ("Shifting Walls", var_shift),
            ("Moving Goal", var_goal),
            ("Keys Lock Goal", var_keys),
            ("Cursed Tiles", var_curse),
        ]:
            ctk.CTkCheckBox(variants, text=label, variable=var, command=apply_variants, text_color=PALETTE["text"]).pack(anchor="w", pady=2)

        ctk.CTkLabel(variants, text="(Variant changes apply on New Maze)", text_color=PALETTE["muted"]).pack(anchor="w", pady=(6, 0))


        def refresh():
            s = self._maze_render(self._maze_state)
            self._maze_text.configure(state="normal")
            self._maze_text.delete("1.0", "end")
            self._maze_text.insert("1.0", s)
            self._maze_text.configure(state="disabled")
            # win?
            gx, gy = (self._maze_state.get("goal") or [0, 0])[:2]
            if int(self._maze_state.get("x", 0)) == int(gx) and int(self._maze_state.get("y", 0)) == int(gy):
                # Goal logic (supports "Keys" variant)
                keys_needed = int(self._maze_state.get("keys_needed", 0) or 0)
                keys_found = int(self._maze_state.get("keys_found", 0) or 0)
                if keys_needed > 0 and keys_found < keys_needed:
                    self._ui_log(f"🔒 Goal is locked. Keys: {keys_found}/{keys_needed}.", dim=True)
                else:
                    if not self._maze_state.get("won"):
                        self._maze_state["won"] = True
                        self._ui_log("🏁 You reached the goal in Maverick's Maze!", dim=True)
                        self._meta_record("maze_win")
                        self._meta_grant_items({"Maze Sigil": 1, "Rift Shard": 1})
                        self._meta_add_rep("Prism Guild", 3)
                    else:
                        self._ui_log("🏁 Goal reached (already cleared).", dim=True)
            self._maze_save()

        def new_maze():
            w = int(self._maze_state.get("w", 10))
            h = int(self._maze_state.get("h", 10))
            seed = int(time.time()) & 0xFFFFFFFF
            self._maze_state = self._maze_generate(w, h, seed, opts=self._maze_state.get('opts'))
            refresh()

        def nudge(dx, dy):
            self._maze_move(self._maze_state, dx, dy)
            refresh()

        def hint():
            gx, gy = (self._maze_state.get("goal") or [0, 0])[:2]
            px, py = int(self._maze_state.get("x", 0)), int(self._maze_state.get("y", 0))
            # simple greedy hint
            hx, hy = ("→" if gx > px else "←" if gx < px else "•"), ("↓" if gy > py else "↑" if gy < py else "•")
            self._ui_log(f"🧠 Maze hint: {hx} {hy} (greedy)", dim=True)

        ctk.CTkButton(right, text="🆕 New Maze", command=new_maze, height=40, fg_color="#1B274A").pack(fill="x", pady=(0, 8))
        ctk.CTkButton(right, text="💡 Hint", command=hint, height=36, fg_color="#1B274A").pack(fill="x", pady=6)

        nav = ctk.CTkFrame(right, fg_color="transparent")
        nav.pack(fill="x", pady=10)
        ctk.CTkButton(nav, text="↑", command=lambda: nudge(0, -1), width=60, height=38, fg_color="#1B274A").grid(row=0, column=1, padx=4, pady=4)
        ctk.CTkButton(nav, text="←", command=lambda: nudge(-1, 0), width=60, height=38, fg_color="#1B274A").grid(row=1, column=0, padx=4, pady=4)
        ctk.CTkButton(nav, text="→", command=lambda: nudge(1, 0), width=60, height=38, fg_color="#1B274A").grid(row=1, column=2, padx=4, pady=4)
        ctk.CTkButton(nav, text="↓", command=lambda: nudge(0, 1), width=60, height=38, fg_color="#1B274A").grid(row=2, column=1, padx=4, pady=4)

        ctk.CTkLabel(right, text="Tip: /maze", text_color=PALETTE["muted"]).pack(anchor="w", pady=(10, 0))
        refresh()

    # -----------------
    # Wild Ride
    # -----------------
    def _wild_default(self) -> Dict[str, Any]:
        return {"seed": int(time.time()) & 0xFFFFFFFF, "step": 0, "log": []}

    def _wild_load(self) -> Dict[str, Any]:
        try:
            p = os.path.join(EXPERIENCES_DIR, "wild_ride_state.json")
            if os.path.exists(p):
                st = json.load(open(p, "r", encoding="utf-8"))
                if isinstance(st, dict) and "seed" in st:
                    return st
        except Exception:
            pass
        return self._wild_default()

    def _wild_save(self) -> None:
        try:
            os.makedirs(EXPERIENCES_DIR, exist_ok=True)
            p = os.path.join(EXPERIENCES_DIR, "wild_ride_state.json")
            json.dump(self._wild_state, open(p, "w", encoding="utf-8"), indent=2)
        except Exception:
            pass

    def _wild_next_beat(self, st: Dict[str, Any]) -> str:
        rng = random.Random(int(st.get("seed", 0)) + int(st.get("step", 0)) * 1337)
        st["step"] = int(st.get("step", 0)) + 1
        locs = ["crystal canyon", "nebula bridge", "laughing dunes", "gravity orchard", "mirror bay", "ion cathedral", "silent arcade"]
        vibes = ["neon", "dreamy", "mythic", "wild", "electric", "cozy", "cosmic"]
        twists = [
            "a door appears where there was none",
            "time loops for exactly 9 seconds",
            "music syncs to your heartbeat",
            "a friendly alien offers a trade",
            "the floor becomes liquid light",
            "a riddle is carved into the air",
            "you find a forgotten relic from your own past",
        ]
        beat = f"Beat {st['step']}: In the {rng.choice(vibes)} {rng.choice(locs)}, {rng.choice(twists)}."
        return beat



    # ---------------------------
    # Dungeon Master (AI campaign)
    # Inspired by AI-Dungeon-Master style: dynamic story + inventory/quests/stats, and
    # a modular RPG engine pattern (stacked states, save/load).
    # ---------------------------

    def _dm_default(self) -> Dict[str, Any]:
        return {
            "version": 1,
            "campaign_name": "New Campaign",
            "setting": "Fantasy frontier at the edge of a forgotten empire.",
            "tone": "mystery, wonder, heroism",
            "safety": "PG-13 (no gore, no sexual content, no hate)",
            "model": getattr(self, "chat_model", CHAT_MODEL),
            "temperature": 0.7,
            "turn": 0,
            "location": "The Crossroads Inn",
            "state_stack": ["exploration"],
            "player": {
                "name": "Mikey",
                "race": "Human",
                "class": "Adventurer",
                "background": "Wanderer",
                "level": 1,
                "hp": 10,
                "hp_max": 10,
                "ac": 12,
                "stats": {"str": 10, "dex": 10, "con": 10, "int": 10, "wis": 10, "cha": 10},
                "skills": {"athletics": 0, "stealth": 0, "perception": 0, "persuasion": 0, "arcana": 0, "survival": 0},
                "inventory": ["Traveler's clothes", "Bedroll", "Waterskin", "10 gp"],
                "notes": "",
            },
            "quests": [
                {"id": "q_main_1", "title": "Find the Missing Lantern-Bearer", "type": "main", "status": "open"},
                {"id": "q_side_1", "title": "Help the Innkeeper with the Cellar", "type": "side", "status": "open"},
                {"id": "q_side_2", "title": "Deliver a Sealed Letter to the Watch", "type": "side", "status": "open"},
            ],
            "npcs": [],
            "flags": {},
            "log": [],  # list of {"role": "player|dm|system", "content": "...", "ts": "..."}
            "last_dm": "",
            "dmhub": {
                "version": 1,
                "active_session": "main",
                "sessions": {
                    "main": {
                        "id": "main",
                        "name": "Sovereign DM Hub",
                        "created_ts": "1970-01-01T00:00:00Z",
                        "participants": ["You"],
                        "messages": [],
                    }
                },
                "command_history": [],
            },
        }

    def _dm_load(self) -> Dict[str, Any]:
        # Robust JSON loader: uses Porch helper if present, otherwise falls back locally.
        loader = globals().get("_porch__load_json")
        if not callable(loader):
            def loader(path: str, default):
                try:
                    if os.path.exists(path):
                        with open(path, "r", encoding="utf-8") as f:
                            return json.load(f)
                except Exception:
                    pass
                return default

        st = loader(DUNGEON_MASTER_STATE_FILE, default={})
        if not isinstance(st, dict) or not st:
            st = self._dm_default()
        # minimal migrations
        st.setdefault("version", 1)
        st.setdefault("state_stack", ["exploration"])
        st.setdefault("player", {})
        st["player"].setdefault("inventory", [])
        st.setdefault("quests", [])
        st.setdefault("log", [])
        st.setdefault("flags", {})
        st.setdefault("model", getattr(self, "chat_model", CHAT_MODEL))
        st.setdefault("temperature", 0.7)
        st.setdefault("turn", 0)
        st.setdefault("location", "The Crossroads Inn")
        # Sovereign DM Hub init
        try:
            st.setdefault("dmhub", {})
            self._dmhub_init(st)
        except Exception:
            pass

        return st

    def _dm_save(self) -> None:
        try:
            os.makedirs(EXPERIENCES_DIR, exist_ok=True)
        except Exception:
            pass

        saver = globals().get("_porch__save_json")
        if not callable(saver):
            def saver(path: str, obj) -> None:
                try:
                    os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
                    with open(path, "w", encoding="utf-8") as f:
                        json.dump(obj, f, ensure_ascii=False, indent=2)
                except Exception:
                    pass

        try:
            saver(DUNGEON_MASTER_STATE_FILE, getattr(self, "_dm_state", None) or {})
        except Exception:
            pass

    # ---------------------------
    # Sovereign DM Hub (DMMessage + DMSession)
    # ---------------------------
    def _dm_now(self) -> str:
        try:
            utc = getattr(datetime, "UTC", datetime.timezone.utc)
            return datetime.datetime.now(utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")
        except Exception:
            try:
                return str(time.time())
            except Exception:
                return "0"

    def _dm_msg_id(self) -> str:
        try:
            return f"dm_{int(time.time()*1000)}_{int(random.random()*1_000_000):06d}"
        except Exception:
            return f"dm_{int(time.time())}"

    def _dm_fnv64(self, data: bytes) -> int:
        # Use Native Metal if available; otherwise pure Python FNV-1a 64.
        try:
            router = getattr(self, "_native_router", None)
            if router and hasattr(router, "fnv1a64"):
                return int(router.fnv1a64(data))
        except Exception:
            pass
        try:
            b = data if isinstance(data, (bytes, bytearray)) else bytes(str(data), "utf-8", errors="ignore")
        except Exception:
            b = bytes(str(data), "utf-8", errors="ignore")
        h = 1469598103934665603
        prime = 1099511628211
        for by in b:
            h ^= by
            h = (h * prime) & 0xFFFFFFFFFFFFFFFF
        return int(h)

    def _dmhub_init(self, st: Dict[str, Any]) -> None:
        hub = st.get("dmhub")
        if not isinstance(hub, dict):
            hub = {}
            st["dmhub"] = hub

        hub.setdefault("version", 1)
        hub.setdefault("command_history", [])
        hub.setdefault("sessions", {})
        hub.setdefault("active_session", "main")

        sessions = hub.get("sessions")
        if not isinstance(sessions, dict):
            sessions = {}
            hub["sessions"] = sessions

        sid = (hub.get("active_session") or "main").strip() or "main"
        hub["active_session"] = sid

        if sid not in sessions or not isinstance(sessions.get(sid), dict):
            sessions[sid] = {
                "id": sid,
                "name": "Sovereign DM Hub",
                "created_ts": self._dm_now(),
                "participants": ["You"],
                "messages": [],
            }

        # Normalize all sessions
        for _k, sess in list(sessions.items()):
            if not isinstance(sess, dict):
                sessions[_k] = {"id": _k, "name": str(_k), "created_ts": self._dm_now(), "participants": ["You"], "messages": []}
                continue
            sess.setdefault("id", _k)
            sess.setdefault("name", "Sovereign DM Hub")
            sess.setdefault("created_ts", self._dm_now())
            sess.setdefault("participants", ["You"])
            sess.setdefault("messages", [])
            if not isinstance(sess.get("participants"), list):
                sess["participants"] = ["You"]
            if not isinstance(sess.get("messages"), list):
                sess["messages"] = []

        # Trim command history if it explodes
        try:
            hist = hub.get("command_history")
            if isinstance(hist, list) and len(hist) > 2000:
                hub["command_history"] = hist[-2000:]
        except Exception:
            pass

    def _dmhub_active_session(self) -> Dict[str, Any]:
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            st = self._dm_load()
            self._dm_state = st
        self._dmhub_init(st)
        hub = st.get("dmhub", {})
        sid = hub.get("active_session", "main")
        sess = (hub.get("sessions") or {}).get(sid)
        if not isinstance(sess, dict):
            sess = {"id": sid, "name": "Sovereign DM Hub", "created_ts": self._dm_now(), "participants": ["You"], "messages": []}
            hub.setdefault("sessions", {})[sid] = sess
        return sess

    def _dmhub_sign_payload(self, payload_obj: Dict[str, Any]) -> int:
        try:
            blob = json.dumps(payload_obj, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
        except Exception:
            blob = bytes(str(payload_obj), "utf-8", errors="ignore")
        return int(self._dm_fnv64(blob))

    def _dmhub_make_message(self, sender: str, recipient: str, text: str, meta: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        msg = {
            "id": self._dm_msg_id(),
            "sender": (sender or "Unknown").strip() or "Unknown",
            "recipient": (recipient or "Unknown").strip() or "Unknown",
            "ts": self._dm_now(),
            "text": text or "",
            "meta": meta if isinstance(meta, dict) else {},
        }
        # ML-Quadrat-inspired audit hook (lightweight): tag potentially high-stakes content.
        try:
            mgr = getattr(self, "_ai_health", None)
            if mgr is not None and hasattr(mgr, "audit_text"):
                domain = "general"
                try:
                    domain = (msg.get("meta") or {}).get("domain") or "general"
                except Exception:
                    domain = "general"
                audit = mgr.audit_text(msg.get("text",""), domain=domain)
                if isinstance(audit, dict) and audit.get("flagged"):
                    msg["meta"]["ml_quadrat_audit"] = audit
        except Exception:
            pass
        sig = self._dmhub_sign_payload({
            "sender": msg["sender"],
            "recipient": msg["recipient"],
            "ts": msg["ts"],
            "text": msg["text"],
            "meta": msg["meta"],
        })
        msg["sig_fnv64"] = int(sig)
        return msg

    def _dmhub_verify_message(self, msg: Dict[str, Any]) -> bool:
        if not isinstance(msg, dict):
            return False
        try:
            expected = self._dmhub_sign_payload({
                "sender": msg.get("sender", ""),
                "recipient": msg.get("recipient", ""),
                "ts": msg.get("ts", ""),
                "text": msg.get("text", ""),
                "meta": msg.get("meta", {}) if isinstance(msg.get("meta"), dict) else {},
            })
            return int(expected) == int(msg.get("sig_fnv64", -1))
        except Exception:
            return False

    def _dmhub_log_command(self, cmd_text: str, sender: str = "You", meta: Optional[Dict[str, Any]] = None) -> None:
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            st = self._dm_load()
            self._dm_state = st
        self._dmhub_init(st)
        hub = st.get("dmhub", {})
        hist = hub.get("command_history")
        if not isinstance(hist, list):
            hist = []
            hub["command_history"] = hist

        rec = {
            "id": self._dm_msg_id(),
            "ts": self._dm_now(),
            "sender": (sender or "Unknown").strip() or "Unknown",
            "cmd": cmd_text or "",
            "meta": meta if isinstance(meta, dict) else {},
        }
        rec["sig_fnv64"] = int(self._dmhub_sign_payload(rec))
        hist.append(rec)
        if len(hist) > 2000:
            hub["command_history"] = hist[-2000:]
        try:
            self._dm_save()
        except Exception:
            pass

    def _dmhub_send(self, recipient: str, text: str, sender: str = "You", meta: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        sess = self._dmhub_active_session()
        msg = self._dmhub_make_message(sender=sender, recipient=recipient, text=text, meta=meta)
        try:
            sess["messages"].append(msg)
            # trim session messages for sanity
            if len(sess["messages"]) > 5000:
                sess["messages"] = sess["messages"][-5000:]
        except Exception:
            pass

        # Persist
        try:
            self._dm_save()
        except Exception:
            pass

        # Notify assistant task list (Brother-mesh hook)
        try:
            if hasattr(self, "assistant_tasks") and isinstance(self.assistant_tasks, list):
                self.assistant_tasks.append({
                    "ts": msg.get("ts"),
                    "type": "dm",
                    "from": msg.get("sender"),
                    "to": msg.get("recipient"),
                    "text": msg.get("text"),
                    "sig_fnv64": msg.get("sig_fnv64"),
                    "done": False,
                })
                if hasattr(self, "_save_assistant_tasks"):
                    self._save_assistant_tasks()
        except Exception:
            pass

        # Multimodal signal bridge (Haptic Event Bus)
        try:
            if getattr(self, "_porch_haptics_on", False) and getattr(self, "_porch_haptics", None):
                self._porch_haptics.emit("dm", meta={
                    "src": "dmhub",
                    "from": msg.get("sender"),
                    "to": msg.get("recipient"),
                    "sig_fnv64": msg.get("sig_fnv64"),
                })
        except Exception:
            pass

        return msg

    def _dmhub_inbox(self, recipient: str = "You", limit: int = 20) -> List[Dict[str, Any]]:
        sess = self._dmhub_active_session()
        msgs = sess.get("messages", [])
        if not isinstance(msgs, list):
            return []
        r = (recipient or "You").strip() or "You"
        out = [m for m in msgs if isinstance(m, dict) and m.get("recipient") == r]
        return out[-max(1, int(limit)):]

    def _dmhub_history(self, limit: int = 25) -> List[Dict[str, Any]]:
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            st = self._dm_load()
            self._dm_state = st
        self._dmhub_init(st)
        hub = st.get("dmhub", {})
        hist = hub.get("command_history", [])
        if not isinstance(hist, list):
            return []
        return hist[-max(1, int(limit)):]

    def _dm_summary(self) -> str:
        st = getattr(self, "_dm_state", None) or self._dm_load()
        p = st.get("player", {}) if isinstance(st, dict) else {}
        q = st.get("quests", []) if isinstance(st, dict) else []
        open_main = [x for x in q if isinstance(x, dict) and x.get("type") == "main" and x.get("status") != "done"]
        open_side = [x for x in q if isinstance(x, dict) and x.get("type") == "side" and x.get("status") != "done"]
        return (
            f"🎲 Dungeon Master — {st.get('campaign_name','(unnamed)')}\n"
            f"Location: {st.get('location','?')}\n"
            f"Player: {p.get('name','?')} (Lv {p.get('level',1)} {p.get('race','?')} {p.get('class','?')}) "
            f"HP {p.get('hp','?')}/{p.get('hp_max','?')} AC {p.get('ac','?')}\n"
            f"Quests: {len(open_main)} main open, {len(open_side)} side open\n"
        )

    def _dm_log_add(self, role: str, content: str) -> None:
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            return
        st.setdefault("log", [])
        st["log"].append({"role": role, "content": content, "ts": _now_iso()})
        if len(st["log"]) > 2000:
            st["log"] = st["log"][-1500:]

    def _dm_state_text(self) -> str:
        st = getattr(self, "_dm_state", None) or {}
        p = st.get("player", {}) if isinstance(st, dict) else {}
        inv = p.get("inventory", []) if isinstance(p, dict) else []
        q = st.get("quests", []) if isinstance(st, dict) else []
        stack = st.get("state_stack", []) if isinstance(st, dict) else []

        def _fmt_quests(kind: str) -> str:
            out = []
            for it in q:
                if not isinstance(it, dict):
                    continue
                if it.get("type") != kind:
                    continue
                out.append(f"- [{it.get('status','open')}] {it.get('title','')}")
            return "\n".join(out) if out else "(none)"

        parts = []
        parts.append(f"Campaign: {st.get('campaign_name','')}")
        parts.append(f"Setting: {st.get('setting','')}")
        parts.append(f"Tone: {st.get('tone','')}")
        parts.append(f"Safety: {st.get('safety','')}")
        parts.append(f"Turn: {st.get('turn',0)}")
        parts.append(f"ModeStack: {' > '.join([str(x) for x in stack])}")
        parts.append(f"Location: {st.get('location','')}")
        parts.append("")
        parts.append("PLAYER")
        parts.append(f"Name: {p.get('name','')}  Race: {p.get('race','')}  Class: {p.get('class','')}  Background: {p.get('background','')}")
        parts.append(f"Level: {p.get('level',1)}  HP: {p.get('hp',0)}/{p.get('hp_max',0)}  AC: {p.get('ac',0)}")
        parts.append(f"Stats: {p.get('stats',{})}")
        parts.append(f"Skills: {p.get('skills',{})}")
        parts.append("")
        parts.append("INVENTORY")
        if isinstance(inv, list) and inv:
            parts.extend([f"- {x}" for x in inv])
        else:
            parts.append("(empty)")
        parts.append("")
        parts.append("QUESTS — MAIN")
        parts.append(_fmt_quests("main"))
        parts.append("")
        parts.append("QUESTS — SIDE")
        parts.append(_fmt_quests("side"))
        return "\n".join(parts)

    def _dm_apply_update(self, upd: Dict[str, Any]) -> None:
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict) or not isinstance(upd, dict):
            return
        st["turn"] = int(st.get("turn", 0)) + 1

        if isinstance(upd.get("location"), str) and upd.get("location").strip():
            st["location"] = upd["location"].strip()

        if isinstance(upd.get("push_state"), str) and upd.get("push_state").strip():
            st.setdefault("state_stack", [])
            st["state_stack"].append(upd["push_state"].strip())
        if upd.get("pop_state"):
            try:
                st.setdefault("state_stack", [])
                if st["state_stack"]:
                    st["state_stack"].pop()
            except Exception:
                pass

        if isinstance(upd.get("flags"), dict):
            st.setdefault("flags", {})
            for k, v in upd["flags"].items():
                st["flags"][str(k)] = v

        p = st.get("player", {})
        if not isinstance(p, dict):
            p = {}
            st["player"] = p

        try:
            hp_delta = int(upd.get("hp_delta", 0))
        except Exception:
            hp_delta = 0
        if hp_delta:
            try:
                p["hp"] = int(p.get("hp", 0)) + hp_delta
                p["hp_max"] = int(p.get("hp_max", p.get("hp", 0)))
                p["hp"] = max(0, min(int(p["hp"]), int(p["hp_max"])))
            except Exception:
                pass

        inv = p.get("inventory", [])
        if not isinstance(inv, list):
            inv = []
        add_items = upd.get("add_items", [])
        rem_items = upd.get("remove_items", [])
        if isinstance(add_items, list):
            for it in add_items:
                s = str(it).strip()
                if s and s not in inv:
                    inv.append(s)
        if isinstance(rem_items, list):
            for it in rem_items:
                s = str(it).strip()
                if s in inv:
                    inv.remove(s)
        p["inventory"] = inv

        if isinstance(upd.get("quest_updates"), list):
            for q_upd in upd["quest_updates"]:
                if not isinstance(q_upd, dict):
                    continue
                qid = str(q_upd.get("id", "")).strip()
                title = str(q_upd.get("title", "")).strip()
                status = str(q_upd.get("status", "")).strip() or "open"
                qtype = str(q_upd.get("type", "")).strip() or "side"
                if not qid:
                    qid = "q_" + hashlib.sha1((title or status).encode("utf-8")).hexdigest()[:8]
                found = False
                for qq in st.get("quests", []):
                    if isinstance(qq, dict) and qq.get("id") == qid:
                        qq["status"] = status
                        if title:
                            qq["title"] = title
                        if qtype:
                            qq["type"] = qtype
                        found = True
                        break
                if not found:
                    st.setdefault("quests", []).append({"id": qid, "title": title or qid, "type": qtype, "status": status})

    def _dm_extract_json_update(self, text_out: str) -> Tuple[str, Dict[str, Any]]:
        raw = (text_out or "").strip()
        if not raw:
            return "", {}
        upd: Dict[str, Any] = {}
        try:
            m = re.search(r"```json\s*(\{.*?\})\s*```", raw, flags=re.S | re.I)
            if not m:
                m = re.search(r"(\{\s*\"update\"\s*:\s*\{.*?\}\s*\})", raw, flags=re.S)
            if not m:
                m = re.search(r"(\{.*\})\s*$", raw, flags=re.S)
            if m:
                obj = json.loads(m.group(1))
                if isinstance(obj, dict) and isinstance(obj.get("update"), dict):
                    upd = obj["update"]
                elif isinstance(obj, dict):
                    upd = obj.get("update") if isinstance(obj.get("update"), dict) else obj
                raw = raw[: m.start()].rstrip()
        except Exception:
            upd = {}
        return raw, upd

    def _dm_llm(self, action: str, roll_info: str = "") -> str:
        st = getattr(self, "_dm_state", None) or self._dm_load()
        p = st.get("player", {})
        lore_txt = ""
        try:
            q = f"{st.get('setting','')} {st.get('location','')} {action}"
            chunks = self.rag.retrieve("Ori", q, k=6, include_ori=True)
            if chunks:
                lore_txt = "\n\n".join([f"- {c.path}: {c.text.strip()}"[:1200] for c in chunks])
        except Exception:
            lore_txt = ""

        log = st.get("log", []) if isinstance(st, dict) else []
        tail = log[-14:] if isinstance(log, list) else []

        sys = (
            "You are a tabletop RPG Dungeon Master inside a desktop app. "
            "Run a single-player, choice-driven fantasy adventure. "
            "Keep content PG-13: no gore, no sexual content, no hate. "
            "Be vivid but concise. Track inventory, quests, HP, and location. "
            "Use the player's sheet and the mode stack (exploration/combat/dialogue/inventory). "
            "If combat happens, keep it abstract and non-graphic.\n\n"
            "OUTPUT FORMAT:\n"
            "1) Narrative (2-8 short paragraphs).\n"
            "2) End with three options labeled A), B), C) as actionable next moves.\n"
            "3) Then include a JSON block in a ```json fence with this structure:\n"
            "{\"update\": {\"location\": \"...\", \"hp_delta\": 0, \"add_items\": [], \"remove_items\": [], \"quest_updates\": [], \"push_state\": \"\", \"pop_state\": false, \"flags\": {}}}\n"
            "Only include keys you are changing. Use empty/zero if nothing changes.\n"
            "Do NOT include any other JSON outside the fenced block."
        )

        context = (
            f"CAMPAIGN_NAME: {st.get('campaign_name','')}\n"
            f"SETTING: {st.get('setting','')}\n"
            f"TONE: {st.get('tone','')}\n"
            f"LOCATION: {st.get('location','')}\n"
            f"STATE_STACK: {st.get('state_stack',[])}\n"
            f"PLAYER: {p}\n"
            f"QUESTS: {st.get('quests',[])}\n"
            + (f"RECENT_ROLL: {roll_info}\n" if roll_info else "")
            + (f"LOCAL_LORE:\n{lore_txt}\n" if lore_txt else "")
        )

        msgs: List[Dict[str, str]] = [{"role": "system", "content": sys}]
        msgs.append({"role": "user", "content": context})

        for it in tail:
            if not isinstance(it, dict):
                continue
            r = it.get("role", "player")
            c = it.get("content", "")
            if r == "dm":
                msgs.append({"role": "assistant", "content": c})
            else:
                msgs.append({"role": "user", "content": c})

        msgs.append({"role": "user", "content": f"PLAYER_ACTION: {action.strip()}"} )

        try:
            opts = {"temperature": float(st.get("temperature", 0.7))}
        except Exception:
            opts = {"temperature": 0.7}
        try:
            resp = ollama_chat(msgs, model=str(st.get("model") or getattr(self, "chat_model", CHAT_MODEL)), options=opts)
            out = (resp or {}).get("message", {}).get("content", "") or ""
            return out.strip()
        except Exception:
            return ""

    def _dm_do_action(self, action: str, roll_info: str = "") -> str:
        action = (action or "").strip()
        if not action:
            return ""
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            st = self._dm_load()
            self._dm_state = st

        self._dm_log_add("player", action)

        out = self._dm_llm(action, roll_info=roll_info)
        if not out:
            out = (
                f"You act: {action}. The world responds with a quiet mystery in {st.get('location','the unknown')}.\n\n"
                "A) Look around for clues.\nB) Talk to someone nearby.\nC) Move on to a new place.\n\n"
                "```json\n{\"update\": {}}\n```"
            )

        narrative, upd = self._dm_extract_json_update(out)
        if upd:
            self._dm_apply_update(upd)

        narrative = narrative.strip()
        if narrative:
            self._dm_log_add("dm", narrative)
            st["last_dm"] = narrative
        self._dm_save()
        return narrative

    def _dm_roll(self, expr: str) -> str:
        expr = (expr or "").strip()
        if not expr:
            expr = "1d20"
        try:
            r = _porch_roll(expr)
            if r.get("ok"):
                return f"{expr} → {r.get('detail')} = {r.get('total')}"
            return f"Roll error: {r.get('error','bad roll')}"
        except Exception as e:
            return f"Roll error: {e}"

    def _dm_export(self) -> str:
        st = getattr(self, "_dm_state", None) or self._dm_load()
        try:
            os.makedirs(DUNGEON_MASTER_EXPORT_DIR, exist_ok=True)
        except Exception:
            pass
        ts = _now_ts()
        base = f"dungeon_master_{ts}"
        json_path = os.path.join(DUNGEON_MASTER_EXPORT_DIR, base + ".json")
        md_path = os.path.join(DUNGEON_MASTER_EXPORT_DIR, base + ".md")
        try:
            _porch__save_json(json_path, st)
        except Exception:
            pass

        p = st.get("player", {})
        md = []
        md.append(f"# {st.get('campaign_name','Dungeon Master')}\n\n")
        md.append(f"**Setting:** {st.get('setting','')}\n\n")
        md.append(f"**Location:** {st.get('location','')}\n\n")
        md.append("## Player\n\n")
        md.append(
            f"- **Name:** {p.get('name','')}\n"
            f"- **Class:** {p.get('class','')}\n"
            f"- **Race:** {p.get('race','')}\n"
            f"- **Level:** {p.get('level',1)}\n"
            f"- **HP:** {p.get('hp','')}/{p.get('hp_max','')}\n"
            f"- **AC:** {p.get('ac','')}\n\n"
        )
        md.append("## Inventory\n\n")
        inv = p.get("inventory", [])
        if isinstance(inv, list) and inv:
            md.extend([f"- {x}\n" for x in inv])
        else:
            md.append("- (empty)\n")
        md.append("\n## Quests\n\n")
        for q in st.get("quests", []):
            if isinstance(q, dict):
                md.append(f"- **{q.get('type','side').upper()}** [{q.get('status','open')}] {q.get('title','')}\n")
        md.append("\n## Recent Session Log (last 20)\n\n")
        for it in (st.get("log", []) or [])[-20:]:
            if isinstance(it, dict):
                md.append(f"- **{it.get('role','')}:** {it.get('content','').strip()}\n")
        md_text = "".join(md)
        try:
            _porch__write(md_path, md_text)
        except Exception:
            try:
                with open(md_path, "w", encoding="utf-8") as f:
                    f.write(md_text)
            except Exception:
                pass
        return f"Exported:\n- {md_path}\n- {json_path}"

    def _dm_slash(self, args: List[str]) -> None:
        a0 = (args[0].lower() if args else "open")

        # Ensure DM state + hub
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            self._dm_state = self._dm_load()
            st = self._dm_state
        try:
            self._dmhub_init(st)
        except Exception:
            pass

        # Audit trail (command history)
        try:
            cmd_line = "/dm " + " ".join(args).strip()
            self._dmhub_log_command(cmd_line, sender="You", meta={"src": "slash"})
        except Exception:
            pass

        if a0 in ("help", "?", "commands"):
            self._ui_log(
                "🎲 Sovereign DM — commands\n"
                " /dm open\n"
                " /dm new <campaign name>\n"
                " /dm status\n"
                " /dm roll <expr>              (ex: 1d20+5, 2d6+2, 4d6kh3)\n"
                " /dm save | /dm load\n"
                " /dm export\n"
                " /dm send <recipient> <text>  (signed DMMessage)\n"
                " /dm inbox [recipient] [n]    (default recipient=You, n=15)\n"
                " /dm history [n]              (default n=25)\n"
                " /dm verify [n]               (verify last n hub messages; default n=25)\n",
                dim=True,
                mono=True,
            )
            return

        # Sovereign DM Hub suite
        if a0 == "send":
            if len(args) < 3:
                self._ui_log("Usage: /dm send <recipient> <text>", dim=True)
                return
            recipient = args[1].strip()
            text = " ".join(args[2:]).strip()
            if not recipient or not text:
                self._ui_log("Usage: /dm send <recipient> <text>", dim=True)
                return
            msg = self._dmhub_send(recipient=recipient, text=text, sender="You", meta={"src": "slash"})
            ok = self._dmhub_verify_message(msg)
            self._ui_log(f"📨 DM → {recipient}  (signed={'OK' if ok else 'FAIL'})", dim=True)
            return

        if a0 == "inbox":
            recipient = (args[1].strip() if len(args) > 1 else "You")
            n = 15
            if len(args) > 2:
                try:
                    n = int(args[2])
                except Exception:
                    n = 15
            msgs = self._dmhub_inbox(recipient=recipient, limit=n)
            if not msgs:
                self._ui_log(f"📥 Inbox empty for {recipient}.", dim=True)
                return
            lines = [f"📥 Inbox for {recipient} (last {len(msgs)}):"]
            for mm in msgs:
                ok = "OK" if self._dmhub_verify_message(mm) else "FAIL"
                ts = mm.get("ts", "")
                sender = mm.get("sender", "?")
                txt = (mm.get("text", "") or "").replace("\n", " ").strip()
                if len(txt) > 160:
                    txt = txt[:157] + "..."
                lines.append(f"- [{ok}] {ts}  {sender} → {recipient}: {txt}")
            self._ui_log("\n".join(lines), dim=True, mono=True)
            return

        if a0 in ("history", "audit"):
            n = 25
            if len(args) > 1:
                try:
                    n = int(args[1])
                except Exception:
                    n = 25
            hist = self._dmhub_history(limit=n)
            if not hist:
                self._ui_log("🧾 DM history empty.", dim=True)
                return
            lines = [f"🧾 DM command history (last {len(hist)}):"]
            for rr in hist:
                ts = rr.get("ts", "")
                sender = rr.get("sender", "?")
                cmd = (rr.get("cmd", "") or "").strip()
                if len(cmd) > 180:
                    cmd = cmd[:177] + "..."
                lines.append(f"- {ts}  {sender}: {cmd}")
            self._ui_log("\n".join(lines), dim=True, mono=True)
            return

        if a0 == "verify":
            n = 25
            if len(args) > 1:
                try:
                    n = int(args[1])
                except Exception:
                    n = 25
            sess = self._dmhub_active_session()
            msgs = sess.get("messages", [])
            if not isinstance(msgs, list) or not msgs:
                self._ui_log("🔎 No DM hub messages to verify.", dim=True)
                return
            chunk = msgs[-max(1, int(n)):]
            okc = 0
            bad = []
            for mm in chunk:
                if self._dmhub_verify_message(mm):
                    okc += 1
                else:
                    bad.append(mm.get("id"))
            self._ui_log(f"🔎 Verified {okc}/{len(chunk)} DM hub messages. Bad: {bad[:10]}", dim=True, mono=True)
            return

        # Campaign controls (existing)
        if a0 in ("open", ""):
            self._open_dungeon_master()
            return
        if a0 in ("new", "reset"):
            name = " ".join(args[1:]).strip() if len(args) > 1 else "New Campaign"
            self._dm_state = self._dm_default()
            self._dm_state["campaign_name"] = name or "New Campaign"
            self._dm_save()
            self._ui_log(f"🎲 New Dungeon Master campaign: {self._dm_state['campaign_name']}", dim=True)
            self._open_dungeon_master()
            return
        if a0 == "save":
            self._dm_save()
            self._ui_log("🎲 Dungeon Master saved.", dim=True)
            return
        if a0 == "load":
            self._dm_state = self._dm_load()
            self._ui_log("🎲 Dungeon Master loaded.", dim=True)
            return
        if a0 == "status":
            self._ui_log("🎲 " + self._dm_summary(), dim=True, mono=True)
            return
        if a0 == "roll":
            expr = " ".join(args[1:]).strip() if len(args) > 1 else "1d20"
            msg = self._dm_roll(expr)
            self._dm_log_add("system", msg)
            self._ui_log("🎲 " + msg, dim=True)
            return
        if a0 == "export":
            msg = self._dm_export()
            self._ui_log("🎲 " + msg, dim=True)
            return

        # Default: treat the remainder as a player action to the campaign DM
        action = " ".join(args).strip()
        out = self._dm_do_action(action)
        if out:
            self._ui_log(out)

    def _open_dungeon_master(self) -> None:
        st = getattr(self, "_dm_state", None)
        if not isinstance(st, dict):
            st = self._dm_load()
            self._dm_state = st

        win = getattr(self, "_dm_win", None)
        try:
            if win is not None and win.winfo_exists():
                try:
                    win.lift()
                    win.focus_force()
                except Exception:
                    pass
                self._dm_refresh_ui()
                return
        except Exception:
            pass

        win = ctk.CTkToplevel(self)
        self._dm_win = win
        win.title("🎲 Dungeon Master")
        win.geometry("1020x720")
        try:
            win.grab_set()
        except Exception:
            pass

        def on_close():
            try:
                self._dm_win = None
            except Exception:
                pass
            try:
                win.destroy()
            except Exception:
                pass

        try:
            win.protocol("WM_DELETE_WINDOW", on_close)
        except Exception:
            pass

        top = ctk.CTkFrame(win, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=10)
        ctk.CTkLabel(top, text="Dungeon Master", font=ctk.CTkFont(size=18, weight="bold"), text_color=PALETTE["text"]).pack(anchor="w")
        ctk.CTkLabel(top, text="AI-driven campaign: inventory + quests + stats + rolls + save/load.", text_color=PALETTE["muted"]).pack(anchor="w", pady=(4, 0))

        body = ctk.CTkFrame(win, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=14, pady=(0, 14))
        body.grid_columnconfigure(0, weight=3)
        body.grid_columnconfigure(1, weight=2)
        body.grid_rowconfigure(0, weight=1)

        left = ctk.CTkFrame(body)
        left.grid(row=0, column=0, sticky="nsew", padx=(0, 10))
        left.grid_rowconfigure(0, weight=1)
        left.grid_columnconfigure(0, weight=1)

        self._dm_text = ctk.CTkTextbox(left, wrap="word")
        self._dm_text.grid(row=0, column=0, sticky="nsew", padx=10, pady=10)

        entry_row = ctk.CTkFrame(left, fg_color="transparent")
        entry_row.grid(row=1, column=0, sticky="ew", padx=10, pady=(0, 10))
        entry_row.grid_columnconfigure(0, weight=1)

        self._dm_entry = ctk.CTkEntry(entry_row, placeholder_text="What do you do? (e.g., 'talk to the innkeeper', 'search the room', 'cast a spell') ...")
        self._dm_entry.grid(row=0, column=0, sticky="ew", padx=(0, 8))

        def send_action():
            try:
                a = self._dm_entry.get()
                self._dm_entry.delete(0, "end")
            except Exception:
                a = ""
            a = (a or "").strip()
            if not a:
                return
            self._dm_do_action(a)
            self._dm_refresh_ui()
            try:
                self._dm_text.see("end")
            except Exception:
                pass

        ctk.CTkButton(entry_row, text="Send", command=send_action, width=120).grid(row=0, column=1)

        try:
            self._dm_entry.bind("<Return>", lambda _ev=None: send_action())
        except Exception:
            pass

        right = ctk.CTkFrame(body)
        right.grid(row=0, column=1, sticky="nsew")
        right.grid_rowconfigure(3, weight=1)
        right.grid_columnconfigure(0, weight=1)

        settings = ctk.CTkFrame(right)
        settings.grid(row=0, column=0, sticky="ew", padx=10, pady=(10, 6))
        settings.grid_columnconfigure(1, weight=1)

        ctk.CTkLabel(settings, text="Campaign").grid(row=0, column=0, sticky="w")
        self._dm_campaign = ctk.CTkEntry(settings)
        self._dm_campaign.grid(row=0, column=1, sticky="ew", padx=(8, 0))

        ctk.CTkLabel(settings, text="Setting").grid(row=1, column=0, sticky="w", pady=(6, 0))
        self._dm_setting = ctk.CTkEntry(settings)
        self._dm_setting.grid(row=1, column=1, sticky="ew", padx=(8, 0), pady=(6, 0))

        ctk.CTkLabel(settings, text="Tone").grid(row=2, column=0, sticky="w", pady=(6, 0))
        self._dm_tone = ctk.CTkEntry(settings)
        self._dm_tone.grid(row=2, column=1, sticky="ew", padx=(8, 0), pady=(6, 0))

        ctk.CTkLabel(settings, text="Model").grid(row=3, column=0, sticky="w", pady=(6, 0))
        self._dm_model = ctk.CTkEntry(settings)
        self._dm_model.grid(row=3, column=1, sticky="ew", padx=(8, 0), pady=(6, 0))

        ctk.CTkLabel(settings, text="Temp").grid(row=4, column=0, sticky="w", pady=(6, 0))
        self._dm_temp = ctk.CTkSlider(settings, from_=0.0, to=1.5, number_of_steps=150)
        self._dm_temp.grid(row=4, column=1, sticky="ew", padx=(8, 0), pady=(6, 0))

        btns = ctk.CTkFrame(right, fg_color="transparent")
        btns.grid(row=1, column=0, sticky="ew", padx=10, pady=(0, 6))
        btns.grid_columnconfigure(0, weight=1)
        btns.grid_columnconfigure(1, weight=1)

        def apply_settings():
            st = self._dm_state
            if not isinstance(st, dict):
                return
            st["campaign_name"] = (self._dm_campaign.get() or st.get("campaign_name","")).strip() or st.get("campaign_name","New Campaign")
            st["setting"] = (self._dm_setting.get() or st.get("setting","")).strip() or st.get("setting","")
            st["tone"] = (self._dm_tone.get() or st.get("tone","")).strip() or st.get("tone","")
            st["model"] = (self._dm_model.get() or st.get("model","")).strip() or st.get("model", getattr(self,"chat_model", CHAT_MODEL))
            try:
                st["temperature"] = float(self._dm_temp.get())
            except Exception:
                st["temperature"] = 0.7
            self._dm_save()
            self._dm_refresh_ui()

        def new_campaign():
            self._dm_state = self._dm_default()
            apply_settings()

        def save_campaign():
            apply_settings()
            self._dm_save()
            self._dm_refresh_ui()

        def load_campaign():
            self._dm_state = self._dm_load()
            self._dm_refresh_ui()

        ctk.CTkButton(btns, text="New", command=new_campaign).grid(row=0, column=0, sticky="ew", padx=(0, 6))
        ctk.CTkButton(btns, text="Save", command=save_campaign).grid(row=0, column=1, sticky="ew", padx=(6, 0))
        ctk.CTkButton(btns, text="Load", command=load_campaign).grid(row=1, column=0, sticky="ew", padx=(0, 6), pady=(6, 0))
        ctk.CTkButton(btns, text="Export", command=lambda: self._ui_log(self._dm_export(), dim=True)).grid(row=1, column=1, sticky="ew", padx=(6, 0), pady=(6, 0))

        dice = ctk.CTkFrame(right)
        dice.grid(row=2, column=0, sticky="ew", padx=10, pady=(0, 6))
        dice.grid_columnconfigure(1, weight=1)

        ctk.CTkLabel(dice, text="Roll").grid(row=0, column=0, sticky="w")
        self._dm_roll_entry = ctk.CTkEntry(dice, placeholder_text="e.g., 1d20+5, 2d6+2, 4d6kh3")
        self._dm_roll_entry.grid(row=0, column=1, sticky="ew", padx=(8, 8))

        def do_roll():
            expr = (self._dm_roll_entry.get() or "1d20").strip()
            msg = self._dm_roll(expr)
            self._dm_log_add("system", msg)
            self._dm_save()
            self._dm_refresh_ui()

        ctk.CTkButton(dice, text="Roll", width=90, command=do_roll).grid(row=0, column=2)

        self._dm_tabs = ctk.CTkTabview(right)
        self._dm_tabs.grid(row=3, column=0, sticky="nsew", padx=10, pady=(0, 10))
        try:
            self._dm_tabs.add("📜 Sheet")
            self._dm_tabs.add("📨 DM Hub")
            self._dm_tabs.add("🕯 Spiritual")
            self._dm_tabs.add("🔌 IoT")
            self._dm_tabs.add("🤖 Orchestra")
            self._dm_tabs.add("⚙ Automation")
            self._dm_tabs.add("🎭 NPC Agents")
        except Exception:
            # older customtkinter uses insert rather than add
            try:
                self._dm_tabs.insert(0, "📜 Sheet")
                self._dm_tabs.insert(1, "📨 DM Hub")
                self._dm_tabs.insert(2, "🕯 Spiritual")
                self._dm_tabs.insert(3, "🔌 IoT")
                self._dm_tabs.insert(4, "🤖 Orchestra")
                self._dm_tabs.insert(5, "⚙ Automation")
                self._dm_tabs.insert(6, "🎭 NPC Agents")
            except Exception:
                pass

        # --- Sheet tab ---
        try:
            sheet_tab = self._dm_tabs.tab("📜 Sheet")
        except Exception:
            sheet_tab = self._dm_tabs
        self._dm_sheet = ctk.CTkTextbox(sheet_tab, wrap="word")
        try:
            self._dm_sheet.pack(fill="both", expand=True, padx=8, pady=8)
        except Exception:
            self._dm_sheet.grid(row=0, column=0, sticky="nsew", padx=8, pady=8)

        # --- DM Hub tab ---
        try:
            hub_tab = self._dm_tabs.tab("📨 DM Hub")
        except Exception:
            hub_tab = None
        if hub_tab is not None:
            try:
                hub_tab.grid_rowconfigure(1, weight=1)
                hub_tab.grid_columnconfigure(0, weight=1)
            except Exception:
                pass

            hub_top = ctk.CTkFrame(hub_tab, fg_color="transparent")
            hub_top.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
            hub_top.grid_columnconfigure(1, weight=1)
            hub_top.grid_columnconfigure(3, weight=1)

            ctk.CTkLabel(hub_top, text="Inbox for").grid(row=0, column=0, sticky="w")
            self._dmhub_inbox_for = ctk.StringVar(value="You")
            try:
                hub_recipients = ["You"] + list(BROTHERS.keys())
            except Exception:
                hub_recipients = ["You"]
            self._dmhub_inbox_menu = ctk.CTkOptionMenu(
                hub_top,
                values=hub_recipients,
                variable=self._dmhub_inbox_for,
                command=lambda _=None: self._dmhub_refresh_ui(),
            )
            self._dmhub_inbox_menu.grid(row=0, column=1, sticky="ew", padx=(8, 8))

            self._dmhub_refresh_btn = ctk.CTkButton(hub_top, text="Refresh", width=90, command=self._dmhub_refresh_ui)
            self._dmhub_refresh_btn.grid(row=0, column=2, sticky="e", padx=(0, 8))

            self._dmhub_verify_btn = ctk.CTkButton(
                hub_top,
                text="Verify",
                width=90,
                command=lambda: self._dmhub_refresh_ui(verify=True),
            )
            self._dmhub_verify_btn.grid(row=0, column=3, sticky="e")

            self._dmhub_inbox_box = ctk.CTkTextbox(hub_tab, wrap="word")
            self._dmhub_inbox_box.grid(row=1, column=0, sticky="nsew", padx=8, pady=(0, 8))

            hub_comp = ctk.CTkFrame(hub_tab, fg_color="transparent")
            hub_comp.grid(row=2, column=0, sticky="ew", padx=8, pady=(0, 8))
            hub_comp.grid_columnconfigure(1, weight=1)

            ctk.CTkLabel(hub_comp, text="From").grid(row=0, column=0, sticky="w")
            self._dmhub_from = ctk.StringVar(value="You")
            self._dmhub_from_menu = ctk.CTkOptionMenu(hub_comp, values=["You"] + list(BROTHERS.keys()), variable=self._dmhub_from)
            self._dmhub_from_menu.grid(row=0, column=1, sticky="ew", padx=(8, 0))

            ctk.CTkLabel(hub_comp, text="To").grid(row=1, column=0, sticky="w", pady=(6, 0))
            self._dmhub_to = ctk.StringVar(value=(list(BROTHERS.keys())[0] if len(list(BROTHERS.keys()))>0 else "Ori"))
            self._dmhub_to_menu = ctk.CTkOptionMenu(hub_comp, values=hub_recipients, variable=self._dmhub_to)
            self._dmhub_to_menu.grid(row=1, column=1, sticky="ew", padx=(8, 0), pady=(6, 0))

            self._dmhub_send_text = ctk.CTkTextbox(hub_comp, height=90, wrap="word")
            self._dmhub_send_text.grid(row=2, column=0, columnspan=2, sticky="ew", pady=(8, 8))

            def _hub_send():
                sender = (self._dmhub_from.get() or "You").strip() or "You"
                recipient = (self._dmhub_to.get() or "").strip()
                try:
                    txt = (self._dmhub_send_text.get("1.0", "end") or "").strip()
                except Exception:
                    txt = ""
                if not recipient or not txt:
                    return
                try:
                    self._dmhub_send(recipient=recipient, text=txt, sender=sender, meta={"channel": "dmhub_ui"})
                except Exception:
                    pass
                try:
                    self._dmhub_send_text.delete("1.0", "end")
                except Exception:
                    pass
                try:
                    self._dmhub_inbox_for.set("You")
                except Exception:
                    pass
                self._dmhub_refresh_ui()

            hub_send_row = ctk.CTkFrame(hub_comp, fg_color="transparent")
            hub_send_row.grid(row=3, column=0, columnspan=2, sticky="ew")
            hub_send_row.grid_columnconfigure(0, weight=1)
            ctk.CTkLabel(hub_send_row, text="Signed messages are stored in your DM hub + queued to assistant_tasks.").grid(row=0, column=0, sticky="w")
            ctk.CTkButton(hub_send_row, text="Send DM", width=120, command=_hub_send).grid(row=0, column=1, sticky="e")

        # --- Spiritual tab ---
        try:
            spirit_tab = self._dm_tabs.tab("🕯 Spiritual")
        except Exception:
            spirit_tab = None
        if spirit_tab is not None:
            try:
                spirit_tab.grid_rowconfigure(3, weight=1)
                spirit_tab.grid_columnconfigure(0, weight=1)
            except Exception:
                pass

            st_sp = getattr(self, "_spirit_state", None)
            if not isinstance(st_sp, dict):
                self._spirit_state = self._spirit_load()
                st_sp = self._spirit_state

            sp_top = ctk.CTkFrame(spirit_tab, fg_color="transparent")
            sp_top.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
            sp_top.grid_columnconfigure(1, weight=1)
            ctk.CTkLabel(sp_top, text="Tradition").grid(row=0, column=0, sticky="w")
            self._spirit_trad = ctk.StringVar(value=st_sp.get("tradition", "Universal"))
            self._spirit_trad_menu = ctk.CTkOptionMenu(
                sp_top,
                values=["Universal", "Bible", "Qur'an", "Bhagavad Gita", "Guru Granth Sahib", "Buddhist", "Taoist", "Mystic"],
                variable=self._spirit_trad,
            )
            self._spirit_trad_menu.grid(row=0, column=1, sticky="ew", padx=(8, 0))

            self._spirit_q = ctk.CTkTextbox(spirit_tab, height=90, wrap="word")
            self._spirit_q.grid(row=1, column=0, sticky="ew", padx=8, pady=(0, 8))
            self._spirit_q.insert("end", st_sp.get("draft", "Ask for guidance, a ritual, or a scripture-aligned reflection..."))

            sp_btns = ctk.CTkFrame(spirit_tab, fg_color="transparent")
            sp_btns.grid(row=2, column=0, sticky="ew", padx=8, pady=(0, 8))
            sp_btns.grid_columnconfigure(0, weight=1)

            self._spirit_out = ctk.CTkTextbox(spirit_tab, wrap="word")
            self._spirit_out.grid(row=3, column=0, sticky="nsew", padx=8, pady=(0, 8))

            def _spirit_ask():
                try:
                    q = (self._spirit_q.get("1.0", "end") or "").strip()
                except Exception:
                    q = ""
                if not q:
                    return
                trad = (self._spirit_trad.get() or "Universal").strip()
                try:
                    ans = self._spirit_chat(question=q, tradition=trad)
                except Exception as e:
                    ans = f"(error) {e}"
                try:
                    self._spirit_out.delete("1.0", "end")
                    self._spirit_out.insert("end", ans)
                except Exception:
                    pass

            def _spirit_save_draft():
                try:
                    st_sp["tradition"] = (self._spirit_trad.get() or "Universal").strip()
                    st_sp["draft"] = (self._spirit_q.get("1.0", "end") or "")
                    self._spirit_save()
                except Exception:
                    pass

            ctk.CTkButton(sp_btns, text="Ask", width=110, command=_spirit_ask).grid(row=0, column=0, sticky="w")
            ctk.CTkButton(sp_btns, text="Save Draft", width=110, command=_spirit_save_draft).grid(row=0, column=1, sticky="w", padx=(8,0))

        # --- IoT tab ---
        try:
            iot_tab = self._dm_tabs.tab("🔌 IoT")
        except Exception:
            iot_tab = None
        if iot_tab is not None:
            try:
                iot_tab.grid_rowconfigure(0, weight=1)
                iot_tab.grid_columnconfigure(0, weight=1)
            except Exception:
                pass

            st_iot = getattr(self, "_iot_state", None)
            if not isinstance(st_iot, dict):
                try:
                    self._iot_state = self._iot_load()
                except Exception:
                    self._iot_state = {}
                st_iot = self._iot_state

            try:
                self._build_iot_hub_ui(iot_tab)
            except Exception as _e:
                try:
                    _LOG.exception("IoT UI build failed: %s", _e)
                except Exception:
                    pass
                try:
                    ctk.CTkLabel(iot_tab, text="IoT Hub: UI build failed (see console).").pack(padx=10, pady=10, anchor="w")
                except Exception:
                    pass

        # --- Orchestra tab ---
        try:
            orch_tab = self._dm_tabs.tab("🤖 Orchestra")
            self._build_orchestra_ui(orch_tab)
        except Exception:
            pass

        # --- Automation tab ---
        try:
            auto_tab = self._dm_tabs.tab("⚙ Automation")
            self._build_automation_ui(auto_tab)
        except Exception:
            pass

        # --- NPC Agents tab ---
        try:
            npc_tab = self._dm_tabs.tab("🎭 NPC Agents")
            self._build_npc_agents_ui(npc_tab)
        except Exception:
            pass

        self._dm_refresh_ui()

    def _dm_refresh_ui(self) -> None:
        st = getattr(self, "_dm_state", None)
        win = getattr(self, "_dm_win", None)
        if not isinstance(st, dict) or win is None:
            return
        try:
            if not win.winfo_exists():
                return
        except Exception:
            return

        try:
            self._dm_campaign.delete(0, "end")
            self._dm_campaign.insert(0, st.get("campaign_name", ""))
            self._dm_setting.delete(0, "end")
            self._dm_setting.insert(0, st.get("setting", ""))
            self._dm_tone.delete(0, "end")
            self._dm_tone.insert(0, st.get("tone", ""))
            self._dm_model.delete(0, "end")
            self._dm_model.insert(0, st.get("model", getattr(self,"chat_model", CHAT_MODEL)))
            try:
                self._dm_temp.set(float(st.get("temperature", 0.7)))
            except Exception:
                pass
        except Exception:
            pass

        try:
            self._dm_text.delete("1.0", "end")
            for it in st.get("log", [])[-200:]:
                if not isinstance(it, dict):
                    continue
                role = it.get("role", "player")
                content = (it.get("content", "") or "").strip()
                if not content:
                    continue
                prefix = {"player": "You", "dm": "DM", "system": "System"}.get(role, role)
                self._dm_text.insert("end", f"{prefix}: {content}\n\n")
            self._dm_text.see("end")
        except Exception:
            pass

        try:
            self._dm_sheet.delete("1.0", "end")
            self._dm_sheet.insert("end", self._dm_state_text())
        except Exception:
            pass

        try:
            self._dmhub_refresh_ui()
        except Exception:
            pass



    # ---------------------------
    # DM Hub UI helpers
    # ---------------------------
    def _dmhub_refresh_ui(self, verify: bool = False) -> None:
        """Refresh the DM Hub panel inside the Dungeon Master window (if present)."""
        try:
            st = getattr(self, "_dm_state", None)
            if not isinstance(st, dict):
                st = self._dm_load()
                self._dm_state = st
            self._dmhub_init(st)
        except Exception:
            return

        box = getattr(self, "_dmhub_inbox_box", None)
        var = getattr(self, "_dmhub_inbox_for", None)
        if box is None or var is None:
            return

        recipient = "You"
        try:
            recipient = (var.get() or "You").strip() or "You"
        except Exception:
            recipient = "You"

        try:
            msgs = self._dmhub_inbox(recipient=recipient, limit=30)
        except Exception:
            msgs = []

        lines = [f"📥 Inbox for {recipient} (last {len(msgs)}):"]
        for mm in msgs:
            if not isinstance(mm, dict):
                continue
            ok = None
            if verify:
                try:
                    ok = self._dmhub_verify_message(mm)
                except Exception:
                    ok = None
            ts = (mm.get("ts", "") or "")
            sender = (mm.get("sender", "?") or "?")
            txt = (mm.get("text", "") or "").replace("\n", " ").strip()
            if len(txt) > 220:
                txt = txt[:217] + "..."
            if ok is True:
                prefix = "[OK] "
            elif ok is False:
                prefix = "[FAIL] "
            else:
                prefix = ""
            lines.append(f"- {prefix}{ts}  {sender} → {recipient}: {txt}")

        # Command history preview
        try:
            hist = self._dmhub_history(limit=12)
        except Exception:
            hist = []
        if hist:
            lines.append("")
            lines.append("🧾 Recent /dm commands:")
            for it in hist[-12:]:
                if not isinstance(it, dict):
                    continue
                ts = it.get("ts", "")
                cmd = (it.get("cmd", "") or "").strip()
                if len(cmd) > 200:
                    cmd = cmd[:197] + "..."
                lines.append(f"- {ts}  {cmd}")

        try:
            box.delete("1.0", "end")
            box.insert("end", "\n".join(lines))
            box.see("end")
        except Exception:
            pass

