    def _spirit_load(self) -> Dict[str, Any]:
        try:
            return _porch__load_json(SPIRITUAL_STATE_FILE, default={"tradition": "Universal", "draft": "", "history": []})
        except Exception:
            return {"tradition": "Universal", "draft": "", "history": []}

    def _spirit_save(self) -> None:
        try:
            st = getattr(self, "_spirit_state", None)
            if not isinstance(st, dict):
                return
            _porch__save_json(SPIRITUAL_STATE_FILE, st)
        except Exception:
            pass

    def _spirit_chat(self, question: str, tradition: str = "Universal") -> str:
        """Ask for spiritual guidance using the selected local LLM (Ollama)."""
        q = (question or "").strip()
        if not q:
            return ""
        trad = (tradition or "Universal").strip() or "Universal"

        sys = (
            "You are 'Spiritual Companion' (Spiritual GPT-style). Provide grounded, compassionate spiritual guidance. "
            "If quoting scripture, prefer short excerpts and cite book/chapter/verse when you are sure; otherwise say you're paraphrasing. "
            "Avoid claiming certainty about divine will. Offer a practical next step (breathing/grounding/reflection)."
        )
        if trad and trad != "Universal":
            sys += f" Focus tradition: {trad}."

        model = str(getattr(self, "chat_model", CHAT_MODEL))
        try:
            if hasattr(self, "model_var"):
                model = str(self.model_var.get() or model)
        except Exception:
            pass

        messages = [{"role": "system", "content": sys}, {"role": "user", "content": q}]
        ans = ""
        try:
            resp = ollama_chat(messages=messages, model=model, options={"temperature": 0.7})
            ans = (((resp or {}).get("message") or {}).get("content") or "").strip()
        except Exception as e:
            ans = f"(Ollama error) {e}"

        try:
            st = getattr(self, "_spirit_state", None)
            if not isinstance(st, dict):
                st = self._spirit_load()
                self._spirit_state = st
            st["tradition"] = trad
            st.setdefault("history", []).append({"ts": time.time(), "tradition": trad, "q": q, "a": ans})
            st["history"] = st["history"][-200:]
            self._spirit_save()
        except Exception:
            pass

        return ans or ""

