    def _iot_save(self) -> None:
        try:
            st = getattr(self, "_iot_state", None)
            if not isinstance(st, dict):
                return
            _porch__save_json(IOT_HUB_STATE_FILE, st)
        except Exception:
            pass

    def _iot_send_command(self, device_id: str, command: str) -> str:
        """
        Send a command to a registered device using local-first routing.

        Supported protos (configured in IoT Device Registry):
          - http: request to a local endpoint (JSON body)
          - mqtt: publish JSON to a topic (requires paho-mqtt)
          - local: record only (no network)

        The `command` can be:
          - plain string (e.g. "WATER zone1 15s")
          - JSON string (e.g. '{"cmd":"water","zone":"zone1","seconds":15}')
        """
        did = (device_id or "").strip()
        cmd_raw = (command or "").strip()
        if not did or not cmd_raw:
            return "(missing device_id or command)"

        # Ensure state
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            st = self._iot_load()
            self._iot_state = st

        # Registry + device config
        try:
            reg = self._iot_registry()
        except Exception:
            reg = st.get("registry") if isinstance(st.get("registry"), dict) else {"devices": {}}
            reg.setdefault("devices", {})
        devices = reg.get("devices") or {}
        cfg = devices.get(did) if isinstance(devices, dict) else None

        # Parse payload
        if cmd_raw.startswith("{") and cmd_raw.endswith("}"):
            try:
                payload = json.loads(cmd_raw)
            except Exception:
                payload = {"command": cmd_raw}
        else:
            payload = {"command": cmd_raw}

        evt = {
            "ts": (self._dm_now() if hasattr(self, "_dm_now") else str(time.time())),
            "device_id": did,
            "command": cmd_raw,
            "payload": payload,
        }
        try:
            st.setdefault("events", []).append(evt)
            st["events"] = st["events"][-500:]
            self._iot_save()
        except Exception:
            pass

        # Optional: broadcast to Bifrost
        try:
            if hasattr(self, "_bifrost") and self._bifrost is not None:
                self._bifrost.broadcast({"type": "iot_command", "device_id": did, "payload": payload, "ts": time.time()})
        except Exception:
            pass

        # No config → local queued
        if not isinstance(cfg, dict):
            return "queued (no registry config)"

        proto = (cfg.get("proto") or "local").lower().strip()
        timeout = float(cfg.get("timeout") or 5)

        if proto == "local":
            return "queued (local)"

        if proto == "http":
            url = (cfg.get("url") or "").strip()
            if not url:
                return "http: missing url"
            method = (cfg.get("method") or "POST").strip().upper()
            headers = cfg.get("headers") if isinstance(cfg.get("headers"), dict) else {}
            token = (cfg.get("token") or "").strip()
            if token:
                headers = dict(headers)
                headers.setdefault("Authorization", f"Bearer {token}")
            headers = dict(headers)
            headers.setdefault("Content-Type", "application/json")
            try:
                import requests  # type: ignore
            except Exception:
                return "http: missing dependency 'requests' (pip install requests)"
            try:
                if method == "GET":
                    r = requests.get(url, params=payload, headers=headers, timeout=timeout)
                else:
                    r = requests.request(method, url, json=payload, headers=headers, timeout=timeout)
                txt = r.text if isinstance(r.text, str) else str(r.text)
                return f"http {r.status_code}: {txt[:180]}"
            except Exception as e:
                return f"http error: {e}"

        if proto == "mqtt":
            mqtt_cfg = cfg.get("mqtt") if isinstance(cfg.get("mqtt"), dict) else {}
            host = (mqtt_cfg.get("host") or "127.0.0.1").strip()
            port = int(mqtt_cfg.get("port") or 1883)
            topic = (mqtt_cfg.get("topic") or "porch/command").strip()
            user = (mqtt_cfg.get("username") or "").strip()
            pw = (mqtt_cfg.get("password") or "").strip()
            try:
                import paho.mqtt.client as mqttc  # type: ignore
            except Exception:
                return "mqtt: missing dependency 'paho-mqtt' (pip install paho-mqtt)"
            try:
                client = mqttc.Client()
                if user:
                    client.username_pw_set(user, pw)
                client.connect(host, port, keepalive=10)
                client.loop_start()
                client.publish(topic, json.dumps({"device_id": did, **payload}))
                time.sleep(0.05)
                client.loop_stop()
                client.disconnect()
                return f"mqtt published → {topic}"
            except Exception as e:
                return f"mqtt error: {e}"

        return f"queued (unknown proto: {proto})"

