    # ---------------------------
    # IoT Hub UI (Sovereign Survival Habitat modules)
    # ---------------------------
    def _build_iot_hub_ui(self, parent) -> None:
        """Build the IoT sub-tabs inside the DM window."""
        try:
            for w in getattr(parent, "winfo_children", lambda: [])():
                try:
                    w.destroy()
                except Exception:
                    pass
        except Exception:
            pass

        try:
            st = getattr(self, "_iot_state", None)
            if not isinstance(st, dict):
                st = self._iot_load()
                self._iot_state = st
        except Exception:
            self._iot_state = {"status": "(not connected)", "devices": [], "events": []}
            st = self._iot_state

        tabs = ctk.CTkTabview(parent)
        tabs.grid(row=0, column=0, sticky="nsew", padx=8, pady=8)
        try:
            parent.grid_rowconfigure(0, weight=1)
            parent.grid_columnconfigure(0, weight=1)
        except Exception:
            pass
        self._iot_tabs = tabs

        dev_tab = tabs.add("Devices")
        tuya_tab = tabs.add("Tuya Cloud")
        sec_tab = tabs.add("Security")
        env_tab = tabs.add("Environment")
        charts_tab = tabs.add("Charts")
        sol_tab = tabs.add("Solar")
        evl_tab = tabs.add("Eval")

        self._build_iot_devices_ui(dev_tab)
        self._build_iot_tuya_ui(tuya_tab)
        self._build_iot_security_ui(sec_tab)
        self._build_iot_environment_ui(env_tab)
        self._build_iot_charts_ui(charts_tab)
        self._build_iot_solar_ui(sol_tab)
        self._build_iot_eval_ui(evl_tab)

        self._iot_refresh_ui()

    def _iot_refresh_ui(self) -> None:
        """Refresh IoT widgets from state (safe to call anytime)."""
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            return

        try:
            if getattr(self, "_iot_status_lbl", None) is not None:
                self._iot_status_lbl.configure(text=f"Status: {st.get('status','')}")
        except Exception:
            pass

        try:
            box = getattr(self, "_iot_devices_box", None)
            if box is not None:
                box.configure(state="normal")
                box.delete("1.0", "end")
                for d in (st.get("devices") or []):
                    if not isinstance(d, dict):
                        continue
                    box.insert("end", f"• {d.get('name','(device)')}  (id={d.get('id','')}, kind={d.get('kind','')})\n")
                if not (st.get("devices") or []):
                    box.insert("end", "(no devices registered yet)\n")
                box.configure(state="disabled")
        except Exception:
            pass

        try:
            t = st.get("tuya") or {}
            if getattr(self, "_tuya_client_id", None) is not None:
                self._tuya_client_id.set(t.get("client_id","") or "")
            if getattr(self, "_tuya_endpoint", None) is not None:
                self._tuya_endpoint.set(t.get("endpoint","") or "")
            if getattr(self, "_tuya_region", None) is not None:
                self._tuya_region.set(t.get("region","us") or "us")
            if getattr(self, "_tuya_access_token_var", None) is not None:
                self._tuya_access_token_var.set(t.get("access_token","") or "")
            if getattr(self, "_tuya_enabled", None) is not None:
                self._tuya_enabled.set(bool(t.get("enabled", False)))
        except Exception:
            pass

        try:
            env = st.get("env") or {}
            last = env.get("last") or {}
            if getattr(self, "_env_last_box", None) is not None:
                self._env_last_box.configure(state="normal")
                self._env_last_box.delete("1.0", "end")
                if isinstance(last, dict) and last:
                    for sid, rec in list(last.items())[-20:]:
                        if not isinstance(rec, dict):
                            continue
                        ts = rec.get("ts")
                        vals = rec.get("values") or {}
                        self._env_last_box.insert("end", f"{sid} @ {ts}: {vals}\n")
                else:
                    self._env_last_box.insert("end", "(no sensor data yet)\n")
                self._env_last_box.configure(state="disabled")
        except Exception:
            pass

        try:
            self._env_render_heatmap()
        except Exception:
            pass

        try:
            self._solar_render()
        except Exception:
            pass

