    # IoT Devices UI
    # ---------------------------
    def _build_iot_devices_ui(self, tab) -> None:
        try:
            tab.grid_rowconfigure(3, weight=1)
            tab.grid_columnconfigure(0, weight=1)
        except Exception:
            pass

        top = ctk.CTkFrame(tab, fg_color="transparent")
        top.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
        top.grid_columnconfigure(1, weight=1)

        self._iot_status_lbl = ctk.CTkLabel(top, text="Status: (loading...)")
        self._iot_status_lbl.grid(row=0, column=0, sticky="w")

        ctk.CTkButton(top, text="Refresh", width=90, command=self._iot_refresh_ui).grid(row=0, column=4, sticky="e")
        ctk.CTkButton(top, text="Discover", width=90, command=self._iot_discover_ssdp).grid(row=0, column=5, sticky="e", padx=(8,0))

        ctk.CTkButton(top, text="Registry", width=90, command=self._iot_open_registry).grid(row=0, column=2, sticky="e", padx=(0, 8))
        self._env_edit_mode = getattr(self, "_env_edit_mode", None) or tk.BooleanVar(value=False)
        ctk.CTkButton(top, text="Edit Layout", width=110, command=self._env_toggle_edit).grid(row=0, column=3, sticky="e", padx=(0, 8))
