    def _tuya_save_from_ui(self) -> None:
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            st = self._iot_load()
            self._iot_state = st
        t = st.get("tuya") or {}
        try:
            t["enabled"] = bool(getattr(self, "_tuya_enabled", None).get())
        except Exception:
            pass
        try:
            t["client_id"] = (getattr(self, "_tuya_client_id", None).get() or "").strip()
        except Exception:
            pass
        try:
            t["secret"] = (getattr(self, "_tuya_secret", None).get() or "").strip()
        except Exception:
            pass
        try:
            t["endpoint"] = (getattr(self, "_tuya_endpoint", None).get() or "").strip()
        except Exception:
            pass
        try:
            t["region"] = (getattr(self, "_tuya_region", None).get() or "us").strip()
        except Exception:
            pass
        try:
            t["access_token"] = (getattr(self, "_tuya_access_token_var", None).get() or "").strip()
        except Exception:
            pass
        st["tuya"] = t
        self._iot_state = st
        try:
            self._iot_save()
        except Exception:
            pass

    def _tuya_preview_sign(self) -> None:
        try:
            self._tuya_save_from_ui()
        except Exception:
            pass
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            return
        tu = st.get("tuya") or {}
        method = (getattr(self, "_tuya_method", None).get() or "GET").strip().upper()
        path = (getattr(self, "_tuya_path", None).get() or "/").strip()
        try:
            body = self._tuya_body.get("1.0", "end").strip()
        except Exception:
            body = "{}"
        try:
            hdrs, dbg = self._tuya_signed_headers(method=method, path=path, body=body, tuya_cfg=tu, do_token=("token" in path))
            out = {"headers": hdrs, "debug": dbg}
            s = json.dumps(out, indent=2, ensure_ascii=False)
        except Exception as e:
            s = f"Sign preview failed: {e}"
        try:
            self._tuya_out.configure(state="normal")
            self._tuya_out.delete("1.0", "end")
            self._tuya_out.insert("end", s)
            self._tuya_out.configure(state="disabled")
        except Exception:
            pass

    def _tuya_http_request(self) -> None:
        try:
            self._tuya_save_from_ui()
        except Exception:
            pass
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            return
        tu = st.get("tuya") or {}
        if not tu.get("enabled", False):
            self._toast("Tuya is disabled (enable it first).", kind="warn")
            return

        method = (getattr(self, "_tuya_method", None).get() or "GET").strip().upper()
        path = (getattr(self, "_tuya_path", None).get() or "/").strip()
        try:
            body = self._tuya_body.get("1.0", "end").strip()
        except Exception:
            body = "{}"

        try:
            resp_txt = self._tuya_request(method=method, path=path, body=body, tuya_cfg=tu)
        except Exception as e:
            resp_txt = f"Request failed: {e}"

        try:
            self._tuya_out.configure(state="normal")
            self._tuya_out.delete("1.0", "end")
            self._tuya_out.insert("end", resp_txt)
            self._tuya_out.configure(state="disabled")
        except Exception:
            pass

    def _tuya_get_token_ui(self) -> None:
        try:
            self._tuya_save_from_ui()
        except Exception:
            pass
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            return
        tu = st.get("tuya") or {}
        if not tu.get("enabled", False):
            self._toast("Enable Tuya first.", kind="warn")
            return
        try:
            txt = self._tuya_request(method="GET", path="/v1.0/token?grant_type=1", body="", tuya_cfg=tu, is_token=True)
            data = None
            try:
                data = json.loads(txt)
            except Exception:
                pass
            if isinstance(data, dict):
                result = data.get("result") if "result" in data else data
                if isinstance(result, dict) and result.get("access_token"):
                    tu["access_token"] = result.get("access_token")
                    tu["refresh_token"] = result.get("refresh_token", tu.get("refresh_token",""))
                    tu["token_ts"] = int(time.time())
                    st["tuya"] = tu
                    self._iot_state = st
                    self._iot_save()
                    self._tuya_access_token_var.set(tu["access_token"])
            self._tuya_out.configure(state="normal")
            self._tuya_out.delete("1.0", "end")
            self._tuya_out.insert("end", txt)
            self._tuya_out.configure(state="disabled")
        except Exception as e:
            self._toast(f"Token fetch failed: {e}", kind="warn")

    def _tuya_signed_headers(self, method: str, path: str, body: str, tuya_cfg: Dict[str, Any], do_token: bool=False) -> tuple[Dict[str,str], Dict[str,Any]]:
        """Create Tuya signature headers (HMAC-SHA256)."""
        import hashlib, hmac, uuid
        t_ms = str(int(time.time() * 1000))
        nonce = uuid.uuid4().hex
        client_id = (tuya_cfg.get("client_id") or "").strip()
        secret = (tuya_cfg.get("secret") or "").strip()
        access_token = (tuya_cfg.get("access_token") or "").strip()

        body_bytes = (body or "").encode("utf-8")
        content_sha256 = hashlib.sha256(body_bytes).hexdigest()

        sig_hdrs = tuya_cfg.get("signature_headers") or {}
        sig_hdrs = {str(k): str(v) for k,v in sig_hdrs.items()} if isinstance(sig_hdrs, dict) else {}
        sig_keys = ":".join(sorted(sig_hdrs.keys()))
        hdr_block = ""
        if sig_hdrs:
            for k in sorted(sig_hdrs.keys()):
                hdr_block += f"{k}:{sig_hdrs[k]}\n"

        string_to_sign = f"{method}\n{content_sha256}\n{hdr_block}\n{path}"

        if do_token:
            sign_str = f"{client_id}{t_ms}{nonce}{string_to_sign}"
        else:
            sign_str = f"{client_id}{access_token}{t_ms}{nonce}{string_to_sign}"

        sign = hmac.new(secret.encode("utf-8"), sign_str.encode("utf-8"), hashlib.sha256).hexdigest().upper()

        headers = {
            "client_id": client_id,
            "t": t_ms,
            "sign_method": "HMAC-SHA256",
            "nonce": nonce,
            "sign": sign,
        }
        if sig_keys:
            headers["Signature-Headers"] = sig_keys
            for k,v in sig_hdrs.items():
                headers[k] = v
        if not do_token and access_token:
            headers["access_token"] = access_token

        dbg = {
            "t": t_ms,
            "nonce": nonce,
            "content_sha256": content_sha256,
            "string_to_sign": string_to_sign,
            "sign_str_prefix": "client_id + (access_token?) + t + nonce + stringToSign",
        }
        return headers, dbg

    def _tuya_request(self, method: str, path: str, body: str, tuya_cfg: Dict[str, Any], is_token: bool=False) -> str:
        """Perform a Tuya OpenAPI request using urllib."""
        import urllib.request, urllib.error
        endpoint = (tuya_cfg.get("endpoint") or "").strip().rstrip("/")
        if not endpoint:
            raise ValueError("Tuya endpoint missing")
        if not path.startswith("/"):
            path = "/" + path
        url = endpoint + path

        headers, dbg = self._tuya_signed_headers(method=method, path=path, body=body, tuya_cfg=tuya_cfg, do_token=is_token)
        data = None
        if method in ("POST", "PUT"):
            data = (body or "").encode("utf-8")
            headers.setdefault("Content-Type", "application/json")

        req = urllib.request.Request(url=url, data=data, method=method)
        for k,v in headers.items():
            if v is None:
                continue
            req.add_header(k, str(v))

        try:
            with urllib.request.urlopen(req, timeout=20) as resp:
                txt = resp.read().decode("utf-8", errors="replace")
                return txt
        except urllib.error.HTTPError as e:
            try:
                err = e.read().decode("utf-8", errors="replace")
            except Exception:
                err = str(e)
            return json.dumps({"http_error": str(e), "body": err, "debug": dbg}, indent=2)
        except Exception as e:
            return json.dumps({"error": str(e), "debug": dbg}, indent=2)

    # ---------------------------
    # IoT Security Scanner (IoTvulCode-inspired)
    # ---------------------------
    def _build_iot_security_ui(self, tab) -> None:
        try:
            tab.grid_rowconfigure(2, weight=1)
            tab.grid_columnconfigure(0, weight=1)
        except Exception:
            pass

        top = ctk.CTkFrame(tab, fg_color="transparent")
        top.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
        top.grid_columnconfigure(1, weight=1)

        self._sec_scan_path = ctk.StringVar(value="")
        ctk.CTkLabel(top, text="Scan path").grid(row=0, column=0, sticky="w")
        ctk.CTkEntry(top, textvariable=self._sec_scan_path).grid(row=0, column=1, sticky="ew", padx=(8, 8))

        def _browse():
            try:
                from tkinter import filedialog as fd
                p = fd.askopenfilename(title="Select firmware/source file (or choose any file in a folder)")
                if p:
                    self._sec_scan_path.set(p)
            except Exception:
                pass

        ctk.CTkButton(top, text="Browse", width=90, command=_browse).grid(row=0, column=2, sticky="e")
        ctk.CTkButton(top, text="Cameras", width=100, command=self._security_show_cameras).grid(row=0, column=3, sticky="e", padx=(8,0))

        btns = ctk.CTkFrame(tab, fg_color="transparent")
        btns.grid(row=1, column=0, sticky="ew", padx=8, pady=(0, 8))
        btns.grid_columnconfigure(0, weight=1)

        self._sec_recursive = ctk.BooleanVar(value=True)
        ctk.CTkCheckBox(btns, text="Recursive folder scan", variable=self._sec_recursive).grid(row=0, column=0, sticky="w")

        def _scan():
            p = (self._sec_scan_path.get() or "").strip()
            if not p:
                self._toast("Pick a file/folder to scan.", kind="warn")
                return
            report = self._iot_security_scan_path(p, recursive=bool(self._sec_recursive.get()))
            try:
                self._sec_out.configure(state="normal")
                self._sec_out.delete("1.0", "end")
                self._sec_out.insert("end", report)
                self._sec_out.configure(state="disabled")
            except Exception:
                pass

        ctk.CTkButton(btns, text="Scan Now", width=120, command=_scan).grid(row=0, column=1, sticky="e")

        self._sec_out = ctk.CTkTextbox(tab, wrap="word")
        self._sec_out.grid(row=2, column=0, sticky="nsew", padx=8, pady=(0, 8))
        self._sec_out.insert("end", "IoT Scanner: looks for common risky patterns (buffer ops, hardcoded creds, shell exec).\n")

    def _iot_security_scan_path(self, path: str, recursive: bool=True) -> str:
        """Lightweight static scan for risky IoT patterns (heuristic)."""
        import os as _os, re as _re, hashlib as _hashlib
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            st = self._iot_load()
            self._iot_state = st
        sec = st.get("security") or {}
        sec["last_scan_path"] = path

        patterns = [
            ("CWE-120/121", r"\b(strcpy|strcat|gets|sprintf|vsprintf)\s*\("),
            ("CWE-78", r"\b(system|popen|execl|execv)\s*\("),
            ("CWE-798", r"(password\s*=\s*\"[^\"]+\"|api_key\s*=\s*\"[^\"]+\"|SECRET\s*=\s*\"[^\"]+\")"),
            ("CWE-306", r"(auth\s*==\s*false|no_auth|skip_auth|bypass_auth)"),
            ("CWE-502", r"(pickle\.loads\(|yaml\.load\()"),
        ]

        hits = []
        files_scanned = 0

        def scan_file(fp: str):
            nonlocal files_scanned
            try:
                if _os.path.getsize(fp) > 8_000_000:
                    return
                with open(fp, "rb") as f:
                    raw = f.read()
                try:
                    txt = raw.decode("utf-8", errors="ignore")
                except Exception:
                    return
                files_scanned += 1
                for cwe, rx in patterns:
                    for m in _re.finditer(rx, txt):
                        ctx = txt[max(0, m.start()-40):min(len(txt), m.end()+40)]
                        fid = _hashlib.sha1((fp + ctx).encode("utf-8", errors="ignore")).hexdigest()[:10]
                        hits.append((cwe, fp, fid, ctx.replace("\n"," ").strip()))
            except Exception:
                return

        p = path
        if _os.path.isdir(p):
            for root, dirs, files in _os.walk(p):
                for fn in files:
                    scan_file(_os.path.join(root, fn))
                if not recursive:
                    break
        else:
            scan_file(p)

        out = []
        out.append("=== Sentinel’s Shield — IoT Static Scan (heuristic) ===")
        out.append(f"Scanned: {files_scanned} file(s)")
        out.append(f"Hits: {len(hits)}")
        out.append("")
        by = {}
        for cwe, fp, fid, ctx in hits:
            by[cwe] = by.get(cwe, 0) + 1
        if by:
            out.append("Summary by CWE-ish bucket:")
            for k in sorted(by.keys()):
                out.append(f"  - {k}: {by[k]}")
            out.append("")
        for cwe, fp, fid, ctx in hits[:200]:
            out.append(f"[{cwe}] {fp}  #{fid}")
            out.append(f"  ↳ {ctx}")
        if len(hits) > 200:
            out.append(f"... (showing first 200 / {len(hits)} hits)")
        out.append("")
        out.append("Note: this is a heuristic scanner, not a proof. Use real firmware analysis tools before relying on results.")
        report = "\n".join(out)

        try:
            sec["last_report"] = report
            st["security"] = sec
            self._iot_state = st
            self._iot_save()
        except Exception:
            pass

        return report

