    def _cysecbench_summarize(self, path: str) -> str:
        import os as _os, csv as _csv
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            st = self._iot_load()
            self._iot_state = st
        cy = st.get("cysecbench") or {}
        cy["path"] = path

        counts = {}
        total = 0
        file_ext = _os.path.splitext(path)[1].lower()
        try:
            if file_ext == ".jsonl":
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            obj = json.loads(line)
                        except Exception:
                            continue
                        total += 1
                        cat = obj.get("category") or obj.get("attack_type") or obj.get("label") or "unknown"
                        counts[str(cat)] = counts.get(str(cat), 0) + 1
            elif file_ext == ".json":
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    obj = json.load(f)
                if isinstance(obj, list):
                    for it in obj:
                        if not isinstance(it, dict):
                            continue
                        total += 1
                        cat = it.get("category") or it.get("attack_type") or it.get("label") or "unknown"
                        counts[str(cat)] = counts.get(str(cat), 0) + 1
                elif isinstance(obj, dict):
                    items = obj.get("data") if isinstance(obj.get("data"), list) else []
                    for it in items:
                        if not isinstance(it, dict):
                            continue
                        total += 1
                        cat = it.get("category") or it.get("attack_type") or it.get("label") or "unknown"
                        counts[str(cat)] = counts.get(str(cat), 0) + 1
            else:
                with open(path, "r", encoding="utf-8", errors="ignore", newline="") as f:
                    reader = _csv.DictReader(f)
                    for row in reader:
                        total += 1
                        cat = row.get("category") or row.get("attack_type") or row.get("label") or "unknown"
                        counts[str(cat)] = counts.get(str(cat), 0) + 1
        except Exception as e:
            return f"Failed to summarize: {e}"

        summ = {
            "file": path,
            "total_rows": total,
            "category_counts": dict(sorted(counts.items(), key=lambda kv: (-kv[1], kv[0]))),
        }
        cy["last_summary"] = summ
        st["cysecbench"] = cy
        self._iot_state = st
        try:
            self._iot_save()
        except Exception:
            pass

        out = []
        out.append("=== CySecBench Summary (non-generative) ===")
        out.append(f"Rows: {total}")
        out.append("Categories:")
        for k,v in summ["category_counts"].items():
            out.append(f"  - {k}: {v}")
        out.append("")
        out.append("Safety: prompts are not displayed or executed in this mode.")
        return "\n".join(out)
    def _esp32_bridge_start(self) -> bool:
        """Start a lightweight local HTTP bridge for ESP32/Arduino devices.

        Endpoints:
          GET  /health
          GET  /last    (last readings)
          POST /ingest  JSON: {sensor_id, values:{pm25,co2,voc,temp,hum,...}, ts, solar?:{...}}
          POST /command JSON: {device_id, command}
        """
        import os
        import threading
        import json as _json
        from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

        try:
            st = getattr(self, "_iot_state", None)
            if not isinstance(st, dict):
                st = self._iot_load()
                self._iot_state = st
            cfg = (st.get("esp32_bridge") or {})
            host = cfg.get("host", "0.0.0.0")
            port = int(cfg.get("port", 8766))
        except Exception:
            host, port = "0.0.0.0", 8766

        try:
            srv = getattr(self, "_esp32_srv", None)
            if srv is not None and getattr(srv, "running", False):
                return True
        except Exception:
            pass

        app = self

        class _Handler(BaseHTTPRequestHandler):
            def _send(self, code=200, body=b"ok", ctype="text/plain"):
                try:
                    self.send_response(code)
                    self.send_header("Content-Type", ctype)
                    self.send_header("Access-Control-Allow-Origin", "*")
                    self.end_headers()
                    self.wfile.write(body)
                except Exception:
                    pass

            def log_message(self, fmt, *args):
                try:
                    if os.getenv("PORCH_SECURE_DEBUG") in ("1","true","yes","on"):
                        super().log_message(fmt, *args)
                except Exception:
                    pass

            def do_OPTIONS(self):
                try:
                    self.send_response(200)
                    self.send_header("Access-Control-Allow-Origin", "*")
                    self.send_header("Access-Control-Allow-Methods", "GET,POST,OPTIONS")
                    self.send_header("Access-Control-Allow-Headers", "Content-Type")
                    self.end_headers()
                except Exception:
                    pass

            def do_GET(self):
                if self.path.startswith("/health"):
                    self._send(200, b"ok")
                    return
                if self.path.startswith("/last"):
                    try:
                        st = getattr(app, "_iot_state", {}) if isinstance(getattr(app, "_iot_state", {}), dict) else {}
                        env = st.get("env") or {}
                        body = _json.dumps(env.get("last") or {}, indent=2).encode("utf-8")
                        self._send(200, body, "application/json")
                    except Exception:
                        self._send(500, b"error")
                    return
                self._send(404, b"not found")

            def do_POST(self):
                if not (self.path.startswith("/ingest") or self.path.startswith("/command")):
                    self._send(404, b"not found")
                    return
                try:
                    length = int(self.headers.get("Content-Length") or "0")
                except Exception:
                    length = 0
                try:
                    raw = self.rfile.read(length) if length > 0 else b"{}"
                except Exception:
                    raw = b"{}"
                try:
                    obj = _json.loads(raw.decode("utf-8", errors="ignore") or "{}")
                except Exception:
                    obj = {}

                if self.path.startswith("/command"):
                    try:
                        did = str(obj.get("device_id") or "")
                        cmd = str(obj.get("command") or "")
                        if did and cmd:
                            app._iot_send_command(did, cmd)
                        self._send(200, b"queued")
                    except Exception:
                        self._send(500, b"error")
                    return

                # /ingest
                try:
                    # solar telemetry (optional)
                    if isinstance(obj, dict) and isinstance(obj.get("solar"), dict):
                        st = getattr(app, "_iot_state", None)
                        if not isinstance(st, dict):
                            st = app._iot_load()
                            app._iot_state = st
                        sol = st.get("solar") or {}
                        sol.update(obj.get("solar") or {})
                        sol["last"] = obj.get("solar") or {}
                        st["solar"] = sol
                        app._iot_state = st
                        app._iot_save()
                        try:
                            app._solar_render()
                        except Exception:
                            pass

                    if isinstance(obj, dict):
                        app._iot_record_sensor(obj)
                    self._send(200, b"ok")
                except Exception:
                    self._send(500, b"error")

        try:
            httpd = ThreadingHTTPServer((host, port), _Handler)
        except Exception:
            host = "127.0.0.1"
            httpd = ThreadingHTTPServer((host, port), _Handler)

        def _run():
            try:
                httpd.serve_forever(poll_interval=0.5)
            except Exception:
                pass

        th = threading.Thread(target=_run, daemon=True)
        th.start()

        class _SrvWrap:
            def __init__(self, httpd, th):
                self.httpd = httpd
                self.th = th
                self.running = True
            def stop(self):
                try:
                    self.running = False
                    self.httpd.shutdown()
                except Exception:
                    pass
            def is_running(self):
                return bool(self.running)

        self._esp32_srv = _SrvWrap(httpd, th)

        try:
            st = getattr(self, "_iot_state", None)
            if isinstance(st, dict):
                st.setdefault("esp32_bridge", {})["enabled"] = True
                st.setdefault("esp32_bridge", {})["host"] = host
                st.setdefault("esp32_bridge", {})["port"] = int(port)
                st["status"] = f"ESP32 bridge running on http://{host}:{port}"
                self._iot_state = st
                self._iot_save()
        except Exception:
            pass

        return True
    def _esp32_bridge_stop(self) -> None:
        try:
            srv = getattr(self, "_esp32_srv", None)
            if srv is not None:
                srv.stop()
        except Exception:
            pass
        try:
            st = getattr(self, "_iot_state", None)
            if isinstance(st, dict):
                st["status"] = "(not connected)"
                st.setdefault("esp32_bridge", {})["enabled"] = False
                self._iot_save()
        except Exception:
            pass


    def _open_wild_ride(self) -> None:
        self._wild_state = getattr(self, "_wild_state", None) or self._wild_load()

        win = ctk.CTkToplevel(self)
        win.title("🎢 Wild Ride")
        win.geometry("900x650")
        try:
            win.grab_set()
        except Exception:
            pass

        top = ctk.CTkFrame(win, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=10)
        ctk.CTkLabel(top, text="Wild Ride", font=ctk.CTkFont(size=18, weight="bold"), text_color=PALETTE["text"]).pack(anchor="w")
        ctk.CTkLabel(top, text="Procedural adventure beats (LLM optional).", text_color=PALETTE["muted"]).pack(anchor="w", pady=(4, 0))

        box = ctk.CTkTextbox(win, wrap="word")
        box.pack(fill="both", expand=True, padx=14, pady=(0, 10))

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=14, pady=(0, 14))

        def refresh():
            box.configure(state="normal")
            box.delete("1.0", "end")
            for line in self._wild_state.get("log", []):
                box.insert("end", line + "\n\n")
            box.configure(state="disabled")
            self._wild_save()

        def new_run():
            self._wild_state = self._wild_default()
            self._wild_state["log"] = ["🎢 Wild Ride started."]
            refresh()

        def next_beat():
            beat = self._wild_next_beat(self._wild_state)
            # optional LLM embellish
            extra = self._llm_quick(
                "You are a playful narrator. Expand the beat into 3 short sentences. Keep it safe and fun.",
                beat,
                max_chars=700,
            )
            if extra:
                beat2 = beat + "\n" + extra
            else:
                beat2 = beat
            self._wild_state.setdefault("log", []).append(beat2)
            refresh()

        def save_md():
            content = "# Wild Ride Log\n\n" + "\n\n---\n\n".join(self._wild_state.get("log", [])) + "\n"
            self._write_textfile(WILD_RIDE_LOG, content)
            self._ui_log(f"💾 Saved Wild Ride log: {WILD_RIDE_LOG}", dim=True)
            try:
                self._index_well_background()
            except Exception:
                pass

        ctk.CTkButton(btns, text="🆕 New Ride", command=new_run, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="➡ Next Beat", command=next_beat, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="💾 Save Log", command=save_md, height=40, fg_color="#1B274A").pack(side="left")

        if not self._wild_state.get("log"):
            self._wild_state["log"] = ["🎢 Wild Ride started."]
        refresh()

