        ctk.CTkLabel(form, text="Dimension name:", text_color=PALETTE["text"]).grid(row=0, column=0, sticky="w")
        name_entry = ctk.CTkEntry(form, placeholder_text="e.g., Neon Reef / Obsidian Garden / Solarus Rift")
        name_entry.grid(row=0, column=1, sticky="ew", padx=(10, 0))
        form.grid_columnconfigure(1, weight=1)

        out = ctk.CTkTextbox(win, wrap="word")
        out.pack(fill="both", expand=True, padx=14, pady=(0, 10))

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=14, pady=(0, 14))

        def write_out(s: str):
            out.configure(state="normal")
            out.delete("1.0", "end")
            out.insert("1.0", s)
            out.configure(state="disabled")

        def open_rift():
            dim = (name_entry.get() or "").strip() or f"Rift-{_now_ts()}"
            desc = self._llm_quick(
                "You are a worldbuilder. Describe a new dimension in 6 short bullets. Keep it safe and wondrous.",
                f"Create a dimension called '{dim}'. Tie it loosely to the Infinite House mythos.",
                max_chars=1200,
            )
            if not desc:
                desc = f"- {dim}: a strange and beautiful place.\n- Light behaves differently.\n- New puzzles await.\n- Friendly entities.\n- A secret library.\n- A safe path home."
            os.makedirs(RIFTS_DIR, exist_ok=True)
            rid = f"rift_{_now_ts()}"
            fp = os.path.join(RIFTS_DIR, f"{rid}.md")
            self._write_textfile(fp, f"# {dim}\n\n{desc}\n")
            write_out(f"Created: {fp}\n\n{desc}")
            self._ui_log(f"🌀 Rift opened: {dim}", dim=True)
            try:
                self._index_well_background()
            except Exception:
                pass

        def forge_world_node():
            dim = (name_entry.get() or "").strip() or f"Rift-{_now_ts()}"
            desc = out.get("1.0", "end").strip()
            if not desc:
                desc = f"{dim} — a new dimension."
            nid = f"rift::{re.sub(r'[^a-z0-9_]+', '_', dim.lower())[:40]}::{_now_ts()}"
            node = {
                "id": nid,
                "title": dim,
                "kind": "dimension",
                "text": desc,
                "tags": ["rift", "dimension", "exploration"],
                "facts": [f"room: {getattr(self, 'home_room_id', 'unknown')}", f"brother: {self.active_brother}"],
                "updated_at": _now_ts(),
            }
            try:
                self.world.upsert_node(node)
                self.world.index_nodes()
                self._ui_log(f"🗺️ Forged World Node: {nid}", dim=True)
            except Exception as e:
                self._ui_log(f"⚠️ Could not forge world node: {e}", error=True)

        ctk.CTkButton(btns, text="🌀 Open Rift", command=open_rift, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="🗺️ Forge World Node", command=forge_world_node, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="📂 Open Rift Folder", command=lambda: open_in_file_manager(RIFTS_DIR), height=40, fg_color="#1B274A").pack(side="left")
        write_out("Name a dimension, then click Open Rift.\n\nTip: /rift")

