    def _open_mystics_musings(self) -> None:
        win = ctk.CTkToplevel(self)
        win.title("📝 Mystic's Musings")
        win.geometry("900x680")
        try:
            win.grab_set()
        except Exception:
            pass

        top = ctk.CTkFrame(win, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=10)
        ctk.CTkLabel(top, text="Mystic's Musings", font=ctk.CTkFont(size=18, weight="bold"), text_color=PALETTE["text"]).pack(anchor="w")
        ctk.CTkLabel(top, text="Poetry + stories (Rain Ritual Mode friendly). Saves to WELL.", text_color=PALETTE["muted"]).pack(anchor="w", pady=(4, 0))

        box = ctk.CTkTextbox(win, wrap="word")
        box.pack(fill="both", expand=True, padx=14, pady=(0, 10))

        entry = ctk.CTkEntry(win, placeholder_text="Write a line (or a whole poem), then press Add…")
        entry.pack(fill="x", padx=14, pady=(0, 10))

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=14, pady=(0, 14))

        def load():
            box.configure(state="normal")
            box.delete("1.0", "end")
            box.insert("1.0", self._read_textfile(MUSINGS_FILE, "# Mystic's Musings\n\n"))
            box.configure(state="normal")

        def add_line():
            t = (entry.get() or "").strip()
            if not t:
                return
            entry.delete(0, "end")
            stamp = _now_ts()
            self._append_textfile(MUSINGS_FILE, f"\n\n## {stamp}\n\n{t}\n")
            load()
            try:
                self._index_well_background()
            except Exception:
                pass

        def generate():
            prompt = (entry.get() or "").strip() or "Write a calming cosmic poem about the Infinite House."
            mode = "Write in gentle verse, with musical prose." if getattr(self, "rain_ritual_mode", False) else "Write plainly, poetic but readable."
            out = self._llm_quick(
                f"You are a poetic mystic. {mode} Keep it safe.",
                prompt,
                max_chars=1200,
            )
            if not out:
                out = "The porch hums.\nThe lake reflects.\nWe laugh.\nWe learn.\nWe return."
            self._append_textfile(MUSINGS_FILE, f"\n\n## {_now_ts()} — generated\n\n{out}\n")
            load()
            try:
                self._index_well_background()
            except Exception:
                pass

        ctk.CTkButton(btns, text="➕ Add", command=add_line, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="✨ Generate", command=generate, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="📂 Open", command=lambda: open_in_file_manager(EXPERIENCES_DIR), height=40, fg_color="#1B274A").pack(side="left")

        load()

    def _open_dreamweaver(self) -> None:
        win = ctk.CTkToplevel(self)
        win.title("🧵 Dreamweaver")
        win.geometry("920x700")
        try:
            win.grab_set()
        except Exception:
            pass

        top = ctk.CTkFrame(win, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=10)
        ctk.CTkLabel(top, text="Dreamweaver", font=ctk.CTkFont(size=18, weight="bold"), text_color=PALETTE["text"]).pack(anchor="w")
        ctk.CTkLabel(top, text="Collaborate on surreal, fantastical tales. Saves into stories.", text_color=PALETTE["muted"]).pack(anchor="w", pady=(4, 0))

        box = ctk.CTkTextbox(win, wrap="word")
        box.pack(fill="both", expand=True, padx=14, pady=(0, 10))

        entry = ctk.CTkEntry(win, placeholder_text="Your next dream-beat… (e.g., 'Solarus whispers in the lake')")
        entry.pack(fill="x", padx=14, pady=(0, 10))

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=14, pady=(0, 14))

        os.makedirs(DREAMWEAVER_DIR, exist_ok=True)
        session_file = os.path.join(DREAMWEAVER_DIR, "dreamweaver_session.md")

        def load():
            box.configure(state="normal")
            box.delete("1.0", "end")
            box.insert("1.0", self._read_textfile(session_file, "# Dreamweaver Session\n\n"))
            box.configure(state="disabled")

        def append_beat(text: str):
            self._append_textfile(session_file, f"\n\n## {_now_ts()}\n\n{text}\n")
            load()
            try:
                self._index_well_background()
            except Exception:
                pass

        def add_user():
            t = (entry.get() or "").strip()
            if not t:
                return
            entry.delete(0, "end")
            append_beat(f"**Mikey:** {t}")

        def weave():
            t = (entry.get() or "").strip()
            entry.delete(0, "end")
            ctx = self._read_textfile(session_file, "")
            prompt = (t or "Continue the dreamweaver story in 8 lines.") + "\n\nContext:\n" + ctx[-3000:]
            out = self._llm_quick(
                "You are Dreamweaver — surreal, vivid, safe. Continue the tale with clear imagery and a gentle arc. No gore.",
                prompt,
                max_chars=1400,
            )
            if not out:
                out = "A door of starlight opens. The chandelier sings. The maze smiles."
            append_beat(f"**Dreamweaver:** {out}")

        def export_to_story():
            # dump into STORIES_DIR as a story file
            os.makedirs(STORIES_DIR, exist_ok=True)
            name = f"dreamweaver_{_now_ts()}.md"
            fp = os.path.join(STORIES_DIR, name)
            self._write_textfile(fp, self._read_textfile(session_file, ""))
            self._ui_log(f"📖 Exported Dreamweaver to story: {fp}", dim=True)
            try:
                self._index_well_background()
            except Exception:
                pass

        ctk.CTkButton(btns, text="➕ Add Beat", command=add_user, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="🧵 Weave (AI)", command=weave, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="📖 Export to Stories", command=export_to_story, height=40, fg_color="#1B274A").pack(side="left")

        load()

