    # ---------------------------
    # Retro Console (ROM launcher)
    # ---------------------------
    def _retro_settings_path(self) -> str:
        return os.path.join(WELL_FOLDER, "settings", "retro_console.json")

    def _retro_load_settings(self) -> Dict[str, Any]:
        path = self._retro_settings_path()
        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    obj = json.load(f)
                if isinstance(obj, dict):
                    return obj
        except Exception:
            pass
        return {
            "emulator_path": "",
            "roms_dir": "",
            "retroarch_core": "",
            "controller_input": False,
            "key_inject": False,

            "extensions": [".nes", ".sfc", ".smc", ".gba", ".gb", ".gbc", ".n64", ".z64", ".v64", ".gen", ".md", ".sms", ".gg", ".pce", ".cue", ".iso"],
        }

    def _retro_save_settings(self, s: Dict[str, Any]) -> None:
        path = self._retro_settings_path()
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(s, f, indent=2, ensure_ascii=False)
        except Exception:
            pass

    def _open_retro_console(self) -> None:
        """
        A simple launcher for emulators you already have installed (e.g., RetroArch).
        Use only ROMs you legally own / homebrew.
        """
        win = ctk.CTkToplevel(self)
        win.title("Retro Console")
        win.geometry("920x640")
        try:
            win.grab_set()
        except Exception:
            pass

        s = self._retro_load_settings()

        top = ctk.CTkFrame(win, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=10)

        ctk.CTkLabel(
            top,
            text="Retro Console",
            font=ctk.CTkFont(size=18, weight="bold"),
            text_color=PALETTE["text"],
        ).pack(anchor="w")
        ctk.CTkLabel(
            top,
            text="Launcher for your installed emulator (ex: RetroArch). Use ROMs you own / homebrew.",
            text_color=PALETTE["muted"],
        ).pack(anchor="w", pady=(4, 0))


        togg = ctk.CTkFrame(top, fg_color="transparent")
        togg.pack(anchor="w", pady=(10, 0))

        retro_input_var = ctk.BooleanVar(value=bool(s.get("controller_input", False)))
        key_inject_var = ctk.BooleanVar(value=bool(s.get("key_inject", False)))

        def _apply_toggles():
            s["controller_input"] = bool(retro_input_var.get())
            s["key_inject"] = bool(key_inject_var.get())
            try:
                self._retro_save_settings(s)
            except Exception:
                pass
            try:
                self._porch_retro_input_on = bool(retro_input_var.get())
            except Exception:
                pass
            try:
                self._porch_retro_inject_on = bool(key_inject_var.get())
            except Exception:
                pass

        ctk.CTkCheckBox(
            togg,
            text="Controller Bridge (Bifrost Inbound)",
            variable=retro_input_var,
            command=_apply_toggles,
            text_color=PALETTE["text"],
        ).pack(side="left", padx=(0, 14))

        ctk.CTkCheckBox(
            togg,
            text="Key Inject (allowlisted)",
            variable=key_inject_var,
            command=_apply_toggles,
            text_color=PALETTE["text"],
        ).pack(side="left")


        form = ctk.CTkFrame(win, fg_color=PALETTE["panel2"], corner_radius=14, border_width=1, border_color="#1B274A")
        form.pack(fill="x", padx=14, pady=(0, 10))

        def row(parent, label, value="", browse_cmd=None, placeholder=""):
            r = ctk.CTkFrame(parent, fg_color="transparent")
            r.pack(fill="x", padx=12, pady=8)
            ctk.CTkLabel(r, text=label, width=160, anchor="w", text_color=PALETTE["muted"]).pack(side="left")
            e = ctk.CTkEntry(r, placeholder_text=placeholder)
            e.pack(side="left", fill="x", expand=True, padx=(0, 8))
            e.insert(0, value or "")
            if browse_cmd:
                ctk.CTkButton(r, text="Browse", width=90, command=lambda: browse_cmd(e)).pack(side="left")
            return e

        def browse_exe(e):
            try:
                p = filedialog.askopenfilename(
                    title="Select emulator executable",
                    filetypes=[("Executable", "*.exe"), ("All files", "*.*")],
                )
                if p:
                    e.delete(0, "end")
                    e.insert(0, p)
            except Exception:
                pass

        def browse_dir(e):
            try:
                p = filedialog.askdirectory(title="Select ROMs folder")
                if p:
                    e.delete(0, "end")
                    e.insert(0, p)
            except Exception:
                pass

        emu_entry = row(form, "Emulator EXE", s.get("emulator_path", ""), browse_exe, "C:\\Path\\to\\retroarch.exe")
        roms_entry = row(form, "ROMs Folder", s.get("roms_dir", ""), browse_dir, "C:\\Path\\to\\ROMs")
        core_entry = row(form, "RetroArch Core (optional)", s.get("retroarch_core", ""), None, "C:\\RetroArch\\cores\\snes9x_libretro.dll")

        mid = ctk.CTkFrame(win, fg_color=PALETTE["panel2"], corner_radius=14, border_width=1, border_color="#1B274A")
        mid.pack(fill="both", expand=True, padx=14, pady=(0, 14))

        # ROM list
        list_frame = ctk.CTkFrame(mid, fg_color="transparent")
        list_frame.pack(fill="both", expand=True, padx=12, pady=12)

        tk_list = tk.Listbox(list_frame, height=14, activestyle="dotbox")
        tk_list.pack(side="left", fill="both", expand=True)

        sb = tk.Scrollbar(list_frame, orient="vertical", command=tk_list.yview)
        sb.pack(side="left", fill="y")
        tk_list.configure(yscrollcommand=sb.set)

        rom_paths: List[str] = []

        def refresh():
            nonlocal rom_paths
            tk_list.delete(0, "end")
            rom_paths = []
            rom_dir = (roms_entry.get() or "").strip()
            exts = s.get("extensions") or []
            exts = [str(x).lower().strip() for x in exts if str(x).strip()]
            if not rom_dir or not os.path.isdir(rom_dir):
                return
            try:
                for root, _, files in os.walk(rom_dir):
                    for fn in files:
                        p = os.path.join(root, fn)
                        if not exts or os.path.splitext(fn)[1].lower() in exts:
                            rom_paths.append(p)
                rom_paths.sort(key=lambda x: os.path.basename(x).lower())
                for p in rom_paths:
                    tk_list.insert("end", os.path.basename(p))
            except Exception:
                pass

        def launch_selected():
            try:
                idx = tk_list.curselection()
                if not idx:
                    self._ui_log("🎮 Select a ROM first.", dim=True)
                    return
                rom = rom_paths[int(idx[0])]
                emu = (emu_entry.get() or "").strip()
                if not emu or not os.path.exists(emu):
                    self._ui_log("🎮 Set a valid Emulator EXE first.", dim=True)
                    return

                core = (core_entry.get() or "").strip()
                args = [emu]

                # RetroArch convention: retroarch.exe -L core.dll romfile
                if os.path.basename(emu).lower().startswith("retroarch") and core:
                    args += ["-L", core, rom]
                else:
                    args += [rom]

                # Save settings
                s2 = dict(s)
                s2["emulator_path"] = emu
                s2["roms_dir"] = (roms_entry.get() or "").strip()
                s2["retroarch_core"] = core
                self._retro_save_settings(s2)

                subprocess.Popen(args, cwd=os.path.dirname(emu) or None)
                self._ui_log(f"🎮 Launching: {os.path.basename(rom)}", dim=True)
            except Exception:
                self._ui_log("🎮 Launch failed (check emulator path/core).", dim=True)

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=14, pady=(0, 14))

        ctk.CTkButton(btns, text="🔄 Refresh", command=refresh, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="▶ Launch Selected", command=launch_selected, height=40, fg_color=PALETTE["accent"]).pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="💾 Save", command=lambda: self._retro_save_settings({
            **s,
            "emulator_path": (emu_entry.get() or "").strip(),
            "roms_dir": (roms_entry.get() or "").strip(),
            "retroarch_core": (core_entry.get() or "").strip(),
        }), height=40, fg_color="#1B274A").pack(side="left")


        dbg = ctk.CTkFrame(win, fg_color="transparent")
        dbg.pack(fill="x", padx=14, pady=(0, 14))
        ctk.CTkLabel(
            dbg,
            text="Retro TV Input Debug (Bifrost inbound)",
            text_color=PALETTE["muted"],
        ).pack(anchor="w")
        dbg_box = ctk.CTkTextbox(dbg, height=160)
        dbg_box.pack(fill="both", expand=True, pady=(6, 0))
        try:
            dbg_box.configure(state="disabled")
        except Exception:
            pass

        def _dbg_refresh():
            try:
                q = getattr(self, "_porch_retro_debug", None)
                rows = []
                if q:
                    for it in list(q)[-80:]:
                        try:
                            ts = float(it.get("ts") or 0.0)
                            stamp = time.strftime("%H:%M:%S", time.localtime(ts))
                            src = str(it.get("source") or "")
                            ev = it.get("events") or []
                            evs = " ".join([
                                f"{str(e.get('btn',''))}:{'1' if bool(e.get('down', False)) else '0'}"
                                for e in ev if isinstance(e, dict)
                            ])
                            rows.append(f"{stamp} {src} {evs}".rstrip())
                        except Exception:
                            continue
                s = "\n".join(rows) if rows else "(no input packets yet)"
                try:
                    dbg_box.configure(state="normal")
                except Exception:
                    pass
                dbg_box.delete("1.0", "end")
                dbg_box.insert("end", s)
                try:
                    dbg_box.configure(state="disabled")
                except Exception:
                    pass
            except Exception:
                pass
            try:
                if win.winfo_exists():
                    win.after(250, _dbg_refresh)
            except Exception:
                pass

        _dbg_refresh()

        refresh()


    def _romforge_root(self) -> str:
        return os.path.join(WELL_FOLDER, "romforge")

    def _romforge_projects_root(self) -> str:
        return os.path.join(self._romforge_root(), "projects")

    def _romforge_cartridges_root(self) -> str:
        return os.path.join(self._romforge_root(), "cartridges")

    def _retro_signals_path(self) -> str:
        return os.path.join(WELL_FOLDER, "retro", "signals.jsonl")

    def _retro_frame_path(self) -> str:
        return os.path.join(WELL_FOLDER, "retro", "frames", "latest.png")

    def _ensure_romforge_dirs(self) -> None:
        try:
            _porch_safe_mkdir(self._romforge_root())
            _porch_safe_mkdir(self._romforge_projects_root())
            _porch_safe_mkdir(self._romforge_cartridges_root())
            _porch_safe_mkdir(os.path.dirname(self._retro_signals_path()))
            _porch_safe_mkdir(os.path.dirname(self._retro_frame_path()))
        except Exception:
            pass

    def _open_rom_forge(self) -> None:
        """
        Sovereign Console: Adventure-to-ROM Forge + Truth Cartridge packaging + Retro bridges.
        Legal note: Do not distribute copyrighted ROMs/BIOS. Use homebrew/public-domain or ROMs you own.
        """
        self._ensure_romforge_dirs()

        win = ctk.CTkToplevel(self)
        win.title("ROM Forge")
        win.geometry("980x720")
        try:
            win.grab_set()
        except Exception:
            pass

        outer = ctk.CTkFrame(win, fg_color=PALETTE["panel"])
        outer.pack(fill="both", expand=True, padx=12, pady=12)

        header = ctk.CTkFrame(outer, fg_color="transparent")
        header.pack(fill="x", padx=12, pady=(12, 6))

        ctk.CTkLabel(
            header,
            text="ROM Forge",
            font=ctk.CTkFont(size=18, weight="bold"),
            text_color=PALETTE["text"],
        ).pack(side="left")

        status_lbl = ctk.CTkLabel(
            header,
            text="",
            font=ctk.CTkFont(size=12),
            text_color=PALETTE["text_dim"],
        )
        status_lbl.pack(side="right")

        body = ctk.CTkFrame(outer, fg_color="transparent")
        body.pack(fill="both", expand=True, padx=12, pady=(6, 12))

        tabs = ctk.CTkTabview(body, fg_color=PALETTE["panel2"])
        tabs.pack(fill="both", expand=True)
        tab_build = tabs.add("Adventure-to-ROM")
        tab_truth = tabs.add("Truth Cartridge")
        tab_bridge = tabs.add("Retro Bridges")

        # ---------- Adventure-to-ROM ----------
        build_top = ctk.CTkFrame(tab_build, fg_color="transparent")
        build_top.pack(fill="x", padx=12, pady=10)

        ctk.CTkLabel(build_top, text="Source World Node", text_color=PALETTE["text"]).grid(row=0, column=0, sticky="w")
        node_var = tk.StringVar(value="")
        node_combo = ctk.CTkComboBox(build_top, variable=node_var, values=[""], width=520)
        node_combo.grid(row=0, column=1, padx=8, sticky="w")

        ctk.CTkLabel(build_top, text="Project Name", text_color=PALETTE["text"]).grid(row=1, column=0, sticky="w", pady=(8,0))
        project_var = tk.StringVar(value="")
        project_entry = ctk.CTkEntry(build_top, textvariable=project_var, width=520)
