        def _sha256_file(path: str) -> str:
            h = hashlib.sha256()
            with open(path, "rb") as f:
                for chunk in iter(lambda: f.read(1024 * 1024), b""):
                    h.update(chunk)
            return h.hexdigest()

        def _ed25519_keys():
            # returns (priv, pub_bytes, priv_path, pub_path) or (None, "", "", "")
            keys_dir = os.path.join(WELL_FOLDER, "keys")
            os.makedirs(keys_dir, exist_ok=True)
            priv_path = os.path.join(keys_dir, "ed25519_private.pem")
            pub_path = os.path.join(keys_dir, "ed25519_public.pem")
            try:
                from cryptography.hazmat.primitives.asymmetric import ed25519
                from cryptography.hazmat.primitives import serialization
            except Exception:
                return None, b"", priv_path, pub_path

            priv = None
            if os.path.exists(priv_path):
                try:
                    pem = open(priv_path, "rb").read()
                    priv = serialization.load_pem_private_key(pem, password=None)
                except Exception:
                    priv = None

            if priv is None:
                priv = ed25519.Ed25519PrivateKey.generate()
                try:
                    pem = priv.private_bytes(
                        encoding=serialization.Encoding.PEM,
                        format=serialization.PrivateFormat.PKCS8,
                        encryption_algorithm=serialization.NoEncryption(),
                    )
                    open(priv_path, "wb").write(pem)
                except Exception:
                    pass

            try:
                pub = priv.public_key()
                pub_pem = pub.public_bytes(
                    encoding=serialization.Encoding.PEM,
                    format=serialization.PublicFormat.SubjectPublicKeyInfo,
                )
                open(pub_path, "wb").write(pub_pem)
                return priv, pub_pem, priv_path, pub_path
            except Exception:
                return priv, b"", priv_path, pub_path

        def _package_cartridge():
            rom = (rom_path_var.get() or "").strip()
            if not rom or not os.path.isfile(rom):
                _safe_ui_log(truth_log, "Select a ROM file first.")
                return

            try:
                rom_hash = _sha256_file(rom)
            except Exception as e:
                _safe_ui_log(truth_log, f"Hash error: {e}")
                return

            manifest = {
                "schema": "parallax.truthcartridge.v1",
                "created_utc": datetime.datetime.now(timezone.utc).isoformat() + "Z",
                "rom_filename": os.path.basename(rom),
                "rom_sha256": rom_hash,
                "notes": (notes.get("1.0", "end").strip() if notes else ""),
            }

            manifest_bytes = json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8")
            sig_b64 = ""
            pub_pem = b""
            priv, pub_pem, priv_path, pub_path = _ed25519_keys()
            if priv is not None:
                try:
                    sig = priv.sign(manifest_bytes)
                    import base64
                    sig_b64 = base64.b64encode(sig).decode("ascii")
                    manifest["ed25519_pub_pem"] = pub_pem.decode("utf-8", "ignore")
                    manifest["ed25519_sig_b64"] = sig_b64
                except Exception:
                    pass
            else:
                _safe_ui_log(truth_log, "Ed25519 signing unavailable (install 'cryptography' to enable signatures).")

            ts = datetime.datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
            base = os.path.splitext(os.path.basename(rom))[0]
            out_zip = os.path.join(self._romforge_cartridges_root(), f"{base}_{ts}.pxcart.zip")
            out_manifest = os.path.join(self._romforge_cartridges_root(), f"{base}_{ts}.manifest.json")

            try:
                with open(out_manifest, "wb") as f:
                    f.write(json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8"))
            except Exception:
                pass

            try:
                with zipfile.ZipFile(out_zip, "w", compression=zipfile.ZIP_DEFLATED) as z:
                    z.write(rom, arcname=os.path.basename(rom))
                    z.writestr("manifest.json", json.dumps(manifest, ensure_ascii=False, indent=2))
                _safe_ui_log(truth_log, f"Truth Cartridge created → {out_zip}")
            except Exception as e:
                _safe_ui_log(truth_log, f"Package error: {e}")

        ctk.CTkButton(truth, text="Package Truth Cartridge", command=_package_cartridge).pack(anchor="w", pady=(8, 0))

