        ctk.CTkSwitch(toggles, text="VR Texture Stream (broadcast ./well/retro/frames/latest.png)", variable=s_on, progress_color=PALETTE["accent"], text_color=PALETTE["text"]).pack(anchor="w", pady=(8,0))

        bridge_log = ctk.CTkTextbox(bridge, height=360)
