    # -----------------
    def _open_cosmic_cartography(self) -> None:
        os.makedirs(CARTOGRAPHY_DIR, exist_ok=True)
        win = ctk.CTkToplevel(self)
        win.title("🗺️ Cosmic Cartography")
        win.geometry("980x720")
        try:
            win.grab_set()
        except Exception:
            pass

        top = ctk.CTkFrame(win, fg_color="transparent")
        top.pack(fill="x", padx=14, pady=10)
        ctk.CTkLabel(top, text="Cosmic Cartography", font=ctk.CTkFont(size=18, weight="bold"), text_color=PALETTE["text"]).pack(anchor="w")
        ctk.CTkLabel(top, text="Map the house + world. Discover hidden secrets.", text_color=PALETTE["muted"]).pack(anchor="w", pady=(4, 0))

        box = ctk.CTkTextbox(win, wrap="word")
        box.pack(fill="both", expand=True, padx=14, pady=(0, 10))

        btns = ctk.CTkFrame(win, fg_color="transparent")
        btns.pack(fill="x", padx=14, pady=(0, 14))

        def render_map() -> str:
            parts = []
            parts.append("# Infinite House — Map\n")
            parts.append(f"Current room: {getattr(self, 'home_room_id', 'unknown')}\n")
            parts.append("## Rooms\n")
            for rid, spec in HOME_ROOMS.items():
                mark = "★" if rid == getattr(self, "home_room_id", None) else "•"
                parts.append(f"- {mark} {rid}: {spec.get('title','')}")
            parts.append("\n## World Nodes\n")
            try:
                count = len(getattr(self.world, "nodes", {}) or {})
            except Exception:
                count = 0
            parts.append(f"- World node count: {count}\n")
            parts.append("## Stories\n")
            try:
                items = []
                if os.path.isdir(STORIES_DIR):
                    for fn in sorted(os.listdir(STORIES_DIR))[-12:]:
                        items.append(fn)
                for fn in items:
                    parts.append(f"- {fn}")
            except Exception:
                pass
            parts.append("\nTip: Use /home <room> to jump rooms.\n")
            return "\n".join(parts)

        def refresh():
            s = render_map()
            box.configure(state="normal")
            box.delete("1.0", "end")
            box.insert("1.0", s)
            box.configure(state="disabled")
            self._write_textfile(CARTOGRAPHY_NOTES_FILE, s)

        def discover_secret():
            idea = self._llm_quick(
                "You are a cartographer of a playful digital house. Suggest ONE hidden secret room or object in 2-3 sentences.",
                "Suggest a hidden discovery that fits the Infinite House. Keep it safe.",
                max_chars=450,
            ) or "A hidden door behind the chandelier leads to a tiny 'Laughter Vault' full of warm echoes."
            self._append_textfile(CARTOGRAPHY_NOTES_FILE, f"\n\n## Secret — {_now_ts()}\n\n{idea}\n")
            # also forge a node
            try:
                nid = f"secret::{_now_ts()}"
                self.world.upsert_node({"id": nid, "title": "Secret Discovery", "kind": "secret", "text": idea, "tags": ["secret"], "updated_at": _now_ts()})
                self.world.index_nodes()
            except Exception:
                pass
            refresh()
            try:
                self._index_well_background()
            except Exception:
                pass

        ctk.CTkButton(btns, text="🔄 Refresh Map", command=refresh, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="🗝️ Discover Secret", command=discover_secret, height=40, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="📂 Open Notes", command=lambda: open_in_file_manager(CARTOGRAPHY_DIR), height=40, fg_color="#1B274A").pack(side="left")
        refresh()

