        left = ctk.CTkFrame(win, fg_color=PALETTE["panel"])
        left.pack(side="left", fill="y", padx=12, pady=12)

        right = ctk.CTkFrame(win, fg_color=PALETTE["panel"])
        right.pack(side="right", fill="both", expand=True, padx=(0,12), pady=12)

        ctk.CTkLabel(left, text="Assistants", font=ctk.CTkFont(size=16, weight="bold"), text_color=PALETTE["text"]).pack(padx=12, pady=(12,6), anchor="w")
        listbox = ctk.CTkTextbox(left, width=220, height=420, fg_color=PALETTE["panel2"], text_color=PALETTE["text"])
