    # ---------- Status pills ----------
    def _set_pill(self, pill: ctk.CTkLabel, text: str, ok: Optional[bool] = None) -> None:
        pill.configure(text=text)
        if ok is None:
            pill.configure(fg_color="#1B274A", text_color=PALETTE["muted"])
        else:
            pill.configure(fg_color=PALETTE["success"] if ok else "#3A2330", text_color=PALETTE["text"] if ok else "#FFD6D6")

    def _update_status_pills(self) -> None:
        self._set_pill(self.pill_online, f"ONLINE: {'ON' if self.online_enabled else 'OFF'}", ok=self.online_enabled)

        has_key = bool(os.getenv(TAVILY_API_KEY_ENV, "").strip())
        has_requests = requests is not None
        tav_ok = has_key and has_requests
        tav_txt = "TAVILY: OK" if tav_ok else ("TAVILY: NO KEY" if not has_key else "TAVILY: NEEDS requests")
        self._set_pill(self.pill_tavily, tav_txt, ok=tav_ok)

        comfy_ok = bool(COMFYUI_URL) and (requests is not None)
        comfy_txt = "COMFYUI: OK" if comfy_ok else ("COMFYUI: OFF" if not COMFYUI_URL else "COMFYUI: NEEDS requests")
        self._set_pill(self.pill_comfy, comfy_txt, ok=comfy_ok)

        a_ok = self.autosnap_enabled and self.autosnap_n > 0
        self._set_pill(self.pill_autosnap, f"AUTOSNAP: {'ON' if a_ok else 'OFF'} ({self.autosnap_n})", ok=a_ok)
        self._set_pill(self.pill_world, f"WORLD: {'ON' if self.world_enabled else 'OFF'}", ok=self.world_enabled)

    # ---------- UI log ----------
    def _ui_log(self, text: str, brother: Optional[str] = None, dim: bool = False, error: bool = False, mono: bool = False) -> None:
        self.textbox.configure(state="normal")
        tag = "color_default"
        if dim:
            tag = "color_dim"
        if error:
            tag = "color_error"
        if brother in BROTHERS:
            tag = f"color_{brother}"
        if mono:
            self._t.insert("end", text + "\n", ("mono", tag))
        else:
            self._t.insert("end", text + "\n", tag)
        self.textbox.configure(state="disabled")
        self.textbox.see("end")

