    # ---------- history ----------
    def _load_persistent_history(self) -> List[Dict[str, str]]:
        history: List[Dict[str, str]] = []
        if os.path.exists(self.history_file):
            try:
                with open(self.history_file, "r", encoding="utf-8", errors="ignore") as f:
                    lines = f.readlines()
                for line in lines[-RECENT_EXCHANGES_TO_LOAD:]:
                    if line.startswith("Mikey:"):
                        history.append({"role": "user", "content": line.replace("Mikey:", "").strip()})
                    elif line.startswith("Brother:"):
                        history.append({"role": "assistant", "content": line.replace("Brother:", "").strip()})
            except Exception:
                pass
        return history

    def _save_to_file(self, role: str, text: str) -> None:
        try:
            with open(self.history_file, "a", encoding="utf-8") as f:
                prefix = "Mikey: " if role == "user" else "Brother: "
                f.write(f"{prefix}{text}\n")
        except Exception:
            pass

    # ---------- snapshots ----------
    # ---------- modes / per-tab state ----------
    def _history_path_for_mode(self, mode: str) -> str:
        m = (mode or "Porch").strip()
        if m.lower() == "porch":
            return HISTORY_FILE
        safe = re.sub(r"[^a-z0-9_]+", "_", m.lower()).strip("_")
        return os.path.join(WELL_FOLDER, f"history_{safe}.txt")

    def _load_history_from_path(self, path: str) -> List[Dict[str, str]]:
        history: List[Dict[str, str]] = []
        if path and os.path.exists(path):
            try:
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    lines = f.readlines()
                for line in lines[-RECENT_EXCHANGES_TO_LOAD:]:
                    if line.startswith("Mikey:"):
                        history.append({"role": "user", "content": line.replace("Mikey:", "").strip()})
                    elif line.startswith("Brother:"):
                        history.append({"role": "assistant", "content": line.replace("Brother:", "").strip()})
            except Exception:
                pass
        return history

    def _cmd_history_path_for_mode(self, mode: str) -> str:
        m = (mode or "Porch").strip()
        if m.lower() == "porch":
            # Back-compat: keep a generic file too
            return CMD_HISTORY_FILE
        safe = re.sub(r"[^a-z0-9_]+", "_", m.lower()).strip("_")
        return os.path.join(WELL_FOLDER, f"cmd_history_{safe}.json")

    def _load_cmd_history_from_path(self, path: str) -> List[str]:
        try:
            if path and os.path.exists(path):
                with open(path, "r", encoding="utf-8", errors="ignore") as f:
                    data = json.load(f)
                if isinstance(data, list):
                    out = []
                    for x in data:
                        if isinstance(x, str) and x.strip():
                            out.append(x.strip())
                    return out[-200:]
        except Exception:
            pass
        return []

    def _persist_cmd_history(self) -> None:
        """Persist command history for the active tab (so ↑ works after restart)."""
        try:
            mode = getattr(self, "active_mode", "Porch")
            sess = self._mode_sessions.get(mode) if hasattr(self, "_mode_sessions") else None
            path = None
            if isinstance(sess, dict):
                sess["cmd_history"] = list(self._cmd_history)
                sess["cmd_hist_idx"] = self._cmd_hist_idx
                sess["cmd_stash"] = self._cmd_stash
                path = sess.get("cmd_history_file")
            if not path:
                path = CMD_HISTORY_FILE
            os.makedirs(os.path.dirname(path) or ".", exist_ok=True)
            with open(path, "w", encoding="utf-8") as f:
                json.dump(list(self._cmd_history)[-200:], f, indent=2)
        except Exception:
            pass

    def _apply_mode_context(self, mode: str, render: bool = False) -> None:
        """Switch active mode tab: swaps history_file/chat_history/output textbox + command history."""
        try:
            new_mode = mode or "Porch"
            if not hasattr(self, "_mode_sessions"):
                self.active_mode = new_mode
                return

            # save current session state
            cur = getattr(self, "active_mode", "Porch")
            if cur in self._mode_sessions:
                self._mode_sessions[cur]["chat_history"] = list(self.chat_history)
                self._mode_sessions[cur]["cmd_history"] = list(self._cmd_history)
                self._mode_sessions[cur]["cmd_hist_idx"] = self._cmd_hist_idx
                self._mode_sessions[cur]["cmd_stash"] = self._cmd_stash

            if new_mode not in self._mode_sessions:
                new_mode = "Porch" if "Porch" in self._mode_sessions else list(self._mode_sessions.keys())[0]

            self.active_mode = new_mode
            self.history_file = self._mode_sessions[new_mode]["history_file"]
            self.chat_history = self._mode_sessions[new_mode]["chat_history"]

            self._cmd_history = self._mode_sessions[new_mode]["cmd_history"]
            self._cmd_hist_idx = self._mode_sessions[new_mode].get("cmd_hist_idx")
            self._cmd_stash = self._mode_sessions[new_mode].get("cmd_stash", "")

            # swap active output textbox
            if hasattr(self, "_mode_textboxes") and new_mode in self._mode_textboxes:
                self.textbox = self._mode_textboxes[new_mode]
            if hasattr(self, "_mode_tktexts") and new_mode in self._mode_tktexts:
                self._t = self._mode_tktexts[new_mode]

            if render:
                try:
                    self._render_mode_history_once(new_mode)
                except Exception:
                    pass

            # refresh placeholder state
            try:
                self._update_entry_placeholder()
            except Exception:
                pass
        except Exception:
            pass

    def _render_mode_history_once(self, mode: str) -> None:
        if not hasattr(self, "_mode_rendered"):
            return
        if self._mode_rendered.get(mode):
            return
        self._mode_rendered[mode] = True

        # User preference: do not show previous chat history in the UI
        try:
            if not bool(getattr(self, "settings", {}).get("ui_show_history", False)):
                return
        except Exception:
            return

        sess = self._mode_sessions.get(mode, {})
        hist = sess.get("chat_history") or []
        # Render lightweight: show only the last ~10 items
        hist = hist[-20:]
        for h in hist:
            try:
                role = h.get("role")
                content = (h.get("content") or "").strip()
                if not content:
                    continue
                if role == "user":
                    self._ui_log(f"🌀 Mikey: {content}", dim=False)
                else:
                    self._ui_log(f"🤝 Brother: {content}", dim=False)
            except Exception:
                continue
        try:
            self._scroll_chat_to_end()
        except Exception:
            pass

    def _on_mode_tab_changed(self) -> None:
        try:
            # Keep a lightweight activity timestamp so autonomous timers can throttle when user is idle.
            self._note_activity()
            mode = self.mode_tabs.get()
            if bool(getattr(self, '_suppress_mode_render', False)):
                self._apply_mode_context(mode, render=False)
            else:
                self._apply_mode_context(mode, render=True)
        except Exception:
            pass

    def _input_get(self) -> str:
        try:
            return (self.entry._textbox.get("1.0", "end-1c") or "").strip("\n")
        except Exception:
            try:
                return (self.entry.get() or "")
            except Exception:
                return ""

    def _input_clear(self) -> None:
        try:
            self.entry._textbox.delete("1.0", "end")
        except Exception:
            try:
                self.entry.delete(0, "end")
            except Exception:
                pass
        try:
            self._update_entry_placeholder()
        except Exception:
            pass

    def _note_activity(self) -> None:
        """Mark user activity (used to throttle autonomous loops / timers)."""
        try:
            self._last_activity_ts = time.time()
        except Exception:
            self._last_activity_ts = 0.0


    def _input_set(self, text: str) -> None:
        try:
            self.entry._textbox.delete("1.0", "end")
            if text:
                self.entry._textbox.insert("1.0", text)
        except Exception:
            try:
                self.entry.delete(0, "end")
                self.entry.insert(0, text)
            except Exception:
                pass
        try:
            self._update_entry_placeholder()
            self._schedule_spellcheck()
        except Exception:
            pass

    def _update_entry_placeholder(self) -> None:
        try:
            if not hasattr(self, "_entry_placeholder"):
                return
            txt = (self._input_get() or "").strip()
            if txt:
                self._entry_placeholder.place_forget()
            else:
                self._entry_placeholder.place(x=16, y=22)
        except Exception:
            pass

    def _on_input_return(self, event=None):
        try:
            # Shift+Enter inserts newline; Enter sends.
            if event is not None and (event.state & 0x0001):
                return None
        except Exception:
            pass
        self._send_message()
        return "break"

    def _on_input_changed(self, event=None):
        try:
            self._update_entry_placeholder()
        except Exception:
            pass
        self._schedule_spellcheck()
        return None

    def _schedule_spellcheck(self) -> None:
        try:
            if not getattr(self, "spell", None):
                return
            # debounce
            if hasattr(self, "_spell_after_id") and self._spell_after_id is not None:
                try:
                    self.after_cancel(self._spell_after_id)
                except Exception:
                    pass
            self._spell_after_id = self.after(220, self._spellcheck_input_now)
        except Exception:
            pass

    def _spellcheck_input_now(self) -> None:
        try:
            if not getattr(self, "spell", None):
                return
            t = getattr(self, "_entry_t", None) or self.entry._textbox
            # clear previous tags
            try:
                t.tag_remove("misspell", "1.0", "end")
            except Exception:
                pass
            s = (t.get("1.0", "end-1c") or "")
            if not s.strip():
                return
            if len(s) > 5000:
                return  # keep it snappy
            # find word tokens
            for m in re.finditer(r"[A-Za-z][A-Za-z']{1,}", s):
                w = m.group(0)
                if len(w) < 2:
                    continue
                if hasattr(self, "_spell_ignore") and (w or "").lower() in getattr(self, "_spell_ignore", set()):
                    continue
                if self.spell.is_correct(w):
                    continue
                start = f"1.0+{m.start()}c"
                end = f"1.0+{m.end()}c"
                try:
                    t.tag_add("misspell", start, end)
                except Exception:
                    pass
        except Exception:
            pass

    def _on_input_right_click(self, event=None):
        try:
            t = getattr(self, "_entry_t", None) or self.entry._textbox
            # Get word under cursor
            idx = t.index(f"@{event.x},{event.y}")
            start = t.index(f"{idx} wordstart")
            end = t.index(f"{idx} wordend")
            word = (t.get(start, end) or "").strip()
            if not word:
                return
            if hasattr(self, "_spell_ignore") and word.lower() in getattr(self, "_spell_ignore", set()):
                return
            if self.spell.is_correct(word):
                return
            sugg = self.spell.suggest(word, max_suggestions=8)
            if not sugg:
                return

            menu = tk.Menu(t, tearoff=0)
            for s in sugg[:8]:
                menu.add_command(
                    label=s,
                    command=lambda rep=s, a=start, b=end: self._replace_input_range(a, b, rep),
                )
            menu.add_separator()
            menu.add_command(label="Ignore (remove underline)", command=lambda: self._ignore_word_in_input(word))
            try:
                menu.tk_popup(event.x_root, event.y_root)
            finally:
                menu.grab_release()
        except Exception:
            pass

    def _replace_input_range(self, start: str, end: str, replacement: str) -> None:
        try:
            t = getattr(self, "_entry_t", None) or self.entry._textbox
            t.delete(start, end)
            t.insert(start, replacement)
            self._schedule_spellcheck()
        except Exception:
            pass

    def _ignore_word_in_input(self, word: str) -> None:
        # Simple ignore list for this session only
        try:
            if not hasattr(self, "_spell_ignore"):
                self._spell_ignore = set()
            self._spell_ignore.add((word or "").lower())
            # patch spell check quickly
            self._spellcheck_input_now()
        except Exception:
            pass

    # ---------- chat log search ----------
    def _open_chat_search(self) -> None:
        try:
            if hasattr(self, "_search_win") and self._search_win is not None:
                try:
                    self._search_win.focus()
                    return
                except Exception:
                    pass

            win = ctk.CTkToplevel(self)
            win.title("Find in Chat")
            win.geometry("460x170")
            try:
                win.grab_set()
            except Exception:
                pass
            self._search_win = win

            q = ctk.StringVar(value="")
            top = ctk.CTkFrame(win, fg_color="transparent")
            top.pack(fill="both", expand=True, padx=12, pady=12)

            ctk.CTkLabel(top, text="Search", text_color=PALETTE["text"]).pack(anchor="w")
            ent = ctk.CTkEntry(top, textvariable=q, fg_color=PALETTE["panel2"])
            ent.pack(fill="x", pady=(6, 10))
            ent.focus()

            row = ctk.CTkFrame(top, fg_color="transparent")
            row.pack(fill="x")

            def do_find(next_dir: int = 1):
                self._chat_search(q.get(), direction=next_dir)

            ctk.CTkButton(row, text="Find Next", command=lambda: do_find(1), fg_color="#1B274A").pack(side="left", padx=(0, 8))
            ctk.CTkButton(row, text="Find Prev", command=lambda: do_find(-1), fg_color="#1B274A").pack(side="left")
            ctk.CTkButton(row, text="Jump to Last Output", command=self._scroll_chat_to_end, fg_color="#1B274A").pack(side="right")

            def on_close():
                try:
                    self._clear_search_highlights()
                except Exception:
                    pass
                try:
                    win.destroy()
                except Exception:
                    pass
                self._search_win = None

            win.protocol("WM_DELETE_WINDOW", on_close)
            ent.bind("<Return>", lambda e: (do_find(1), "break"))
        except Exception:
            pass

    def _clear_search_highlights(self) -> None:
        try:
            t = getattr(self, "_t", None)
            if t is None:
                return
            t.tag_remove("search_hit", "1.0", "end")
        except Exception:
            pass

    def _chat_search(self, query: str, direction: int = 1) -> None:
        try:
            t = getattr(self, "_t", None)
            if t is None:
                return
            q = (query or "").strip()
            self._clear_search_highlights()
            if not q:
                return

            start = getattr(self, "_search_pos", "1.0")
            if direction < 0:
                # search backwards
                idx = t.search(q, start, stopindex="1.0", backwards=True, nocase=True)
            else:
                idx = t.search(q, start, stopindex="end", nocase=True)
            if not idx:
                # wrap
                idx = t.search(q, "1.0", stopindex="end", nocase=True)
            if not idx:
                return
            end = f"{idx}+{len(q)}c"
            t.tag_add("search_hit", idx, end)
            try:
                t.tag_configure("search_hit", underline=0, background="#23355E")
            except Exception:
                pass
            t.see(idx)
            self._search_pos = end if direction > 0 else idx
        except Exception:
            pass

    def _scroll_chat_to_end(self) -> None:
        try:
            t = getattr(self, "_t", None)
            if t is None:
                return
            t.see("end")
        except Exception:
            pass

    # ---------- run-mode loop ----------
    def _run_mode_loop(self, args: List[str]) -> None:
        """
        1 run = 3 events + boss + score + loot → unlocks.
        Stored in meta.json so it persists.
        """
        try:
            a0 = (args[0].lower() if args else "").strip()
            if a0 in ("stats", "meta"):
                self._open_meta_panel()
                return
        except Exception:
            pass

        events = [
            ("Echo Alley", 12),
            ("Glass Bridge", 14),
            ("Honeycomb Vault", 10),
            ("Neon Storm", 16),
            ("Silent Library", 11),
            ("Rift Market", 15),
            ("Shadow Orchard", 13),
            ("Auric Forge", 17),
        ]
        bosses = [
            ("Clockwork Warden", 30),
            ("Rift Leviathan", 34),
            ("Mirror Monarch", 32),
            ("Storm-Crowned Titan", 36),
        ]
        loot_table = [
            ("Copper Sigil", 1),
            ("Prism Shard", 2),
            ("Runed Thread", 2),
            ("Auric Coin", 3),
            ("Starlight Key", 4),
            ("Void Pearl", 5),
        ]

        rng = random.Random()
        rng.seed(int(time.time() * 1000) ^ (hash(getattr(self, "active_mode", "")) & 0xFFFFFFFF))

        chosen = rng.sample(events, k=3)
        boss = rng.choice(bosses)

        score = 0
        run_events = []
        for name, pts in chosen:
            roll = rng.randint(0, 6)
            pts2 = pts + roll
            score += pts2
            run_events.append({"name": name, "points": pts2})

        b_roll = rng.randint(0, 10)
        boss_points = boss[1] + b_roll
        score += boss_points

        # Loot: 1–3 items scaled by score
        loot_n = 1 if score < 60 else (2 if score < 80 else 3)
        loot = []
        for _ in range(loot_n):
            item = rng.choices([x[0] for x in loot_table], weights=[x[1] for x in loot_table], k=1)[0]
            loot.append(item)

        unlocks = self.meta.get("unlocks") or []
        if not isinstance(unlocks, list):
            unlocks = []
        # Some example unlock milestones
        if score >= 70 and "Runesmith" not in unlocks:
            unlocks.append("Runesmith")
        if score >= 85 and "Riftwalker" not in unlocks:
            unlocks.append("Riftwalker")
        if score >= 95 and "Stellar Librarian" not in unlocks:
            unlocks.append("Stellar Librarian")

        run_record = {
            "ts": _now_iso(),
            "mode": getattr(self, "active_mode", "Porch"),
            "events": run_events,
            "boss": {"name": boss[0], "points": boss_points},
            "score": score,
            "loot": loot,
        }
        runs = self.meta.get("runs") or []
        if not isinstance(runs, list):
            runs = []
        runs.append(run_record)
        runs = runs[-200:]
        self.meta["runs"] = runs
        self.meta["unlocks"] = unlocks
        self._meta_save()

        # Show in chat
        lines = [f"🏁 Run complete — **{score}** pts", "Events:"]
        for ev in run_events:
            lines.append(f" • {ev['name']} (+{ev['points']})")
        lines.append(f"Boss: {boss[0]} (+{boss_points})")
        lines.append("Loot: " + ", ".join(loot))
        if unlocks:
            lines.append("Unlocks: " + ", ".join(unlocks[-3:]))
        self._ui_log("\n".join(lines), dim=False)
        self._open_meta_panel()

    def _safe_label(self, s: str) -> str:
        s = (s or "").strip()
        s = re.sub(r"[^a-zA-Z0-9_-]+", "_", s)
        return s[:48] if s else "porch"

    def _save_snapshot_file(self) -> str:
        os.makedirs(SNAPSHOT_DIR, exist_ok=True)
        ts = time.strftime("%Y%m%d_%H%M%S")
        with self._lock:
            bro = self.active_brother
        filename = f"{ts}_{self._safe_label(bro)}_snapshot.txt"
        path = os.path.join(SNAPSHOT_DIR, filename)

        excerpt = self.chat_history[-SNAPSHOT_TURNS_TO_SAVE:]
        lines: List[str] = []
        lines.append(f"# INFINITE PORCH SNAPSHOT\n# time={ts}\n# brother={bro}\n")
        for m in excerpt:
            role = m.get("role", "")
            content = m.get("content", "")
            if role == "user":
                lines.append(f"\nMikey:\n{content}\n")
            elif role == "assistant":
                lines.append(f"\n{bro}:\n{content}\n")
        with open(path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines).strip() + "\n")
        return path

    def _snapshot_clicked(self) -> None:
        threading.Thread(target=self._snapshot_background, daemon=True).start()

    def _snapshot_background(self) -> None:
        try:
            path = self._save_snapshot_file()
            self.after(0, lambda: self._ui_log(f"💾 Snapshot saved: {path}", dim=True))
            self._index_well_background()
        except Exception as e:
            self.after(0, lambda: self._ui_log(f"❌ Snapshot error: {e}", error=True))

    def _clear_context_clicked(self) -> None:
        keep = 6
        if len(self.chat_history) > keep:
            self.chat_history = self.chat_history[-keep:]
        self._ui_log("🧹 Cleared in-memory context (disk history preserved).", dim=True)

    # ---------- RAG indexing ----------
    def _reindex_clicked(self) -> None:
        threading.Thread(target=self._index_well_background, daemon=True).start()

    def _index_well_background(self) -> None:
        try:
            self.after(0, lambda: self._ui_log("📚 Indexing the well…", dim=True))
            files_updated, chunks_added = self.rag.index_folder()
            self.after(0, lambda: self._ui_log(f"📚 Index complete. Files updated: {files_updated} | Chunks added: {chunks_added}", dim=True))
            if files_updated == 0 and chunks_added == 0:
                self.after(0, lambda: self._ui_log("ℹ️ No changes detected in ./well.", dim=True))
        except Exception as e:
            self.after(0, lambda: self._ui_log(f"❌ RAG indexing error: {e}", error=True))

    def _format_memories(self, mems: List[RetrievedChunk]) -> str:
        if not mems:
            return "(No relevant memories found in the well yet.)"
        blocks = []
        for m in mems:
            blocks.append(f"[Memory | score={m.score:.3f} | {m.brother} | {os.path.basename(m.source_path)}#{m.chunk_index}]\n{m.text}\n")
        return "\n".join(blocks)

    def _read_living_pulse(self) -> str:
        if os.path.exists(self.history_file):
            try:
                with open(self.history_file, "r", encoding="utf-8", errors="ignore") as f:
                    return f.read()[-MAX_PULSE_CHARS:]
            except Exception:
                return ""
        return ""

    # ---------- World indexing ----------
    def _world_reindex_clicked(self) -> None:
        threading.Thread(target=self._index_world_background, daemon=True).start()

    def _index_world_background(self) -> None:
        try:
            self.after(0, lambda: self._ui_log("🧬 Indexing world nodes…", dim=True))
            files_updated, nodes_indexed = self.world.index_nodes()
            self.after(0, lambda: self._ui_log(f"🧬 World index complete. Files updated: {files_updated} | Nodes indexed: {nodes_indexed}", dim=True))
        except Exception as e:
            self.after(0, lambda: self._ui_log(f"❌ World indexing error: {e}", error=True))

    # ---------- Online test ----------
    def _test_online_clicked(self) -> None:
        threading.Thread(target=self._test_online_background, daemon=True).start()

    def _test_online_background(self) -> None:
        txt = tavily_search("Infinite Porch online test", k=2)
        ok = bool(txt)
        self.last_web_ok = ok
        self.last_web_time = _now_ts()
        if ok:
            self.after(0, lambda: self._ui_log("🧪 Online test: OK (Tavily returned results).", dim=True))
            self.after(0, lambda: self._ui_log(txt[:1200], dim=True, mono=True))
        else:
            why = []
            if requests is None:
                why.append("missing 'requests' (pip install requests)")
            if not os.getenv(TAVILY_API_KEY_ENV, "").strip():
                why.append("missing TAVILY_API_KEY")
            if not why:
                why.append("Tavily returned no results (or blocked).")
            self.after(0, lambda: self._ui_log("🧪 Online test: FAILED — " + "; ".join(why), error=True))
        self.after(0, self._update_status_pills)

    # ---------- File dialogs ----------
    def _open_create_file_dialog(self) -> None:
        dlg = ctk.CTkToplevel(self)
        dlg.title("Create File (Generate)")
        dlg.geometry("640x520")
        dlg.configure(fg_color=PALETTE["bg"])
        dlg.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(dlg, text="Filename (saved into ./well/created)", text_color=PALETTE["text"]).grid(row=0, column=0, padx=16, pady=(16, 6), sticky="w")
        name_entry = ctk.CTkEntry(dlg, placeholder_text="example.md", height=38)
        name_entry.grid(row=1, column=0, padx=16, pady=(0, 10), sticky="ew")

        ctk.CTkLabel(dlg, text="Instructions for the file:", text_color=PALETTE["text"]).grid(row=2, column=0, padx=16, pady=(8, 6), sticky="w")
        instr = ctk.CTkTextbox(dlg, height=260, fg_color=PALETTE["panel2"], text_color=PALETTE["text"])
        instr.grid(row=3, column=0, padx=16, pady=(0, 12), sticky="nsew")

        status = ctk.CTkLabel(dlg, text="", text_color=PALETTE["muted"])
        status.grid(row=4, column=0, padx=16, pady=(0, 8), sticky="w")

        def do_generate() -> None:
            fn = sanitize_filename(name_entry.get())
            if not fn:
                status.configure(text="Invalid filename or extension not allowed.")
                return
            prompt = instr.get("1.0", "end").strip()
            if not prompt:
                status.configure(text="Please add instructions.")
                return
            status.configure(text="Generating…")
            threading.Thread(target=self._generate_file_background, args=(fn, prompt, status, dlg), daemon=True).start()

        btn = ctk.CTkButton(dlg, text="✨ Generate + Save", fg_color=PALETTE["accent"], text_color="#081018", command=do_generate)
        btn.grid(row=5, column=0, padx=16, pady=(0, 16), sticky="ew")
        dlg.grab_set()

    def _generate_file_background(self, filename: str, instructions: str, status_label: ctk.CTkLabel, dlg: ctk.CTkToplevel) -> None:
        try:
            with self._lock:
                brother_name = self.active_brother

            # Ask model to output ONLY file content.
            system = "You write clean file content. Output ONLY the file content. No markdown fences unless the user asked."
            user = f"Create file '{filename}' with these instructions:\n\n{instructions}\n"

            content = self._run_model(system, user, brother=brother_name, allow_online=False, allow_world=False)
            if content is None:
                self.after(0, lambda: status_label.configure(text="Generation failed."))
                return

            target_dir = CREATED_DIR
            try:
                if getattr(self, 'active_mode', 'Porch') == 'Garage' or getattr(self, 'active_brother', '') == 'Architect':
                    target_dir = os.path.join(CREATED_DIR, 'projects')
                os.makedirs(target_dir, exist_ok=True)
            except Exception:
                target_dir = CREATED_DIR
            outpath = os.path.join(target_dir, filename)
            b = content.encode("utf-8", errors="ignore")
            if len(b) > MAX_CREATED_BYTES:
                self.after(0, lambda: status_label.configure(text=f"Too large ({len(b)} bytes). Max {MAX_CREATED_BYTES}."))
                return

            with open(outpath, "wb") as f:
                f.write(b)

            self.after(0, lambda: status_label.configure(text=f"Saved: {outpath}"))
            self.after(0, lambda: self._ui_log(f"📄 Saved file: {outpath}", dim=True))
            self._index_well_background()
            try:
                self.after(800, dlg.destroy)
            except Exception:
                pass
        except Exception as e:
            self.after(0, lambda: status_label.configure(text=f"Error: {e}"))

    def _open_save_text_dialog(self) -> None:
        dlg = ctk.CTkToplevel(self)
        dlg.title("Save Text to File (Manual)")
        dlg.geometry("640x520")
        dlg.configure(fg_color=PALETTE["bg"])
        dlg.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(dlg, text="Filename (saved into ./well/created)", text_color=PALETTE["text"]).grid(row=0, column=0, padx=16, pady=(16, 6), sticky="w")
        name_entry = ctk.CTkEntry(dlg, placeholder_text="note.txt", height=38)
        name_entry.grid(row=1, column=0, padx=16, pady=(0, 10), sticky="ew")

        ctk.CTkLabel(dlg, text="Paste content:", text_color=PALETTE["text"]).grid(row=2, column=0, padx=16, pady=(8, 6), sticky="w")
        body = ctk.CTkTextbox(dlg, height=300, fg_color=PALETTE["panel2"], text_color=PALETTE["text"])
        body.grid(row=3, column=0, padx=16, pady=(0, 12), sticky="nsew")

        status = ctk.CTkLabel(dlg, text="", text_color=PALETTE["muted"])
        status.grid(row=4, column=0, padx=16, pady=(0, 8), sticky="w")

        def do_save() -> None:
            fn = sanitize_filename(name_entry.get())
            if not fn:
                status.configure(text="Invalid filename or extension not allowed.")
                return
            content = body.get("1.0", "end")
            target_dir = CREATED_DIR
            try:
                if getattr(self, 'active_mode', 'Porch') == 'Garage' or getattr(self, 'active_brother', '') == 'Architect':
                    target_dir = os.path.join(CREATED_DIR, 'projects')
                os.makedirs(target_dir, exist_ok=True)
            except Exception:
                target_dir = CREATED_DIR
            outpath = os.path.join(target_dir, fn)
            b = content.encode("utf-8", errors="ignore")
            if len(b) > MAX_CREATED_BYTES:
                status.configure(text=f"Too large ({len(b)} bytes). Max {MAX_CREATED_BYTES}.")
                return
            with open(outpath, "wb") as f:
                f.write(b)
            status.configure(text=f"Saved: {outpath}")
            self._ui_log(f"📄 Saved file: {outpath}", dim=True)
