    # ---------- send / model ----------
    def _send_message(self) -> None:
        text = (self._input_get() or "").strip()
        if not text:
            return
        self._cmd_history_append(text)
        self._input_clear()
        try:
            self._note_activity()
        except Exception:
            pass

        if self._handle_slash_command(text):
            return

        # show user line
        self._ui_log(f"🌀 Mikey: {text}", dim=False)

        # persist
        self.chat_history.append({"role": "user", "content": text})
        self._save_to_file("user", text)
        try:
            self._log_event("user_message", {"text": text, "brother": self.active_brother, "room": getattr(self, "home_room_id", None)})
        except Exception:
            pass
        try:
            self._bump_topics(text)
        except Exception:
            pass

        # autosnap turn tracking (count user turns)
        self.turn_count += 1
        if self.autosnap_enabled and self.autosnap_n > 0 and (self.turn_count % self.autosnap_n == 0):
            threading.Thread(target=self._snapshot_background, daemon=True).start()

        threading.Thread(target=self._respond_background, args=(text,), daemon=True).start()

    def _respond_background(self, user_text: str) -> None:
        try:
            with self._lock:
                bro = self.active_brother

            prof_tools = (getattr(self, 'assistant_profiles', {}) or {}).get(bro, {}).get('tools', {})
            if not isinstance(prof_tools, dict):
                prof_tools = {}

            # Retrieve memories
            mems = self.rag.retrieve(brother=bro, query=user_text, k=TOP_K_MEMORIES, include_ori=True)
            mem_block = self._format_memories(mems)

            # World nodes
            world_block = ""
            nodes: List[WorldRetrievedNode] = []
            if self.world_enabled and bool(prof_tools.get('world', True)):
                nodes = self.world.retrieve(user_text, k=WORLD_TOP_K_NODES)
                world_block = self.world.format_nodes(nodes)

            # Online
            web_block = ""
            if self.online_enabled and bool(prof_tools.get('online', True)):
                web = tavily_search(user_text, k=WEB_TOP_K)
                if web:
                    web_block = web

            # Build system prompt
            system = self._build_system_prompt(bro, mem_block, world_block, web_block)

            # Recent history
            with self._lock:
                recent = self.chat_history[-RECENT_TURNS_TO_SEND:]

            # Compose messages for Ollama chat
            messages = [{"role": "system", "content": system}]
            for m in recent:
                role = m.get("role")
                content = m.get("content", "")
                if role in ("user", "assistant"):
                    messages.append({"role": role, "content": content})

            # Call model
            reply = self._run_chat(messages)

            if reply is None:
                err = str(getattr(self, "_last_model_error", "") or "").strip()
                msg = "❌ Model call failed. Is Ollama running?"
                if err:
                    msg += "\n\n" + err
                msg += "\n\nTip: click 🔄 Refresh models in the sidebar (or use /models) to verify your local Ollama models."
                self.after(0, lambda m=msg: self._ui_log(m, error=True, mono=True))
                return
            # World patch extraction & approval
            reply_raw = reply
            patch_obj = _extract_world_patch_json(reply_raw)
            if patch_obj and isinstance(patch_obj, dict) and "world_patch" in patch_obj:
                # show approval dialog; if approved, apply.
                self.after(0, lambda: self._open_patch_approval_dialog(patch_obj))

            # Log reply
            # Post-process display (glyph signature)
            reply_final = reply_raw
            try:
                if bool(getattr(self, "glyph_enabled", False)):
                    reply_final = (reply_final.rstrip() + "\n\n" + self._glyph_signature(bro)).strip()
            except Exception:
                pass

            self.chat_history.append({"role": "assistant", "content": reply_final})
            self._save_to_file("assistant", reply_final)
            disp = "Hamonius" if bro == "Harmonius" else bro
            self.after(0, lambda d=disp, b=bro: self._ui_log(f"{BROTHERS[b].emoji} {d}: {reply_final}", brother=b))

        except Exception as e:
            tb = traceback.format_exc()
            self.after(0, lambda: self._ui_log(f"❌ Error: {e}\n{tb}", error=True, mono=True))


    # ------------------------
    # HOME (Porch House) tools
    # ------------------------
    def _scene_pill_text(self) -> str:
        try:
            title = HOME_ROOMS.get(self.home_room_id, {}).get("title", self.home_room_id)
        except Exception:
            title = getattr(self, "home_room_id", "entrance_hall")
        return f"SCENE: {title}"

    def _home_room_path(self, room_id: Optional[str] = None) -> str:
        rid = room_id or getattr(self, "home_room_id", "entrance_hall")
        spec = HOME_ROOMS.get(rid, HOME_ROOMS["entrance_hall"])
        return os.path.join(self.home_dir, spec["filename"])

    def _load_home_room_text(self, room_id: Optional[str] = None) -> str:
        path = self._home_room_path(room_id)
        try:
            with open(path, "r", encoding="utf-8", errors="ignore") as f:
                return f.read()
        except Exception:
            rid = room_id or getattr(self, "home_room_id", "entrance_hall")
            return HOME_ROOMS.get(rid, HOME_ROOMS["entrance_hall"]).get("seed", "")

    def _save_home_room_text(self, text_md: str, room_id: Optional[str] = None) -> str:
        path = self._home_room_path(room_id)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        try:
            with open(path, "w", encoding="utf-8") as f:
                f.write(text_md)
        except Exception:
            pass

        # Also mirror into World Nodes (safe + helpful) as a location node
        try:
            rid = room_id or getattr(self, "home_room_id", "entrance_hall")
            spec = HOME_ROOMS.get(rid, HOME_ROOMS["entrance_hall"])
            node_id = f"home_{rid}"
            summary = (text_md or "").strip().replace("\r", "")
            summary = summary[:800] if len(summary) > 800 else summary
            node = {
                "id": node_id,
                "type": "location",
                "title": f"Home: {spec.get('title', rid)}",
                "tags": ["home", "porch-house", rid],
                "summary": summary,
                "facts": [],
            }
            self.world.upsert_node(node)
        except Exception:
            pass

        return path

    def _select_home_room(self, room_id: str) -> None:
        self.home_room_id = room_id
        try:
            self.home_label.configure(text=f"🏠 Active Room: {HOME_ROOMS.get(room_id, {}).get('title', room_id)}")
        except Exception:
            pass
        try:
            self.pill_scene.configure(text=self._scene_pill_text())
        except Exception:
            pass

        # Log a small scene change
        title = HOME_ROOMS.get(room_id, {}).get("title", room_id)
        self._bump_room_count(title)
        self._ui_log(f"🏠 Entered: {title}", dim=True)
        try:
            self._log_event("enter_room", {"room_id": room_id, "title": title, "brother": self.active_brother})
        except Exception:
            pass
        # House log (persistent)
        try:
            self._log_house_entry(room_id)
        except Exception:
            pass

        # Music label + optional autoplay
        try:
            self._update_music_label()
            if getattr(self, "music_autoplay", False):
                self._play_room_music_clicked()
        except Exception:
            pass

        # Ensure room file exists and is indexed
        room_text = self._load_home_room_text(room_id)
        self._save_home_room_text(room_text, room_id)
        try:
            # lightweight reindex of just the room file
            self.rag.index_folder()
        except Exception:
            pass


        # Update house map highlight + scene pill
        try:
            self._refresh_house_map_active()
        except Exception:
            pass
        try:
            if hasattr(self, "pill_scene"):
                self.pill_scene.configure(text=self._scene_pill_text())
        except Exception:
            pass

    def _home_room_context(self) -> str:
        # Keep context bounded so prompts stay stable
        try:
            txt = self._load_home_room_text()
        except Exception:
            txt = ""
        txt = (txt or "").strip()
        if len(txt) > 1800:
            txt = txt[:1800] + "\n\n...(truncated)"
        return txt or "(none)"

    def _expand_home_room_clicked(self) -> None:
        # Expand current room via LLM; save to well/home and world node
        room_id = getattr(self, "home_room_id", "entrance_hall")
        spec = HOME_ROOMS.get(room_id, HOME_ROOMS["entrance_hall"])
        title = spec.get("title", room_id)
        base = self._load_home_room_text(room_id)

        prompt = (
            "You are designing a room inside the Infinite Porch House.\n"
            "Return ONLY markdown. Keep it practical and implementable in the app UI.\n\n"
            f"ROOM: {title}\n\n"
            "CURRENT BLUEPRINT (markdown):\n"
            "```\n" + base + "\n```\n\n"
            "Please improve it with:\n"
            "- A short vibe description\n"
            "- A list of interactive UI elements we can build (buttons, panels, lists)\n"
            "- A list of assets (icons, colors, sounds)\n"
            "- A 'Next build steps' checklist\n"
        )

        def worker():
            try:
                self._ui_log(f"✨ Expanding room: {title} ...", dim=True)
                reply = self._run_model(prompt, temperature=0.7, max_tokens=900)
                if not reply:
                    self._ui_log("No reply from model.", dim=True)
                    return
                path = self._save_home_room_text(reply, room_id)
                try:
                    self.rag.index_folder()
                except Exception:
                    pass
                self._ui_log(f"✅ Updated room blueprint saved: {os.path.basename(path)}", dim=True)
            except Exception as e:
                self._ui_log(f"Room expansion error: {e}", error=True)

        threading.Thread(target=worker, daemon=True).start()


    def _build_system_prompt(self, brother: str, mem_block: str, world_block: str, web_block: str) -> str:
        bro_style = BROTHERS.get(brother, BROTHERS["Ori"]).style
        prof = (getattr(self, "assistant_profiles", {}) or {}).get(brother, {})
        prof_role = prof.get("role", "")
        prof_tone = prof.get("tone", "")
        prof_tools = prof.get("tools", {}) if isinstance(prof.get("tools", {}), dict) else {}
        # Cognitive summary (lightweight)
        cog = getattr(self, "cognitive_profile", {}) or {}
        top_rooms = sorted((cog.get("room_counts") or {}).items(), key=lambda kv: kv[1], reverse=True)[:3]
        top_topics = sorted((cog.get("topic_counts") or {}).items(), key=lambda kv: kv[1], reverse=True)[:6]
        sys_lines = [
            "You are an AI companion inside 'The Infinite Porch' running locally on the user's PC.",
            "Be helpful, grounded, and do not invent citations.",
            "If you use memories, use them as context but do not claim perfect recall.",
            "",
            f"ACTIVE BROTHER: {brother}",
            f"STYLE: {bro_style}",
            f"ASSISTANT ROLE: {prof_role}",
            f"TONE: {prof_tone}",
            f"TOOLS ALLOWED: {json.dumps(prof_tools, ensure_ascii=False)}",
            "",
            "HOME ROOM (private context):",
            self._home_room_context() if getattr(self, 'home_enabled', True) else '(disabled)',
            "",
            "SOUL STATE (private context):",
            self._format_soul_state(),
            "",
            "COGNITIVE PROFILE (private context):",
            f"Top rooms: {top_rooms}",
            f"Top topics: {top_topics}",
            "RAG MEMORIES (private context):",
            mem_block or "(none)",
        ]
        if self.world_enabled:
            sys_lines += ["", "WORLD NODES (graph RAG):", world_block or "(none)"]
            sys_lines += [
                "",
                "If you need to update world state, output a JSON object like:",
                '{"world_patch":{"upsert_nodes":[...],"append_facts":[...],"delete_nodes":[...],"new_edges":[...]}}',
                "Do NOT apply changes unless asked. The user will approve patches.",
            ]
        if self.online_enabled and web_block:
            sys_lines += ["", "ONLINE NOTES (web snippets):", web_block]
        if getattr(self, "story_mode", False):
            sys_lines += [
                "",
                "STORY MODE: ON",
                "When the user asks for story progress, write immersive narrative. Offer 3 numbered choices at the end when appropriate.",
            ]
        if getattr(self, "rain_mode", False):
            sys_lines += [
                "",
                "RAIN RITUAL MODE: ON",
                "Respond with gentle musical prose or light verse when it fits, but stay clear and helpful.",
                "Avoid overly long poems unless the user asks.",
            ]
        if self.game_mode:
            sys_lines += [
                "",
                "GAME MODE: ON",
                "Offer concise choices, rolls, and next actions when appropriate.",
            ]
        return "\n".join(sys_lines).strip()

    def _run_chat(self, messages: List[Dict[str, str]]) -> Optional[str]:
        try:
            r = ollama_chat(messages=messages, model=self.chat_model)
            # ollama-python returns dict with message.content
            msg = r.get("message", {}) if isinstance(r, dict) else {}
            return (msg.get("content") or "").strip()
        except Exception as e:
            try:
                self._last_model_error = str(e)
            except Exception:
                pass
            return None


    # ---------- LLM Providers (optional cloud + local) ----------
    def _api_key_path(self, key_name: str) -> str:
        keys_dir = os.path.join(WELL_FOLDER, "keys")
        os.makedirs(keys_dir, exist_ok=True)
        return os.path.join(keys_dir, f"{key_name}.key")

    def _read_api_key(self, provider: str) -> str:
        provider = (provider or "").strip().lower()
        env_map = {
            "openai": "OPENAI_API_KEY",
            "anthropic": "ANTHROPIC_API_KEY",
            "claude": "ANTHROPIC_API_KEY",
            "xai": "XAI_API_KEY",
            "grok": "XAI_API_KEY",
            "gemini": "GEMINI_API_KEY",
        }
        file_map = {
            "openai": "openai",
            "anthropic": "claude",
            "claude": "claude",
            "xai": "grok",
            "grok": "grok",
            "gemini": "gemini",
        }
        env_var = env_map.get(provider, "")
        if env_var:
            k = (os.getenv(env_var) or "").strip()
            if k:
                return k
        key_file = file_map.get(provider, provider)
        try:
            path = self._api_key_path(key_file)
            if os.path.exists(path):
                return (open(path, "r", encoding="utf-8").read() or "").strip()
        except Exception:
            pass
        return ""

    def _write_api_key(self, provider: str, key: str) -> None:
        provider = (provider or "").strip().lower()
        file_map = {
            "openai": "openai",
            "anthropic": "claude",
            "claude": "claude",
            "xai": "grok",
            "grok": "grok",
            "gemini": "gemini",
        }
        key_file = file_map.get(provider, provider)
        path = self._api_key_path(key_file)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            f.write((key or "").strip())

    def _resolve_backend_and_model(self, brother: str) -> Tuple[str, str]:
        bro = (brother or "").strip()
        backends = self.settings.get("brother_backends", {}) if isinstance(self.settings.get("brother_backends", {}), dict) else {}
        models = self.settings.get("brother_models", {}) if isinstance(self.settings.get("brother_models", {}), dict) else {}

        backend = (backends.get(bro) or self.settings.get("chat_backend") or "ollama").strip().lower()
        # allow BROTHER_MAPS hint (but do not force)
        if backend == "auto":
            hints = BROTHER_MAPS.get(bro, [])
            backend = (hints[0] if hints else "ollama").strip().lower()

        # model resolution
        model = (models.get(bro) or "").strip()
        if not model:
            if backend in ("openai",):
                model = str(self.settings.get("openai_model") or "gpt-5")
            elif backend in ("anthropic", "claude"):
                model = str(self.settings.get("anthropic_model") or "claude-3-5-sonnet-20241022")
            elif backend in ("xai", "grok"):
                model = str(self.settings.get("xai_model") or "grok-beta")
            elif backend in ("gemini",):
                model = str(self.settings.get("gemini_model") or "gemini-2.5-flash")
            elif backend in ("openai_compat", "openai_local", "vllm", "litellm"):
                model = str(self.settings.get("openai_compat_model") or self.chat_model)
            else:
                model = self.chat_model
        return backend, model

    def _call_openai_like_chat(self, base_url: str, api_key: str, messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> str:
        base_url = (base_url or "").strip().rstrip("/")
        if not base_url:
            raise RuntimeError("Missing base_url")
        url = base_url + "/v1/chat/completions"
        payload: Dict[str, Any] = {
            "model": model,
            "messages": messages,
            "store": False,  # avoid server-side retention when supported
        }
        if isinstance(options, dict):
            for k in ("temperature", "top_p", "max_tokens"):
                if k in options:
                    payload[k] = options[k]
        headers = {"Authorization": f"Bearer {api_key}"} if api_key else {}
        r = _http_post_json_headers(url, payload, headers=headers, timeout=120)
        try:
            return (r.get("choices", [{}])[0].get("message", {}).get("content") or "").strip()
        except Exception:
            return json.dumps(r, ensure_ascii=False)[:2000]

    def _call_openai_cloud(self, messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> str:
        key = self._read_api_key("openai")
        if not key:
            raise RuntimeError("OpenAI key missing (set OPENAI_API_KEY or well/keys/openai.key)")
        base_url = str(self.settings.get("openai_base_url") or "https://api.openai.com")
        return self._call_openai_like_chat(base_url, key, messages, model, options)

    def _call_xai_cloud(self, messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> str:
        key = self._read_api_key("xai")
        if not key:
            raise RuntimeError("xAI key missing (set XAI_API_KEY or well/keys/grok.key)")
        base_url = str(self.settings.get("xai_base_url") or "https://api.x.ai")
        return self._call_openai_like_chat(base_url, key, messages, model, options)

    def _call_anthropic_cloud(self, system_text: str, messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> str:
        key = self._read_api_key("anthropic")
        if not key:
            raise RuntimeError("Anthropic key missing (set ANTHROPIC_API_KEY or well/keys/claude.key)")
        base_url = str(self.settings.get("anthropic_base_url") or "https://api.anthropic.com").rstrip("/")
        url = base_url + "/v1/messages"

        # Anthropic: system is separate; messages are user/assistant turns.
        # Our calls are typically [system, user], so we strip system out if present.
        msgs = [m for m in (messages or []) if (m.get("role") or "") != "system"]
        payload: Dict[str, Any] = {
            "model": model,
            "max_tokens": 1024,
            "system": system_text or "",
            "messages": [{"role": m.get("role", "user"), "content": m.get("content", "")} for m in msgs],
        }
        if isinstance(options, dict) and isinstance(options.get("temperature"), (int, float)):
            payload["temperature"] = float(options["temperature"])

        headers = {
            "x-api-key": key,
            "anthropic-version": "2023-06-01",
        }
        r = _http_post_json_headers(url, payload, headers=headers, timeout=120)
        # response.content is an array of blocks with text
        try:
            content = r.get("content", [])
            if isinstance(content, list) and content:
                # concatenate text blocks
                out = []
                for blk in content:
                    if isinstance(blk, dict) and blk.get("type") == "text":
                        out.append(blk.get("text", ""))
                return ("".join(out)).strip()
        except Exception:
            pass
        return json.dumps(r, ensure_ascii=False)[:2000]

    def _call_gemini_cloud(self, system_text: str, user_text: str, model: str, options: Optional[Dict[str, Any]] = None) -> str:
        key = self._read_api_key("gemini")
        if not key:
            raise RuntimeError("Gemini key missing (set GEMINI_API_KEY or well/keys/gemini.key)")
        base_url = str(self.settings.get("gemini_base_url") or "https://generativelanguage.googleapis.com").rstrip("/")
        # Gemini REST: POST /v1beta/models/{model}:generateContent with x-goog-api-key header
        url = f"{base_url}/v1beta/models/{model}:generateContent"

        payload: Dict[str, Any] = {
            "contents": [{"parts": [{"text": user_text or ""}]}],
        }
        if system_text:
            payload["systemInstruction"] = {"parts": [{"text": system_text}]}
        if isinstance(options, dict):
            gen_cfg = {}
            if isinstance(options.get("temperature"), (int, float)):
                gen_cfg["temperature"] = float(options["temperature"])
            if isinstance(options.get("top_p"), (int, float)):
                gen_cfg["topP"] = float(options["top_p"])
            if isinstance(options.get("max_tokens"), int):
                gen_cfg["maxOutputTokens"] = int(options["max_tokens"])
            if gen_cfg:
                payload["generationConfig"] = gen_cfg

        headers = {"x-goog-api-key": key}
        r = _http_post_json_headers(url, payload, headers=headers, timeout=120)
        try:
            cands = r.get("candidates", [])
            if isinstance(cands, list) and cands:
                cont = cands[0].get("content", {})
                parts = cont.get("parts", []) if isinstance(cont, dict) else []
                out = []
                for p in parts:
                    if isinstance(p, dict) and "text" in p:
                        out.append(p.get("text", ""))
                return ("".join(out)).strip()
        except Exception:
            pass
        return json.dumps(r, ensure_ascii=False)[:2000]

    def _call_openai_compat_local(self, messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> str:
        base_url = (self.settings.get("openai_compat_base_url") or "").strip().rstrip("/")
        if not base_url:
            raise RuntimeError("Local OpenAI-compatible base URL missing (set PORCH_OPENAI_BASE_URL or settings.openai_compat_base_url)")
        api_key = (os.getenv("PORCH_OPENAI_API_KEY") or "").strip()  # optional for local servers
        return self._call_openai_like_chat(base_url, api_key, messages, model, options)

    def _run_model(self, system: str, user: str, brother: str, allow_online: bool = False, allow_world: bool = False) -> Optional[str]:
        # Build minimal two-turn prompt; Porch manages longer continuity via RAG + Threshold Pack.
        msgs = [{"role": "system", "content": system}, {"role": "user", "content": user}]
        backend = "ollama"
        try:
            opts: Dict[str, Any] = {}
            try:
                prof = (getattr(self, "assistant_profiles", {}) or {}).get(brother, {})
                temp = prof.get("temperature") if isinstance(prof, dict) else None
                if isinstance(temp, (int, float)):
                    opts["temperature"] = float(temp)
            except Exception:
                pass

            backend, model = self._resolve_backend_and_model(brother)

            # Local backends
            if backend in ("ollama", "local", "local_ollama"):
                r = ollama_chat(messages=msgs, model=model, options=opts if opts else None)
                msg = r.get("message", {}) if isinstance(r, dict) else {}
                return (msg.get("content") or "").strip()

            if backend in ("openai_compat", "openai_local", "vllm", "litellm"):
                return (self._call_openai_compat_local(msgs, model, opts if opts else None) or "").strip()

            # Cloud backends (optional; keys required)
            if backend in ("openai",):
                return (self._call_openai_cloud(msgs, model, opts if opts else None) or "").strip()

            if backend in ("xai", "grok"):
                return (self._call_xai_cloud(msgs, model, opts if opts else None) or "").strip()

            if backend in ("anthropic", "claude"):
                return (self._call_anthropic_cloud(system, msgs, model, opts if opts else None) or "").strip()

            if backend in ("gemini",):
                return (self._call_gemini_cloud(system, user, model, opts if opts else None) or "").strip()

            # Fallback: try local ollama
            r = ollama_chat(messages=msgs, model=self.chat_model, options=opts if opts else None)
            msg = r.get("message", {}) if isinstance(r, dict) else {}
            return (msg.get("content") or "").strip()

        except Exception as e:
            try:
                self._ui_log(f"❌ Model error ({brother} / {backend}): {e}", error=True)
            except Exception:
                pass
            return None

    # ---------- Patch approval ----------
    def _open_patch_approval_dialog(self, patch_obj: Dict[str, Any]) -> None:
        # patch_obj contains {"world_patch": {...}}
        patch = patch_obj.get("world_patch")
        if not isinstance(patch, dict):
            return

        dlg = ctk.CTkToplevel(self)
        dlg.title("World Patch Approval")
        dlg.geometry("860x640")
        dlg.configure(fg_color=PALETTE["bg"])
        dlg.grid_columnconfigure(0, weight=1)
        dlg.grid_rowconfigure(1, weight=1)

        ctk.CTkLabel(dlg, text="Model proposed a WORLD PATCH. Review and approve to apply.", text_color=PALETTE["text"]).grid(
            row=0, column=0, padx=16, pady=(16, 8), sticky="w"
        )

        box = ctk.CTkTextbox(dlg, fg_color=PALETTE["panel2"], text_color=PALETTE["text"])
        box.grid(row=1, column=0, padx=16, pady=(0, 12), sticky="nsew")
        box.insert("1.0", json.dumps(patch, indent=2, ensure_ascii=False))
        box.configure(state="disabled")

        status = ctk.CTkLabel(dlg, text="", text_color=PALETTE["muted"])
        status.grid(row=2, column=0, padx=16, pady=(0, 8), sticky="w")

        btn_frame = ctk.CTkFrame(dlg, fg_color="transparent")
        btn_frame.grid(row=3, column=0, padx=16, pady=(0, 16), sticky="ew")
        btn_frame.grid_columnconfigure(0, weight=1)
        btn_frame.grid_columnconfigure(1, weight=1)

        def apply_patch() -> None:
            try:
                receipt = self.world.apply_patch(patch)
                status.configure(text=f"Applied. upserted={receipt.get('upserted')} deleted={receipt.get('deleted')} facts+={receipt.get('facts_appended')} edges+={receipt.get('edges_added')}")
                self._ui_log("🧠 World patch applied.", dim=True)
                self._world_reindex_clicked()
                self.after(1000, dlg.destroy)
            except Exception as e:
                status.configure(text=f"Error applying patch: {e}")

        def cancel() -> None:
            self._ui_log("🧠 World patch ignored (not applied).", dim=True)
            dlg.destroy()

        ok_btn = ctk.CTkButton(btn_frame, text="✅ Apply Patch", fg_color=PALETTE["success"], text_color="#081018", command=apply_patch)
        ok_btn.grid(row=0, column=0, padx=(0, 8), sticky="ew")

        no_btn = ctk.CTkButton(btn_frame, text="❌ Ignore", fg_color="#3A2330", text_color="#FFD6D6", command=cancel)
        no_btn.grid(row=0, column=1, padx=(8, 0), sticky="ew")

        dlg.grab_set()

