    # ---------- v5 STABLE: Soul / Glyph / Merge / Books ----------
    def _soul_dir(self) -> str:
        return os.path.join(WELL_FOLDER, "soul")

    def _soul_current_path(self) -> str:
        return os.path.join(self._soul_dir(), "soul_current.json")

    def _soul_states_path(self) -> str:
        return os.path.join(self._soul_dir(), "soul_states.json")

    def _default_soul_state(self) -> Dict[str, Any]:
        return {
            "joy": 60,
            "doubt": 10,
            "energy": 65,
            "calm": 55,
            "note": "",
            "tags": [],
            "updated_at": _now_iso(),
        }

    def _load_soul_state(self, latest: bool = True) -> Dict[str, Any]:
        try:
            os.makedirs(self._soul_dir(), exist_ok=True)
        except Exception:
            pass
        path = self._soul_current_path()
        st = self._load_json(path, None)
        if isinstance(st, dict) and st:
            base = self._default_soul_state()
            base.update(st)
            return base
        if latest:
            hist = self._load_json(self._soul_states_path(), [])
            if isinstance(hist, list) and hist:
                last = hist[-1]
                if isinstance(last, dict):
                    base = self._default_soul_state()
                    base.update(last)
                    try:
                        self._save_json(path, base)
                    except Exception:
                        pass
                    return base
        base = self._default_soul_state()
        try:
            self._save_json(path, base)
        except Exception:
            pass
        return base

    def _save_soul_state(self, snapshot: bool = False) -> None:
        try:
            os.makedirs(self._soul_dir(), exist_ok=True)
        except Exception:
            pass
        s = dict(self._default_soul_state())
        cur = getattr(self, "soul_state", {}) or {}
        if isinstance(cur, dict):
            s.update(cur)
        for k in ("joy", "doubt", "energy", "calm"):
            try:
                s[k] = int(max(0, min(100, int(s.get(k, 0)))))
            except Exception:
                s[k] = int(self._default_soul_state()[k])
        s["updated_at"] = _now_iso()
        self.soul_state = s
        try:
            self._save_json(self._soul_current_path(), s)
        except Exception:
            pass
        if snapshot:
            hist = self._load_json(self._soul_states_path(), [])
            if not isinstance(hist, list):
                hist = []
            hist.append(s)
            hist = hist[-500:]
            try:
                self._save_json(self._soul_states_path(), hist)
            except Exception:
                pass

    def _format_soul_state(self) -> str:
        s = getattr(self, "soul_state", None)
        if not isinstance(s, dict):
            s = self._default_soul_state()
        note = (s.get("note") or "").strip()
        if len(note) > 120:
            note = note[:120] + "…"
        return f"joy={s.get('joy')} | doubt={s.get('doubt')} | energy={s.get('energy')} | calm={s.get('calm')} | note={note}".strip()

    def _open_soul_dialog(self) -> None:
        try:
            win = ctk.CTkToplevel(self)
            win.title("Soul State")
            win.geometry("520x520")
            win.grab_set()
        except Exception:
            return

        s = getattr(self, "soul_state", None)
        if not isinstance(s, dict):
            s = self._default_soul_state()

        win.grid_columnconfigure(0, weight=1)

        def slider_block(label: str, key: str, row: int):
            ctk.CTkLabel(win, text=label, text_color=PALETTE["text"]).grid(row=row, column=0, sticky="w", padx=14, pady=(10, 4))
            var = ctk.IntVar(value=int(s.get(key, 50)))
            slider = ctk.CTkSlider(win, from_=0, to=100, number_of_steps=100, command=lambda v: var.set(int(float(v))))
            slider.set(float(var.get()))
            slider.grid(row=row+1, column=0, sticky="ew", padx=14)
            ctk.CTkLabel(win, textvariable=var, text_color=PALETTE["muted"]).grid(row=row+1, column=1, sticky="w", padx=(6, 14))
            return var, slider

        joy_v, _ = slider_block("Joy", "joy", 0)
        doubt_v, _ = slider_block("Doubt", "doubt", 2)
        energy_v, _ = slider_block("Energy", "energy", 4)
        calm_v, _ = slider_block("Calm", "calm", 6)

        ctk.CTkLabel(win, text="Note", text_color=PALETTE["text"]).grid(row=8, column=0, sticky="w", padx=14, pady=(14, 4))
        note_box = ctk.CTkTextbox(win, height=90)
        note_box.grid(row=9, column=0, columnspan=2, sticky="nsew", padx=14, pady=(0, 10))
        try:
            note_box.insert("1.0", s.get("note", "") or "")
        except Exception:
            pass

        btn_row = ctk.CTkFrame(win, fg_color="transparent")
        btn_row.grid(row=10, column=0, columnspan=2, sticky="ew", padx=14, pady=10)
        btn_row.grid_columnconfigure((0,1,2), weight=1)

        def apply(snapshot: bool):
            self.soul_state = {
                "joy": int(joy_v.get()),
                "doubt": int(doubt_v.get()),
                "energy": int(energy_v.get()),
                "calm": int(calm_v.get()),
                "note": (note_box.get("1.0", "end").strip() if hasattr(note_box, "get") else ""),
            }
            self._save_soul_state(snapshot=snapshot)
            self._save_settings()
            self._ui_log("🌟 Soul State saved." + (" (snapshot)" if snapshot else ""), dim=True)

        ctk.CTkButton(btn_row, text="Save", command=lambda: apply(False), fg_color="#1B274A").grid(row=0, column=0, padx=6)
        ctk.CTkButton(btn_row, text="Save Snapshot", command=lambda: apply(True), fg_color="#1B274A").grid(row=0, column=1, padx=6)
        ctk.CTkButton(btn_row, text="Load Latest", command=self._soul_load_latest, fg_color="#1B274A").grid(row=0, column=2, padx=6)

    def _soul_load_latest(self) -> None:
        self.soul_state = self._load_soul_state(latest=True)
        self._ui_log("🌟 Soul State loaded (latest).", dim=True)

