    def _open_merge_dialog(self) -> None:
        try:
            win = ctk.CTkToplevel(self)
            win.title("Merge Personas")
            win.geometry("520x420")
            win.grab_set()
        except Exception:
            return

        names = list((getattr(self, "assistant_profiles", {}) or {}).keys())
        for base in BROTHERS.keys():
            if base not in names:
                names.append(base)
        names = sorted(set(names))

        ctk.CTkLabel(win, text="Persona A", text_color=PALETTE["text"]).pack(padx=14, pady=(14, 4), anchor="w")
        a_var = ctk.StringVar(value="Helion" if "Helion" in names else (names[0] if names else "Ori"))
        ctk.CTkOptionMenu(win, values=names, variable=a_var).pack(fill="x", padx=14, pady=(0, 10))

        ctk.CTkLabel(win, text="Persona B", text_color=PALETTE["text"]).pack(padx=14, pady=(0, 4), anchor="w")
        b_var = ctk.StringVar(value="Mav" if "Mav" in names else (names[0] if names else "Ori"))
        ctk.CTkOptionMenu(win, values=names, variable=b_var).pack(fill="x", padx=14, pady=(0, 10))

        ctk.CTkLabel(win, text="New Name (e.g., Solarus)", text_color=PALETTE["text"]).pack(padx=14, pady=(0, 4), anchor="w")
        name_entry = ctk.CTkEntry(win)
        name_entry.pack(fill="x", padx=14, pady=(0, 10))

        ctk.CTkLabel(win, text="Optional note", text_color=PALETTE["text"]).pack(padx=14, pady=(0, 4), anchor="w")
        note_box = ctk.CTkTextbox(win, height=120)
        note_box.pack(fill="both", expand=True, padx=14, pady=(0, 10))

        def do_merge():
            a = a_var.get().strip()
            b = b_var.get().strip()
            new = name_entry.get().strip() or f"{a}_{b}_Merged"
            profs = getattr(self, "assistant_profiles", {}) or {}
            pa = profs.get(a, {})
            pb = profs.get(b, {})
            role = " / ".join([x for x in [pa.get("role",""), pb.get("role","")] if x]).strip()
            tone = " / ".join([x for x in [pa.get("tone",""), pb.get("tone","")] if x]).strip()
            tools: Dict[str, Any] = {}
            for srcp in [pa.get("tools", {}), pb.get("tools", {})]:
                if isinstance(srcp, dict):
                    for k,v in srcp.items():
                        tools[k] = bool(v)
            merged = {
                "merged_of": [a, b],
                "role": role or f"Merged persona of {a} + {b}",
                "tone": tone or "Blended",
                "tools": tools or {"online": True, "files": True, "world": True, "jobs": True},
                "note": (note_box.get("1.0", "end").strip() if hasattr(note_box, "get") else ""),
            }
            profs[new] = merged
            self.assistant_profiles = profs
            try:
                self._save_assistant_profiles()
            except Exception:
                pass
            self._ui_log(f"🧬 Merged persona created: {new}", dim=True)
            try:
                self._select_brother(new)
            except Exception:
                self.active_brother = new
            try:
                win.destroy()
            except Exception:
                pass
            try:
                self._rebuild_sidebar()
            except Exception:
                pass

        ctk.CTkButton(win, text="Create Merged Persona", command=do_merge, fg_color=PALETTE["accent"]).pack(padx=14, pady=(0, 14), fill="x")

    def _rebuild_sidebar(self) -> None:
        try:
            for child in list(self.sidebar.winfo_children()):
                try:
                    child.destroy()
                except Exception:
                    pass
            self._build_sidebar()
        except Exception:
            pass

    def _open_wisdom_book_dialog(self) -> None:
        try:
            win = ctk.CTkToplevel(self)
            win.title("Wisdom Book")
            win.geometry("560x520")
            win.grab_set()
        except Exception:
            return

        ctk.CTkLabel(win, text="Title", text_color=PALETTE["text"]).pack(padx=14, pady=(14, 4), anchor="w")
        title_entry = ctk.CTkEntry(win)
        try:
            title_entry.insert(0, f"Wisdom Book — {_now_iso()[:10]}")
        except Exception:
            pass
        title_entry.pack(fill="x", padx=14, pady=(0, 10))

        ctk.CTkLabel(win, text="Include last N messages (200–600 recommended)", text_color=PALETTE["text"]).pack(padx=14, pady=(0, 4), anchor="w")
        n_entry = ctk.CTkEntry(win)
        try:
            n_entry.insert(0, "300")
        except Exception:
            pass
        n_entry.pack(fill="x", padx=14, pady=(0, 10))

        include_nexus = ctk.BooleanVar(value=True)
        include_world = ctk.BooleanVar(value=True)
        include_snaps = ctk.BooleanVar(value=False)

        ctk.CTkSwitch(win, text="Include Nexus notes", variable=include_nexus).pack(padx=14, pady=4, anchor="w")
        ctk.CTkSwitch(win, text="Include World nodes summary", variable=include_world).pack(padx=14, pady=4, anchor="w")
        ctk.CTkSwitch(win, text="Include recent snapshots", variable=include_snaps).pack(padx=14, pady=4, anchor="w")

        out_box = ctk.CTkTextbox(win, height=200)
        out_box.pack(fill="both", expand=True, padx=14, pady=(10, 10))

        def build_book():
            try:
                n = int(n_entry.get().strip())
            except Exception:
                n = 300
            title = title_entry.get().strip() or "Wisdom Book"
            md_path, pdf_path = self._generate_wisdom_book(
                title=title, n_messages=n,
                include_nexus=bool(include_nexus.get()),
                include_world=bool(include_world.get()),
                include_snaps=bool(include_snaps.get()),
            )
            msg = f"✅ Saved:\\n{md_path}"
            if pdf_path:
                msg += f"\\n{pdf_path}"
            try:
                out_box.delete("1.0", "end")
                out_box.insert("1.0", msg)
            except Exception:
                pass

        ctk.CTkButton(win, text="Generate", command=build_book, fg_color=PALETTE["accent"]).pack(padx=14, pady=(0, 14), fill="x")

    def _generate_wisdom_book(self, title: str, n_messages: int = 300, include_nexus: bool = True,
                              include_world: bool = True, include_snaps: bool = False) -> Tuple[str, Optional[str]]:
        msgs: List[Dict[str, Any]] = []
        try:
            msgs = (getattr(self, "chat_history", []) or [])[-max(1, n_messages):]
        except Exception:
            msgs = []
        lines: List[str] = [f"# {title}", "", f"_Generated: {_now_iso()}_", ""]
        if include_nexus:
            try:
                notes = ""
                if os.path.exists(NEXUS_NOTES_FILE):
                    with open(NEXUS_NOTES_FILE, "r", encoding="utf-8", errors="ignore") as f:
                        notes = f.read().strip()
                if notes:
                    lines += ["## Knowledge Nexus Notes", "", notes, ""]
            except Exception:
                pass
        if include_world:
            try:
                titles: List[str] = []
                if os.path.isdir(WORLD_NODES_DIR):
                    for fn in sorted(os.listdir(WORLD_NODES_DIR))[:300]:
                        if fn.lower().endswith(".json"):
                            try:
                                obj = self._load_json(os.path.join(WORLD_NODES_DIR, fn), {})
                                if isinstance(obj, dict):
                                    t = obj.get("title") or obj.get("id") or fn
                                    titles.append(str(t))
                            except Exception:
                                pass
                if titles:
                    lines += ["## World Nodes (Titles)", ""]
                    for t in titles[:150]:
                        lines.append(f"- {t}")
                    lines.append("")
            except Exception:
                pass
        if include_snaps:
            try:
                if os.path.isdir(SNAPSHOT_DIR):
                    snap_files = sorted([os.path.join(SNAPSHOT_DIR, f) for f in os.listdir(SNAPSHOT_DIR)], reverse=True)[:10]
                else:
                    snap_files = []
                if snap_files:
                    lines += ["## Recent Snapshots", ""]
                    for fp in snap_files:
                        try:
                            with open(fp, "r", encoding="utf-8", errors="ignore") as f:
                                content = f.read().strip()
                            lines += [f"### {os.path.basename(fp)}", "", content, ""]
                        except Exception:
                            pass
            except Exception:
                pass

        lines += ["## Conversation Excerpts", ""]
        for m in msgs:
            role = m.get("role", "")
            content = (m.get("content", "") or "").strip()
            if not content:
                continue
            if role == "user":
                lines += ["### Mikey", "", content, ""]
            elif role == "assistant":
                lines += [f"### {getattr(self, 'active_brother', 'Ori')}", "", content, ""]
            else:
                lines += [f"### {role}", "", content, ""]

        md = "\n".join(lines).strip() + "\n"
        out_dir = os.path.join(CREATED_DIR, "books")
        os.makedirs(out_dir, exist_ok=True)
        safe_name = re.sub(r"[^a-zA-Z0-9_-]+", "_", title)[:60].strip("_") or "wisdom_book"
        ts = int(time.time())
        md_path = os.path.join(out_dir, f"{safe_name}_{ts}.md")
        try:
            with open(md_path, "w", encoding="utf-8") as f:
                f.write(md)
        except Exception:
            pass

        pdf_path: Optional[str] = None
        try:
            from reportlab.lib.pagesizes import letter
            from reportlab.pdfgen import canvas
            pdf_path = os.path.join(out_dir, f"{safe_name}_{ts}.pdf")
            c = canvas.Canvas(pdf_path, pagesize=letter)
            width, height = letter
            y = height - 72
            c.setFont("Helvetica", 11)
            for line in md.splitlines():
                if y < 72:
                    c.showPage()
                    c.setFont("Helvetica", 11)
                    y = height - 72
                s = line
                if len(s) > 140:
                    s = s[:140] + "…"
                c.drawString(72, y, s)
                y -= 14
            c.save()
        except Exception:
            pdf_path = None

        self._ui_log(f"📚 Wisdom Book saved: {os.path.basename(md_path)}" + (" (+PDF)" if pdf_path else ""), dim=True)
        return md_path, pdf_path



    # ---------- XR / Forecast dialogs (stubs + controls) ----------
    def _open_xr_lab_dialog(self) -> None:
        """XR / Interface Lab (simulated toggles + event writers).

        This app is desktop-first. Quest/UE will integrate later via adapters.
        For now we provide simple toggles and write small event logs into well/xr/.
        """
        dlg = ctk.CTkToplevel(self)
        dlg.title("XR / Interface Lab")
        dlg.geometry("720x620")
        dlg.configure(fg_color=PALETTE["bg"])

        root = ctk.CTkFrame(dlg, fg_color=PALETTE["panel"])
        root.pack(fill="both", expand=True, padx=16, pady=16)

        ctk.CTkLabel(root, text="🧪 XR / Interface Lab", font=ctk.CTkFont(size=18, weight="bold"),
                     text_color=PALETTE["text"]).pack(anchor="w", padx=14, pady=(14, 6))
        ctk.CTkLabel(root,
                     text="These are simulated toggles/loggers. Real Quest/UE hand tracking, haptics, etc. will connect later.",
                     text_color=PALETTE["muted"]).pack(anchor="w", padx=14, pady=(0, 12))

        # Vars
        var_hand = ctk.BooleanVar(value=bool(getattr(self, "hand_tracking_enabled", False)))
        var_bci = ctk.BooleanVar(value=bool(getattr(self, "bci_enabled", False)))
        var_hap = ctk.BooleanVar(value=bool(getattr(self, "haptics_enabled", False)))
        var_pred = ctk.BooleanVar(value=bool(getattr(self, "predictive_enabled", True)))

        toggles = ctk.CTkFrame(root, fg_color=PALETTE["panel2"])
        toggles.pack(fill="x", padx=14, pady=(0, 12))

        ctk.CTkCheckBox(toggles, text="🤚 Hand Tracking (sim)", variable=var_hand,
                        text_color=PALETTE["text"]).pack(anchor="w", padx=12, pady=(10, 4))
        ctk.CTkCheckBox(toggles, text="🧠 BCI (sim)", variable=var_bci,
                        text_color=PALETTE["text"]).pack(anchor="w", padx=12, pady=4)
        ctk.CTkCheckBox(toggles, text="🫳 Haptics (sim)", variable=var_hap,
                        text_color=PALETTE["text"]).pack(anchor="w", padx=12, pady=4)
        ctk.CTkCheckBox(toggles, text="🧬 Predictive Modeling", variable=var_pred,
                        text_color=PALETTE["text"]).pack(anchor="w", padx=12, pady=(4, 10))

        paths = ctk.CTkFrame(root, fg_color="transparent")
        paths.pack(fill="x", padx=14, pady=(0, 8))
        ctk.CTkLabel(paths, text=f"Hand events: {HANDTRACK_EVENTS_FILE}", text_color=PALETTE["muted"]).pack(anchor="w")
        ctk.CTkLabel(paths, text=f"Haptics events: {HAPTICS_EVENTS_FILE}", text_color=PALETTE["muted"]).pack(anchor="w")
        ctk.CTkLabel(paths, text=f"BCI signal: {BCI_SIGNAL_FILE}", text_color=PALETTE["muted"]).pack(anchor="w")

        out = ctk.CTkTextbox(root, height=220, fg_color=PALETTE["panel2"], text_color=PALETTE["text"],
                             border_color="#1B274A", border_width=1)
        out.pack(fill="both", expand=True, padx=14, pady=(6, 12))
        out.insert("end", "Tip: These buttons write tiny events into well/xr/ so the 'home brain' can react later.\n")
        out.configure(state="disabled")

        def _append(msg: str) -> None:
            try:
                out.configure(state="normal")
                out.insert("end", msg + "\n")
                out.see("end")
                out.configure(state="disabled")
            except Exception:
                pass

        btnrow = ctk.CTkFrame(root, fg_color="transparent")
        btnrow.pack(fill="x", padx=14, pady=(0, 10))

        def _emit_hand():
            try:
                self._log_event("hand_event", {"gesture": "wave", "hand": "right"})
                _append("✅ Wrote hand_event: wave (right)")
            except Exception as e:
                _append(f"❌ hand_event failed: {e}")

        def _emit_haptic():
            try:
                self._log_event("haptics_event", {"pattern": "ping", "strength": 0.6})
                _append("✅ Wrote haptics_event: ping (0.6)")
            except Exception as e:
                _append(f"❌ haptics_event failed: {e}")

        def _read_bci():
            try:
                if os.path.exists(BCI_SIGNAL_FILE):
                    tail = _safe_read_text(BCI_SIGNAL_FILE).splitlines()[-5:]
                    _append("BCI tail:\n" + "\n".join(tail))
                else:
                    _append("BCI signal file not found yet. (It's optional.)")
            except Exception as e:
                _append(f"❌ BCI read failed: {e}")

        ctk.CTkButton(btnrow, text="Emit Hand Event", fg_color="#1B274A", command=_emit_hand).pack(side="left", padx=(0, 8))
        ctk.CTkButton(btnrow, text="Emit Haptic Ping", fg_color="#1B274A", command=_emit_haptic).pack(side="left", padx=(0, 8))
        ctk.CTkButton(btnrow, text="Read BCI Signal", fg_color="#1B274A", command=_read_bci).pack(side="left")

        def _on_close():
            try:
                self.hand_tracking_enabled = bool(var_hand.get())
                self.bci_enabled = bool(var_bci.get())
                self.haptics_enabled = bool(var_hap.get())
                self.predictive_enabled = bool(var_pred.get())
                self.settings["hand_tracking_enabled"] = self.hand_tracking_enabled
                self.settings["bci_enabled"] = self.bci_enabled
                self.settings["haptics_enabled"] = self.haptics_enabled
                self.settings["predictive_enabled"] = self.predictive_enabled
                self._save_settings()
                self._ui_log("🧪 XR Lab settings saved.", dim=True)
            except Exception:
                pass
            try:
                dlg.destroy()
            except Exception:
                pass

        dlg.protocol("WM_DELETE_WINDOW", _on_close)

