def _open_sovereign_reality_engine(self):
    import os, json, time, threading, subprocess, shutil, webbrowser
    import tkinter as tk
    import customtkinter as ctk

    # Paths
    well = WELL_FOLDER
    ingest_root = os.path.join(well, "ingest")
    ue_ingest = os.path.join(ingest_root, "unreal")
    unity_ingest = os.path.join(ingest_root, "unity_vr")
    ue_meta = os.path.join(ingest_root, "ue_assets_meta")
    unity_meta = os.path.join(ingest_root, "unity_assets_meta")
    exports_root = os.path.join(well, "created", "projects")
    ue_exports = os.path.join(exports_root, "unreal_exports")
    unity_exports = os.path.join(exports_root, "unity_exports")
    vr_exports = os.path.join(exports_root, "vr_exports")

    for p in [ue_ingest, unity_ingest, ue_meta, unity_meta, ue_exports, unity_exports, vr_exports]:
        try:
            os.makedirs(p, exist_ok=True)
        except Exception:
            pass

    dlg = ctk.CTkToplevel(self)
    dlg.title("🏛️ Sovereign Reality Engine — UE5 + Unity + VR")
    dlg.geometry("980x720")
    try:
        dlg.transient(self)
        dlg.grab_set()
    except Exception:
        pass

    root = ctk.CTkFrame(dlg, fg_color=PALETTE.get("panel", "#0E1320"))
    root.pack(fill="both", expand=True, padx=12, pady=12)
    header = ctk.CTkFrame(root, fg_color="transparent")
    header.pack(fill="x", padx=8, pady=(8, 4))

    title = ctk.CTkLabel(header, text="Sovereign Reality Engine", font=ctk.CTkFont(size=18, weight="bold"))
    title.pack(side="left")

    status_lbl = ctk.CTkLabel(header, text="", font=ctk.CTkFont(size=12))
    status_lbl.pack(side="right")

    tabs = ctk.CTkTabview(root)
