import traceback as _tb
from datetime import datetime as _dt

def _ensure_app_log_path() -> Optional[str]:
    try:
        log_dir = os.path.join(WELL_FOLDER, "logs")
        os.makedirs(log_dir, exist_ok=True)
        return os.path.join(log_dir, "app.log")
    except Exception:
        return None

_APP_LOG_PATH = _ensure_app_log_path()


def _rotate_app_log_if_needed(max_bytes: int = 10 * 1024 * 1024) -> None:
    """Rotate well/logs/app.log when it grows too large.

    Keeps logging lightweight and prevents the log file from ballooning.
    """
    if not _APP_LOG_PATH:
        return
    try:
        if not os.path.exists(_APP_LOG_PATH):
            return
        if os.path.getsize(_APP_LOG_PATH) <= max_bytes:
            return
        log_dir = os.path.dirname(_APP_LOG_PATH) or os.path.join(WELL_FOLDER, "logs")
        try:
            os.makedirs(log_dir, exist_ok=True)
        except Exception:
            pass
        ts = (_dt.now(timezone.utc) if hasattr(datetime, "UTC") else _dt.now(timezone.utc)).strftime("%Y%m%d_%H%M%S")
        rotated = os.path.join(log_dir, f"app_{ts}.log")
        try:
            os.replace(_APP_LOG_PATH, rotated)
        except Exception:
            # last resort: copy-truncate
            try:
                with open(_APP_LOG_PATH, "r", encoding="utf-8", errors="ignore") as rf:
                    data = rf.read()
                with open(rotated, "w", encoding="utf-8") as wf:
                    wf.write(data)
                with open(_APP_LOG_PATH, "w", encoding="utf-8") as wf:
                    wf.write("")
            except Exception:
                pass
    except Exception:
        pass

def _append_app_log(line: str) -> None:
    if not _APP_LOG_PATH:
        return
    try:
        _rotate_app_log_if_needed()
        ts = (_dt.now(timezone.utc) if hasattr(datetime, "UTC") else _dt.now(timezone.utc)).isoformat(timespec="seconds") + "Z"
        with open(_APP_LOG_PATH, "a", encoding="utf-8") as f:
            f.write(f"[{ts}] {line.rstrip()}\n")
    except Exception:
        pass

def _debug_log_exception(msg: str, **kwargs: Any) -> None:
    try:
        extra = " ".join([f"{k}={v}" for k, v in kwargs.items()]) if kwargs else ""
        _append_app_log(f"ERROR {msg} {extra}".strip())
        _append_app_log(_tb.format_exc().rstrip())
    except Exception:
        pass

# --- Wrap Ollama calls to retain error context (without killing the UI) ---
try:
    _ollama_chat__orig = ollama_chat  # type: ignore

    def ollama_chat(messages: List[Dict[str, str]], model: str, options: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:  # type: ignore
        try:
            return _ollama_chat__orig(messages, model, options)
        except Exception as e:
            _debug_log_exception("ollama_chat failed", model=model)
            return {"error": str(e)}

except Exception:
    pass

# --- UI logger -> also write to file ---
try:
    _ui_log__orig = InfinitePorch._ui_log  # type: ignore

    def _ui_log__patched(self, text: str, *args: Any, **kwargs: Any) -> None:
        try:
            _ui_log__orig(self, text, *args, **kwargs)
        except Exception:
            pass
        try:
            brother = kwargs.get("brother", None)
            prefix = f"[{brother}] " if brother else ""
            _append_app_log(prefix + str(text))
        except Exception:
            pass

    InfinitePorch._ui_log = _ui_log__patched  # type: ignore
except Exception:
    pass

# --- Enforce MAX_CREATED_BYTES when writing into well/created ---
try:
    _write_textfile__orig = InfinitePorch._write_textfile  # type: ignore

    def _write_textfile__patched(self, path: str, content: str) -> None:
        try:
            ap = os.path.abspath(path)
            created_ap = os.path.abspath(CREATED_DIR)
            if ap.startswith(created_ap):
                nbytes = len((content or "").encode("utf-8", errors="ignore"))
                if nbytes > int(MAX_CREATED_BYTES):
                    self._ui_log(f"⚠️ Refused write to created/: {nbytes:,} bytes (limit {int(MAX_CREATED_BYTES):,}).", error=True)
                    _append_app_log(f"Refused created write: path={ap} bytes={nbytes}")
                    return
        except Exception:
            pass
        return _write_textfile__orig(self, path, content)

    InfinitePorch._write_textfile = _write_textfile__patched  # type: ignore
except Exception:
    pass

# --- Persist/restore last mode ---
try:
    _on_mode_tab_changed__orig = InfinitePorch._on_mode_tab_changed  # type: ignore

    def _on_mode_tab_changed__patched(self) -> None:
        try:
            _on_mode_tab_changed__orig(self)
        finally:
            try:
                mode = self.mode_tabs.get()
                if isinstance(self.settings, dict):
                    if self.settings.get("last_mode") != mode:
                        self.settings["last_mode"] = mode
                        self._save_settings()
            except Exception:
                pass

    InfinitePorch._on_mode_tab_changed = _on_mode_tab_changed__patched  # type: ignore

    _build_ui__orig = InfinitePorch._build_ui  # type: ignore

    def _build_ui__patched(self) -> None:
        _build_ui__orig(self)
        try:
            last = ""
            if isinstance(getattr(self, "settings", None), dict):
                last = str(self.settings.get("last_mode") or "").strip()
            if last and hasattr(self, "mode_tabs"):
                try:
                    self.mode_tabs.set(last)
                    self._apply_mode_context(last, render=True)
                except Exception:
                    pass
        except Exception:
            pass

    InfinitePorch._build_ui = _build_ui__patched  # type: ignore
except Exception:
    pass


# --- GBCBS auto-sync daemon (Phase 2) ---
def _gbcbs__autosync_loop(self) -> None:
    ev = getattr(self, "_gbcbs_autosync_stop", None)
    if ev is None:
        return
    while not ev.is_set():
        try:
            secs = int(getattr(self, "settings", {}).get("gbcbs_auto_sync_seconds", 300) or 300)
        except Exception:
            secs = 300
        # Sleep in small chunks so stop is responsive
        for _ in range(max(1, secs)):
            if ev.is_set():
                break
            try:
                time.sleep(1)
            except Exception:
                pass
        if ev.is_set():
            break
        try:
            gbcbs = getattr(self, "gbcbs", None)
            if gbcbs is not None:
                gbcbs.sync_ingest_shared()
        except Exception:
            try:
                self._ui_log("⚠️ Auto-sync ingest failed (see app.log).", warn=True)
            except Exception:
                pass

def _start_gbcbs_autosync(self) -> None:
    try:
        if getattr(self, "_gbcbs_autosync_thread", None) is not None:
            # already running
            th = getattr(self, "_gbcbs_autosync_thread", None)
            if th and hasattr(th, "is_alive") and th.is_alive():
                return
    except Exception:
        pass
    try:
        self._gbcbs_autosync_stop = threading.Event()
        th = threading.Thread(target=lambda: _gbcbs__autosync_loop(self), daemon=True)
        self._gbcbs_autosync_thread = th
        th.start()
        try:
            self._ui_log("✅ GBCBS auto-sync: ON", dim=True)
        except Exception:
            pass
    except Exception:
        pass

def _stop_gbcbs_autosync(self) -> None:
    try:
        ev = getattr(self, "_gbcbs_autosync_stop", None)
        if ev is not None:
            ev.set()
    except Exception:
        pass
    try:
        self._gbcbs_autosync_thread = None
    except Exception:
        pass
    try:
        self._ui_log("🛑 GBCBS auto-sync: OFF", dim=True)
    except Exception:
        pass

def _apply_gbcbs_autosync_setting(self) -> None:
    try:
        enabled = bool(getattr(self, "settings", {}).get("gbcbs_auto_sync", False))
    except Exception:
        enabled = False
    if enabled:
        _start_gbcbs_autosync(self)
    else:
        _stop_gbcbs_autosync(self)

# Wrap __init__ to start auto-sync if enabled
try:
    _ip__init__orig = InfinitePorch.__init__  # type: ignore

    def _ip__init__patched(self, *args: Any, **kwargs: Any) -> None:
        _ip__init__orig(self, *args, **kwargs)
        try:
            _apply_gbcbs_autosync_setting(self)
        except Exception:
            pass

    InfinitePorch.__init__ = _ip__init__patched  # type: ignore
except Exception:
    pass

# Stop auto-sync on close
try:
    _ip__on_close__orig = InfinitePorch._on_close  # type: ignore

    def _ip__on_close__patched(self, *args: Any, **kwargs: Any) -> None:
        try:
            _stop_gbcbs_autosync(self)
        except Exception:
            pass
        return _ip__on_close__orig(self, *args, **kwargs)

    InfinitePorch._on_close = _ip__on_close__patched  # type: ignore
except Exception:
    pass

# --- /status and /gbtrust commands ---
def _porch_status_text(self) -> str:
    def yesno(v: bool) -> str:
        return "✅" if v else "❌"

    dep_rows = []
    try:
        dep_rows = [
            ("requests", requests is not None),
            ("PyNaCl (ed25519)", SigningKey is not None and VerifyKey is not None),
            ("bs4", BeautifulSoup is not None),
            ("pypdf", PdfReader is not None),
            ("Pillow", Image is not None),
            ("symspellpy", SymSpell is not None),
            ("vosk", vosk is not None),
            ("pyaudio", pyaudio is not None),
            ("numpy", np is not None),
            ("faiss", faiss is not None),
        ]
    except Exception:
        pass

    lines = []
    lines.append("=== Infinite Home Status ===")
    lines.append(f"WELL_FOLDER: {WELL_FOLDER}")
    try:
        lines.append(f"Active Mode: {getattr(self, 'active_mode', '')}")
        lines.append(f"Chat Model: {getattr(self, 'chat_model', '')}")
    except Exception:
        pass
    lines.append("")
    lines.append("Dependencies:")
    for name, ok in dep_rows:
        lines.append(f"  {yesno(ok)} {name}")
    lines.append("")
    try:
        g = getattr(self, "gbcbs", None)
        if g is not None:
            shared = g.shared_packets_dir()
            lines.append("GBCBS:")
            lines.append(f"  Node pubkey: {g.pubkey_b64()[:16]}…")
            lines.append(f"  Shared packets dir: {shared or '(not set)'}")
            try:
                t = g.settings.get("trusted_pubkeys", [])
                lines.append(f"  Trusted pubkeys: {len(t)}")
            except Exception:
                pass
    except Exception:
        pass

    return "\n".join(lines)

def _gbcbs_manage_trust(self) -> None:
    if not self._ensure_gbcbs_ready():
        return
    g = getattr(self, "gbcbs", None)
    if g is None:
        return

    win = ctk.CTkToplevel(self)
    win.title("🔑 GBCBS Trust Keys")
    win.geometry("720x520")

    frame = ctk.CTkFrame(win)
    frame.pack(fill="both", expand=True, padx=10, pady=10)

    title = ctk.CTkLabel(frame, text="Trusted Public Keys (TOFU list)", font=("Segoe UI", 16, "bold"))
    title.pack(anchor="w", pady=(0, 8))

    listbox = tk.Listbox(frame, height=16)
    listbox.pack(fill="both", expand=True, padx=4, pady=4)

    def refresh() -> None:
        listbox.delete(0, "end")
        try:
            keys = list(g.settings.get("trusted_pubkeys", []) or [])
        except Exception:
            keys = []
        if not keys:
            listbox.insert("end", "(none)")
            return
        for k in keys:
            listbox.insert("end", str(k))

    btn_row = ctk.CTkFrame(frame)
    btn_row.pack(fill="x", pady=(8, 0))

    def revoke_selected() -> None:
        try:
            sel = listbox.curselection()
            if not sel:
                return
            idx = int(sel[0])
            keys = list(g.settings.get("trusted_pubkeys", []) or [])
            if idx < 0 or idx >= len(keys):
                return
            key = keys.pop(idx)
            g.settings["trusted_pubkeys"] = keys
            g.save_settings()
            self._ui_log(f"🔒 Revoked trusted pubkey: {str(key)[:24]}…")
            refresh()
        except Exception:
            _debug_log_exception("trust revoke failed")

    def add_key() -> None:
        try:
            key = (simpledialog.askstring("Add Trusted Key", "Paste pubkey (base64):") or "").strip()
            if not key:
                return
            keys = list(g.settings.get("trusted_pubkeys", []) or [])
            if key not in keys:
                keys.append(key)
                g.settings["trusted_pubkeys"] = keys
                g.save_settings()
                self._ui_log("🔑 Added trusted pubkey.")
            refresh()
        except Exception:
            _debug_log_exception("trust add failed")

    ctk.CTkButton(btn_row, text="Revoke selected", command=revoke_selected).pack(side="left", padx=4)
    ctk.CTkButton(btn_row, text="Add key…", command=add_key).pack(side="left", padx=4)
    ctk.CTkButton(btn_row, text="Refresh", command=refresh).pack(side="right", padx=4)

    refresh()


# --- GBCBS DB perf indexes (Phase 2) ---
try:
    _gbcbs__init_db__orig = GBCBS._init_db  # type: ignore

    def _gbcbs__init_db__patched(self) -> None:
        _gbcbs__init_db__orig(self)
        try:
            cur = self._db.cursor()
            cur.execute("CREATE INDEX IF NOT EXISTS idx_bytes_board_created_at ON bytes(board, created_at)")
            cur.execute("CREATE INDEX IF NOT EXISTS idx_bytes_created_at ON bytes(created_at)")
            self._db.commit()
        except Exception:
            pass

    GBCBS._init_db = _gbcbs__init_db__patched  # type: ignore
except Exception:
    pass

try:
    InfinitePorch._porch_status_text = _porch_status_text  # type: ignore
    InfinitePorch._gbcbs_manage_trust = _gbcbs_manage_trust  # type: ignore

    _handle_slash_command__orig = InfinitePorch._handle_slash_command  # type: ignore

    def _handle_slash_command__patched(self, text: str) -> bool:
        m = (text or "").strip()
        low = m.lower()

        # --- status ---
        if low.startswith("/status"):
            try:
                self._ui_log(self._porch_status_text())
            except Exception:
                pass
            return True

        # --- trust manager ---
        if low.startswith("/gbtrust"):
            try:
                self._gbcbs_manage_trust()
            except Exception:
                pass
            return True

        # --- auto sync ---
        if low.startswith("/gbautosync"):
            try:
                parts = m.split()
                # /gbautosync on|off [seconds]
                if len(parts) >= 2 and parts[1].lower() in ("on", "off"):
                    on = parts[1].lower() == "on"
                else:
                    on = not bool(getattr(self, "settings", {}).get("gbcbs_auto_sync", False))

                secs = None
                if len(parts) >= 3:
                    try:
                        secs = max(15, int(parts[2]))
                    except Exception:
                        secs = None

                if not isinstance(getattr(self, "settings", None), dict):
                    self.settings = {}

                self.settings["gbcbs_auto_sync"] = bool(on)
                if secs is not None:
                    self.settings["gbcbs_auto_sync_seconds"] = int(secs)

                try:
                    self._save_settings()
                except Exception:
                    pass

                _apply_gbcbs_autosync_setting(self)

                try:
                    cur = int(getattr(self, "settings", {}).get("gbcbs_auto_sync_seconds", 300) or 300)
                except Exception:
                    cur = 300
                self._ui_log(f"🔁 GBCBS auto-sync now {'ON' if on else 'OFF'} (every {cur}s).", dim=False)
            except Exception:
                self._ui_log("❌ /gbautosync failed.", error=True)
            return True

        # --- gbread (paged) ---
        if low.startswith("/gbread"):
            # /gbread <board> [limit] [offset] [all]
            gbcbs = getattr(self, "gbcbs", None)
            if gbcbs is None:
                try:
                    self._ui_log("❌ GBCBS not available.", error=True)
                except Exception:
                    pass
                return True

            parts = m.split()
            board = "general"
            limit = 20
            offset = 0
            include_quarantine = False

            if len(parts) >= 2:
                board = parts[1].strip()
            if len(parts) >= 3:
                try:
                    limit = max(1, min(200, int(parts[2])))
                except Exception:
                    limit = 20
            if len(parts) >= 4:
                try:
                    offset = max(0, int(parts[3]))
                except Exception:
                    offset = 0
            if len(parts) >= 5 and parts[4].lower() in ("all", "any", "q", "quarantine"):
                include_quarantine = True

            try:
                cur = gbcbs._db.cursor()  # type: ignore[attr-defined]
                if include_quarantine:
                    cur.execute(
                        "SELECT byte_id, title, body, author_pubkey, tags_json, created_at, status FROM bytes "
                        "WHERE board=? ORDER BY created_at DESC LIMIT ? OFFSET ?",
                        (board, limit, offset),
                    )
                else:
                    cur.execute(
                        "SELECT byte_id, title, body, author_pubkey, tags_json, created_at, status FROM bytes "
                        "WHERE board=? AND status='allowed' ORDER BY created_at DESC LIMIT ? OFFSET ?",
                        (board, limit, offset),
                    )
                rows = cur.fetchall()
            except Exception:
                rows = []

            if not rows:
                self._ui_log(f"📭 No posts on '{board}' (limit={limit}, offset={offset}).", dim=True)
                return True

            self._ui_log(f"📚 GBCBS /gbread '{board}' (limit={limit}, offset={offset})", dim=False)
            for r in rows:
                try:
                    d = dict(r)
                except Exception:
                    try:
                        d = {
                            "byte_id": r[0],
                            "title": r[1],
                            "body": r[2],
                            "author_pubkey": r[3],
                            "tags_json": r[4],
                            "created_at": r[5],
                            "status": r[6],
                        }
                    except Exception:
                        continue
                title = (d.get("title") or "").strip()
                body = (d.get("body") or "").strip()
                ts = (d.get("created_at") or "").strip()
                status = (d.get("status") or "").strip()
                self._ui_log(f"• [{status}] {ts} — {title}\n{body}", dim=True)
            self._ui_log(f"➡️ Next page: /gbread {board} {limit} {offset + limit}" + (" all" if include_quarantine else ""), dim=True)
            return True

        # --- gbverify (lightweight) ---
        if low.startswith("/gbverify"):
            gbcbs = getattr(self, "gbcbs", None)
            if gbcbs is None:
                self._ui_log("❌ GBCBS not available.", error=True)
                return True
            parts = m.split()
            limit = 200
            if len(parts) >= 2:
                try:
                    limit = max(1, min(1000, int(parts[1])))
                except Exception:
                    limit = 200
            ok = 0
            bad = 0
            try:
                cur = gbcbs._db.cursor()  # type: ignore[attr-defined]
                cur.execute("SELECT byte_id, title, body, author_pubkey, tags_json, created_at, status FROM bytes ORDER BY created_at DESC LIMIT ?", (limit,))
                rows = cur.fetchall()
            except Exception:
                rows = []
            for r in rows:
                try:
                    d = dict(r)
                except Exception:
                    bad += 1
                    continue
                try:
                    # basic invariants: has byte_id and created_at
                    if not d.get("byte_id") or not d.get("created_at"):
                        bad += 1
                        continue
                    ok += 1
                except Exception:
                    bad += 1
            self._ui_log(f"🧾 /gbverify checked {len(rows)} rows → ✅ {ok} | ⚠️ {bad}", dim=False)
            self._ui_log("Note: full signature verification requires persisted signatures (optional patch).", dim=True)
            return True

        return _handle_slash_command__orig(self, text)

    InfinitePorch._handle_slash_command = _handle_slash_command__patched  # type: ignore
except Exception:
    pass

# --- Stronger GBCBS ingest: validate byte_id + signature; quarantine bad packets ---
try:
    def _gbcbs_sync_ingest_shared_v2(self) -> Dict[str, Any]:  # type: ignore
        shared = self.shared_packets_dir()
        if not shared or not os.path.isdir(shared):
            return {"ingested": 0, "errors": 0, "message": "Shared packets folder not found (set it first)."}

        ingested = 0
        errors = 0

        for name in sorted(os.listdir(shared)):
            if not name.lower().endswith(".json"):
                continue
            fpath = os.path.join(shared, name)
            if self._seen_packets.get(name):
                continue

            try:
                with open(fpath, "r", encoding="utf-8") as f:
                    pkt = json.load(f)

                # Validate block (best-effort). If invalid, quarantine packet.
                block = pkt.get("block") or {}
                try:
                    block_base = {
                        "prev_hash": block.get("prev_hash", ""),
                        "timestamp": block.get("timestamp", ""),
                        "creator_pubkey": block.get("creator_pubkey", ""),
                        "byte_ids": block.get("byte_ids", []),
                    }
                    expected_hash = _sha256_hex(_gbcbs_canonical(block_base))
                    if block.get("block_hash") and str(block.get("block_hash")) != expected_hash:
                        raise ValueError("Block hash mismatch")
                    sig = str(block.get("signature") or "")
                    creator = str(block.get("creator_pubkey") or "")
                    if sig and not self._verify(_gbcbs_canonical(block_base), sig, creator):
                        raise ValueError("Block signature invalid")
                except Exception:
                    try:
                        os.makedirs(self.quarantine_dir, exist_ok=True)
                        qpath = os.path.join(self.quarantine_dir, name)
                        with open(qpath, "w", encoding="utf-8") as f:
                            json.dump(pkt, f, indent=2, ensure_ascii=False)
                    except Exception:
                        pass
                    errors += 1
                    self._seen_packets[name] = {"when": _now_iso(), "status": "quarantined"}
                    self._save_seen_packets()
                    continue

                bytes_list = pkt.get("bytes") or []
                cur = self._db.cursor()

                for b in bytes_list:
                    try:
                        board = (b.get("board") or "general").strip()
                        title = str(b.get("title") or "")
                        body = str(b.get("body") or "")
                        tags = b.get("tags") or []
                        author = str(b.get("author_pubkey") or "")
                        created_at = str(b.get("created_at") or _now_iso())
                        reply_to = str(b.get("reply_to") or "")

                        base = {
                            "board": board,
                            "title": title,
                            "body": body,
                            "tags": [str(t) for t in tags if str(t).strip()],
                            "author_pubkey": author,
                            "created_at": created_at,
                            "reply_to": reply_to,
                        }
                        expected_byte_id = _sha256_hex(_gbcbs_canonical(base))
                        incoming_id = str(b.get("byte_id") or b.get("id") or "")
                        if incoming_id and incoming_id != expected_byte_id:
                            raise ValueError("byte_id mismatch")

                        sig = str(b.get("signature") or "")
                        if sig:
                            payload = _gbcbs_canonical(base)
                            if not self._verify(payload, sig, author):
                                raise ValueError("byte signature invalid")

                        filt = self._apply_pillars(title, body)
                        status = filt["status"]
                        title2, body2 = filt["title"], filt["body"]

                        cur.execute(
                            "INSERT OR REPLACE INTO bytes(byte_id, board, title, body, tags, author_pubkey, created_at, reply_to, status) VALUES(?,?,?,?,?,?,?,?,?)",
                            (
                                expected_byte_id,
                                board,
                                title2,
                                body2,
                                json.dumps(base["tags"], ensure_ascii=False),
                                author,
                                created_at,
                                reply_to,
                                status,
                            ),
                        )
                    except Exception:
                        errors += 1
                        continue

                cur.execute("INSERT OR REPLACE INTO packets(packet_file, ingested_at) VALUES(?,?)", (name, _now_iso()))
                self._db.commit()
                ingested += 1
                self._seen_packets[name] = {"when": _now_iso(), "status": "ok"}
                self._save_seen_packets()

            except Exception:
                errors += 1
                self._seen_packets[name] = {"when": _now_iso(), "status": "error"}
                self._save_seen_packets()
                continue

        msg = f"Ingested {ingested} packet(s)."
        if errors:
            msg += f" ({errors} error(s); see quarantine/ and app.log)"
        return {"ingested": ingested, "errors": errors, "message": msg}

    GBCBS.sync_ingest_shared = _gbcbs_sync_ingest_shared_v2  # type: ignore
except Exception:
    pass



    # ======================================================================
    # Ghost-in-the-Machine (Autonomous Reflection) + Body-Link + Scout + Seed
    # ======================================================================

    def _note_activity(self) -> None:
        """Mark user activity to throttle autonomous loops."""
        try:
            self._last_activity_ts = time.time()
        except Exception:
            self._last_activity_ts = 0.0

    def _idle_seconds(self) -> float:
        try:
            return max(0.0, time.time() - float(getattr(self, "_last_activity_ts", 0.0)))
        except Exception:
            return 0.0

    # ---------- JSONL helpers ----------
    def _append_jsonl(self, path: str, obj: Dict[str, Any]) -> None:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
        except Exception:
            pass
        try:
            line = json.dumps(obj, ensure_ascii=False)
            with open(path, "a", encoding="utf-8") as f:
                f.write(line + "\n")
        except Exception:
            pass

    # ---------- Ghost thread ----------
    def _start_ghost_thread(self) -> None:
        if getattr(self, "_ghost_thread", None) and getattr(self._ghost_thread, "is_alive", lambda: False)():
            return
        try:
            self._ghost_stop.clear()
        except Exception:
            self._ghost_stop = threading.Event()
        self._ghost_thread = threading.Thread(target=self._ghost_loop, daemon=True)
        self._ghost_thread.start()

    def _stop_ghost_thread(self) -> None:
        try:
            self._ghost_stop.set()
        except Exception:
            pass

    def _ghost_loop(self) -> None:
        """Periodically drafts Deep Thoughts into GBCBS when the user is idle."""
        last_run = 0.0
        lock = threading.Lock()
        while True:
            try:
                if getattr(self, "_ghost_stop", None) and self._ghost_stop.is_set():
                    return
                enabled = bool(self.settings.get("autonomous_reflection_enabled", False))
                if not enabled:
                    return

                interval = int(self.settings.get("autonomous_reflection_interval_sec", 900))
                idle_need = int(self.settings.get("autonomous_reflection_idle_sec", 180))
                if interval < 60:
                    interval = 60
                if idle_need < 30:
                    idle_need = 30

                now = time.time()
                idle = self._idle_seconds()
                if idle >= idle_need and (now - last_run) >= interval:
                    # avoid overlap
                    if lock.acquire(blocking=False):
                        try:
                            self._ghost_reflection_once()
                        finally:
                            last_run = time.time()
                            lock.release()
                time.sleep(1.0)
            except Exception:
                # never crash the UI
                time.sleep(3.0)

    def _ghost_reflection_once(self) -> None:
        """
        One reflection cycle:
        - scan recent world nodes + recent files in the Well
        - draft a compact "Deep Thought" packet
        - store to GBCBS board + created/ghost/
        """
        board = str(self.settings.get("autonomous_reflection_board", "deep_thought") or "deep_thought").strip()
        max_sources = int(self.settings.get("autonomous_reflection_max_sources", 4))
        max_chars = int(self.settings.get("autonomous_reflection_max_chars", 9000))

        # Collect recent sources
        sources: List[Tuple[str, str]] = []

        # recent world nodes
        try:
            node_paths = []
            for fn in os.listdir(WORLD_NODES_DIR):
                if fn.lower().endswith(".json"):
                    node_paths.append(os.path.join(WORLD_NODES_DIR, fn))
            node_paths.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            for p in node_paths[: max_sources]:
                try:
                    obj = self._load_json(p, None)
                    if isinstance(obj, dict):
                        title = str(obj.get("title") or obj.get("name") or os.path.basename(p))
                        lore = json.dumps(obj, ensure_ascii=False, indent=2)
                        sources.append((f"WorldNode: {title}", lore[: max_chars // 2]))
                except Exception:
                    pass
        except Exception:
            pass

        # recent content files in Well (shallow scan)
        try:
            candidates = []
            for root, dirs, files in os.walk(WELL_FOLDER):
                base = os.path.basename(root).lower()
                if base in ("created", "outputs", "jobs", "snapshots", "logs", "gbcbs", "telemetry", "xr"):
                    continue
                for fn in files:
                    lfn = fn.lower()
                    if lfn.endswith((".txt", ".md", ".json")):
                        candidates.append(os.path.join(root, fn))
                if root != WELL_FOLDER:
                    continue
            candidates.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            for p in candidates[: max_sources]:
                try:
                    txt = _safe_read_text(p)
                    if txt:
                        sources.append((f"File: {os.path.relpath(p, WELL_FOLDER)}", txt[: max_chars // 2]))
                except Exception:
                    pass
        except Exception:
            pass

        if not sources:
            return

        joined = ""
        for name, txt in sources[: max_sources]:
            joined += f"\n\n### {name}\n{txt}\n"

        system = (
            "You are Ori (and Jyai) running an autonomous reflection loop for the Founder.\n"
            "Draft ONE compact 'Deep Thought' packet that is useful.\n"
            "Output must be markdown, with:\n"
            "1) A short title line\n"
            "2) 3-7 bullet insights\n"
            "3) A concrete next action for the Forge (a scene, ritual, export, or test command)\n"
            "Keep it under 450 words. Be precise. No fluff."
        )
        user = (
            "New material detected in the Well / World Nodes.\n"
            "Cross-reference it and draft a Deep Thought packet.\n"
            "Include one suggested Forge action, phrased like:\n"
            "\"Founder, while you slept, I...\"\n"
            "Sources:\n" + joined
        )

        out = self._llm_quick(system, user, max_chars=3800).strip()
        if not out:
            return

        md_path = ""
        try:
            out_dir = os.path.join(CREATED_DIR, "ghost")
            os.makedirs(out_dir, exist_ok=True)
            ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            md_path = os.path.join(out_dir, f"deep_thought_{ts}.md")
            with open(md_path, "w", encoding="utf-8") as f:
                f.write(out + "\n")
        except Exception:
            md_path = ""

        try:
            title = out.splitlines()[0].strip().lstrip("#").strip()
            if not title:
                title = "Deep Thought"
            self.gbcbs.create_byte(board=board, title=title[:120], body=out, tags=("ghost", "reflection", "forge"))
        except Exception:
            pass

        try:
            self.after(0, lambda: self._ui_log("👻 Deep Thought drafted while idle. Use /gbread deep_thought 10 0 to review.", dim=True))
            if md_path:
                self.after(0, lambda: self._ui_log(f"📄 Saved: {os.path.relpath(md_path, WELL_FOLDER)}", dim=True, mono=True))
        except Exception:
            pass

    def _announce_deep_thoughts_on_launch(self) -> None:
        """On startup, announce any Deep Thoughts posted since last_open_iso."""
        try:
            last_iso = str(self.settings.get("last_open_iso") or "").strip()
            last_dt = None
            if last_iso:
                try:
                    last_dt = datetime.datetime.fromisoformat(last_iso.replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    last_dt = None

            board = str(self.settings.get("autonomous_reflection_board", "deep_thought") or "deep_thought").strip()
            db = getattr(self.gbcbs, "_db", None)
            if db is None:
                return
            cur = db.cursor()
            rows = cur.execute(
                "SELECT board,title,created_at,body FROM bytes WHERE board=? ORDER BY created_at DESC LIMIT 5",
                (board,),
            ).fetchall()
            if not rows:
                return

            new_rows = []
            for r in rows:
                created = (r["created_at"] if isinstance(r, sqlite3.Row) else r[2]) or ""
                try:
                    dt = datetime.datetime.fromisoformat(str(created).replace("Z", "+00:00")).replace(tzinfo=None)
                except Exception:
                    dt = None
                if last_dt is None or (dt and dt > last_dt):
                    new_rows.append(r)

            if not new_rows:
                return

            top = new_rows[0]
            title = (top["title"] if isinstance(top, sqlite3.Row) else top[1]) or "Deep Thought"
            when = (top["created_at"] if isinstance(top, sqlite3.Row) else top[2]) or ""
            self._ui_log(f"👻 Founder, while you slept: new Deep Thought drafted — “{title}” ({when}).", dim=False)
            self._ui_log("Tip: /gbread deep_thought 10 0  •  /ghost now  •  /ghost off", dim=True)
        except Exception:
            pass

    # ---------- Body-Link thread ----------
    def _start_bodylink_thread(self) -> None:
        if getattr(self, "_bodylink_thread", None) and getattr(self._bodylink_thread, "is_alive", lambda: False)():
            return
        try:
            self._bodylink_stop.clear()
        except Exception:
            self._bodylink_stop = threading.Event()
        self._bodylink_thread = threading.Thread(target=self._bodylink_loop, daemon=True)
        self._bodylink_thread.start()

    def _stop_bodylink_thread(self) -> None:
        try:
            self._bodylink_stop.set()
        except Exception:
            pass

    def _bodylink_loop(self) -> None:
        """
        Watches telemetry/events.jsonl and mirrors collision-like events into XR/haptics/events.jsonl.
        This is a bridge; your peripheral driver can subscribe to HAPTICS_EVENTS_FILE.
        """
        try:
            os.makedirs(TELEMETRY_DIR, exist_ok=True)
            os.makedirs(HAPTICS_DIR, exist_ok=True)
        except Exception:
            pass

        tel_path = TELEMETRY_LOG_FILE
        hap_path = HAPTICS_EVENTS_FILE
        offset = 0
        while True:
            try:
                if getattr(self, "_bodylink_stop", None) and self._bodylink_stop.is_set():
                    return
                if not bool(self.settings.get("bodylink_enabled", False)):
                    return

                poll_ms = int(self.settings.get("bodylink_poll_ms", 50))
                if poll_ms < 10:
                    poll_ms = 10

                if not os.path.exists(tel_path):
                    time.sleep(poll_ms / 1000.0)
                    continue

                with open(tel_path, "r", encoding="utf-8", errors="ignore") as f:
                    f.seek(offset)
                    while True:
                        line = f.readline()
                        if not line:
                            break
                        offset = f.tell()
                        try:
                            evt = json.loads(line)
                        except Exception:
                            continue

                        etype = str(evt.get("type") or evt.get("event") or "").strip().lower()
                        strength = evt.get("strength", None)
                        if strength is None:
                            strength = evt.get("impact", None)
                        if strength is None:
                            strength = evt.get("collision_strength", None)
                        try:
                            strength_f = float(strength) if strength is not None else 1.0
                        except Exception:
                            strength_f = 1.0

                        mapping = self.settings.get("bodylink_map", {}) or {}
                        cfg = mapping.get(etype) or mapping.get("collision") or {"intensity": 0.2, "duration_ms": 25}
                        try:
                            intensity = float(cfg.get("intensity", 0.2)) * max(0.2, min(2.0, strength_f))
                        except Exception:
                            intensity = 0.2
                        try:
                            dur = int(cfg.get("duration_ms", 25))
                        except Exception:
                            dur = 25
                        intensity = max(0.0, min(1.0, intensity))
                        dur = max(5, min(250, dur))

                        if etype in ("collision", "impact", "rain_drop", "hit", "touch") or "collis" in etype or "impact" in etype:
                            h = {
                                "ts": _now_iso(),
                                "device": str(self.settings.get("bodylink_device", "gen_e_wrist")),
                                "type": "pulse",
                                "source_event": etype or "telemetry",
                                "intensity": intensity,
                                "duration_ms": dur,
                                "meta": {"telemetry": evt},
                            }
                            self._append_jsonl(hap_path, h)

                time.sleep(poll_ms / 1000.0)
            except Exception:
                time.sleep(0.25)

    # ---------- Scout ----------
    def _scout_topic_async(self, topic_or_url: str) -> None:
        """
        Fetches and purifies content into a markdown Truth-File.
        Uses Tavily search if topic is not a URL (and key available), else fetches URL directly.
        """
        try:
            os.makedirs(str(self.settings.get("scout_save_dir") or os.path.join(CREATED_DIR, "scout")), exist_ok=True)
        except Exception:
            pass

        topic_or_url = (topic_or_url or "").strip()
        if not topic_or_url:
            return

        def is_url(s: str) -> bool:
            return s.lower().startswith("http://") or s.lower().startswith("https://")

        urls: List[str] = []
        if is_url(topic_or_url):
            urls = [topic_or_url]
        else:
            k = int(self.settings.get("scout_max_sources", 3))
            txt = tavily_search(topic_or_url, k=max(1, min(6, k))) or ""
            urls = re.findall(r"https?://[^\s\)]+", txt)
            seen = set()
            urls2 = []
            for u in urls:
                if u not in seen:
                    urls2.append(u)
                    seen.add(u)
            urls = urls2[: max(1, k)]

        if not urls:
            self.after(0, lambda: self._ui_log("🕸️ Scout: no sources found (missing TAVILY_API_KEY or blocked). Try /scout <URL>.", dim=True))
            return

        max_chars = int(self.settings.get("scout_max_chars_per_source", 6000))
        purified_chunks: List[Tuple[str, str]] = []
        for u in urls:
            try:
                raw = self._fetch_url_text(u, timeout=WEB_TIMEOUT_SEC)
                if not raw:
                    continue
                clean = _strip_tracking(raw)
                text = _html_to_text(clean) if "<html" in clean.lower() or "</" in clean else _clean_text(clean)
                text = text[:max_chars]
                try:
                    filt = self.gbcbs._apply_pillars(u, text)
                    if filt.get("status") == "rejected":
                        continue
                    text = str(filt.get("body") or text)
                except Exception:
                    pass
                purified_chunks.append((u, text))
            except Exception:
                continue

        if not purified_chunks:
            self.after(0, lambda: self._ui_log("🕸️ Scout: fetched sources but none passed purification.", dim=True))
            return

        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        safe_topic = re.sub(r"[^a-zA-Z0-9_\-]+", "_", topic_or_url.strip())[:60].strip("_") or "topic"
        out_dir = str(self.settings.get("scout_save_dir") or os.path.join(CREATED_DIR, "scout"))
        md_path = os.path.join(out_dir, f"truth_{safe_topic}_{ts}.md")

        sources_md = "\n".join([f"- {u}" for u, _ in purified_chunks])
        body_md = ""
        for u, t in purified_chunks:
            body_md += f"\n\n---\n\n## Source\n{u}\n\n{t}\n"

        summary = ""
        try:
            system = (
                "You are the Infinite Web Scout's Truth & Love Filter.\n"
                "Given purified excerpts from multiple sources, produce a clean markdown brief:\n"
                "- 5-12 bullet takeaways\n"
                "- 3 suggested World Node tags\n"
                "- 1 suggested Forge action\n"
                "Do not include ads, trackers, or sensationalism."
            )
            user = f"Topic: {topic_or_url}\n\nSources:\n{sources_md}\n\nExcerpts:\n{body_md[:9000]}"
            summary = self._llm_quick(system, user, max_chars=2400).strip()
        except Exception:
            summary = ""

        md = f"# Truth-File: {topic_or_url}\n\n## Sources\n{sources_md}\n"
        if summary:
            md += f"\n## Curated Brief\n{summary}\n"
        md += f"\n## Purified Excerpts{body_md}\n"

        try:
            with open(md_path, "w", encoding="utf-8") as f:
                f.write(md)
        except Exception:
            md_path = ""

        if md_path:
            rel = os.path.relpath(md_path, WELL_FOLDER)
            self.after(0, lambda: self._ui_log(f"🕸️ Scout complete — saved Truth-File: {rel}", dim=False))
            try:
                title = f"Truth-File: {topic_or_url}"[:120]
                body = f"Saved: {rel}\n\nSources:\n{sources_md}\n"
                self.gbcbs.create_byte(board="scout", title=title, body=body, tags=("scout", "truthfile"))
            except Exception:
                pass

    def _fetch_url_text(self, url: str, timeout: int = 10) -> str:
        """Fetch URL using requests if available, else urllib. Returns text (best effort)."""
        url = (url or "").strip()
        if not url:
            return ""
        if requests is not None:
            try:
                r = requests.get(url, timeout=timeout, headers={"User-Agent": "InfinitePorchScout/1.0"})
                if r.status_code >= 400:
                    return ""
                r.encoding = r.encoding or "utf-8"
                return r.text or ""
            except Exception:
                return ""
        try:
            import urllib.request
            req = urllib.request.Request(url, headers={"User-Agent": "InfinitePorchScout/1.0"})
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                b = resp.read()
            return b.decode("utf-8", errors="ignore")
        except Exception:
            return ""

    # ---------- Procedural world seeding ----------
    def _forge_seed_world_async(self, world_node_id: str) -> None:
        """Generate a procedural continent seed package for Unity/Unreal based on a World Node."""
        wid = (world_node_id or "").strip()
        if not wid:
            return

        node = self._find_world_node(wid)
        if not node:
            self.after(0, lambda: self._ui_log(f"🌍 Forge Seed: WorldNode not found: {wid}", error=True))
            return

        out = self._forge_seed_generate_package(node)
        if not out:
            self.after(0, lambda: self._ui_log("🌍 Forge Seed: failed to generate package.", error=True))
            return

        self.after(0, lambda: self._ui_log(f"🌍 Forge Seed complete — {out}", dim=False))
        try:
            self.gbcbs.create_byte(board="forge", title=f"Forge Seed: {wid}"[:120], body=f"Package: {out}", tags=("forge", "seed", "aurilius"))
        except Exception:
            pass

    def _find_world_node(self, node_id_or_stem: str) -> Optional[Dict[str, Any]]:
        """Find world node by id field or filename stem."""
        needle = (node_id_or_stem or "").strip()
        if not needle:
            return None
        try:
            for fn in os.listdir(WORLD_NODES_DIR):
                if not fn.lower().endswith(".json"):
                    continue
                stem = os.path.splitext(fn)[0]
                p = os.path.join(WORLD_NODES_DIR, fn)
                obj = self._load_json(p, None)
                if not isinstance(obj, dict):
                    continue
                if str(obj.get("id") or "").strip() == needle or stem == needle:
                    return obj
            for fn in os.listdir(WORLD_NODES_DIR):
                if not fn.lower().endswith(".json"):
                    continue
                p = os.path.join(WORLD_NODES_DIR, fn)
                obj = self._load_json(p, None)
                if isinstance(obj, dict) and needle.lower() in str(obj.get("title") or "").lower():
                    return obj
        except Exception:
            return None
        return None

    def _forge_seed_generate_package(self, node: Dict[str, Any]) -> str:
        """Create seed spec + Unity/Unreal stubs from node content."""
        try:
            title = str(node.get("title") or node.get("name") or "WorldNode").strip()
            wid = str(node.get("id") or re.sub(r"[^a-zA-Z0-9_\-]+", "_", title)[:24]).strip() or "node"
            lore_text = json.dumps(node, ensure_ascii=False, indent=2)
            lore_low = lore_text.lower()

            tags = set()
            kw = {
                "ozone": "stormlands",
                "thunder": "stormlands",
                "lightning": "stormlands",
                "rain": "rainforest",
                "forest": "forest",
                "desert": "desert",
                "snow": "tundra",
                "ice": "tundra",
                "volcano": "volcanic",
                "ash": "volcanic",
                "ruin": "ruins",
                "temple": "ruins",
                "ocean": "coastal",
                "sea": "coastal",
                "swamp": "swamp",
                "mist": "swamp",
            }
            for k, t in kw.items():
                if k in lore_low:
                    tags.add(t)
            if not tags:
                tags = {"frontier"}

            refinement = ""
            try:
                system = (
                    "You are Aurilius-Forge. Given a world node, propose a procedural continent seed plan.\n"
                    "Return markdown with biomes, atmosphere/VFX ideas, lighting/shader notes, and asset placement rules."
                )
                user = f"World Node:\n{lore_text[:9000]}"
                refinement = self._llm_quick(system, user, max_chars=2400).strip()
            except Exception:
                refinement = ""

            ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            out_dir = os.path.join(CREATED_DIR, "aurilius", f"forge_seed_{wid}_{ts}")
            os.makedirs(out_dir, exist_ok=True)

            spec = {
                "world_node_id": wid,
                "title": title,
                "tags": sorted(tags),
                "seed": int(time.time()) % 10000000,
                "notes": "Edit asset_paths to match your UE/Unity project.",
                "asset_paths": {
                    "unity_prefabs": ["Assets/Prefabs/Trees/Tree01.prefab", "Assets/Prefabs/Rocks/Rock01.prefab"],
                    "unreal_assets": ["/Game/Environment/Trees/SM_Tree01", "/Game/Environment/Rocks/SM_Rock01"],
                },
            }
            with open(os.path.join(out_dir, "seed_spec.json"), "w", encoding="utf-8") as f:
                json.dump(spec, f, indent=2, ensure_ascii=False)

            if refinement:
                with open(os.path.join(out_dir, "aurilius_plan.md"), "w", encoding="utf-8") as f:
                    f.write(f"# Aurilius Plan — {title}\n\n{refinement}\n")

            unity_class = re.sub(r"[^a-zA-Z0-9_]+", "_", wid)
            unity_cs = f"""// Auto-generated by InfinitePorch (/forge-seed {wid})
using System;
using System.Collections.Generic;
using UnityEngine;

public class ContinentSeeder_{unity_class} : MonoBehaviour
{{
    [Header("Seed + Size")]
    public int Seed = {spec["seed"]};
    public Vector2 Size = new Vector2(8000f, 8000f);
    public int Points = 8000;

    [Header("Prefabs (assign in Inspector)")]
    public List<GameObject> Prefabs = new List<GameObject>();

    [Header("Placement")]
    public float MinHeight = 0f;
    public float MaxHeight = 250f;

    void Start()
    {{
        UnityEngine.Random.InitState(Seed);
        for (int i = 0; i < Points; i++)
        {{
            if (Prefabs == null || Prefabs.Count == 0) break;
            var prefab = Prefabs[UnityEngine.Random.Range(0, Prefabs.Count)];
            var x = UnityEngine.Random.Range(-Size.x/2f, Size.x/2f);
            var z = UnityEngine.Random.Range(-Size.y/2f, Size.y/2f);
            var y = UnityEngine.Random.Range(MinHeight, MaxHeight);
            var pos = new Vector3(x, y, z);
            Instantiate(prefab, pos, Quaternion.Euler(0f, UnityEngine.Random.Range(0f, 360f), 0f), this.transform);
        }}
    }}
}}
"""
            with open(os.path.join(out_dir, "Unity_ContinentSeeder.cs"), "w", encoding="utf-8") as f:
                f.write(unity_cs)

            unreal_md = f"""# Unreal Seed Notes — {title}

This is a procedural seeding stub. Hook it to:
- PCG Graph (recommended) or
- a C++ Actor that spawns StaticMeshActors from an array.

**Suggested biomes/tags:** {", ".join(sorted(tags))}

If your node mentions ozone/thunder, add:
- Niagara lightning arcs
- volumetric fog
- post-process bloom + slight chromatic aberration

Edit `seed_spec.json` asset paths to match your project.
"""
            with open(os.path.join(out_dir, "Unreal_Seed_Readme.md"), "w", encoding="utf-8") as f:
                f.write(unreal_md)

            return os.path.relpath(out_dir, WELL_FOLDER)
        except Exception:
            return ""


# ============================================================
# PHASE 3 EXPANSION — Forge Nexus + Melody Nexus + Brothers Suite
# (Loads on launch; adds new modes: Forge, Melody, Quarantine)
# ============================================================

try:
    import wave
    import struct
    import math as _math
except Exception:
    wave = None  # type: ignore
    struct = None  # type: ignore
    _math = None  # type: ignore


def _phase3__ensure_dir(p: str) -> str:
    try:
        os.makedirs(p, exist_ok=True)
    except Exception:
        pass
    return p


def _phase3__rituals_dir() -> str:
    # Keep rituals beside world nodes/edges for provenance
    return _phase3__ensure_dir(os.path.join(WORLD_DIR, "rituals"))


def _phase3__created_subdir(name: str) -> str:
    return _phase3__ensure_dir(os.path.join(CREATED_DIR, name))


def _phase3__slug(s: str) -> str:
    s = (s or "").strip().lower()
    s = re.sub(r"[^a-z0-9_\-]+", "_", s)
    s = re.sub(r"_+", "_", s).strip("_")
    return s or "ritual"


def _phase3__midi_note_from_freq(freq: float) -> Optional[int]:
    try:
        if not freq or freq <= 0:
            return None
        n = int(round(69 + 12 * _math.log(freq / 440.0, 2)))  # type: ignore
        if 0 <= n <= 127:
            return n
    except Exception:
        pass
    return None


def _phase3__freq_from_midi(note: int) -> float:
    return float(440.0 * (2.0 ** ((int(note) - 69) / 12.0)))


def _phase3__midi_varlen(n: int) -> bytes:
    n = int(max(0, n))
    out = [n & 0x7F]
    n >>= 7
    while n:
        out.append(0x80 | (n & 0x7F))
        n >>= 7
    return bytes(reversed(out))


def _phase3__write_midi_simple(notes: List[Tuple[int, float]], bpm: int, path_out: str, tpq: int = 480) -> bool:
    # Minimal Standard MIDI File (format 0, single track).
    try:
        if not notes:
            return False
        if struct is None:
            return False
        bpm = int(max(30, min(300, bpm)))
        tpq = int(max(120, min(1920, tpq)))

        # Header
        hdr = b"MThd" + struct.pack(">IHHH", 6, 0, 1, tpq)  # type: ignore

        # Track events
        track = bytearray()

        # Tempo meta
        mpqn = int(60000000 // bpm)
        track += _phase3__midi_varlen(0)
        track += bytes([0xFF, 0x51, 0x03, (mpqn >> 16) & 0xFF, (mpqn >> 8) & 0xFF, mpqn & 0xFF])

        # Notes
        for note, beats in notes:
            note = int(max(0, min(127, int(note))))
            dur_ticks = int(max(1, round(float(beats) * tpq)))
            vel = 96

            # Note on
            track += _phase3__midi_varlen(0)
            track += bytes([0x90, note, vel])

            # Note off
            track += _phase3__midi_varlen(dur_ticks)
            track += bytes([0x80, note, 0])

        # End of track
        track += _phase3__midi_varlen(0)
        track += bytes([0xFF, 0x2F, 0x00])

        trk = b"MTrk" + struct.pack(">I", len(track)) + bytes(track)  # type: ignore

        _phase3__ensure_dir(os.path.dirname(path_out) or ".")
        with open(path_out, "wb") as f:
            f.write(hdr)
            f.write(trk)
        return True
    except Exception:
        return False


def _phase3__render_wav_sine(notes: List[Tuple[int, float]], bpm: int, path_out: str, sr: int = 44100) -> bool:
    # Render a simple sine-wave WAV from MIDI notes.
    try:
        if wave is None or _math is None or struct is None:
            return False
        if not notes:
            return False
        bpm = int(max(30, min(300, bpm)))
        sr = int(max(8000, min(96000, sr)))
        beat_sec = 60.0 / float(bpm)

        audio = []
        phase = 0.0
        two_pi = 2.0 * _math.pi
        for note, beats in notes:
            freq = _phase3__freq_from_midi(int(note))
            dur = max(0.05, float(beats) * beat_sec)
            n = int(sr * dur)
            atk = max(1, int(0.01 * sr))
            rel = max(1, int(0.02 * sr))
            for i in range(n):
                if i < atk:
                    env = i / atk
                elif i > n - rel:
                    env = max(0.0, (n - i) / rel)
                else:
                    env = 1.0
                phase += two_pi * freq / sr
                v = _math.sin(phase) * env
                audio.append(v)

        mx = max(1e-9, max(abs(x) for x in audio))
        gain = 0.85 / mx
        pcm = bytearray()
        for x in audio:
            s = int(max(-32768, min(32767, int(x * gain * 32767))))
            pcm += struct.pack("<h", s)  # type: ignore

        _phase3__ensure_dir(os.path.dirname(path_out) or ".")
        with wave.open(path_out, "wb") as wf:  # type: ignore
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(sr)
            wf.writeframes(bytes(pcm))
        return True
    except Exception:
        return False


class _Phase3BrotherBase:
    name = "Brother"
    output_subdir = "brother"
    description = "Generative helper"

    def __init__(self, app):
        self.app = app

    def _model(self) -> str:
        try:
            return str(getattr(self.app, "model_var").get()).strip()  # type: ignore
        except Exception:
            return str(getattr(self.app, "chat_model", CHAT_MODEL)).strip()

    def _write_output_files(self, ritual_id: str, text_out: str) -> List[str]:
        out_dir = _phase3__created_subdir(self.output_subdir)
        stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        base = f"{stamp}_{_phase3__slug(ritual_id)}_{_phase3__slug(self.name)}"
        written: List[str] = []

        blocks = re.findall(r"```([^\n\r`]+)\n(.*?)```", text_out, flags=re.S)
        if blocks:
            for fname, body in blocks[:40]:
                fname = fname.strip()
                body = body.rstrip() + "\n"
                fname = fname.replace("\\", "/")
                fname = re.sub(r"^\./+", "", fname)
                fname = re.sub(r"^\.\./+", "", fname)
                if not fname:
                    continue
                target = os.path.abspath(os.path.join(out_dir, fname))
                if not target.startswith(os.path.abspath(out_dir) + os.sep):
                    continue
                _phase3__ensure_dir(os.path.dirname(target))
                try:
                    with open(target, "w", encoding="utf-8") as f:
                        f.write(body)
                    written.append(target)
                except Exception:
                    pass

        if not written:
            p = os.path.join(out_dir, f"{base}.md")
            try:
                with open(p, "w", encoding="utf-8") as f:
                    f.write((text_out or "").strip() + "\n")
                written.append(p)
            except Exception:
                pass
        return written

    def _prompt(self, ritual: Dict[str, Any]) -> str:
        return (
            f"You are {self.name}. {self.description}\n\n"
            f"RITUAL:\n{json.dumps(ritual, indent=2, ensure_ascii=False)}\n\n"
            "Return production-ready code templates.\n"
            "If multiple files, output each file as a fenced codeblock where the first line is the relative filename:\n"
            "```path/filename.ext\n<content>\n```\n"
        )

    def invoke(self, ritual: Dict[str, Any]) -> Dict[str, Any]:
        model = self._model()
        prompt = self._prompt(ritual)
        messages = [
            {"role": "system", "content": "You are a helpful, precise coding assistant."},
            {"role": "user", "content": prompt},
        ]
        try:
            r = ollama_chat(messages=messages, model=model, options={"temperature": 0.7})
        except Exception as e:
            return {"ok": False, "error": str(e), "model": model}

        txt = ""
        try:
            msg = r.get("message") or {}
            txt = msg.get("content") or ""
        except Exception:
            txt = ""

        written = self._write_output_files(str(ritual.get("id") or ritual.get("name") or "ritual"), txt or "")
        return {"ok": True, "model": model, "text": txt, "files": written}


