def _phase3_parse_ritual(text_in: str) -> Dict[str, Any]:
    raw = (text_in or "").strip()
    low = raw.lower()

    intent = ""
    targets: List[str] = []
    symbols: List[str] = []

    if "->" in raw or "→" in raw or "=>" in raw:
        symbols.append("flow")
    if "^" in raw:
        symbols.append("directive")
    if "loop" in low:
        symbols.append("loop")
    if "mint" in low or "nft" in low:
        symbols.append("mint")
    if "ritual" in low:
        symbols.append("ritual")

    m = re.search(r"^\s*\^\s*([a-zA-Z0-9_\- ]+)\s*$", raw, flags=re.M)
    if m:
        intent = m.group(1).strip()

    if not intent:
        for kw in ["export", "mint", "generate", "build", "summon", "compose", "analyze", "fetch"]:
            if kw in low:
                intent = kw
                break
    if not intent:
        intent = "generate"

    def _add_t(t: str):
        if t and t not in targets:
            targets.append(t)

    if any(k in low for k in ["unreal", "ue5", "blueprint", "metasound", "nanite", "lumen"]):
        _add_t("unreal")
    if any(k in low for k in ["unity", "xr toolkit", "openxr", "c#"]):
        _add_t("unity")
    if any(k in low for k in ["web3", "solidity", "contract", "erc", "nft", "rust", "anchor", "solana"]):
        _add_t("web3")
    if any(k in low for k in ["python", ".py", "script"]):
        _add_t("python")
    if any(k in low for k in ["react", "three", "html", "css", "javascript", "js"]):
        _add_t("frontend")
    if any(k in low for k in ["midi", "music", "melody", "bpm", "daw", "fmod"]):
        _add_t("music")
    if any(k in low for k in ["vr", "teleport", "snap turn", "comfort"]):
        _add_t("vr")

    m2 = re.search(r"targets?\s*:\s*(.+)$", raw, flags=re.I | re.M)
    if m2:
        parts = [p.strip().lower() for p in re.split(r"[,\s]+", m2.group(1)) if p.strip()]
        for p in parts:
            _add_t(p)

    if not targets:
        targets = ["python"]

    rid = _id8()
    return {
        "id": f"ritual_{rid}",
        "created_at": _now_ts(),
        "intent": intent,
        "targets": targets,
        "symbols": symbols,
        "text": raw,
    }


def _phase3_save_ritual(ritual: Dict[str, Any]) -> str:
    rdir = _phase3__rituals_dir()
    rid = _phase3__slug(str(ritual.get("id") or "ritual"))
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    path = os.path.join(rdir, f"{stamp}_{rid}.json")
    try:
        with open(path, "w", encoding="utf-8") as f:
            json.dump(ritual, f, indent=2, ensure_ascii=False)
    except Exception:
        pass
    return path


def _phase3_export_vr_pack() -> str:
    out_dir = _phase3__created_subdir("vr_pack")
    files = {}
    files["XRSetup.md"] = (
        "# VR Starter Pack (Unity XR Toolkit / OpenXR)\n\n"
        "This pack provides minimal scripts for:\n"
        "- Teleport locomotion\n"
        "- Snap turn\n\n"
        "Usage:\n"
        "1) Install XR Interaction Toolkit + OpenXR plugin in Unity.\n"
        "2) Add XR Origin (Action-based).\n"
        "3) Add Teleportation Areas to your floor.\n"
        "4) Attach Teleport.cs + SnapTurn.cs to a controller input handler.\n\n"
        "Comfort notes:\n"
        "- Teleport is generally most comfortable.\n"
        "- Keep snap turn at 30–45 degrees.\n"
        "- Avoid accelerating the camera continuously.\n"
    )
    files["Teleport.cs"] = (
        "using UnityEngine;\n"
        "using UnityEngine.XR.Interaction.Toolkit;\n\n"
        "public class Teleport : MonoBehaviour {\n"
        "    public TeleportationProvider provider;\n"
        "    public Transform xrOrigin;\n"
        "    public void TeleportTo(Vector3 destination){\n"
        "        if(provider == null) return;\n"
        "        var req = new TeleportRequest(){ destinationPosition = destination };\n"
        "        provider.QueueTeleportRequest(req);\n"
        "    }\n"
        "}\n"
    )
    files["SnapTurn.cs"] = (
        "using UnityEngine;\n\n"
        "public class SnapTurn : MonoBehaviour {\n"
        "    public Transform xrOrigin;\n"
        "    public float snapDegrees = 45f;\n"
        "    public void TurnLeft(){ if(xrOrigin!=null) xrOrigin.Rotate(0f, -snapDegrees, 0f); }\n"
        "    public void TurnRight(){ if(xrOrigin!=null) xrOrigin.Rotate(0f, snapDegrees, 0f); }\n"
        "}\n"
    )

    for fn, body in files.items():
        p = os.path.join(out_dir, fn)
        try:
            with open(p, "w", encoding="utf-8") as f:
                f.write(body)
        except Exception:
            pass
    return out_dir


def _phase3__voice_record_wav(seconds: int = 6, sr: int = 16000) -> Optional[str]:
    if pyaudio is None or wave is None:
        return None
    seconds = int(max(1, min(VOICE_MAX_SECONDS, seconds)))
    sr = int(max(8000, min(48000, sr)))
    out_dir = _phase3__created_subdir("voice_rituals")
    stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    wav_path = os.path.join(out_dir, f"voice_{stamp}.wav")

    pa = None
    try:
        pa = pyaudio.PyAudio()  # type: ignore
        stream = pa.open(format=pyaudio.paInt16, channels=1, rate=sr, input=True, frames_per_buffer=1024)  # type: ignore
        frames = []
        for _ in range(int(sr / 1024 * seconds)):
            frames.append(stream.read(1024, exception_on_overflow=False))
        stream.stop_stream()
        stream.close()
        pa.terminate()

        with wave.open(wav_path, "wb") as wf:  # type: ignore
            wf.setnchannels(1)
            wf.setsampwidth(2)
            wf.setframerate(sr)
            wf.writeframes(b"".join(frames))
        return wav_path
    except Exception:
        try:
            if pa is not None:
                pa.terminate()
        except Exception:
            pass
        return None


def _phase3__voice_to_notes(wav_path: str, bpm: int = 120) -> List[Tuple[int, float]]:
    notes: List[Tuple[int, float]] = []
    if wave is None:
        return notes
    try:
        with wave.open(wav_path, "rb") as wf:  # type: ignore
            sr = wf.getframerate()
            n = wf.getnframes()
            raw = wf.readframes(n)
        x = np.frombuffer(raw, dtype=np.int16).astype(np.float32)
        if x.size < sr // 2:
            return notes
        x = x / max(1.0, float(np.max(np.abs(x))))

        win = int(0.20 * sr)
        hop = int(0.10 * sr)
        fmin, fmax = 80.0, 1000.0
        beats_per_win = 0.5

        last_note = None
        for i in range(0, len(x) - win, hop):
            seg = x[i:i+win]
            if float(np.mean(np.abs(seg))) < 0.03:
                continue
            sp = np.fft.rfft(seg * np.hanning(len(seg)))
            mag = np.abs(sp)
            freqs = np.fft.rfftfreq(len(seg), d=1.0/sr)
            mask = (freqs >= fmin) & (freqs <= fmax)
            if not np.any(mask):
                continue
            idx = int(np.argmax(mag[mask]))
            f = float(freqs[mask][idx])
            n0 = _phase3__midi_note_from_freq(f)
            if n0 is None:
                continue
            if last_note is None or n0 != last_note:
                notes.append((n0, beats_per_win))
                last_note = n0

        compact: List[Tuple[int, float]] = []
        for n0, b in notes:
            if not compact or compact[-1][0] != n0:
                compact.append((n0, b))
        return compact[:128]
    except Exception:
        return notes


def _phase3__melody_generate_notes(scale: str, steps: int) -> List[int]:
    steps = int(max(4, min(64, steps)))
    root_map = {"C": 60, "D": 62, "E": 64, "F": 65, "G": 67, "A": 69, "B": 71}
    root = root_map.get((scale or "C")[0].upper(), 60)
    major = [0, 2, 4, 5, 7, 9, 11, 12]
    minor = [0, 2, 3, 5, 7, 8, 10, 12]
    use = major if ("major" in (scale or "").lower() or "maj" in (scale or "").lower()) else minor
    out: List[int] = []
    for i in range(steps):
        deg = use[i % len(use)]
        out.append(root + deg)
    return out


def _phase3__melody_pack(notes_midis: List[int], step_beats: float = 0.5) -> List[Tuple[int, float]]:
    return [(int(n), float(step_beats)) for n in notes_midis]


def _phase3_install(self) -> None:
    for sub in ["aurilius", "architect", "ledger", "weaver", "oracle", "melody_nexus", "voice_rituals", "vr_pack"]:
        _phase3__created_subdir(sub)
    _phase3__rituals_dir()

    try:
        self._phase3_brothers = {
            "Aurilius": _BrotherAurilius(self),
            "Architect": _BrotherArchitect(self),
            "Ledger": _BrotherLedger(self),
            "Weaver": _BrotherWeaver(self),
            "Oracle": _BrotherOracle(self),
        }
    except Exception:
        self._phase3_brothers = {}

    try:
        if hasattr(self, "mode_tabs") and "Forge" in getattr(self, "_mode_names", []):
            _phase3_install_forge_ui(self)
    except Exception:
        pass

    try:
        if hasattr(self, "mode_tabs") and "Melody" in getattr(self, "_mode_names", []):
            _phase3_install_melody_ui(self)
    except Exception:
        pass

    try:
        if hasattr(self, "mode_tabs") and "Quarantine" in getattr(self, "_mode_names", []):
            _phase3_install_quarantine_ui(self)
    except Exception:
        pass


def _phase3_install_forge_ui(self) -> None:
    tab = self.mode_tabs.tab("Forge")
    if getattr(self, "_phase3_forge_installed", False):
        return
    self._phase3_forge_installed = True

    out_tb = self._mode_textboxes.get("Forge")
    if out_tb is not None:
        try:
            out_tb.pack_forget()
        except Exception:
            pass

    top = ctk.CTkFrame(tab, fg_color="transparent")
    top.pack(fill="x", padx=10, pady=(8, 6))

    left = ctk.CTkFrame(top, fg_color=PALETTE["panel"])
    left.pack(side="left", fill="both", expand=True, padx=(0, 8))

    ctk.CTkLabel(left, text="Forge Ritual (write here)", text_color=PALETTE["text"],
                 font=ctk.CTkFont(size=13, weight="bold")).pack(anchor="w", padx=10, pady=(10, 4))

    self.forge_input = ctk.CTkTextbox(left, height=140, fg_color=PALETTE["panel2"], text_color=PALETTE["text"])
    self.forge_input.pack(fill="both", expand=True, padx=10, pady=(0, 10))
    try:
        self.forge_input.insert("end", "^ generate\ntargets: unreal unity web3\n\nSummon: Aurilius + Architect\nBuild: a procedural room + VR locomotion + a simple web3 mint stub.\n")
    except Exception:
        pass

    right = ctk.CTkFrame(top, fg_color=PALETTE["panel"])
    right.pack(side="right", fill="y")

    ctk.CTkLabel(right, text="Brothers", text_color=PALETTE["text"],
                 font=ctk.CTkFont(size=13, weight="bold")).pack(anchor="w", padx=10, pady=(10, 4))

    self._phase3_brother_vars = {}
    for name in ["Aurilius", "Architect", "Harmonius", "Ledger", "Weaver", "Oracle"]:
        v = ctk.BooleanVar(value=(name in ("Aurilius", "Architect")))
        self._phase3_brother_vars[name] = v
        ctk.CTkCheckBox(right, text=name, variable=v).pack(anchor="w", padx=10, pady=2)

    ctk.CTkLabel(right, text="Targets", text_color=PALETTE["muted"]).pack(anchor="w", padx=10, pady=(10, 2))
    self._phase3_target_vars = {}
    for t in ["unreal", "unity", "web3", "python", "frontend", "music", "vr"]:
        v = ctk.BooleanVar(value=(t in ("unreal", "unity")))
        self._phase3_target_vars[t] = v
        ctk.CTkCheckBox(right, text=t, variable=v).pack(anchor="w", padx=10, pady=1)

    btnrow = ctk.CTkFrame(right, fg_color="transparent")
    btnrow.pack(fill="x", padx=10, pady=(10, 10))

    def do_parse():
        try:
            self.mode_tabs.set("Forge")
        except Exception:
            pass
        ritual = _phase3_parse_ritual(self.forge_input.get("1.0", "end"))
        tars = [k for k, vv in self._phase3_target_vars.items() if bool(vv.get())]
        if tars:
            ritual["targets"] = tars
        self._phase3_last_ritual = ritual
        self._ui_log("🛠 Ritual parsed:", dim=True)
        self._ui_log(json.dumps(ritual, indent=2, ensure_ascii=False), mono=True)

    def do_save():
        ritual = getattr(self, "_phase3_last_ritual", None)
        if not isinstance(ritual, dict):
            ritual = _phase3_parse_ritual(self.forge_input.get("1.0", "end"))
        ritual["text"] = self.forge_input.get("1.0", "end").strip()
        path = _phase3_save_ritual(ritual)
        self._ui_log(f"✅ Ritual saved → {path}", dim=True)

    def do_run():
        try:
            self.mode_tabs.set("Forge")
        except Exception:
            pass
        ritual = getattr(self, "_phase3_last_ritual", None)
        if not isinstance(ritual, dict):
            ritual = _phase3_parse_ritual(self.forge_input.get("1.0", "end"))
        ritual["text"] = self.forge_input.get("1.0", "end").strip()
        tars = [k for k, vv in self._phase3_target_vars.items() if bool(vv.get())]
        if tars:
            ritual["targets"] = tars
        selected = [k for k, vv in self._phase3_brother_vars.items() if bool(vv.get())]
        if not selected:
            selected = ["Aurilius", "Architect"]
        ritual["brothers"] = selected

        self._ui_log(f"🔥 Running ritual with: {', '.join(selected)}", dim=True)
        ritual["results"] = []
        for bro_name in selected:
            bro = (getattr(self, "_phase3_brothers", {}) or {}).get(bro_name)
            if bro is None:
                ritual["results"].append({"brother": bro_name, "ok": False, "error": "Brother not available"})
                self._ui_log(f"⚠️ {bro_name} missing.", dim=True)
                continue
            self._ui_log(f"— {bro_name} invoking…", dim=True)
            res = bro.invoke(ritual)
            ritual["results"].append({"brother": bro_name, **res})
            if res.get("ok"):
                files = res.get("files") or []
                self._ui_log(f"✅ {bro_name} complete. Files: {len(files)}", dim=True)
                for fp in files[:8]:
                    self._ui_log(f"  • {fp}", dim=True, mono=True)
            else:
                self._ui_log(f"❌ {bro_name} failed: {res.get('error')}", error=True)

        path = _phase3_save_ritual(ritual)
        self._ui_log(f"🧾 Ritual receipt saved → {path}", dim=True)

    ctk.CTkButton(btnrow, text="Parse", command=do_parse).pack(fill="x", pady=2)
    ctk.CTkButton(btnrow, text="Run Ritual", fg_color=PALETTE["accent"], command=do_run).pack(fill="x", pady=2)
    ctk.CTkButton(btnrow, text="Save", command=do_save).pack(fill="x", pady=2)

    if out_tb is not None:
        out_tb.pack(fill="both", expand=True, padx=10, pady=(0, 10))


