    top.pack(fill="x", padx=10, pady=(8, 6))

    panel = ctk.CTkFrame(top, fg_color=PALETTE["panel"])
    panel.pack(fill="x")

    ctk.CTkLabel(panel, text="Melody Nexus (DAW Station)", text_color=PALETTE["text"],
                 font=ctk.CTkFont(size=13, weight="bold")).grid(row=0, column=0, columnspan=6, sticky="w", padx=10, pady=(10, 6))

