    self.mel_stepbeats = ctk.DoubleVar(value=0.5)
    self.mel_render_wav = ctk.BooleanVar(value=True)
    self.mel_realtime = ctk.BooleanVar(value=False)

    ctk.CTkLabel(panel, text="BPM", text_color=PALETTE["muted"]).grid(row=1, column=0, sticky="w", padx=10)
    ctk.CTkSlider(panel, from_=60, to=200, number_of_steps=140, variable=self.mel_bpm).grid(row=2, column=0, sticky="ew", padx=10, pady=(0, 10))

