# PHASE 2+ ADDON — Ritual Parser v2 + Harmonius (AI MIDI) + GBCBS Signatures
# ======================================================================

# Optional deps
try:
    import spacy  # type: ignore
except Exception:
    spacy = None  # type: ignore

try:
    import mido  # type: ignore
except Exception:
    mido = None  # type: ignore

try:
    import torch  # type: ignore
    import torch.nn as nn  # type: ignore
except Exception:
    torch = None  # type: ignore
    nn = None  # type: ignore


def _ritual_parse_v2(text_in: str) -> Dict[str, Any]:
    """Parse a ritual text into symbols / intent / targets.

    - Regex first (fast, deterministic).
    - spaCy (optional) to refine intent phrasing.
    """
    raw = (text_in or "").strip()
    low = raw.lower()

    # Symbols / runes
    symbols: List[str] = []
    sym_map = [
        ("->", "flow"), ("→", "flow"), ("=>", "flow"), ("⇢", "flow"),
        ("^", "directive"), ("∞", "infinite"), ("♪", "music"), ("⚓", "anchor"),
        ("⟐", "gem"), ("⊚", "core"), ("∴", "therefore"), ("🌀", "spiral"),
    ]
    for s, name in sym_map:
        if s in raw and name not in symbols:
            symbols.append(name)

    # Keyword symbols
    for k, name in [
        ("loop", "loop"),
        ("mint", "mint"), ("nft", "mint"),
        ("scrape", "scout"), ("scout", "scout"), ("web", "web"),
        ("seed", "seed"), ("biome", "biome"), ("continent", "continent"),
        ("haptic", "haptic"), ("vibration", "haptic"), ("telemetry", "telemetry"),
        ("midi", "midi"), ("melody", "music"), ("voice", "voice"),
    ]:
        if k in low and name not in symbols:
            symbols.append(name)

    # Targets
    targets: List[str] = []
    def _add_target(t: str) -> None:
        t = (t or "").strip().lower()
        if not t:
            return
        alias = {
            "ue": "unreal", "ue5": "unreal", "unrealengine": "unreal",
            "blueprints": "unreal", "blueprint": "unreal",
            "c#": "unity", "unity3d": "unity",
            "js": "web", "javascript": "web",
            "sol": "web3", "solidity": "web3", "contract": "web3",
            "blockchain": "web3", "nft": "web3",
        }.get(t, t)
        if alias not in targets:
            targets.append(alias)

    # Explicit targets: "targets: unreal unity web3"
    m = re.search(r"targets?\s*:\s*(.+)$", raw, flags=re.I | re.M)
    if m:
        parts = [p.strip() for p in re.split(r"[ ,;\t]+", m.group(1)) if p.strip()]
        for p in parts:
            _add_target(p)

    # Heuristic targets from text
    if any(k in low for k in ["unreal", "ue5", "blueprint", "metasound"]): _add_target("unreal")
    if any(k in low for k in ["unity", "c#", "fmod", "xr toolkit", "openxr"]): _add_target("unity")
    if any(k in low for k in ["react", "three.js", "threejs", "frontend", "wallet"]): _add_target("web")
    if any(k in low for k in ["web3", "solidity", "ipfs", "mint", "nft", "contract"]): _add_target("web3")
    if any(k in low for k in ["python", "script", "tkinter"]): _add_target("python")
    if any(k in low for k in ["midi", "melody", "music", "daw"]): _add_target("music")
    if any(k in low for k in ["vr", "teleport", "snapturn", "comfort"]): _add_target("vr")

    if not targets:
        targets = ["python"]

    # Intent
    intent = ""
    # explicit directive lines: "^ mint", "^ seed", "intent: ..."
    for line in raw.splitlines():
        ln = line.strip()
        if not ln:
            continue
        m2 = re.match(r"^\^\s*([a-zA-Z_\- ]+)", ln)
        if m2:
            intent = m2.group(1).strip().lower()
            break
        m3 = re.match(r"^(intent|do|action)\s*:\s*(.+)$", ln, flags=re.I)
        if m3:
            intent = m3.group(2).strip().lower()
            break

    if not intent:
        # keyword intent guess
        if "seed" in low or "biome" in low or "continent" in low:
            intent = "seed world"
        elif "scrape" in low or "scout" in low:
            intent = "scout"
        elif "mint" in low or "nft" in low:
            intent = "mint"
        elif "haptic" in low or "telemetry" in low:
            intent = "body-link"
        elif "midi" in low or "melody" in low or "music" in low:
            intent = "compose"
        else:
            intent = "generate"

    # Optional: spaCy refine intent phrase (best-effort, no heavy model downloads)
    if spacy is not None:
        try:
            nlp = None
            # Try to load small English model if installed; don't auto-download.
            for model_name in ["en_core_web_sm", "en_core_web_md", "en_core_web_lg"]:
                try:
                    nlp = spacy.load(model_name)
                    break
                except Exception:
                    nlp = None
            if nlp is not None:
                doc = nlp(raw[:2000])
                # pick first main verb lemma
                for token in doc:
                    if token.pos_ == "VERB" and token.dep_ in ("ROOT", "conj"):
                        v = (token.lemma_ or token.text or "").strip().lower()
                        if v:
                            intent = v if intent in ("generate", "compose") else intent
                        break
        except Exception:
            pass

    rid = _id8() if "_id8" in globals() else str(int(time.time()))[-8:]
    return {
        "id": rid,
        "intent": intent,
        "targets": targets,
        "symbols": symbols,
        "text": raw,
    }


