# --------------------------
# Harmonius: AI MIDI evolver
# --------------------------

def _harmonius_find_latest_midi(search_dirs: List[str]) -> str:
    cand: List[Tuple[float, str]] = []
    for d in search_dirs:
        try:
            if not d or not os.path.isdir(d):
                continue
            for nm in os.listdir(d):
                if nm.lower().endswith(".mid") or nm.lower().endswith(".midi"):
                    fp = os.path.join(d, nm)
                    try:
                        cand.append((os.path.getmtime(fp), fp))
                    except Exception:
                        pass
        except Exception:
            pass
    cand.sort(reverse=True)
    return cand[0][1] if cand else ""


def _harmonius_read_midi_pitches(path_in: str) -> List[int]:
    """Return a pitch sequence from a MIDI file.

    Prefers mido if available. Falls back to a minimal SMF parser for format-0 note_on.
    """
    if not path_in or not os.path.isfile(path_in):
        return []
    if mido is not None:
        try:
            mid = mido.MidiFile(path_in)
            pitches: List[int] = []
            for tr in mid.tracks:
                for msg in tr:
                    if msg.type == "note_on" and getattr(msg, "velocity", 0) > 0:
                        pitches.append(int(getattr(msg, "note", 60)))
            return pitches
        except Exception:
            pass

    # Minimal SMF parser (format 0/1). We only capture note_on with velocity > 0.
    try:
        data = open(path_in, "rb").read()
    except Exception:
        return []
    if not data.startswith(b"MThd") or len(data) < 14:
        return []
    pos = 8
    fmt = int.from_bytes(data[pos:pos+2], "big"); pos += 2
    ntr = int.from_bytes(data[pos:pos+2], "big"); pos += 2
    tpq = int.from_bytes(data[pos:pos+2], "big"); pos += 2

    def read_varlen(i: int) -> Tuple[int, int]:
        v = 0
        while i < len(data):
            b = data[i]; i += 1
            v = (v << 7) | (b & 0x7F)
            if (b & 0x80) == 0:
                break
        return v, i

    pitches: List[int] = []
    running = None
    for _ in range(max(1, ntr)):
        # find next track chunk
        if pos + 8 > len(data):
            break
        if data[pos:pos+4] != b"MTrk":
            # scan forward
            nxt = data.find(b"MTrk", pos)
            if nxt < 0:
                break
            pos = nxt
        pos += 4
        tlen = int.from_bytes(data[pos:pos+4], "big"); pos += 4
        end = min(len(data), pos + tlen)
        i = pos
        while i < end:
            _, i = read_varlen(i)  # delta
            if i >= end:
                break
            status = data[i]
            if status < 0x80:
                # running status
                if running is None:
                    break
                status = running
            else:
                i += 1
                running = status

            if status == 0xFF:
                if i >= end:
                    break
                meta_type = data[i]; i += 1
                mlen, i = read_varlen(i)
                i += mlen
                continue
            if status == 0xF0 or status == 0xF7:
                slen, i = read_varlen(i)
                i += slen
                continue

            ev = status & 0xF0
            if ev in (0xC0, 0xD0):  # 1 data byte
                i += 1
            else:
                if i + 2 > end:
                    break
                d1 = data[i]; d2 = data[i+1]; i += 2
                if ev == 0x90 and d2 > 0:
                    pitches.append(int(d1))
        pos = end
    return pitches


def _harmonius_write_midi(pitches: List[int], bpm: int, out_path: str) -> bool:
    try:
        notes = [(int(p), 0.5) for p in pitches if 0 <= int(p) <= 127]
        if not notes:
            return False
        return bool(_phase3__write_midi_simple(notes, int(bpm or 120), out_path))
    except Exception:
        return False


def _harmonius_mutate(pitches: List[int], n: int = 64) -> List[int]:
    if not pitches:
        return []
    out = []
    base = pitches[:]
    for i in range(n):
        p = base[i % len(base)]
        # small random walk
        if random.random() < 0.35:
            p = int(max(36, min(96, p + random.choice([-5, -2, -1, 1, 2, 5]))))
        out.append(p)
    return out


def _harmonius_lstm_evolve(pitches: List[int], steps_out: int = 96, epochs: int = 25, seed_len: int = 32, temperature: float = 1.0) -> List[int]:
    """Evolve a pitch sequence with a tiny Torch LSTM (CPU-friendly).

    If torch is unavailable, caller should fallback to _harmonius_mutate.
    """
    if torch is None or nn is None:
        return _harmonius_mutate(pitches, steps_out)
    if not pitches or len(pitches) < 8:
        return _harmonius_mutate(pitches, steps_out)

    device = torch.device("cpu")
    torch.manual_seed(42)

    # clamp
    seq = [int(max(0, min(127, p))) for p in pitches]
    # build training pairs
    seq_len = int(max(8, min(64, seed_len)))
    xs = []
    ys = []
    for i in range(0, len(seq) - seq_len - 1):
        xs.append(seq[i:i+seq_len])
        ys.append(seq[i+1:i+seq_len+1])
    if len(xs) < 4:
        return _harmonius_mutate(seq, steps_out)

    X = torch.tensor(xs, dtype=torch.long, device=device)
    Y = torch.tensor(ys, dtype=torch.long, device=device)

    class TinyLSTM(nn.Module):
        def __init__(self):
            super().__init__()
            self.emb = nn.Embedding(128, 64)
            self.lstm = nn.LSTM(64, 128, num_layers=1, batch_first=True)
            self.fc = nn.Linear(128, 128)

        def forward(self, x):
            e = self.emb(x)
            o, _ = self.lstm(e)
            return self.fc(o)

    model = TinyLSTM().to(device)
    opt = torch.optim.Adam(model.parameters(), lr=0.003)
    loss_fn = nn.CrossEntropyLoss()

    model.train()
    # short training loop
    bs = min(64, X.shape[0])
    for ep in range(int(max(5, min(120, epochs)))):
        # sample batch
        idx = torch.randint(0, X.shape[0], (bs,), device=device)
        xb = X[idx]
        yb = Y[idx]
        logits = model(xb)  # (B,T,128)
        loss = loss_fn(logits.reshape(-1, 128), yb.reshape(-1))
        opt.zero_grad()
        loss.backward()
        opt.step()

    # Generate
    model.eval()
    seed = seq[-seq_len:] if len(seq) >= seq_len else (seq * ((seq_len // len(seq)) + 1))[:seq_len]
    out = seed[:]
    cur = torch.tensor([seed], dtype=torch.long, device=device)
    with torch.no_grad():
        for _ in range(int(max(16, steps_out))):
            logits = model(cur)[:, -1, :]  # (1,128)
            probs = torch.softmax(logits / float(max(0.2, temperature)), dim=-1).squeeze(0)
            # sample
            nxt = int(torch.multinomial(probs, 1).item())
            out.append(nxt)
            cur = torch.tensor([out[-seq_len:]], dtype=torch.long, device=device)
    return out[-steps_out:]


class _BrotherHarmonius(_Phase3BrotherBase):
    name = "Harmonius"
    output_subdir = "harmonius"
    description = "AI melody evolver. Voice→MIDI → LSTM evolution → new MIDI."

    def invoke(self, ritual: Dict[str, Any]) -> Dict[str, Any]:
        try:
            text = (ritual.get("text") or "") if isinstance(ritual, dict) else ""
            bpm = 120
            try:
                bpm = int(ritual.get("bpm") or 120)
            except Exception:
                bpm = 120

            # Try to locate a MIDI path in the ritual text
            midi_path = ""
            m = re.search(r"(?:midi|file)\s*:\s*(.+?\.(?:mid|midi))\b", text, flags=re.I)
            if m:
                midi_path = m.group(1).strip().strip('"').strip("'")
            if midi_path and not os.path.isabs(midi_path):
                # relative to cwd / well
                cand = [midi_path, os.path.join("well", midi_path), os.path.join(_phase3__created_subdir("voice_rituals"), midi_path)]
                for c in cand:
                    if os.path.isfile(c):
                        midi_path = c
                        break

            if not midi_path or not os.path.isfile(midi_path):
                midi_path = _harmonius_find_latest_midi([
                    _phase3__created_subdir("voice_rituals"),
                    _phase3__created_subdir("melody_nexus"),
                    os.path.join("well", "created"),
                ])

            if not midi_path:
                return {"ok": False, "error": "No MIDI found. Run Voice→MIDI first or specify 'midi: path.mid' in the ritual."}

            pitches = _harmonius_read_midi_pitches(midi_path)
            if not pitches:
                return {"ok": False, "error": f"Could not extract notes from {midi_path}"}

            # Evolve
            steps_out = 96
            epochs = 25
            temperature = 1.0
            try:
                steps_out = int(ritual.get("steps_out") or 96)
            except Exception:
                pass
            try:
                epochs = int(ritual.get("epochs") or 25)
            except Exception:
                pass
            try:
                temperature = float(ritual.get("temperature") or 1.0)
            except Exception:
                pass

            evolved = _harmonius_lstm_evolve(pitches, steps_out=steps_out, epochs=epochs, seed_len=32, temperature=temperature) if (torch is not None) else _harmonius_mutate(pitches, steps_out)

            ritual_id = ritual.get("id") or "ritual"
            out_dir = _phase3__created_subdir(self.output_subdir)
            stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
            mid_out = os.path.join(out_dir, f"{stamp}_{_phase3__slug(ritual_id)}_harmonius_evolved.mid")
            wav_out = os.path.join(out_dir, f"{stamp}_{_phase3__slug(ritual_id)}_harmonius_evolved.wav")

            ok_mid = _harmonius_write_midi(evolved, bpm=bpm, out_path=mid_out)
            files = []
            if ok_mid:
                files.append(mid_out)

            # Optional: render a WAV using existing Phase3 renderer if available
            try:
                if ok_mid and bool(ritual.get("render_wav", True)) and "_phase3__render_wav" in globals():
                    # Render sine-wave at pitch sequence
                    _phase3__render_wav([(p, 0.5) for p in evolved], bpm, wav_out)  # type: ignore
                    if os.path.isfile(wav_out):
                        files.append(wav_out)
            except Exception:
                pass

            # Create a short summary markdown
            summary = f"# Harmonius Evolution\n\nInput MIDI: `{midi_path}`\n\nGenerated: `{os.path.basename(mid_out)}`\n\nTorch: `{bool(torch is not None)}`\n"
            md_files = self._write_output_files(ritual_id, summary)
            files.extend(md_files)

            return {"ok": True, "files": files, "message": "Harmonius evolution complete."}
        except Exception as e:
            return {"ok": False, "error": str(e)}


