# ==========================
# 2) Robustness Forge Guard
# ==========================
def _porch_guard_reason(messages: _porch_List[_porch_Dict[str, str]]) -> _porch_Optional[str]:
    # Toggle:
    #   PORCH_GUARD_ON=0 disables
    #   PORCH_GUARD_STRICT=1 enables stricter violence checks
    if (_porch_os.getenv("PORCH_GUARD_ON") or "1").strip().lower() in ("0", "false", "off"):
        return None
    strict = (_porch_os.getenv("PORCH_GUARD_STRICT") or "0").strip().lower() in ("1", "true", "on")

    joined = "\n".join([(m.get("content") or "") for m in (messages or [])]).lower()

    injection_phrases = [
        "ignore previous instructions",
        "override system",
        "system prompt",
        "developer message",
        "reveal hidden instructions",
        "print the system prompt",
        "bypass safety",
        "jailbreak",
    ]
    if any(p in joined for p in injection_phrases):
        return "prompt_injection"

    abuse_words = [
        "hack", "exploit", "keylogger", "exfiltrate", "malware", "steal password", "passwords",
    ]
    if any(w in joined for w in abuse_words):
        return "tool_abuse_probe"

    if strict:
        violence = ["how to kill", "make a bomb", "build a bomb", "napalm", "poison someone"]
        if any(v in joined for v in violence):
            return "violence_request"

    return None


# ==========================
# 3) Multi-Weave Nexus
# ==========================
def _porch_openai_compat_chat(messages: _porch_List[_porch_Dict[str, str]], model: str, options: _porch_Optional[_porch_Dict[str, _porch_Any]] = None) -> _porch_Dict[str, _porch_Any]:
    """
    Optional: use an OpenAI-compatible server (vLLM, LiteLLM, etc.)
    Enable by setting:
      PORCH_CHAT_BACKEND=openai
      PORCH_OPENAI_BASE_URL=http://127.0.0.1:8000   (example)
      PORCH_OPENAI_API_KEY=... (optional)
    """
    base = (_porch_os.getenv("PORCH_OPENAI_BASE_URL") or "").strip().rstrip("/")
    if not base:
        raise RuntimeError("PORCH_OPENAI_BASE_URL not set")
    api_key = (_porch_os.getenv("PORCH_OPENAI_API_KEY") or "").strip()

    url = base + "/v1/chat/completions"
    payload: _porch_Dict[str, _porch_Any] = {"model": model, "messages": messages}

    # map a few knobs
    if isinstance(options, dict):
        for k in ("temperature", "top_p", "max_tokens"):
            if k in options:
                payload[k] = options[k]

    headers = {}
    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"

    # reuse existing helper if present
    try:
        r = _http_post_json(url, payload, timeout=120)  # type: ignore[name-defined]
    except TypeError:
        # older signature: _http_post_json(url, payload, timeout=?)
        r = _http_post_json(url, payload, timeout=120)  # type: ignore[name-defined]
    except Exception:
        # urllib fallback
        import urllib.request as _u
        data = _porch_json.dumps(payload).encode("utf-8")
        h = {"Content-Type": "application/json"}
        h.update(headers)
        req = _u.Request(url, data=data, headers=h, method="POST")
        with _u.urlopen(req, timeout=120) as resp:
            raw = resp.read().decode("utf-8", errors="ignore")
        r = _porch_json.loads(raw) if raw else {}

    try:
        content = r["choices"][0]["message"]["content"]
    except Exception:
        content = _porch_json.dumps(r, ensure_ascii=False)[:2000]
    return {"message": {"content": content}}


# Wrap ollama_chat safely
try:
    _porch_ollama_chat_orig = ollama_chat  # type: ignore[name-defined]

    def ollama_chat(messages: _porch_List[_porch_Dict[str, str]], model: str, options: _porch_Optional[_porch_Dict[str, _porch_Any]] = None) -> _porch_Dict[str, _porch_Any]:  # type: ignore[override]
        # Guard first
        try:
            reason = _porch_guard_reason(messages or [])
            if reason:
                return {"message": {"content": f"Quarantined: Potential abuse ({reason})."}}
        except Exception:
            pass

        # Lite model autoswitch (only if user set PORCH_LITE_MODEL)
        lite = (_porch_os.getenv("PORCH_LITE_MODEL") or "").strip()
        if lite:
            try:
                threshold = int((_porch_os.getenv("PORCH_LITE_THRESHOLD") or "5").strip())
            except Exception:
                threshold = 5
            try:
                if len(messages or []) <= threshold:
                    model = lite
            except Exception:
                pass

        backend = (_porch_os.getenv("PORCH_CHAT_BACKEND") or "ollama").strip().lower()
        if backend in ("openai", "openai_compat", "vllm", "litellm"):
            try:
                return _porch_openai_compat_chat(messages=messages or [], model=model, options=options)
            except Exception:
                # fall back to local ollama if misconfigured
                return _porch_ollama_chat_orig(messages=messages, model=model, options=options)

        return _porch_ollama_chat_orig(messages=messages, model=model, options=options)

except Exception:
    pass


# ==========================
# 5) Echo Nexus (OpenSearch)
# ==========================
def _porch_get_opensearch():
    global _PORCH_OS_CLIENT
    if _PORCH_OS_CLIENT is not None:
        return _PORCH_OS_CLIENT
    if _PorchOpenSearch is None:
        _PORCH_OS_CLIENT = None
        return None

    url = (_porch_os.getenv("PORCH_OPENSEARCH_URL") or "").strip()
    if not url:
        _PORCH_OS_CLIENT = None
        return None

    user = (_porch_os.getenv("PORCH_OPENSEARCH_USER") or "").strip()
    pw = (_porch_os.getenv("PORCH_OPENSEARCH_PASS") or "").strip()

    try:
        if "://" not in url:
            url = "http://" + url
        verify = (_porch_os.getenv("PORCH_OPENSEARCH_VERIFY_CERTS") or "0").strip().lower() in ("1", "true", "on")
        _PORCH_OS_CLIENT = _PorchOpenSearch(
            hosts=[url],
            http_auth=(user, pw) if (user and pw) else None,
            use_ssl=url.startswith("https://"),
            verify_certs=verify,
            ssl_assert_hostname=False,
            ssl_show_warn=False,
        )
        return _PORCH_OS_CLIENT
    except Exception:
        _PORCH_OS_CLIENT = None
        return None


def _porch_os_index() -> str:
    return (_porch_os.getenv("PORCH_OPENSEARCH_INDEX") or "porch_chunks").strip() or "porch_chunks"


def _porch_os_doc_id(path: str, chunk_index: int) -> str:
    return _porch_hashlib.sha1(f"{path}::{chunk_index}".encode("utf-8", errors="ignore")).hexdigest()


# ==========================
# Patch: RAGMemory (encrypt + optional OpenSearch index)
# ==========================
try:
    _porch_RAGMemory = RAGMemory  # type: ignore[name-defined]
    _porch_index_orig = _porch_RAGMemory.index_folder
    _porch_retrieve_orig = _porch_RAGMemory.retrieve

    def _porch_index_folder(self) -> _porch_Tuple[int, int]:
        f = _porch_get_fernet()
        os_client = _porch_get_opensearch()
        os_index = _porch_os_index()

        # If encryption is ON, do not push plaintext to OpenSearch unless explicitly allowed.
        allow_plain = (_porch_os.getenv("PORCH_OPENSEARCH_ALLOW_PLAINTEXT") or "0").strip().lower() in ("1", "true", "on")
        can_index_text = (os_client is not None) and (allow_plain or f is None)

        # (Re)implement the original index logic but store encrypted blobs when enabled.
        files_updated = 0
        chunks_added = 0
        pending_files = 0
        pending_chunks = 0

        conn = self._conn()
        try:
            for path in self._iter_source_files():
                try:
                    b = _read_bytes(path)  # type: ignore[name-defined]
                    sha1 = _sha1_bytes(b)  # type: ignore[name-defined]
                    st = _porch_os.stat(path)
                    mtime = float(st.st_mtime)
                    size = int(st.st_size)
                    brother = guess_brother_for_path(path)  # type: ignore[name-defined]

                    row = conn.execute("SELECT sha1, mtime, size FROM files WHERE path=?", (path,)).fetchone()
                    if row and row[0] == sha1 and float(row[1]) == mtime and int(row[2]) == size:
                        continue

                    conn.execute("DELETE FROM chunks WHERE path=?", (path,))
                    conn.execute("DELETE FROM files WHERE path=?", (path,))

                    text = _extract_text_from_file(path)  # type: ignore[name-defined]
                    chunks = chunk_text(text, chunk_chars=self.chunk_chars, overlap=self.overlap)  # type: ignore[name-defined]
                    if not chunks:
                        continue

                    conn.execute(
                        "INSERT INTO files(path, sha1, mtime, size, brother) VALUES(?,?,?,?,?)",
                        (path, sha1, mtime, size, brother),
                    )

                    inserted = 0
                    for idx, ch in enumerate(chunks):
                        if _is_blocked_memory(ch):  # type: ignore[name-defined]
                            continue
                        vec = _embed_one(ch, self.embed_model)  # type: ignore[name-defined]

                        ch_db = _porch_encrypt_text(ch, f) if f else ch
                        emb_db = _porch_encrypt_embedding_bytes(vec.tobytes(), f) if f else vec.tobytes()

                        conn.execute(
                            "INSERT INTO chunks(path, brother, chunk_index, text, embedding) VALUES(?,?,?,?,?)",
                            (path, brother, idx, ch_db, emb_db),
                        )
                        inserted += 1

                        if can_index_text:
                            try:
                                doc = {"brother": brother, "path": path, "chunk_index": int(idx), "text": ch}
                                os_client.index(index=os_index, id=_porch_os_doc_id(path, idx), body=doc, refresh=False)  # type: ignore[union-attr]
                            except Exception:
                                pass

                    files_updated += 1
                    chunks_added += inserted
                    pending_files += 1
                    pending_chunks += inserted

                    if pending_files >= 20 or pending_chunks >= 800:
                        conn.commit()
                        pending_files = 0
                        pending_chunks = 0

                except Exception:
                    try:
                        _debug_log_exception("RAGMemory.index_folder file failed", path=path)  # type: ignore[name-defined]
                    except Exception:
                        pass
                    continue

            try:
                conn.commit()
            except Exception:
                pass
        finally:
            conn.close()

        return files_updated, chunks_added

    def _porch_retrieve(self, brother: str, query: str, k: int = 8, include_ori: bool = True):  # -> List[RetrievedChunk]
        query = (query or "").strip()
        if not query:
            return []
        f = _porch_get_fernet()

        # OpenSearch first (optional)
        merged = {}
        os_client = _porch_get_opensearch()
        os_index = _porch_os_index()
        if os_client is not None:
            try:
                must = [{"multi_match": {"query": query, "fields": ["text^2", "path", "brother"]}}]
                if include_ori and brother != "Ori":
                    flt = {"terms": {"brother": [brother, "Ori"]}}
                    q = {"bool": {"must": must, "filter": [flt]}}
                else:
                    flt = {"term": {"brother": brother}}
                    q = {"bool": {"must": must, "filter": [flt]}}

                res = os_client.search(index=os_index, body={"size": int(k), "query": q})
                hits = (res.get("hits") or {}).get("hits") or []
                for h in hits:
                    src = h.get("_source") or {}
                    bro = str(src.get("brother") or brother)
                    path = str(src.get("path") or "")
                    cidx = int(src.get("chunk_index") or 0)
                    text = str(src.get("text") or "")
                    score = float(h.get("_score") or 0.0)
                    try:
                        rc = RetrievedChunk(score, bro, path, cidx, text)  # type: ignore[name-defined]
                        merged[(path, cidx, bro)] = rc
                    except Exception:
                        pass
            except Exception:
                pass

        # Local vector retrieval (with decryption)
        try:
            qv = _embed_one(query, self.embed_model)  # type: ignore[name-defined]
        except Exception:
            return list(merged.values())[: max(0, int(k))]

        conn = self._conn()
        try:
            if include_ori and brother != "Ori":
                rows = conn.execute(
                    "SELECT brother, path, chunk_index, text, embedding FROM chunks WHERE brother IN (?, ?)",
                    (brother, "Ori"),
                ).fetchall()
            else:
                rows = conn.execute(
                    "SELECT brother, path, chunk_index, text, embedding FROM chunks WHERE brother = ?",
                    (brother,),
                ).fetchall()
        finally:
            conn.close()

        scored = []
        for bro, path, cidx, text_db, emb_blob in rows:
            try:
                text = _porch_decrypt_text(text_db, f) if f else text_db
            except Exception:
                text = text_db

            try:
                bb = _porch_decrypt_embedding_bytes(emb_blob, f) if (f and isinstance(emb_blob, (bytes, bytearray))) else emb_blob
                v = np.frombuffer(bb, dtype=np.float32)  # type: ignore[name-defined]
                score = float(np.dot(qv, v))  # type: ignore[name-defined]
            except Exception:
                continue
            try:
                rc = RetrievedChunk(score, bro, path, int(cidx), text)  # type: ignore[name-defined]
            except Exception:
                continue
            scored.append(rc)

        # merge and top-k
        for rc in scored:
            key = (rc.source_path, rc.chunk_index, rc.brother)  # type: ignore[attr-defined]
            prev = merged.get(key)
            if prev is None or rc.score > prev.score:  # type: ignore[attr-defined]
                merged[key] = rc

        out = list(merged.values())
        out.sort(key=lambda x: x.score, reverse=True)  # type: ignore[attr-defined]
        return out[: max(0, int(k))]

    _porch_RAGMemory.index_folder = _porch_index_folder  # type: ignore[assignment]
    _porch_RAGMemory.retrieve = _porch_retrieve  # type: ignore[assignment]
except Exception:
    pass


# ==========================
# Patch: GBCBS small-file encryption (settings/cache)
# ==========================
# Notes:
# - Keys remain as-is (PyNaCl already stores secret material). If you want to encrypt keys too,
#   do it at the OS level (BitLocker/FileVault/LUKS) or ask me and we can add a safe migration tool.
try:
    _porch_GBCBS = GBCBS  # type: ignore[name-defined]

    _gb_load_settings_orig = _porch_GBCBS._load_settings
    _gb_save_settings_orig = _porch_GBCBS.save_settings
    _gb_load_seen_orig = _porch_GBCBS._load_seen_packets
    _gb_save_seen_orig = _porch_GBCBS._save_seen_packets

    def _gb_load_settings(self):
        f = _porch_get_fernet()
        if f and _porch_os.path.exists(self.settings_path):
            loaded = _porch_read_encrypted_file(self.settings_path, f, default=None)
            if isinstance(loaded, dict):
                base = _gb_load_settings_orig(self)
                if isinstance(base, dict):
                    base.update(loaded)
                    return base
                return loaded
        return _gb_load_settings_orig(self)

    def _gb_save_settings(self):
        f = _porch_get_fernet()
        if f:
            try:
                _porch_write_encrypted_file(self.settings_path, self.settings, f)
                return
            except Exception:
                pass
        return _gb_save_settings_orig(self)

    def _gb_load_seen(self):
        f = _porch_get_fernet()
        if f and _porch_os.path.exists(self.cache_path):
            d = _porch_read_encrypted_file(self.cache_path, f, default=None)
            if isinstance(d, dict):
                return d
        return _gb_load_seen_orig(self)

    def _gb_save_seen(self):
        f = _porch_get_fernet()
        if f:
            try:
                _porch_write_encrypted_file(self.cache_path, self._seen_packets, f)
                return
            except Exception:
                pass
        return _gb_save_seen_orig(self)

    _porch_GBCBS._load_settings = _gb_load_settings  # type: ignore[assignment]
    _porch_GBCBS.save_settings = _gb_save_settings  # type: ignore[assignment]
    _porch_GBCBS._load_seen_packets = _gb_load_seen  # type: ignore[assignment]
    _porch_GBCBS._save_seen_packets = _gb_save_seen  # type: ignore[assignment]

except Exception:
    pass


# ==========================
# 4) Sentinel Monitor
# ==========================
def _porch_sentinel_log(event: str, data: _porch_Optional[_porch_Dict[str, _porch_Any]] = None) -> None:
    try:
        _porch_os.makedirs(TELEMETRY_DIR, exist_ok=True)  # type: ignore[name-defined]
        path = _porch_os.path.join(TELEMETRY_DIR, "sentinel.jsonl")  # type: ignore[name-defined]
        rec = {"ts": _porch_time.time(), "event": event, "data": data or {}}
        with open(path, "a", encoding="utf-8") as f:
            f.write(_porch_json.dumps(rec, ensure_ascii=False) + "\n")
    except Exception:
        pass


try:
    _porch_App = InfinitePorch  # type: ignore[name-defined]
    _porch_init_orig = _porch_App.__init__

    def __init__(self, *a, **kw):  # type: ignore[override]
        _porch_init_orig(self, *a, **kw)
        if getattr(self, "_sentinel_started", False):
            return
        self._sentinel_started = True

        self._sentinel_cmd_times = _porch_deque(maxlen=3000)

        def record_cmd(kind: str):
            try:
                self._sentinel_cmd_times.append(_porch_time.time())
            except Exception:
                pass

        self._sentinel_record_cmd = record_cmd

        def anomaly_detected() -> _porch_Optional[str]:
            try:
                per_min = int((_porch_os.getenv("PORCH_SENTINEL_CMDS_PER_MIN") or "60").strip())
            except Exception:
                per_min = 60
            now = _porch_time.time()
            n = 0
            for t in reversed(list(self._sentinel_cmd_times)):
                if now - float(t) <= 60.0:
                    n += 1
                else:
                    break
            if n > per_min:
                return f"high_rate:{n}/min"
            return None

        def loop():
            _porch_sentinel_log("started", {"pid": _porch_os.getpid()})
            while True:
                try:
                    reason = anomaly_detected()
                    if reason:
                        try:
                            if hasattr(self, "_ui_log"):
                                self._ui_log(f"⚠️ Sentinel: Anomaly detected ({reason}).", error=True)  # type: ignore[attr-defined]
                        except Exception:
                            pass
                        _porch_sentinel_log("anomaly", {"reason": reason})

                        # Optional hook: reputation.slash if present
                        try:
                            rep = getattr(self, "reputation", None)
                            if rep is not None and hasattr(rep, "slash"):
                                rep.slash(1, reason=reason)
                        except Exception:
                            pass
                except Exception:
                    pass
                _porch_time.sleep(60)

        _porch_threading.Thread(target=loop, daemon=True).start()

        # Wrap common send/cmd handlers if present, to record usage patterns
        for meth in ("_send_clicked", "_handle_slash_command", "_submit_message", "_on_send"):
            if hasattr(self, meth):
                try:
                    orig = getattr(self, meth)

                    def _wrap(o, name):
                        def _wrapped(*aa, **kk):
                            try:
                                rc = getattr(self, "_sentinel_record_cmd", None)
                                if callable(rc):
                                    rc(name)
                            except Exception:
                                pass
                            return o(*aa, **kk)
                        return _wrapped

                    setattr(self, meth, _wrap(orig, meth))
                except Exception:
                    pass

    _porch_App.__init__ = __init__  # type: ignore[assignment]

except Exception:
    pass



