#   $env:PORCH_MELODY_ON="1"      # auto-enable Melody
#   $env:PORCH_IPFS_ON="1"        # auto-enable Ancestral Well
#   $env:PORCH_HAPTICS_ON="1"     # auto-enable Haptic bus
