def _porch_truthy(v: object) -> bool:
    s = str(v or "").strip().lower()
    return s in ("1", "true", "yes", "y", "on")


def _porch_safe_mkdir(p: str) -> None:
    try:
        os.makedirs(p, exist_ok=True)
    except Exception:
        pass


def _porch_iso() -> str:
    try:
        return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat() + "Z"
    except Exception:
        return _now_ts()


# ----------------------------
# Haptic Event Bus
# ----------------------------
class HapticShader:
    """
    Simple haptic event encoder that writes JSONL events.
    A "real bus" that other modules can call.
    """
    DEFAULTS = {
        "gold_thrum": {"freq": 7.83, "amp": 0.55, "ms": 2200},
        "static_itch": {"freq": 55.0, "amp": 0.35, "ms": 700},
        "verify_ping": {"freq": 33.0, "amp": 0.40, "ms": 450},
        "alert": {"freq": 90.0, "amp": 0.70, "ms": 900},
        "calm": {"freq": 6.2, "amp": 0.25, "ms": 2400},
    }

    def __init__(self, events_path: str):
        self.events_path = events_path
        _porch_safe_mkdir(os.path.dirname(events_path) or ".")

    def emit(self, event: str, freq: Optional[float] = None, amp: Optional[float] = None, ms: Optional[int] = None,
             meta: Optional[Dict[str, Any]] = None) -> None:
        e = (event or "event").strip()
        d = dict(self.DEFAULTS.get(e, {}))
        if freq is not None:
            d["freq"] = float(freq)
        if amp is not None:
            d["amp"] = float(amp)
        if ms is not None:
            d["ms"] = int(ms)
        rec = {
            "ts": time.time(),
            "iso": _porch_iso(),
            "event": e,
            "freq": float(d.get("freq", 20.0)),
            "amp": float(d.get("amp", 0.5)),
            "ms": int(d.get("ms", 600)),
            "meta": meta or {},
        }
        try:
            with open(self.events_path, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")
        except Exception:
            pass


# ----------------------------
# Oracle-Eye (Vision Stream)
# ----------------------------
def _porch_capture_webcam(out_path: str, cam_index: int = 0) -> bool:
    if cv2 is None:
        return False
    try:
        cap = cv2.VideoCapture(int(cam_index))
        if not cap.isOpened():
            try:
                cap.release()
            except Exception:
                pass
            return False
        ok, frame = cap.read()
        try:
            cap.release()
        except Exception:
            pass
        if not ok or frame is None:
            return False
        cv2.imwrite(out_path, frame)
        return True
    except Exception:
        return False


def _porch_ollama_chat_with_image(image_path: str, prompt: str, model: str) -> str:
    """
    Uses Ollama /api/chat with message.images.
    Works with models like llava, moondream, etc. if installed in Ollama.
    """
    try:
        b = _read_bytes(image_path)
        b64 = base64.b64encode(b).decode("utf-8")
        payload = {
            "model": model,
            "stream": False,
            "messages": [{
                "role": "user",
                "content": prompt or "Describe this image.",
                "images": [b64],
            }],
        }
        r = _http_post_json(f"{OLLAMA_URL}/api/chat", payload, timeout=180)
        return str(((r or {}).get("message") or {}).get("content") or "").strip()
    except Exception as e:
        return f"(Vision model call failed: {e})"


# ----------------------------
# Bifrost (Live-Link WebSocket)
# ----------------------------
class _PorchBifrostServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 8765):
        self.host = host
        self.port = int(port)
        self._clients = set()
        self._thread = None
        self._loop = None
        self._server = None
        self._alive = threading.Event()

    async def _handler(self, ws):
        self._clients.add(ws)
        try:
            await ws.send(json.dumps({"type": "hello", "ts": time.time(), "msg": "bifrost_connected"}))
            async for _ in ws:
                # Keep it simple: ignore inbound; this is a broadcast bridge.
                pass
        finally:
            try:
                self._clients.discard(ws)
            except Exception:
                pass

    async def _run(self):
        self._alive.set()
        if websockets is None:
            return
        self._server = await websockets.serve(self._handler, self.host, self.port)
        await self._server.wait_closed()

    def start(self) -> bool:
        if websockets is None:
            return False
        if self._thread and self._thread.is_alive():
            return True

        def _worker():
            try:
                self._loop = asyncio.new_event_loop()
                asyncio.set_event_loop(self._loop)
                self._loop.run_until_complete(self._run())
            except Exception:
                pass

        self._thread = threading.Thread(target=_worker, daemon=True)
        self._thread.start()
        return True

    def stop(self) -> None:
        try:
            if self._server is not None:
                self._server.close()
        except Exception:
            pass
        try:
            if self._loop is not None:
                self._loop.call_soon_threadsafe(lambda: None)
                self._loop.stop()
        except Exception:
            pass

    def status(self) -> str:
        if websockets is None:
            return "missing_dep(websockets)"
        if self._thread and self._thread.is_alive():
            return f"on ws://{self.host}:{self.port} (clients={len(self._clients)})"
        return "off"

    def broadcast(self, obj: Dict[str, Any]) -> None:
        if websockets is None:
            return
        if not (self._thread and self._thread.is_alive() and self._loop):
            return
        msg = json.dumps(obj, ensure_ascii=False)

        async def _send_all():
            dead = []
            for ws in list(self._clients):
                try:
                    await ws.send(msg)
                except Exception:
                    dead.append(ws)
            for ws in dead:
                try:
                    self._clients.discard(ws)
                except Exception:
                    pass

        try:
            asyncio.run_coroutine_threadsafe(_send_all(), self._loop)
        except Exception:
            pass


# ----------------------------
# Ancestral Well (IPFS)
# ----------------------------
class _PorchAncestralWell:
    def __init__(self):
        self.enabled = False
        self.client = None

    def on(self) -> str:
        if ipfshttpclient is None:
            self.enabled = False
            self.client = None
            return "IPFS disabled (missing dep: ipfshttpclient)."
        try:
            addr = (os.getenv("PORCH_IPFS_ADDR") or "").strip() or "/dns/localhost/tcp/5001/http"
            self.client = ipfshttpclient.connect(addr)
            self.enabled = True
            return f"IPFS enabled ({addr})."
        except Exception as e:
            self.enabled = False
            self.client = None
            return f"IPFS connect failed: {e}"

    def off(self) -> str:
        self.enabled = False
        try:
            if self.client is not None:
                self.client.close()
        except Exception:
            pass
        self.client = None
        return "IPFS disabled."

    def status(self) -> str:
        if not self.enabled:
            return "off"
        return "on"

    def push_file(self, path: str) -> str:
        if not self.enabled or self.client is None:
            return "IPFS is off. Use /ancestral on"
        p = Path(path).expanduser()
        if not p.exists():
            return f"File not found: {p}"
        try:
            res = self.client.add(str(p))
            cid = res["Hash"] if isinstance(res, dict) else (res[-1]["Hash"] if res else "")
            try:
                self.client.pin.add(cid)
            except Exception:
                pass
            return f"Pushed to IPFS: {cid}"
        except Exception as e:
            return f"IPFS push failed: {e}"


# ----------------------------
# Melody Nexus (MIDI + rhythm hooks)
# ----------------------------
def _porch_write_thrum_midi(out_path: str, hz: float = 7.83, seconds: float = 12.0) -> str:
    """
    Writes a tiny MIDI file representing a 'thrum'. If MIDI libs missing, writes a text placeholder.
    """
    hz = float(hz)
    seconds = float(max(1.0, seconds))
    _porch_safe_mkdir(os.path.dirname(out_path) or ".")

    if MIDIFile is None:
        try:
            with open(out_path + ".txt", "w", encoding="utf-8") as f:
                f.write(f"Melody Nexus placeholder\nfreq={hz}\nseconds={seconds}\n")
            return f"(midiutil missing) wrote {out_path}.txt"
        except Exception as e:
            return f"Failed: {e}"

    try:
        midi = MIDIFile(1)
        track = 0
        time0 = 0
        midi.addTempo(track, time0, 120)
        # Map low frequency to a low note and pulse it
        base_note = 36  # C2
        beats = int(seconds * 2)
        for i in range(beats):
            midi.addNote(track, 0, base_note, i * 0.5, 0.25, 80)
        with open(out_path, "wb") as f:
            midi.writeFile(f)
        return f"Wrote MIDI: {out_path}"
    except Exception as e:
        return f"Melody write failed: {e}"


