# ----------------------------
# Anchor DB helpers
# ----------------------------
def _porch_anchors_ensure_table(db_path: str) -> None:
    try:
        conn = sqlite3.connect(db_path)
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS world_anchors(
                name TEXT PRIMARY KEY,
                x REAL, y REAL, z REAL,
                meta TEXT,
                updated_at TEXT
            )
            """
        )
        conn.commit()
    except Exception:
        pass
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _porch_anchor_add(db_path: str, name: str, x: float, y: float, z: float, meta: str = "") -> str:
    _porch_anchors_ensure_table(db_path)
    try:
        conn = sqlite3.connect(db_path)
        conn.execute(
            "INSERT OR REPLACE INTO world_anchors(name, x, y, z, meta, updated_at) VALUES(?,?,?,?,?,?)",
            (name, float(x), float(y), float(z), meta, _porch_iso()),
        )
        conn.commit()
        return f"Anchor saved: {name} ({x}, {y}, {z})"
    except Exception as e:
        return f"Anchor add failed: {e}"
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _porch_anchor_del(db_path: str, name: str) -> str:
    _porch_anchors_ensure_table(db_path)
    try:
        conn = sqlite3.connect(db_path)
        conn.execute("DELETE FROM world_anchors WHERE name=?", (name,))
        conn.commit()
        return f"Anchor deleted: {name}"
    except Exception as e:
        return f"Anchor delete failed: {e}"
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _porch_anchor_list(db_path: str) -> List[Dict[str, Any]]:
    _porch_anchors_ensure_table(db_path)
    out = []
    try:
        conn = sqlite3.connect(db_path)
        rows = conn.execute("SELECT name, x, y, z, meta, updated_at FROM world_anchors ORDER BY name").fetchall()
        for r in rows:
            out.append({"name": r[0], "x": r[1], "y": r[2], "z": r[3], "meta": r[4] or "", "updated_at": r[5] or ""})
    except Exception:
        pass
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return out


# ----------------------------
# Patch: add runtime feature manager to InfinitePorch
# ----------------------------
try:
    _PorchApp = InfinitePorch  # type: ignore[name-defined]
    _orig_init = _PorchApp.__init__
    _orig_slash = _PorchApp._handle_slash_command

    def __init__(self, *a, **kw):  # type: ignore[override]
        _orig_init(self, *a, **kw)

        # feature state
        self._porch_eye_on = False
        self._porch_bifrost_on = False
        self._porch_melody_on = False
        self._porch_ipfs_on = False
        self._porch_haptics_on = False

        # instances
        self._porch_haptics = HapticShader(HAPTICS_EVENTS_FILE)
        self._porch_bifrost = _PorchBifrostServer(
            host=(os.getenv("PORCH_BIFROST_HOST") or "127.0.0.1"),
            port=int(os.getenv("PORCH_BIFROST_PORT") or "8765"),
        )
        # retro controller bridge (Bifrost inbound -> queue / optional key injection)
        self._porch_retro_input_on = False
        self._porch_retro_inject_on = False
        try:
            _rs = self._retro_load_settings()
            self._porch_retro_input_on = bool(_rs.get("controller_input", False))
            self._porch_retro_inject_on = bool(_rs.get("key_inject", False))
        except Exception:
            pass
        self._porch_retro_btn_state = {}
        try:
            from collections import deque
            self._porch_retro_debug = deque(maxlen=400)
            self._porch_retro_debug_last = {"ts": 0.0, "source": "", "events": []}
        except Exception:
            self._porch_retro_debug = None
            self._porch_retro_debug_last = None
        self._porch_retro_input_queue = os.path.join(WELL_FOLDER, "retro", "input_queue.jsonl")
        try:
            os.makedirs(os.path.dirname(self._porch_retro_input_queue), exist_ok=True)
        except Exception:
            pass

        # optional keyboard injection backend (safe allowlist only)
        self._porch_retro_kb = None
        self._porch_retro_keys = {}
        self._porch_retro_key_consts = {}
        try:
            from pynput.keyboard import Controller as _KBController, Key as _KBKey  # type: ignore
            self._porch_retro_kb = _KBController()
            self._porch_retro_key_consts = {
                "UP": _KBKey.up, "DOWN": _KBKey.down, "LEFT": _KBKey.left, "RIGHT": _KBKey.right,
                "ENTER": _KBKey.enter, "SHIFT": _KBKey.shift, "ESC": _KBKey.esc,
            }
        except Exception:
            self._porch_retro_kb = None

        # default keymap (RetroArch-style). You can adjust later in Retro Console settings.
        self._porch_retro_keys = {
            "A": "z",
            "B": "x",
            "X": "a",
            "Y": "s",
            "L": "q",
            "R": "w",
            "START": "ENTER",
            "SELECT": "SHIFT",
            "UP": "UP",
            "DOWN": "DOWN",
            "LEFT": "LEFT",
            "RIGHT": "RIGHT",
        }

        def _porch__retro_enqueue(evt: Dict[str, Any]) -> None:
            try:
                line = json.dumps(evt, ensure_ascii=False)
            except Exception:
                line = str(evt)
            try:
                # basic rotation
                p = self._porch_retro_input_queue
                try:
                    if os.path.exists(p) and os.path.getsize(p) > 5 * 1024 * 1024:
                        ts = int(time.time())
                        os.replace(p, p + f".{ts}.bak")
                except Exception:
                    pass
                with open(p, "a", encoding="utf-8") as f:
                    f.write(line + "\n")
            except Exception:
                pass

        def _porch__retro_inject(events: List[Dict[str, Any]]) -> None:
            if not self._porch_retro_inject_on:
                return
            kb = self._porch_retro_kb
            if kb is None:
                return
            for e in events:
                btn = str(e.get("btn", "")).strip().upper()
                down = bool(e.get("down", False))
                key = self._porch_retro_keys.get(btn)
                if not key:
                    continue
                try:
                    if key in self._porch_retro_key_consts:
                        kobj = self._porch_retro_key_consts[key]
                    else:
                        # single-char only
                        if not isinstance(key, str) or len(key) != 1:
                            continue
                        kobj = key
                    if down:
                        kb.press(kobj)
                    else:
                        kb.release(kobj)
                except Exception:
                    continue

        def _porch__retro_handle_packet(obj: Dict[str, Any]) -> None:
            try:
                if not self._porch_retro_input_on:
                    return
                t = str(obj.get("type", "")).strip().lower()
                if t not in ("retro_input", "controller_input"):
                    return

                src = str(obj.get("source", "bifrost"))[:32]
                now = time.time()

                allowed = {"A","B","X","Y","L","R","START","SELECT","UP","DOWN","LEFT","RIGHT"}
                events: List[Dict[str, Any]] = []

                if isinstance(obj.get("events"), list):
                    for it in obj.get("events"):
                        if not isinstance(it, dict):
                            continue
                        btn = str(it.get("btn", "")).strip().upper()
                        if btn not in allowed:
                            continue
                        down = bool(it.get("down", False))
                        events.append({"btn": btn, "down": bool(down)})
                elif isinstance(obj.get("buttons"), dict):
                    buttons = obj.get("buttons") or {}
                    for k, v in buttons.items():
                        btn = str(k).strip().upper()
                        if btn not in allowed:
                            continue
                        try:
                            down = bool(int(v))
                        except Exception:
                            down = bool(v)
                        prev = bool(self._porch_retro_btn_state.get(btn, False))
                        if down != prev:
                            self._porch_retro_btn_state[btn] = down
                            events.append({"btn": btn, "down": down})
                else:
                    # accept shorthand: {"btn":"A","down":1}
                    btn = str(obj.get("btn", "")).strip().upper()
                    if btn in allowed:
                        down = bool(obj.get("down", False))
                        prev = bool(self._porch_retro_btn_state.get(btn, False))
                        if down != prev:
                            self._porch_retro_btn_state[btn] = down
                            events.append({"btn": btn, "down": down})

                if not events:
                    return

                evt = {"ts": now, "source": src, "type": "retro_input", "events": events}
                try:
                    q = getattr(self, "_porch_retro_debug", None)
                    if q is not None:
                        rec = {"ts": float(now), "source": src, "events": list(events)}
                        try:
                            self._porch_retro_debug_last = rec
                        except Exception:
                            pass
                        try:
                            q.append(rec)
                        except Exception:
                            pass
                except Exception:
                    pass
                _porch__retro_enqueue(evt)
                _porch__retro_inject(events)
            except Exception:
                pass

        # register inbound handler if supported
        try:
            if hasattr(self._porch_bifrost, "set_on_message"):
                self._porch_bifrost.set_on_message(_porch__retro_handle_packet)
        except Exception:
            pass
        self._porch_ipfs = _PorchAncestralWell()

        # ensure dirs
        _porch_safe_mkdir(os.path.join(WELL_FOLDER, "vision"))
        _porch_safe_mkdir(os.path.join(WELL_FOLDER, "melody"))
        _porch_safe_mkdir(TELEMETRY_DIR)
        _porch_safe_mkdir(HAPTICS_DIR)

        # auto-enable from env
        try:
            if _porch_truthy(os.getenv("PORCH_HAPTICS_ON", "")):
                self._porch_haptics_on = True
                self._ui_log("🫳 Haptics: ON (event bus ready).", dim=True, mono=True)

            if _porch_truthy(os.getenv("PORCH_VISION_ON", "")):
                self._porch_eye_on = True
                self._ui_log("🔮 Oracle-Eye: ON (use /eye snap).", dim=True, mono=True)

            if _porch_truthy(os.getenv("PORCH_BIFROST_ON", "")):
                ok = self._porch_bifrost.start()
                self._porch_bifrost_on = bool(ok)
                if ok:
                    self._ui_log(f"🌈 Bifrost: ON ({self._porch_bifrost.status()})", dim=True, mono=True)
                else:
                    self._ui_log("🌈 Bifrost: missing dep (pip install websockets).", dim=True, mono=True)

            if _porch_truthy(os.getenv("PORCH_MELODY_ON", "")):
                self._porch_melody_on = True
                self._ui_log("🎼 Melody Nexus: ON (/melody thrum).", dim=True, mono=True)

            if _porch_truthy(os.getenv("PORCH_IPFS_ON", "")):
                msg = self._porch_ipfs.on()
                self._porch_ipfs_on = self._porch_ipfs.enabled
                self._ui_log(f"🧬 Ancestral Well: {msg}", dim=True, mono=True)

        except Exception:
            pass

    def _handle_slash_command(self, text: str) -> bool:  # type: ignore[override]
        m = (text or "").strip()
        if not m.startswith("/"):
            return _orig_slash(self, text)

        parts = m.split()
        cmd = parts[0].lower()

        # ---------- /eye ----------
        if cmd == "/eye":
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                self._porch_eye_on = True
                self._ui_log("🔮 Oracle-Eye enabled. Use /eye snap", dim=True, mono=True)
                return True
            if sub in ("off", "disable"):
                self._porch_eye_on = False
                self._ui_log("🔮 Oracle-Eye disabled.", dim=True, mono=True)
                return True
            if sub in ("status",):
                dep = "ok" if cv2 is not None else "missing(opencv-python)"
                self._ui_log(f"🔮 Oracle-Eye: {'ON' if self._porch_eye_on else 'OFF'} dep={dep}", dim=True, mono=True)
                return True

            if not self._porch_eye_on:
                self._ui_log("🔮 Oracle-Eye is OFF. Use /eye on", error=True)
                return True

            vision_dir = os.path.join(WELL_FOLDER, "vision")
            _porch_safe_mkdir(vision_dir)
            stamp = time.strftime("%Y%m%d_%H%M%S")
            img_path = os.path.join(vision_dir, f"eye_{stamp}.png")

            if sub in ("snap", "capture"):
                cam = int(os.getenv("PORCH_VISION_CAM", "0") or "0")
                ok = _porch_capture_webcam(img_path, cam_index=cam)
                if ok:
                    self._ui_log(f"📷 Saved: {img_path}", dim=True, mono=True)
                    try:
                        if self._porch_haptics_on:
                            self._porch_haptics.emit("verify_ping", meta={"src": "eye_snap"})
                    except Exception:
                        pass
                else:
                    self._ui_log("📷 Capture failed. Install OpenCV: pip install opencv-python", error=True)
                return True

            if sub in ("ocr",):
                # OCR latest image in vision dir
                try:
                    imgs = sorted([p for p in os.listdir(vision_dir) if p.lower().endswith((".png", ".jpg", ".jpeg"))])
                    if not imgs:
                        self._ui_log("No images found in well/vision. Use /eye snap first.", error=True)
                        return True
                    latest = os.path.join(vision_dir, imgs[-1])
                    t = _image_to_text(latest)
                    outp = os.path.join(vision_dir, f"ocr_{stamp}.txt")
                    with open(outp, "w", encoding="utf-8") as f:
                        f.write(t or "")
                    self._ui_log(f"🧾 OCR saved: {outp}", dim=True, mono=True)
                    if (t or "").strip():
                        self._ui_log((t[:1200] + ("…" if len(t) > 1200 else "")), dim=True, mono=False)
                    return True
                except Exception as e:
                    self._ui_log(f"OCR failed: {e}", error=True)
                    return True

            if sub in ("describe", "vlm"):
                try:
                    imgs = sorted([p for p in os.listdir(vision_dir) if p.lower().endswith((".png", ".jpg", ".jpeg"))])
                    if not imgs:
                        self._ui_log("No images found in well/vision. Use /eye snap first.", error=True)
                        return True
                    latest = os.path.join(vision_dir, imgs[-1])
                    prompt = " ".join(parts[2:]).strip() if len(parts) > 2 else "Describe this image in detail."
                    model = (os.getenv("PORCH_VISION_MODEL") or "llava:latest").strip()
                    self._ui_log(f"👁️ VLM ({model}) analyzing latest image…", dim=True, mono=True)
                    out = _porch_ollama_chat_with_image(latest, prompt, model=model)
                    self._ui_log(out or "(no output)", dim=False, mono=False)
                    return True
                except Exception as e:
                    self._ui_log(f"Vision describe failed: {e}", error=True)
                    return True

            self._ui_log("Usage: /eye on|off|snap|ocr|describe [prompt]", dim=True, mono=True)
            return True

        # ---------- /bifrost ----------
        if cmd == "/bifrost":
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                ok = self._porch_bifrost.start()
                self._porch_bifrost_on = bool(ok)
                if ok:
                    self._ui_log(f"🌈 Bifrost enabled: {self._porch_bifrost.status()}", dim=True, mono=True)
                else:
                    self._ui_log("🌈 Bifrost missing dep. Install: pip install websockets", error=True)
                return True
            if sub in ("off", "disable"):
                self._porch_bifrost.stop()
                self._porch_bifrost_on = False
                self._ui_log("🌈 Bifrost disabled.", dim=True, mono=True)
                return True
            self._ui_log(f"🌈 Bifrost: {self._porch_bifrost.status()}", dim=True, mono=True)
            return True

        # ---------- /anchors ----------
        if cmd == "/anchors":
            sub = (parts[1].lower() if len(parts) > 1 else "list")
            if sub == "list":
                rows = _porch_anchor_list(RAG_DB)
                if not rows:
                    self._ui_log("(No anchors yet.)", dim=True, mono=True)
                else:
                    lines = ["Anchors:"]
                    for r in rows[:200]:
                        lines.append(f"- {r['name']}: ({r['x']:.3f}, {r['y']:.3f}, {r['z']:.3f})  {r.get('meta','')}")
                    self._ui_log("\n".join(lines), dim=True, mono=True)
                return True
            if sub == "add" and len(parts) >= 6:
                name = parts[2]
                try:
                    x, y, z = float(parts[3]), float(parts[4]), float(parts[5])
                except Exception:
                    self._ui_log("Usage: /anchors add <name> <x> <y> <z> [meta...]", error=True)
                    return True
                meta = " ".join(parts[6:]).strip()
                msg = _porch_anchor_add(RAG_DB, name, x, y, z, meta=meta)
                self._ui_log(msg, dim=True, mono=True)
                try:
                    if self._porch_bifrost_on:
                        self._porch_bifrost.broadcast({"type": "anchor_add", "name": name, "x": x, "y": y, "z": z, "meta": meta, "iso": _porch_iso()})
                except Exception:
                    pass
                return True
            if sub == "del" and len(parts) >= 3:
                name = parts[2]
                msg = _porch_anchor_del(RAG_DB, name)
                self._ui_log(msg, dim=True, mono=True)
                try:
                    if self._porch_bifrost_on:
                        self._porch_bifrost.broadcast({"type": "anchor_del", "name": name, "iso": _porch_iso()})
                except Exception:
                    pass
                return True
            self._ui_log("Usage: /anchors list | /anchors add <name> <x> <y> <z> [meta...] | /anchors del <name>", dim=True, mono=True)
            return True


        # ---------- /retroinput ----------
        if cmd in ("/retroinput", "/retro-input", "/retro_input"):
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                self._porch_retro_input_on = True
                self._ui_log("🎮 Retro input bridge ON (Bifrost -> ./well/retro/input_queue.jsonl).", dim=True, mono=True)
                return True
            if sub in ("off", "disable"):
                self._porch_retro_input_on = False
                self._ui_log("🎮 Retro input bridge OFF.", dim=True, mono=True)
                return True
            self._ui_log(
                f"🎮 Retro input: {'ON' if getattr(self, '_porch_retro_input_on', False) else 'OFF'} | "
                f"Inject: {'ON' if getattr(self, '_porch_retro_inject_on', False) else 'OFF'}",
                dim=True,
                mono=True,
            )
            return True

        # ---------- /retroinject ----------
        if cmd in ("/retroinject", "/retro-inject", "/retro_inject"):
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                self._porch_retro_inject_on = True
                if getattr(self, "_porch_retro_kb", None) is None:
                    self._ui_log("🎮 Retro key injection ON, but backend missing. Install: pip install pynput", dim=True, mono=True)
                else:
                    self._ui_log("🎮 Retro key injection ON (allowlisted keys only).", dim=True, mono=True)
                return True
            if sub in ("off", "disable"):
                self._porch_retro_inject_on = False
                self._ui_log("🎮 Retro key injection OFF.", dim=True, mono=True)
                return True
            self._ui_log(
                f"🎮 Inject: {'ON' if getattr(self, '_porch_retro_inject_on', False) else 'OFF'}",
                dim=True,
                mono=True,
            )
            return True

        # ---------- /retrohelp ----------
        if cmd in ("/retrohelp", "/retro-help", "/retro_help"):
            self._ui_log(
                "🎮 Retro Input Packet (Bifrost JSON)\n"
                "Supported:\n"
                "  {\"type\":\"retro_input\",\"events\":[{\"btn\":\"A\",\"down\":1},{\"btn\":\"LEFT\",\"down\":0}],\"source\":\"vr\"}\n"
                "or\n"
                "  {\"type\":\"retro_input\",\"buttons\":{\"A\":1,\"B\":0,\"UP\":1}}\n"
                "Buttons allowlist: A,B,X,Y,L,R,START,SELECT,UP,DOWN,LEFT,RIGHT\n"
                "Use /retroinput on and optionally /retroinject on.",
                dim=True,
                mono=True,
            )
            return True

# ---------- /melody ----------
        if cmd == "/melody":
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                self._porch_melody_on = True
                self._ui_log("🎼 Melody Nexus enabled. Try: /melody thrum 7.83 12", dim=True, mono=True)
                return True
            if sub in ("off", "disable"):
                self._porch_melody_on = False
                self._ui_log("🎼 Melody Nexus disabled.", dim=True, mono=True)
                return True
            if sub == "thrum":
                if not self._porch_melody_on:
                    self._ui_log("🎼 Melody is OFF. Use /melody on", error=True)
                    return True
                hz = float(parts[2]) if len(parts) > 2 else 7.83
                secs = float(parts[3]) if len(parts) > 3 else 12.0
                outp = os.path.join(WELL_FOLDER, "melody", f"thrum_{time.strftime('%Y%m%d_%H%M%S')}.mid")
                msg = _porch_write_thrum_midi(outp, hz=hz, seconds=secs)
                self._ui_log(msg, dim=True, mono=True)
                try:
                    if self._porch_haptics_on:
                        self._porch_haptics.emit("gold_thrum", freq=hz, meta={"src": "melody_thrum", "file": outp})
                except Exception:
                    pass
                return True
            self._ui_log(f"🎼 Melody: {'ON' if self._porch_melody_on else 'OFF'} (midiutil={'ok' if MIDIFile is not None else 'missing'})", dim=True, mono=True)
            return True

        # ---------- /ancestral ----------
        if cmd == "/ancestral":
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                msg = self._porch_ipfs.on()
                self._porch_ipfs_on = self._porch_ipfs.enabled
                self._ui_log(f"🧬 Ancestral Well: {msg}", dim=True, mono=True)
                return True
            if sub in ("off", "disable"):
                msg = self._porch_ipfs.off()
                self._porch_ipfs_on = False
                self._ui_log(f"🧬 Ancestral Well: {msg}", dim=True, mono=True)
                return True
            if sub == "push" and len(parts) >= 3:
                p = " ".join(parts[2:]).strip()
                msg = self._porch_ipfs.push_file(p)
                self._ui_log(msg, dim=True, mono=True)
                return True
            self._ui_log(f"🧬 Ancestral Well: {self._porch_ipfs.status()} (dep={'ok' if ipfshttpclient is not None else 'missing'})", dim=True, mono=True)
            return True

        # ---------- /haptic ----------
        if cmd == "/haptic":
            sub = (parts[1].lower() if len(parts) > 1 else "status")
            if sub in ("on", "enable"):
                self._porch_haptics_on = True
                self._ui_log("🫳 Haptics enabled.", dim=True, mono=True)
                return True
            if sub in ("off", "disable"):
                self._porch_haptics_on = False
                self._ui_log("🫳 Haptics disabled.", dim=True, mono=True)
                return True
            if sub == "emit":
                if not self._porch_haptics_on:
                    self._ui_log("🫳 Haptics is OFF. Use /haptic on", error=True)
                    return True
                if len(parts) < 3:
                    self._ui_log("Usage: /haptic emit <event> [freq] [amp] [ms]", error=True)
                    return True
                ev = parts[2]
                freq = float(parts[3]) if len(parts) > 3 else None
                amp = float(parts[4]) if len(parts) > 4 else None
                ms = int(float(parts[5])) if len(parts) > 5 else None
                self._porch_haptics.emit(ev, freq=freq, amp=amp, ms=ms, meta={"src": "slash"})
                self._ui_log(f"🫳 emitted {ev}", dim=True, mono=True)
                return True
            # convenience shortcuts:
            if sub in ("gold_thrum", "static_itch", "verify_ping", "alert", "calm"):
                if not self._porch_haptics_on:
                    self._ui_log("🫳 Haptics is OFF. Use /haptic on", error=True)
                    return True
                self._porch_haptics.emit(sub, meta={"src": "slash"})
                self._ui_log(f"🫳 {sub}", dim=True, mono=True)
                return True
            self._ui_log(f"🫳 Haptics: {'ON' if self._porch_haptics_on else 'OFF'} (file={HAPTICS_EVENTS_FILE})", dim=True, mono=True)
            return True


        # ---------- /unreal ----------
        if cmd in ("/unreal", "/ue", "/unrealbridge"):
            sub = (parts[1].lower() if len(parts) > 1 else "open")
            if sub in ("open", "ui", "panel"):
                try:
                    self._open_unreal_bridge()
                except Exception:
                    self._ui_log("🧩 Unreal Bridge UI failed to open.", error=True)
                return True
            if sub in ("ping", "test"):
                try:
                    n = 0
                    if hasattr(self, "_porch_bifrost") and hasattr(self._porch_bifrost, "broadcast"):
                        n = int(self._porch_bifrost.broadcast({"type": "unreal_ping", "ts": time.time(), "msg": "hello_from_porch"}))
                    self._ui_log(f"🧩 Unreal ping broadcast to {n} client(s).", dim=True, mono=True)
                except Exception:
                    self._ui_log("🧩 Unreal ping failed.", error=True)
                return True
            if sub == "mcp":
                cmdline = " ".join(parts[2:]).strip()
                if not cmdline:
                    self._ui_log("🧩 Usage: /unreal mcp <command>", dim=True, mono=True)
                    return True
                try:
                    n = int(self._porch_bifrost.broadcast({"type": "mcp_cmd", "ts": time.time(), "cmd": cmdline}))
                    self._ui_log(f"🧩 MCP command sent to {n} client(s): {cmdline}", dim=True, mono=True)
                except Exception:
                    self._ui_log("🧩 MCP send failed.", error=True)
                return True
            self._ui_log("🧩 /unreal: open | ping | mcp <cmd>", dim=True, mono=True)
            return True

        # ---------- /airsim ----------
        if cmd == "/airsim":
            sub = (parts[1].lower() if len(parts) > 1 else "open")
            if sub in ("open", "ui", "panel"):
                try:
                    self._open_airsim_panel()
                except Exception:
                    self._ui_log("🛩️ AirSim panel failed to open.", error=True)
                return True
            if sub in ("test", "ping", "connect"):
                try:
                    msg = self._airsim_test()
                except Exception as e:
                    msg = f"AirSim test failed: {e}"
                self._ui_log(f"🛩️ {msg}", dim=True, mono=True)
                return True
            self._ui_log("🛩️ /airsim: open | test", dim=True, mono=True)
            return True
        return _orig_slash(self, text)

    _PorchApp.__init__ = __init__  # type: ignore[assignment]
    _PorchApp._handle_slash_command = _handle_slash_command  # type: ignore[assignment]


    def _open_unreal_bridge(self) -> None:
        try:
            import webbrowser
        except Exception:
            webbrowser = None
        win = ctk.CTkToplevel(self)
        win.title("Unreal / MCP / AirSim Bridge")
        win.geometry("820x520")
        try:
            win.grab_set()
        except Exception:
            pass
        ctk.CTkLabel(win, text="Unreal Bridge (local-first)", text_color=PALETTE["text"], font=("Segoe UI", 20, "bold")).pack(anchor="w", padx=16, pady=(16, 6))
        ctk.CTkLabel(win, text="Use Bifrost packets + MCP to drive Unreal in real time. AirSim is optional.", text_color=PALETTE["muted"]).pack(anchor="w", padx=16)
        links = ctk.CTkFrame(win, fg_color="transparent")
        links.pack(fill="x", padx=16, pady=(14, 6))
        def _open(url: str):
            try:
                if webbrowser:
                    webbrowser.open(url)
            except Exception:
                pass
        ctk.CTkButton(links, text="UnrealGenAISupport", command=lambda: _open("https://github.com/prajwalshettydev/UnrealGenAISupport"), height=36, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(links, text="unreal-mcp", command=lambda: _open("https://github.com/chongdashu/unreal-mcp"), height=36, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(links, text="AirSim", command=lambda: _open("https://github.com/microsoft/AirSim"), height=36, fg_color="#1B274A").pack(side="left")

        pane = ctk.CTkFrame(win)
        pane.pack(fill="both", expand=True, padx=16, pady=16)
        ctk.CTkLabel(pane, text="MCP Command", text_color=PALETTE["muted"]).pack(anchor="w", padx=12, pady=(12, 4))
        entry = ctk.CTkEntry(pane, placeholder_text="spawn temple | delete actor=... | set weather=rain")
        entry.pack(fill="x", padx=12)
        out = ctk.CTkTextbox(pane, height=220)
        out.pack(fill="both", expand=True, padx=12, pady=(12, 12))
        try:
            out.configure(state="disabled")
        except Exception:
            pass
        btns = ctk.CTkFrame(pane, fg_color="transparent")
        btns.pack(fill="x", padx=12, pady=(0, 12))
        def _log(s: str):
            try:
                out.configure(state="normal")
            except Exception:
                pass
            out.insert("end", s + "\n")
            out.see("end")
            try:
                out.configure(state="disabled")
            except Exception:
                pass
        def _send_ping():
            try:
                n = int(self._porch_bifrost.broadcast({"type": "unreal_ping", "ts": time.time(), "msg": "hello_from_porch"}))
                _log(f"Ping broadcast to {n} client(s)")
            except Exception as e:
                _log(f"Ping failed: {e}")
        def _send_mcp():
            cmdline = (entry.get() or "").strip()
            if not cmdline:
                _log("Enter a command.")
                return
            try:
                n = int(self._porch_bifrost.broadcast({"type": "mcp_cmd", "ts": time.time(), "cmd": cmdline}))
                _log(f"Sent to {n} client(s): {cmdline}")
            except Exception as e:
                _log(f"Send failed: {e}")
        ctk.CTkButton(btns, text="Ping", command=_send_ping, height=38, fg_color="#1B274A").pack(side="left", padx=(0, 8))
        ctk.CTkButton(btns, text="Send MCP", command=_send_mcp, height=38, fg_color=PALETTE["accent"]).pack(side="left")
        ctk.CTkButton(btns, text="AirSim Test", command=lambda: _log(self._airsim_test()), height=38, fg_color="#1B274A").pack(side="right")

    def _airsim_test(self) -> str:
        try:
            import airsim  # type: ignore
        except Exception:
            return "airsim python package not installed (pip install airsim)"
        try:
            client = airsim.MultirotorClient()
            client.confirmConnection()
            try:
                state = client.getMultirotorState()
                return f"connected (multirotor) | armed={getattr(getattr(state,'kinematics_estimated',None),'position',None) is not None}"
            except Exception:
                return "connected"
        except Exception as e:
            return f"not connected: {e}"

    def _open_airsim_panel(self) -> None:
        win = ctk.CTkToplevel(self)
        win.title("AirSim")
        win.geometry("640x360")
        try:
            win.grab_set()
        except Exception:
            pass
        ctk.CTkLabel(win, text="AirSim (optional)", text_color=PALETTE["text"], font=("Segoe UI", 18, "bold")).pack(anchor="w", padx=16, pady=(16, 6))
        ctk.CTkLabel(win, text="This panel only tests the AirSim Python client connection.", text_color=PALETTE["muted"]).pack(anchor="w", padx=16)
        out = ctk.CTkTextbox(win, height=160)
        out.pack(fill="both", expand=True, padx=16, pady=16)
        try:
            out.configure(state="disabled")
        except Exception:
            pass
        def _run():
            msg = self._airsim_test()
            try:
                out.configure(state="normal")
            except Exception:
                pass
            out.delete("1.0", "end")
            out.insert("end", msg)
            try:
                out.configure(state="disabled")
            except Exception:
                pass
        ctk.CTkButton(win, text="Test Connection", command=_run, height=40, fg_color=PALETTE["accent"]).pack(padx=16, pady=(0, 16), anchor="e")

except Exception:
    pass

