def _env_toggle_edit(self):
    try:
        v = getattr(self, "_env_edit_mode", None)
        if v is None:
            self._env_edit_mode = tk.BooleanVar(value=False)
            v = self._env_edit_mode
        v.set(not bool(v.get()))
        self._toast("Layout edit: ON" if v.get() else "Layout edit: OFF", kind="info")
    except Exception:
        pass

def _env_on_press(self, event):
    try:
        if not getattr(self, "_env_edit_mode", tk.BooleanVar(value=False)).get():
            return
        c = getattr(self, "_env_canvas", None)
        if c is None:
            return
        item = c.find_closest(event.x, event.y)[0]
        tags = c.gettags(item) or ()
        room = None
        for t in tags:
            if isinstance(t, str) and t.startswith("room:"):
                room = t.split(":", 1)[1]
                break
        if not room:
            return
        self._env_drag = {"room": room}
    except Exception:
        pass

def _env_on_drag(self, event):
    try:
        if not getattr(self, "_env_edit_mode", tk.BooleanVar(value=False)).get():
            return
        drag = getattr(self, "_env_drag", None)
        if not isinstance(drag, dict):
            return
        room = drag.get("room")
        if not room:
            return
        st = getattr(self, "_iot_state", None)
        if not isinstance(st, dict):
            return
        env = st.get("env") or {}
        rooms = env.get("rooms") or {}
        meta = rooms.get(room) or {}
        c = getattr(self, "_env_canvas", None)
        if c is None:
            return
        w = int(c.winfo_width() or 1)
        h = int(c.winfo_height() or 1)
        gw = int(env.get("grid_w", 2) or 2)
        gh = int(env.get("grid_h", 2) or 2)
        pad = 10
        cell_w = max(10, (w - pad*2) / max(1, gw))
        cell_h = max(10, (h - pad*2) / max(1, gh))
        nx = int((event.x - pad) / cell_w)
        ny = int((event.y - pad) / cell_h)
        nx = max(0, min(gw-1, nx))
        ny = max(0, min(gh-1, ny))
        if int(meta.get("x", 0)) == nx and int(meta.get("y", 0)) == ny:
            return
        meta["x"], meta["y"] = nx, ny
        rooms[room] = meta
        env["rooms"] = rooms
        st["env"] = env
        self._iot_state = st
        try:
            self._iot_save()
        except Exception:
            pass
        try:
            self._env_render_heatmap()
        except Exception:
            pass
    except Exception:
        pass

def _env_on_release(self, event):
    try:
        self._env_drag = None
    except Exception:
        pass

# ---------------------------
# Rolling charts (PM2.5 / CO2 / VOC)
# ---------------------------
def _build_iot_charts_ui(self, tab) -> None:
    try:
        tab.grid_rowconfigure(1, weight=1)
        tab.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    top = ctk.CTkFrame(tab, fg_color="transparent")
    top.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
    top.grid_columnconfigure(6, weight=1)

    ctk.CTkLabel(top, text="Sensor").grid(row=0, column=0, sticky="w")
    self._charts_sensor = ctk.StringVar(value="sensor-1")
    self._charts_metric_pm25 = tk.BooleanVar(value=True)
    self._charts_metric_co2 = tk.BooleanVar(value=True)
    self._charts_metric_voc = tk.BooleanVar(value=True)
    self._charts_auto = tk.BooleanVar(value=True)

    self._charts_sensor_menu = ctk.CTkOptionMenu(top, values=["sensor-1"], variable=self._charts_sensor, command=lambda _=None: self._charts_render())
    self._charts_sensor_menu.grid(row=0, column=1, sticky="w", padx=(8, 12))

    ctk.CTkCheckBox(top, text="PM2.5", variable=self._charts_metric_pm25, command=self._charts_render).grid(row=0, column=2, padx=(0, 8))
    ctk.CTkCheckBox(top, text="CO₂", variable=self._charts_metric_co2, command=self._charts_render).grid(row=0, column=3, padx=(0, 8))
    ctk.CTkCheckBox(top, text="VOC", variable=self._charts_metric_voc, command=self._charts_render).grid(row=0, column=4, padx=(0, 8))
    ctk.CTkCheckBox(top, text="Auto", variable=self._charts_auto).grid(row=0, column=5, padx=(0, 8))
    ctk.CTkButton(top, text="Refresh", width=90, command=self._charts_render).grid(row=0, column=6, sticky="e")

    self._charts_holder = ctk.CTkFrame(tab, fg_color="transparent")
    self._charts_holder.grid(row=1, column=0, sticky="nsew", padx=8, pady=(4, 8))
    self._charts_holder.grid_rowconfigure(0, weight=1)
    self._charts_holder.grid_columnconfigure(0, weight=1)

    self._charts_text = ctk.CTkTextbox(self._charts_holder, wrap="none")
    self._charts_text.grid(row=0, column=0, sticky="nsew")

    self._charts_canvas = None
    self._charts_plot_timer()

def _charts_plot_timer(self):
    try:
        if getattr(self, "_charts_auto", tk.BooleanVar(value=False)).get():
            self._charts_render()
    except Exception:
        pass
    try:
        self.after(2000, self._charts_plot_timer)
    except Exception:
        pass

def _charts_render(self):
    st = getattr(self, "_iot_state", None)
    if not isinstance(st, dict):
        return
    env = st.get("env") or {}
    hist = env.get("history") or {}
    sid = (self._charts_sensor.get() if getattr(self, "_charts_sensor", None) is not None else "sensor-1")

    # update menu options
    try:
        keys = sorted(list(hist.keys())) or ["sensor-1"]
        if getattr(self, "_charts_sensor_menu", None) is not None:
            self._charts_sensor_menu.configure(values=keys)
    except Exception:
        pass

    series = hist.get(sid) or []
    xs=[]; pm25=[]; co2=[]; voc=[]
    for r in series[-300:]:
        if not isinstance(r, dict):
            continue
        try:
            ts=float(r.get("ts"))
        except Exception:
            continue
        vals=r.get("values") or {}
        xs.append(ts)
        pm25.append(vals.get("pm25"))
        co2.append(vals.get("co2"))
        voc.append(vals.get("voc"))

    show_pm25 = getattr(self, "_charts_metric_pm25", tk.BooleanVar(value=True)).get()
    show_co2 = getattr(self, "_charts_metric_co2", tk.BooleanVar(value=True)).get()
    show_voc = getattr(self, "_charts_metric_voc", tk.BooleanVar(value=True)).get()

    # matplotlib optional
    try:
        import matplotlib
        matplotlib.use("Agg")
        from matplotlib.figure import Figure
        from matplotlib.backends.backend_tkagg import FigureCanvasTkAgg
        fig = Figure(figsize=(6,3), dpi=100)
        ax = fig.add_subplot(111)

        def clean(series):
            out=[]
            for v in series:
                try:
                    out.append(float(v))
                except Exception:
                    out.append(float("nan"))
            return out

        if show_pm25:
            ax.plot(xs, clean(pm25), label="PM2.5")
        if show_co2:
            ax.plot(xs, clean(co2), label="CO2")
        if show_voc:
            ax.plot(xs, clean(voc), label="VOC")
        ax.set_title(f"{sid} (last {len(xs)} samples)")
        ax.grid(True, alpha=0.3)
        ax.legend(loc="upper right", fontsize=8)

        if getattr(self, "_charts_canvas", None) is not None:
            try:
                self._charts_canvas.get_tk_widget().destroy()
            except Exception:
                pass
            self._charts_canvas = None

        try:
            self._charts_text.grid_forget()
        except Exception:
            pass
        canvas = FigureCanvasTkAgg(fig, master=self._charts_holder)
        canvas.draw()
        canvas.get_tk_widget().grid(row=0, column=0, sticky="nsew")
        self._charts_canvas = canvas
        return
    except Exception:
        pass

    # fallback text
    try:
        if getattr(self, "_charts_canvas", None) is not None:
            try:
                self._charts_canvas.get_tk_widget().destroy()
            except Exception:
                pass
            self._charts_canvas = None
        self._charts_text.grid(row=0, column=0, sticky="nsew")
        self._charts_text.configure(state="normal")
        self._charts_text.delete("1.0", "end")
        self._charts_text.insert("end", f"{sid} (install matplotlib for charts)\n")
        self._charts_text.insert("end", "ts\tpm25\tco2\tvoc\n")
        for i, ts in enumerate(xs[-50:]):
            self._charts_text.insert("end", f"{ts:.0f}\t{pm25[-50+i]}\t{co2[-50+i]}\t{voc[-50+i]}\n")
        self._charts_text.configure(state="disabled")
    except Exception:
        pass

