def _iot_registry(self) -> Dict[str, Any]:
    st = getattr(self, "_iot_state", None)
    if not isinstance(st, dict):
        st = self._iot_load()
        self._iot_state = st
    reg = st.get("registry")
    if not isinstance(reg, dict):
        reg = {"devices": {}}
        st["registry"] = reg
    reg.setdefault("devices", {})
    return reg

def _iot_open_registry(self):
    try:
        win = getattr(self, "_iot_registry_win", None)
        if win is not None and win.winfo_exists():
            win.lift(); win.focus_force()
            return
    except Exception:
        pass

    win = ctk.CTkToplevel(self)
    win.title("IoT Device Registry")
    win.geometry("840x520")
    self._iot_registry_win = win

    win.grid_rowconfigure(1, weight=1)
    win.grid_columnconfigure(0, weight=1)

    reg = self._iot_registry()
    devices = reg.get("devices") or {}

    top = ctk.CTkFrame(win, fg_color="transparent")
    top.grid(row=0, column=0, sticky="ew", padx=10, pady=10)
