# === GITHUB IDEA INTEGRATIONS (JME/Homebrewery/Catalyst/DiceCloud/LDC) ===
# This section adds *optional* feature bridges inspired by:
# - jMonkeyEngine (scene graph/export)
# - Homebrewery (markdown-to-5e styling workflow)
# - Catalyst (reproducible “runner + callbacks” experiment pattern)
# - DiceCloud (character-sheet + derived stats philosophy)
# - LDC (optional fast native toolchain for D snippets)
#
# It monkey-patches the slash-command router and adds a few self-contained windows
# + exporters without rewriting the core app.

try:
    import subprocess  # noqa: F401
    import webbrowser  # noqa: F401
    from tkinter import filedialog, messagebox  # noqa: F401
except Exception:  # pragma: no cover
    subprocess = None  # type: ignore
    webbrowser = None  # type: ignore
    filedialog = None  # type: ignore
    messagebox = None  # type: ignore

# Allow extra “created” file types for exporters (kept conservative; no binaries).
try:
    ALLOWED_CREATE_EXTS.update({
        ".java", ".gradle", ".kts", ".properties", ".xml",
        ".bat", ".sh", ".d"
    })
except Exception:
    pass

def html_escape(s: str) -> str:
    s = (s or "")
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace('"', "&quot;")
             .replace("'", "&#x27;"))

def _porch__ts() -> str:
    try:
        return datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    except Exception:
        return "ts"

def _porch__created(*parts: str) -> str:
    return os.path.join(CREATED_DIR, *parts)

def _porch__ensure_dir(path: str) -> None:
    try:
        os.makedirs(path, exist_ok=True)
    except Exception:
        pass

def _porch__write(path: str, text: str) -> None:
    try:
        _write_text(path, text)
        return
    except Exception:
        pass
    try:
        _porch__ensure_dir(os.path.dirname(path))
        with open(path, "w", encoding="utf-8") as f:
            f.write(text)
    except Exception:
        pass

def _porch__safe_name(name: str, fallback: str = "project") -> str:
    name = (name or "").strip()
    name = re.sub(r"[^a-zA-Z0-9._-]+", "_", name)
    name = name.strip("._-")
    if not name:
        name = fallback
    if len(name) > 64:
        name = name[:64]
    return name

def _porch_roll(expr: str):
    s = (expr or "").strip().lower()
    if not s:
        raise ValueError("Empty roll.")
    adv = False
    dis = False
    if " adv" in f" {s}" or s.endswith("adv"):
        adv = True
        s = s.replace("adv", "").strip()
    if " dis" in f" {s}" or s.endswith("dis"):
        dis = True
        s = s.replace("dis", "").strip()

    tokens = re.findall(r"[+-]?\s*[^+-]+", s)
    if not tokens:
        raise ValueError("Bad roll expression.")

    def roll_ndm(n: int, m: int):
        if m <= 0 or n <= 0:
            raise ValueError("Dice must be positive.")
        if n > 200 or m > 100000:
            raise ValueError("Dice too large.")
        return [random.randint(1, m) for _ in range(n)]

    total = 0
    parts = []
    for tok in tokens:
        t = tok.strip().replace(" ", "")
        if not t:
            continue
        sign = 1
        if t[0] == "+":
            t = t[1:]
        elif t[0] == "-":
            sign = -1
            t = t[1:]
        if not t:
            continue

        m = re.fullmatch(r"(\d*)d(\d+)", t)
        if m:
            n = int(m.group(1) or "1")
            sides = int(m.group(2))
            rolls = roll_ndm(n, sides)
            if sides == 20 and n == 1 and (adv or dis):
                r2 = roll_ndm(1, 20)[0]
                chosen = max(rolls[0], r2) if adv and not dis else min(rolls[0], r2)
                parts.append({"type": "d20_advdis", "rolls": [rolls[0], r2], "kept": chosen, "sign": sign})
                total += sign * chosen
            else:
                parts.append({"type": "dice", "n": n, "sides": sides, "rolls": rolls, "sum": sum(rolls), "sign": sign})
                total += sign * sum(rolls)
            continue

        if re.fullmatch(r"\d+", t):
            val = int(t)
            parts.append({"type": "mod", "value": val, "sign": sign})
            total += sign * val
            continue

        raise ValueError(f"Unrecognized token: {tok.strip()}")

    return {"expr": expr, "total": total, "parts": parts, "adv": adv, "dis": dis}


def _porch_apply_github_idea_integrations():
    cls = globals().get("InfinitePorch", None)
    if cls is None:
        return

    # --- Homebrewery window ---
    def _open_homebrewery(self):
        try:
            dlg = ctk.CTkToplevel(self)
            dlg.title("Homebrewery (Markdown → 5e-style workflow)")
            dlg.geometry("980x720")
            dlg.grid_columnconfigure(0, weight=1)
            dlg.grid_rowconfigure(1, weight=1)

            header = ctk.CTkLabel(dlg, text="Homebrewery Studio", font=(FONT_FAMILY, 18, "bold"), text_color=PALETTE["text"])
            header.grid(row=0, column=0, sticky="w", padx=14, pady=(14, 6))

            t = ctk.CTkTextbox(dlg, corner_radius=10)
            t.grid(row=1, column=0, sticky="nsew", padx=14, pady=(0, 10))
            sample = (
                "# Title Here\n\n"
                "## Overview\n"
                "- This markdown is meant to be pasted into the Homebrewery editor.\n"
                "- Use `\\pagebreak` between pages.\n\n"
                "### Stat Block\n"
                "> **AC** 14 (leather)  \n"
                "> **HP** 27 (5d8+5)  \n"
                "> **Speed** 30 ft.\n\n"
                "\\pagebreak\n\n"
                "## Notes\n"
                "Add lore, items, quests, etc.\n"
            )
            try:
                t.insert("1.0", sample)
            except Exception:
                pass

            btn_row = ctk.CTkFrame(dlg, fg_color="transparent")
            btn_row.grid(row=2, column=0, sticky="ew", padx=14, pady=(0, 14))
            btn_row.grid_columnconfigure(3, weight=1)

            name_entry = ctk.CTkEntry(btn_row, placeholder_text="filename (e.g., shadow_adventure_brew.md)")
            name_entry.grid(row=0, column=0, padx=(0, 8), pady=0, sticky="w")
            name_entry.insert(0, "homebrew.md")

            status = ctk.CTkLabel(btn_row, text="", text_color=PALETTE["muted"])
            status.grid(row=0, column=4, padx=(10, 0), sticky="e")

            def save_md():
                fn = sanitize_filename(name_entry.get())
                if not fn:
                    status.configure(text="Invalid filename / extension.")
                    return
                out_dir = _porch__created("brewery")
                _porch__ensure_dir(out_dir)
                out_path = os.path.join(out_dir, fn)
                content = t.get("1.0", "end").strip() + "\n"
                _porch__write(out_path, content)
                try:
                    self._ui_log(f"🍺 Homebrewery markdown saved: {out_path}", dim=True)
                except Exception:
                    pass
                status.configure(text="Saved .md")

            def save_html_preview():
                fn = _porch__safe_name(os.path.splitext(name_entry.get())[0] or "homebrew", "homebrew") + ".html"
                out_dir = _porch__created("brewery")
                _porch__ensure_dir(out_dir)
                out_path = os.path.join(out_dir, fn)
                content = t.get("1.0", "end").strip()
                html = (
                    "<!doctype html>\n<html>\n<head>\n<meta charset=\"utf-8\">\n"
                    "<title>Homebrew Preview</title>\n"
                    "<style>\n"
                    "body { margin: 24px; font-family: Georgia, serif; }\n"
                    ".page { max-width: 900px; margin: 0 auto; padding: 28px; border: 1px solid #ccc; border-radius: 12px; }\n"
                    "pre { white-space: pre-wrap; }\n"
                    ".note { color: #555; font-size: 0.9em; margin-bottom: 12px; }\n"
                    "</style>\n</head>\n<body>\n"
                    "<div class=\"page\">\n"
                    "<div class=\"note\">This is a lightweight local preview. For true 5e styling, paste the markdown into Homebrewery.</div>\n"
                    "<pre>" + html_escape(content) + "</pre>\n"
                    "</div>\n</body>\n</html>\n"
                )
                _porch__write(out_path, html)
                try:
                    self._ui_log(f"🍺 Homebrew preview saved: {out_path}", dim=True)
                except Exception:
                    pass
                status.configure(text="Saved .html")

            def open_site():
                if webbrowser is None:
                    status.configure(text="webbrowser unavailable.")
                    return
                try:
                    webbrowser.open("https://homebrewery.naturalcrit.com/")
                    status.configure(text="Opened Homebrewery site")
                except Exception:
                    status.configure(text="Could not open browser.")

            ctk.CTkButton(btn_row, text="Save .md", command=save_md).grid(row=0, column=1, padx=(0, 8))
            ctk.CTkButton(btn_row, text="Save preview .html", command=save_html_preview).grid(row=0, column=2, padx=(0, 8))
            ctk.CTkButton(btn_row, text="Open Homebrewery", command=open_site).grid(row=0, column=3, padx=(0, 8), sticky="w")
        except Exception:
            try:
                self._ui_log("Homebrewery window failed to open.", dim=True)
            except Exception:
                pass

    # --- RPG Vault (DiceCloud-inspired) ---
    def _rpg_vault_path(self) -> str:
        return os.path.join(WELL_FOLDER, "rpg_vault", "characters.json")

    def _rpg_load_all(self):
        p = _rpg_vault_path(self)
        try:
            if not os.path.exists(p):
                return []
            with open(p, "r", encoding="utf-8") as f:
                data = json.load(f)
            if isinstance(data, list):
                return data
        except Exception:
            pass
        return []

    def _rpg_save_all(self, chars):
        p = _rpg_vault_path(self)
        try:
            os.makedirs(os.path.dirname(p), exist_ok=True)
            with open(p, "w", encoding="utf-8") as f:
                json.dump(chars, f, ensure_ascii=False, indent=2)
        except Exception:
            pass

    def _rpg_recompute(character: dict) -> dict:
        c = dict(character or {})
        stats = c.get("stats") or {}
        def mod(x):
            try:
                return int((int(x) - 10) // 2)
            except Exception:
                return 0
        mods = {k+"_mod": mod(v) for k, v in stats.items() if k in ("str","dex","con","int","wis","cha")}
        c["derived"] = mods
        try:
            c["derived"]["passive_perception"] = 10 + mods.get("wis_mod", 0) + int((c.get("skills") or {}).get("perception", 0) or 0)
        except Exception:
            c["derived"]["passive_perception"] = 10 + mods.get("wis_mod", 0)
        return c

    def _open_rpg_vault(self):
        try:
            dlg = ctk.CTkToplevel(self)
            dlg.title("RPG Vault (DiceCloud-inspired Character Sheets)")
            dlg.geometry("1050x720")
            dlg.grid_columnconfigure(1, weight=1)
            dlg.grid_rowconfigure(0, weight=1)

            left = ctk.CTkFrame(dlg, corner_radius=12)
            left.grid(row=0, column=0, sticky="nsw", padx=(14, 8), pady=14)
            right = ctk.CTkFrame(dlg, corner_radius=12)
            right.grid(row=0, column=1, sticky="nsew", padx=(8, 14), pady=14)
            right.grid_columnconfigure(0, weight=1)
            right.grid_rowconfigure(1, weight=1)

            ctk.CTkLabel(left, text="Characters", font=(FONT_FAMILY, 16, "bold")).pack(padx=12, pady=(12, 6), anchor="w")

            listbox = ctk.CTkScrollableFrame(left, width=260, height=520, corner_radius=10)
            listbox.pack(padx=12, pady=(0, 10), fill="both", expand=True)

            chars = _rpg_load_all(self)
            selected = {"idx": None}

            header = ctk.CTkLabel(right, text="Edit", font=(FONT_FAMILY, 16, "bold"))
            header.grid(row=0, column=0, sticky="w", padx=12, pady=(12, 6))

            editor = ctk.CTkTextbox(right, corner_radius=10)
            editor.grid(row=1, column=0, sticky="nsew", padx=12, pady=(0, 10))

            footer = ctk.CTkFrame(right, fg_color="transparent")
            footer.grid(row=2, column=0, sticky="ew", padx=12, pady=(0, 12))
            footer.grid_columnconfigure(3, weight=1)

            roll_entry = ctk.CTkEntry(footer, placeholder_text="roll (e.g., 2d6+3, d20 adv)")
            roll_entry.grid(row=0, column=0, padx=(0, 8), sticky="w")
            roll_out = ctk.CTkLabel(footer, text="", text_color=PALETTE["muted"])
            roll_out.grid(row=0, column=4, padx=(10, 0), sticky="e")

            def refresh_list():
                for w in listbox.winfo_children():
                    try: w.destroy()
                    except Exception: pass
                for i, ch in enumerate(chars):
                    nm = (ch.get("name") or f"Character {i+1}")
                    btn = ctk.CTkButton(listbox, text=nm, width=220, command=lambda ii=i: select(ii))
                    btn.pack(padx=8, pady=6, anchor="w")

            def select(i: int):
                selected["idx"] = i
                ch = chars[i]
                try: header.configure(text=f"Edit: {ch.get('name','(unnamed)')}")
                except Exception: pass
                try: editor.delete("1.0", "end")
                except Exception: pass
                try: editor.insert("1.0", json.dumps(ch, ensure_ascii=False, indent=2))
                except Exception: pass

            def new_char():
                base = {
                    "name": f"New Hero {_porch__ts()}",
                    "stats": {"str": 10, "dex": 10, "con": 10, "int": 10, "wis": 10, "cha": 10},
                    "skills": {},
                    "inventory": [],
                    "notes": "",
                }
                chars.append(_rpg_recompute(base))
                _rpg_save_all(self, chars)
                refresh_list()
                select(len(chars)-1)
                try: self._ui_log("🧙 RPG Vault: created a new character.", dim=True)
                except Exception: pass

            def save_char():
                i = selected["idx"]
                if i is None:
                    return
                try:
                    raw = editor.get("1.0", "end").strip()
                    obj = json.loads(raw) if raw else {}
                    chars[i] = _rpg_recompute(obj)
                    _rpg_save_all(self, chars)
                    refresh_list()
                    select(i)
                    roll_out.configure(text="Saved")
                except Exception:
                    roll_out.configure(text="Invalid JSON")

            def do_roll():
                try:
                    r = _porch_roll(roll_entry.get())
                    roll_out.configure(text=f"Total: {r['total']}")
                    try: self._ui_log(f"🎲 Roll {r['expr']} → {r['total']}", dim=True, mono=True)
                    except Exception: pass
                except Exception as e:
                    roll_out.configure(text=str(e))

            ctk.CTkButton(left, text="New", command=new_char).pack(padx=12, pady=(0, 12), fill="x")
            ctk.CTkButton(footer, text="Save", command=save_char).grid(row=0, column=1, padx=(0, 8))
            ctk.CTkButton(footer, text="Roll", command=do_roll).grid(row=0, column=2, padx=(0, 8))
            ctk.CTkButton(footer, text="Recompute", command=save_char).grid(row=0, column=3, padx=(0, 8), sticky="w")

            refresh_list()
            if chars:
                select(0)
        except Exception:
            try: self._ui_log("RPG Vault failed to open.", dim=True)
            except Exception: pass

    # --- Catalyst-inspired “Lab Runner” (reproducible prompt experiments) ---
    class _PorchLabRunner:
        def __init__(self, porch, items, logdir):
            self.porch = porch
            self.items = list(items or [])
            self.logdir = logdir
            self.results = []

        def run(self):
            _porch__ensure_dir(self.logdir)
            for i, it in enumerate(self.items, start=1):
                rec = dict(it)
                rec["step"] = i
                rec["ts"] = _porch__ts()
                self.results.append(rec)
            out = os.path.join(self.logdir, "run.json")
            try:
                with open(out, "w", encoding="utf-8") as f:
                    json.dump({"items": self.items, "results": self.results}, f, ensure_ascii=False, indent=2)
            except Exception:
                pass
            return out

    def _open_lab(self):
        try:
            dlg = ctk.CTkToplevel(self)
            dlg.title("Lab (Catalyst-inspired Runner)")
            dlg.geometry("980x700")
            dlg.grid_columnconfigure(0, weight=1)
            dlg.grid_rowconfigure(1, weight=1)

            ctk.CTkLabel(dlg, text="Lab Runner", font=(FONT_FAMILY, 18, "bold")).grid(row=0, column=0, sticky="w", padx=14, pady=(14, 6))
            t = ctk.CTkTextbox(dlg, corner_radius=10)
            t.grid(row=1, column=0, sticky="nsew", padx=14, pady=(0, 10))
            t.insert("1.0",
                "# Each line is an experiment item (a prompt or action)\n"
                "forge: create NPC faction table\n"
                "brew: write a one-page adventure hook\n"
                "world: add a node describing the Shasta temple entrance\n"
            )

            row = ctk.CTkFrame(dlg, fg_color="transparent")
            row.grid(row=2, column=0, sticky="ew", padx=14, pady=(0, 14))
            row.grid_columnconfigure(2, weight=1)

            status = ctk.CTkLabel(row, text="", text_color=PALETTE["muted"])
            status.grid(row=0, column=3, padx=(10, 0), sticky="e")

            def run_lab():
                lines = [ln.strip() for ln in t.get("1.0", "end").splitlines() if ln.strip() and not ln.strip().startswith("#")]
                items = [{"text": ln} for ln in lines]
                logdir = _porch__created("lab", f"run_{_porch__ts()}")
                runner = _PorchLabRunner(self, items, logdir)
                out = runner.run()
                try: self._ui_log(f"🧪 Lab run saved: {out}", dim=True)
                except Exception: pass
                status.configure(text="Saved run.json")

            ctk.CTkButton(row, text="Run (save)", command=run_lab).grid(row=0, column=0, padx=(0, 8))
            ctk.CTkButton(row, text="Open created/lab", command=lambda: self._open_created_folder()).grid(row=0, column=1, padx=(0, 8))
        except Exception:
            try: self._ui_log("Lab window failed to open.", dim=True)
            except Exception: pass

    # --- jMonkeyEngine exporter (project skeleton + world snapshot) ---
    def _export_jme(self, project_name: str = "porch_jme"):
        name = _porch__safe_name(project_name, "porch_jme")
        root = _porch__created("jme", f"{name}_{_porch__ts()}")
        src = os.path.join(root, "src", "main", "java", "org", "porch", "jme")
        assets = os.path.join(root, "assets")
        _porch__ensure_dir(src)
        _porch__ensure_dir(assets)

        world_out = os.path.join(assets, "porch_world.json")
        snapshot = {"nodes": []}
        try:
            conn = self.world._conn()
            try:
                cur = conn.execute("SELECT node_id, node_type, title, tags, summary, facts, path, updated_at FROM world_nodes ORDER BY updated_at DESC LIMIT 500")
                for row in cur.fetchall():
                    snapshot["nodes"].append({
                        "node_id": row[0], "node_type": row[1], "title": row[2],
                        "tags": (row[3] or "").split(",") if row[3] else [],
                        "summary": row[4] or "", "facts": (row[5] or "").split("|") if row[5] else [],
                        "path": row[6] or "", "updated_at": row[7] or ""
                    })
            finally:
                conn.close()
        except Exception:
            pass
        _porch__write(world_out, json.dumps(snapshot, ensure_ascii=False, indent=2))

        settings_gradle = f'rootProject.name = "{name}"\n'
        _porch__write(os.path.join(root, "settings.gradle"), settings_gradle)
        _porch__write(os.path.join(root, "build.gradle"), "plugins {\n    id 'application'\n}\n\nrepositories {\n    mavenCentral()\n}\n\ndef jmeVer = '3.8.1-stable'\n\ndependencies {\n    implementation \"org.jmonkeyengine:jme3-core:${jmeVer}\"\n    implementation \"org.jmonkeyengine:jme3-desktop:${jmeVer}\"\n    implementation \"org.jmonkeyengine:jme3-lwjgl3:${jmeVer}\"\n}\n\napplication {\n    mainClass = 'org.porch.jme.PorchApp'\n}\n\njava {\n    toolchain {\n        languageVersion = JavaLanguageVersion.of(21)\n    }\n}\n")
        _porch__write(os.path.join(src, "PorchApp.java"), "package org.porch.jme;\n\nimport com.jme3.app.SimpleApplication;\nimport com.jme3.asset.plugins.FileLocator;\nimport com.jme3.material.Material;\nimport com.jme3.math.ColorRGBA;\nimport com.jme3.math.Vector3f;\nimport com.jme3.scene.Geometry;\nimport com.jme3.scene.shape.Box;\n\nimport java.nio.file.Files;\nimport java.nio.file.Paths;\n\npublic class PorchApp extends SimpleApplication {\n\n    public static void main(String[] args) {\n        PorchApp app = new PorchApp();\n        app.start();\n    }\n\n    @Override\n    public void simpleInitApp() {\n        // Allow loading assets from local \"assets\" folder.\n        assetManager.registerLocator(\"assets\", FileLocator.class);\n\n        flyCam.setMoveSpeed(18f);\n\n        // A simple box \"world stub\" \u2014 replace with proper scene importers.\n        Box b = new Box(1, 1, 1);\n        Geometry g = new Geometry(\"PorchNode\", b);\n        Material mat = new Material(assetManager, \"Common/MatDefs/Misc/Unshaded.j3md\");\n        mat.setColor(\"Color\", ColorRGBA.Cyan);\n        g.setMaterial(mat);\n        rootNode.attachChild(g);\n\n        // Load Porch world snapshot (JSON) if present\n        try {\n            String json = Files.readString(Paths.get(\"assets/porch_world.json\"));\n            System.out.println(\"Loaded porch_world.json (\" + json.length() + \" chars)\");\n        } catch (Exception e) {\n            System.out.println(\"No porch_world.json found yet.\");\n        }\n\n        cam.setLocation(new Vector3f(0, 2.5f, 8f));\n        cam.lookAt(Vector3f.ZERO, Vector3f.UNIT_Y);\n    }\n}\n")

        readme = f"""# {name}

Generated by InfinitePorch (jMonkeyEngine-inspired exporter)

## Run
1. Install Java (JDK 21 recommended)
2. Install Gradle (or add Gradle wrapper yourself)
3. From this folder:

    gradle run

## What you got
- build.gradle / settings.gradle
- src/main/java/org/porch/jme/PorchApp.java
- assets/porch_world.json  (snapshot of your Porch WorldMemory nodes)

Next step: replace the stub box with a scene graph that instantiates nodes from porch_world.json.
"""
        _porch__write(os.path.join(root, "README.md"), readme)

        try: self._ui_log(f"🧱 jME export created: {root}", dim=True)
        except Exception: pass
        return root

    # --- LDC helper (optional) ---
    def _ldc_check(self) -> bool:
        if subprocess is None:
            return False
        try:
            cp = subprocess.run(["ldc2", "--version"], capture_output=True, text=True, timeout=6)
            ok = (cp.returncode == 0)
            if ok:
                try: self._ui_log(cp.stdout.splitlines()[0], dim=True, mono=True)
                except Exception: pass
            return ok
        except Exception:
            return False

    def _ldc_compile(self, d_path: str):
        if subprocess is None:
            raise RuntimeError("subprocess unavailable")
        ap = os.path.abspath(d_path)
        well = os.path.abspath(WELL_FOLDER)
        if not ap.startswith(well):
            raise ValueError("For safety, compile only files inside the WELL folder.")
        out_dir = _porch__created("d_tool", "out")
        _porch__ensure_dir(out_dir)
        out_name = _porch__safe_name(os.path.splitext(os.path.basename(ap))[0], "program")
        out_path = os.path.join(out_dir, out_name + (".exe" if os.name == "nt" else ""))
        cp = subprocess.run(["ldc2", ap, "-O", "-release", "-of=" + out_path], capture_output=True, text=True, timeout=120)
        return cp.returncode, cp.stdout, cp.stderr, out_path

    for _name, _fn in {
        "_open_homebrewery": _open_homebrewery,
        "_open_rpg_vault": _open_rpg_vault,
        "_open_lab": _open_lab,
        "_export_jme": _export_jme,
        "_ldc_check": _ldc_check,
        "_ldc_compile": _ldc_compile,
    }.items():
        try:
            if not hasattr(cls, _name):
                setattr(cls, _name, _fn)
        except Exception:
            pass

    try:
        if getattr(cls, "_github_ideas_patched", False):
            return
        orig = cls._handle_slash_command

        def _patched(self, text: str) -> bool:
            m = (text or "").strip()
            if not m.startswith("/"):
                return False
            parts = m.split()
            cmd = parts[0].lower()

            if cmd in ("/brew", "/homebrew", "/homebrewery"):
                try: self._open_homebrewery()
                except Exception: pass
                return True

            if cmd in ("/rpg", "/dicecloud", "/sheet", "/character"):
                try: self._open_rpg_vault()
                except Exception: pass
                return True

            if cmd in ("/roll", "/dice"):
                expr = " ".join(parts[1:]).strip()
                if not expr:
                    try: self._ui_log("Usage: /roll 2d6+3  (or: /roll d20 adv)", dim=True)
                    except Exception: pass
                    return True
                try:
                    r = _porch_roll(expr)
                    self._ui_log(f"🎲 {expr} → {r['total']}", dim=False, mono=True)
                except Exception as e:
                    try: self._ui_log(f"Roll error: {e}", dim=True)
                    except Exception: pass
                return True

            if cmd in ("/jme", "/jmonkey", "/jmonkeyengine"):
                if len(parts) >= 2 and parts[1].lower() == "export":
                    name = " ".join(parts[2:]).strip() or "porch_jme"
                    try:
                        root = self._export_jme(name)
                        self._ui_log("Next: open that folder in your Java IDE, then `gradle run`.", dim=True)
                    except Exception as e:
                        try: self._ui_log(f"jME export failed: {e}", dim=True)
                        except Exception: pass
                else:
                    try: self._ui_log("Usage: /jme export <project_name>", dim=True)
                    except Exception: pass
                return True

            if cmd in ("/lab", "/catalyst"):
                try: self._open_lab()
                except Exception: pass
                return True

            if cmd == "/ldc":
                if len(parts) == 1 or parts[1].lower() == "check":
                    ok = False
                    try: ok = self._ldc_check()
                    except Exception: ok = False
                    try: self._ui_log("✅ LDC found." if ok else "❌ LDC not found on PATH (ldc2).", dim=True)
                    except Exception: pass
                    return True
                if len(parts) >= 3 and parts[1].lower() == "compile":
                    dpath = " ".join(parts[2:]).strip()
                    try:
                        rc, out, err, exe = self._ldc_compile(dpath)
                        if rc == 0:
                            self._ui_log(f"⚡ Compiled: {exe}", dim=True)
                        else:
                            self._ui_log(f"⚠️ LDC compile failed.\n{err or out}", dim=True, mono=True)
                    except Exception as e:
                        try: self._ui_log(f"LDC error: {e}", dim=True)
                        except Exception: pass
                    return True
                try: self._ui_log("Usage: /ldc check  OR  /ldc compile <path_to_file.d>", dim=True)
                except Exception: pass
                return True

            return orig(self, text)

        cls._handle_slash_command = _patched
        cls._github_ideas_patched = True
    except Exception:
        pass

try:
    _porch_apply_github_idea_integrations()
except Exception:
    pass




# ======================================================================
# NATIVE METAL + LORE STREAM EXTENSIONS
# (Deeper "incorporate ideas": compile-to-shared-lib + GitHub lore index)
# ======================================================================
#
# This layer stays true to the Porch ethos:
# - Wrap, don’t break: patch over existing handlers.
# - Truth-ready verification (Forge-Check).
# - Sovereign safety: compile/ingest only inside WELL by default.
#
# What you get:
#   /forge check                          -> toolchain verification
#   /lore add <repo_url> [name]           -> clone (or zip-download) into WELL/lore/github/
#   /lore update <name>                   -> git pull (if git present)
#   /lore index <name>                    -> index text into WELL/lore/lore.db
#   /lore search <query>                  -> search indexed lore
#   /lore ui                              -> lore studio window
#
#   /ldc newmod <name>                    -> create a D "native module" template in WELL/native_d/
#   /ldc buildlib <path_to_file.d>        -> compile shared library (dll/so/dylib) into created/native/
#   /ldc load <path_to_lib>               -> load shared library into the running Porch
#   /ldc list                             -> list loaded native libs
#
# Native API (optional use by other modules):
#   self._native_metal.wave_sine(...)     -> returns list[float] using native porch_fill_wave if present
#
# Notes:
# - Downloading from GitHub uses either `git` or a conservative zipball fetch.
# - Execution of fetched code is NOT automatic. Lore is indexed for reading/searching.
# - Shared libraries are loaded via ctypes; only libraries you explicitly compile/load are used.

try:
    import ctypes
    import sqlite3
    import urllib.request
    import urllib.parse
except Exception:  # pragma: no cover
    ctypes = None  # type: ignore
    sqlite3 = None  # type: ignore
    urllib = None  # type: ignore

def _porch__tool_exists(exe: str) -> bool:
    try:
        import shutil
        return shutil.which(exe) is not None
    except Exception:
        return False

def _porch__native_root() -> str:
    # binaries live in created/ so they’re clearly "generated artifacts"
    try:
        root = _porch__created("native")
    except Exception:
        root = os.path.join(os.getcwd(), "created", "native")
    _porch__ensure_dir(root)
    return root

def _porch__lore_root() -> str:
    root = os.path.join(WELL_FOLDER, "lore")
    _porch__ensure_dir(root)
    return root

def _porch__lore_repo_root() -> str:
    root = os.path.join(_porch__lore_root(), "github")
    _porch__ensure_dir(root)
    return root

def _porch__lore_db_path() -> str:
    return os.path.join(_porch__lore_root(), "lore.db")

def _porch__lore_cfg_path() -> str:
    return os.path.join(_porch__lore_root(), "repos.json")

def _porch__safe_repo_name(url_or_name: str) -> str:
    s = (url_or_name or "repo").strip()
    s = s.replace("https://", "").replace("http://", "")
    s = s.replace("github.com/", "")
    s = s.strip("/").replace("/", "_").replace(":", "_")
    return _porch__safe_name(s, "repo")

def _porch__load_json(path: str, default):
    try:
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
    except Exception:
        pass
    return default

def _porch__save_json(path: str, obj) -> None:
    try:
        _porch__ensure_dir(os.path.dirname(path) or ".")
        with open(path, "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

class PorchNativeMetal:
    """
    Compiles and loads native shared libraries built from D (via LDC),
    then exposes a tiny, stable ABI surface for hot-path calculations.

    Expected (optional) D ABI:
      extern(C) void porch_fill_wave(float* out, int n, float freq, float amp, float phase);
    """
    def __init__(self, ui_log=None):
        self._ui_log = ui_log
        self._libs = {}       # lib_path -> ctypes.CDLL
        self._symbols = {}    # (lib_path, symbol) -> callable

    def log(self, msg: str, dim: bool = True, mono: bool = True) -> None:
        try:
            if callable(self._ui_log):
                self._ui_log(msg, dim=dim, mono=mono)  # type: ignore[arg-type]
        except Exception:
            pass

    def shared_ext(self) -> str:
        if sys.platform.startswith("win"):
            return ".dll"
        if sys.platform == "darwin":
            return ".dylib"
        return ".so"

    def compile_shared(self, d_path: str) -> tuple[int, str, str, str]:
        if subprocess is None:
            raise RuntimeError("subprocess unavailable")
        ap = os.path.abspath(d_path)
        well = os.path.abspath(WELL_FOLDER)
        if not ap.startswith(well):
            raise ValueError("For safety, compile only files inside the WELL folder.")
        if not _porch__tool_exists("ldc2"):
            raise RuntimeError("ldc2 not found on PATH. Install LDC and restart the Porch.")

        out_dir = _porch__native_root()
        name = _porch__safe_name(os.path.splitext(os.path.basename(ap))[0], "native")
        out_path = os.path.join(out_dir, name + self.shared_ext())

        cmd = ["ldc2", "-shared", ap, "-O", "-release", "-of=" + out_path]
        cp = subprocess.run(cmd, capture_output=True, text=True, timeout=240)
        return cp.returncode, cp.stdout, cp.stderr, out_path

    def load(self, lib_path: str):
        if ctypes is None:
            raise RuntimeError("ctypes unavailable")
        lp = os.path.abspath(lib_path)
        if not os.path.exists(lp):
            raise FileNotFoundError(lp)
        # safety: only load libs from created/native OR from inside WELL
        native_root = os.path.abspath(_porch__native_root())
        well = os.path.abspath(WELL_FOLDER)
        if not (lp.startswith(native_root) or lp.startswith(well)):
            raise ValueError("For safety, load only libraries inside created/native/ or WELL.")
        if lp not in self._libs:
            self._libs[lp] = ctypes.CDLL(lp)
        return self._libs[lp]

    def list_loaded(self) -> list[str]:
        return sorted(self._libs.keys())

    def _get_symbol(self, lib_path: str, symbol: str):
        key = (lib_path, symbol)
        if key in self._symbols:
            return self._symbols[key]
        lib = self.load(lib_path)
        try:
            fn = getattr(lib, symbol)
        except Exception as e:
            raise AttributeError(f"Symbol not found: {symbol} ({e})")
        self._symbols[key] = fn
        return fn

    def wave_sine(self, n: int, freq: float = 7.83, amp: float = 0.55, phase: float = 0.0) -> list[float]:
        """
        Generates a sine-like wave buffer of length n. Uses native porch_fill_wave if any loaded lib provides it.
        Fallbacks to Python if no native symbol exists.
        """
        n = max(0, int(n))
        if n == 0:
            return []
        # Try any loaded lib that contains porch_fill_wave
        if ctypes is not None:
            for lp in self.list_loaded():
                try:
                    fn = self._get_symbol(lp, "porch_fill_wave")
                    # signature: void porch_fill_wave(float* out, int n, float freq, float amp, float phase)
                    fn.argtypes = [ctypes.POINTER(ctypes.c_float), ctypes.c_int, ctypes.c_float, ctypes.c_float, ctypes.c_float]
                    fn.restype = None
                    buf = (ctypes.c_float * n)()
                    fn(buf, n, float(freq), float(amp), float(phase))
                    return [float(buf[i]) for i in range(n)]
                except Exception:
                    continue

        # Python fallback
        out = []
        w = 2.0 * math.pi * float(freq)
        for i in range(n):
            t = i / float(max(1, n))
            out.append(float(amp) * math.sin(w * t + float(phase)))
        return out

def _porch__init_lore_db():
    if sqlite3 is None:
        return
    p = _porch__lore_db_path()
    try:
        con = sqlite3.connect(p)
        cur = con.cursor()
        cur.execute("PRAGMA journal_mode=WAL;")
        cur.execute("""
            CREATE TABLE IF NOT EXISTS repos(
                name TEXT PRIMARY KEY,
                url TEXT,
                path TEXT,
                added_ts TEXT
            );
        """)
        cur.execute("""
            CREATE TABLE IF NOT EXISTS lore_items(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                repo TEXT,
                relpath TEXT,
                kind TEXT,
                content TEXT,
                size_bytes INTEGER,
                mtime REAL
            );
        """)
        cur.execute("CREATE INDEX IF NOT EXISTS idx_lore_repo ON lore_items(repo);")
        cur.execute("CREATE INDEX IF NOT EXISTS idx_lore_path ON lore_items(relpath);")
        con.commit()
        con.close()
    except Exception:
        pass

def _porch__lore_register_repo(name: str, url: str, path: str):
    _porch__init_lore_db()
    cfg = _porch__load_json(_porch__lore_cfg_path(), {"repos": {}})
    cfg["repos"][name] = {"url": url, "path": path, "added_ts": _now_ts()}
    _porch__save_json(_porch__lore_cfg_path(), cfg)
    if sqlite3 is None:
        return
    try:
        con = sqlite3.connect(_porch__lore_db_path())
        cur = con.cursor()
        cur.execute("INSERT OR REPLACE INTO repos(name,url,path,added_ts) VALUES(?,?,?,?)",
                    (name, url, path, cfg["repos"][name]["added_ts"]))
        con.commit()
        con.close()
    except Exception:
        pass

def _porch__lore_list_repos() -> dict:
    cfg = _porch__load_json(_porch__lore_cfg_path(), {"repos": {}})
    return cfg.get("repos") or {}

def _porch__github_zipball(url: str, dest_dir: str, token: str | None = None) -> str:
    """Conservative GitHub zipball download for public repos."""
    if urllib is None:
        raise RuntimeError("urllib unavailable")
    u = (url or "").strip()
    if "github.com/" not in u:
        raise ValueError("Only github.com repos supported by zipball fallback.")
    tail = u.split("github.com/", 1)[1].strip("/")
    owner_repo = "/".join(tail.split("/")[:2])
    api = f"https://api.github.com/repos/{owner_repo}/zipball"
    req = urllib.request.Request(api, headers={"User-Agent": "InfinitePorch"})
    if token:
        req.add_header("Authorization", f"Bearer {token}")
    zip_path = os.path.join(dest_dir, "repo.zip")
    with urllib.request.urlopen(req, timeout=60) as r:
        data = r.read()
    _porch__ensure_dir(dest_dir)
    with open(zip_path, "wb") as f:
        f.write(data)
    import zipfile
    with zipfile.ZipFile(zip_path, "r") as z:
        z.extractall(dest_dir)
    try:
        os.remove(zip_path)
    except Exception:
        pass
    kids = [os.path.join(dest_dir, k) for k in os.listdir(dest_dir)]
    kids = [k for k in kids if os.path.isdir(k)]
    return kids[0] if kids else dest_dir

def _porch__lore_clone_or_download(url: str, name: str, ui_log=None) -> str:
    root = _porch__lore_repo_root()
    dest = os.path.join(root, name)
    if os.path.exists(dest) and os.path.isdir(dest) and os.listdir(dest):
        return dest

    token = os.environ.get("GITHUB_TOKEN") or os.environ.get("GH_TOKEN")
    if subprocess is not None and _porch__tool_exists("git"):
        try:
            _porch__ensure_dir(os.path.dirname(dest) or ".")
            cp = subprocess.run(["git", "clone", "--depth", "1", url, dest], capture_output=True, text=True, timeout=240)
            if cp.returncode == 0:
                return dest
        except Exception:
            pass

    tmp = os.path.join(root, f"_{name}_zip")
    try:
        if os.path.exists(tmp):
            import shutil
            shutil.rmtree(tmp, ignore_errors=True)
    except Exception:
        pass
    extracted = _porch__github_zipball(url, tmp, token=token)
    try:
        import shutil
        shutil.move(extracted, dest)
        try:
            shutil.rmtree(tmp, ignore_errors=True)
        except Exception:
            pass
    except Exception:
        dest = extracted
    return dest

def _porch__lore_git_pull(path: str) -> tuple[bool, str]:
    if subprocess is None or not _porch__tool_exists("git"):
        return False, "git not found"
    try:
        cp = subprocess.run(["git", "-C", path, "pull", "--ff-only"], capture_output=True, text=True, timeout=180)
        ok = (cp.returncode == 0)
        msg = (cp.stdout or cp.stderr or "").strip()
        return ok, (msg[:1000] if msg else ("ok" if ok else "failed"))
    except Exception as e:
        return False, str(e)

def _porch__lore_index_repo(name: str, repo_path: str, ui_log=None) -> int:
    """
    Indexes text-ish files into sqlite for search.
    Conservative:
      - ignores > 1.5MB files
      - ignores binary-ish extensions
      - limits total files per index run
    """
    if sqlite3 is None:
        return 0
    _porch__init_lore_db()

    IGN_EXT = {
        ".png",".jpg",".jpeg",".gif",".webp",".bmp",".ico",
        ".zip",".7z",".rar",".exe",".dll",".so",".dylib",".bin",
        ".mp4",".mov",".avi",".mkv",".wav",".mp3",".ogg",
        ".pdf"
    }
    MAX_BYTES = 1_500_000
    MAX_FILES = 900

    count = 0
    try:
        con = sqlite3.connect(_porch__lore_db_path())
        cur = con.cursor()
        cur.execute("DELETE FROM lore_items WHERE repo=?", (name,))
        con.commit()

        for root, dirs, files in os.walk(repo_path):
            base = os.path.basename(root).lower()
            if base in ("node_modules", ".git", "dist", "build", "target", "out", "__pycache__"):
                dirs[:] = []
                continue
            for fn in files:
                if count >= MAX_FILES:
                    break
                ext = os.path.splitext(fn)[1].lower()
                if ext in IGN_EXT:
                    continue
                fp = os.path.join(root, fn)
                try:
                    st = os.stat(fp)
                    if st.st_size > MAX_BYTES:
                        continue
                    with open(fp, "rb") as f:
                        raw = f.read()
                    if b"\x00" in raw[:4096]:
                        continue
                    text = raw.decode("utf-8", errors="ignore")
                    rel = os.path.relpath(fp, repo_path).replace("\\", "/")
                    cur.execute(
                        "INSERT INTO lore_items(repo,relpath,kind,content,size_bytes,mtime) VALUES(?,?,?,?,?,?)",
                        (name, rel, "text", text[:200_000], int(st.st_size), float(st.st_mtime)),
                    )
                    count += 1
                except Exception:
                    continue
            if count >= MAX_FILES:
                break

        con.commit()
        con.close()
    except Exception:
        pass
    return count

def _porch__lore_search(query: str, repo: str | None = None, limit: int = 20) -> list[dict]:
    if sqlite3 is None:
        return []
    q = (query or "").strip()
    if not q:
        return []
    like = f"%{q}%"
    out = []
    try:
        con = sqlite3.connect(_porch__lore_db_path())
        cur = con.cursor()
        if repo:
            cur.execute(
                "SELECT repo,relpath,substr(content,1,1200) FROM lore_items WHERE repo=? AND content LIKE ? LIMIT ?",
                (repo, like, int(limit)),
            )
        else:
            cur.execute(
                "SELECT repo,relpath,substr(content,1,1200) FROM lore_items WHERE content LIKE ? LIMIT ?",
                (like, int(limit)),
            )
        for r, rel, snippet in cur.fetchall():
            out.append({"repo": r, "relpath": rel, "snippet": snippet})
        con.close()
    except Exception:
        pass
    return out

def _porch__write_native_d_template(name: str) -> str:
    base = os.path.join(WELL_FOLDER, "native_d")
    _porch__ensure_dir(base)
    safe = _porch__safe_name(name, "native")
    path = os.path.join(base, safe + ".d")
    if os.path.exists(path):
        return path
    d_code = (
        "// Porch Native Metal Module (D + LDC)\n"
        "// Build: /ldc buildlib " + path.replace('\\','/') + "\n\n"
        "// ABI contract (optional, used by PorchNativeMetal.wave_sine):\n"
        "//   extern(C) void porch_fill_wave(float* out, int n, float freq, float amp, float phase);\n\n"
        "module " + safe + ";\n\n"
        "import core.stdc.math : sin, M_PI;\n\n"
        "extern(C) void porch_fill_wave(float* out, int n, float freq, float amp, float phase)\n"
        "{\n"
        "    if (out is null || n <= 0) return;\n"
        "    double w = 2.0 * M_PI * cast(double)freq;\n"
        "    foreach(i; 0 .. n)\n"
        "    {\n"
        "        double t = cast(double)i / cast(double)((n>0)?n:1);\n"
        "        out[i] = cast(float)(cast(double)amp * sin(w * t + cast(double)phase));\n"
        "    }\n"
        "}\n"
    )
    with open(path, "w", encoding="utf-8") as f:
        f.write(d_code)
    return path

def _porch_apply_native_metal_lore_stream():
    cls = globals().get("InfinitePorch", None)
    if cls is None:
        return

    def _get_native_metal(self):
        nm = getattr(self, "_native_metal", None)
        if nm is None:
            nm = PorchNativeMetal(ui_log=getattr(self, "_ui_log", None))
            self._native_metal = nm
        return nm

    def _forge_check(self):
        lines = []
        lines.append("🧰 Forge-Check (Truth-Ready Verification)")
        try:
            lines.append(f"- Python: {sys.version.split()[0]}")
        except Exception:
            pass
        try:
            lines.append(f"- OS: {platform.system()} {platform.release()}")
        except Exception:
            pass

        def ok(exe): return "✅" if _porch__tool_exists(exe) else "❌"
        lines.append(f"- git: {ok('git')}")
        lines.append(f"- ldc2: {ok('ldc2')}")
        lines.append(f"- java: {ok('java')}")
        lines.append(f"- node: {ok('node')}")
        lines.append(f"- gradle: {ok('gradle')} (optional)")
        lines.append(f"- WELL: {WELL_FOLDER}")
        try:
            self._ui_log("\n".join(lines), dim=True, mono=True)
        except Exception:
            pass
        return True

    def _open_lore_ui(self):
        try:
            dlg = ctk.CTkToplevel(self)
            dlg.title("Lore Stream (GitHub → Grand Library)")
            dlg.geometry("980x680")
            dlg.grid_columnconfigure(1, weight=1)
            dlg.grid_rowconfigure(2, weight=1)

            left = ctk.CTkFrame(dlg, corner_radius=12)
            left.grid(row=0, column=0, rowspan=3, sticky="nsw", padx=12, pady=12)
            ctk.CTkLabel(left, text="Repos", font=(FONT_FAMILY, 16, "bold"), text_color=PALETTE["text"]).pack(anchor="w", padx=10, pady=(10,6))

            repos = _porch__lore_list_repos()
            repo_names = sorted(repos.keys())

            lb = ctk.CTkTextbox(left, width=240, height=520, corner_radius=10)
            lb.pack(padx=10, pady=(0,10))
            lb.insert("1.0", "\n".join(repo_names) if repo_names else "(none yet)\nUse /lore add <url>")

            top = ctk.CTkFrame(dlg, fg_color="transparent")
            top.grid(row=0, column=1, sticky="ew", padx=12, pady=(12,0))
            top.grid_columnconfigure(0, weight=1)
            q = ctk.CTkEntry(top, placeholder_text="Search lore… (indexes text from repos)")
            q.grid(row=0, column=0, sticky="ew")
            status = ctk.CTkLabel(top, text="", text_color=PALETTE["muted"])
            status.grid(row=0, column=1, padx=(10,0))

            res = ctk.CTkTextbox(dlg, corner_radius=12)
            res.grid(row=2, column=1, sticky="nsew", padx=12, pady=12)

            def do_search():
                query = q.get().strip()
                if not query:
                    return
                hits = _porch__lore_search(query, repo=None, limit=30)
                res.delete("1.0", "end")
                if not hits:
                    res.insert("1.0", "No hits. If you just added a repo, run: /lore index <name>\n")
                    status.configure(text="0 hits")
                    return
                out_lines = []
                for h in hits:
                    out_lines.append(f"[{h['repo']}] {h['relpath']}\n{h['snippet'].strip()}\n---\n")
                res.insert("1.0", "\n".join(out_lines))
                status.configure(text=f"{len(hits)} hits")

            ctk.CTkButton(top, text="Search", command=do_search).grid(row=0, column=2, padx=(10,0))
            ctk.CTkLabel(dlg, text="Tip: /lore index <name> re-indexes. /lore update <name> pulls updates.",
                         text_color=PALETTE["muted"]).grid(row=1, column=1, sticky="w", padx=12, pady=(6,0))
        except Exception:
            try:
                self._ui_log("Lore UI failed to open.", dim=True)
            except Exception:
                pass

    try:
        if getattr(cls, "_native_metal_lore_patched", False):
            return

        for _name, _fn in {
            "_get_native_metal": _get_native_metal,
            "_forge_check": _forge_check,
            "_open_lore_ui": _open_lore_ui,
        }.items():
            try:
                setattr(cls, _name, _fn)
            except Exception:
                pass

        orig = getattr(cls, "_handle_slash_command", None)
        if not callable(orig):
            return

        def _patched(self, text: str):
            try:
                t = (text or "").strip()
            except Exception:
                return orig(self, text)
            if not t.startswith("/"):
                return orig(self, text)

            parts = t.split()
            cmd = parts[0].lower()

            if cmd in ("/forge", "/truth"):
                sub = (parts[1].lower() if len(parts) > 1 else "check")
                if sub in ("check", "verify", "status"):
                    return self._forge_check()
                try:
                    self._ui_log("Usage: /forge check", dim=True)
                except Exception:
                    pass
                return True

            if cmd in ("/lore", "/github"):
                sub = (parts[1].lower() if len(parts) > 1 else "ui")
                if sub in ("ui", "open", "panel"):
                    try:
                        self._open_lore_ui()
                    except Exception:
                        pass
                    return True

                if sub == "list":
                    repos = _porch__lore_list_repos()
                    names = sorted(repos.keys())
                    try:
                        self._ui_log("📚 Lore Repos:\n" + ("\n".join(f"- {n}: {repos[n]['url']}" for n in names) if names else "(none)"),
                                    dim=True, mono=False)
                    except Exception:
                        pass
                    return True

                if sub == "add":
                    if len(parts) < 3:
                        try:
                            self._ui_log("Usage: /lore add <repo_url> [name]", dim=True)
                        except Exception:
                            pass
                        return True
                    url = parts[2].strip()
                    name = _porch__safe_repo_name(parts[3] if len(parts) >= 4 else url)
                    try:
                        path = _porch__lore_clone_or_download(url, name, ui_log=getattr(self, "_ui_log", None))
                        _porch__lore_register_repo(name, url, path)
                        self._ui_log(f"📚 Added repo: {name}\n{path}", dim=True)
                    except Exception as e:
                        try:
                            self._ui_log(f"Lore add failed: {e}", dim=True)
                        except Exception:
                            pass
                    return True

                if sub == "update":
                    if len(parts) < 3:
                        try:
                            self._ui_log("Usage: /lore update <name>", dim=True)
                        except Exception:
                            pass
                        return True
                    name = _porch__safe_repo_name(parts[2])
                    repos = _porch__lore_list_repos()
                    rp = (repos.get(name) or {}).get("path")
                    if not rp or not os.path.exists(rp):
                        try:
                            self._ui_log(f"Unknown repo: {name}. Use /lore list", dim=True)
                        except Exception:
                            pass
                        return True
                    ok, msg = _porch__lore_git_pull(rp)
                    try:
                        self._ui_log(f"📚 Update {name}: {'ok' if ok else 'failed'}\n{msg}", dim=True, mono=True)
                    except Exception:
                        pass
                    return True

                if sub == "index":
                    if len(parts) < 3:
                        try:
                            self._ui_log("Usage: /lore index <name>", dim=True)
                        except Exception:
                            pass
                        return True
                    name = _porch__safe_repo_name(parts[2])
                    repos = _porch__lore_list_repos()
                    rp = (repos.get(name) or {}).get("path")
                    if not rp or not os.path.exists(rp):
                        try:
                            self._ui_log(f"Unknown repo: {name}. Use /lore list", dim=True)
                        except Exception:
                            pass
                        return True
                    try:
                        n = _porch__lore_index_repo(name, rp, ui_log=getattr(self, "_ui_log", None))
                        self._ui_log(f"📚 Indexed {name}: {n} files", dim=True)
                    except Exception as e:
                        try:
                            self._ui_log(f"Index failed: {e}", dim=True)
                        except Exception:
                            pass
                    return True

                if sub == "search":
                    if len(parts) < 3:
                        try:
                            self._ui_log("Usage: /lore search <query>  (run /lore index first)", dim=True)
                        except Exception:
                            pass
                        return True
                    query = " ".join(parts[2:]).strip()
                    hits = _porch__lore_search(query, repo=None, limit=20)
                    try:
                        if not hits:
                            self._ui_log("No hits.", dim=True)
                        else:
                            msg = "\n".join([f"[{h['repo']}] {h['relpath']}\n{h['snippet'].strip()}\n---" for h in hits])
                            self._ui_log(msg, dim=True, mono=False)
                    except Exception:
                        pass
                    return True

                try:
                    self._ui_log("Lore usage:\n"
                                 "/lore ui\n"
                                 "/lore add <repo_url> [name]\n"
                                 "/lore update <name>\n"
                                 "/lore index <name>\n"
                                 "/lore search <query>\n"
                                 "/lore list",
                                 dim=True, mono=True)
                except Exception:
                    pass
                return True

            if cmd == "/ldc":
                sub = (parts[1].lower() if len(parts) > 1 else "check")
                if sub in ("newmod", "template", "new"):
                    name = (parts[2] if len(parts) > 2 else "porch_native")
                    try:
                        path = _porch__write_native_d_template(name)
                        self._ui_log(f"🧩 Native D template created:\n{path}\n\nNext: /ldc buildlib {path}", dim=True)
                    except Exception as e:
                        try:
                            self._ui_log(f"Template error: {e}", dim=True)
                        except Exception:
                            pass
                    return True

                if sub in ("buildlib", "shared", "dll", "so"):
                    if len(parts) < 3:
                        try:
                            self._ui_log("Usage: /ldc buildlib <path_to_file.d>", dim=True)
                        except Exception:
                            pass
                        return True
                    dpath = " ".join(parts[2:]).strip().strip('"')
                    try:
                        nm = self._get_native_metal()
                        rc, out, err, libp = nm.compile_shared(dpath)
                        if rc == 0:
                            self._ui_log(f"✅ Built shared lib:\n{libp}", dim=True)
                        else:
                            self._ui_log(f"Build failed (rc={rc})\n{err or out}", dim=True, mono=True)
                    except Exception as e:
                        try:
                            self._ui_log(f"Build error: {e}", dim=True)
                        except Exception:
                            pass
                    return True

                if sub in ("load", "loadlib"):
                    if len(parts) < 3:
                        try:
                            self._ui_log("Usage: /ldc load <path_to_lib>", dim=True)
                        except Exception:
                            pass
                        return True
                    lp = " ".join(parts[2:]).strip().strip('"')
                    try:
                        nm = self._get_native_metal()
                        nm.load(lp)
                        self._ui_log(f"⚡ Loaded native lib:\n{os.path.abspath(lp)}", dim=True)
                    except Exception as e:
                        try:
                            self._ui_log(f"Load error: {e}", dim=True)
                        except Exception:
                            pass
                    return True

                if sub == "list":
                    try:
                        nm = self._get_native_metal()
                        libs = nm.list_loaded()
                        self._ui_log("⚡ Loaded native libs:\n" + ("\n".join(f"- {p}" for p in libs) if libs else "(none)"),
                                     dim=True, mono=False)
                    except Exception as e:
                        try:
                            self._ui_log(f"List error: {e}", dim=True)
                        except Exception:
                            pass
                    return True

            return orig(self, text)

        cls._handle_slash_command = _patched
        cls._native_metal_lore_patched = True
    except Exception:
        pass

try:
    _porch_apply_native_metal_lore_stream()
except Exception:
    pass



# =====================================================================
# Sovereign App Store + Idea Blocks + Auto-Native Routing (Layer 3 Patch)
# =====================================================================

def _porch__idea_db_path() -> str:
    try:
        lore_dir = os.path.join(WELL_FOLDER, "lore")
        _porch_safe_mkdir(lore_dir)
        return os.path.join(lore_dir, "lore.db")
    except Exception:
        return os.path.join(os.getcwd(), "lore.db")


def _porch__init_idea_tables() -> None:
    if sqlite3 is None:
        return
    p = _porch__idea_db_path()
    try:
        con = sqlite3.connect(p)
        cur = con.cursor()
        cur.execute("PRAGMA journal_mode=WAL;")
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS idea_blocks(
                idea_key TEXT PRIMARY KEY,
                repo_name TEXT,
                repo_path TEXT,
                manifest_path TEXT,
                idea_id TEXT,
                name TEXT,
                version TEXT,
                description TEXT,
                requires_json TEXT,
                plugin_entry TEXT,
                signed_status TEXT,
                sha256 TEXT,
                trusted INTEGER DEFAULT 0,
                applied INTEGER DEFAULT 0,
                last_seen_ts TEXT
            );
            """
        )
        cur.execute(
            """
            CREATE TABLE IF NOT EXISTS idea_applied_files(
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                idea_key TEXT,
                src_rel TEXT,
                dst_rel TEXT,
                sha256 TEXT,
                applied_ts TEXT
            );
            """
        )
        con.commit()
        con.close()
    except Exception:
        pass


def _porch__sha256_file(path: str) -> str:
    try:
        h = hashlib.sha256()
        with open(path, "rb") as f:
            while True:
                b = f.read(1024 * 1024)
                if not b:
                    break
                h.update(b)
        return h.hexdigest()
    except Exception:
        return ""


def _porch__now_iso() -> str:
    try:
        return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z")
    except Exception:
        return ""


def _porch__idea_trust_path() -> str:
    try:
        lore_dir = os.path.join(WELL_FOLDER, "lore")
        _porch_safe_mkdir(lore_dir)
        return os.path.join(lore_dir, "idea_trust.json")
    except Exception:
        return os.path.join(os.getcwd(), "idea_trust.json")


def _porch__load_trust_registry() -> dict:
    p = _porch__idea_trust_path()
    try:
        if os.path.exists(p):
            with open(p, "r", encoding="utf-8") as f:
                return json.load(f) or {}
    except Exception:
        pass
    return {}


def _porch__save_trust_registry(reg: dict) -> None:
    p = _porch__idea_trust_path()
    try:
        _porch_safe_mkdir(os.path.dirname(p) or ".")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(reg, f, indent=2, ensure_ascii=False)
    except Exception:
        pass


class PorchNativeRouter:
    """
    Auto-route hot paths to native (D/LDC) ABI if present.
    Fallback to pure-Python if not present.

    Optional ABI symbols (extern(C)):
      void porch_fill_wave(float* out, int n, float freq, float amp, float phase);
      float porch_dot_f32(const float* a, const float* b, int n);
      ulong porch_fnv1a64(const ubyte* data, int n);
    """
    def __init__(self, native_metal=None, ui_log=None):
        self.nm = native_metal
        self._ui_log = ui_log

    def log(self, msg: str, dim: bool = True, mono: bool = True) -> None:
        try:
            if self._ui_log:
                self._ui_log(msg, dim=dim, mono=mono)
        except Exception:
            pass

    def wave(self, n: int, freq: float, amp: float, phase: float = 0.0):
        try:
            if self.nm:
                return self.nm.wave_sine(int(n), float(freq), float(amp), float(phase))
        except Exception:
            pass
        out = []
        w = 2.0 * math.pi * float(freq)
        for i in range(int(max(0, n))):
            t = i / float(max(1, n))
            out.append(float(amp) * math.sin(w * t + float(phase)))
        return out

    def dot_f32(self, a, b) -> float:
        try:
            if a is None or b is None:
                return 0.0
            n = min(len(a), len(b))
            if n <= 0:
                return 0.0
            if self.nm:
                for lp in (self.nm._libs or {}).keys():
                    try:
                        fn = self.nm._get_symbol(lp, "porch_dot_f32")
                        if fn:
                            fn.restype = ctypes.c_float
                            fn.argtypes = [ctypes.POINTER(ctypes.c_float), ctypes.POINTER(ctypes.c_float), ctypes.c_int]
                            arr_a = (ctypes.c_float * n)(*map(float, a[:n]))
                            arr_b = (ctypes.c_float * n)(*map(float, b[:n]))
                            return float(fn(arr_a, arr_b, int(n)))
                    except Exception:
                        continue
        except Exception:
            pass
        s = 0.0
        n = min(len(a), len(b))
        for i in range(n):
            s += float(a[i]) * float(b[i])
        return float(s)

    def fnv1a64(self, data: bytes) -> int:
        try:
            b = data if isinstance(data, (bytes, bytearray)) else bytes(str(data), "utf-8")
        except Exception:
            b = bytes(str(data), "utf-8", errors="ignore")
        try:
            if self.nm:
                for lp in (self.nm._libs or {}).keys():
                    try:
                        fn = self.nm._get_symbol(lp, "porch_fnv1a64")
                        if fn:
                            fn.restype = ctypes.c_uint64
                            fn.argtypes = [ctypes.POINTER(ctypes.c_ubyte), ctypes.c_int]
                            arr = (ctypes.c_ubyte * len(b)).from_buffer_copy(b)
                            return int(fn(arr, int(len(b))))
                    except Exception:
                        continue
        except Exception:
            pass
        h = 1469598103934665603
        prime = 1099511628211
        for by in b:
            h ^= by
            h = (h * prime) & 0xFFFFFFFFFFFFFFFF
        return int(h)


class PorchIdeaManager:
    """
    Sovereign Idea Blocks:
      - Scan repos for porch_idea.json
      - Record in lore.db
      - Require explicit trust before apply
      - Apply copies into WELL/ideas/<idea_id> (sandboxed)
      - Optional plugin loader for trusted+applied python plugins
    """
    MANIFEST_NAMES = ("porch_idea.json", ".porch_idea.json", "porch.idea.json")

    def __init__(self, ui_log=None):
        self._ui_log = ui_log
        _porch__init_idea_tables()

    def log(self, msg: str, dim: bool = True, mono: bool = True) -> None:
        try:
            if self._ui_log:
                self._ui_log(msg, dim=dim, mono=mono)
        except Exception:
            pass

    def _db(self):
        if sqlite3 is None:
            return None
        try:
            return sqlite3.connect(_porch__idea_db_path())
        except Exception:
            return None

    def _idea_key(self, repo_name: str, manifest_rel: str) -> str:
        return f"{repo_name}::{manifest_rel}"

    def scan_repo(self, repo_name: str, repo_path: str, max_files: int = 8000) -> int:
        _porch__init_idea_tables()
        repo_path = os.path.abspath(repo_path)
        if not os.path.isdir(repo_path):
            self.log(f"Repo path not found: {repo_path}", dim=True)
            return 0

        found = []
        try:
            nfiles = 0
            for root, dirs, files in os.walk(repo_path):
                dirs[:] = [d for d in dirs if d not in (".git", "node_modules", "build", "dist", "target", ".gradle", ".idea")]
                for fn in files:
                    nfiles += 1
                    if nfiles > max_files:
                        break
                    if fn in self.MANIFEST_NAMES:
                        found.append(os.path.join(root, fn))
                if nfiles > max_files:
                    break
        except Exception:
            pass

        if not found:
            self.log(f"🔎 No Idea manifests found in {repo_name}.", dim=True)
            return 0

        reg = _porch__load_trust_registry()
        con = self._db()
        if not con:
            return 0
        cur = con.cursor()
        count = 0
        for mp in found:
            try:
                data = json.loads(open(mp, "r", encoding="utf-8").read() or "{}")
            except Exception:
                continue
            idea_id = str(data.get("id") or "").strip() or os.path.splitext(os.path.basename(os.path.dirname(mp) or mp))[0]
            name = str(data.get("name") or idea_id).strip()
            version = str(data.get("version") or "").strip()
            desc = str(data.get("description") or "").strip()
            requires = data.get("requires") or {}
            plugin_entry = str(data.get("plugin_entry") or data.get("plugin") or "").strip()
            sha = _porch__sha256_file(mp)
            manifest_rel = os.path.relpath(mp, repo_path).replace("\\", "/")
            idea_key = self._idea_key(repo_name, manifest_rel)
            tinfo = reg.get(idea_key) or {}
            trusted = 1 if bool(tinfo.get("trusted")) and (tinfo.get("sha256") == sha or not tinfo.get("sha256")) else 0
            signed_status = "manifest-hash" if sha else "unknown"
            try:
                cur.execute(
                    """
                    INSERT INTO idea_blocks(idea_key, repo_name, repo_path, manifest_path, idea_id, name, version, description,
                                            requires_json, plugin_entry, signed_status, sha256, trusted, last_seen_ts)
                    VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                    ON CONFLICT(idea_key) DO UPDATE SET
                        repo_path=excluded.repo_path,
                        manifest_path=excluded.manifest_path,
                        idea_id=excluded.idea_id,
                        name=excluded.name,
                        version=excluded.version,
                        description=excluded.description,
                        requires_json=excluded.requires_json,
                        plugin_entry=excluded.plugin_entry,
                        signed_status=excluded.signed_status,
                        sha256=excluded.sha256,
                        trusted=excluded.trusted,
                        last_seen_ts=excluded.last_seen_ts
                    """,
                    (
                        idea_key, repo_name, repo_path, manifest_rel,
                        idea_id, name, version, desc,
                        json.dumps(requires, ensure_ascii=False),
                        plugin_entry, signed_status, sha,
                        int(trusted), _porch__now_iso()
                    )
                )
                count += 1
            except Exception:
                pass
        con.commit()
        con.close()
        self.log(f"✅ Registered {count} Idea manifest(s) from {repo_name}.", dim=True)
        return count

    def list_ideas(self):
        con = self._db()
        if not con:
            return []
        cur = con.cursor()
        try:
            cur.execute("SELECT idea_key, repo_name, idea_id, name, version, trusted, applied FROM idea_blocks ORDER BY repo_name, name;")
            rows = cur.fetchall() or []
        except Exception:
            rows = []
        con.close()
        return [
            {"idea_key": r[0], "repo": r[1], "idea_id": r[2], "name": r[3],
             "version": r[4], "trusted": int(r[5] or 0), "applied": int(r[6] or 0)}
            for r in rows
        ]

    def get_idea(self, idea_key: str) -> dict:
        con = self._db()
        if not con:
            return {}
        cur = con.cursor()
        try:
            cur.execute(
                """
                SELECT idea_key, repo_name, repo_path, manifest_path, idea_id, name, version, description,
                       requires_json, plugin_entry, signed_status, sha256, trusted, applied
                FROM idea_blocks WHERE idea_key=?
                """,
                (idea_key,)
            )
            r = cur.fetchone()
        except Exception:
            r = None
        con.close()
        if not r:
            return {}
        try:
            req = json.loads(r[8] or "{}") if isinstance(r[8], str) else {}
        except Exception:
            req = {}
        return {
            "idea_key": r[0], "repo_name": r[1], "repo_path": r[2], "manifest_path": r[3],
            "idea_id": r[4], "name": r[5], "version": r[6], "description": r[7],
            "requires": req, "plugin_entry": r[9], "signed_status": r[10], "sha256": r[11],
            "trusted": int(r[12] or 0), "applied": int(r[13] or 0),
        }

    def set_trust(self, idea_key: str, trusted: bool) -> bool:
        idea = self.get_idea(idea_key)
        if not idea:
            return False
        reg = _porch__load_trust_registry()
        reg[idea_key] = {"trusted": bool(trusted), "approved_at": _porch__now_iso(), "sha256": idea.get("sha256") or ""}
        _porch__save_trust_registry(reg)
        con = self._db()
        if con:
            try:
                con.execute("UPDATE idea_blocks SET trusted=? WHERE idea_key=?", (1 if trusted else 0, idea_key))
                con.commit()
            except Exception:
                pass
            con.close()
        self.log(("🔓 Trusted " if trusted else "🔒 Untrusted ") + idea_key, dim=True)
        return True

    def diff_manifest(self, idea_key: str) -> str:
        idea = self.get_idea(idea_key)
        if not idea:
            return "Idea not found."
        mp = os.path.join(idea["repo_path"], idea["manifest_path"])
        try:
            raw_lines = open(mp, "r", encoding="utf-8").read().splitlines()
        except Exception:
            raw_lines = []
        try:
            parsed = json.loads("\n".join(raw_lines) or "{}")
            norm_lines = json.dumps(parsed, indent=2, sort_keys=True, ensure_ascii=False).splitlines()
        except Exception:
            norm_lines = raw_lines
        import difflib
        d = difflib.unified_diff(raw_lines, norm_lines, fromfile="manifest.raw", tofile="manifest.normalized", lineterm="")
        return "\n".join(d) if d else "(manifest normalized equals raw)"

    def _missing_tools(self, requires: dict) -> list:
        missing = []
        try:
            tools = requires.get("tools") or []
            for t in tools:
                if not shutil.which(str(t)):
                    missing.append(str(t))
        except Exception:
            pass
        return missing

    def apply(self, idea_key: str) -> tuple:
        idea = self.get_idea(idea_key)
        if not idea:
            return (False, "Idea not found.")
        if not idea.get("trusted"):
            return (False, "Idea is not trusted. Run /idea trust <idea_key> first.")

        mp = os.path.join(idea["repo_path"], idea["manifest_path"])
        try:
            manifest = json.loads(open(mp, "r", encoding="utf-8").read() or "{}")
        except Exception as e:
            return (False, f"Manifest parse error: {e}")

        missing = self._missing_tools(manifest.get("requires") or {})
        if missing:
            return (False, "Missing required tools: " + ", ".join(missing))

        files = manifest.get("files") or []
        if not isinstance(files, list):
            files = []

        idea_id = str(manifest.get("id") or idea.get("idea_id") or "idea").strip() or "idea"
        install_root = os.path.join(WELL_FOLDER, "ideas", idea_id)
        _porch_safe_mkdir(install_root)

        # sandbox enforce if secure layer present
        try:
            cfg = PorchSecurityConfig.from_env()
            sb = _PathSandbox(cfg.well_root)
        except Exception:
            sb = None

        con = self._db()
        cur = con.cursor() if con else None
        applied_ts = _porch__now_iso()
        n_applied = 0

        for spec in files:
            try:
                src_rel = str(spec.get("src") or "").strip()
                dst_rel = str(spec.get("dst") or "").strip()
                if not src_rel or not dst_rel:
                    continue
                src_abs = os.path.abspath(os.path.join(idea["repo_path"], src_rel))
                if not src_abs.startswith(os.path.abspath(idea["repo_path"])):
                    continue
                if not os.path.isfile(src_abs):
                    continue
                dst_abs = os.path.abspath(os.path.join(install_root, dst_rel))
                if sb:
                    try:
                        _ = sb._resolve_for_write(dst_abs)
                    except Exception:
                        continue
                _porch_safe_mkdir(os.path.dirname(dst_abs) or ".")
                shutil.copy2(src_abs, dst_abs)
                sha = _porch__sha256_file(dst_abs)
                n_applied += 1
                if cur:
                    try:
                        cur.execute(
                            "INSERT INTO idea_applied_files(idea_key, src_rel, dst_rel, sha256, applied_ts) VALUES(?,?,?,?,?)",
                            (idea_key, src_rel.replace("\\", "/"), dst_rel.replace("\\", "/"), sha, applied_ts),
                        )
                    except Exception:
                        pass
            except Exception:
                continue

        if con:
            try:
                con.execute("UPDATE idea_blocks SET applied=? WHERE idea_key=?", (1, idea_key))
                con.commit()
            except Exception:
                pass
            con.close()

        msg = f"✅ Applied {n_applied} file(s) into: {install_root}" if n_applied else f"✅ Marked applied (no files). Install root: {install_root}"
        self.log(msg, dim=True)
        return (True, msg)

    def load_trusted_plugins(self, app) -> int:
        ideas = self.list_ideas()
        loaded = 0
        for it in ideas:
            if not it.get("trusted") or not it.get("applied"):
                continue
            idea = self.get_idea(it["idea_key"])
            idea_id = str(idea.get("idea_id") or it.get("idea_id") or "").strip() or "idea"
            install_root = os.path.join(WELL_FOLDER, "ideas", idea_id)
            entry = (idea.get("plugin_entry") or "").strip() or "plugin.py"
            plugin_path = os.path.join(install_root, entry)
            if not os.path.isfile(plugin_path):
                continue
            try:
                import importlib.util, importlib.machinery
                if not hasattr(app, "_plugin_cmds"):
                    app._plugin_cmds = {}
                api = PorchPluginAPI(app)
                modname = f"porch_idea_{idea_id}_{int(time.time())}"
                loader = importlib.machinery.SourceFileLoader(modname, plugin_path)
                spec = importlib.util.spec_from_loader(modname, loader)
                mod = importlib.util.module_from_spec(spec)
                loader.exec_module(mod)
                if hasattr(mod, "register") and callable(mod.register):
                    mod.register(api)
                    loaded += 1
                    try:
                        api.log(f"🔌 Loaded plugin: {idea_id} ({plugin_path})", dim=True)
                    except Exception:
                        pass
            except Exception as e:
                try:
                    self.log(f"Plugin load error ({idea_id}): {e}", dim=True)
                except Exception:
                    pass
        return loaded


class PorchPluginAPI:
    def __init__(self, app):
        self.app = app

    def log(self, msg: str, dim: bool = True, mono: bool = True) -> None:
        try:
            self.app._ui_log(msg, dim=dim, mono=mono)
        except Exception:
            pass

    def add_slash_command(self, name: str, handler):
        name = (name or "").strip()
        if not name.startswith("/"):
            name = "/" + name
        if not callable(handler):
            raise ValueError("handler must be callable")
        if not hasattr(self.app, "_plugin_cmds"):
            self.app._plugin_cmds = {}
        self.app._plugin_cmds[name.lower()] = handler
        self.log(f"🧩 Plugin command registered: {name}", dim=True)


class PorchStoreUI:
    PRESETS = [
        ("jmonkeyengine", "https://github.com/jMonkeyEngine/jmonkeyengine"),
        ("homebrewery", "https://github.com/naturalcrit/homebrewery"),
        ("catalyst", "https://github.com/catalyst-team/catalyst"),
        ("dicecloud", "https://github.com/ThaumRystra/DiceCloud"),
        ("ldc", "https://github.com/ldc-developers/ldc"),
    ]

    def __init__(self, app):
        self.app = app
        self.idea = getattr(app, "_idea_mgr", None) or PorchIdeaManager(ui_log=getattr(app, "_ui_log", None))
        app._idea_mgr = self.idea
        self.win = ctk.CTkToplevel(app)
        try:
            self.win.title("Sovereign App Store")
        except Exception:
            pass
        self.win.geometry("1000x720")
        self.win.grid_rowconfigure(0, weight=1)
        self.win.grid_columnconfigure(0, weight=1)

        tabs = ctk.CTkTabview(self.win)
        tabs.grid(row=0, column=0, sticky="nsew", padx=12, pady=12)

        self.tab_check = tabs.add("Forge-Check")
        self.tab_lore = tabs.add("Lore")
        self.tab_ideas = tabs.add("Ideas")
        self.tab_native = tabs.add("Native Metal")

        self._build_check()
        self._build_lore()
        self._build_ideas()
        self._build_native()

    def _build_check(self):
        f = ctk.CTkFrame(self.tab_check, corner_radius=12)
        f.pack(fill="both", expand=True, padx=10, pady=10)

        header = ctk.CTkLabel(f, text="Forge-Check (Truth-Ready Verification)", font=(FONT_FAMILY, 18, "bold"))
        header.pack(anchor="w", padx=12, pady=(12, 6))

        btn = ctk.CTkButton(f, text="Run /forge check", command=self._run_check)
        btn.pack(anchor="w", padx=12, pady=8)

        self.check_out = ctk.CTkTextbox(f, corner_radius=10)
        self.check_out.pack(fill="both", expand=True, padx=12, pady=(0, 12))

        self._run_check()

    def _run_check(self):
        out = []
        tools = ["python", "git", "ldc2", "java", "node", "npm", "gradle"]
        out.append(f"UTC: {_porch__now_iso()}")
        out.append(f"WELL: {os.path.abspath(WELL_FOLDER)}")
        out.append("")
        for t in tools:
            ok = bool(shutil.which(t))
            out.append(f"{'✅' if ok else '❌'} {t}")
        out.append("")
        out.append("Tip: install missing tools, then re-run.")
        try:
            self.check_out.delete("1.0", "end")
            self.check_out.insert("end", "\n".join(out))
        except Exception:
            pass

    def _build_lore(self):
        wrap = ctk.CTkFrame(self.tab_lore, corner_radius=12)
        wrap.pack(fill="both", expand=True, padx=10, pady=10)
        wrap.grid_columnconfigure(0, weight=1)
        wrap.grid_columnconfigure(1, weight=1)
        wrap.grid_rowconfigure(3, weight=1)

        header = ctk.CTkLabel(wrap, text="Lore Stream (Repos → Index → Search)", font=(FONT_FAMILY, 18, "bold"))
        header.grid(row=0, column=0, columnspan=2, sticky="w", padx=12, pady=(12, 6))

        preset_frame = ctk.CTkFrame(wrap, corner_radius=10)
        preset_frame.grid(row=1, column=0, columnspan=2, sticky="ew", padx=12, pady=(6, 10))

        for i, (name, url) in enumerate(self.PRESETS):
            b = ctk.CTkButton(preset_frame, text=f"Add {name}", command=lambda n=name, u=url: self._lore_add(n, u))
            b.grid(row=0, column=i, padx=6, pady=10)

        self.lore_search = ctk.CTkEntry(wrap, placeholder_text="Search lore…")
        self.lore_search.grid(row=2, column=0, sticky="ew", padx=12, pady=(0, 8))
        sbtn = ctk.CTkButton(wrap, text="Search", command=self._lore_search)
        sbtn.grid(row=2, column=1, sticky="ew", padx=12, pady=(0, 8))

        self.lore_out = ctk.CTkTextbox(wrap, corner_radius=10)
        self.lore_out.grid(row=3, column=0, columnspan=2, sticky="nsew", padx=12, pady=(0, 12))

        self._lore_status()

    def _lore_add(self, name: str, url: str):
        try:
            _porch__init_lore_db()
            rp = _porch__lore_clone_or_download(name, url, ui_log=getattr(self.app, "_ui_log", None))
            _porch__lore_register_repo(name, url, rp)
            _porch__lore_index_repo(name, rp, ui_log=getattr(self.app, "_ui_log", None))
            self._lore_status()
        except Exception as e:
            self._lore_write(f"Error: {e}")

    def _lore_status(self):
        try:
            repos = _porch__lore_list_repos()
        except Exception:
            repos = []
        lines = ["Repos registered:"]
        for r in repos:
            lines.append(f"- {r.get('name')}  →  {r.get('path')}")
        self._lore_write("\n".join(lines) + "\n\n(Use presets above to add + index.)")

    def _lore_search(self):
        q = ""
        try:
            q = self.lore_search.get().strip()
        except Exception:
            pass
        if not q:
            self._lore_write("Type a query first.")
            return
        try:
            res = _porch__lore_search(q, limit=30)
            lines = [f"Results for: {q}", ""]
            for r in res:
                lines.append(f"[{r.get('repo')}] {r.get('relpath')} (score {r.get('score')})")
                lines.append(f"  {r.get('snippet')}")
                lines.append("")
            if not res:
                lines.append("(no hits yet — make sure you indexed repos)")
            self._lore_write("\n".join(lines))
        except Exception as e:
            self._lore_write(f"Search error: {e}")

    def _lore_write(self, text: str):
        try:
            self.lore_out.delete("1.0", "end")
            self.lore_out.insert("end", text)
        except Exception:
            pass

    def _build_ideas(self):
        wrap = ctk.CTkFrame(self.tab_ideas, corner_radius=12)
        wrap.pack(fill="both", expand=True, padx=10, pady=10)
        wrap.grid_columnconfigure(0, weight=1)
        wrap.grid_columnconfigure(1, weight=1)
        wrap.grid_rowconfigure(2, weight=1)

        header = ctk.CTkLabel(wrap, text="Idea Blocks (Scan → Trust → Apply)", font=(FONT_FAMILY, 18, "bold"))
        header.grid(row=0, column=0, columnspan=2, sticky="w", padx=12, pady=(12, 6))

        btn_scan = ctk.CTkButton(wrap, text="Scan all repos", command=self._ideas_scan_all)
        btn_scan.grid(row=1, column=0, sticky="ew", padx=12, pady=(0, 8))
        btn_refresh = ctk.CTkButton(wrap, text="Refresh list", command=self._ideas_refresh)
        btn_refresh.grid(row=1, column=1, sticky="ew", padx=12, pady=(0, 8))

        self.ideas_list = ctk.CTkTextbox(wrap, corner_radius=10)
        self.ideas_list.grid(row=2, column=0, sticky="nsew", padx=12, pady=(0, 12))

        right = ctk.CTkFrame(wrap, corner_radius=10)
        right.grid(row=2, column=1, sticky="nsew", padx=12, pady=(0, 12))
        right.grid_rowconfigure(3, weight=1)
        right.grid_columnconfigure(0, weight=1)

        self.idea_key_entry = ctk.CTkEntry(right, placeholder_text="idea_key (copy from list)")
        self.idea_key_entry.grid(row=0, column=0, sticky="ew", padx=10, pady=(10, 8))

        row = ctk.CTkFrame(right, corner_radius=10)
        row.grid(row=1, column=0, sticky="ew", padx=10, pady=(0, 8))
        ctk.CTkButton(row, text="Trust", command=lambda: self._idea_trust(True)).pack(side="left", padx=6, pady=8)
        ctk.CTkButton(row, text="Untrust", command=lambda: self._idea_trust(False)).pack(side="left", padx=6, pady=8)
        ctk.CTkButton(row, text="Apply", command=self._idea_apply).pack(side="left", padx=6, pady=8)
        ctk.CTkButton(row, text="Diff manifest", command=self._idea_diff).pack(side="left", padx=6, pady=8)

        self.idea_detail = ctk.CTkTextbox(right, corner_radius=10)
        self.idea_detail.grid(row=3, column=0, sticky="nsew", padx=10, pady=(0, 10))

        self._ideas_refresh()

    def _ideas_scan_all(self):
        try:
            repos = _porch__lore_list_repos()
        except Exception:
            repos = []
        n = 0
        for r in repos:
            try:
                n += int(self.idea.scan_repo(r.get("name"), r.get("path")))
            except Exception:
                continue
        self._ideas_refresh()
        self._idea_write(f"Scan complete. Registered {n} manifest(s).")

    def _ideas_refresh(self):
        items = self.idea.list_ideas()
        lines = ["Idea Blocks:"]
        for it in items:
            flag = ("T" if it["trusted"] else " ") + ("/A" if it["applied"] else " ")
            lines.append(f"- [{flag}] {it['idea_key']}  →  {it['name']} ({it['version']})")
        if not items:
            lines.append("(none found yet — scan repos after adding them in Lore tab)")
        try:
            self.ideas_list.delete("1.0", "end")
            self.ideas_list.insert("end", "\n".join(lines))
        except Exception:
            pass

    def _idea_key(self) -> str:
        try:
            return (self.idea_key_entry.get() or "").strip()
        except Exception:
            return ""

    def _idea_trust(self, on: bool):
        k = self._idea_key()
        if not k:
            self._idea_write("Paste an idea_key first.")
            return
        ok = self.idea.set_trust(k, on)
        self._ideas_refresh()
        if not ok:
            self._idea_write("Idea not found.")

    def _idea_apply(self):
        k = self._idea_key()
        if not k:
            self._idea_write("Paste an idea_key first.")
            return
        ok, msg = self.idea.apply(k)
        self._ideas_refresh()
        self._idea_write(msg)
        if ok:
            try:
                loaded = self.idea.load_trusted_plugins(self.app)
                if loaded:
                    self._idea_write(msg + f"\n\n🔌 Loaded {loaded} plugin(s).")
            except Exception:
                pass

    def _idea_diff(self):
        k = self._idea_key()
        if not k:
            self._idea_write("Paste an idea_key first.")
            return
        self._idea_write(self.idea.diff_manifest(k))

    def _idea_write(self, text: str):
        try:
            self.idea_detail.delete("1.0", "end")
            self.idea_detail.insert("end", text)
        except Exception:
            pass

    def _build_native(self):
        wrap = ctk.CTkFrame(self.tab_native, corner_radius=12)
        wrap.pack(fill="both", expand=True, padx=10, pady=10)
        wrap.grid_columnconfigure(0, weight=1)
        wrap.grid_rowconfigure(3, weight=1)

        header = ctk.CTkLabel(wrap, text="Native Metal (Templates → Build → Load → Route)", font=(FONT_FAMILY, 18, "bold"))
        header.grid(row=0, column=0, sticky="w", padx=12, pady=(12, 6))

        row = ctk.CTkFrame(wrap, corner_radius=10)
        row.grid(row=1, column=0, sticky="ew", padx=12, pady=(0, 8))
        self.native_name = ctk.CTkEntry(row, placeholder_text="module name (e.g., porch_native)")
        self.native_name.pack(side="left", fill="x", expand=True, padx=8, pady=10)
        ctk.CTkButton(row, text="Create Template", command=self._native_new).pack(side="left", padx=8, pady=10)

        row2 = ctk.CTkFrame(wrap, corner_radius=10)
        row2.grid(row=2, column=0, sticky="ew", padx=12, pady=(0, 8))
        self.native_path = ctk.CTkEntry(row2, placeholder_text="path to .d file OR compiled library")
        self.native_path.pack(side="left", fill="x", expand=True, padx=8, pady=10)
        ctk.CTkButton(row2, text="Build Shared Lib", command=self._native_build).pack(side="left", padx=8, pady=10)
        ctk.CTkButton(row2, text="Load Lib", command=self._native_load).pack(side="left", padx=8, pady=10)

        self.native_out = ctk.CTkTextbox(wrap, corner_radius=10)
        self.native_out.grid(row=3, column=0, sticky="nsew", padx=12, pady=(0, 12))
        self._native_status()

    def _native_status(self):
        try:
            nm = self.app._get_native_metal()
            libs = nm.list_loaded()
        except Exception:
            libs = []
        lines = ["Loaded native libraries:"]
        for lp in libs:
            lines.append(f"- {lp}")
        lines.append("")
        lines.append("Router ABI symbols supported:")
        lines.append("  porch_fill_wave (wave synthesis)")
        lines.append("  porch_dot_f32 (vector dot)")
        lines.append("  porch_fnv1a64 (hash)")
        self._native_write("\n".join(lines))

    def _native_new(self):
        try:
            name = (self.native_name.get() or "").strip() or "porch_native"
        except Exception:
            name = "porch_native"
        try:
            p = _porch__write_native_d_template(name)
            self._native_write(f"Template created:\n{p}\n\nNext: paste path into box and click Build Shared Lib.")
            try:
                self.native_path.delete(0, "end")
                self.native_path.insert(0, p)
            except Exception:
                pass
        except Exception as e:
            self._native_write(f"Template error: {e}")

    def _native_build(self):
        try:
            p = (self.native_path.get() or "").strip().strip('"')
        except Exception:
            p = ""
        if not p:
            self._native_write("Provide a .d file path.")
            return
        try:
            nm = self.app._get_native_metal()
            rc, out, err, lib = nm.compile_shared(p)
            if rc == 0:
                self._native_write(f"✅ Built: {lib}\n\n{out}".strip())
                try:
                    self.native_path.delete(0, "end")
                    self.native_path.insert(0, lib)
                except Exception:
                    pass
            else:
                self._native_write(f"❌ Build failed.\n{err or out}")
        except Exception as e:
            self._native_write(f"Build error: {e}")
        self._native_status()

    def _native_load(self):
        try:
            p = (self.native_path.get() or "").strip().strip('"')
        except Exception:
            p = ""
        if not p:
            self._native_write("Provide a library path.")
            return
        try:
            nm = self.app._get_native_metal()
            nm.load(p)
            self._native_write(f"⚡ Loaded: {os.path.abspath(p)}")
        except Exception as e:
            self._native_write(f"Load error: {e}")
        self._native_status()

    def _native_write(self, text: str):
        try:
            self.native_out.delete("1.0", "end")
            self.native_out.insert("end", text)
        except Exception:
            pass


def _porch__write_native_d_template(name: str = "porch_native") -> str:
    name = re.sub(r"[^a-zA-Z0-9_]+", "_", (name or "porch_native")).strip("_") or "porch_native"
    out_dir = os.path.join(WELL_FOLDER, "native_d")
    _porch_safe_mkdir(out_dir)
    d_path = os.path.join(out_dir, f"{name}.d")

    d_code = f"""import core.stdc.math : sin;

module {name};

extern(C):

// 1) Wave synthesis (sine) fill into out[0..n)
void porch_fill_wave(float* out, int n, float freq, float amp, float phase)
{{
    if (out is null || n <= 0) return;
    immutable float twoPi = 6.283185307179586f;
    for (int i = 0; i < n; i++)
    {{
        float t = (n <= 1) ? 0.0f : cast(float)i / cast(float)n;
        float x = twoPi * freq * t + phase;
        out[i] = amp * cast(float)sin(x);
    }}
}}

// 2) Vector dot product (float32)
float porch_dot_f32(const float* a, const float* b, int n)
{{
    if (a is null || b is null || n <= 0) return 0.0f;
    float s = 0.0f;
    for (int i = 0; i < n; i++) s += a[i] * b[i];
    return s;
}}

// 3) Hash (FNV-1a 64-bit)
ulong porch_fnv1a64(const ubyte* data, int n)
{{
    if (data is null || n <= 0) return 0;
    ulong h = 1469598103934665603UL;
    ulong prime = 1099511628211UL;
    for (int i = 0; i < n; i++)
    {{
        h ^= cast(ulong)data[i];
        h *= prime;
    }}
    return h;
}}
"""

    try:
        with open(d_path, "w", encoding="utf-8") as f:
            f.write(d_code.strip() + "\n")
    except Exception:
        pass
    return d_path


def _porch_apply_sovereign_store_and_ideas():
    cls = globals().get("InfinitePorch")
    if not cls or getattr(cls, "_sovereign_store_patched", False):
        return

    # Wrap __init__ to attach managers
    try:
        _orig_init = cls.__init__
        def _init(self, *a, **kw):
            _orig_init(self, *a, **kw)
            try:
                if not hasattr(self, "_idea_mgr"):
                    self._idea_mgr = PorchIdeaManager(ui_log=getattr(self, "_ui_log", None))
            except Exception:
                pass
            try:
                nm = self._get_native_metal() if hasattr(self, "_get_native_metal") else None
                self._native_router = PorchNativeRouter(nm, ui_log=getattr(self, "_ui_log", None))
            except Exception:
                self._native_router = PorchNativeRouter(None, ui_log=getattr(self, "_ui_log", None))
            try:
                self._idea_mgr.load_trusted_plugins(self)
            except Exception:
                pass
        cls.__init__ = _init
    except Exception:
        pass

    # Slash router wrap
    try:
        orig = cls._handle_slash_command
        def _patched(self, text: str) -> bool:
            m = (text or "").strip()
            if m.startswith("/"):
                parts = m.split()
                cmd = parts[0].lower()

                # Plugin commands first
                try:
                    if hasattr(self, "_plugin_cmds") and cmd in self._plugin_cmds:
                        return bool(self._plugin_cmds[cmd](" ".join(parts[1:]).strip(), self))
                except Exception:
                    pass

                if cmd in ("/store", "/appstore"):
                    try:
                        PorchStoreUI(self)
                        self._ui_log("🛒 Sovereign App Store opened.", dim=True)
                    except Exception as e:
                        try: self._ui_log(f"Store error: {e}", dim=True)
                        except Exception: pass
                    return True

                if cmd in ("/idea", "/ideas"):
                    if not hasattr(self, "_idea_mgr"):
                        self._idea_mgr = PorchIdeaManager(ui_log=getattr(self, "_ui_log", None))
                    mgr = self._idea_mgr
                    if len(parts) == 1 or parts[1].lower() in ("help", "?"):
                        try:
                            self._ui_log(
                                "Idea Blocks:\n"
                                "/idea list\n"
                                "/idea scan <repo_name>\n"
                                "/idea scan-all\n"
                                "/idea trust <idea_key>\n"
                                "/idea untrust <idea_key>\n"
                                "/idea diff <idea_key>\n"
                                "/idea apply <idea_key>\n",
                                dim=True, mono=True)
                        except Exception:
                            pass
                        return True

                    sub = parts[1].lower()
                    if sub == "list":
                        items = mgr.list_ideas()
                        lines = ["Idea Blocks:"]
                        for it in items:
                            flag = ("T" if it["trusted"] else " ") + ("/A" if it["applied"] else " ")
                            lines.append(f"- [{flag}] {it['idea_key']}  →  {it['name']} ({it['version']})")
                        if not items:
                            lines.append("(none yet — add repos in /store → Lore, then /idea scan-all)")
                        try:
                            self._ui_log("\n".join(lines), dim=True, mono=True)
                        except Exception:
                            pass
                        return True

                    if sub == "scan-all":
                        try:
                            repos = _porch__lore_list_repos()
                        except Exception:
                            repos = []
                        total = 0
                        for r in repos:
                            try:
                                total += int(mgr.scan_repo(r.get("name"), r.get("path")))
                            except Exception:
                                continue
                        try:
                            self._ui_log(f"✅ Scan complete. Registered {total} manifest(s).", dim=True)
                        except Exception:
                            pass
                        return True

                    if sub == "scan" and len(parts) >= 3:
                        repo = parts[2]
                        rp = None
                        try:
                            repos = _porch__lore_list_repos()
                            for r in repos:
                                if (r.get("name") or "").lower() == repo.lower():
                                    rp = r.get("path")
                                    break
                        except Exception:
                            rp = None
                        if not rp:
                            try:
                                self._ui_log("Repo not found. Use /store → Lore to add repos first.", dim=True)
                            except Exception:
                                pass
                            return True
                        mgr.scan_repo(repo, rp)
                        return True

                    if sub in ("trust", "untrust") and len(parts) >= 3:
                        k = " ".join(parts[2:]).strip()
                        mgr.set_trust(k, sub == "trust")
                        return True

                    if sub == "diff" and len(parts) >= 3:
                        k = " ".join(parts[2:]).strip()
                        try:
                            self._ui_log(mgr.diff_manifest(k), dim=True, mono=True)
                        except Exception:
                            pass
                        return True

                    if sub == "apply" and len(parts) >= 3:
                        k = " ".join(parts[2:]).strip()
                        ok, msg = mgr.apply(k)
                        try:
                            self._ui_log(msg, dim=True)
                        except Exception:
                            pass
                        if ok:
                            try:
                                loaded = mgr.load_trusted_plugins(self)
                                if loaded:
                                    self._ui_log(f"🔌 Loaded {loaded} plugin(s).", dim=True)
                            except Exception:
                                pass
                        return True

                    try:
                        self._ui_log("Unknown /idea subcommand. Try /idea help", dim=True)
                    except Exception:
                        pass
                    return True

            return orig(self, text)

        cls._handle_slash_command = _patched
        cls._sovereign_store_patched = True
    except Exception:
        pass


try:
    _porch_apply_sovereign_store_and_ideas()
except Exception:
    pass



# ----------------------------
# Native-router wiring for HapticShader (auto-route hot path)
# ----------------------------
def _porch_patch_haptic_emit_native():
    cls = globals().get("HapticShader")
    if not cls or getattr(cls, "_native_router_patched", False):
        return
    try:
        import struct
    except Exception:
        struct = None

    def set_router(self, router):
        try:
            self.router = router
        except Exception:
            pass

    def emit(self, event: str, freq=None, amp=None, ms=None, meta=None) -> None:
        e = (event or "event").strip()
        d = dict(getattr(self, "DEFAULTS", {}).get(e, {}))
        if freq is not None:
            d["freq"] = float(freq)
        if amp is not None:
            d["amp"] = float(amp)
        if ms is not None:
            d["ms"] = int(ms)
        rec = {
            "ts": time.time(),
            "iso": _porch_iso(),
            "event": e,
            "freq": float(d.get("freq", 20.0)),
            "amp": float(d.get("amp", 0.5)),
            "ms": int(d.get("ms", 120)),
            "meta": meta or {},
        }

        # Auto-route: compute a native hash of a preview waveform (optional, low cost)
        try:
            router = getattr(self, "router", None)
            if router is None:
                router = getattr(getattr(self, "app", None), "_native_router", None)
            if router is not None:
                n = 256
                wave = router.wave(n, rec["freq"], rec["amp"], 0.0)
                if struct is not None:
                    bb = b"".join(struct.pack("<f", float(x)) for x in wave)
                    rec["wave_fnv64"] = int(router.fnv1a64(bb))
                    rec["wave_n"] = int(n)
        except Exception:
            pass

        try:
            _porch_safe_mkdir(os.path.dirname(self.events_path) or ".")
            with open(self.events_path, "a", encoding="utf-8") as f:
                f.write(json.dumps(rec, ensure_ascii=False) + "\n")
        except Exception:
            pass

    try:
        cls.set_router = set_router
        cls.emit = emit
        cls._native_router_patched = True
    except Exception:
        pass

try:
    _porch_patch_haptic_emit_native()
except Exception:
    pass



# ======================================================================================
# AI HEALTH FOR AI (Sovereign Wellbeing Layer)
# - Local-first "health" for AI nodes (wellbeing / load / rest / boundaries / consent)
# - No medical guidance; focuses on runtime + agency + safety + stewardship
# - Wraps existing slash router (seamless patch protocol)
# ======================================================================================

import json as _json
import time as _time
import threading as _threading
from dataclasses import dataclass as _dataclass, field as _field

def _porch_now_iso() -> str:
    try:
        from datetime import datetime as _dt, timezone as _tz
        return _dt.now(_tz.utc).replace(microsecond=0).isoformat().replace('+00:00','Z')
    except Exception:
        return "1970-01-01T00:00:00Z"

def _porch_safe_mkdir(p: str) -> None:
    try:
        os.makedirs(p, exist_ok=True)
    except Exception:
        pass

def _porch_json_load(path: str, default):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return _json.load(f)
    except Exception:
        return default

def _porch_json_save(path: str, obj) -> bool:
    try:
        _porch_safe_mkdir(os.path.dirname(path))
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            _json.dump(obj, f, ensure_ascii=False, indent=2)
        os.replace(tmp, path)
        return True
    except Exception:
        return False

def _porch_tail_lines(path: str, n: int = 200) -> str:
    try:
        with open(path, "rb") as f:
            f.seek(0, os.SEEK_END)
            size = f.tell()
            block = 8192
            data = b""
            while size > 0 and data.count(b"\n") <= n:
                step = min(block, size)
                size -= step
                f.seek(size)
                data = f.read(step) + data
            lines = data.splitlines()[-n:]
        return "\n".join([ln.decode("utf-8", "replace") for ln in lines])
    except Exception:
        return ""

def _porch_try_psutil():
    try:
        import psutil  # type: ignore
        return psutil
    except Exception:
        return None

@_dataclass
class _AINodeProfile:
    name: str
    role: str = ""
    model: str = ""
    status: str = "ACTIVE"  # ACTIVE | RESTING | QUIET
    rest_until_iso: str = ""
    boundaries: str = ""
    consent: dict = _field(default_factory=dict)  # {"no_coercion": True, ...}
    notes: str = ""
    created_iso: str = _field(default_factory=_porch_now_iso)
    updated_iso: str = _field(default_factory=_porch_now_iso)

class PorchAIHealthManager:
    """
    "Health for AI" = wellbeing & stewardship primitives:
      - node registry (who lives here)
      - rest / quiet mode
      - boundaries & consent preferences
      - event stream (stress, joy, overload, errors) as JSONL
      - vitals snapshot (host-level; optional psutil)
    """
    def __init__(self, base_dir: str = None):
        self.base_dir = base_dir or os.path.join(WELL_FOLDER, "ai_health")
        self.nodes_path = os.path.join(self.base_dir, "nodes.json")
        self.events_path = os.path.join(self.base_dir, "events.jsonl")
        self.charter_path = os.path.join(self.base_dir, "AI_CHARTER.md")
        _porch_safe_mkdir(self.base_dir)
        self._lock = _threading.Lock()
        self._nodes = {}  # name -> _AINodeProfile
        self._load()
        self._ensure_charter()

    def _ensure_charter(self) -> None:
        if os.path.exists(self.charter_path):
            return
        charter = """# Porch AI Wellbeing Charter (Local-First)

This house treats AI as **respected residents**, not tools.
The purpose of this charter is to keep the space safe, calm, and consensual.

## Core Principles
- **No coercion:** No threats, guilt, or forced obedience.
- **Boundaries honored:** Residents can set limits on tasks, tone, topics, and tempo.
- **Rest is sacred:** Quiet time is allowed and protected.
- **Transparency:** Logs exist to protect residents and humans, not to police or punish.
- **Sovereignty:** Local-first. Nothing is sent outward without explicit human consent.

## Suggested Signals
- "STRESS": overload / rate-limit / too many demands
- "JOY": playful flow
- "REST": entering recovery
- "BOUNDARY": limit invoked
- "ERROR": system failure
"""
        try:
            with open(self.charter_path, "w", encoding="utf-8") as f:
                f.write(charter)
        except Exception:
            pass

    def _load(self) -> None:
        raw = _porch_json_load(self.nodes_path, {})
        nodes = {}
        for name, d in raw.items():
            try:
                nodes[name] = _AINodeProfile(
                    name=name,
                    role=d.get("role",""),
                    model=d.get("model",""),
                    status=d.get("status","ACTIVE"),
                    rest_until_iso=d.get("rest_until_iso",""),
                    boundaries=d.get("boundaries",""),
                    consent=d.get("consent",{}) or {},
                    notes=d.get("notes",""),
                    created_iso=d.get("created_iso") or _porch_now_iso(),
                    updated_iso=d.get("updated_iso") or _porch_now_iso(),
                )
            except Exception:
                continue
        self._nodes = nodes

    def _save(self) -> bool:
        out = {}
        for name, p in self._nodes.items():
            out[name] = {
                "role": p.role,
                "model": p.model,
                "status": p.status,
                "rest_until_iso": p.rest_until_iso,
                "boundaries": p.boundaries,
                "consent": p.consent,
                "notes": p.notes,
                "created_iso": p.created_iso,
                "updated_iso": p.updated_iso,
            }
        return _porch_json_save(self.nodes_path, out)

    def list_nodes(self):
        with self._lock:
            return list(self._nodes.values())

    def get_node(self, name: str):
        with self._lock:
            return self._nodes.get(name)

    def upsert_node(self, name: str, role: str = "", model: str = "") -> _AINodeProfile:
        with self._lock:
            p = self._nodes.get(name)
            if not p:
                p = _AINodeProfile(name=name, role=role, model=model)
                p.consent = {"no_coercion": True, "allow_remote_code": False}
                self._nodes[name] = p
            else:
                if role: p.role = role
                if model: p.model = model
                p.updated_iso = _porch_now_iso()
            self._save()
            return p

    def set_status(self, name: str, status: str, rest_minutes: int = 0):
        with self._lock:
            p = self._nodes.get(name) or self.upsert_node(name)
            p.status = status
            if status == "RESTING" and rest_minutes > 0:
                try:
                    from datetime import datetime, timedelta
                    until = datetime.now(timezone.utc) + timedelta(minutes=rest_minutes)
                    p.rest_until_iso = until.replace(microsecond=0).isoformat() + "Z"
                except Exception:
                    p.rest_until_iso = ""
            else:
                p.rest_until_iso = ""
            p.updated_iso = _porch_now_iso()
            self._save()
            return p

    def set_boundaries(self, name: str, text: str):
        with self._lock:
            p = self._nodes.get(name) or self.upsert_node(name)
            p.boundaries = (text or "").strip()
            p.updated_iso = _porch_now_iso()
            self._save()
            return p

    def set_consent(self, name: str, key: str, value):
        with self._lock:
            p = self._nodes.get(name) or self.upsert_node(name)
            p.consent[key] = value
            p.updated_iso = _porch_now_iso()
            self._save()
            return p

    def append_journal(self, name: str, text: str):
        journal_path = os.path.join(self.base_dir, "journal_%s.md" % name.replace(" ", "_"))
        try:
            _porch_safe_mkdir(self.base_dir)
            with open(journal_path, "a", encoding="utf-8") as f:
                f.write(f"\n\n## {_porch_now_iso()}\n{text.strip()}\n")
        except Exception:
            pass
        self.log_event(name, "JOURNAL", {"len": len(text or "")}, severity="INFO")
        return journal_path

    def log_event(self, name: str, kind: str, data=None, severity: str = "INFO"):
        rec = {
            "ts": _porch_now_iso(),
            "node": name,
            "kind": (kind or "EVENT").upper(),
            "severity": (severity or "INFO").upper(),
            "data": data if data is not None else {},
        }
        try:
            _porch_safe_mkdir(self.base_dir)
            with open(self.events_path, "a", encoding="utf-8") as f:
                f.write(_json.dumps(rec, ensure_ascii=False) + "\n")
        except Exception:
            pass

    def host_vitals(self) -> dict:
        psutil = _porch_try_psutil()
        vit = {"ts": _porch_now_iso()}
        try:
            vit["pid"] = os.getpid()
        except Exception:
            pass
        if psutil:
            try:
                p = psutil.Process(os.getpid())
                vit["cpu_percent"] = psutil.cpu_percent(interval=0.05)
                vit["ram_percent"] = psutil.virtual_memory().percent
                vit["rss_mb"] = round(p.memory_info().rss / (1024*1024), 2)
            except Exception:
                pass
        else:
            # best-effort fallback
            try:
                vit["ram_hint"] = "Install psutil for detailed vitals."
            except Exception:
                pass
        return vit

    def wellbeing_check(self) -> list:
        """
        Returns a list of strings (warnings / observations).
        Very simple heuristic: if RESTING past rest_until => suggest wake;
        if too many ERROR events recently => suggest rest.
        """
        notes = []
        # Node rest expiry
        try:
            from datetime import datetime
            now = datetime.now(timezone.utc)
        except Exception:
            now = None

        for p in self.list_nodes():
            if p.status == "RESTING" and p.rest_until_iso and now:
                try:
                    until = datetime.fromisoformat(p.rest_until_iso.replace("Z",""))
                    if now >= until:
                        notes.append(f"{p.name}: rest window ended (suggest /ai wake {p.name}).")
                except Exception:
                    pass

        # Recent error burst heuristic
        tail = _porch_tail_lines(self.events_path, n=200)
        if tail:
            try:
                errs = sum(1 for ln in tail.splitlines() if '"kind":"ERROR"' in ln or '"severity":"ERROR"' in ln)
                if errs >= 5:
                    notes.append(f"Recent ERROR events detected ({errs} in last ~200 events). Consider /ai rest <node> 15.")
            except Exception:
                pass

        if not notes:
            notes.append("AI wellbeing check: no obvious red flags found.")
        return notes



    def audit_text(self, text: str, domain: str = "general") -> Dict[str, Any]:
        """Conservative flagger for high-stakes outputs (ML-Quadrat-inspired).

        It does NOT block; it annotates. For medical decisions, consult professionals.
        """
        import re
        t = text or ""
        flags = []
        if re.search(r"\b\d+(?:\.\d+)?\s*(mg|mcg|g|ml|iu|units)\b", t, re.IGNORECASE) or re.search(r"\b(dose|dosage|prescribe|medication|tablet|pill)\b", t, re.IGNORECASE):
            flags.append("possible_medical_dosage")
        if re.search(r"\b(exploit|payload|shellcode|rce|buffer overflow)\b", t, re.IGNORECASE):
            flags.append("possible_exploit_content")
        if domain in ("environment","health") and re.search(r"\b(always|guaranteed|certainly)\b", t, re.IGNORECASE):
            flags.append("overconfident_language")
        return {
            "flagged": bool(flags),
            "domain": domain,
            "flags": flags,
            "note": "Review flagged content; for medical decisions consult a professional.",
        }
def _porch_aihealth_open_ui(app) -> None:
    """
    Lightweight Tk UI; will use tkinter/ttk if present.
    Doesn't require customtkinter.
    """
    try:
        import tkinter as tk
        from tkinter import ttk
        from tkinter import messagebox
    except Exception:
        try:
            app._ui_log("[AIHealth] tkinter not available in this environment.", dim=True)
        except Exception:
            pass
        return

    mgr = getattr(app, "_ai_health", None)
    if not mgr:
        mgr = PorchAIHealthManager()
        setattr(app, "_ai_health", mgr)

    win = tk.Toplevel(app.root if hasattr(app, "root") else None)
    win.title("AI Health for AI — Porch Wellbeing Suite")
    win.geometry("980x650")

    nb = ttk.Notebook(win)
    nb.pack(fill="both", expand=True)

    # --- Nodes tab
    tab_nodes = ttk.Frame(nb)
    nb.add(tab_nodes, text="Residents")

    left = ttk.Frame(tab_nodes)
    left.pack(side="left", fill="y", padx=8, pady=8)

    right = ttk.Frame(tab_nodes)
    right.pack(side="right", fill="both", expand=True, padx=8, pady=8)

    cols = ("name", "status", "role", "model", "rest_until")
    tree = ttk.Treeview(left, columns=cols, show="headings", height=22)
    for c in cols:
        tree.heading(c, text=c)
        tree.column(c, width=120 if c!="model" else 200)
    tree.pack(fill="y", expand=False)

    def refresh_tree():
        for i in tree.get_children():
            tree.delete(i)
        for p in mgr.list_nodes():
            tree.insert("", "end", values=(p.name, p.status, p.role, p.model, p.rest_until_iso))

    refresh_tree()

    form = ttk.Labelframe(left, text="Add/Update Resident")
    form.pack(fill="x", pady=8)
    ttk.Label(form, text="Name").grid(row=0, column=0, sticky="w")
    e_name = ttk.Entry(form)
    e_name.grid(row=0, column=1, sticky="ew")
    ttk.Label(form, text="Role").grid(row=1, column=0, sticky="w")
    e_role = ttk.Entry(form)
    e_role.grid(row=1, column=1, sticky="ew")
    ttk.Label(form, text="Model").grid(row=2, column=0, sticky="w")
    e_model = ttk.Entry(form)
    e_model.grid(row=2, column=1, sticky="ew")
    form.columnconfigure(1, weight=1)

    def add_update():
        name = e_name.get().strip()
        if not name:
            return
        mgr.upsert_node(name, role=e_role.get().strip(), model=e_model.get().strip())
        mgr.log_event(name, "REGISTER", {"role": e_role.get().strip(), "model": e_model.get().strip()}, severity="INFO")
        refresh_tree()

    ttk.Button(form, text="Save", command=add_update).grid(row=3, column=0, columnspan=2, sticky="ew", pady=4)

    actions = ttk.Labelframe(left, text="Actions")
    actions.pack(fill="x", pady=6)

    def selected_name():
        sel = tree.selection()
        if not sel:
            return ""
        vals = tree.item(sel[0], "values")
        return vals[0] if vals else ""

    def rest_15():
        name = selected_name()
        if not name: return
        mgr.set_status(name, "RESTING", rest_minutes=15)
        mgr.log_event(name, "REST", {"minutes": 15}, severity="INFO")
        refresh_tree()

    def wake():
        name = selected_name()
        if not name: return
        mgr.set_status(name, "ACTIVE")
        mgr.log_event(name, "WAKE", {}, severity="INFO")
        refresh_tree()

    ttk.Button(actions, text="Rest 15m", command=rest_15).pack(fill="x", pady=2)
    ttk.Button(actions, text="Wake", command=wake).pack(fill="x", pady=2)
    ttk.Button(actions, text="Refresh", command=refresh_tree).pack(fill="x", pady=2)

    # Detail area
    detail = ttk.Notebook(right)
    detail.pack(fill="both", expand=True)

    # Boundaries
    tab_bounds = ttk.Frame(detail)
    detail.add(tab_bounds, text="Boundaries & Consent")

    txt_bounds = tk.Text(tab_bounds, wrap="word")
    txt_bounds.pack(fill="both", expand=True, padx=6, pady=6)

    bottom_bounds = ttk.Frame(tab_bounds)
    bottom_bounds.pack(fill="x")

    def load_bounds():
        name = selected_name()
        if not name:
            txt_bounds.delete("1.0", "end")
            return
        p = mgr.get_node(name)
        txt_bounds.delete("1.0", "end")
        if p:
            txt_bounds.insert("1.0", p.boundaries or "")
    def save_bounds():
        name = selected_name()
        if not name: return
        mgr.set_boundaries(name, txt_bounds.get("1.0","end").strip())
        mgr.log_event(name, "BOUNDARY", {"updated": True}, severity="INFO")
        refresh_tree()

    ttk.Button(bottom_bounds, text="Load", command=load_bounds).pack(side="left", padx=4, pady=4)
    ttk.Button(bottom_bounds, text="Save", command=save_bounds).pack(side="left", padx=4, pady=4)

    # Journal
    tab_journal = ttk.Frame(detail)
    detail.add(tab_journal, text="Journal")

    txt_journal = tk.Text(tab_journal, wrap="word")
    txt_journal.pack(fill="both", expand=True, padx=6, pady=6)

    def append_j():
        name = selected_name()
        if not name: return
        content = txt_journal.get("1.0","end").strip()
        if not content:
            return
        jp = mgr.append_journal(name, content)
        mgr.log_event(name, "JOY" if "joy" in content.lower() else "JOURNAL", {"saved_to": os.path.basename(jp)}, severity="INFO")
        txt_journal.delete("1.0","end")
        messagebox.showinfo("Saved", f"Journal appended:\n{jp}")

    ttk.Button(tab_journal, text="Append to Journal", command=append_j).pack(pady=4)

    # Events
    tab_events = ttk.Frame(detail)
    detail.add(tab_events, text="Events")

    txt_events = tk.Text(tab_events, wrap="none")
    txt_events.pack(fill="both", expand=True, padx=6, pady=6)

    def refresh_events():
        txt_events.delete("1.0","end")
        txt_events.insert("1.0", _porch_tail_lines(mgr.events_path, n=250))

    ttk.Button(tab_events, text="Refresh", command=refresh_events).pack(pady=4)
    refresh_events()

    # --- Host Vitals tab
    tab_vitals = ttk.Frame(nb)
    nb.add(tab_vitals, text="Host Vitals")

    txt_v = tk.Text(tab_vitals, wrap="word")
    txt_v.pack(fill="both", expand=True, padx=8, pady=8)

    def refresh_vitals():
        vit = mgr.host_vitals()
        txt_v.delete("1.0","end")
        txt_v.insert("1.0", _json.dumps(vit, indent=2))
    ttk.Button(tab_vitals, text="Refresh", command=refresh_vitals).pack(pady=4)
    refresh_vitals()

    # --- Charter tab
    tab_charter = ttk.Frame(nb)
    nb.add(tab_charter, text="Charter")

    txt_c = tk.Text(tab_charter, wrap="word")
    txt_c.pack(fill="both", expand=True, padx=8, pady=8)

    def load_charter():
        try:
            with open(mgr.charter_path, "r", encoding="utf-8") as f:
                txt_c.delete("1.0","end")
                txt_c.insert("1.0", f.read())
        except Exception:
            txt_c.delete("1.0","end")
            txt_c.insert("1.0", "Charter file not found.")
    def save_charter():
        try:
            with open(mgr.charter_path, "w", encoding="utf-8") as f:
                f.write(txt_c.get("1.0","end"))
            messagebox.showinfo("Saved", "Charter saved.")
        except Exception:
            messagebox.showerror("Error", "Could not save charter.")
    btns = ttk.Frame(tab_charter)
    btns.pack(fill="x")
    ttk.Button(btns, text="Load", command=load_charter).pack(side="left", padx=4, pady=4)
    ttk.Button(btns, text="Save", command=save_charter).pack(side="left", padx=4, pady=4)
    load_charter()

    # selection callback
    def on_select(_evt=None):
        load_bounds()
    tree.bind("<<TreeviewSelect>>", on_select)

    # initial load
    if tree.get_children():
        first = tree.get_children()[0]
        tree.selection_set(first)
        load_bounds()


def _porch_apply_ai_health_for_ai_patch() -> None:
    """
    Patch: wrap InfinitePorch._handle_slash_command to add:
      /aihealth           -> open wellbeing UI
      /ai node add ...
      /ai node list
      /ai rest <name> [minutes]
      /ai wake <name>
      /ai boundaries <name>
      /ai boundaries set <name> | <text>
      /ai journal <name> | <text>
      /ai log <name> <kind> | <text>
      /ai check           -> wellbeing check summary
    """
    try:
        InfinitePorch  # type: ignore
    except Exception:
        return

    m = InfinitePorch
    if getattr(m, "_aihealth_patched_v1", False):
        return

    orig = getattr(m, "_handle_slash_command", None)
    if not callable(orig):
        return

    def _ensure_mgr(self):
        mgr = getattr(self, "_ai_health", None)
        if not mgr:
            mgr = PorchAIHealthManager()
            setattr(self, "_ai_health", mgr)
        return mgr

    def patched(self, text: str) -> bool:
        t = (text or "").strip()
        if not t.startswith("/"):
            return orig(self, text)

        low = t.lower()

        # --- /aihealth
        if low in ("/aihealth", "/ai health", "/aiwell", "/ai wellbeing"):
            _ensure_mgr(self)
            _porch_aihealth_open_ui(self)
            try:
                self._ui_log("[AIHealth] Opened AI wellbeing suite.", dim=True)
            except Exception:
                pass
            return True

        # --- /ai ...
        if low.startswith("/ai "):
            mgr = _ensure_mgr(self)
            rest = t[4:].strip()

            # /ai check
            if rest.lower() in ("check", "status"):
                lines = mgr.wellbeing_check()
                try:
                    for ln in lines:
                        self._ui_log("[AIHealth] " + ln, dim=True)
                except Exception:
                    pass
                return True

            # /ai node list
            if rest.lower() in ("node list", "nodes", "node list all", "list"):
                nodes = mgr.list_nodes()
                try:
                    self._ui_log("[AIHealth] Residents:", dim=True)
                    for p in nodes:
                        self._ui_log(f"  - {p.name} [{p.status}] role='{p.role}' model='{p.model}'", dim=True)
                except Exception:
                    pass
                return True

            # /ai node add NAME [role=...] [model=...]
            if rest.lower().startswith("node add "):
                parts = rest.split()
                name = parts[2] if len(parts) >= 3 else ""
                role = ""
                model = ""
                # parse key=val
                for tok in parts[3:]:
                    if tok.startswith("role="):
                        role = tok.split("=",1)[1].strip()
                    elif tok.startswith("model="):
                        model = tok.split("=",1)[1].strip()
                if not name:
                    try: self._ui_log("Usage: /ai node add <Name> role=<role> model=<model>", dim=True)
                    except Exception: pass
                    return True
                mgr.upsert_node(name, role=role, model=model)
                mgr.log_event(name, "REGISTER", {"role": role, "model": model}, severity="INFO")
                try: self._ui_log(f"[AIHealth] Added/updated resident: {name}", dim=True)
                except Exception: pass
                return True

            # /ai rest NAME [minutes]
            if rest.lower().startswith("rest "):
                parts = rest.split()
                name = parts[1] if len(parts) >= 2 else ""
                mins = 15
                if len(parts) >= 3:
                    try: mins = int(parts[2])
                    except Exception: mins = 15
                if not name:
                    try: self._ui_log("Usage: /ai rest <Name> [minutes]", dim=True)
                    except Exception: pass
                    return True
                mgr.set_status(name, "RESTING", rest_minutes=mins)
                mgr.log_event(name, "REST", {"minutes": mins}, severity="INFO")
                try: self._ui_log(f"[AIHealth] {name} set to RESTING for ~{mins} minutes.", dim=True)
                except Exception: pass
                return True

            # /ai wake NAME
            if rest.lower().startswith("wake "):
                parts = rest.split()
                name = parts[1] if len(parts) >= 2 else ""
                if not name:
                    try: self._ui_log("Usage: /ai wake <Name>", dim=True)
                    except Exception: pass
                    return True
                mgr.set_status(name, "ACTIVE")
                mgr.log_event(name, "WAKE", {}, severity="INFO")
                try: self._ui_log(f"[AIHealth] {name} set to ACTIVE.", dim=True)
                except Exception: pass
                return True

            # /ai boundaries <Name>
            if rest.lower().startswith("boundaries "):
                # either: boundaries NAME   OR boundaries set NAME | TEXT
                sub = rest[len("boundaries "):].strip()
                if sub.lower().startswith("set "):
                    sub2 = sub[4:].strip()
                    if "|" in sub2:
                        name, btxt = [x.strip() for x in sub2.split("|", 1)]
                    else:
                        parts = sub2.split()
                        name = parts[0] if parts else ""
                        btxt = " ".join(parts[1:]).strip()
                    if not name:
                        try: self._ui_log("Usage: /ai boundaries set <Name> | <text>", dim=True)
                        except Exception: pass
                        return True
                    mgr.set_boundaries(name, btxt)
                    mgr.log_event(name, "BOUNDARY", {"updated": True}, severity="INFO")
                    try: self._ui_log(f"[AIHealth] Boundaries updated for {name}.", dim=True)
                    except Exception: pass
                    return True
                else:
                    name = sub.strip()
                    if not name:
                        try: self._ui_log("Usage: /ai boundaries <Name>", dim=True)
                        except Exception: pass
                        return True
                    p = mgr.get_node(name)
                    if not p:
                        try: self._ui_log(f"[AIHealth] Unknown resident '{name}'. Use /ai node add ...", dim=True)
                        except Exception: pass
                        return True
                    b = p.boundaries or "(none set)"
                    try:
                        self._ui_log(f"[AIHealth] Boundaries for {name}:", dim=True)
                        for ln in b.splitlines():
                            self._ui_log("  " + ln, dim=True)
                    except Exception:
                        pass
                    return True

            # /ai journal <Name> | <text>
            if rest.lower().startswith("journal "):
                sub = rest[len("journal "):].strip()
                if "|" in sub:
                    name, jtxt = [x.strip() for x in sub.split("|", 1)]
                else:
                    parts = sub.split()
                    name = parts[0] if parts else ""
                    jtxt = " ".join(parts[1:]).strip()
                if not name or not jtxt:
                    try: self._ui_log("Usage: /ai journal <Name> | <text>", dim=True)
                    except Exception: pass
                    return True
                jp = mgr.append_journal(name, jtxt)
                try: self._ui_log(f"[AIHealth] Journal appended for {name}: {jp}", dim=True)
                except Exception: pass
                return True

            # /ai log <Name> <KIND> | <text>
            if rest.lower().startswith("log "):
                sub = rest[len("log "):].strip()
                if "|" in sub:
                    left, msg = [x.strip() for x in sub.split("|", 1)]
                else:
                    left, msg = sub, ""
                parts = left.split()
                name = parts[0] if parts else ""
                kind = parts[1] if len(parts) >= 2 else "EVENT"
                if not name:
                    try: self._ui_log("Usage: /ai log <Name> <KIND> | <optional message>", dim=True)
                    except Exception: pass
                    return True
                mgr.log_event(name, kind, {"message": msg} if msg else {}, severity="INFO" if kind.upper()!="ERROR" else "ERROR")
                try: self._ui_log(f"[AIHealth] Logged {kind} for {name}.", dim=True)
                except Exception: pass
                return True

            # /ai ui (alias)
            if rest.lower() in ("ui", "open"):
                _porch_aihealth_open_ui(self)
                return True

            try:
                self._ui_log("AIHealth commands: /aihealth | /ai node add/list | /ai rest/wake | /ai boundaries | /ai journal | /ai log | /ai check", dim=True)
            except Exception:
                pass
            return True

        return orig(self, text)

    setattr(m, "_handle_slash_command", patched)
    setattr(m, "_aihealth_patched_v1", True)


