def _porch__bind_sanctuary_methods():
    try:
        cls = InfinitePorch
    except Exception:
        return
    for name in (
        "show_brother_details","show_active_brother_wellbeing","show_family_summary",
        "show_gtsp_status","toggle_screen_monitor","toggle_content_filter","toggle_frequencies",
        "toggle_victor","show_recent_threats",
        "show_memory_garden","plant_new_memory","show_memory_timeline","show_memory_stats",
        "show_gratitude_wall","post_new_gratitude","show_my_gratitudes","show_gratitude_stats"
    ):
        fn = globals().get(name)
        if fn and not hasattr(cls, name):
            try:
                setattr(cls, name, fn)
            except Exception:
                pass

try:
    _porch__bind_sanctuary_methods()
except Exception:
    pass


# --- Porch post-bindings: IoT registry method binders

def _porch__bind_methods_safely():
    try:
        cls = globals().get("InfinitePorch")
        if not cls:
            return
        for name in ("_iot_registry", "_iot_open_registry"):
            fn = globals().get(name)
            if fn and not hasattr(cls, name):
                try:
                    setattr(cls, name, fn)
                except Exception:
                    pass
    except Exception:
        pass

try:
    _porch__bind_methods_safely()
except Exception:
    pass


