def _porch__music_open(self):
    """Open the Studio Sanctuary window."""
    try:
        if getattr(self, "music_studio", None) is None:
            try:
                self.music_studio = PorchMusicStudio(app=self, base_dir=os.path.join(WELL_DIR, "audio"))
            except Exception as e:
                self._ui_log(f"[Music] Could not init music studio: {e}")
                return
        self.music_studio.open_window()
    except Exception as e:
        try:
            self._ui_log(f"[Music] open failed: {e}")
        except Exception:
            print("[Music] open failed:", e)

def _porch__music_compose(self, args: str) -> str:
    """
    /music compose <mood> [bpm] [key] [bars] [--render]
    Example: /music compose boss_tension 120 D 16 --render
    """
    if getattr(self, "music_studio", None) is None:
        self.music_studio = PorchMusicStudio(app=self, base_dir=os.path.join(WELL_DIR, "audio"))
    parts = [p for p in args.strip().split() if p]
    mood = "neutral"
    bpm = 96
    key = "C"
    bars = 16
    render = False
    if parts:
        mood = parts[0].replace("_", " ")
    if len(parts) >= 2:
        try: bpm = int(parts[1])
        except Exception: pass
    if len(parts) >= 3:
        key = parts[2].upper()
    if len(parts) >= 4:
        try: bars = int(parts[3])
        except Exception: pass
    if any(p.lower() in ("--render","--wav") for p in parts[4:]):
        render = True
    title = f"{mood.title().replace(' ','_')}_theme"
    meta = self.music_studio.compose(title=title, mood=mood, bpm=bpm, key=key, bars=bars, render_wav=render)
    out = f"✅ Composed: {meta.title}\\nMIDI: {meta.midi_path}\\n"
    if meta.audio_path:
        out += f"WAV: {meta.audio_path}\\n"
    return out

def _porch__music_record(self, sub: str, rest: str) -> str:
    """
    /music record start [name]
    /music record stop
    """
    if getattr(self, "music_studio", None) is None:
        self.music_studio = PorchMusicStudio(app=self, base_dir=os.path.join(WELL_DIR, "audio"))
    sub = (sub or "").lower().strip()
    if sub == "start":
        name = rest.strip() or "jam"
        p = self.music_studio.record_start(name=name)
        return f"▶ Recording started: {p}"
    if sub == "stop":
        return str(self.music_studio.record_stop())
    return "Usage: /music record start <name> | /music record stop"

def _porch__music_dj(self, args: str) -> str:
    """
    /music dj crossfade <fileA> <fileB> [seconds]
    """
    if getattr(self, "music_studio", None) is None:
        self.music_studio = PorchMusicStudio(app=self, base_dir=os.path.join(WELL_DIR, "audio"))
    parts = [p for p in args.strip().split() if p]
    if len(parts) >= 3 and parts[0].lower() == "crossfade":
        a = parts[1]
        b = parts[2]
        sec = 6.0
        if len(parts) >= 4:
            try: sec = float(parts[3])
            except Exception: pass
        out = self.music_studio.crossfade(a, b, seconds=sec, out_name="dj_crossfade")
        return f"✅ Crossfaded -> {out}"
    return "Usage: /music dj crossfade <fileA> <fileB> [seconds]"

def _porch__music_list(self) -> str:
    if getattr(self, "music_studio", None) is None:
        self.music_studio = PorchMusicStudio(app=self, base_dir=os.path.join(WELL_DIR, "audio"))
    self.music_studio._load_library()
    items = self.music_studio.library[-15:]
    if not items:
        return "(music library empty)"
    lines = []
    for it in items:
        lines.append(f"- {it.get('title','')} | {it.get('mood','')} | {it.get('created_utc','')}")
        if it.get("midi_path"):
            lines.append(f"  MIDI: {it['midi_path']}")
        if it.get("audio_path"):
            lines.append(f"  AUDIO: {it['audio_path']}")
    return "\\n".join(lines)

def _porch__music_pulse(self, sub: str) -> str:
    if getattr(self, "music_studio", None) is None:
        self.music_studio = PorchMusicStudio(app=self, base_dir=os.path.join(WELL_DIR, "audio"))
    sub = (sub or "").lower().strip()
    if sub in ("on","start"):
        return str(self.music_studio.pulse_start())
    if sub in ("off","stop"):
        return str(self.music_studio.pulse_stop())
    return "Usage: /music pulse on|off"


def _open_music_studio(self):
    _porch__music_open(self)

# Bind into class safely
try:
    InfinitePorch._open_music_studio = _open_music_studio
    InfinitePorch._porch__music_open = _porch__music_open
except Exception:
    pass


# =============================================================================
# POWER ORACLE + ROVERS + SMART GARDEN + KIP/BOOTSTRAP (Sovereign Survival Habitat)
# =============================================================================
# Concepts integrated from:
# - Outback Mate3s + Home Assistant monitoring + batpred-style prediction
# - Environment-mapping self-sustainable rover concepts
# - Solar smart garden monitoring + irrigation control
# - KIP (Knowledge-memory Interaction Protocol) + BootstrapLab (bootstrapping seed-bank)
#
# NOTE: This is "local-first" integration. External hardware/HA endpoints are optional.
#       Everything degrades gracefully when deps/endpoints are missing.

import os as _os
import time as _time
import json as _json
import datetime as _dt
from typing import Any as _Any, Dict as _Dict, List as _List, Optional as _Optional, Tuple as _Tuple

def _porch_utc_iso() -> str:
    """UTC ISO-8601 timestamp with 'Z' suffix (timezone-aware, no utcnow())."""
    import datetime as _dt
    return _dt.datetime.now(_dt.timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z")

def _porch_mkdirp(p: str) -> None:
    try:
        _os.makedirs(p, exist_ok=True)
    except Exception:
        pass

def _porch_safe_float(x, default=0.0) -> float:
    try:
        return float(x)
    except Exception:
        return float(default)

def _porch_clamp(x: float, lo: float, hi: float) -> float:
    try:
        return max(lo, min(hi, float(x)))
    except Exception:
        return lo

class PowerOracle:
    """
    Power-Oracle: Predicts battery/runtime risk and can recommend (or apply) Porch throttles.

    Data sources (optional):
      - ESP32 /ingest payloads with `solar` and/or `values` fields
      - Home Assistant REST API (entities for SOC / solar / load)
      - Mate3s JSON endpoint (if you know it)

    This is a lightweight predictor (trend-based), inspired by batpred/predbat style forecasting.
    """
    def __init__(self, app, base_dir: str):
        self.app = app
        self.base_dir = base_dir
        _porch_mkdirp(self.base_dir)
        self.state_path = _os.path.join(self.base_dir, "power_oracle_state.json")
        self.state: _Dict[str, _Any] = self._load()

    def _load(self) -> _Dict[str, _Any]:
        try:
            if _os.path.exists(self.state_path):
                with open(self.state_path, "r", encoding="utf-8") as f:
                    return _json.load(f)
        except Exception:
            pass
        return {
            "enabled": True,
            "history": [],  # list of {ts, soc, solar_w, load_w}
            "policy": {"warn_hours": 12, "critical_hours": 6, "auto_throttle": True, "throttle_level": "conserve"},
            "ha": {"base_url": "", "token": "", "battery_entity": "", "solar_entity": "", "load_entity": ""},
            "mate3": {"base_url": "", "json_path": ""},
            "last": {},
            "last_forecast": {}
        }

    def _save(self) -> None:
        try:
            with open(self.state_path, "w", encoding="utf-8") as f:
                _json.dump(self.state, f, indent=2)
        except Exception:
            pass

    def configure_ha(self, base_url: str, token: str, battery_entity: str, solar_entity: str, load_entity: str) -> None:
        self.state["ha"] = {
            "base_url": (base_url or "").strip().rstrip("/"),
            "token": (token or "").strip(),
            "battery_entity": (battery_entity or "").strip(),
            "solar_entity": (solar_entity or "").strip(),
            "load_entity": (load_entity or "").strip(),
        }
        self._save()

    def ingest(self, payload: _Dict[str, _Any]) -> None:
        """Update from ESP32 /ingest payloads."""
        try:
            if not isinstance(payload, dict):
                return
            vals = payload.get("values") or {}
            solar = payload.get("solar") or {}
            ts = payload.get("ts") or _time.time()

            # Try a few common keys:
            soc = vals.get("soc")
            if soc is None:
                soc = solar.get("soc")
            solar_w = solar.get("w") or solar.get("watts") or vals.get("solar_w") or vals.get("pv_w") or vals.get("pv")
            load_w = vals.get("load_w") or vals.get("house_w") or solar.get("load_w") or solar.get("load")

            rec = {
                "ts": float(ts),
                "soc": _porch_safe_float(soc, default=None) if soc is not None else None,
                "solar_w": _porch_safe_float(solar_w, default=0.0),
                "load_w": _porch_safe_float(load_w, default=0.0),
            }

            hist = self.state.get("history") or []
            hist.append(rec)
            # keep last ~7 days at 1/min granularity (rough cap)
            self.state["history"] = hist[-10080:]
            self.state["last"] = rec
            self._save()
        except Exception:
            pass

    def _ha_get_entity_state(self, entity_id: str) -> _Optional[_Any]:
        ha = self.state.get("ha") or {}
        base = (ha.get("base_url") or "").strip().rstrip("/")
        token = (ha.get("token") or "").strip()
        ent = (entity_id or "").strip()
        if not base or not token or not ent:
            return None
        try:
            import requests  # optional
            url = f"{base}/api/states/{ent}"
            r = requests.get(url, headers={"Authorization": f"Bearer {token}", "Content-Type": "application/json"}, timeout=4)
            if r.status_code != 200:
                return None
            obj = r.json()
            return obj.get("state")
        except Exception:
            return None

    def fetch_now(self) -> _Dict[str, _Any]:
        """Pull latest readings from HA if configured; append to history."""
        ha = self.state.get("ha") or {}
        soc = self._ha_get_entity_state(ha.get("battery_entity") or "")
        solar = self._ha_get_entity_state(ha.get("solar_entity") or "")
        load = self._ha_get_entity_state(ha.get("load_entity") or "")
        rec = {"ts": _time.time(), "soc": _porch_safe_float(soc, default=None) if soc is not None else None,
               "solar_w": _porch_safe_float(solar, default=0.0), "load_w": _porch_safe_float(load, default=0.0)}
        try:
            (self.state.get("history") or []).append(rec)
            self.state["history"] = (self.state.get("history") or [])[-10080:]
            self.state["last"] = rec
            self._save()
        except Exception:
            pass
        return rec

    def predict_next_hours(self, hours: int = 24) -> _Dict[str, _Any]:
        """
        Very lightweight forecast:
          - estimate SOC slope (percentage points per hour) from recent history
          - estimate runtime to 20% (warn) and 10% (critical)
        """
        hist = [h for h in (self.state.get("history") or []) if isinstance(h, dict) and h.get("soc") is not None]
        hist = hist[-240:]  # last ~240 samples
        if len(hist) < 3:
            fc = {"ok": False, "reason": "not enough SOC history", "critical": False}
            self.state["last_forecast"] = fc
            self._save()
            return fc

        # use last N points to compute slope
        pts = [(float(h.get("ts") or 0), float(h.get("soc") or 0)) for h in hist[-120:]]
        t0, s0 = pts[0]
        t1, s1 = pts[-1]
        dt_hours = max(1e-6, (t1 - t0) / 3600.0)
        slope = (s1 - s0) / dt_hours  # % per hour (negative means draining)

        soc_now = float(hist[-1].get("soc") or 0.0)
        warn_at = 20.0
        crit_at = 10.0

        def _time_to(target):
            if slope >= -1e-6:
                return None  # not draining (or charging)
            return max(0.0, (soc_now - target) / (-slope))

        hrs_to_warn = _time_to(warn_at)
        hrs_to_crit = _time_to(crit_at)

        fc = {
            "ok": True,
            "ts_utc": _porch_utc_iso(),
            "soc_now": soc_now,
            "slope_pct_per_hr": slope,
            "hours_to_warn": hrs_to_warn,
            "hours_to_critical": hrs_to_crit,
            "critical": (hrs_to_crit is not None and hrs_to_crit <= float((self.state.get("policy") or {}).get("critical_hours", 6))),
            "warning": (hrs_to_warn is not None and hrs_to_warn <= float((self.state.get("policy") or {}).get("warn_hours", 12))),
        }
        self.state["last_forecast"] = fc
        self._save()
        return fc

    def status_text(self) -> str:
        last = self.state.get("last") or {}
        fc = self.state.get("last_forecast") or {}
        pol = self.state.get("policy") or {}
        lines = []
        lines.append("POWER-ORACLE ⚡🔮")
        lines.append(f"Enabled: {bool(self.state.get('enabled', True))}")
        lines.append(f"Last: soc={last.get('soc')}  solar_w={last.get('solar_w')}  load_w={last.get('load_w')}  ts={last.get('ts')}")
        if fc.get("ok"):
            lines.append(f"Forecast: soc_now={fc.get('soc_now'):.1f}%  slope={fc.get('slope_pct_per_hr'):.2f}%/hr")
            lines.append(f"Hours→Warn(20%): {fc.get('hours_to_warn')} | Hours→Critical(10%): {fc.get('hours_to_critical')}")
            lines.append(f"Flags: warning={fc.get('warning')} critical={fc.get('critical')}")
        else:
            lines.append(f"Forecast: (not ready) {fc.get('reason','')}")
        lines.append(f"Policy: warn_hours={pol.get('warn_hours')} critical_hours={pol.get('critical_hours')} auto_throttle={pol.get('auto_throttle')}")
        return "\n".join(lines)

class RoverSentinel:
    """
    Mechanical Sentinel: a software representation of self-sustaining rovers/drones.
    - Register rover endpoints (uses existing IoT device registry routing)
    - Accept ingest payloads with rover status and position
    - Manage missions and simple path trails
    """
    def __init__(self, app, base_dir: str):
        self.app = app
        self.base_dir = base_dir
        _porch_mkdirp(self.base_dir)
        self.state_path = _os.path.join(self.base_dir, "rovers_state.json")
        self.state = self._load()

    def _load(self) -> _Dict[str, _Any]:
        try:
            if _os.path.exists(self.state_path):
                with open(self.state_path, "r", encoding="utf-8") as f:
                    return _json.load(f)
        except Exception:
            pass
        return {"fleet": {}, "missions": [], "last_reports": {}}

    def _save(self) -> None:
        try:
            with open(self.state_path, "w", encoding="utf-8") as f:
                _json.dump(self.state, f, indent=2)
        except Exception:
            pass

    def register(self, rover_id: str, device_id: str = "", notes: str = "") -> None:
        rid = (rover_id or "").strip()
        if not rid:
            return
        self.state.setdefault("fleet", {})[rid] = {
            "rover_id": rid,
            "device_id": (device_id or rid).strip(),
            "notes": (notes or "").strip(),
            "path": self.state.get("fleet", {}).get(rid, {}).get("path", []) if isinstance(self.state.get("fleet", {}).get(rid, {}), dict) else [],
            "last": self.state.get("fleet", {}).get(rid, {}).get("last", {}) if isinstance(self.state.get("fleet", {}).get(rid, {}), dict) else {},
        }
        self._save()

    def ingest(self, payload: _Dict[str, _Any]) -> None:
        # Accept: {"rover": {"id": "...", "pos":{"x":..,"y":..}, "report":"...", "status":"..."}, "ts":...}
        try:
            rover = payload.get("rover") if isinstance(payload, dict) else None
            if not isinstance(rover, dict):
                return
            rid = str(rover.get("id") or rover.get("rover_id") or "").strip()
            if not rid:
                return
            self.state.setdefault("fleet", {}).setdefault(rid, {"rover_id": rid, "device_id": rid, "notes": "", "path": [], "last": {}})
            ent = self.state["fleet"][rid]
            pos = rover.get("pos") or {}
            x = _porch_safe_float(pos.get("x"), default=None) if isinstance(pos, dict) else None
            y = _porch_safe_float(pos.get("y"), default=None) if isinstance(pos, dict) else None
            ts = float(payload.get("ts") or _time.time())
            if x is not None and y is not None:
                ent.setdefault("path", []).append({"ts": ts, "x": x, "y": y})
                ent["path"] = ent["path"][-2000:]
            ent["last"] = {
                "ts": ts,
                "status": rover.get("status") or "",
                "report": rover.get("report") or "",
                "pos": {"x": x, "y": y},
            }
            self.state.setdefault("last_reports", {})[rid] = ent["last"]
            self._save()
        except Exception:
            pass

    def deploy(self, rover_id: str, mission: str) -> str:
        rid = (rover_id or "").strip()
        if not rid:
            return "(missing rover_id)"
        fleet = self.state.get("fleet") or {}
        ent = fleet.get(rid) if isinstance(fleet, dict) else None
        if not isinstance(ent, dict):
            return f"(unknown rover {rid})"
        device_id = ent.get("device_id") or rid
        cmd = f"ROVER_DEPLOY {mission}".strip()
        try:
            res = self.app._iot_send_command(device_id, cmd)
        except Exception:
            res = "queued"
        self.state.setdefault("missions", []).append({"ts_utc": _porch_utc_iso(), "rover_id": rid, "mission": mission, "device_id": device_id})
        self.state["missions"] = self.state["missions"][-250:]
        self._save()
        return f"deploy queued → rover={rid} device={device_id} mission='{mission}'"

class SmartGardenForge:
    """
    Smart Garden Forge: zones, sensors, irrigation control, solar-aware automation.
    - Uses device registry routing for actuators (pump/valve)
    - Consumes ingest payload values (soil moisture, lux, temp, humidity)
    """
    def __init__(self, app, base_dir: str):
        self.app = app
        self.base_dir = base_dir
        _porch_mkdirp(self.base_dir)
        self.state_path = _os.path.join(self.base_dir, "garden_state.json")
        self.state = self._load()

    def _load(self) -> _Dict[str, _Any]:
        try:
            if _os.path.exists(self.state_path):
                with open(self.state_path, "r", encoding="utf-8") as f:
                    return _json.load(f)
        except Exception:
            pass
        return {
            "auto": False,
            "thresholds": {"soil_min": 0.35},
            "zones": {
                "zone1": {"sensor_id": "sensor", "actuator_device_id": "", "last": {}, "history": []},
            },
            "events": []
        }

    def _save(self) -> None:
        try:
            with open(self.state_path, "w", encoding="utf-8") as f:
                _json.dump(self.state, f, indent=2)
        except Exception:
            pass

    def configure_zone(self, zone: str, sensor_id: str, actuator_device_id: str) -> None:
        z = (zone or "").strip() or "zone1"
        self.state.setdefault("zones", {}).setdefault(z, {})
        self.state["zones"][z]["sensor_id"] = (sensor_id or "").strip() or "sensor"
        self.state["zones"][z]["actuator_device_id"] = (actuator_device_id or "").strip()
        self._save()

    def ingest(self, sensor_id: str, values: _Dict[str, _Any], ts: float) -> None:
        sid = (sensor_id or "").strip() or "sensor"
        if not isinstance(values, dict):
            return
        soil = values.get("soil") or values.get("soil_moisture") or values.get("moisture")
        lux = values.get("lux") or values.get("light") or values.get("sun")
        temp = values.get("temp") or values.get("temperature")
        hum = values.get("hum") or values.get("humidity")
        rec = {"ts": float(ts), "soil": _porch_safe_float(soil, default=None) if soil is not None else None,
               "lux": _porch_safe_float(lux, default=None) if lux is not None else None,
               "temp": _porch_safe_float(temp, default=None) if temp is not None else None,
               "hum": _porch_safe_float(hum, default=None) if hum is not None else None}

        # assign to any zone that matches sensor_id
        for zn, zcfg in (self.state.get("zones") or {}).items():
            if not isinstance(zcfg, dict):
                continue
            if (zcfg.get("sensor_id") or "sensor") != sid:
                continue
            zcfg["last"] = rec
            zcfg.setdefault("history", []).append(rec)
            zcfg["history"] = zcfg["history"][-5000:]
        self._save()

    def status_text(self) -> str:
        t = []
        t.append("SMART GARDEN FORGE 🌿☀️")
        t.append(f"Auto: {bool(self.state.get('auto', False))}  soil_min={((self.state.get('thresholds') or {}).get('soil_min'))}")
        zones = self.state.get("zones") or {}
        if not zones:
            t.append("(no zones configured)")
        for zn, zcfg in zones.items():
            if not isinstance(zcfg, dict):
                continue
            last = zcfg.get("last") or {}
            t.append(f"- {zn}: sensor_id={zcfg.get('sensor_id')} actuator={zcfg.get('actuator_device_id')}")
            t.append(f"    last soil={last.get('soil')} lux={last.get('lux')} temp={last.get('temp')} hum={last.get('hum')} ts={last.get('ts')}")
        return "\n".join(t)

    def water(self, zone: str, seconds: int = 10) -> str:
        z = (zone or "").strip() or "zone1"
        zones = self.state.get("zones") or {}
        zcfg = zones.get(z) if isinstance(zones, dict) else None
        if not isinstance(zcfg, dict):
            return f"(unknown zone {z})"
        dev = (zcfg.get("actuator_device_id") or "").strip()
        if not dev:
            return f"(zone {z} has no actuator_device_id configured)"
        sec = int(seconds) if seconds is not None else 10
        sec = max(1, min(3600, sec))
        payload = {"cmd": "water", "zone": z, "seconds": sec}
        if isinstance(zcfg, dict) and (zcfg.get("actuator_command") or "").strip():
            payload["cmd"] = (zcfg.get("actuator_command") or "water").strip()
        try:
            res = self.app._iot_send_command(dev, json.dumps(payload))
        except Exception:
            res = "queued"
        self.state.setdefault("events", []).append({"ts": _time.time(), "ts_utc": _porch_utc_iso(), "type": "water", "zone": z, "seconds": sec, "device_id": dev, "result": res})
        self.state["events"] = self.state["events"][-500:]
        self._save()
        return f"watering queued → zone={z} dev={dev} seconds={sec}"

    def tick_auto(self) -> _Optional[str]:
        """If auto mode and soil below threshold, trigger watering (with cooldown)."""
        if not bool(self.state.get("auto", False)):
            return None
        soil_min = _porch_safe_float((self.state.get("thresholds") or {}).get("soil_min", 0.35), 0.35)
        zones = self.state.get("zones") or {}
        now = _time.time()
        cooldown = 30 * 60  # 30 minutes
        for zn, zcfg in zones.items():
            if not isinstance(zcfg, dict):
                continue
            last = zcfg.get("last") or {}
            soil = last.get("soil")
            if soil is None:
                continue
            try:
                soil_f = float(soil)
            except Exception:
                continue

            last_water_ts = None
            for ev in reversed(self.state.get("events") or []):
                if isinstance(ev, dict) and ev.get("type") == "water" and ev.get("zone") == zn:
                    last_water_ts = ev.get("ts") or ev.get("ts_epoch")
                    break

            if soil_f < soil_min:
                if last_water_ts is None:
                    return self.water(zn, seconds=15)
                try:
                    if now - float(last_water_ts) > cooldown:
                        return self.water(zn, seconds=15)
                except Exception:
                    # if can't parse timestamp, do nothing
                    pass
        return None

class KIPVault:
    """
    Knowledge Infrastructure (KIP-like): a tiny local knowledge graph + bootstrap manifest.
    """
    def __init__(self, app, base_dir: str):
        self.app = app
        self.base_dir = base_dir
        _porch_mkdirp(self.base_dir)
        self.path = _os.path.join(self.base_dir, "kip_vault.json")
        self.state = self._load()

    def _load(self) -> _Dict[str, _Any]:
        try:
            if _os.path.exists(self.path):
                with open(self.path, "r", encoding="utf-8") as f:
                    return _json.load(f)
        except Exception:
            pass
        return {"nodes": {}, "edges": [], "bootstrap_manifests": []}

    def _save(self) -> None:
        try:
            with open(self.path, "w", encoding="utf-8") as f:
                _json.dump(self.state, f, indent=2)
        except Exception:
            pass

    def add_node(self, title: str, content: str, tags: _Optional[_List[str]] = None) -> str:
        ttl = (title or "").strip() or "Untitled"
        nid = f"n_{abs(hash(ttl)) % 10_000_000}"
        self.state.setdefault("nodes", {})[nid] = {
            "id": nid,
            "title": ttl,
            "content": (content or "").strip(),
            "tags": tags or [],
            "created_utc": _porch_utc_iso(),
        }
        self._save()
        return nid

    def link(self, a: str, b: str, rel: str = "related") -> None:
        a = (a or "").strip()
        b = (b or "").strip()
        if not a or not b:
            return
        self.state.setdefault("edges", []).append({"a": a, "b": b, "rel": (rel or "related").strip(), "ts_utc": _porch_utc_iso()})
        self.state["edges"] = self.state["edges"][-5000:]
        self._save()

    def export_graph(self, out_path: str) -> str:
        try:
            with open(out_path, "w", encoding="utf-8") as f:
                _json.dump(self.state, f, indent=2)
            return out_path
        except Exception:
            return "(export failed)"

    def bootstrap_snapshot(self, root_dir: str, out_dir: str) -> str:
        _porch_mkdirp(out_dir)
        ts = _porch_utc_iso().replace(":", "-")
        out_path = _os.path.join(out_dir, f"bootstrap_manifest_{ts}.json")
        manifest = {"ts_utc": _porch_utc_iso(), "root": _os.path.abspath(root_dir), "files": [], "notes": "Local seed-bank manifest (BootstrapLab-style)"}  # noqa

        def _walk(p):
            try:
                for dp, _, fnames in _os.walk(p):
                    for fn in fnames:
                        full = _os.path.join(dp, fn)
                        try:
                            st = _os.stat(full)
                            manifest["files"].append({"path": _os.path.relpath(full, root_dir), "size": int(st.st_size), "mtime": float(st.st_mtime)})
                        except Exception:
                            manifest["files"].append({"path": _os.path.relpath(full, root_dir), "size": None, "mtime": None})
                        if len(manifest["files"]) >= 5000:
                            return
            except Exception:
                pass

        # pick a few key dirs if they exist:
        for rel in ["well", "experiences", "models", "vault", "."]:
            p = _os.path.join(root_dir, rel)
            if _os.path.exists(p):
                _walk(p)

        try:
            with open(out_path, "w", encoding="utf-8") as f:
                _json.dump(manifest, f, indent=2)
        except Exception:
            pass

        self.state.setdefault("bootstrap_manifests", []).append({"ts_utc": _porch_utc_iso(), "path": out_path})
        self.state["bootstrap_manifests"] = self.state["bootstrap_manifests"][-50:]
        self._save()
        return out_path

# -----------------------------------------------------------------------------
# Porch integration helpers (monkey-patch style)
# -----------------------------------------------------------------------------

def _porch__ensure_power_oracle(self):
    if getattr(self, "power_oracle", None) is None:
        base = _os.path.join(WELL_DIR, "power")
        self.power_oracle = PowerOracle(app=self, base_dir=base)
    return self.power_oracle

def _porch__ensure_rovers(self):
    if getattr(self, "rovers", None) is None:
        base = _os.path.join(WELL_DIR, "rovers")
        self.rovers = RoverSentinel(app=self, base_dir=base)
    return self.rovers

def _porch__ensure_garden(self):
    if getattr(self, "garden", None) is None:
        base = _os.path.join(WELL_DIR, "garden")
        self.garden = SmartGardenForge(app=self, base_dir=base)
    return self.garden

def _porch__ensure_kip(self):
    if getattr(self, "kip", None) is None:
        base = _os.path.join(WELL_DIR, "kip")
        self.kip = KIPVault(app=self, base_dir=base)
    return self.kip

def _porch__power_fetch_now(self) -> str:
    po = _porch__ensure_power_oracle(self)
    rec = po.fetch_now()
    return f"[Power] fetched: soc={rec.get('soc')} solar_w={rec.get('solar_w')} load_w={rec.get('load_w')}"

def _porch__power_predict(self, hours: int = 24) -> str:
    po = _porch__ensure_power_oracle(self)
    fc = po.predict_next_hours(hours=hours)
    # auto-throttle if critical
    try:
        pol = (po.state.get("policy") or {})
        if fc.get("critical") and bool(pol.get("auto_throttle", True)):
            lvl = pol.get("throttle_level") or "conserve"
            msg = _porch__power_apply_throttle(self, str(lvl))
            return po.status_text() + "\n\n" + msg
    except Exception:
        pass
    return po.status_text()

def _porch__power_apply_throttle(self, level: str = "conserve") -> str:
    lvl = (level or "conserve").strip().lower()
    if lvl not in ("conserve", "minimal", "normal"):
        lvl = "conserve"
    setattr(self, "_power_throttle_level", lvl)
    # best-effort: reduce internal background intensity
    try:
        # if a music pulse is running, turn it off in conserve mode
        if lvl in ("conserve", "minimal") and getattr(self, "music_studio", None) is not None:
            try:
                self.music_studio.pulse_enabled = False
            except Exception:
                pass
    except Exception:
        pass
    return f"[Power] throttle applied → level={lvl} (local-first; affects Porch policies/tools)"

def _porch__power_release_throttle(self) -> str:
    setattr(self, "_power_throttle_level", "normal")
    return "[Power] throttle released → level=normal"

def _porch__rover_register(self, rover_id: str, device_id: str = "", notes: str = "") -> str:
    rv = _porch__ensure_rovers(self)
    rv.register(rover_id, device_id=device_id, notes=notes)
    return f"[Rover] registered → rover_id={rover_id} device_id={device_id or rover_id}"

def _porch__rover_deploy(self, rover_id: str, mission: str) -> str:
    rv = _porch__ensure_rovers(self)
    return rv.deploy(rover_id, mission)

def _porch__garden_status(self) -> str:
    gd = _porch__ensure_garden(self)
    return gd.status_text()

def _porch__garden_water(self, zone: str, seconds: int = 10) -> str:
    gd = _porch__ensure_garden(self)
    return gd.water(zone, seconds)

def _porch__garden_auto(self, onoff: str) -> str:
    gd = _porch__ensure_garden(self)
    v = (onoff or "").strip().lower()
    if v in ("on","true","1","yes","enable","enabled"):
        gd.state["auto"] = True
        gd._save()
        return "[Garden] auto mode: ON"
    if v in ("off","false","0","no","disable","disabled"):
        gd.state["auto"] = False
        gd._save()
        return "[Garden] auto mode: OFF"
    return f"[Garden] auto currently: {bool(gd.state.get('auto', False))}"

def _porch__kip_add(self, title: str, content: str) -> str:
    kv = _porch__ensure_kip(self)
    nid = kv.add_node(title, content, tags=["porch"])
    return f"[KIP] node added → {nid} '{title}'"

def _porch__kip_link(self, a: str, b: str, rel: str = "related") -> str:
    kv = _porch__ensure_kip(self)
    kv.link(a, b, rel=rel)
    return f"[KIP] linked {a} --({rel})-> {b}"

def _porch__bootstrap_snapshot(self) -> str:
    kv = _porch__ensure_kip(self)
    out_dir = _os.path.join(WELL_DIR, "bootstrap")
    p = kv.bootstrap_snapshot(root_dir=BASE_DIR if 'BASE_DIR' in globals() else _os.getcwd(), out_dir=out_dir)
    return f"[Bootstrap] manifest written: {p}"

# -----------------------------------------------------------------------------
# UI: add extra IoT tabs (Power / Rovers / Garden / KIP)
# -----------------------------------------------------------------------------

def _build_iot_power_ui(self, tab) -> None:
    try:
        tab.grid_rowconfigure(2, weight=1)
        tab.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    po = _porch__ensure_power_oracle(self)

    top = ctk.CTkFrame(tab, fg_color="transparent")
    top.grid(row=0, column=0, sticky="ew", padx=10, pady=(10, 6))
    top.grid_columnconfigure(1, weight=1)
    ctk.CTkLabel(top, text="Power Oracle ⚡🔮", font=ctk.CTkFont(size=16, weight="bold")).grid(row=0, column=0, sticky="w")
    self._power_auto_throttle = ctk.BooleanVar(value=bool((po.state.get("policy") or {}).get("auto_throttle", True)))
    def _save_pol():
        try:
            po.state.setdefault("policy", {})["auto_throttle"] = bool(self._power_auto_throttle.get())
            po._save()
        except Exception:
            pass
    ctk.CTkCheckBox(top, text="Auto-throttle on critical", variable=self._power_auto_throttle, command=_save_pol).grid(row=0, column=1, sticky="e")

    box = ctk.CTkTextbox(tab, height=220)
    box.grid(row=1, column=0, sticky="nsew", padx=10, pady=(0, 6))
    box.insert("end", po.status_text())
    box.configure(state="disabled")
    self._power_box = box

    btns = ctk.CTkFrame(tab, fg_color="transparent")
    btns.grid(row=2, column=0, sticky="ew", padx=10, pady=(0, 10))
    ctk.CTkButton(btns, text="Configure HA", command=lambda: _porch__power_open_ha_config(self)).pack(side="left", padx=(0, 8))
    def _refresh():
        try:
            po = _porch__ensure_power_oracle(self)
            txt = po.status_text()
            self._power_box.configure(state="normal")
            self._power_box.delete("1.0", "end")
            self._power_box.insert("end", txt)
            self._power_box.configure(state="disabled")
        except Exception:
            pass

    ctk.CTkButton(btns, text="Fetch Now (HA)", command=lambda: (self._ui_log(_porch__power_fetch_now(self)), _refresh())).pack(side="left", padx=(0, 8))
    ctk.CTkButton(btns, text="Predict 24h", command=lambda: (self._ui_log(_porch__power_predict(self, 24)), _refresh())).pack(side="left", padx=(0, 8))
    ctk.CTkButton(btns, text="Throttle: Conserve", command=lambda: self._ui_log(_porch__power_apply_throttle(self, "conserve"))).pack(side="left", padx=(0, 8))
    ctk.CTkButton(btns, text="Throttle: Normal", command=lambda: self._ui_log(_porch__power_release_throttle(self))).pack(side="left", padx=(0, 8))

def _build_iot_rovers_ui(self, tab) -> None:
    try:
        tab.grid_rowconfigure(1, weight=1)
        tab.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    rv = _porch__ensure_rovers(self)

    top = ctk.CTkFrame(tab, fg_color="transparent")
    top.grid(row=0, column=0, sticky="ew", padx=10, pady=10)
    top.grid_columnconfigure(1, weight=1)
    ctk.CTkLabel(top, text="Mechanical Sentinel 🤖👁️", font=ctk.CTkFont(size=16, weight="bold")).grid(row=0, column=0, sticky="w")

    form = ctk.CTkFrame(tab, fg_color="transparent")
    form.grid(row=1, column=0, sticky="ew", padx=10, pady=(0, 6))
    form.grid_columnconfigure(1, weight=1)
    self._rover_id_var = ctk.StringVar(value="")
    self._rover_device_var = ctk.StringVar(value="")
    self._rover_mission_var = ctk.StringVar(value="investigate anomaly")
    ctk.CTkLabel(form, text="Rover ID").grid(row=0, column=0, sticky="w")
    ctk.CTkEntry(form, textvariable=self._rover_id_var).grid(row=0, column=1, sticky="ew", padx=(8, 0))
    ctk.CTkLabel(form, text="Device ID").grid(row=0, column=2, sticky="w", padx=(12, 0))
    ctk.CTkEntry(form, textvariable=self._rover_device_var).grid(row=0, column=3, sticky="ew", padx=(8, 0))

    ctk.CTkLabel(form, text="Mission").grid(row=1, column=0, sticky="w", pady=(6,0))
    ctk.CTkEntry(form, textvariable=self._rover_mission_var).grid(row=1, column=1, columnspan=3, sticky="ew", padx=(8, 0), pady=(6,0))

    btns = ctk.CTkFrame(tab, fg_color="transparent")
    btns.grid(row=2, column=0, sticky="ew", padx=10, pady=(0, 10))
    def _reg():
        rid = self._rover_id_var.get().strip()
        did = self._rover_device_var.get().strip()
        self._ui_log(_porch__rover_register(self, rid, device_id=did))
        _refresh()
    def _deploy():
        rid = self._rover_id_var.get().strip()
        ms = self._rover_mission_var.get().strip()
        self._ui_log(_porch__rover_deploy(self, rid, ms))
        _refresh()

    ctk.CTkButton(btns, text="Register", command=_reg).pack(side="left", padx=(0, 8))
    ctk.CTkButton(btns, text="Deploy", command=_deploy).pack(side="left", padx=(0, 8))

    box = ctk.CTkTextbox(tab)
    box.grid(row=3, column=0, sticky="nsew", padx=10, pady=(0, 10))
    self._rovers_box = box

    def _refresh():
        try:
            rv = _porch__ensure_rovers(self)
            fleet = rv.state.get("fleet") or {}
            lines = ["ROVER FLEET:"]
            if not fleet:
                lines.append("(none registered)")
            else:
                for rid, ent in fleet.items():
                    if not isinstance(ent, dict):
                        continue
                    last = ent.get("last") or {}
                    lines.append(f"- {rid} device={ent.get('device_id')} status={last.get('status','')} pos={last.get('pos')} report={str(last.get('report',''))[:120]}")
            self._rovers_box.delete("1.0", "end")
            self._rovers_box.insert("end", "\n".join(lines))
        except Exception:
            pass
    _refresh()

def _build_iot_garden_ui(self, tab) -> None:
    try:
        tab.grid_rowconfigure(3, weight=1)
        tab.grid_columnconfigure(0, weight=1)
    except Exception:
        pass

    gd = _porch__ensure_garden(self)

    top = ctk.CTkFrame(tab, fg_color="transparent")
