    ctk.CTkLabel(form, text="Seconds").grid(row=0, column=2, sticky="w", padx=(12,0))
    ctk.CTkEntry(form, textvariable=self._garden_seconds_var, width=120).grid(row=0, column=3, sticky="w", padx=(8,0))

    btns = ctk.CTkFrame(tab, fg_color="transparent")
    btns.grid(row=2, column=0, sticky="ew", padx=10, pady=(0, 6))
    def _water():
        z = self._garden_zone_var.get().strip()
        try:
            sec = int(float(self._garden_seconds_var.get().strip()))
        except Exception:
            sec = 15
        self._ui_log(_porch__garden_water(self, z, sec))
        _refresh()
    ctk.CTkButton(btns, text="Water", command=_water).pack(side="left", padx=(0, 8))
    ctk.CTkButton(btns, text="Zones…", command=lambda: _porch__garden_open_zones(self)).pack(side="left", padx=(0, 8))
    ctk.CTkButton(btns, text="Refresh", command=lambda: _refresh()).pack(side="left", padx=(0, 8))

    box = ctk.CTkTextbox(tab)
    box.grid(row=3, column=0, sticky="nsew", padx=10, pady=(0, 10))
    self._garden_box = box

