try:
    import threading
    import time
    import math
except Exception:
    threading = None  # type: ignore

def _pt__base_dir() -> str:
    try:
        return BASE_DIR  # type: ignore
    except Exception:
        return os.path.dirname(os.path.abspath(__file__))

def _pt__outputs_dir() -> str:
    d = os.path.join(_pt__base_dir(), "outputs")
    try:
        os.makedirs(d, exist_ok=True)
    except Exception:
        pass
    return d

def _pt__safe_slug(s: str) -> str:
    s = (s or "").strip().lower()
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif ch in (" ", "-", "_", "."):
            out.append("_")
    slug = "".join(out).strip("_")
    return slug[:60] if slug else "project"

def _pt__write_files(root: str, files: dict) -> None:
    os.makedirs(root, exist_ok=True)
    for rel, content in (files or {}).items():
        p = os.path.join(root, rel)
        if rel.endswith("/"):
            os.makedirs(p, exist_ok=True)
            continue
        os.makedirs(os.path.dirname(p), exist_ok=True)
        if isinstance(content, (bytes, bytearray)):
            with open(p, "wb") as f:
                f.write(content)
        else:
            with open(p, "w", encoding="utf-8", errors="ignore") as f:
                f.write(str(content))

def _pt__utc_iso() -> str:
    try:
        return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00","Z")
    except Exception:
        return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace('+00:00','Z')

