class BluetoothDeviceGenerator:
    """Generate BLE firmware sketches (ESP32 / Arduino style)."""
    def create_ble_sensor(self, sensor_type: str) -> dict:
        st = _pt__safe_slug(sensor_type)
        name = f"{st}_sensor"
        firmware = f'''// Generated by Infinite Porch — People's Technology
// {sensor_type} BLE Sensor (ESP32)

#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>

#define SERVICE_UUID        "12345678-1234-1234-1234-1234567890ab"
#define CHARACTERISTIC_UUID "abcd1234-1234-1234-1234-abcdef123456"

BLECharacteristic* pCharacteristic = nullptr;

float read_{st}() {{
  return 42.0; // TODO: real sensor
}}

void setup() {{
  Serial.begin(115200);
  BLEDevice::init("{name}");
  BLEServer *pServer = BLEDevice::createServer();
  BLEService *pService = pServer->createService(SERVICE_UUID);
  pCharacteristic = pService->createCharacteristic(
      CHARACTERISTIC_UUID,
      BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_NOTIFY
  );
  pCharacteristic->addDescriptor(new BLE2902());
  pService->start();
  BLEAdvertising *pAdvertising = BLEDevice::getAdvertising();
  pAdvertising->addServiceUUID(SERVICE_UUID);
  BLEDevice::startAdvertising();
}}

void loop() {{
  float value = read_{st}();
  pCharacteristic->setValue((uint8_t*)&value, sizeof(value));
  pCharacteristic->notify();
  delay(1000);
}}
'''
        return {"firmware": firmware, "platform": "ESP32", "instructions": "Upload via Arduino IDE / PlatformIO", "cost":"$5 total", "savings":"~90% cheaper"}

