try:
    _pt__init__orig = InfinitePorch.__init__  # type: ignore
    def _pt__init__patched(self, *a, **kw):
        _pt__init__orig(self, *a, **kw)
        try:
            _pt__ensure_hub(self)
            if getattr(self, "people_tech", None):
                self.people_tech.start_autonomous()
        except Exception:
            pass
    InfinitePorch.__init__ = _pt__init__patched  # type: ignore
except Exception:
    pass

def _pt__handle_command(self, text: str) -> bool:
    m = (text or "").strip()
    if not m.startswith("/"):
        return False
    parts = m.split()
    cmd = parts[0].lower()
    if cmd in ("/export","/exports"):
        if len(parts) >= 3 and parts[1].lower() == "mobile":
            kind = parts[2].lower()
            concept = " ".join(parts[3:]).strip() or "Porch App"
            _pt__ensure_hub(self)
            hub=getattr(self,"people_tech",None)
            if not hub:
                self._ui_log("People's Tech Hub not ready.", dim=True); return True
            res = hub.exporter.export_mobile(concept, kind)
            self._ui_log(f"📤 Exported {res.get('type')} → {res.get('root')}\n{res.get('instructions')}")
            return True
        self.export_mobile_dialog()
        return True
    if cmd in ("/gadget","/gadgets"):
        tmpl = parts[1].lower() if len(parts)>1 else "smart_plug"
        self.load_template(tmpl)
        return True
    if cmd in ("/autonomous","/auto_create"):
        _pt__ensure_hub(self)
        hub=getattr(self,"people_tech",None)
        sub = parts[1].lower() if len(parts)>1 else "status"
        if not hub:
            self._ui_log("Autonomous Creation not ready.", dim=True); return True
        if sub in ("status","info"):
            self.show_autonomous_status(); return True
        if sub in ("run","now","tick"):
            hub.autonomy.run_once(); return True
        if sub in ("pause","stop","off"):
            hub.autonomy.stop(); return True
        if sub in ("resume","on","start"):
            hub.autonomy.start(); return True
        self.show_autonomous_status()
        return True
    return False

try:
    _pt__hsc_orig = InfinitePorch._handle_slash_command  # type: ignore
    def _pt__hsc_patched(self, text: str) -> bool:
        try:
            if _pt__handle_command(self, text):
                return True
        except Exception:
            pass
        return _pt__hsc_orig(self, text)
    InfinitePorch._handle_slash_command = _pt__hsc_patched  # type: ignore
except Exception:
    pass


# ======================================================================
# PET GUARDIAN + TAMAGO HATCHERY (Porch Pets)
# - Bark / dB monitor via IoT ingest
# - Calming audio (432Hz + brown noise) + focus ping
# - Optional intercom clip playback
# - Optional haptic "purr" via _porch_haptics
# - Virtual Tamago pet (serenity XP linked to noise/bark)
# ======================================================================

try:
    import numpy as _np  # optional
except Exception:
    _np = None
try:
    import soundfile as _sf  # optional
except Exception:
    _sf = None

class TamagoPet:
    """Local-first virtual pet inspired by AI-tamago (no external deps)."""
    def __init__(self, name="Tamago", species="Sentinel Companion"):
        self.name = name
        self.species = species
        self.hunger = 30.0      # 0=full, 100=starving
        self.happiness = 75.0   # 0=sad, 100=joy
        self.serenity_xp = 0.0
        self.level = 1
        self.startled = False
        self.last_update = time.time()

    def tick(self, dt: float, noise_db: float = 0.0, bark_spike: bool = False):
        dt = max(0.0, float(dt))
        # hunger increases slowly
        self.hunger = min(100.0, self.hunger + dt * 0.0025)
        # happiness decays slightly with hunger
        self.happiness = max(0.0, min(100.0, self.happiness - dt * 0.001 * (1.0 + self.hunger/100.0)))

        if bark_spike or (noise_db and noise_db >= 80.0):
            self.startled = True
            self.happiness = max(0.0, self.happiness - 2.5)
            self.serenity_xp = max(0.0, self.serenity_xp - 1.0)
        else:
            # calm environment → serenity gains
            self.startled = False
            self.serenity_xp += dt * 0.003
            if noise_db and noise_db <= 60.0:
                self.serenity_xp += dt * 0.002

        # level up every 100 xp
        new_level = int(self.serenity_xp // 100.0) + 1
        if new_level > self.level:
            self.level = new_level
            self.happiness = min(100.0, self.happiness + 10.0)

        self.last_update = time.time()

    def feed(self, amount: float = 25.0):
        self.hunger = max(0.0, self.hunger - float(amount))
        self.happiness = min(100.0, self.happiness + 4.0)

    def pet(self, amount: float = 10.0):
        self.happiness = min(100.0, self.happiness + float(amount))
        self.serenity_xp += float(amount) * 0.5

    def snapshot(self):
        return {
            "name": self.name,
            "species": self.species,
            "hunger": self.hunger,
            "happiness": self.happiness,
            "serenity_xp": self.serenity_xp,
            "level": self.level,
            "startled": self.startled,
            "last_update": self.last_update,
        }

    @classmethod
    def from_snapshot(cls, d: dict):
        p = cls(d.get("name","Tamago"), d.get("species","Sentinel Companion"))
        p.hunger = float(d.get("hunger", 30.0))
        p.happiness = float(d.get("happiness", 75.0))
        p.serenity_xp = float(d.get("serenity_xp", 0.0))
        p.level = int(d.get("level", 1))
        p.startled = bool(d.get("startled", False))
        p.last_update = float(d.get("last_update", time.time()))
        return p


class PorchPetGuardian:
    """Handles bark/noise sensing + calming remediation + tamago state."""
    def __init__(self, app):
        self.app = app
        self.enabled = True
        self.threshold_db = 85.0
        self.cooldown_sec = 10.0
        self.last_trigger_ts = 0.0
        self.last_db = 0.0
        self.bark_spikes = 0
        self.total_barks = 0
        self.window_barks = []  # list of (ts, db)
        self.intercom_clip = ""  # path to wav
        self.diffuser_device_id = ""  # optional device registry id
        self.diffuser_command = "diffuse"
        self.auto_calm = True
        self.auto_intercom = True
        self.auto_haptic = True
        self.ping_enabled = True
        self.calm_track_path = ""  # generated
        self.ping_path = ""        # generated
        self.pet = TamagoPet(name="Tamago", species="Sentinel Companion")

        self._tick_thread = None
        self._tick_stop = threading.Event()

    def load(self, state: dict):
        if not isinstance(state, dict):
            return
        self.enabled = bool(state.get("enabled", True))
        self.threshold_db = float(state.get("threshold_db", 85.0))
        self.cooldown_sec = float(state.get("cooldown_sec", 10.0))
        self.last_trigger_ts = float(state.get("last_trigger_ts", 0.0))
        self.last_db = float(state.get("last_db", 0.0))
        self.total_barks = int(state.get("total_barks", 0))
        self.bark_spikes = int(state.get("bark_spikes", 0))
        self.intercom_clip = str(state.get("intercom_clip", "") or "")
        self.diffuser_device_id = str(state.get("diffuser_device_id", "") or "")
        self.diffuser_command = str(state.get("diffuser_command", "diffuse") or "diffuse")
        self.auto_calm = bool(state.get("auto_calm", True))
        self.auto_intercom = bool(state.get("auto_intercom", True))
        self.auto_haptic = bool(state.get("auto_haptic", True))
        self.ping_enabled = bool(state.get("ping_enabled", True))
        pet_snap = state.get("tamago") or {}
        try:
            self.pet = TamagoPet.from_snapshot(pet_snap) if isinstance(pet_snap, dict) else TamagoPet()
        except Exception:
            self.pet = TamagoPet()

    def dump(self):
        return {
            "enabled": self.enabled,
            "threshold_db": self.threshold_db,
            "cooldown_sec": self.cooldown_sec,
            "last_trigger_ts": self.last_trigger_ts,
            "last_db": self.last_db,
            "total_barks": self.total_barks,
            "bark_spikes": self.bark_spikes,
            "intercom_clip": self.intercom_clip,
            "diffuser_device_id": self.diffuser_device_id,
            "diffuser_command": self.diffuser_command,
            "auto_calm": self.auto_calm,
            "auto_intercom": self.auto_intercom,
            "auto_haptic": self.auto_haptic,
            "ping_enabled": self.ping_enabled,
            "tamago": self.pet.snapshot(),
        }

    def _log(self, msg: str):
        try:
            if hasattr(self.app, "_ui_log"):
                self.app._ui_log(msg)
            else:
                print(msg)
        except Exception:
            print(msg)

    def _dm(self, msg: str):
        # route into DM hub if present
        try:
            if hasattr(self.app, "_dmhub_send"):
                # "Jyai" pings "Ori/You" as described
                self.app._dmhub_send(recipient="You", text=msg, sender="Jyai", meta={"type": "pet_alert"})
                return
        except Exception:
            pass
        self._log("[Pet] " + msg)

    def start(self):
        if self._tick_thread and self._tick_thread.is_alive():
            return
        self._tick_stop.clear()

        def _run():
            last = time.time()
            while not self._tick_stop.is_set():
                now = time.time()
                dt = now - last
                last = now
                try:
                    self.pet.tick(dt, noise_db=self.last_db, bark_spike=False)
                    # gentle reminders if barking high in last 10 minutes
                    cutoff = now - 600.0
                    self.window_barks = [(t, d) for (t, d) in self.window_barks if t >= cutoff]
                    if len(self.window_barks) >= 12:
                        # nudge once per 10 min
                        if now - self.last_trigger_ts > 120.0:
                            self._dm(f"Pack stress rising (bark spikes ~{len(self.window_barks)} in 10m). Consider water/check windows.")
                except Exception:
                    pass
                time.sleep(3.0)

        self._tick_thread = threading.Thread(target=_run, daemon=True)
        self._tick_thread.start()

    def stop(self):
        self._tick_stop.set()

    def on_sensor(self, sid: str, vals: dict) -> bool:
        """Return True if bark trigger fired."""
        if not self.enabled or not isinstance(vals, dict):
            return False

        db = None
        for k in ("db", "decibels", "decibel", "sound_db", "noise_db", "spl"):
            if k in vals:
                try:
                    db = float(vals.get(k))
                except Exception:
                    db = None
                break
        if db is None:
            return False

        self.last_db = db
        fired = False

        if db >= float(self.threshold_db):
            now = time.time()
            if (now - float(self.last_trigger_ts)) >= float(self.cooldown_sec):
                fired = True
                self.last_trigger_ts = now
                self.bark_spikes += 1
                self.total_barks += 1
                self.window_barks.append((now, db))

                self.pet.tick(0.1, noise_db=db, bark_spike=True)

                self._dm(f"Noise levels hitting {db:.1f} dB (threshold {self.threshold_db:.0f}) — the pack is agitated. (sensor {sid})")
                try:
                    if self.auto_calm:
                        self.trigger_calm()
                    if self.auto_intercom:
                        self.play_intercom()
                    if self.auto_haptic:
                        self.emit_purr()
                    # optional diffuser
                    if self.diffuser_device_id:
                        self.trigger_diffuser()
                except Exception:
                    pass
        return fired

    # ---------- Remediation actions ----------
    def _ensure_audio_dir(self) -> str:
        base = None
        try:
            base = getattr(self.app, "WELL_DIR", None) or None
        except Exception:
            base = None
        if not base:
            try:
                base = os.path.abspath(os.path.join(os.path.dirname(__file__), "well"))
            except Exception:
                base = os.path.abspath("well")
        audio_dir = os.path.join(base, "audio")
        os.makedirs(audio_dir, exist_ok=True)
        return audio_dir

    def _write_wav(self, path: str, samples, sr: int = 44100) -> str:
        if _sf is None:
            self._log("[Pet] WAV write requires soundfile. Install: pip install soundfile")
            return ""
        try:
            _sf.write(path, samples, sr)
            return path
        except Exception as e:
            self._log(f"[Pet] Could not write wav: {e}")
            return ""

    def _gen_brown_noise(self, seconds: float, sr: int = 44100):
        if _np is None:
            return None
        n = int(seconds * sr)
        white = _np.random.randn(n)
        brown = _np.cumsum(white)
        brown = brown / (_np.max(_np.abs(brown)) + 1e-9)
        return brown

    def _gen_sine(self, freq: float, seconds: float, sr: int = 44100):
        if _np is None:
            return None
        t = _np.linspace(0.0, seconds, int(seconds * sr), endpoint=False)
        return _np.sin(2.0 * _np.pi * float(freq) * t)

    def _mix(self, a, b, wa=0.6, wb=0.4):
        if _np is None:
            return None
        if a is None:
            return b
        if b is None:
            return a
        n = min(len(a), len(b))
        x = wa * a[:n] + wb * b[:n]
        x = x / (_np.max(_np.abs(x)) + 1e-9)
        return x

    def _play_wav_best_effort(self, path: str):
        # optional playback using pygame if present
        try:
            import pygame  # optional
            try:
                pygame.mixer.init()
            except Exception:
                try:
                    pygame.mixer.quit()
                except Exception:
                    pass
                pygame.mixer.init()
            pygame.mixer.music.load(path)
            pygame.mixer.music.play()
            return True
        except Exception:
            self._log("[Pet] Audio playback unavailable (optional). Install: pip install pygame")
            return False

    def trigger_calm(self):
        """Generate and play Canine-Zen track: 432Hz + brown noise."""
        audio_dir = self._ensure_audio_dir()
        out_path = os.path.join(audio_dir, "canine_zen_432_brown.wav")
        if not os.path.exists(out_path):
            if _np is None or _sf is None:
                self._log("[Pet] Calming track generation requires numpy + soundfile. Install: pip install numpy soundfile")
                return "missing_deps"
            sine = self._gen_sine(432.0, 12.0)
            brown = self._gen_brown_noise(12.0)
            mix = self._mix(sine, brown, wa=0.55, wb=0.45)
            self._write_wav(out_path, mix, 44100)
        self.calm_track_path = out_path
        self._log("[Pet] 🐾 Calming track engaged (432Hz + brown noise).")
        self._play_wav_best_effort(out_path)
        return "ok"

    def focus_ping(self):
        """Short high-frequency ping to interrupt barking loop (subtle)."""
        audio_dir = self._ensure_audio_dir()
        out_path = os.path.join(audio_dir, "focus_ping.wav")
        if not os.path.exists(out_path):
            if _np is None or _sf is None:
                self._log("[Pet] Focus ping generation requires numpy + soundfile. Install: pip install numpy soundfile")
                return "missing_deps"
            sine = self._gen_sine(3000.0, 0.25)
            # fade
            n = len(sine)
            fade = _np.linspace(1.0, 0.0, n)
            sig = (sine * fade) * 0.6
            self._write_wav(out_path, sig, 44100)
        self.ping_path = out_path
        self._log("[Pet] 🔔 Focus ping emitted.")
        self._play_wav_best_effort(out_path)
        return "ok"

    def play_intercom(self):
        """Play a recorded voice clip (calm command)."""
        clip = (self.intercom_clip or "").strip()
        if not clip:
            self._log("[Pet] Intercom clip not set. Use Pets UI → Set Intercom Clip, or /pet clip <path>")
            return "no_clip"
        if not os.path.exists(clip):
            self._log(f"[Pet] Intercom clip missing: {clip}")
            return "missing"
        self._log("[Pet] 📣 Intercom: 'Easy, pack. The Porch is secure.'")
        self._play_wav_best_effort(clip)
        return "ok"

    def emit_purr(self):
        """Low-frequency haptic purr (5–10Hz vibe) via _porch_haptics."""
        try:
            h = getattr(self.app, "_porch_haptics", None)
            if h and hasattr(h, "emit"):
                h.emit("pet_purr", meta={"hz": 7.0, "ts": time.time()})
                self._log("[Pet] 🫶 Haptic purr emitted (7Hz).")
                return "ok"
        except Exception:
            pass
        self._log("[Pet] Haptics unavailable (no _porch_haptics).")
        return "no_haptics"

    def trigger_diffuser(self):
        """Optional Tuya/IoT diffuser command routing via device registry."""
        if not self.diffuser_device_id:
            return "no_device"
        payload = {"cmd": self.diffuser_command, "scent": "lavender", "mode": "calm"}
        try:
            if hasattr(self.app, "_iot_send_command"):
                ok = self.app._iot_send_command(self.diffuser_device_id, payload)
                self._log(f"[Pet] 🌿 Diffuser command sent → {self.diffuser_device_id} ({'ok' if ok else 'queued'})")
                return "ok"
        except Exception as e:
            self._log(f"[Pet] Diffuser send failed: {e}")
        return "fail"

    # ---------- UI ----------
    def open_window(self):
        import customtkinter as ctk
        import tkinter as tk
        from tkinter import filedialog

        if getattr(self, "_win", None) and self._win.winfo_exists():
            try:
                self._win.lift()
                return
            except Exception:
                pass

        win = ctk.CTkToplevel()
        win.title("🐾 Pet Guardian & Tamago Hatchery")
        win.geometry("820x560")
        self._win = win

        win.grid_columnconfigure(0, weight=1)
        win.grid_rowconfigure(1, weight=1)

        top = ctk.CTkFrame(win)
        top.grid(row=0, column=0, sticky="ew", padx=10, pady=10)
        top.grid_columnconfigure(6, weight=1)

        self._ui_enabled = ctk.BooleanVar(value=self.enabled)
        ctk.CTkCheckBox(top, text="Enable Pet Guardian", variable=self._ui_enabled, command=lambda: self._ui_apply()).grid(row=0, column=0, sticky="w", padx=(0,10))
        ctk.CTkLabel(top, text="Chaos Threshold (dB):").grid(row=0, column=1, sticky="w")
        self._ui_thr = ctk.CTkEntry(top, width=70)
        self._ui_thr.insert(0, str(int(self.threshold_db)))
        self._ui_thr.grid(row=0, column=2, sticky="w", padx=(6,10))

        ctk.CTkButton(top, text="Test Calm", width=90, command=self.trigger_calm).grid(row=0, column=3, padx=6)
        ctk.CTkButton(top, text="Ping", width=70, command=self.focus_ping).grid(row=0, column=4, padx=6)
        ctk.CTkButton(top, text="Intercom", width=90, command=self.play_intercom).grid(row=0, column=5, padx=6)

        ctk.CTkButton(top, text="Set Intercom Clip", width=140, command=lambda: self._ui_pick_clip(filedialog)).grid(row=0, column=6, sticky="e")

        body = ctk.CTkFrame(win)
        body.grid(row=1, column=0, sticky="nsew", padx=10, pady=(0,10))
        body.grid_columnconfigure(0, weight=1)
        body.grid_columnconfigure(1, weight=1)
        body.grid_rowconfigure(0, weight=1)

        left = ctk.CTkFrame(body)
        left.grid(row=0, column=0, sticky="nsew", padx=(0,8))
        left.grid_rowconfigure(1, weight=1)
        left.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(left, text="Pack-Leader Dashboard", font=ctk.CTkFont(size=15, weight="bold")).grid(row=0, column=0, sticky="w", padx=10, pady=(10,4))
        self._dash = ctk.CTkTextbox(left, wrap="word")
        self._dash.grid(row=1, column=0, sticky="nsew", padx=10, pady=(0,10))

        right = ctk.CTkFrame(body)
        right.grid(row=0, column=1, sticky="nsew", padx=(8,0))
        right.grid_rowconfigure(1, weight=1)
        right.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(right, text="Tamago Hatchery", font=ctk.CTkFont(size=15, weight="bold")).grid(row=0, column=0, sticky="w", padx=10, pady=(10,4))
        self._tam = ctk.CTkTextbox(right, wrap="word")
        self._tam.grid(row=1, column=0, sticky="nsew", padx=10, pady=(0,10))

        actions = ctk.CTkFrame(right, fg_color="transparent")
        actions.grid(row=2, column=0, sticky="ew", padx=10, pady=(0,10))
        ctk.CTkButton(actions, text="🍖 Feed", width=90, command=lambda: self._ui_feed()).pack(side="left", padx=(0,8))
        ctk.CTkButton(actions, text="🤲 Pet", width=90, command=lambda: self._ui_pet()).pack(side="left", padx=(0,8))
        ctk.CTkButton(actions, text="💤 Calm Mode", width=120, command=lambda: self.trigger_calm()).pack(side="left", padx=(0,8))
        ctk.CTkButton(actions, text="Save", width=90, command=lambda: self._ui_apply(save=True)).pack(side="right")

        def _refresh_loop():
            try:
                if not win.winfo_exists():
                    return
                self._render_dash()
                win.after(1000, _refresh_loop)
            except Exception:
                pass
        _refresh_loop()

    def _ui_pick_clip(self, filedialog):
        try:
            p = filedialog.askopenfilename(title="Select WAV clip", filetypes=[("WAV", "*.wav"), ("All files", "*.*")])
            if p:
                self.intercom_clip = p
                self._log(f"[Pet] Intercom clip set: {p}")
                self._ui_apply(save=True)
        except Exception as e:
            self._log(f"[Pet] Could not pick clip: {e}")

    def _ui_apply(self, save=False):
        try:
            self.enabled = bool(self._ui_enabled.get()) if hasattr(self, "_ui_enabled") else self.enabled
            if hasattr(self, "_ui_thr"):
                try:
                    self.threshold_db = float(self._ui_thr.get().strip())
                except Exception:
                    pass
            if save:
                try:
                    if hasattr(self.app, "_pet_save"):
                        self.app._pet_save()
                except Exception:
                    pass
        except Exception:
            pass

    def _ui_feed(self):
        self.pet.feed(25.0)
        try:
            if hasattr(self.app, "_pet_save"):
                self.app._pet_save()
        except Exception:
            pass

    def _ui_pet(self):
        self.pet.pet(12.0)
        try:
            if hasattr(self.app, "_porch_haptics") and getattr(self.app, "_porch_haptics", None):
                self.app._porch_haptics.emit("tamago_pet", meta={"ts": time.time()})
        except Exception:
            pass
        try:
            if hasattr(self.app, "_pet_save"):
                self.app._pet_save()
        except Exception:
            pass

    def _render_dash(self):
        # dashboard + tamago cards
        try:
            now = time.time()
            last10 = [(t,d) for (t,d) in self.window_barks if t >= now-600.0]
            lines = []
            lines.append("🐾 Mellow-Pack Protocol")
            lines.append(f"Last dB: {self.last_db:.1f}   Threshold: {self.threshold_db:.0f}")
            lines.append(f"Bark spikes (10m): {len(last10)}   Total spikes: {self.total_barks}")
            lines.append("")
            if last10:
                mx = max(d for (_,d) in last10)
                lines.append(f"Peak (10m): {mx:.1f} dB")
            else:
                lines.append("Peak (10m): —")
            lines.append("")
            lines.append("Auto actions:")
            lines.append(f"  Calm: {'ON' if self.auto_calm else 'OFF'}   Intercom: {'ON' if self.auto_intercom else 'OFF'}   Haptic: {'ON' if self.auto_haptic else 'OFF'}")
            lines.append("")
            if self.diffuser_device_id:
                lines.append(f"Diffuser device: {self.diffuser_device_id} (cmd: {self.diffuser_command})")
            else:
                lines.append("Diffuser device: (not set)")

            if hasattr(self, "_dash") and self._dash.winfo_exists():
                self._dash.delete("1.0","end")
                self._dash.insert("end","\n".join(lines))

            p = self.pet
            tam = []
            tam.append("🥚 Tamago Hatchery")
            tam.append(f"Name: {p.name}   Level: {p.level}")
            tam.append(f"Hunger: {p.hunger:5.1f}/100   Happiness: {p.happiness:5.1f}/100")
            tam.append(f"Serenity XP: {p.serenity_xp:7.1f}")
            tam.append(f"State: {'😱 Startled' if p.startled else '😌 Calm'}")
            tam.append("")
            tam.append("Tip: Keep the RV quiet → Serenity XP rises.")
            if hasattr(self, "_tam") and self._tam.winfo_exists():
                self._tam.delete("1.0","end")
                self._tam.insert("end","\n".join(tam))
        except Exception:
            pass


# ----------------- App integration (patches) -----------------
try:
    _PET_STATE_FILE = os.path.join("experiences", "sanctuary", "pets.json")
except Exception:
    _PET_STATE_FILE = "pets.json"

def _pet__load_json(path: str, default=None):
    try:
        return _porch__load_json(path, default=default)  # may exist in Porch
    except Exception:
        try:
            if not os.path.exists(path):
                return default
            with open(path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return default

def _pet__save_json(path: str, data):
    try:
        return _porch__save_json(path, data)  # may exist in Porch
    except Exception:
        try:
            os.makedirs(os.path.dirname(path), exist_ok=True)
        except Exception:
            pass
        try:
            with open(path, "w", encoding="utf-8") as f:
                json.dump(data, f, indent=2)
        except Exception:
            pass

def _pet__ensure(self):
    if getattr(self, "pet_guardian", None) is None:
        # load persisted state
        st = _pet__load_json(_PET_STATE_FILE, default={}) or {}
        pg = PorchPetGuardian(self)
        pg.load(st)
        self.pet_guardian = pg
        try:
            pg.start()
        except Exception:
            pass

def _pet_save(self):
    try:
        _pet__ensure(self)
        pg = getattr(self, "pet_guardian", None)
        if pg:
            _pet__save_json(_PET_STATE_FILE, pg.dump())
    except Exception:
        pass

def _pet_open(self):
    _pet__ensure(self)
    try:
        self.pet_guardian.open_window()
    except Exception as e:
        try:
            self._ui_log(f"[Pet] Could not open window: {e}")
        except Exception:
            pass

def _pet_status_text(self) -> str:
    _pet__ensure(self)
    pg = getattr(self, "pet_guardian", None)
    if not pg:
        return "[Pet] (not ready)"
    p = pg.pet
    now = time.time()
    last10 = len([(t,d) for (t,d) in pg.window_barks if t >= now-600.0])
    return (
        f"🐾 Pet Guardian\n"
        f"Enabled: {pg.enabled} | Threshold: {pg.threshold_db:.0f} dB | Last dB: {pg.last_db:.1f}\n"
        f"Bark spikes (10m): {last10} | Total spikes: {pg.total_barks}\n"
        f"Tamago: {p.name} L{p.level} | Hunger {p.hunger:.1f} | Happy {p.happiness:.1f} | Serenity {p.serenity_xp:.1f} | {'Startled' if p.startled else 'Calm'}"
    )

def _pet_feed(self):
    _pet__ensure(self)
    pg = getattr(self, "pet_guardian", None)
    if pg:
        pg.pet.feed(25.0)
        _pet_save(self)
        self._ui_log("[Pet] 🍖 Fed Tamago.")
    return True

def _pet_pet(self):
    _pet__ensure(self)
    pg = getattr(self, "pet_guardian", None)
    if pg:
        pg.pet.pet(12.0)
        try:
            if hasattr(self, "_porch_haptics") and getattr(self, "_porch_haptics", None):
                self._porch_haptics.emit("tamago_pet", meta={"ts": time.time()})
        except Exception:
            pass
        _pet_save(self)
        self._ui_log("[Pet] 🤲 You pet Tamago.")
    return True

def _pet_calm(self):
    _pet__ensure(self)
    pg = getattr(self, "pet_guardian", None)
    if pg:
        pg.trigger_calm()
    return True

def _pet_ping(self):
    _pet__ensure(self)
    pg = getattr(self, "pet_guardian", None)
    if pg:
        pg.focus_ping()
    return True

def _pet_clip(self, path: str):
    _pet__ensure(self)
    pg = getattr(self, "pet_guardian", None)
    if pg:
        pg.intercom_clip = path.strip()
        _pet_save(self)
        self._ui_log(f"[Pet] Intercom clip set: {pg.intercom_clip}")
    return True

# Patch IoT sensor recording to feed PetGuardian
try:
    _pet__iot_orig = InfinitePorch._iot_record_sensor  # type: ignore

    def _pet__iot_patched(self, payload: Dict[str, Any]) -> None:
        _pet__iot_orig(self, payload)
        try:
            _pet__ensure(self)
            pg = getattr(self, "pet_guardian", None)
            if pg and isinstance(payload, dict):
                sid = str(payload.get("sensor_id") or payload.get("id") or "sensor").strip()
                vals = payload.get("values") or {}
                pg.on_sensor(sid, vals)
                _pet_save(self)
        except Exception:
            pass

    InfinitePorch._iot_record_sensor = _pet__iot_patched  # type: ignore
except Exception:
    pass

# Patch __init__ so PetGuardian starts on startup
try:
    _pet__init_orig = InfinitePorch.__init__  # type: ignore

    def _pet__init_patched(self, *a, **kw):
        _pet__init_orig(self, *a, **kw)
        try:
            _pet__ensure(self)
            _pet_save(self)
        except Exception:
            pass

    InfinitePorch.__init__ = _pet__init_patched  # type: ignore
except Exception:
    pass

# Patch slash commands
try:
    _pet__hsc_orig = InfinitePorch._handle_slash_command  # type: ignore

    def _pet__hsc_patched(self, text: str):
        t = (text or "").strip()
        if t.startswith("/pet") or t.startswith("/pets"):
            parts = t.split()
            if len(parts) == 1:
                _pet_open(self)
                return True
            sub = parts[1].lower()
            if sub in ("open", "ui"):
                _pet_open(self); return True
            if sub in ("status", "info"):
                try: self._ui_log(_pet_status_text(self))
                except Exception: pass
                return True
            if sub == "feed":
                return _pet_feed(self)
            if sub == "pet":
                return _pet_pet(self)
            if sub in ("calm", "soothe"):
                return _pet_calm(self)
            if sub in ("ping", "chirp"):
                return _pet_ping(self)
            if sub in ("threshold","thr") and len(parts) >= 3:
                try:
                    _pet__ensure(self)
                    pg=getattr(self,"pet_guardian",None)
                    if pg: pg.threshold_db = float(parts[2]); _pet_save(self)
                    self._ui_log(f"[Pet] Threshold set → {float(parts[2]):.0f} dB")
                except Exception:
                    pass
                return True
            if sub == "clip" and len(parts) >= 3:
                return _pet_clip(self, " ".join(parts[2:]))
            # toggles
            if sub in ("monitor","enabled") and len(parts) >= 3:
                val = parts[2].lower() in ("on","true","1","yes")
                _pet__ensure(self); pg=getattr(self,"pet_guardian",None)
                if pg: pg.enabled = val; _pet_save(self)
                try: self._ui_log(f"[Pet] Guardian {'ON' if val else 'OFF'}")
                except Exception: pass
                return True
            return True
        return _pet__hsc_orig(self, text)

    InfinitePorch._handle_slash_command = _pet__hsc_patched  # type: ignore
except Exception:
    pass



# =============================================================================
# HARDWARE FORGE: KiCad + PCB Designer AI + Freerouting + Cyclone CNC
# =============================================================================
# Notes:
# - Designed to be OPTIONAL and safe: if KiCad/Freerouting/serial tools are missing,
#   Porch will still run and will show helpful diagnostics.
# - Generates projects into: WELL_DIR/hardware/
#
# References (for user docs only):
# - Freerouting CLI supports -de (input .dsn) and -do (output .ses) as documented in
#   freerouting/freerouting README. (See repo for details.)
# =============================================================================

import time
import datetime
import shutil as _shutil
import subprocess as _subprocess
from dataclasses import dataclass as _dataclass, field as _field

try:
    import serial as _serial  # type: ignore
except Exception:
    _serial = None

def _hw_now_utc_iso() -> str:
    # timezone-aware UTC timestamp (avoid datetime.utcnow deprecation)
    return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")

def _hw_slug(s: str) -> str:
    s = re.sub(r"[^a-zA-Z0-9_\- ]+", "", (s or "").strip())
    s = s.replace(" ", "_")
    s = re.sub(r"_+", "_", s).strip("_")
    return s.lower() or "project"

def _hw_safe_mkdir(p: str) -> str:
    os.makedirs(p, exist_ok=True)
    return p

def _hw_write_text(path: str, content: str) -> None:
    _hw_safe_mkdir(os.path.dirname(path))
    with open(path, "w", encoding="utf-8") as f:
        f.write(content)

def _hw_read_json(path: str, default):
    try:
        with open(path, "r", encoding="utf-8") as f:
            return json.load(f)
    except Exception:
        return default

def _hw_write_json(path: str, obj) -> None:
    _hw_safe_mkdir(os.path.dirname(path))
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, indent=2)

def _hw_guess_kicad_cli() -> Optional[str]:
    # Prefer PATH
    exe = _shutil.which("kicad-cli") or _shutil.which("kicad-cli.exe")
    if exe:
        return exe

    # Common Windows install paths (KiCad 6/7/8)
    candidates = []
    pf = os.environ.get("ProgramFiles", r"C:\Program Files")
    for ver in ["8.0", "7.0", "6.0"]:
        candidates.append(os.path.join(pf, "KiCad", ver, "bin", "kicad-cli.exe"))
    # Some installs use KiCad\bin\kicad-cli.exe (without version)
    candidates.append(os.path.join(pf, "KiCad", "bin", "kicad-cli.exe"))
    for c in candidates:
        if os.path.exists(c):
            return c
    return None

@_dataclass
class _HardwareForgeConfig:
    kicad_cli: Optional[str] = None
    freerouting_jar: Optional[str] = None
    java: Optional[str] = None
    cyclone_port: Optional[str] = None
    cyclone_baud: int = 115200
    # Default CNC controller is GRBL-like streaming; works for many Arduino+CNC-shield builds.
    cyclone_assume_grbl: bool = True

    def resolve(self):
        if not self.kicad_cli:
            self.kicad_cli = _hw_guess_kicad_cli()
        if not self.java:
            self.java = _shutil.which("java") or _shutil.which("java.exe")
        return self

class _KiCadWrapper:
    """
    Thin wrapper that prefers KiCad's pcbnew Python when available,
    otherwise uses kicad-cli for export operations.

    Important: pcbnew usually exists in KiCad's bundled Python, not standard Python.
    """
    def __init__(self, cfg: _HardwareForgeConfig):
        self.cfg = cfg
        self.pcbnew = None
        try:
            import pcbnew  # type: ignore
            self.pcbnew = pcbnew
        except Exception:
            self.pcbnew = None

    def has_pcbnew(self) -> bool:
        return self.pcbnew is not None

    def export_gerbers(self, pcb_path: str, out_dir: str) -> Dict[str, str]:
        out_dir = _hw_safe_mkdir(out_dir)
        if self.has_pcbnew():
            # Keep it conservative: use CLI for gerbers even if pcbnew exists, because
            # plot params vary widely across KiCad versions.
            pass
        if not self.cfg.kicad_cli:
            raise RuntimeError("kicad-cli not found. Set it in Hardware Forge → KiCad Setup.")
        cmd = [self.cfg.kicad_cli, "pcb", "export", "gerbers", "-o", out_dir, pcb_path]
        _subprocess.check_call(cmd)
        # Drill export too
        cmd2 = [self.cfg.kicad_cli, "pcb", "export", "drill", "-o", out_dir, pcb_path]
        _subprocess.check_call(cmd2)
        return {"gerbers_dir": out_dir}

    def export_bom(self, sch_path: str, out_csv: str) -> Dict[str, str]:
        if not self.cfg.kicad_cli:
            raise RuntimeError("kicad-cli not found. Set it in Hardware Forge → KiCad Setup.")
        _hw_safe_mkdir(os.path.dirname(out_csv))
        cmd = [self.cfg.kicad_cli, "sch", "export", "bom", "-o", out_csv, sch_path]
        _subprocess.check_call(cmd)
        return {"bom_csv": out_csv}

class _FreeroutingRunner:
    def __init__(self, cfg: _HardwareForgeConfig):
        self.cfg = cfg

    def can_run(self) -> bool:
        return bool(self.cfg.java and self.cfg.freerouting_jar and os.path.exists(self.cfg.freerouting_jar))

    def route(self, dsn_path: str, ses_out: str, ignore_netclasses: Optional[List[str]] = None) -> Dict[str, str]:
        if not self.can_run():
            raise RuntimeError("Freerouting not configured. Set java + freerouting.jar in Hardware Forge → KiCad Setup.")
        _hw_safe_mkdir(os.path.dirname(ses_out))
        cmd = [self.cfg.java, "-jar", self.cfg.freerouting_jar, "-de", dsn_path, "-do", ses_out]
        if ignore_netclasses:
            cmd += ["-inc", ",".join(ignore_netclasses)]
        _subprocess.check_call(cmd)
        return {"ses": ses_out}

class _CycloneCNCController:
    """
    Simple GRBL-style G-code streamer (works with many Arduino+CNC-shield builds).
    If your Cyclone is driven by something else, you can still use this as a baseline.
    """
    def __init__(self, cfg: _HardwareForgeConfig):
        self.cfg = cfg

    def available(self) -> bool:
        return _serial is not None

    def stream_gcode(self, gcode_path: str, port: str, baud: int = 115200, on_line=None) -> Dict[str, str]:
        if _serial is None:
            raise RuntimeError("pyserial not installed. Install with: pip install pyserial")
        if not os.path.exists(gcode_path):
            raise FileNotFoundError(gcode_path)
        ser = _serial.Serial(port, baudrate=int(baud), timeout=2)
        try:
            # GRBL needs a short wake-up
            ser.write(b"\r\n\r\n")
            ser.flush()
            time.sleep(2)
            ser.reset_input_buffer()

            with open(gcode_path, "r", encoding="utf-8", errors="ignore") as f:
                for raw in f:
                    line = raw.strip()
                    if not line or line.startswith(";") or line.startswith("("):
                        continue
                    ser.write((line + "\n").encode("ascii", errors="ignore"))
                    ser.flush()
                    # Wait for ok
                    resp = ser.readline().decode("ascii", errors="ignore").strip()
                    if on_line:
                        on_line(line, resp)
            return {"status": "sent", "port": port, "file": gcode_path}
        finally:
            try:
                ser.close()
            except Exception:
                pass

class _ComponentLibraryManager:
    def __init__(self, base_dir: str):
        self.base_dir = base_dir
        self.map_path = os.path.join(base_dir, "libs", "component_map.json")
        self._data = _hw_read_json(self.map_path, default={"parts": {}, "updated": _hw_now_utc_iso()})

    def save(self):
        self._data["updated"] = _hw_now_utc_iso()
        _hw_write_json(self.map_path, self._data)

    def parts(self) -> Dict[str, Dict]:
        return self._data.setdefault("parts", {})

    def upsert(self, key: str, symbol: str = "", footprint: str = "", notes: str = ""):
        key = (key or "").strip()
        if not key:
            raise ValueError("Part name required")
        self.parts()[key] = {"symbol": symbol, "footprint": footprint, "notes": notes, "updated": _hw_now_utc_iso()}
        self.save()

    def delete(self, key: str):
        if key in self.parts():
            del self.parts()[key]
            self.save()

class _AssemblyGuideGenerator:
    def generate_markdown(self, project_dir: str, bom_csv: Optional[str], out_md: str) -> Dict[str, str]:
        lines = []
        lines.append("# Assembly Guide")
        lines.append("")
        lines.append(f"- Generated: `{_hw_now_utc_iso()}`")
        if bom_csv and os.path.exists(bom_csv):
            lines.append(f"- BOM: `{os.path.relpath(bom_csv, project_dir)}`")
        lines.append("")
        lines.append("## Tools")
        lines.append("- Soldering iron + solder")
        lines.append("- Tweezers, flush cutters")
        lines.append("- Multimeter (continuity)")
        lines.append("")
        lines.append("## Recommended Order")
        lines.append("1. Small passive parts (resistors/caps)")
        lines.append("2. ICs / sockets")
        lines.append("3. Headers / connectors")
        lines.append("4. Sensors")
        lines.append("5. Power stage (regulators/relays)")
        lines.append("")
        lines.append("## Checks")
        lines.append("- Visual inspection (bridges, polarity)")
        lines.append("- Continuity on power rails (no shorts)")
        lines.append("- First power-up with current-limited supply")
        _hw_write_text(out_md, "\n".join(lines) + "\n")
        return {"assembly_md": out_md}

    def generate_pdf(self, md_path: str, out_pdf: str) -> Optional[str]:
        # Optional: only if reportlab is available in environment
        try:
            from reportlab.lib.pagesizes import letter
            from reportlab.pdfgen import canvas
        except Exception:
            return None
        _hw_safe_mkdir(os.path.dirname(out_pdf))
        c = canvas.Canvas(out_pdf, pagesize=letter)
        w, h = letter
        y = h - 50
        c.setFont("Helvetica", 12)
        c.drawString(50, y, "Assembly Guide")
        y -= 30
        try:
            body = open(md_path, "r", encoding="utf-8", errors="ignore").read().splitlines()
        except Exception:
            body = ["(missing markdown)"]
        c.setFont("Helvetica", 10)
        for line in body:
            if y < 60:
                c.showPage()
                y = h - 50
                c.setFont("Helvetica", 10)
            c.drawString(50, y, line[:110])
            y -= 14
        c.save()
        return out_pdf

class _FirmwareTemplateSystem:
    def generate_platformio_esp32(self, out_dir: str, name: str, features: Optional[List[str]] = None) -> Dict[str, str]:
        out_dir = _hw_safe_mkdir(out_dir)
        features = features or []
        ini = f"""[env:esp32dev]
platform = espressif32
board = esp32dev
framework = arduino
monitor_speed = 115200

lib_deps =
    knolleary/PubSubClient@^2.8
    bblanchon/ArduinoJson@^7
"""
        main = f"""// Generated by Infinite Porch Hardware Forge
// Project: {name}
// Features: {", ".join(features) if features else "base"}

#include <Arduino.h>

void setup() {{
  Serial.begin(115200);
  delay(250);
  Serial.println("Hardware Forge firmware boot ✅");
}}

void loop() {{
  delay(1000);
}}
"""
        _hw_write_text(os.path.join(out_dir, "platformio.ini"), ini)
        _hw_write_text(os.path.join(out_dir, "src", "main.cpp"), main)
        return {"platformio_dir": out_dir}

class _TestingAutomation:
    def generate_test_plan(self, out_dir: str, project_name: str) -> Dict[str, str]:
        out_dir = _hw_safe_mkdir(out_dir)
        md = os.path.join(out_dir, "TEST_PLAN.md")
        content = f"""# Test Plan: {project_name}

Generated: {_hw_now_utc_iso()}

## Electrical
- Continuity: GND plane continuity
- Shorts: 3V3↔GND, 5V↔GND
- Regulator output stable under load

## Firmware
- Boot log appears on Serial 115200
- Sensor read loop returns plausible values
- Watchdog safety (if used)

## Integration
- MQTT publish to local broker (if enabled)
- Home Assistant entity appears (Overseer)

## CNC (Cyclone)
- Dry-run (spindle off) with Z raised
- Home/limit switch check (if present)

"""
        _hw_write_text(md, content)
        return {"test_plan": md}

class _PorchHardwareForge:
    def __init__(self, app):
        self.app = app
        self.base_dir = _hw_safe_mkdir(os.path.join(WELL_DIR, "hardware"))
        self.projects_dir = _hw_safe_mkdir(os.path.join(self.base_dir, "projects"))
        self.exports_dir = _hw_safe_mkdir(os.path.join(self.base_dir, "exports"))
        self.cncs_dir = _hw_safe_mkdir(os.path.join(self.base_dir, "cnc"))
        self.cfg_path = os.path.join(self.base_dir, "hardware_forge_config.json")
        cfg_obj = _hw_read_json(self.cfg_path, default={})
        self.cfg = _HardwareForgeConfig(**{k: cfg_obj.get(k) for k in _HardwareForgeConfig().__dict__.keys() if k in cfg_obj}).resolve()
        self._save_cfg()

        self.kicad = _KiCadWrapper(self.cfg)
        self.freerouting = _FreeroutingRunner(self.cfg)
        self.cnc = _CycloneCNCController(self.cfg)
        self.lib = _ComponentLibraryManager(self.base_dir)
        self.assembly = _AssemblyGuideGenerator()
        self.fw = _FirmwareTemplateSystem()
        self.tests = _TestingAutomation()

    def _save_cfg(self):
        _hw_write_json(self.cfg_path, {
            "kicad_cli": self.cfg.kicad_cli,
            "freerouting_jar": self.cfg.freerouting_jar,
            "java": self.cfg.java,
            "cyclone_port": self.cfg.cyclone_port,
            "cyclone_baud": int(self.cfg.cyclone_baud),
            "cyclone_assume_grbl": bool(self.cfg.cyclone_assume_grbl),
            "updated": _hw_now_utc_iso(),
        })

    def doctor(self) -> str:
        lines = []
        lines.append("🏛️ Hardware Forge — Doctor")
        lines.append(f"- base_dir: {self.base_dir}")
        lines.append(f"- kicad-cli: {self.cfg.kicad_cli or '(not found)'}")
        lines.append(f"- pcbnew (KiCad Python): {'yes' if self.kicad.has_pcbnew() else 'no'}")
        lines.append(f"- java: {self.cfg.java or '(not found)'}")
        lines.append(f"- freerouting.jar: {self.cfg.freerouting_jar or '(not set)'}")
        lines.append(f"- pyserial: {'yes' if _serial is not None else 'no'}")
        lines.append(f"- cyclone_port: {self.cfg.cyclone_port or '(not set)'}")
        return "\n".join(lines)

    def new_project(self, name: str, concept: str) -> Dict[str, str]:
        slug = _hw_slug(name)
        proj_dir = _hw_safe_mkdir(os.path.join(self.projects_dir, slug))
        stamp = _hw_now_utc_iso()

        spec = {
            "name": name,
            "slug": slug,
            "created": stamp,
            "concept": concept,
            "components": [],
            "nets": [],
            "notes": "",
        }
        _hw_write_json(os.path.join(proj_dir, "spec.json"), spec)
        _hw_write_text(os.path.join(proj_dir, "spec.md"),
f"""# {name}

Created: {stamp}

## Concept
{concept}

## Next Steps
1. Use **Hardware Forge → PCB Designer AI** to generate a component/netlist draft.
2. Open the project in **KiCad** and refine schematic/footprints.
3. Export DSN → run **Freerouting** → import SES.
4. Export Gerbers/Drill → generate CNC toolpaths (FlatCAM/RapidPCB) → stream to Cyclone.

""")

        # Minimal KiCad stubs (openable, but intentionally empty)
        prj = os.path.join(proj_dir, f"{slug}.kicad_pro")
        sch = os.path.join(proj_dir, f"{slug}.kicad_sch")
        pcb = os.path.join(proj_dir, f"{slug}.kicad_pcb")
        _hw_write_text(prj, self._kicad_pro_template(slug))
        _hw_write_text(sch, self._kicad_sch_template(name))
        _hw_write_text(pcb, self._kicad_pcb_template(name))
        return {"project_dir": proj_dir, "kicad_pro": prj, "kicad_sch": sch, "kicad_pcb": pcb}

    def _kicad_pro_template(self, slug: str) -> str:
        # Minimal project JSON (KiCad 6/7/8 tolerate extra fields)
        return json.dumps({
            "meta": {"filename": f"{slug}.kicad_pro", "version": 1},
            "project": {
                "files": {
                    "schematic": f"{slug}.kicad_sch",
                    "board": f"{slug}.kicad_pcb"
                }
            }
        }, indent=2) + "\n"

    def _kicad_sch_template(self, title: str) -> str:
        uid = str(uuid.uuid4())
        return f"""(kicad_sch (version 20231120) (generator "porch-hardware-forge")
  (uuid "{uid}")
  (paper "A4")
  (title_block
    (title "{title}")
    (date "{_hw_now_utc_iso()}")
    (rev "A")
    (company "Parallax / Infinite Porch")
  )
  (lib_symbols)
  (sheet_instances
    (path "/" (page "1"))
  )
  (symbol_instances)
)
"""

    def _kicad_pcb_template(self, title: str) -> str:
        uid = str(uuid.uuid4())
        # Basic layer set for 2-layer boards
        layers = """(layers
    (0 "F.Cu" signal)
    (31 "B.Cu" signal)
    (32 "B.Adhes" user)
    (33 "F.Adhes" user)
    (34 "B.Paste" user)
    (35 "F.Paste" user)
    (36 "B.SilkS" user)
    (37 "F.SilkS" user)
    (38 "B.Mask" user)
    (39 "F.Mask" user)
    (40 "Dwgs.User" user)
    (41 "Cmts.User" user)
    (42 "Eco1.User" user)
    (43 "Eco2.User" user)
    (44 "Edge.Cuts" user)
    (45 "Margin" user)
    (46 "B.CrtYd" user)
    (47 "F.CrtYd" user)
    (48 "B.Fab" user)
    (49 "F.Fab" user)
  )"""
        return f"""(kicad_pcb (version 20240108) (generator "porch-hardware-forge")
  (uuid "{uid}")
  (general (thickness 1.6))
  (paper "A4")
  {layers}
  (setup (pad_to_mask_clearance 0.0))
  (net 0 "")
  (gr_rect (start 0 0) (end 60 40) (layer "Edge.Cuts") (width 0.15) (fill none))
)
"""

    def pcb_ai_prompt(self, project_dir: str) -> str:
        spec_path = os.path.join(project_dir, "spec.json")
        spec = _hw_read_json(spec_path, default={})
        prompt = f"""# PCB Designer AI Prompt (KiCad)

You are an expert PCB designer.
Goal: produce a practical KiCad schematic + PCB plan.

Project:
- Name: {spec.get("name")}
- Concept: {spec.get("concept")}

Deliverables:
1) Component list (with suggested symbols + footprints)
2) Netlist (nets + which pins connect)
3) Board outline suggestion (mm)
4) Power tree (5V/3V3, protection)
5) Notes for noise/EMI and trace width guidance
6) If sensors: suggested placement and keepouts

Output format (JSON):
{{
  "components":[{{"ref":"U1","value":"ESP32","symbol":"...","footprint":"...","notes":""}}, ...],
  "nets":[{{"name":"3V3","pins":["U1:3V3","C1:1", ...]}}, ...],
  "outline_mm":[60,40],
  "notes":"..."
}}

"""
        out = os.path.join(project_dir, "pcb_ai_prompt.md")
        _hw_write_text(out, prompt)
        return out

    def apply_ai_output(self, project_dir: str, ai_json_path: str) -> Dict[str, str]:
        spec_path = os.path.join(project_dir, "spec.json")
        spec = _hw_read_json(spec_path, default={})
        ai = _hw_read_json(ai_json_path, default={})
        if "components" in ai:
            spec["components"] = ai["components"]
        if "nets" in ai:
            spec["nets"] = ai["nets"]
        if "notes" in ai:
            spec["notes"] = ai["notes"]
        spec["updated"] = _hw_now_utc_iso()
        _hw_write_json(spec_path, spec)
        return {"spec_json": spec_path}

    def generate_assembly(self, project_dir: str, bom_csv: Optional[str] = None) -> Dict[str, str]:
        out_md = os.path.join(project_dir, "ASSEMBLY_GUIDE.md")
        res = self.assembly.generate_markdown(project_dir, bom_csv, out_md)
        out_pdf = os.path.join(project_dir, "ASSEMBLY_GUIDE.pdf")
        pdf = self.assembly.generate_pdf(out_md, out_pdf)
        if pdf:
            res["assembly_pdf"] = pdf
        return res

    def generate_firmware_templates(self, project_dir: str) -> Dict[str, str]:
        name = os.path.basename(project_dir)
        out = os.path.join(project_dir, "firmware", "esp32_platformio")
        return self.fw.generate_platformio_esp32(out, name=name, features=["mqtt-ready"])

    def generate_tests(self, project_dir: str) -> Dict[str, str]:
        name = os.path.basename(project_dir)
        out = os.path.join(project_dir, "tests")
        return self.tests.generate_test_plan(out, project_name=name)

# -----------------------------------------------------------------------------
# InfinitePorch integration (monkey patches) — keeps base file stable
# -----------------------------------------------------------------------------

def _ip__ensure_hardware_forge(self):
    if getattr(self, "hardware_forge", None) is None:
        try:
            self.hardware_forge = _PorchHardwareForge(self)
        except Exception as e:
            self.hardware_forge = None
            self._ui_log(f"[Hardware] init failed: {e}", dim=True)
    return getattr(self, "hardware_forge", None)

def _ip_open_hardware_forge(self):
    hf = _ip__ensure_hardware_forge(self)
    if not hf:
        return
    try:
        top = ctk.CTkToplevel(self.root)
        top.title("🏛️ Hardware Forge (KiCad / Routing / CNC)")
        top.geometry("980x640")
        top.grab_set()

        header = ctk.CTkFrame(top)
        header.pack(fill="x", padx=10, pady=(10, 6))
        ctk.CTkLabel(header, text="🏛️ Hardware Forge", font=ctk.CTkFont(size=18, weight="bold")).pack(side="left", padx=(10, 6), pady=10)

        body = ctk.CTkFrame(top)
        body.pack(fill="both", expand=True, padx=10, pady=10)

        tabs = ctk.CTkTabview(body)
        tabs.pack(fill="both", expand=True)

        tab_diag = tabs.add("Doctor")
        tab_proj = tabs.add("Projects")
        tab_lib = tabs.add("Library")
        tab_tools = tabs.add("Tools")
        tab_cnc = tabs.add("Cyclone CNC")

        # Doctor
        diag_txt = ctk.CTkTextbox(tab_diag, wrap="word")
        diag_txt.pack(fill="both", expand=True, padx=10, pady=10)
        diag_txt.insert("end", hf.doctor())

        # Projects
        row = ctk.CTkFrame(tab_proj)
        row.pack(fill="x", padx=10, pady=10)
        ctk.CTkLabel(row, text="New project name:").pack(side="left", padx=(0,6))
        name_entry = ctk.CTkEntry(row, width=240)
        name_entry.pack(side="left", padx=(0,10))
        name_entry.insert(0, "new_board")

        concept_entry = ctk.CTkEntry(row, width=520)
        concept_entry.pack(side="left", padx=(0,10))
        concept_entry.insert(0, "Describe the board you want (sensors, power, comms)...")

        def _create():
            name = name_entry.get().strip()
            concept = concept_entry.get().strip()
            try:
                res = hf.new_project(name, concept)
                self._ui_log(f"[Hardware] Created project: {res['project_dir']}")
            except Exception as e:
                self._ui_log(f"[Hardware] create failed: {e}", dim=True)

        ctk.CTkButton(row, text="Create", command=_create, width=110).pack(side="left")

        # List projects
        proj_list = ctk.CTkTextbox(tab_proj, wrap="none")
        proj_list.pack(fill="both", expand=True, padx=10, pady=(0,10))
        def _refresh_projects():
            proj_list.delete("1.0","end")
            try:
                items = sorted([d for d in os.listdir(hf.projects_dir) if os.path.isdir(os.path.join(hf.projects_dir,d))])
                for d in items:
                    proj_list.insert("end", os.path.join(hf.projects_dir, d) + "\n")
            except Exception as e:
                proj_list.insert("end", f"(error) {e}\n")
        _refresh_projects()

        # Library
        lib_box = ctk.CTkTextbox(tab_lib, wrap="none")
        lib_box.pack(fill="both", expand=True, padx=10, pady=10)

        def _refresh_lib():
            lib_box.delete("1.0","end")
            parts = hf.lib.parts()
            if not parts:
                lib_box.insert("end","(empty)\n")
                return
            for k,v in sorted(parts.items()):
                lib_box.insert("end", f"{k} | sym={v.get('symbol','')} | fp={v.get('footprint','')} | notes={v.get('notes','')}\n")
        _refresh_lib()

        lib_row = ctk.CTkFrame(tab_lib)
        lib_row.pack(fill="x", padx=10, pady=(0,10))
        p_name = ctk.CTkEntry(lib_row, width=200); p_name.pack(side="left", padx=(0,6)); p_name.insert(0,"BME680")
        p_sym = ctk.CTkEntry(lib_row, width=220); p_sym.pack(side="left", padx=(0,6)); p_sym.insert(0,"Sensor_Gas:BME680")
        p_fp = ctk.CTkEntry(lib_row, width=220); p_fp.pack(side="left", padx=(0,6)); p_fp.insert(0,"Package_LGA:LGA-8_3x3mm_P0.8mm")
        def _add_part():
            try:
                hf.lib.upsert(p_name.get(), p_sym.get(), p_fp.get(), "")
                _refresh_lib()
                self._ui_log(f"[Hardware] Saved component map for {p_name.get()}")
            except Exception as e:
                self._ui_log(f"[Hardware] library error: {e}", dim=True)
        ctk.CTkButton(lib_row, text="Upsert", command=_add_part, width=110).pack(side="left")

        # Tools
        tools_txt = ctk.CTkTextbox(tab_tools, wrap="word")
        tools_txt.pack(fill="both", expand=True, padx=10, pady=10)
        tools_txt.insert("end",
"""Tools:
- Generate PCB AI prompt: creates pcb_ai_prompt.md inside a project folder
- Apply AI output: merges agent_output.json into spec.json
- Assembly guide: creates ASSEMBLY_GUIDE.md (+ optional PDF)
- Firmware templates: creates PlatformIO ESP32 skeleton
- Test automation: creates TEST_PLAN.md

Tip: Use /pcb commands from the main chat too.
""")

        tool_row = ctk.CTkFrame(tab_tools)
        tool_row.pack(fill="x", padx=10, pady=(0,10))
        proj_entry = ctk.CTkEntry(tool_row, width=540)
        proj_entry.pack(side="left", padx=(0,8))
        proj_entry.insert(0, hf.projects_dir)

        def _pick_latest():
            try:
                items = sorted([os.path.join(hf.projects_dir,d) for d in os.listdir(hf.projects_dir) if os.path.isdir(os.path.join(hf.projects_dir,d))], key=os.path.getmtime)
                if items:
                    proj_entry.delete(0,"end"); proj_entry.insert(0, items[-1])
            except Exception:
                pass
        ctk.CTkButton(tool_row, text="Use latest", command=_pick_latest, width=110).pack(side="left", padx=(0,8))

        def _do_prompt():
            p = proj_entry.get().strip()
            try:
                out = hf.pcb_ai_prompt(p)
                self._ui_log(f"[Hardware] Wrote: {out}")
            except Exception as e:
                self._ui_log(f"[Hardware] prompt error: {e}", dim=True)
        ctk.CTkButton(tool_row, text="AI Prompt", command=_do_prompt, width=110).pack(side="left", padx=(0,8))

        def _do_asm():
            p = proj_entry.get().strip()
            try:
                res = hf.generate_assembly(p, bom_csv=None)
                self._ui_log(f"[Hardware] Assembly: {res}")
            except Exception as e:
                self._ui_log(f"[Hardware] assembly error: {e}", dim=True)
        ctk.CTkButton(tool_row, text="Assembly", command=_do_asm, width=110).pack(side="left", padx=(0,8))

        def _do_fw():
            p = proj_entry.get().strip()
            try:
                res = hf.generate_firmware_templates(p)
                self._ui_log(f"[Hardware] Firmware templates: {res}")
            except Exception as e:
                self._ui_log(f"[Hardware] firmware error: {e}", dim=True)
        ctk.CTkButton(tool_row, text="Firmware", command=_do_fw, width=110).pack(side="left", padx=(0,8))

        def _do_tests():
            p = proj_entry.get().strip()
            try:
                res = hf.generate_tests(p)
                self._ui_log(f"[Hardware] Tests: {res}")
            except Exception as e:
                self._ui_log(f"[Hardware] tests error: {e}", dim=True)
        ctk.CTkButton(tool_row, text="Tests", command=_do_tests, width=110).pack(side="left")

        # CNC
        cnc_top = ctk.CTkFrame(tab_cnc)
        cnc_top.pack(fill="x", padx=10, pady=10)
        ctk.CTkLabel(cnc_top, text="COM Port:").pack(side="left", padx=(0,6))
        port_entry = ctk.CTkEntry(cnc_top, width=160); port_entry.pack(side="left", padx=(0,10))
        port_entry.insert(0, hf.cfg.cyclone_port or "COM3")
        ctk.CTkLabel(cnc_top, text="Baud:").pack(side="left", padx=(0,6))
        baud_entry = ctk.CTkEntry(cnc_top, width=100); baud_entry.pack(side="left", padx=(0,10))
        baud_entry.insert(0, str(hf.cfg.cyclone_baud))

        gcode_entry = ctk.CTkEntry(cnc_top, width=420); gcode_entry.pack(side="left", padx=(0,10))
        gcode_entry.insert(0, os.path.join(hf.cncs_dir, "job.gcode"))

        cnc_log = ctk.CTkTextbox(tab_cnc, wrap="none")
        cnc_log.pack(fill="both", expand=True, padx=10, pady=(0,10))

        def _stream():
            p = gcode_entry.get().strip()
            port = port_entry.get().strip()
            baud = int(baud_entry.get().strip() or "115200")
            try:
                cnc_log.insert("end", f"Streaming {p} → {port} @ {baud}\n")
                cnc_log.see("end")
                def on_line(line, resp):
                    cnc_log.insert("end", f"{line}  =>  {resp}\n")
                    cnc_log.see("end")
                    cnc_log.update_idletasks()
                res = hf.cnc.stream_gcode(p, port, baud=baud, on_line=on_line)
                cnc_log.insert("end", f"DONE: {res}\n")
            except Exception as e:
                cnc_log.insert("end", f"ERROR: {e}\n")
                cnc_log.see("end")
        ctk.CTkButton(cnc_top, text="Send G-code", command=_stream, width=140).pack(side="left")

    except Exception as e:
        self._ui_log(f"[Hardware] UI failed: {e}", dim=True)

def _ip_hw_kicad_setup_dialog(self):
    hf = _ip__ensure_hardware_forge(self)
    if not hf:
        return
    try:
        top = ctk.CTkToplevel(self.root)
        top.title("🏛️ Hardware Forge — KiCad Setup")
        top.geometry("760x420")
        top.grab_set()

        frm = ctk.CTkFrame(top)
        frm.pack(fill="both", expand=True, padx=12, pady=12)

        def row(lbl, val, width=520):
            r = ctk.CTkFrame(frm); r.pack(fill="x", pady=6)
            ctk.CTkLabel(r, text=lbl, width=160, anchor="w").pack(side="left")
            e = ctk.CTkEntry(r, width=width); e.pack(side="left", padx=(0,8))
            e.insert(0, val or "")
            return e

        e_kicad = row("kicad-cli path", hf.cfg.kicad_cli or _hw_guess_kicad_cli() or "")
        e_java  = row("java path", hf.cfg.java or (_shutil.which("java") or ""))
        e_free  = row("freerouting.jar path", hf.cfg.freerouting_jar or "")
        e_port  = row("Cyclone COM port", hf.cfg.cyclone_port or "")
        e_baud  = row("Cyclone baud", str(hf.cfg.cyclone_baud), width=200)

        def _save():
            hf.cfg.kicad_cli = e_kicad.get().strip() or None
            hf.cfg.java = e_java.get().strip() or None
            hf.cfg.freerouting_jar = e_free.get().strip() or None
            hf.cfg.cyclone_port = e_port.get().strip() or None
            try:
                hf.cfg.cyclone_baud = int(e_baud.get().strip() or "115200")
            except Exception:
                hf.cfg.cyclone_baud = 115200
            hf.cfg.resolve()
            hf._save_cfg()
            # refresh wrappers
            hf.kicad = _KiCadWrapper(hf.cfg)
            hf.freerouting = _FreeroutingRunner(hf.cfg)
            hf.cnc = _CycloneCNCController(hf.cfg)
            self._ui_log("[Hardware] Saved Hardware Forge config ✅")
            try:
                top.destroy()
            except Exception:
                pass

        ctk.CTkButton(frm, text="Save", command=_save, width=120).pack(anchor="e", pady=(12,0))
    except Exception as e:
        self._ui_log(f"[Hardware] setup dialog error: {e}", dim=True)

