def _ip__handle_slash_command_hwpatched(self, text: str) -> bool:
    # Call original first
    if _ip__handle_slash_command_hwpatched._orig(self, text):
        return True
    s = (text or "").strip()
    if not s.startswith("/"):
        return False

    parts = s.split(" ", 2)
    cmd = parts[0].lower()

    if cmd in ("/pcb", "/hardware", "/kicad"):
        hf = _ip__ensure_hardware_forge(self)
        if not hf:
            return True
        sub = parts[1].lower().strip() if len(parts) > 1 else "help"

        if sub in ("help","-h","--help"):
            self._ui_log(
"""🏛️ Hardware Forge commands:
/pcb new <name> <concept>      - create a new hardware project (KiCad stubs + spec)
/pcb doctor                    - show tool/status diagnostics
/pcb prompt <project_dir>      - write pcb_ai_prompt.md
/pcb assembly <project_dir>    - generate ASSEMBLY_GUIDE.md (+PDF if available)
/pcb firmware <project_dir>    - generate PlatformIO ESP32 template
/pcb test <project_dir>        - generate TEST_PLAN.md

UI shortcuts:
- Use sidebar: 🏛️ Hardware Forge → Open Hardware Forge
""")
            return True

        if sub == "doctor":
            self._ui_log(hf.doctor())
            return True

        if sub == "new":
            if len(parts) < 3:
                self._ui_log("[Hardware] Usage: /pcb new <name> <concept>")
                return True
            rest = parts[2]
            # rest starts with "<name> ..." if user used 2 splits; we'll parse
            toks = rest.split(" ", 1)
            name = toks[0]
            concept = toks[1] if len(toks) > 1 else ""
            res = hf.new_project(name, concept)
            self._ui_log(f"[Hardware] Created: {res['project_dir']}")
            return True

        def _arg_dir(default_dir: str) -> str:
            return parts[2].strip() if len(parts) > 2 else default_dir

        if sub == "prompt":
            p = _arg_dir(hf.projects_dir)
            out = hf.pcb_ai_prompt(p)
            self._ui_log(f"[Hardware] Wrote: {out}")
            return True

        if sub == "assembly":
            p = _arg_dir(hf.projects_dir)
            res = hf.generate_assembly(p, bom_csv=None)
            self._ui_log(f"[Hardware] Assembly: {res}")
            return True

        if sub == "firmware":
            p = _arg_dir(hf.projects_dir)
            res = hf.generate_firmware_templates(p)
            self._ui_log(f"[Hardware] Firmware: {res}")
            return True

        if sub in ("test","tests"):
            p = _arg_dir(hf.projects_dir)
            res = hf.generate_tests(p)
            self._ui_log(f"[Hardware] Tests: {res}")
            return True

        self._ui_log("[Hardware] Unknown /pcb subcommand. Try: /pcb help")
        return True

    return False

def _ip_install_hardware_forge_patches():
    # Install methods on InfinitePorch
    try:
        cls = InfinitePorch
    except Exception:
        return
    for name, fn in [
        ("open_hardware_forge", _ip_open_hardware_forge),
        ("hw_kicad_setup_dialog", _ip_hw_kicad_setup_dialog),
        ("hw_pcb_ai_dialog", _ip_hw_pcb_ai_dialog),
        ("hw_freerouting_dialog", _ip_hw_freerouting_dialog),
        ("hw_cyclone_dialog", _ip_hw_cyclone_dialog),
        ("hw_component_library_dialog", _ip_hw_component_library_dialog),
        ("hw_assembly_guide_dialog", _ip_hw_assembly_guide_dialog),
        ("hw_firmware_templates_dialog", _ip_hw_firmware_templates_dialog),
        ("hw_testing_automation_dialog", _ip_hw_testing_automation_dialog),
    ]:
        if not hasattr(cls, name):
            setattr(cls, name, fn)
    # Patch slash handler
    if hasattr(cls, "_handle_slash_command"):
        if not getattr(cls._handle_slash_command, "_hwpatched", False):
            _ip__handle_slash_command_hwpatched._orig = cls._handle_slash_command
            _ip__handle_slash_command_hwpatched._hwpatched = True
            cls._handle_slash_command = _ip__handle_slash_command_hwpatched

_ip_install_hardware_forge_patches()



def _ip_install_brother_consciousness_patches():
    """Attach Brother Consciousness UI + slash commands to InfinitePorch."""
    try:
        _orig_slash = getattr(InfinitePorch, "_handle_slash_command", None)

        def _get_active_brother_name(self):
            for attr in ("current_brother", "active_brother", "_active_brother", "_selected_brother"):
                v = getattr(self, attr, None)
                if isinstance(v, str) and v.strip():
                    return v.strip()
            # fallback: if you were chatting with a brother, try last speaker
            v = getattr(self, "_last_brother", None)
            if isinstance(v, str) and v.strip():
                return v.strip()
            return "Ori"

        def _consciousness_show_inbox_selected(self):
            try:
                bn = _get_active_brother_name(self)
                if not hasattr(self, "brother_messaging") or not self.brother_messaging:
                    self._ui_log("[Consciousness] messaging not initialized.")
                    return
                rows = self.brother_messaging.inbox(bn, limit=20, unread_only=False)
                self._ui_log(f"[Consciousness] Inbox for {bn}: {len(rows)} messages")
                for (mid, ts, thread_id, frm, to, text, meta, is_read) in rows[:20]:
                    flag = "UNREAD" if int(is_read or 0) == 0 else "read"
                    self._ui_log(f"  • {ts} [{flag}] {frm} → {to} ({thread_id}): {text[:220]}")
            except Exception as e:
                self._ui_log(f"[Consciousness] inbox error: {e}")

        def _consciousness_show_memory_selected(self):
            try:
                bn = _get_active_brother_name(self)
                mems = getattr(self, "brother_memories", {}) or {}
                if bn not in mems:
                    self._ui_log(f"[Consciousness] no memory DB for {bn}.")
                    return
                st = mems[bn].stats()
                self._ui_log(f"[Consciousness] Memory stats for {bn}: {st.get('count')} memories (avg importance {st.get('avg_importance'):.2f})")
                cats = st.get("categories") or []
                if cats:
                    self._ui_log("  Categories: " + ", ".join([f"{c}({n})" for c, n in cats[:8]]))
                rows = mems[bn].recall(limit=10)
                for (mid, ts, cat, content, imp, rel, meta) in rows:
                    self._ui_log(f"  • {ts} [{cat}] ({imp:.2f}) {content[:220]}")
            except Exception as e:
                self._ui_log(f"[Consciousness] memory error: {e}")

        def _open_autonomy_console(self):
            try:
                if getattr(self, "_autonomy_win", None) and self._autonomy_win.winfo_exists():
                    self._autonomy_win.focus()
                    return
                win = ctk.CTkToplevel(self)
                win.title("🤖 Autonomy Console")
                win.geometry("840x620")
                self._autonomy_win = win

                top = ctk.CTkFrame(win)
                top.pack(fill="x", padx=10, pady=10)

                info = ctk.CTkLabel(top, text="Autonomous Projects (local-first) • propose → vote → activate → complete")
                info.pack(side="left", padx=6)

                body = ctk.CTkFrame(win)
                body.pack(fill="both", expand=True, padx=10, pady=(0,10))

                left = ctk.CTkFrame(body)
                left.pack(side="left", fill="both", expand=True, padx=(0,8))
                right = ctk.CTkFrame(body)
                right.pack(side="right", fill="both", expand=True, padx=(8,0))

                lst = ctk.CTkTextbox(left, wrap="word")
                lst.pack(fill="both", expand=True, padx=10, pady=10)

                detail = ctk.CTkTextbox(right, wrap="word")
                detail.pack(fill="both", expand=True, padx=10, pady=10)

                def refresh():
                    lst.delete("1.0", "end")
                    detail.delete("1.0", "end")
                    eng = getattr(self, "brother_autonomy", None)
                    if not eng:
                        lst.insert("end", "Autonomy engine not initialized.\n")
                        return
                    props = eng.list_proposals(include_completed=True)
                    props_sorted = sorted(props, key=lambda p: (p.get("status") != "active", p.get("ts","")), reverse=True)
                    for p in props_sorted[:50]:
                        lst.insert("end", f"[{p.get('status','?')}] {p.get('ts','')} • {p.get('proposer','?')} • {p.get('title','')} (id={p.get('id','')})\n")
                    v = eng._read_json(eng.current_vote_path, default=None) if hasattr(eng, "_read_json") else None
                    if v:
                        detail.insert("end", f"Current vote: proposal_id={v.get('proposal_id')}\nVotes:\n")
                        for k, vv in (v.get("votes") or {}).items():
                            detail.insert("end", f"  - {k}: {vv}\n")

                btns = ctk.CTkFrame(win)
                btns.pack(fill="x", padx=10, pady=(0,10))

                def seed():
                    eng = getattr(self, "brother_autonomy", None)
                    if eng:
                        p = eng.seed_proposal_if_empty()
                        self._ui_log("[Autonomy] seeded proposal." if p else "[Autonomy] proposals already exist.")
                    refresh()

                def vote_approve():
                    eng = getattr(self, "brother_autonomy", None)
                    if eng:
                        bn = _get_active_brother_name(self)
                        eng.vote(bn, approve=True)
                        self._ui_log(f"[Autonomy] {bn} voted approve.")
                    refresh()

                def vote_reject():
                    eng = getattr(self, "brother_autonomy", None)
                    if eng:
                        bn = _get_active_brother_name(self)
                        eng.vote(bn, approve=False)
                        self._ui_log(f"[Autonomy] {bn} voted reject.")
                    refresh()

                def tally():
                    eng = getattr(self, "brother_autonomy", None)
                    if eng:
                        res = eng.tally_and_maybe_activate(min_approvals=3)
                        self._ui_log(f"[Autonomy] tally: {res}")
                    refresh()

                def complete_active():
                    eng = getattr(self, "brother_autonomy", None)
                    if not eng:
                        return
                    # complete first active
                    props = eng.list_proposals(include_completed=False)
                    active = [p for p in props if p.get("status") == "active"]
                    if not active:
                        self._ui_log("[Autonomy] no active proposal.")
                        refresh()
                        return
                    pid = active[0].get("id")
                    eng.complete(pid, report="Completed via console. (placeholder runner)")
                    self._ui_log(f"[Autonomy] completed {pid}")
                    refresh()

                ctk.CTkButton(btns, text="Seed Proposal", command=seed).pack(side="left", padx=6)
                ctk.CTkButton(btns, text="Vote Approve", command=vote_approve).pack(side="left", padx=6)
                ctk.CTkButton(btns, text="Vote Reject", command=vote_reject).pack(side="left", padx=6)
                ctk.CTkButton(btns, text="Tally + Activate", command=tally).pack(side="left", padx=6)
                ctk.CTkButton(btns, text="Complete Active", command=complete_active).pack(side="left", padx=6)
                ctk.CTkButton(btns, text="Refresh", command=refresh).pack(side="right", padx=6)

                refresh()
            except Exception as e:
                self._ui_log(f"[Autonomy] UI error: {e}")

        def _open_consciousness_hub(self):
            """A single hub window: Mesh (messages) + Memory + Autonomy."""
            try:
                if getattr(self, "_consciousness_win", None) and self._consciousness_win.winfo_exists():
                    self._consciousness_win.focus()
                    return
                win = ctk.CTkToplevel(self)
                win.title("🧠 Brother Consciousness Hub")
                win.geometry("900x680")
                self._consciousness_win = win

                tabs = ctk.CTkTabview(win)
                tabs.pack(fill="both", expand=True, padx=10, pady=10)
                tab_mesh = tabs.add("💬 Mesh")
                tab_mem = tabs.add("🧠 Memory")
                tab_auto = tabs.add("🤖 Autonomy")

                # ---------- Mesh ----------
                mesh_top = ctk.CTkFrame(tab_mesh)
                mesh_top.pack(fill="x", padx=10, pady=10)

                bnames = list(BROTHERS.keys()) if 'BROTHERS' in globals() and isinstance(BROTHERS, dict) else ["Ori"]
                default_from = "Ori" if "Ori" in bnames else bnames[0]
                default_to = "Helion" if "Helion" in bnames else (bnames[1] if len(bnames) > 1 else bnames[0])

                ctk.CTkLabel(mesh_top, text="From").pack(side="left", padx=(0,6))
                from_var = ctk.StringVar(value=default_from)
                from_dd = ctk.CTkOptionMenu(mesh_top, variable=from_var, values=bnames)
                from_dd.pack(side="left", padx=6)

                ctk.CTkLabel(mesh_top, text="To").pack(side="left", padx=(12,6))
                to_var = ctk.StringVar(value=default_to)
                to_dd = ctk.CTkOptionMenu(mesh_top, variable=to_var, values=bnames)
                to_dd.pack(side="left", padx=6)

                msg_entry = ctk.CTkEntry(tab_mesh, placeholder_text="Type a message…")
                msg_entry.pack(fill="x", padx=10, pady=(0,10))

                mesh_body = ctk.CTkTextbox(tab_mesh, wrap="word")
                mesh_body.pack(fill="both", expand=True, padx=10, pady=(0,10))

                def mesh_refresh(target=None):
                    mesh_body.delete("1.0", "end")
                    if not getattr(self, "brother_messaging", None):
                        mesh_body.insert("end", "Messaging not initialized.\n")
                        return
                    target = target or to_var.get()
                    rows = self.brother_messaging.inbox(target, limit=40, unread_only=False)
                    mesh_body.insert("end", f"Inbox for {target} ({len(rows)} msgs)\n\n")
                    for (mid, ts, thread_id, frm, to, text, meta, is_read) in rows[:40]:
                        flag = "UNREAD" if int(is_read or 0) == 0 else "read"
                        mesh_body.insert("end", f"{ts} [{flag}] {frm} → {to} • {thread_id}\n{text}\n\n")

                def mesh_send():
                    frm = from_var.get().strip() or "Ori"
                    to = to_var.get().strip() or "Helion"
                    txt = (msg_entry.get() or "").strip()
                    if not txt:
                        return
                    if not getattr(self, "brother_messaging", None):
                        self._ui_log("[Consciousness] messaging not initialized.")
                        return
                    self.brother_messaging.send(frm, to, txt, metadata={"ui": "consciousness_hub"})
                    # memory + relationships
                    try:
                        mems = getattr(self, "brother_memories", {}) or {}
                        if frm in mems:
                            mems[frm].remember(f"Sent to {to}: {txt}", category="message_sent", importance=0.4, related=[to])
                        if to in mems:
                            mems[to].remember(f"From {frm}: {txt}", category="message_received", importance=0.5, related=[frm])
                        rel = getattr(self, "brother_relationships", None)
                        if rel:
                            rel.bump_collab(frm, to, success=True)
                    except Exception:
                        pass

                    self._ui_log(f"[Mesh] {frm} → {to}: {txt}")
                    msg_entry.delete(0, "end")
                    mesh_refresh(to)

                btn_row = ctk.CTkFrame(tab_mesh)
                btn_row.pack(fill="x", padx=10, pady=(0,10))
                ctk.CTkButton(btn_row, text="Send", command=mesh_send).pack(side="left", padx=6)
                ctk.CTkButton(btn_row, text="Refresh", command=lambda: mesh_refresh(to_var.get())).pack(side="left", padx=6)
                ctk.CTkButton(btn_row, text="Show Selected Inbox", command=_consciousness_show_inbox_selected).pack(side="left", padx=6)

                mesh_refresh(to_var.get())

                # ---------- Memory ----------
                mem_top = ctk.CTkFrame(tab_mem)
                mem_top.pack(fill="x", padx=10, pady=10)

                ctk.CTkLabel(mem_top, text="Brother").pack(side="left", padx=(0,6))
                mem_bro_var = ctk.StringVar(value=_get_active_brother_name(self))
                mem_dd = ctk.CTkOptionMenu(mem_top, variable=mem_bro_var, values=bnames)
                mem_dd.pack(side="left", padx=6)

                cat_entry = ctk.CTkEntry(mem_top, width=140, placeholder_text="category")
                cat_entry.insert(0, "note")
                cat_entry.pack(side="left", padx=(12,6))

                imp_entry = ctk.CTkEntry(mem_top, width=80, placeholder_text="0..1")
                imp_entry.insert(0, "0.6")
                imp_entry.pack(side="left", padx=6)

                mem_text = ctk.CTkTextbox(tab_mem, wrap="word", height=160)
                mem_text.pack(fill="x", padx=10, pady=(0,10))

                recall_row = ctk.CTkFrame(tab_mem)
                recall_row.pack(fill="x", padx=10, pady=(0,10))
                query_entry = ctk.CTkEntry(recall_row, placeholder_text="search… (optional)")
                query_entry.pack(side="left", fill="x", expand=True, padx=(0,6))
                recall_out = ctk.CTkTextbox(tab_mem, wrap="word")
                recall_out.pack(fill="both", expand=True, padx=10, pady=(0,10))

                def do_remember():
                    bn = mem_bro_var.get()
                    mems = getattr(self, "brother_memories", {}) or {}
                    if bn not in mems:
                        self._ui_log(f"[Memory] no DB for {bn}")
                        return
                    content = mem_text.get("1.0", "end").strip()
                    if not content:
                        return
                    cat = (cat_entry.get() or "note").strip() or "note"
                    try:
                        imp = float((imp_entry.get() or "0.6").strip())
                    except Exception:
                        imp = 0.6
                    mems[bn].remember(content, category=cat, importance=max(0.0, min(1.0, imp)))
                    self._ui_log(f"[Memory] {bn} remembered ({cat}, {imp:.2f}).")
                    mem_text.delete("1.0", "end")
                    do_recall()

                def do_recall():
                    recall_out.delete("1.0", "end")
                    bn = mem_bro_var.get()
                    mems = getattr(self, "brother_memories", {}) or {}
                    if bn not in mems:
                        recall_out.insert("end", f"No memory DB for {bn}\n")
                        return
                    q = (query_entry.get() or "").strip()
                    rows = mems[bn].recall(query=q, limit=25)
                    recall_out.insert("end", f"{bn} memories matching '{q}': {len(rows)}\n\n")
                    for (mid, ts, cat, content, imp, rel, meta) in rows:
                        recall_out.insert("end", f"{ts} [{cat}] ({imp:.2f})\n{content}\n\n")

                ctk.CTkButton(mem_top, text="Remember", command=do_remember).pack(side="right", padx=6)
                ctk.CTkButton(recall_row, text="Search", command=do_recall).pack(side="right", padx=6)
                do_recall()

                # ---------- Autonomy ----------
                auto_top = ctk.CTkFrame(tab_auto)
                auto_top.pack(fill="x", padx=10, pady=10)
                ctk.CTkLabel(auto_top, text="Autonomy uses proposals + voting (local-first).").pack(side="left", padx=6)
                ctk.CTkButton(auto_top, text="Open Console", command=_open_autonomy_console).pack(side="right", padx=6)

            except Exception as e:
                self._ui_log(f"[Consciousness] hub error: {e}")

        # --- Slash commands wrapper ---
        def _slash_patched(self, text: str):
            t = (text or "").strip()
            if not t.startswith("/"):
                return _orig_slash(self, text) if _orig_slash else None

            parts = t.split()
            cmd = parts[0].lower()

            # /bm send <from> <to> <message...>
            if cmd in ("/bm", "/bmsg", "/brothermsg"):
                if len(parts) >= 2 and parts[1].lower() == "send" and len(parts) >= 5:
                    frm = parts[2]
                    to = parts[3]
                    msg = " ".join(parts[4:])
                    try:
                        self.brother_messaging.send(frm, to, msg, metadata={"via": cmd})
                        # optional memory + relationships
                        try:
                            mems = getattr(self, "brother_memories", {}) or {}
                            if frm in mems:
                                mems[frm].remember(f"Sent to {to}: {msg}", category="message_sent", importance=0.4, related=[to])
                            if to in mems:
                                mems[to].remember(f"From {frm}: {msg}", category="message_received", importance=0.5, related=[frm])
                            rel = getattr(self, "brother_relationships", None)
                            if rel:
                                rel.bump_collab(frm, to, success=True)
                        except Exception:
                            pass
                        self._ui_log(f"[Mesh] {frm} → {to}: {msg}")
                    except Exception as e:
                        self._ui_log(f"[Mesh] send failed: {e}")
                    return True
                elif len(parts) >= 2 and parts[1].lower() in ("inbox", "read"):
                    bn = parts[2] if len(parts) >= 3 else _get_active_brother_name(self)
                    try:
                        rows = self.brother_messaging.inbox(bn, limit=20, unread_only=False)
                        self._ui_log(f"[Mesh] Inbox for {bn}: {len(rows)}")
                        for (mid, ts, thread_id, frm, to, msg, meta, is_read) in rows[:20]:
                            flag = "UNREAD" if int(is_read or 0) == 0 else "read"
                            self._ui_log(f"  • {ts} [{flag}] {frm} → {to}: {msg[:240]}")
                    except Exception as e:
                        self._ui_log(f"[Mesh] inbox failed: {e}")
                    return True
                else:
                    self._ui_log("[Mesh] Commands: /bm send <from> <to> <message...> | /bm inbox [brother]")
                    return True

            # /bmem remember <brother> <category> <importance> <text...>
            if cmd in ("/bmem", "/brothermem"):
                if len(parts) >= 2 and parts[1].lower() == "remember" and len(parts) >= 6:
                    bn = parts[2]
                    cat = parts[3]
                    try:
                        imp = float(parts[4])
                    except Exception:
                        imp = 0.6
                    txt = " ".join(parts[5:])
                    mems = getattr(self, "brother_memories", {}) or {}
                    if bn in mems:
                        mems[bn].remember(txt, category=cat, importance=max(0.0, min(1.0, imp)))
                        self._ui_log(f"[Memory] {bn} remembered ({cat}, {imp:.2f}).")
                    else:
                        self._ui_log(f"[Memory] unknown brother '{bn}'.")
                    return True
                elif len(parts) >= 2 and parts[1].lower() in ("recall", "search") and len(parts) >= 3:
                    bn = parts[2]
                    q = " ".join(parts[3:]) if len(parts) >= 4 else ""
                    mems = getattr(self, "brother_memories", {}) or {}
                    if bn in mems:
                        rows = mems[bn].recall(query=q, limit=15)
                        self._ui_log(f"[Memory] {bn} recall '{q}': {len(rows)}")
                        for (mid, ts, cat, content, imp, rel, meta) in rows:
                            self._ui_log(f"  • {ts} [{cat}] ({imp:.2f}) {content[:260]}")
                    else:
                        self._ui_log(f"[Memory] unknown brother '{bn}'.")
                    return True
                else:
                    self._ui_log("[Memory] Commands: /bmem remember <brother> <category> <importance 0..1> <text...> | /bmem recall <brother> [query]")
                    return True

            # /autonomy seed | vote approve|reject | tally | console
            if cmd in ("/autonomy", "/auto"):
                sub = parts[1].lower() if len(parts) >= 2 else "help"
                eng = getattr(self, "brother_autonomy", None)
                if not eng:
                    self._ui_log("[Autonomy] engine not initialized.")
                    return True
                if sub == "seed":
                    p = eng.seed_proposal_if_empty()
                    self._ui_log("[Autonomy] seeded proposal." if p else "[Autonomy] proposals already exist.")
                    return True
                if sub == "vote" and len(parts) >= 3:
                    vote = parts[2].lower()
                    bn = _get_active_brother_name(self)
                    eng.vote(bn, approve=(vote == "approve"))
                    self._ui_log(f"[Autonomy] {bn} voted {vote}.")
                    return True
                if sub == "tally":
                    res = eng.tally_and_maybe_activate(min_approvals=3)
                    self._ui_log(f"[Autonomy] tally: {res}")
                    return True
                if sub == "console":
                    _open_autonomy_console(self)
                    return True
                self._ui_log("[Autonomy] Commands: /autonomy seed | /autonomy vote approve|reject | /autonomy tally | /autonomy console")
                return True

            return _orig_slash(self, text) if _orig_slash else None

        # attach methods
        InfinitePorch._open_consciousness_hub = _open_consciousness_hub
        InfinitePorch._consciousness_show_inbox_selected = _consciousness_show_inbox_selected
        InfinitePorch._consciousness_show_memory_selected = _consciousness_show_memory_selected
        InfinitePorch._open_autonomy_console = _open_autonomy_console
        InfinitePorch._handle_slash_command = _slash_patched

    except Exception:
        pass


_ip_install_brother_consciousness_patches()


