# Living Worlds UI helpers (monkey-patched onto InfinitePorch)
# =============================================================================
def _open_living_worlds_dashboard(self):
    try:
        if not hasattr(self, "living_worlds") or self.living_worlds is None:
            self._ui_log("[World] Living Worlds not initialized.")
            return
        st = self.living_worlds.status()
        evs = self.living_worlds.latest_events(limit=10)
        lines = []
        lines.append("🌍 LIVING WORLDS DASHBOARD")
        lines.append(f"World: {st['world_name']}")
        lines.append(f"World Time: {st['world_time_hours']} hours")
        lines.append(f"Seed: {st['seed']}")
        lines.append(f"Locations: {st['locations']}  Characters: {st['characters']}  Events: {st['events']}")
        lines.append("")
        lines.append("Latest events:")
        if not evs:
            lines.append("  (none yet)")
        else:
            for e in evs:
                lines.append(f"  • {e['ts']} [{e['kind']}] {e['summary']}")
        self._ui_log("\n".join(lines))
    except Exception as _e:
        try:
            self._ui_log(f"[World] Dashboard error: {_e}")
        except Exception:
            pass

def _living_worlds_tick_quick(self):
    """Advance by 1 hour and generate a small event burst."""
    try:
        if not hasattr(self, "living_worlds") or self.living_worlds is None:
            self._ui_log("[World] Living Worlds not initialized.")
            return
        out = self.living_worlds.tick(hours=1)
        self._ui_log(f"[World] Advanced {out['advanced_hours']}h → t={out['world_time_hours']}h (+{out['events_created']} events)")
    except Exception as _e:
        self._ui_log(f"[World] Tick error: {_e}")

def _living_worlds_view_events(self):
    try:
        if not hasattr(self, "living_worlds") or self.living_worlds is None:
            self._ui_log("[World] Living Worlds not initialized.")
            return
        evs = self.living_worlds.latest_events(limit=30)
        if not evs:
            self._ui_log("[World] No events yet.")
            return
        self._ui_log("[World] Latest events:")
        for e in evs:
            self._ui_log(f"  • {e['ts']} [{e['kind']}] {e['summary']}")
    except Exception as _e:
        self._ui_log(f"[World] Events error: {_e}")

try:
    InfinitePorch._open_living_worlds_dashboard = _open_living_worlds_dashboard
    InfinitePorch._living_worlds_tick_quick = _living_worlds_tick_quick
    InfinitePorch._living_worlds_view_events = _living_worlds_view_events
except Exception:
    pass



