# Home Assistant (Overseer) + IoT Auto-Discovery + Camera Registry
# =========================

def _ha__cfg(self):
    st = getattr(self, "_iot_state", {}) or {}
    ha = (st.get("home_assistant") or {})
    if not isinstance(ha, dict):
        ha = {}
    ha.setdefault("base_url", "")
    ha.setdefault("token", "")
    ha.setdefault("verify_ssl", True)
    ha.setdefault("last_ok", False)
    ha.setdefault("last_error", "")
    ha.setdefault("entities_cache", [])
    st["home_assistant"] = ha
    self._iot_state = st
    return ha

def _ha__save_cfg(self, base_url: str, token: str, verify_ssl: bool = True):
    ha = _ha__cfg(self)
    ha["base_url"] = (base_url or "").strip().rstrip("/")
    ha["token"] = (token or "").strip()
    ha["verify_ssl"] = bool(verify_ssl)
    ha["last_error"] = ""
    self._iot_save()
    return ha

def _ha__request(self, method: str, path: str, json_body=None, timeout=8):
    """Home Assistant REST call. Returns (ok, data_or_text)."""
    ha = _ha__cfg(self)
    base = ha.get("base_url", "").strip().rstrip("/")
    token = ha.get("token", "").strip()
    if not base or not token:
        return False, "Home Assistant not configured. Set base_url + token first."
    url = base + path
    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    verify_ssl = bool(ha.get("verify_ssl", True))
    # requests if available, else stdlib
    try:
        import requests  # type: ignore
        r = requests.request(method.upper(), url, headers=headers, json=json_body, timeout=timeout, verify=verify_ssl)
        ct = (r.headers.get("content-type") or "").lower()
        if "application/json" in ct:
            return (200 <= r.status_code < 300), r.json()
        return (200 <= r.status_code < 300), r.text
    except Exception:
        try:
            import urllib.request, urllib.error
            import json as _json
            data = None
            if json_body is not None:
                data = _json.dumps(json_body).encode("utf-8")
            req = urllib.request.Request(url, data=data, method=method.upper())
            for k, v in headers.items():
                req.add_header(k, v)
            ctx = None
            if not verify_ssl:
                import ssl
                ctx = ssl._create_unverified_context()
            with urllib.request.urlopen(req, timeout=timeout, context=ctx) as resp:
                body = resp.read().decode("utf-8", errors="ignore")
                ctype = (resp.headers.get("content-type") or "").lower()
                if "application/json" in ctype:
                    return True, _json.loads(body or "null")
                return True, body
        except Exception as e:
            return False, f"{type(e).__name__}: {e}"

def _ha_test_connection(self):
    ok, data = _ha__request(self, "GET", "/api/")
    ha = _ha__cfg(self)
    ha["last_ok"] = bool(ok)
    ha["last_error"] = "" if ok else str(data)
    self._iot_save()
    return ok, data

def _ha_list_entities(self, limit=80):
    ok, data = _ha__request(self, "GET", "/api/states")
    if ok and isinstance(data, list):
        slim = [{"entity_id": d.get("entity_id"), "state": d.get("state")} for d in data[:limit]]
        ha = _ha__cfg(self)
        ha["entities_cache"] = slim
        ha["last_ok"] = True
        ha["last_error"] = ""
        self._iot_save()
        return True, slim
    ha = _ha__cfg(self)
    ha["last_ok"] = False
    ha["last_error"] = str(data)
    self._iot_save()
    return False, data

def _ha_call_service(self, domain: str, service: str, entity_id=None, extra=None):
    body = {}
    if entity_id:
        body["entity_id"] = entity_id
    if extra:
        body.update(extra)
    return _ha__request(self, "POST", f"/api/services/{domain}/{service}", json_body=body, timeout=10)

def _build_iot_home_assistant_ui(self, tab):
    """Home Assistant UI: creds + entity utilities + live WS events."""
    try:
        import customtkinter as ctk
    except Exception:
        return

    frm = ctk.CTkFrame(tab, fg_color="transparent")
    frm.grid(row=0, column=0, sticky="nsew", padx=8, pady=8)
    tab.grid_rowconfigure(0, weight=1)
    tab.grid_columnconfigure(0, weight=1)
    frm.grid_columnconfigure(1, weight=1)

    st = getattr(self, "_iot_state", None) or self._iot_load()
    self._iot_state = st
    ha = st.get("home_assistant", {})
    ha.setdefault("ws_enabled", True)
    ha.setdefault("auto_events", True)
    ha.setdefault("event_log", [])
    ha.setdefault("last_states", {})

    url_var = ctk.StringVar(value=str(ha.get("base_url", "") or ""))
    token_var = ctk.StringVar(value=str(ha.get("token", "") or ""))
    verify_var = ctk.BooleanVar(value=bool(ha.get("verify_ssl", True)))
    auto_events_var = ctk.BooleanVar(value=bool(ha.get("auto_events", True)))
    ws_enabled_var = ctk.BooleanVar(value=bool(ha.get("ws_enabled", True)))

    def _hdr(lbl: str, row: int):
        h = ctk.CTkLabel(frm, text=lbl, font=("Segoe UI", 14, "bold"))
        h.grid(row=row, column=0, columnspan=2, sticky="w", pady=(10, 4))
        return row + 1

    r = 0
    r = _hdr("Home Assistant Credentials", r)

    ctk.CTkLabel(frm, text="Base URL").grid(row=r, column=0, sticky="w", padx=(0, 8))
    ctk.CTkEntry(frm, textvariable=url_var).grid(row=r, column=1, sticky="ew")
    r += 1

    ctk.CTkLabel(frm, text="Long-Lived Access Token").grid(row=r, column=0, sticky="w", padx=(0, 8))
    ctk.CTkEntry(frm, textvariable=token_var, show="•").grid(row=r, column=1, sticky="ew")
    r += 1

    ctk.CTkCheckBox(frm, text="Verify SSL", variable=verify_var).grid(row=r, column=0, sticky="w")
    ctk.CTkCheckBox(frm, text="Enable WS Events", variable=ws_enabled_var).grid(row=r, column=1, sticky="w")
    r += 1

    ctk.CTkCheckBox(frm, text="Auto-start Events on Startup", variable=auto_events_var).grid(row=r, column=0, columnspan=2, sticky="w")
    r += 1

    btns = ctk.CTkFrame(frm, fg_color="transparent")
    btns.grid(row=r, column=0, columnspan=2, sticky="ew", pady=(6, 0))
    for i in range(6):
        btns.grid_columnconfigure(i, weight=1)
    r += 1

    def _save():
        ha["base_url"] = (url_var.get() or "").strip()
        ha["token"] = (token_var.get() or "").strip()
        ha["verify_ssl"] = bool(verify_var.get())
        ha["auto_events"] = bool(auto_events_var.get())
        ha["ws_enabled"] = bool(ws_enabled_var.get())
        st["home_assistant"] = ha
        self._iot_save(st)
        self._ui_log("[HA] Saved credentials/settings.")

    ctk.CTkButton(btns, text="💾 Save", command=_save).grid(row=0, column=0, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="🔌 Test", command=lambda: self._ui_log(self._ha_test_connection())).grid(row=0, column=1, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="📋 Entities", command=lambda: self._ui_log(self._ha_list_entities(limit=50))).grid(row=0, column=2, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="🔄 Sync Devices", command=lambda: self._ui_log(self._ha_sync_devices())).grid(row=0, column=3, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="🌐 Open HA", command=lambda: self._ha_open_dashboard()).grid(row=0, column=4, padx=4, pady=4, sticky="ew")

    def _toggle_events():
        running = bool(getattr(self, "_ha_event_stream", None) and getattr(self._ha_event_stream, "running", False))
        if running:
            self._ui_log(self._ha_events_stop())
        else:
            self._ui_log(self._ha_events_start())

    ctk.CTkButton(btns, text="📡 Events On/Off", command=_toggle_events).grid(row=0, column=5, padx=4, pady=4, sticky="ew")

    r = _hdr("Live Events", r)

    ev_btns = ctk.CTkFrame(frm, fg_color="transparent")
    ev_btns.grid(row=r, column=0, columnspan=2, sticky="ew")
    for i in range(4):
        ev_btns.grid_columnconfigure(i, weight=1)
    r += 1

    ctk.CTkButton(ev_btns, text="▶ Start Events", command=lambda: self._ui_log(self._ha_events_start())).grid(row=0, column=0, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(ev_btns, text="⏹ Stop Events", command=lambda: self._ui_log(self._ha_events_stop())).grid(row=0, column=1, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(ev_btns, text="🧾 Recent Events", command=lambda: self._ui_log(self._ha_events_show_recent(limit=25))).grid(row=0, column=2, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(ev_btns, text="🚨 Motion Log", command=lambda: self._ui_log(self._security_show_motion_log(limit=40))).grid(row=0, column=3, padx=4, pady=4, sticky="ew")

    status = self._ha_events_status()
    ctk.CTkLabel(frm, text=status).grid(row=r, column=0, columnspan=2, sticky="w", pady=(0, 6))
    r += 1

    r = _hdr("Scenes & Automations", r)

    sa = ctk.CTkFrame(frm, fg_color="transparent")
    sa.grid(row=r, column=0, columnspan=2, sticky="ew")
    for i in range(4):
        sa.grid_columnconfigure(i, weight=1)
    r += 1

    ctk.CTkButton(sa, text="🎬 Create Scene (Sample)", command=lambda: self._ui_log(self._ha_create_scene("Porch Scene", {"light.living_room":"on"}))).grid(row=0, column=0, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(sa, text="⚡ Run Automation (Sample)", command=lambda: self._ui_log(self._ha_run_automation("automation.porch_sample"))).grid(row=0, column=1, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(sa, text="📷 Cameras", command=lambda: self._security_show_cameras()).grid(row=0, column=2, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(sa, text="📡 MQTT On/Off", command=lambda: self._ui_log(self._mqtt_toggle())).grid(row=0, column=3, padx=4, pady=4, sticky="ew")

    note = (
        "Tip: Add motion entities in ./well/iot_state.json → security.motion_entities\n"
        "When WS events are on, motion state changes will auto-log in the Porch."
    )
    ctk.CTkLabel(frm, text=note, justify="left").grid(row=r, column=0, columnspan=2, sticky="w")

def _iot_discover_ssdp(self, timeout_s=2.0):
    """Simple SSDP discovery (UPnP). Stores results in iot_state.discovery.last_ssdp and adds to registry."""
    import socket, time
    st = getattr(self, "_iot_state", {}) or {}
    disc = st.get("discovery") or {}
    st["discovery"] = disc

    msg = (
        "M-SEARCH * HTTP/1.1\r\n"
        "HOST: 239.255.255.250:1900\r\n"
        "MAN: \"ssdp:discover\"\r\n"
        "MX: 1\r\n"
        "ST: ssdp:all\r\n\r\n"
    ).encode("utf-8")

    results = []
    s = None
    try:
        s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM, socket.IPPROTO_UDP)
        s.settimeout(0.4)
        s.sendto(msg, ("239.255.255.250", 1900))
        t0 = time.time()
        while time.time() - t0 < float(timeout_s):
            try:
                data, addr = s.recvfrom(65535)
            except socket.timeout:
                continue
            text = data.decode("utf-8", errors="ignore")
            headers = {}
            for line in text.split("\r\n")[1:]:
                if ":" in line:
                    k, v = line.split(":", 1)
                    headers[k.strip().lower()] = v.strip()
            results.append({
                "ip": addr[0],
                "st": headers.get("st", ""),
                "usn": headers.get("usn", ""),
                "server": headers.get("server", ""),
                "location": headers.get("location", ""),
            })
    except Exception as e:
        self._ui_log(f"[Discover] SSDP error: {type(e).__name__}: {e}")
    finally:
        try:
            if s:
                s.close()
        except Exception:
            pass

    seen = set()
    ded = []
    for r in results:
        key = (r.get("location", ""), r.get("usn", ""), r.get("ip", ""))
        if key in seen:
            continue
        seen.add(key)
        ded.append(r)

    from datetime import datetime, timezone
    disc["last_ssdp"] = ded
    disc["last_run"] = datetime.now(timezone.utc).isoformat()
    st["discovery"] = disc

    # Add to registry
    reg = st.get("registry") or {}
    for d in ded:
        name = (d.get("st") or "device").split(":")[-1] or "device"
        did = f"ssdp:{d.get('ip','')}/{name}"
        if did not in reg:
            reg[did] = {"name": name, "kind": "ssdp", "ip": d.get("ip", ""), "location": d.get("location", "")}
    st["registry"] = reg

    self._iot_state = st
    self._iot_save()
    self._iot_refresh_ui()
    self._ui_log(f"[Discover] SSDP found {len(ded)} device(s).")

def _security_show_cameras(self):
    """Open a simple camera hub (snapshot + open-in-browser)."""
    st = getattr(self, "_iot_state", None) or self._iot_load()
    self._iot_state = st
    sec = st.get("security", {})
    cams = list(sec.get("cameras", []) or [])
    if not cams:
        return self._ui_log("[Security] No cameras configured. Add security.cameras in IoT state (DM → IoT Hub → Security).")

    # Fallback text-only if UI/PIL not available
    try:
        import customtkinter as ctk
    except Exception:
        lines = ["[Security] Cameras:"]
        for c in cams:
            lines.append(f"- {c.get('name','Camera')}  ({c.get('type','url')})  {c.get('url','')}")
        return self._ui_log("\n".join(lines))

    try:
        from PIL import Image
    except Exception:
        Image = None

    import webbrowser

    # Ensure motion log keys
    sec.setdefault("motion_events", [])
    sec.setdefault("motion_entities", [])
    st["security"] = sec
    self._iot_save(st)

    top = ctk.CTkToplevel(self)
    top.title("Security Cameras")
    try:
        top.geometry("940x540")
    except Exception:
        pass

    top.grid_rowconfigure(0, weight=1)
    top.grid_columnconfigure(1, weight=1)

    left = ctk.CTkFrame(top)
    left.grid(row=0, column=0, sticky="nsw", padx=8, pady=8)
    right = ctk.CTkFrame(top)
    right.grid(row=0, column=1, sticky="nsew", padx=8, pady=8)

    right.grid_rowconfigure(2, weight=1)
    right.grid_columnconfigure(0, weight=1)

    ctk.CTkLabel(left, text="Cameras", font=("Segoe UI", 14, "bold")).pack(anchor="w", padx=8, pady=(8, 4))

    cam_var = ctk.StringVar(value=cams[0].get("name","Camera"))

    names = [c.get("name","Camera") for c in cams]
    opt = ctk.CTkOptionMenu(left, values=names, variable=cam_var)
    opt.pack(fill="x", padx=8, pady=4)

    info = ctk.CTkTextbox(right, height=90)
    info.grid(row=0, column=0, sticky="ew", padx=8, pady=(8, 4))
    info.insert("end", "Select a camera to view snapshot / open feed.\n")
    info.configure(state="disabled")

    preview_lbl = ctk.CTkLabel(right, text="(snapshot preview)", height=360)
    preview_lbl.grid(row=1, column=0, sticky="nsew", padx=8, pady=8)

    # Keep a reference so image doesn't GC
    self._camera_preview_img = None

    def _get_cam():
        name = cam_var.get()
        for c in cams:
            if c.get("name","Camera") == name:
                return c
        return cams[0]

    def _set_info(text):
        info.configure(state="normal")
        info.delete("1.0", "end")
        info.insert("end", text)
        info.configure(state="disabled")

    def _fetch_snapshot_bytes(url: str, timeout: float = 6.0):
        try:
            import requests
        except Exception:
            return None, "requests not installed"
        try:
            r = requests.get(url, stream=True, timeout=timeout)
            r.raise_for_status()
            ct = (r.headers.get("Content-Type") or "").lower()

            # If it's a single image, just read it
            if "image/" in ct and "multipart" not in ct:
                return r.content, None

            # MJPEG stream: read until first JPEG frame
            data = b""
            for chunk in r.iter_content(chunk_size=4096):
                if not chunk:
                    continue
                data += chunk
                soi = data.find(b"\xff\xd8")
                eoi = data.find(b"\xff\xd9")
                if soi != -1 and eoi != -1 and eoi > soi:
                    frame = data[soi:eoi+2]
                    return frame, None
                if len(data) > 2_000_000:
                    break
            return None, "no JPEG frame found"
        except Exception as e:
            return None, str(e)

    def _render_snapshot():
        cam = _get_cam()
        name = cam.get("name","Camera")
        url = (cam.get("snapshot_url") or cam.get("url") or "").strip()
        ctype = cam.get("type","url")

        if not url:
            _set_info(f"{name}\nType: {ctype}\nNo URL set.")
            preview_lbl.configure(text="(no url)")
            return

        _set_info(f"{name}\nType: {ctype}\nURL: {url}\n\nFetching snapshot...")
        if Image is None:
            preview_lbl.configure(text="PIL not installed. Install pillow to see snapshots.")
            return

        b, err = _fetch_snapshot_bytes(url)
        if err:
            _set_info(f"{name}\nType: {ctype}\nURL: {url}\n\nSnapshot error: {err}")
            preview_lbl.configure(text="(snapshot failed)")
            return
        try:
            import io
            img = Image.open(io.BytesIO(b))
            img.thumbnail((860, 380))
            try:
                import customtkinter as ctk
                cimg = ctk.CTkImage(light_image=img, dark_image=img, size=img.size)
                self._camera_preview_img = cimg
                preview_lbl.configure(image=cimg, text="")
            except Exception:
                preview_lbl.configure(text="(snapshot loaded)")
        except Exception as e:
            _set_info(f"{name}\nType: {ctype}\nURL: {url}\n\nDecode error: {e}")
            preview_lbl.configure(text="(decode failed)")

    def _open_browser():
        cam = _get_cam()
        url = (cam.get("url") or cam.get("snapshot_url") or "").strip()
        if url:
            webbrowser.open(url)

    def _log_motion_test():
        import datetime as _dt
        evt = {"ts": _dt.datetime.now(timezone.utc).isoformat()+"Z", "source": "manual", "note": f"Test motion from {cam_var.get()}"}
        sec["motion_events"].insert(0, evt)
        sec["motion_events"] = sec["motion_events"][:500]
        st["security"] = sec
        self._iot_save(st)
        self._ui_log(f"[Security] Motion logged: {evt['note']}")

    btns = ctk.CTkFrame(right, fg_color="transparent")
    btns.grid(row=3, column=0, sticky="ew", padx=8, pady=(0, 8))
    for i in range(4):
        btns.grid_columnconfigure(i, weight=1)

    ctk.CTkButton(btns, text="🖼 Snapshot", command=_render_snapshot).grid(row=0, column=0, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="🌐 Open Feed", command=_open_browser).grid(row=0, column=1, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="🚨 Log Motion (Test)", command=_log_motion_test).grid(row=0, column=2, padx=4, pady=4, sticky="ew")
    ctk.CTkButton(btns, text="📜 Motion Log", command=lambda: self._ui_log(self._security_show_motion_log(limit=60))).grid(row=0, column=3, padx=4, pady=4, sticky="ew")

    # initial
    try:
        _render_snapshot()
    except Exception:
        pass


def _security_show_motion_log(self, limit: int = 40):
    """Return a readable motion log."""
    st = getattr(self, "_iot_state", None) or self._iot_load()
    sec = st.get("security", {})
    events = list(sec.get("motion_events", []) or [])[: max(1, int(limit))]
    if not events:
        return "[Security] No motion events logged yet."
    lines = ["[Security] Motion Events:"]
    for e in events:
        ts = e.get("ts", "?")
        src = e.get("source", "unknown")
        note = e.get("note", "")
        ent = e.get("entity_id", "")
        lines.append(f"- {ts} | {src} | {ent} {note}".strip())
    return "\n".join(lines)

# === HOME ASSISTANT WS EVENTS + MQTT + SECURITY ENHANCEMENTS (ROLLING FORWARD) ===

class PorchHAEventStream:
    """Home Assistant WebSocket event stream (state_changed). Optional dependency: websockets."""

    def __init__(self, app, base_url: str, token: str, verify_ssl: bool = True):
        self.app = app
        self.base_url = (base_url or "").strip().rstrip("/")
        self.token = (token or "").strip()
        self.verify_ssl = bool(verify_ssl)
        self.running = False
        self._thread = None
        self._stop_flag = False

    @staticmethod
    def _ws_url(base_url: str) -> str:
        u = (base_url or "").strip().rstrip("/")
        if u.startswith("https://"):
            u = "wss://" + u[len("https://"):]
        elif u.startswith("http://"):
            u = "ws://" + u[len("http://"):]
        elif not (u.startswith("ws://") or u.startswith("wss://")):
            # assume http
            u = "ws://" + u
        return u + "/api/websocket"

    def start(self) -> str:
        if self.running:
            return "[HA] WS events already running."
        if not (self.base_url and self.token):
            return "[HA] Missing base_url/token."
        try:
            import websockets  # noqa: F401
        except Exception:
            return "[HA] websockets not installed. Install: pip install websockets"
        self._stop_flag = False
        self._thread = threading.Thread(target=self._run_thread, name="PorchHAEventStream", daemon=True)
        self._thread.start()
        return "[HA] WS event stream starting..."

    def stop(self) -> str:
        if not self.running and not self._thread:
            return "[HA] WS events not running."
        self._stop_flag = True
        return "[HA] WS event stream stopping..."

    def _run_thread(self):
        import asyncio, json as _json, datetime as _dt
        import ssl as _ssl
        import websockets

        ws_url = self._ws_url(self.base_url)

        ssl_ctx = None
        if ws_url.startswith("wss://"):
            ssl_ctx = _ssl.create_default_context()
            if not self.verify_ssl:
                ssl_ctx.check_hostname = False
                ssl_ctx.verify_mode = _ssl.CERT_NONE

        async def runner():
            nonlocal ws_url, ssl_ctx
            self.running = True
            try:
                async with websockets.connect(ws_url, ssl=ssl_ctx, ping_interval=20, ping_timeout=20) as ws:
                    # hello
                    try:
                        await ws.recv()
                    except Exception:
                        pass
                    await ws.send(_json.dumps({"type": "auth", "access_token": self.token}))
                    # auth response
                    auth = await ws.recv()
                    try:
                        auth_obj = _json.loads(auth)
                        if auth_obj.get("type") != "auth_ok":
                            raise RuntimeError(f"auth failed: {auth_obj}")
                    except Exception:
                        raise

                    # subscribe
                    await ws.send(_json.dumps({"id": 1, "type": "subscribe_events", "event_type": "state_changed"}))

                    while not self._stop_flag:
                        try:
                            msg = await asyncio.wait_for(ws.recv(), timeout=1.0)
                        except asyncio.TimeoutError:
                            continue
                        except Exception:
                            break
                        try:
                            obj = _json.loads(msg)
                        except Exception:
                            continue
                        if obj.get("type") != "event":
                            continue
                        ev = obj.get("event") or {}
                        if ev.get("event_type") != "state_changed":
                            continue
                        data = ev.get("data") or {}
                        ent = data.get("entity_id")
                        new_state = (data.get("new_state") or {}).get("state")
                        old_state = (data.get("old_state") or {}).get("state")

                        ts = _dt.datetime.now(timezone.utc).isoformat() + "Z"
                        # marshal to main thread
                        try:
                            self.app.after(0, lambda e=ent, o=old_state, n=new_state, t=ts: self.app._ha_on_state_changed(e, o, n, t))
                        except Exception:
                            pass
            except Exception as e:
                try:
                    self.app.after(0, lambda: self.app._ui_log(f"[HA] WS events error: {e}"))
                except Exception:
                    pass
            finally:
                self.running = False

        try:
            asyncio.run(runner())
        except Exception:
            self.running = False


def _ha_events_status(self) -> str:
    st = getattr(self, "_iot_state", None) or self._iot_load()
    ha = st.get("home_assistant", {})
    running = bool(getattr(self, "_ha_event_stream", None) and getattr(self._ha_event_stream, "running", False))
    return f"[HA] WS Events: {'RUNNING' if running else 'stopped'} | ws_enabled={ha.get('ws_enabled', True)} | auto_events={ha.get('auto_events', True)}"


def _ha_events_start(self, silent: bool = False) -> str:
    st = getattr(self, "_iot_state", None) or self._iot_load()
    self._iot_state = st
    ha = st.get("home_assistant", {})
    ha.setdefault("event_log", [])
    ha.setdefault("last_states", {})
    st["home_assistant"] = ha
    self._iot_save(st)

    if not ha.get("ws_enabled", True):
        return "[HA] WS events disabled (toggle 'Enable WS Events' in HA settings)."

    base_url = (ha.get("base_url") or "").strip()
    token = (ha.get("token") or "").strip()
    verify_ssl = bool(ha.get("verify_ssl", True))

    if not (base_url and token):
        return "[HA] Missing base_url/token. Save HA credentials first."

    self._ha_event_stream = getattr(self, "_ha_event_stream", None) or PorchHAEventStream(self, base_url, token, verify_ssl)
    # update creds if changed
    self._ha_event_stream.base_url = base_url.rstrip("/")
    self._ha_event_stream.token = token
    self._ha_event_stream.verify_ssl = verify_ssl

    msg = self._ha_event_stream.start()
    if not silent:
        self._ui_log(self._ha_events_status())
    return msg


def _ha_events_stop(self) -> str:
    es = getattr(self, "_ha_event_stream", None)
    if not es:
        return "[HA] WS events not running."
    msg = es.stop()
    return msg


def _ha_events_show_recent(self, limit: int = 25) -> str:
    st = getattr(self, "_iot_state", None) or self._iot_load()
    ha = st.get("home_assistant", {})
    events = list(ha.get("event_log", []) or [])[: max(1, int(limit))]
    if not events:
        return "[HA] No events captured yet. Start WS events first."
    lines = ["[HA] Recent WS Events:"]
    for e in events:
        ts = e.get("ts", "?")
        ent = e.get("entity_id", "?")
        o = e.get("old", "?")
        n = e.get("new", "?")
        lines.append(f"- {ts} | {ent} | {o} → {n}")
    return "\n".join(lines)


def _ha_on_state_changed(self, entity_id: str, old_state: str, new_state: str, ts: str):
    """Internal callback used by WS stream."""
    if not entity_id:
        return

    st = getattr(self, "_iot_state", None) or self._iot_load()
    ha = st.get("home_assistant", {})
    ha.setdefault("event_log", [])
    ha.setdefault("last_states", {})
    ha["last_states"][entity_id] = new_state

    ha["event_log"].insert(0, {"ts": ts, "entity_id": entity_id, "old": old_state, "new": new_state})
    ha["event_log"] = ha["event_log"][:500]
    st["home_assistant"] = ha

    # Motion logging
    sec = st.get("security", {})
    sec.setdefault("motion_events", [])
    sec.setdefault("motion_entities", [])
    motion_entities = set(sec.get("motion_entities", []) or [])
    if entity_id in motion_entities or (entity_id.startswith("binary_sensor.") and "motion" in entity_id.lower()):
        if str(new_state).lower() in ("on", "true", "detected", "motion"):
            sec["motion_events"].insert(0, {"ts": ts, "source": "home_assistant", "entity_id": entity_id, "note": "motion detected"})
            sec["motion_events"] = sec["motion_events"][:500]
            st["security"] = sec
            try:
                self._ui_log(f"[Security] Motion: {entity_id}")
            except Exception:
                pass

    # Power Oracle live ingest (best-effort)
    try:
        if hasattr(self, "_power_oracle") and self._power_oracle:
            self._power_oracle.ingest_ha_state_change(entity_id, new_state, ts)
    except Exception:
        pass

    self._iot_state = st
    try:
        self._iot_save(st)
    except Exception:
        pass


# MQTT (optional) — used for device discovery + commands
def _mqtt__cfg(self):
    st = getattr(self, "_iot_state", None) or self._iot_load()
    self._iot_state = st
    mqtt = st.get("mqtt", {}) or {}
    mqtt.setdefault("host", "localhost")
    mqtt.setdefault("port", 1883)
    mqtt.setdefault("username", "")
    mqtt.setdefault("password", "")
    mqtt.setdefault("tls", False)
    mqtt.setdefault("topics", {"discovery": "homeassistant/#", "events": "porch/events/#", "commands": "porch/commands/#"})
    st["mqtt"] = mqtt
    self._iot_save(st)
    return mqtt


def _mqtt_start(self) -> str:
    mqtt = self._mqtt__cfg()
    try:
        import paho.mqtt.client as mqttc
    except Exception:
        return "[MQTT] paho-mqtt not installed. Install: pip install paho-mqtt"

    if getattr(self, "_mqtt_client", None):
        return "[MQTT] Already running."

    client = mqttc.Client()
    if mqtt.get("username"):
        client.username_pw_set(mqtt.get("username"), mqtt.get("password") or "")

    def on_connect(cl, userdata, flags, rc):
        try:
            self.after(0, lambda: self._ui_log(f"[MQTT] Connected rc={rc}"))
        except Exception:
            pass
        try:
            cl.subscribe(mqtt["topics"]["discovery"])
        except Exception:
            pass
        try:
            cl.subscribe(mqtt["topics"]["events"])
        except Exception:
            pass

    def on_message(cl, userdata, msg):
        try:
            payload = (msg.payload or b"").decode("utf-8", errors="ignore")
            topic = msg.topic
            # lightweight discovery: record topics in iot registry
            st = getattr(self, "_iot_state", None) or self._iot_load()
            st.setdefault("mqtt_seen", [])
            st["mqtt_seen"].insert(0, {"ts": _dt.datetime.now(timezone.utc).isoformat()+"Z", "topic": topic, "payload": payload[:512]})
            st["mqtt_seen"] = st["mqtt_seen"][:200]
            self._iot_state = st
            self._iot_save(st)
        except Exception:
            pass

    client.on_connect = on_connect
    client.on_message = on_message

    try:
        client.connect(mqtt["host"], int(mqtt["port"]), 60)
        client.loop_start()
        self._mqtt_client = client
        return "[MQTT] Started."
    except Exception as e:
        return f"[MQTT] Start failed: {e}"


def _mqtt_stop(self) -> str:
    cl = getattr(self, "_mqtt_client", None)
    if not cl:
        return "[MQTT] Not running."
    try:
        cl.loop_stop()
    except Exception:
        pass
    try:
        cl.disconnect()
    except Exception:
        pass
    self._mqtt_client = None
    return "[MQTT] Stopped."


def _mqtt_toggle(self) -> str:
    if getattr(self, "_mqtt_client", None):
        return self._mqtt_stop()
    return self._mqtt_start()


def _mqtt_publish(self, topic: str, payload=None, qos: int = 0, retain: bool = False) -> str:
    cl = getattr(self, "_mqtt_client", None)
    if not cl:
        return "[MQTT] Not running."
    try:
        if payload is None:
            payload = ""
        if not isinstance(payload, (str, bytes)):
            payload = json.dumps(payload)
        cl.publish(topic, payload, qos=qos, retain=retain)
        return f"[MQTT] Published to {topic}"
    except Exception as e:
        return f"[MQTT] Publish failed: {e}"


# Bind new methods onto InfinitePorch
InfinitePorch._ha_events_status = _ha_events_status
InfinitePorch._ha_events_start = _ha_events_start
InfinitePorch._ha_events_stop = _ha_events_stop
InfinitePorch._ha_events_show_recent = _ha_events_show_recent
InfinitePorch._ha_on_state_changed = _ha_on_state_changed
InfinitePorch._security_show_motion_log = _security_show_motion_log
InfinitePorch._mqtt__cfg = _mqtt__cfg
InfinitePorch._mqtt_start = _mqtt_start
InfinitePorch._mqtt_stop = _mqtt_stop
InfinitePorch._mqtt_toggle = _mqtt_toggle
InfinitePorch._mqtt_publish = _mqtt_publish

# Patch init to auto-start HA WS events if configured
_ip__init__orig_for_ha = InfinitePorch.__init__
def _ip__init__ha_events(self, *a, **kw):
    _ip__init__orig_for_ha(self, *a, **kw)
    try:
        st = getattr(self, "_iot_state", None)
        if not st:
            st = self._iot_load()
            self._iot_state = st
        ha = st.get("home_assistant", {})
        if ha.get("auto_events", True) and ha.get("ws_enabled", True) and ha.get("base_url") and ha.get("token"):
            try:
                self.after(350, lambda: self._ha_events_start(silent=True))
            except Exception:
                self._ha_events_start(silent=True)
    except Exception as e:
        try:
            self._ui_log(f"[HA] Auto-start events skipped: {e}")
        except Exception:
            pass
InfinitePorch.__init__ = _ip__init__ha_events

# Bind into InfinitePorch
InfinitePorch._build_iot_home_assistant_ui = _build_iot_home_assistant_ui
InfinitePorch._iot_discover_ssdp = _iot_discover_ssdp
InfinitePorch._security_show_cameras = _security_show_cameras



