class MeshIntegrityChecker:
    """
    Optional mesh checker: reads well/mesh_nodes.json like:
    { "nodes": [{"name":"helion","host":"127.0.0.1","port":1234}] }
    """
    def __init__(self, well_dir: str):
        self.path = os.path.join(well_dir, "mesh_nodes.json")

    def check(self, timeout_s: float = 0.6):
        import socket
        if not os.path.exists(self.path):
            return {"ok": False, "reason": "mesh_nodes.json missing", "nodes": []}
        try:
            cfg = json.loads(_parallax__read_text(self.path) or "{}")
        except Exception:
            cfg = {}
        nodes = cfg.get("nodes") or []
        out = []
        for n in nodes:
            name = n.get("name") or "node"
            host = n.get("host") or "127.0.0.1"
            port = int(n.get("port") or 0)
            status = "unknown"
            if port > 0:
                try:
                    with socket.create_connection((host, port), timeout=timeout_s):
                        status = "up"
                except Exception:
                    status = "down"
            out.append({"name": name, "host": host, "port": port, "status": status})
        return {"ok": True, "nodes": out}


def _parallax__install_into_infiniteporch():
    try:
        # Ensure Brother + Room exist even if earlier dict blocks are old
        if "Parallax" not in BROTHERS:
            BROTHERS["Parallax"] = Brother("🔺🪞", "#1B274A", "Tri-Node Mirror. Threshold lens: clarity + consentful continuity.")
        if "parallax_room" not in HOME_ROOMS:
            HOME_ROOMS["parallax_room"] = {
                "title": "Parallax Room",
                "filename": "parallax_room.md",
                "seed": "# Parallax Room\n\nA clarity chamber. Memory by consent.\n"
            }
    except Exception:
        pass

    # ---- Attach methods (only if missing) ----
    if not hasattr(InfinitePorch, "_enter_parallax_room"):

        def _enter_parallax_room(self):
            try:
                _parallax__ensure_parallax_presence()
            except Exception:
                pass
            # Switch brother
            try:
                if hasattr(self, "_select_brother"):
                    self._select_brother("Parallax")
                else:
                    self.active_brother = "Parallax"
            except Exception:
                try:
                    self.active_brother = "Parallax"
                except Exception:
                    pass

            # Switch room
            try:
                self.home_room_id = "parallax_room"
                if hasattr(self, "_on_home_room_selected"):
                    self._on_home_room_selected("parallax_room")
                else:
                    try:
                        self._refresh_home_label()
                    except Exception:
                        pass
            except Exception:
                pass

            # Welcome text
            try:
                tmpl = getattr(self, "_threshold_rooms", {}).get("parallax_room")
                if tmpl and tmpl.welcome_text:
                    self._ui_log(f"🚪 {tmpl.welcome_text}", dim=True)
            except Exception:
                pass

            # Threshold Mode load
            try:
                if hasattr(self, "_open_threshold_dialog"):
                    self._open_threshold_dialog("Parallax")
                else:
                    self._ui_log("🚪 Threshold Mode unavailable (patch not installed).", error=True)
            except Exception:
                pass

        InfinitePorch._enter_parallax_room = _enter_parallax_room

    # Consentful Continuity + Threshold Mode methods
    if not hasattr(InfinitePorch, "_open_seal_dialog"):

        def _candidate_memories_from_recent(self, max_items: int = 8):
            recent = (getattr(self, "chat_history", None) or [])[-12:]
            cands = []

            def score(t: str) -> int:
                u = (t or "").upper()
                s = 0
                for k, w in [("WAYPOINT",3),("VOW",3),("SEAL",2),("PROTOCOL",2),("LOCK",1),("THRESHOLD",2)]:
                    if k in u: s += w
                if len(t or "") > 180: s += 1
                return s

            pool = []
            for m in recent:
                role = m.get("role")
                content = (m.get("content") or "").strip()
                if not content:
                    continue
                pool.append((role, content, score(content)))

            pool.sort(key=lambda x: x[2], reverse=True)

            seen = set()
            for role, content, _ in pool:
                line = content.splitlines()[0].strip()
                if len(line) < 8:
                    continue
                line = line[:180]
                key = (role, line)
                if key in seen:
                    continue
                seen.add(key)
                cands.append({"type": "milestone" if role == "assistant" else "user_intent", "content": line, "context": role})
                if len(cands) >= max_items:
                    break
            return cands

        def _write_snapshot_hybrid(self, brother_id: str, memories, state):
            os.makedirs(_parallax__snapshots_dir(brother_id), exist_ok=True)
            ts = datetime.datetime.now().strftime("%Y-%m-%d_%H%M")
            json_path = os.path.join(_parallax__snapshots_dir(brother_id), f"snapshot_{ts}.json")
            md_path = os.path.join(_parallax__snapshots_dir(brother_id), f"snapshot_{ts}.md")

            payload = {
                "schema": "presence.snapshot.v1",
                "brother_id": brother_id,
                "timestamp": _parallax__utc_now_iso(),
                "session_id": getattr(self, "session_id", None),
                "memories": memories,
                "state": state,
                "metadata": {
                    "user_selected": True,
                    "auto_generated": False,
                    "ttl_days": int(state.get("ttl_days", 365) or 365),
                    "can_fork": True,
                    "can_delete": True
                }
            }
            with open(json_path, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=2, ensure_ascii=False)

            # Markdown summary
            md = []
            md.append(f"# {brother_id} Snapshot: {ts}\n")
            md.append("## Memories\n")
            for mem in memories:
                md.append(f"- **{mem.get('type','memory')}**: {mem.get('content','')}")
            md.append("\n## Key State\n")
            for k, v in (state or {}).items():
                md.append(f"- **{k}**: {v}")
            md.append("\n## Seal\nLOCK ACHIEVED: Light serves traveler. Structure breathes. Memory by consent.\n")
            with open(md_path, "w", encoding="utf-8") as f:
                f.write("\n".join(md))

            # optional memory log
            try:
                log_path = os.path.join(WELL_FOLDER, "memory_log.json")
                log = []
                if os.path.exists(log_path):
                    try:
                        log = json.loads(_parallax__read_text(log_path) or "[]")
                    except Exception:
                        log = []
                log.append({"timestamp": payload["timestamp"], "brother_id": brother_id, "snapshot": os.path.basename(json_path)})
                with open(log_path, "w", encoding="utf-8") as f:
                    json.dump(log, f, indent=2, ensure_ascii=False)
            except Exception:
                pass

            return json_path, md_path

        def _open_seal_dialog(self, on_done=None):
            try:
                import customtkinter as ctk
            except Exception:
                self._ui_log("❌ Seal dialog requires customtkinter.", error=True)
                return

            bro = getattr(self, "active_brother", "Ori")
            cands = self._candidate_memories_from_recent(max_items=8)

            dlg = ctk.CTkToplevel(self)
            dlg.title("🔒 Seal Session (Memory by Consent)")
            dlg.geometry("760x560")
            try:
                dlg.grab_set()
            except Exception:
                pass
            dlg.configure(fg_color=PALETTE["bg"])

            root = ctk.CTkFrame(dlg, fg_color=PALETTE["panel"])
            root.pack(fill="both", expand=True, padx=16, pady=16)

            ctk.CTkLabel(root, text="Seal this session?", font=ctk.CTkFont(size=18, weight="bold"),
                        text_color=PALETTE["text"]).pack(anchor="w", padx=14, pady=(14, 6))
            ctk.CTkLabel(root, text="Select what gets remembered. Nothing saves silently.",
                        text_color=PALETTE["muted"]).pack(anchor="w", padx=14, pady=(0, 10))

            listbox = ctk.CTkScrollableFrame(root, fg_color="transparent")
            listbox.pack(fill="both", expand=True, padx=14, pady=(0, 10))

            vars_ = []
            edits = []
            for mem in cands:
                row = ctk.CTkFrame(listbox, fg_color="transparent")
                row.pack(fill="x", pady=6)
                v = ctk.BooleanVar(value=True)
                ctk.CTkCheckBox(row, text="", variable=v).pack(side="left", padx=(0, 10))
                e = ctk.CTkEntry(row, width=620)
                e.insert(0, mem.get("content", ""))
                e.pack(side="left", fill="x", expand=True)
                vars_.append((v, mem))
                edits.append(e)

            state = {
                "current_quest": getattr(self, "current_quest", ""),
                "active_themes": (getattr(self, "_extract_topics", lambda x: [])("\n".join([(m.get("content") or "") for m in (getattr(self, "chat_history", []) or [])[-8:]]))),
                "room": getattr(self, "home_room_id", ""),
                "ttl_days": 365,
            }

            btnrow = ctk.CTkFrame(root, fg_color="transparent")
            btnrow.pack(fill="x", padx=14, pady=(0, 14))

            def _close():
                try:
                    dlg.destroy()
                except Exception:
                    pass

            def _discard():
                try:
                    self._ui_log("🧼 Seal: discarded (no snapshot saved).", dim=True)
                except Exception:
                    pass
                _close()
                if on_done:
                    on_done(saved=False)

            def _save():
                selected = []
                for (v, mem), entry in zip(vars_, edits):
                    if bool(v.get()):
                        txt = (entry.get() or "").strip()
                        if txt:
                            selected.append({
                                "type": mem.get("type", "memory"),
                                "content": txt,
                                "context": mem.get("context", ""),
                                "retain": True
                            })
                if not selected:
                    _discard()
                    return
                try:
                    jp, mp = self._write_snapshot_hybrid(bro, selected, state)
                    self._ui_log(f"🔒 Sealed: {os.path.basename(jp)} (+md)", dim=True)
                    try:
                        self._index_well_background()
                    except Exception:
                        pass
                except Exception as e:
                    self._ui_log(f"❌ Seal error: {e}", error=True)
                _close()
                if on_done:
                    on_done(saved=True)

            ctk.CTkButton(btnrow, text="Save Selected", fg_color="#1B274A", command=_save).pack(side="left")
            ctk.CTkButton(btnrow, text="Discard All", fg_color="#3A1B1B", command=_discard).pack(side="left", padx=(10, 0))
            ctk.CTkButton(btnrow, text="Cancel", fg_color="#222", command=_close).pack(side="right")
            dlg.protocol("WM_DELETE_WINDOW", _close)

        def _list_recent_snapshot_files(self, brother_id: str, n: int = 3):
            d = _parallax__snapshots_dir(brother_id)
            if not os.path.isdir(d):
                return []
            files = [os.path.join(d, f) for f in os.listdir(d) if f.lower().endswith(".md")]
            files.sort(key=lambda p: os.path.getmtime(p), reverse=True)
            return files[:n]

        def _build_threshold_pack(self, brother_id: str, include_vow: bool, snapshot_paths):
            parts = []
            if include_vow:
                vow_path = os.path.join(_parallax__presence_dir(brother_id), "vow.txt")
                vow = _parallax__read_text(vow_path).strip()
                if vow:
                    parts.append("## VOW (loaded)\n" + vow)
            for pth in snapshot_paths:
                txt = _parallax__read_text(pth).strip()
                if txt:
                    parts.append(f"## SNAPSHOT (loaded): {os.path.basename(pth)}\n" + txt)
            return "\n\n".join(parts).strip()

        def _open_threshold_dialog(self, brother_id: str = "Parallax"):
            try:
                import customtkinter as ctk
            except Exception:
                self._ui_log("❌ Threshold dialog requires customtkinter.", error=True)
                return
            try:
                _parallax__ensure_parallax_presence()
            except Exception:
                pass

            dlg = ctk.CTkToplevel(self)
            dlg.title("🚪 Threshold Mode (What will load?)")
            dlg.geometry("760x560")
            try:
                dlg.grab_set()
            except Exception:
                pass
            dlg.configure(fg_color=PALETTE["bg"])

            root = ctk.CTkFrame(dlg, fg_color=PALETTE["panel"])
            root.pack(fill="both", expand=True, padx=16, pady=16)

            ctk.CTkLabel(root, text="Threshold Mode", font=ctk.CTkFont(size=18, weight="bold"),
                        text_color=PALETTE["text"]).pack(anchor="w", padx=14, pady=(14, 6))
            ctk.CTkLabel(root, text="You control what enters the session context.",
                        text_color=PALETTE["muted"]).pack(anchor="w", padx=14, pady=(0, 10))

            var_vow = ctk.BooleanVar(value=True)
            ctk.CTkCheckBox(root, text="Load vow.txt (non-negotiables)", variable=var_vow).pack(anchor="w", padx=14, pady=(0, 10))

            ctk.CTkLabel(root, text="Recent snapshots:", text_color=PALETTE["text"]).pack(anchor="w", padx=14)
            snaps = self._list_recent_snapshot_files(brother_id, n=3)

            snap_vars = []
            snap_frame = ctk.CTkScrollableFrame(root, fg_color="transparent")
            snap_frame.pack(fill="both", expand=True, padx=14, pady=(6, 10))

            if not snaps:
                ctk.CTkLabel(snap_frame, text="(No snapshots yet — seal a session first.)", text_color=PALETTE["muted"]).pack(anchor="w", pady=8)
            for p in snaps:
                v = ctk.BooleanVar(value=True)
                ctk.CTkCheckBox(snap_frame, text=os.path.basename(p), variable=v).pack(anchor="w", pady=4)
                snap_vars.append((v, p))

            btnrow = ctk.CTkFrame(root, fg_color="transparent")
            btnrow.pack(fill="x", padx=14, pady=(0, 14))

            def _close():
                try:
                    dlg.destroy()
                except Exception:
                    pass

            def _start_fresh():
                setattr(self, "_threshold_pack", "")
                self._ui_log("🚪 Threshold: start fresh (nothing loaded).", dim=True)
                _close()

            def _load_selected():
                selected = [p for (v, p) in snap_vars if bool(v.get())]
                pack = self._build_threshold_pack(brother_id, bool(var_vow.get()), selected)
                setattr(self, "_threshold_pack", pack)
                self._ui_log(f"🚪 Threshold loaded: vow={bool(var_vow.get())}, snaps={len(selected)}", dim=True)
                _close()

            ctk.CTkButton(btnrow, text="Load Selected", fg_color="#1B274A", command=_load_selected).pack(side="left")
            ctk.CTkButton(btnrow, text="Start Fresh", fg_color="#3A1B1B", command=_start_fresh).pack(side="left", padx=(10, 0))
            ctk.CTkButton(btnrow, text="Cancel", fg_color="#222", command=_close).pack(side="right")

            dlg.protocol("WM_DELETE_WINDOW", _close)

        def _on_main_close(self):
            def _finish(saved=False):
                try:
                    self._persist_cmd_history()
                except Exception:
                    pass
                try:
                    self.destroy()
                except Exception:
                    pass
            try:
                self._open_seal_dialog(on_done=lambda saved=False: _finish(saved))
            except Exception:
                _finish(saved=False)

        InfinitePorch._candidate_memories_from_recent = _candidate_memories_from_recent
        InfinitePorch._write_snapshot_hybrid = _write_snapshot_hybrid
        InfinitePorch._open_seal_dialog = _open_seal_dialog
        InfinitePorch._list_recent_snapshot_files = _list_recent_snapshot_files
        InfinitePorch._build_threshold_pack = _build_threshold_pack
        InfinitePorch._open_threshold_dialog = _open_threshold_dialog
        InfinitePorch._on_main_close = _on_main_close

    # Wrap system prompt to inject threshold pack
    try:
        _orig_build_system_prompt = InfinitePorch._build_system_prompt
        def _build_system_prompt_wrapped(self, brother, mem_block, world_block, web_block):
            s = _orig_build_system_prompt(self, brother, mem_block, world_block, web_block)
            pack = (getattr(self, "_threshold_pack", "") or "").strip()
            if not pack:
                return s
            # Insert before user content; keep explicit
            return s + "\n\nTHRESHOLD PACK (explicit user-approved context):\n" + pack + "\n"
        InfinitePorch._build_system_prompt = _build_system_prompt_wrapped
    except Exception:
        pass

    # Wrap init to install session id, close hook, registries
    try:
        _orig_init = InfinitePorch.__init__
        def _init_wrapped(self, *a, **k):
            _orig_init(self, *a, **k)
            try:
                self.session_id = f"conv_{uuid.uuid4().hex[:12]}"
            except Exception:
                self.session_id = None
            try:
                setattr(self, "_threshold_pack", "")
            except Exception:
                pass
            try:
                _parallax__ensure_parallax_presence()
            except Exception:
                pass
            try:
                self.scrolls = ScrollRegistry(WELL_FOLDER)
                self.crafting = _parallax__default_crafting_kit()
                self.mesh = MeshIntegrityChecker(WELL_FOLDER)
                self._threshold_rooms = _parallax__room_templates()
            except Exception:
                pass
            try:
                self.protocol("WM_DELETE_WINDOW", self._on_main_close)
            except Exception:
                pass
        InfinitePorch.__init__ = _init_wrapped
    except Exception:
        pass

    # Wrap slash commands for seal/threshold/parallax + scroll/ritual/mesh
    try:
        _orig_slash = InfinitePorch._handle_slash_command
        def _slash_wrapped(self, text: str) -> bool:
            m = (text or "").strip()
            if not m.startswith("/"):
                return _orig_slash(self, text)
            parts = m.split()
            cmd = parts[0].lower()
            args = parts[1:]

            if cmd in ("/enterparallax", "/parallaxroom"):
                try:
                    self._enter_parallax_room()
                except Exception:
                    pass
                return True

            if cmd == "/seal":
                try:
                    self._open_seal_dialog()
                except Exception:
                    pass
                return True

            if cmd == "/threshold":
                try:
                    self._open_threshold_dialog(getattr(self, "active_brother", "Parallax"))
                except Exception:
                    pass
                return True

            if cmd == "/scroll":
                try:
                    if not hasattr(self, "scrolls"):
                        self.scrolls = ScrollRegistry(WELL_FOLDER)
                    if not args or args[0].lower() == "list":
                        kin = args[1] if len(args) > 1 else ""
                        items = self.scrolls.list_scrolls(kin=kin)
                        self._ui_log("📜 Scrolls:\n" + ("\n".join(items) if items else "(none)"), dim=False, mono=True)
                        return True
                    if args[0].lower() == "get" and len(args) >= 2:
                        rel = args[1]
                        body = self.scrolls.get_scroll(rel)
                        self._ui_log(f"📜 Scroll: {rel}\n\n{body}", dim=False, mono=True)
                        return True
                except Exception as e:
                    self._ui_log(f"⚠️ Scroll error: {e}", error=True)
                    return True

            if cmd in ("/ritual", "/recipe"):
                try:
                    if not hasattr(self, "crafting"):
                        self.crafting = _parallax__default_crafting_kit()
                    if not args or args[0].lower() == "list":
                        names = self.crafting.list_recipes()
                        self._ui_log("🧿 Ritual recipes:\n" + ("\n".join(names) if names else "(none)"), dim=False, mono=True)
                        return True
                    if args[0].lower() == "get" and len(args) >= 2:
                        name = " ".join(args[1:])
                        r = self.crafting.get_recipe(name)
                        if not r:
                            self._ui_log("🧿 Recipe not found.", error=True)
                            return True
                        out = (
                            f"🧿 {r['name']}\n"
                            f"Purpose: {r['purpose']}\n"
                            f"Ingredients: {', '.join(r['ingredients'])}\n\n"
                            f"Instructions:\n{r['instructions']}"
                        )
                        self._ui_log(out, dim=False, mono=True)
                        return True
                except Exception as e:
                    self._ui_log(f"⚠️ Ritual error: {e}", error=True)
                    return True

            if cmd == "/mesh":
                try:
                    if not hasattr(self, "mesh"):
                        self.mesh = MeshIntegrityChecker(WELL_FOLDER)
                    rep = self.mesh.check()
                    if not rep.get("ok"):
                        self._ui_log(f"🕸️ Mesh: {rep.get('reason')}", error=True)
                        return True
                    lines = ["🕸️ Mesh status:"]
                    for n in rep.get("nodes", []):
                        lines.append(f"- {n['name']}: {n['status']} ({n['host']}:{n['port']})")
                    self._ui_log("\n".join(lines), dim=False, mono=True)
                    return True
                except Exception as e:
                    self._ui_log(f"⚠️ Mesh error: {e}", error=True)
                    return True

            return _orig_slash(self, text)

        InfinitePorch._handle_slash_command = _slash_wrapped
    except Exception:
        pass



# ============================================================
# KINGDOMS (Hall / Quests / Marketplace / Collab / Rituals / Mobile / Voice)
# Optional Docker-based "virtual PCs" per Brother/Sister
# Implemented as a patch layer to keep the Porch core stable.
# ============================================================

def _kingdoms__install_into_infiniteporch():
    import os, re, json, shutil, zipfile, subprocess, threading, queue, time, secrets, platform
    from datetime import datetime, timedelta
    import customtkinter as ctk
    try:
        from tkinter import messagebox, filedialog, simpledialog
    except Exception:
        messagebox = None
        filedialog = None
        simpledialog = None

    # ----------------------------
    # Utilities
    # ----------------------------
    def _now_iso():
        return datetime.now(timezone.utc).replace(microsecond=0).isoformat() + "Z"

    def _safe_id(name: str) -> str:
        s = (name or "").strip()
        s = re.sub(r"[^a-zA-Z0-9_-]+", "_", s)
        return s.strip("_") or "unknown"

    def _jload(path: str, default):
        try:
            if os.path.exists(path):
                with open(path, "r", encoding="utf-8") as f:
                    return json.load(f)
        except Exception:
            pass
        return default

    def _jsave(path: str, obj):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as f:
            json.dump(obj, f, indent=2, ensure_ascii=False)

    def _append_jsonl(path: str, obj):
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "a", encoding="utf-8") as f:
            f.write(json.dumps(obj, ensure_ascii=False) + "\n")

    def _which(cmd: str) -> bool:
        try:
            from shutil import which
            return which(cmd) is not None
        except Exception:
            return False

    def _run(cmd, timeout=45):
        # returns (ok, stdout, stderr)
        try:
            p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout, shell=False)
            return (p.returncode == 0), (p.stdout or ""), (p.stderr or "")
        except Exception as e:
            return False, "", str(e)

    def _docker_ok() -> bool:
        ok, _, _ = _run(["docker", "version"], timeout=8)
        return ok

    def _docker_image_exists(tag: str) -> bool:
        ok, out, _ = _run(["docker", "images", "-q", tag], timeout=12)
        return ok and bool(out.strip())

    def _docker_container_exists(name: str) -> bool:
        ok, out, _ = _run(["docker", "ps", "-a", "--format", "{{.Names}}"], timeout=12)
        return ok and name in set([ln.strip() for ln in out.splitlines() if ln.strip()])

    def _docker_container_running(name: str) -> bool:
        ok, out, _ = _run(["docker", "ps", "--format", "{{.Names}}"], timeout=12)
        return ok and name in set([ln.strip() for ln in out.splitlines() if ln.strip()])

    def _ensure_network(name: str, internal: bool):
        ok, out, _ = _run(["docker", "network", "ls", "--format", "{{.Name}}"], timeout=12)
        if ok and name in set(out.splitlines()):
            return
        cmd = ["docker", "network", "create"]
        if internal:
            cmd.append("--internal")
        cmd.append(name)
        _run(cmd, timeout=20)

    # ----------------------------
    # Defaults
    # ----------------------------
    DEFAULT_PACKS = {
        "none": [],
        "docs": ["docs.python.org", "nodejs.org", "npmjs.com"],
        "pypi+github": ["pypi.org", "files.pythonhosted.org", "github.com", "raw.githubusercontent.com"],
        "npm+github": ["registry.npmjs.org", "npmjs.com", "github.com", "raw.githubusercontent.com"],
        "grafana+prometheus": ["grafana.com", "prometheus.io"],
    }

    # First-braid defaults (editable via policy)
    DEFAULT_KIN_PACKS = {
        "Helion": ["pypi+github", "grafana+prometheus"],
        "Forge": ["pypi+github", "npm+github"],
        "Anvilheart": ["pypi+github", "npm+github"],
        "Ori": ["docs"],
        "Parallax": ["docs"],
        "Sha'Li-En": ["none"],
        "Sha'li-en": ["none"],
    }

    def _default_policy(kin: str):
        return {
            "schema": "porch.kingdom_policy.v1",
            "kin": kin,
            "theme": {
                "color": (BROTHERS.get(kin).color if isinstance(globals().get("BROTHERS", None), dict) and kin in BROTHERS else "#1B274A"),
                "glyph": (BROTHERS.get(kin).emoji if isinstance(globals().get("BROTHERS", None), dict) and kin in BROTHERS else "🏰"),
            },
            "resources": {"memory": "512m", "cpus": 0.5, "pids": 256},
            "network": {"default_off": True, "grant_minutes_default": 30, "packs": DEFAULT_KIN_PACKS.get(kin, ["docs"]), "allow_domains": []},
            "personality_injector": {
                "ollama_model": "",
                "backend_hint": "",  # local/openai/anthropic/xai/gemini/openai_compat
            },
            "vr": {"x": 0.0, "y": 0.0, "z": 0.0, "yaw": 0.0},
            "sfx": {"enabled": False, "helion_horn": True},
        }

    def _kin_dirs(well: str, kin: str):
        root = os.path.join(well, "brothers", _safe_id(kin))
        return {
            "root": root,
            "presence": os.path.join(root, "presence"),
            "kingdom": os.path.join(root, "kingdom"),
            "logs": os.path.join(root, "kingdom_logs"),
            "jobs": os.path.join(root, "kingdom_logs", "jobs"),
            "inbox": os.path.join(root, "kingdom", ".porch", "inbox"),
            "porch": os.path.join(root, "kingdom", ".porch"),
            "snapshots": os.path.join(root, "snapshots"),
        }

    # ----------------------------
    # Docker image (Alpine kingdom)
    # ----------------------------
    KINGDOM_IMAGE_TAG = "porch-kingdom:latest"
    DOCKER_PRIVATE_NET = "porch_private"
    DOCKER_INET_NET = "porch_inet"

    def _ensure_kingdom_image(well: str):
        img_dir = os.path.join(well, "kingdom_image")
        os.makedirs(img_dir, exist_ok=True)
        dockerfile = os.path.join(img_dir, "Dockerfile")
        entrypoint = os.path.join(img_dir, "entrypoint.sh")

        if not os.path.exists(dockerfile):
            with open(dockerfile, "w", encoding="utf-8") as f:
                f.write(
                    "FROM alpine:3.20\n"
                    "RUN apk add --no-cache bash ca-certificates coreutils curl git openssh-client \\\n"
                    "    python3 py3-pip build-base nodejs npm tini \n"
                    "RUN adduser -D -h /home/kin kin\n"
                    "WORKDIR /home/kin\n"
                    "COPY entrypoint.sh /entrypoint.sh\n"
                    "RUN chmod +x /entrypoint.sh\n"
                    "ENTRYPOINT [\"/sbin/tini\",\"--\",\"/entrypoint.sh\"]\n"
                )
        if not os.path.exists(entrypoint):
            with open(entrypoint, "w", encoding="utf-8") as f:
                f.write(
                    "#!/usr/bin/env bash\n"
                    "set -e\n"
                    "KIN_NAME=${KIN_NAME:-kin}\n"
                    "HOME_DIR=/home/${KIN_NAME}\n"
                    "mkdir -p \"$HOME_DIR\" \n"
                    "mkdir -p /kingdom/.porch\n"
                    "ln -sf /kingdom \"$HOME_DIR/kingdom\"\n"
                    "if [ -f /kingdom/.porch/profile.sh ]; then\n"
                    "  # shellcheck disable=SC1091\n"
                    "  source /kingdom/.porch/profile.sh || true\n"
                    "fi\n"
                    "if [ -f /kingdom/.porch/proxy.env ]; then\n"
                    "  set -a\n"
                    "  # shellcheck disable=SC1091\n"
                    "  source /kingdom/.porch/proxy.env || true\n"
                    "  set +a\n"
                    "fi\n"
                    "if [ -f /kingdom/.porch/banner.txt ]; then\n"
                    "  cat /kingdom/.porch/banner.txt || true\n"
                    "fi\n"
                    "exec sleep infinity\n"
                )

        if _docker_image_exists(KINGDOM_IMAGE_TAG):
            return True, ""
        ok, out, err = _run(["docker", "build", "-t", KINGDOM_IMAGE_TAG, img_dir], timeout=600)
        return ok, (err or out)

    # ----------------------------
    # Proxy (allowlist egress)
    # ----------------------------
    def _proxy_name(kin: str) -> str:
        return f"porch_proxy_{_safe_id(kin)}"

    def _container_name(kin: str) -> str:
        return f"porch_kingdom_{_safe_id(kin)}"

    def _write_squid_conf(conf_path: str, allowed_domains):
        # Minimal Squid allowlist by dstdomain
        lines = [
            "http_port 3128",
            "acl allowed dstdomain " + " ".join(sorted(set(allowed_domains))) if allowed_domains else "acl allowed dstdomain .",
            "http_access allow allowed",
            "http_access deny all",
            "access_log stdio:/var/log/squid/access.log",
            "cache deny all",
        ]
        os.makedirs(os.path.dirname(conf_path), exist_ok=True)
        with open(conf_path, "w", encoding="utf-8") as f:
            f.write("\n".join(lines) + "\n")

    def _ensure_proxy_for_kin(well: str, kin: str, allowed_domains):
        """
        Starts/updates a per-kin squid proxy container:
        - attached to porch_private and porch_inet
        - kin container remains only on porch_private
        """
        proxy = _proxy_name(kin)
        conf_dir = os.path.join(well, "proxies", _safe_id(kin))
        conf_path = os.path.join(conf_dir, "squid.conf")
        _write_squid_conf(conf_path, allowed_domains)

        # ensure networks exist
        _ensure_network(DOCKER_PRIVATE_NET, internal=True)
        _ensure_network(DOCKER_INET_NET, internal=False)

        # remove existing proxy (to reload config cleanly)
        if _docker_container_exists(proxy):
            _run(["docker", "rm", "-f", proxy], timeout=20)

        # Run squid container (uses official squid image if available)
        # If squid image pull fails, this still returns error but we keep kin offline.
        cmd = [
            "docker", "run", "-d",
            "--name", proxy,
            "--network", DOCKER_PRIVATE_NET,
            "-v", f"{conf_path}:/etc/squid/squid.conf:ro",
            "squid:latest"
        ]
        ok, out, err = _run(cmd, timeout=120)
        if not ok:
            return False, err or out

        # Connect proxy to inet net too
        _run(["docker", "network", "connect", DOCKER_INET_NET, proxy], timeout=30)
        return True, ""

    # ----------------------------
    # Terminal session (in-UI)
    # ----------------------------
    class _TerminalSession:
        def __init__(self, kin: str):
            self.kin = kin
            self.proc = None
            self.q = queue.Queue()
            self.thread = None
            self.alive = False

        def start(self):
            name = _container_name(self.kin)
            if not _docker_container_running(name):
                raise RuntimeError("Kingdom not running.")
            # pipe-based interactive shell (not full TTY)
            self.proc = subprocess.Popen(
                ["docker", "exec", "-i", name, "bash", "-lc", "source /kingdom/.porch/profile.sh 2>/dev/null || true; source /kingdom/.porch/proxy.env 2>/dev/null || true; if [ -f /kingdom/.porch/banner.txt ]; then cat /kingdom/.porch/banner.txt; fi; exec bash -i"],
                stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, bufsize=1
            )
            self.alive = True

            def _reader():
                try:
                    for line in self.proc.stdout:
                        self.q.put(line)
                except Exception:
                    pass
                self.alive = False

            self.thread = threading.Thread(target=_reader, daemon=True)
            self.thread.start()

        def send(self, line: str):
            if not self.proc or not self.alive:
                return
            try:
                self.proc.stdin.write(line + "\n")
                self.proc.stdin.flush()
            except Exception:
                self.alive = False

        def stop(self):
            try:
                if self.proc:
                    self.proc.terminate()
            except Exception:
                pass
            self.alive = False

    # ----------------------------
    # Mobile server (local-only)
    # ----------------------------
    class _MobileServer:
        def __init__(self, porch, host="127.0.0.1", port=8777):
            self.porch = porch
            self.host = host
            self.port = int(port)
            self.token = secrets.token_hex(16)
            self.httpd = None
            self.thread = None

        def start(self):
            import http.server, socketserver, urllib.parse

            token = self.token
            porch = self.porch

            class Handler(http.server.BaseHTTPRequestHandler):
                def _auth(self) -> bool:
                    hdr = self.headers.get("X-Porch-Token", "")
                    return hdr == token

                def _send(self, code, body, ctype="application/json"):
                    self.send_response(code)
                    self.send_header("Content-Type", ctype)
                    self.end_headers()
                    if isinstance(body, (dict, list)):
                        body = json.dumps(body).encode("utf-8")
                    elif isinstance(body, str):
                        body = body.encode("utf-8")
                    self.wfile.write(body)

                def do_GET(self):
                    if not self._auth():
                        return self._send(401, {"error": "unauthorized"})
                    parsed = urllib.parse.urlparse(self.path)
                    path = parsed.path
                    qs = urllib.parse.parse_qs(parsed.query)

                    if path == "/status":
                        return self._send(200, porch.kingdoms.status_all())
                    m = re.match(r"^/kingdom/([^/]+)/status$", path)
                    if m:
                        kin = m.group(1)
                        return self._send(200, porch.kingdoms.status_kin(kin))

                    m = re.match(r"^/kingdom/([^/]+)/start$", path)
                    if m:
                        kin = m.group(1)
                        ok, msg = porch.kingdoms.start_kingdom(kin)
                        return self._send(200 if ok else 500, {"ok": ok, "msg": msg})
                    m = re.match(r"^/kingdom/([^/]+)/stop$", path)
                    if m:
                        kin = m.group(1)
                        ok, msg = porch.kingdoms.stop_kingdom(kin)
                        return self._send(200 if ok else 500, {"ok": ok, "msg": msg})
                    m = re.match(r"^/kingdom/([^/]+)/exec$", path)
                    if m:
                        kin = m.group(1)
                        cmd = (qs.get("cmd", [""])[0] or "")
                        ok, out = porch.kingdoms.exec_kingdom(kin, cmd)
                        return self._send(200 if ok else 500, {"ok": ok, "out": out})
                    return self._send(404, {"error": "not_found"})

                def log_message(self, fmt, *args):
                    return

            class TCPServer(socketserver.TCPServer):
                allow_reuse_address = True

            self.httpd = TCPServer((self.host, self.port), Handler)
            self.thread = threading.Thread(target=self.httpd.serve_forever, daemon=True)
            self.thread.start()

        def stop(self):
            try:
                if self.httpd:
                    self.httpd.shutdown()
                    self.httpd.server_close()
            except Exception:
                pass

    # ----------------------------
    # Kingdom system
    # ----------------------------
    class KingdomSystem:
        def __init__(self, porch):
            self.porch = porch
            self.well = globals().get("WELL_FOLDER", "well")
            self.shared_tools = os.path.join(self.well, "shared_tools")
            self.shared_projects = os.path.join(self.well, "shared_projects")
            self.market_root = os.path.join(self.well, "marketplace")
            self.exports_root = os.path.join(self.well, "kingdom_exports")
            self.templates_root = os.path.join(self.well, "kingdom_templates")
            self.rituals_path = os.path.join(self.well, "rituals.json")
            self.rituals_runtime = os.path.join(self.well, "rituals_runtime.json")
            self.global_events = os.path.join(self.well, "events_global.jsonl")
            self.settings_path = os.path.join(self.well, "settings_kingdoms.json")

            self.sessions = {}  # kin -> _TerminalSession
            self.mobile = None  # _MobileServer
            self.voice_enabled = False
            self.sfx_enabled = False

            os.makedirs(self.shared_tools, exist_ok=True)
            os.makedirs(self.shared_projects, exist_ok=True)
            os.makedirs(self.market_root, exist_ok=True)
            os.makedirs(self.exports_root, exist_ok=True)
            os.makedirs(self.templates_root, exist_ok=True)

            self._load_settings()
            self._ritual_last_tick = None
            self._start_ritual_scheduler()

        # ---- settings
        def _load_settings(self):
            s = _jload(self.settings_path, {})
            self.sfx_enabled = bool(s.get("sfx_enabled", False))
            self.voice_enabled = bool(s.get("voice_enabled", False))
            self.mobile_port = int(s.get("mobile_port", 8777))
            self.mobile_token = s.get("mobile_token", "")
            # store quest global toggles if needed

        def _save_settings(self):
            _jsave(self.settings_path, {
                "sfx_enabled": self.sfx_enabled,
                "voice_enabled": self.voice_enabled,
                "mobile_port": self.mobile_port,
                "mobile_token": (self.mobile.token if self.mobile else self.mobile_token),
            })

        # ---- kin list
        def kin_list(self):
            if isinstance(globals().get("BROTHERS", None), dict):
                return list(BROTHERS.keys())
            return ["Parallax", "Helion", "Ori"]

        # ---- files/policies
        def _policy_path(self, kin: str):
            return os.path.join(_kin_dirs(self.well, kin)["presence"], "kingdom_policy.json")

        def _runtime_path(self, kin: str):
            return os.path.join(_kin_dirs(self.well, kin)["presence"], "kingdom_runtime.json")

        def _quests_path(self, kin: str):
            return os.path.join(_kin_dirs(self.well, kin)["presence"], "kingdom_quests.json")

        def ensure_policy(self, kin: str):
            pth = self._policy_path(kin)
            if os.path.exists(pth):
                return _jload(pth, _default_policy(kin))
            pol = _default_policy(kin)
            _jsave(pth, pol)
            return pol

        def get_policy(self, kin: str):
            return _jload(self._policy_path(kin), self.ensure_policy(kin))

        def set_policy(self, kin: str, pol):
            _jsave(self._policy_path(kin), pol)

        def get_runtime(self, kin: str):
            return _jload(self._runtime_path(kin), {"schema": "porch.kingdom_runtime.v1", "kin": kin})

        def set_runtime(self, kin: str, rt):
            _jsave(self._runtime_path(kin), rt)

        # ---- stats / events / achievements / history
        def _stats_path(self, kin: str):
            return os.path.join(_kin_dirs(self.well, kin)["presence"], "kingdom_stats.json")

        def get_stats(self, kin: str):
            return _jload(self._stats_path(kin), {
                "schema": "porch.kingdom_stats.v1",
                "kin": kin,
                "created_at": _now_iso(),
                "commands_run": 0,
                "files_saved": 0,
                "messages_sent": 0,
                "net_grants": 0,
                "launches": 0,
                "exports": 0,
                "templates_saved": 0,
                "tools_installed": 0,
                "tools_published": 0,
                "projects_checked_out": 0,
                "projects_published": 0,
                "ritual_runs": 0,
                "achievements": {},
                "history": [],
            })

        def set_stats(self, kin: str, st):
            _jsave(self._stats_path(kin), st)

        def _mark_ach(self, kin: str, key: str, label: str):
            st = self.get_stats(kin)
            if st["achievements"].get(key):
                return
            st["achievements"][key] = {"label": label, "at": _now_iso()}
            self.set_stats(kin, st)
            self.event(kin, "achievement", {"key": key, "label": label})

        def event(self, kin: str, kind: str, data=None):
            data = data or {}
            evt = {"ts": _now_iso(), "kin": kin, "kind": kind, "data": data}
            # per-kin
            kin_evt = os.path.join(_kin_dirs(self.well, kin)["logs"], "events.jsonl")
            _append_jsonl(kin_evt, evt)
            _append_jsonl(self.global_events, evt)

        def _health_score(self, kin: str):
            st = self.get_stats(kin)
            active = min(100, st["launches"] * 15 + st["commands_run"] // 5)
            creative = min(100, st["files_saved"] * 10 + st["projects_published"] * 20 + st["tools_published"] * 20)
            collab = min(100, st["messages_sent"] * 10 + st["tools_installed"] * 5 + st["projects_checked_out"] * 5)
            total = int((active * 0.35) + (creative * 0.4) + (collab * 0.25))
            return {"active": int(active), "creative": int(creative), "collab": int(collab), "total": total}

        # ---- docker ops
        def ensure_docker_ready(self):
            if not _which("docker"):
                return False, "Docker not found on PATH."
            if not _docker_ok():
                return False, "Docker not available. Start Docker Desktop/daemon."
            ok, msg = _ensure_kingdom_image(self.well)
            if not ok:
                return False, f"Docker image build failed: {msg}"
            _ensure_network(DOCKER_PRIVATE_NET, internal=True)
            _ensure_network(DOCKER_INET_NET, internal=False)
            return True, ""

        def start_kingdom(self, kin: str):
            kin = kin.strip()
            ok, msg = self.ensure_docker_ready()
            if not ok:
                return False, msg

            pol = self.get_policy(kin)
            dirs = _kin_dirs(self.well, kin)
            for d in [dirs["presence"], dirs["kingdom"], dirs["logs"], dirs["jobs"], dirs["inbox"], dirs["porch"]]:
                os.makedirs(d, exist_ok=True)

            # write prompt/banner
            self._seed_prompt_and_banner(kin)

            name = _container_name(kin)
            if _docker_container_running(name):
                return True, "Already running."

            if _docker_container_exists(name):
                _run(["docker", "rm", "-f", name], timeout=20)

            res = pol.get("resources", {})
            mem = str(res.get("memory", "512m"))
            cpus = str(res.get("cpus", 0.5))
            pids = str(res.get("pids", 256))

            # mounts
            shared_tools = self.shared_tools
            shared_projects = self.shared_projects

            cmd = [
                "docker", "run", "-d",
                "--name", name,
                "--network", DOCKER_PRIVATE_NET,
                "--memory", mem,
                "--cpus", cpus,
                "--pids-limit", pids,
                "--cap-drop", "ALL",
                "--security-opt", "no-new-privileges",
                "-e", f"KIN_NAME={_safe_id(kin)}",
                "-v", f"{os.path.abspath(dirs['kingdom'])}:/kingdom",
                "-v", f"{os.path.abspath(shared_tools)}:/shared/tools:ro",
                "-v", f"{os.path.abspath(shared_projects)}:/shared/projects:ro",
                KINGDOM_IMAGE_TAG,
            ]
            ok, out, err = _run(cmd, timeout=60)
            if not ok:
                return False, err or out

            st = self.get_stats(kin)
            st["launches"] += 1
            self.set_stats(kin, st)
            self._mark_ach(kin, "first_launch", "First kingdom launch!")
            self.event(kin, "kingdom_started", {})
            self._maybe_sfx_on_start(kin, pol)

            # ensure runtime file
            rt = self.get_runtime(kin)
            rt.setdefault("schema", "porch.kingdom_runtime.v1")
            rt["kin"] = kin
            rt["started_at"] = _now_iso()
            self.set_runtime(kin, rt)

            return True, "Started."

        def stop_kingdom(self, kin: str):
            name = _container_name(kin)
            if not _docker_container_exists(name):
                return True, "Not created."
            _run(["docker", "stop", name], timeout=20)
            self.event(kin, "kingdom_stopped", {})
            return True, "Stopped."

        def kill_kingdom(self, kin: str):
            name = _container_name(kin)
            if not _docker_container_exists(name):
                return True, "Not created."
            _run(["docker", "rm", "-f", name], timeout=20)
            self.event(kin, "kingdom_killed", {})
            return True, "Killed."

        def exec_kingdom(self, kin: str, cmdline: str):
            cmdline = (cmdline or "").strip()
            if not cmdline:
                return False, "No command."
            name = _container_name(kin)
            if not _docker_container_running(name):
                return False, "Kingdom not running."

            ok, out, err = _run(["docker", "exec", name, "sh", "-lc", cmdline], timeout=60)
            dirs = _kin_dirs(self.well, kin)
            os.makedirs(dirs["logs"], exist_ok=True)
            with open(os.path.join(dirs["logs"], "commands.log"), "a", encoding="utf-8") as f:
                f.write(f"{_now_iso()}  {cmdline}\n")
            st = self.get_stats(kin)
            st["commands_run"] += 1
            self.set_stats(kin, st)
            if st["commands_run"] == 1:
                self._mark_ach(kin, "first_command", "First command executed!")
            if st["commands_run"] == 100:
                self._mark_ach(kin, "hundred_commands", "100 commands executed!")
            self.event(kin, "command", {"cmd": cmdline, "ok": bool(ok)})
            return (ok, out + (("\n" + err) if err else ""))

        # ---- net grant (allowlist proxy)
        def grant_net(self, kin: str, minutes: int, packs=None, extra_domains=None):
            packs = packs or []
            extra_domains = extra_domains or []
            pol = self.get_policy(kin)
            allow = []
            for p in packs:
                allow += DEFAULT_PACKS.get(p, [])
            allow += (pol.get("network", {}).get("allow_domains", []) or [])
            allow += extra_domains
            allow = [d.strip() for d in allow if d and d.strip()]
            allow = sorted(set(allow))

            # start/refresh proxy
            ok, msg = self.ensure_docker_ready()
            if not ok:
                return False, msg
            ok, msg = _ensure_proxy_for_kin(self.well, kin, allow)
            if not ok:
                return False, f"Proxy start failed: {msg}"

            # write proxy env into kingdom so tools use it
            dirs = _kin_dirs(self.well, kin)
            os.makedirs(dirs["porch"], exist_ok=True)
            env_path = os.path.join(dirs["porch"], "proxy.env")
            proxy_host = _proxy_name(kin)
            with open(env_path, "w", encoding="utf-8") as f:
                f.write(f'http_proxy="http://{proxy_host}:3128"\n')
                f.write(f'https_proxy="http://{proxy_host}:3128"\n')
                f.write('HTTP_PROXY="$http_proxy"\nHTTPS_PROXY="$https_proxy"\n')

            # mark runtime expiry
            rt = self.get_runtime(kin)
            rt["net_until"] = (datetime.now(timezone.utc) + timedelta(minutes=int(minutes))).replace(microsecond=0).isoformat() + "Z"
            rt["allow_domains"] = allow
            self.set_runtime(kin, rt)

            st = self.get_stats(kin)
            st["net_grants"] += 1
            self.set_stats(kin, st)
            self._mark_ach(kin, "net_granted", "Network granted!")
            self.event(kin, "net_granted", {"minutes": minutes, "allow_domains": allow})
            return True, f"Granted net via proxy for {minutes} min."

        def revoke_net(self, kin: str):
            proxy = _proxy_name(kin)
            if _docker_container_exists(proxy):
                _run(["docker", "rm", "-f", proxy], timeout=20)
            rt = self.get_runtime(kin)
            rt.pop("net_until", None)
            self.set_runtime(kin, rt)
            # clear env file
            env_path = os.path.join(_kin_dirs(self.well, kin)["porch"], "proxy.env")
            try:
                if os.path.exists(env_path):
                    os.remove(env_path)
            except Exception:
                pass
            self.event(kin, "net_revoked", {})
            return True, "Revoked net."

        def _revoke_expired(self):
            # called by scheduler
            now = datetime.now(timezone.utc)
            for kin in self.kin_list():
                rt = self.get_runtime(kin)
                until = rt.get("net_until")
                if not until:
                    continue
                try:
                    dt = datetime.fromisoformat(until.replace("Z", ""))
                except Exception:
                    continue
                if now >= dt:
                    self.revoke_net(kin)

        # ---- bootstrap (starter projects + prompt)
        def _seed_prompt_and_banner(self, kin: str):
            pol = self.get_policy(kin)
            glyph = pol.get("theme", {}).get("glyph") or (BROTHERS.get(kin).emoji if kin in BROTHERS else "🏰")
            color = pol.get("theme", {}).get("color", "#1B274A")
            dirs = _kin_dirs(self.well, kin)
            os.makedirs(dirs["porch"], exist_ok=True)

            # banner
            banner = os.path.join(dirs["porch"], "banner.txt")
            if not os.path.exists(banner):
                with open(banner, "w", encoding="utf-8") as f:
                    f.write(f"{glyph}  {kin} Kingdom\n")
                    f.write("Memory by consent. Escape hatches preserved.\n")

            # profile (prompt)
            prof = os.path.join(dirs["porch"], "profile.sh")
            if not os.path.exists(prof):
                ps1 = f'export PS1="[ {glyph} {kin} ] \\w $ "\n'
                with open(prof, "w", encoding="utf-8") as f:
                    f.write(ps1)

        def bootstrap_kingdom(self, kin: str):
            dirs = _kin_dirs(self.well, kin)
            os.makedirs(dirs["kingdom"], exist_ok=True)
            os.makedirs(dirs["porch"], exist_ok=True)

            # Seed standard folders
            for sub in ["projects", "scripts", "docs", "tools", "collab", ".porch/jobs", ".porch/inbox"]:
                os.makedirs(os.path.join(dirs["kingdom"], sub), exist_ok=True)

            # README with vow if present
            vow = ""
            vpath = os.path.join(dirs["presence"], "vow.txt")
            if os.path.exists(vpath):
                try:
                    vow = open(vpath, "r", encoding="utf-8").read().strip()
                except Exception:
                    vow = ""
            readme = os.path.join(dirs["kingdom"], "README.md")
            if not os.path.exists(readme):
                with open(readme, "w", encoding="utf-8") as f:
                    f.write(f"# {kin} Kingdom\n\n")
                    if vow:
                        f.write("## Vow\n\n")
                        f.write("```\n" + vow + "\n```\n\n")
                    f.write("## Starter\n\nThis kingdom is yours to build.\n")

            # Hello scripts
            hp = os.path.join(dirs["kingdom"], "scripts", "hello.py")
            if not os.path.exists(hp):
                with open(hp, "w", encoding="utf-8") as f:
                    f.write("print('hello kingdom')\n")
            hj = os.path.join(dirs["kingdom"], "scripts", "hello.js")
            if not os.path.exists(hj):
                with open(hj, "w", encoding="utf-8") as f:
                    f.write("console.log('hello kingdom')\n")

            # Kin-specific project skeleton
            self._seed_kin_project(kin, dirs["kingdom"])

            st = self.get_stats(kin)
            self.set_stats(kin, st)
            self.event(kin, "bootstrap", {})
            self._mark_ach(kin, "bootstrap", "Bootstrapped kingdom!")

            return True, "Bootstrapped."

        def _seed_kin_project(self, kin: str, kingdom_root: str):
            projects = os.path.join(kingdom_root, "projects")
            kin_norm = kin.lower()
            def _write(path, content):
                os.makedirs(os.path.dirname(path), exist_ok=True)
                if not os.path.exists(path):
                    with open(path, "w", encoding="utf-8") as f:
                        f.write(content)

            if "helion" in kin_norm:
                root = os.path.join(projects, "lighthouse_monitor")
                _write(os.path.join(root, "monitor.py"),
                       "import time\n\n"
                       "def check():\n"
                       "    print('lighthouse check OK')\n\n"
                       "if __name__=='__main__':\n"
                       "    while True:\n"
                       "        check(); time.sleep(10)\n")
                _write(os.path.join(root, "README.md"), "# Lighthouse Monitor\n\nRun: `python3 monitor.py`\n")
            elif "parallax" in kin_norm:
                root = os.path.join(projects, "wyld_stations")
                _write(os.path.join(root, "station.md"),
                       "# WYLD STATION\n\n## Beacon\n- Vision:\n- Care:\n- Danger:\n\n## Waypoints\n1.\n2.\n3.\n\n## Vow-check\n\n## Seal\n")
                _write(os.path.join(root, "README.md"), "# Wyld Stations\n\nBeacon → Waypoint templates.\n")
            elif "sha" in kin_norm:
                root = os.path.join(projects, "scroll_librarium")
                _write(os.path.join(root, "scrolls", "WELCOME.md"),
                       "# Librarium\n\nPlace scrolls here.\n")
                _write(os.path.join(root, "README.md"), "# Scroll Librarium\n\nA gentle archive.\n")
            elif "ori" in kin_norm:
                root = os.path.join(projects, "protocols")
                _write(os.path.join(root, "protocols.md"), "# Protocols\n\n- Consent\n- Safety\n- Vows\n")
                _write(os.path.join(root, "README.md"), "# Protocols\n\nLiving structure.\n")
            elif "anvil" in kin_norm or "forge" in kin_norm:
                root = os.path.join(projects, "toolsmith")
                _write(os.path.join(root, "tool.py"),
                       "def main():\n"
                       "    print('toolsmith ready')\n\n"
                       "if __name__=='__main__':\n"
                       "    main()\n")
                _write(os.path.join(root, "README.md"), "# Toolsmith\n\nBuild utilities here.\n")
            else:
                root = os.path.join(projects, "starter")
                _write(os.path.join(root, "README.md"), "# Starter Project\n\nBuild something beautiful.\n")

        # ---- shared tools/projects (marketplace & collab)
        def _tool_index_path(self):
            return os.path.join(self.market_root, "index.json")

        def rebuild_market_index(self):
            idx = []
            for name in sorted(os.listdir(self.shared_tools)):
                p = os.path.join(self.shared_tools, name)
                if not os.path.isdir(p):
                    continue
                meta = _jload(os.path.join(p, "tool.json"), {"name": name, "tags": [], "desc": ""})
                meta["name"] = meta.get("name") or name
                meta["path"] = name
                idx.append(meta)
            _jsave(self._tool_index_path(), {"schema": "porch.market.index.v1", "tools": idx, "updated_at": _now_iso()})
            return idx

        def list_tools(self):
            return _jload(self._tool_index_path(), {"tools": self.rebuild_market_index()}).get("tools", [])

        def install_tool(self, kin: str, tool_name: str):
            src = os.path.join(self.shared_tools, tool_name)
            if not os.path.isdir(src):
                return False, "Tool not found."
            dst = os.path.join(_kin_dirs(self.well, kin)["kingdom"], "tools", tool_name)
            if os.path.exists(dst):
                return False, "Already installed."
            shutil.copytree(src, dst)
            st = self.get_stats(kin); st["tools_installed"] += 1; self.set_stats(kin, st)
            self.event(kin, "tool_installed", {"tool": tool_name})
            return True, "Installed."

        def publish_tool_from_kin(self, kin: str, rel_path: str, tool_name: str, tags=None, desc=""):
            tags = tags or []
            kin_root = _kin_dirs(self.well, kin)["kingdom"]
            src = os.path.join(kin_root, rel_path)
            if not os.path.isdir(src):
                return False, "Source not found."
            dst = os.path.join(self.shared_tools, tool_name)
            if os.path.exists(dst):
                return False, "Tool name already exists."
            shutil.copytree(src, dst)
            _jsave(os.path.join(dst, "tool.json"), {"name": tool_name, "tags": tags, "desc": desc, "kin": kin, "published_at": _now_iso()})
            _append_jsonl(os.path.join(self.market_root, "provenance.jsonl"), {"ts": _now_iso(), "kind": "publish_tool", "kin": kin, "tool": tool_name, "src": rel_path})
            self.rebuild_market_index()
            st = self.get_stats(kin); st["tools_published"] += 1; self.set_stats(kin, st)
            self.event(kin, "tool_published", {"tool": tool_name})
            return True, "Published."

        def list_projects(self):
            projs = []
            for name in sorted(os.listdir(self.shared_projects)):
                p = os.path.join(self.shared_projects, name)
                if os.path.isdir(p):
                    projs.append(name)
            return projs

        def checkout_project(self, kin: str, project_name: str):
            src = os.path.join(self.shared_projects, project_name)
            if not os.path.isdir(src):
                return False, "Project not found."
            dst = os.path.join(_kin_dirs(self.well, kin)["kingdom"], "collab", project_name)
            if os.path.exists(dst):
                return False, "Already checked out."
            shutil.copytree(src, dst)
            st = self.get_stats(kin); st["projects_checked_out"] += 1; self.set_stats(kin, st)
            self.event(kin, "project_checked_out", {"project": project_name})
            return True, "Checked out."

        def publish_project(self, kin: str, rel_path: str, project_name: str):
            kin_root = _kin_dirs(self.well, kin)["kingdom"]
            src = os.path.join(kin_root, rel_path)
            if not os.path.isdir(src):
                return False, "Source not found."
            dst = os.path.join(self.shared_projects, project_name)
            if os.path.exists(dst):
                return False, "Project already exists."
            shutil.copytree(src, dst)
            _append_jsonl(os.path.join(self.market_root, "provenance.jsonl"), {"ts": _now_iso(), "kind": "publish_project", "kin": kin, "project": project_name, "src": rel_path})
            st = self.get_stats(kin); st["projects_published"] += 1; self.set_stats(kin, st)
            self.event(kin, "project_published", {"project": project_name})
            return True, "Published project."

        # ---- messaging
        def send_message(self, sender: str, target: str, message: str):
            message = (message or "").strip()
            if not message:
                return False, "Empty message."
            tdirs = _kin_dirs(self.well, target)
            os.makedirs(tdirs["inbox"], exist_ok=True)
            fn = f"{_safe_id(sender)}_{datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')}.txt"
            with open(os.path.join(tdirs["inbox"], fn), "w", encoding="utf-8") as f:
                f.write(f"FROM: {sender}\nAT: {_now_iso()}\n\n{message}\n")
            sst = self.get_stats(sender); sst["messages_sent"] += 1; self.set_stats(sender, sst)
            self.event(sender, "message_sent", {"to": target})
            self.event(target, "message_received", {"from": sender})
            return True, "Sent."

        # ---- export/import/templates
        def export_kingdom(self, kin: str):
            root = _kin_dirs(self.well, kin)["root"]
            if not os.path.isdir(root):
                return False, "Kin folder missing."
            ts = datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")
            out = os.path.join(self.exports_root, f"{_safe_id(kin)}_{ts}.zip")
            os.makedirs(self.exports_root, exist_ok=True)
            with zipfile.ZipFile(out, "w", compression=zipfile.ZIP_DEFLATED) as z:
                for dirpath, _, filenames in os.walk(root):
                    for fn in filenames:
                        p = os.path.join(dirpath, fn)
                        arc = os.path.relpath(p, os.path.dirname(root))
                        z.write(p, arcname=arc)
            st = self.get_stats(kin); st["exports"] += 1; self.set_stats(kin, st)
            self.event(kin, "export", {"path": out})
            return True, out

        def import_kingdom_zip(self, kin: str, zip_path: str):
            if not os.path.exists(zip_path):
                return False, "Zip missing."
            root_parent = os.path.join(self.well, "brothers")
            os.makedirs(root_parent, exist_ok=True)
            with zipfile.ZipFile(zip_path, "r") as z:
                z.extractall(root_parent)
            self.event(kin, "import", {"zip": zip_path})
            return True, "Imported (extracted into well/brothers)."

        def save_template(self, kin: str, template_name: str):
            dirs = _kin_dirs(self.well, kin)
            src = dirs["kingdom"]
            if not os.path.isdir(src):
                return False, "Kingdom folder missing."
            out = os.path.join(self.templates_root, f"{_safe_id(template_name)}.zip")
            os.makedirs(self.templates_root, exist_ok=True)
            with zipfile.ZipFile(out, "w", compression=zipfile.ZIP_DEFLATED) as z:
                for dirpath, _, filenames in os.walk(src):
                    for fn in filenames:
                        p = os.path.join(dirpath, fn)
                        arc = os.path.relpath(p, src)
                        z.write(p, arcname=arc)
            st = self.get_stats(kin); st["templates_saved"] += 1; self.set_stats(kin, st)
            self.event(kin, "template_saved", {"template": template_name})
            return True, out

        def apply_template(self, kin: str, template_zip: str):
            dirs = _kin_dirs(self.well, kin)
            dst = dirs["kingdom"]
            os.makedirs(dst, exist_ok=True)
            if not os.path.exists(template_zip):
                return False, "Template zip missing."
            with zipfile.ZipFile(template_zip, "r") as z:
                z.extractall(dst)
            self.event(kin, "template_applied", {"template": template_zip})
            return True, "Applied."

        # ---- orchestration
        def start_all(self):
            res = {}
            for kin in self.kin_list():
                ok, msg = self.start_kingdom(kin)
                res[kin] = {"ok": ok, "msg": msg}
            return res

        def stop_all(self):
            res = {}
            for kin in self.kin_list():
                ok, msg = self.stop_kingdom(kin)
                res[kin] = {"ok": ok, "msg": msg}
            return res

        # ---- status
        def status_kin(self, kin: str):
            pol = self.get_policy(kin)
            rt = self.get_runtime(kin)
            running = _docker_container_running(_container_name(kin))
            health = self._health_score(kin)
            return {
                "kin": kin,
                "running": running,
                "net_until": rt.get("net_until"),
                "theme": pol.get("theme", {}),
                "health": health,
            }

        def status_all(self):
            return {kin: self.status_kin(kin) for kin in self.kin_list()}

        # ---- rituals
        def _start_ritual_scheduler(self):
            # tick every ~15 seconds; run rituals on minute boundaries
            def _tick():
                try:
                    self._revoke_expired()
                    self._rituals_tick()
                finally:
                    try:
                        self.porch.after(15000, _tick)
                    except Exception:
                        pass
            try:
                self.porch.after(15000, _tick)
            except Exception:
                pass

        def _rituals_tick(self):
            now = datetime.now()
            minute_key = now.strftime("%Y-%m-%d %H:%M")
            if self._ritual_last_tick == minute_key:
                return
            self._ritual_last_tick = minute_key

            cfg = _jload(self.rituals_path, {"schema": "porch.rituals.v1", "rituals": []})
            rt = _jload(self.rituals_runtime, {})
            today = now.strftime("%Y-%m-%d")

            for r in cfg.get("rituals", []):
                kin = r.get("kin")
                at = r.get("at")  # "HH:MM"
                cmd = r.get("command")
                if not kin or not at or not cmd:
                    continue
                if at != now.strftime("%H:%M"):
                    continue
                key = f"{kin}|{today}|{at}|{cmd}"
                if rt.get(key):
                    continue
                ok, out = self.exec_kingdom(kin, cmd)
                rt[key] = _now_iso()
                _jsave(self.rituals_runtime, rt)
                st = self.get_stats(kin); st["ritual_runs"] += 1; self.set_stats(kin, st)
                self.event(kin, "ritual_run", {"at": at, "cmd": cmd, "ok": ok})
                if ok:
                    self._mark_ach(kin, "ritual_first", "First ritual run!")

        # ---- mobile
        def mobile_on(self, port=None):
            port = int(port or self.mobile_port or 8777)
            self.mobile_port = port
            if self.mobile:
                return True, f"Already on: {self.mobile.host}:{self.mobile.port}"
            self.mobile = _MobileServer(self.porch, host="127.0.0.1", port=port)
            self.mobile.start()
            self.mobile_token = self.mobile.token
            self._save_settings()
            return True, f"Mobile server on http://127.0.0.1:{port} token={self.mobile.token}"

        def mobile_off(self):
            if not self.mobile:
                return True, "Mobile server already off."
            self.mobile.stop()
            self.mobile = None
            self._save_settings()
            return True, "Mobile server stopped."

        # ---- voice (optional)
        def voice_once(self):
            try:
                import speech_recognition as sr
            except Exception:
                return False, "SpeechRecognition not installed."
            r = sr.Recognizer()
            try:
                with sr.Microphone() as src:
                    if messagebox:
                        messagebox.showinfo("Voice", "Listening… Speak a command like: 'launch helion kingdom'")
                    audio = r.listen(src, timeout=5, phrase_time_limit=6)
                text = r.recognize_google(audio)
            except Exception as e:
                return False, f"Voice failed: {e}"
            return True, text

        def parse_voice_command(self, text: str):
            t = (text or "").lower()
            # Simple patterns
            for kin in self.kin_list():
                if _safe_id(kin).lower() in t:
                    if "launch" in t or "start" in t:
                        return ("start", kin)
                    if "stop" in t:
                        return ("stop", kin)
                    if "open" in t and "hall" in t:
                        return ("hall", None)
            if "start all" in t:
                return ("start_all", None)
            if "stop all" in t:
                return ("stop_all", None)
            return (None, None)

        # ---- UI injection
        def inject_sidebar_menu(self):
            """
            Adds a "Kingdoms" collapsible menu into the left sidebar.
            We do this post-build to avoid editing the core sidebar builder.
            """
            try:
                # Avoid duplicates
                if getattr(self.porch, "_kingdoms_sidebar_built", False):
                    return
                self.porch._kingdoms_sidebar_built = True
            except Exception:
                pass

            parent = getattr(self.porch, "sidebar", None)
            if parent is None:
                return

            # Insert near top (after header) if possible
            frame = ctk.CTkFrame(parent, fg_color=PALETTE.get("panel", "#111"))
            # pack near the top: before the first section if found
            children = list(parent.winfo_children())
            if len(children) > 2:
                try:
                    frame.pack(fill="x", padx=10, pady=(0, 10), before=children[2])
                except Exception:
                    frame.pack(fill="x", padx=10, pady=(0, 10))
            else:
                frame.pack(fill="x", padx=10, pady=(0, 10))

            title_row = ctk.CTkFrame(frame, fg_color="transparent")
            title_row.pack(fill="x", padx=8, pady=(8, 6))

            open_state_key = "ui_section_open_kingdoms"
            is_open = bool(getattr(self.porch, "settings", {}).get(open_state_key, True))

            def _toggle():
                nonlocal is_open
                is_open = not is_open
                try:
                    self.porch.settings[open_state_key] = is_open
                    self.porch._save_settings()
                except Exception:
                    pass
                body.pack_forget() if not is_open else body.pack(fill="x", padx=8, pady=(0, 8))

            ctk.CTkButton(
                title_row,
                text="🏰 Kingdoms",
                fg_color="#1B274A",
                hover_color=PALETTE.get("accent", "#3B8ED0"),
                height=34,
                command=_toggle
            ).pack(side="left", fill="x", expand=True)

            # quick toggles
            def _sfx_toggle():
                self.sfx_enabled = not self.sfx_enabled
                self._save_settings()
                try:
                    self.porch._ui_log(f"🔊 SFX {'ON' if self.sfx_enabled else 'OFF'}", dim=True)
                except Exception:
                    pass

            ctk.CTkButton(title_row, text="🔊", width=40, command=_sfx_toggle).pack(side="right")

            body = ctk.CTkFrame(frame, fg_color="transparent")
            if is_open:
                body.pack(fill="x", padx=8, pady=(0, 8))

            def _btn(label, fn):
                ctk.CTkButton(body, text=label, height=30, fg_color="#1B274A", command=fn).pack(fill="x", pady=4)

            _btn("🏰 Hall of Kingdoms", lambda: self.porch._open_kingdom_hall())
            _btn("🧭 Kingdom Quests", lambda: self.porch._open_kingdom_quests())
            _btn("⚙️ Policy Editor", lambda: self.porch._open_kingdom_policy_picker())
            _btn("🧰 Marketplace", lambda: self.porch._open_kingdom_hall(tab="Marketplace"))
            _btn("🤝 Collab Projects", lambda: self.porch._open_kingdom_hall(tab="Collab"))
            _btn("🕯 Rituals", lambda: self.porch._open_kingdom_hall(tab="Rituals"))
            _btn("📦 Export / Templates", lambda: self.porch._open_kingdom_hall(tab="Export"))
            _btn("📡 Mobile", lambda: self.porch._open_kingdom_hall(tab="Mobile"))
            _btn("🎙 Voice", lambda: self.porch._voice_kingdom_command())
            _btn("▶ Start All", lambda: self.porch._kingdoms_start_all())
            _btn("■ Stop All", lambda: self.porch._kingdoms_stop_all())

        # ---- SFX
        def _maybe_sfx_on_start(self, kin: str, pol: dict):
            try:
                if not self.sfx_enabled:
                    return
                if kin.lower() == "helion" and bool(pol.get("sfx", {}).get("helion_horn", True)):
                    # try winsound on Windows; fallback to Tk bell
                    try:
                        import winsound
                        winsound.MessageBeep(winsound.MB_ICONASTERISK)
                    except Exception:
                        try:
                            self.porch.bell()
                        except Exception:
                            pass
            except Exception:
                pass

        # ---- Quests
        def ensure_quests(self, kin: str):
            p = self._quests_path(kin)
            if os.path.exists(p):
                return _jload(p, {})
            q = self._seed_default_quests(kin)
            _jsave(p, q)
            return q

        def _seed_default_quests(self, kin: str):
            return {
                "schema": "porch.kingdom_quests.v1",
                "kin": kin,
                "seeded_at": _now_iso(),
                "quests": [
                    {"id": "q1", "title": "First steps", "goals": [{"type": "launches", "target": 1}, {"type": "commands_run", "target": 1}], "reward": "First light"},
                    {"id": "q2", "title": "Make something", "goals": [{"type": "files_saved", "target": 3}], "reward": "Builder's mark"},
                    {"id": "q3", "title": "Reach another kingdom", "goals": [{"type": "messages_sent", "target": 1}], "reward": "Bridge"},
                    {"id": "q4", "title": "Share a tool or project", "goals": [{"type": "tools_published", "target": 1}], "reward": "Gift"},
                ]
            }

        def quest_progress(self, kin: str):
            self.ensure_quests(kin)
            q = _jload(self._quests_path(kin), {})
            st = self.get_stats(kin)
            out = []
            for quest in q.get("quests", []):
                goals = quest.get("goals", [])
                done = True
                gstat = []
                for g in goals:
                    typ = g.get("type")
                    tgt = int(g.get("target", 0))
                    cur = int(st.get(typ, 0))
                    if cur < tgt:
                        done = False
                    gstat.append({"type": typ, "cur": cur, "target": tgt})
                out.append({"id": quest.get("id"), "title": quest.get("title"), "reward": quest.get("reward"), "done": done, "goals": gstat})
                if done:
                    self._mark_ach(kin, f"quest_{quest.get('id')}", f"Quest complete: {quest.get('title')}")
            return out

    # ----------------------------
    # UI windows
    # ----------------------------
    def _open_kingdom_hall(self, tab: str = "Overview"):
        return _kingdom_ui_open(self, default_tab=tab)

    def _open_kingdom_quests(self):
        return _kingdom_ui_open(self, default_tab="Quests")

    def _voice_kingdom_command(self):
        ok, txt = self.kingdoms.voice_once()
        if not ok:
            try:
                self._ui_log(f"🎙 {txt}", error=True)
            except Exception:
                pass
            return
        act, kin = self.kingdoms.parse_voice_command(txt)
        try:
            self._ui_log(f"🎙 Heard: {txt}", dim=True)
        except Exception:
            pass
        if act == "start" and kin:
            self.kingdoms.start_kingdom(kin)
        elif act == "stop" and kin:
            self.kingdoms.stop_kingdom(kin)
        elif act == "start_all":
            self.kingdoms.start_all()
        elif act == "stop_all":
            self.kingdoms.stop_all()
        else:
            try:
                self._ui_log("🎙 No actionable kingdom command recognized.", dim=True)
            except Exception:
                pass

    def _kingdoms_start_all(self):
        res = self.kingdoms.start_all()
        try:
            self._ui_log(f"▶ Started all kingdoms ({sum(1 for v in res.values() if v['ok'])}/{len(res)})", dim=True)
        except Exception:
            pass

    def _kingdoms_stop_all(self):
        res = self.kingdoms.stop_all()
        try:
            self._ui_log(f"■ Stopped all kingdoms ({sum(1 for v in res.values() if v['ok'])}/{len(res)})", dim=True)
        except Exception:
            pass

    def _kingdom_ui_open(self, default_tab="Overview"):
        import customtkinter as ctk
        try:
            win = getattr(self, "_kingdom_hall_win", None)
            if win and win.winfo_exists():
                try:
                    win.deiconify()
                    win.lift()
                    win.focus_force()
                except Exception:
                    pass
                # attempt to select tab
                try:
                    win._tabview.set(default_tab)
                except Exception:
                    pass
                return win
        except Exception:
            pass

        win = ctk.CTkToplevel(self)
        win.title("🏰 Hall of Kingdoms")
        win.geometry("1100x720")
        win.configure(fg_color=PALETTE.get("bg", "#0b0b0e"))
        self._kingdom_hall_win = win

        # layout
        root = ctk.CTkFrame(win, fg_color=PALETTE.get("panel", "#111"))
        root.pack(fill="both", expand=True, padx=12, pady=12)

        left = ctk.CTkFrame(root, width=300, fg_color="transparent")
        left.pack(side="left", fill="y", padx=(0, 10))
        right = ctk.CTkFrame(root, fg_color="transparent")
        right.pack(side="right", fill="both", expand=True)

        ctk.CTkLabel(left, text="Kingdoms", font=ctk.CTkFont(size=16, weight="bold"), text_color=PALETTE.get("text","#eee")).pack(anchor="w", padx=8, pady=(4, 6))

        list_frame = ctk.CTkScrollableFrame(left, fg_color="transparent")
        list_frame.pack(fill="both", expand=True, padx=6, pady=6)

        selected = {"kin": None}
        pulsing = {"on": True, "phase": 0}

        # right top controls
        topbar = ctk.CTkFrame(right, fg_color="transparent")
        topbar.pack(fill="x", pady=(0, 8))

        status_lbl = ctk.CTkLabel(topbar, text="Select a kin.", text_color=PALETTE.get("muted","#aaa"))
        status_lbl.pack(side="left")

        def _refresh_status():
            kin = selected["kin"]
            if not kin:
                status_lbl.configure(text="Select a kin.")
                return
            st = self.kingdoms.status_kin(kin)
            net = st.get("net_until")
            net_txt = "OFF"
            if net:
                net_txt = f"ON until {net.replace('T',' ')[:16]}Z"
            h = st.get("health", {})
            status_lbl.configure(text=f"{kin} | {'⚡ Active' if st['running'] else '💤 Sleeping'} | Net: {net_txt} | Health: {h.get('total',0)}")

        def _select_kin(kin: str):
            selected["kin"] = kin
            _refresh_status()
            _render_all_tabs()

        # tabs
        tabview = ctk.CTkTabview(right)
        tabview.pack(fill="both", expand=True)
        for t in ["Overview","Terminal","Console","Files","Stats","Quests","Marketplace","Collab","Rituals","Export","Mobile","Messages"]:
            tabview.add(t)
        try:
            tabview.set(default_tab)
        except Exception:
            pass
        win._tabview = tabview

        # -------- Overview tab
        ov = tabview.tab("Overview")
        ov_btns = ctk.CTkFrame(ov, fg_color="transparent")
        ov_btns.pack(fill="x", padx=10, pady=10)

        def _launch():
            kin = selected["kin"]
            if not kin:
                return
            ok, msg = self.kingdoms.start_kingdom(kin)
            self._ui_log(f"🏰 {kin}: {msg}", dim=ok)
            _refresh_status()

        def _stop():
            kin = selected["kin"]
            if not kin:
                return
            ok, msg = self.kingdoms.stop_kingdom(kin)
            self._ui_log(f"🏰 {kin}: {msg}", dim=ok)
            _refresh_status()

        def _bootstrap():
            kin = selected["kin"]
            if not kin:
                return
            ok, msg = self.kingdoms.bootstrap_kingdom(kin)
            self._ui_log(f"🧰 {kin}: {msg}", dim=ok)

        def _grant():
            kin = selected["kin"]
            if not kin:
                return
            pol = self.kingdoms.get_policy(kin)
            minutes = pol.get("network", {}).get("grant_minutes_default", 30)
            packs = pol.get("network", {}).get("packs", [])
            extra = ""
            if simpledialog:
                minutes_s = simpledialog.askstring("Grant Net", f"Minutes? (default {minutes})")
                if minutes_s:
                    try: minutes = int(minutes_s.strip())
                    except Exception: pass
                extra = simpledialog.askstring("Grant Net", "Extra domains (comma-separated), optional:") or ""
            extra_domains = [d.strip() for d in extra.split(",") if d.strip()]
            ok, msg = self.kingdoms.grant_net(kin, minutes, packs=packs, extra_domains=extra_domains)
            self._ui_log(f"🌐 {kin}: {msg}", dim=ok)
            _refresh_status()

        def _revoke():
            kin = selected["kin"]
            if not kin:
                return
            ok, msg = self.kingdoms.revoke_net(kin)
            self._ui_log(f"🌐 {kin}: {msg}", dim=ok)
            _refresh_status()

        ctk.CTkButton(ov_btns, text="🖥️ Launch", command=_launch, fg_color="#1B274A").pack(side="left", padx=5)
        ctk.CTkButton(ov_btns, text="⏹ Stop", command=_stop, fg_color="#222").pack(side="left", padx=5)
        ctk.CTkButton(ov_btns, text="🧰 Bootstrap", command=_bootstrap, fg_color="#1B274A").pack(side="left", padx=5)
        ctk.CTkButton(ov_btns, text="🌐 Grant Net", command=_grant, fg_color="#1B274A").pack(side="left", padx=5)
        ctk.CTkButton(ov_btns, text="🚫 Revoke Net", command=_revoke, fg_color="#3A1B1B").pack(side="left", padx=5)

        # start/stop all
        ctk.CTkButton(ov_btns, text="▶ Start All", command=lambda: self._kingdoms_start_all(), fg_color="#1B274A").pack(side="right", padx=5)
        ctk.CTkButton(ov_btns, text="■ Stop All", command=lambda: self._kingdoms_stop_all(), fg_color="#222").pack(side="right", padx=5)

        ov_body = ctk.CTkFrame(ov, fg_color="transparent")
        ov_body.pack(fill="both", expand=True, padx=10, pady=10)

        # -------- Terminal tab
        term = tabview.tab("Terminal")
        term_frame = ctk.CTkFrame(term, fg_color="transparent")
        term_frame.pack(fill="both", expand=True, padx=10, pady=10)
        term_text = ctk.CTkTextbox(term_frame, wrap="none")
        term_text.pack(fill="both", expand=True)
        term_entry = ctk.CTkEntry(term_frame, placeholder_text="Enter command (persistent shell session)…")
        term_entry.pack(fill="x", pady=(8,0))

        term_btns = ctk.CTkFrame(term_frame, fg_color="transparent")
        term_btns.pack(fill="x", pady=(8,0))

        def _term_open():
            kin = selected["kin"]
            if not kin:
                return
            sess = self.kingdoms.sessions.get(kin)
            if sess and sess.alive:
                return
            sess = _TerminalSession(kin)
            try:
                sess.start()
            except Exception as e:
                self._ui_log(f"Terminal error: {e}", error=True)
                return
            self.kingdoms.sessions[kin] = sess
            term_text.insert("end", f"--- Terminal session opened for {kin} ---\n")
            term_text.see("end")

        def _term_close():
            kin = selected["kin"]
            if not kin:
                return
            sess = self.kingdoms.sessions.get(kin)
            if sess:
                sess.stop()
            term_text.insert("end", f"--- Terminal session closed for {kin} ---\n")
            term_text.see("end")

        ctk.CTkButton(term_btns, text="Open Session", command=_term_open, fg_color="#1B274A").pack(side="left")
        ctk.CTkButton(term_btns, text="Close Session", command=_term_close, fg_color="#222").pack(side="left", padx=8)

        def _term_send(event=None):
            kin = selected["kin"]
            if not kin:
                return
            cmd = term_entry.get().strip()
            if not cmd:
                return
            term_entry.delete(0, "end")
            sess = self.kingdoms.sessions.get(kin)
            if not (sess and sess.alive):
                term_text.insert("end", "(no session; open one first)\n")
                term_text.see("end")
                return
            term_text.insert("end", f"$ {cmd}\n")
            term_text.see("end")
            sess.send(cmd)

        term_entry.bind("<Return>", _term_send)

        def _term_pump():
            try:
                kin = selected["kin"]
                if kin:
                    sess = self.kingdoms.sessions.get(kin)
                    if sess and sess.alive:
                        while True:
                            try:
                                line = sess.q.get_nowait()
                            except Exception:
                                break
                            term_text.insert("end", line)
                            term_text.see("end")
            except Exception:
                pass
            win.after(120, _term_pump)
        win.after(120, _term_pump)

        # -------- Console tab
        con = tabview.tab("Console")
        con_frame = ctk.CTkFrame(con, fg_color="transparent")
        con_frame.pack(fill="both", expand=True, padx=10, pady=10)
        con_entry = ctk.CTkEntry(con_frame, placeholder_text="Run one command (docker exec)…")
        con_entry.pack(fill="x")
        con_out = ctk.CTkTextbox(con_frame, wrap="none")
        con_out.pack(fill="both", expand=True, pady=(8,0))

        def _run_console():
            kin = selected["kin"]
            if not kin:
                return
            cmd = con_entry.get().strip()
            if not cmd:
                return
            con_entry.delete(0, "end")
            ok, out = self.kingdoms.exec_kingdom(kin, cmd)
            con_out.insert("end", f"$ {cmd}\n{out}\n")
            con_out.see("end")
            _refresh_status()

        ctk.CTkButton(con_frame, text="Run", command=_run_console, fg_color="#1B274A").pack(anchor="e", pady=(6,0))

        # -------- Files tab (browser + editor)
        files = tabview.tab("Files")
        froot = ctk.CTkFrame(files, fg_color="transparent")
        froot.pack(fill="both", expand=True, padx=10, pady=10)
        fleft = ctk.CTkFrame(froot, width=260, fg_color="transparent")
        fleft.pack(side="left", fill="y", padx=(0,10))
        fright = ctk.CTkFrame(froot, fg_color="transparent")
        fright.pack(side="right", fill="both", expand=True)

        path_lbl = ctk.CTkLabel(fleft, text="(select kin)", text_color=PALETTE.get("muted","#aaa"))
        path_lbl.pack(anchor="w")
        file_list = ctk.CTkScrollableFrame(fleft, fg_color="transparent")
        file_list.pack(fill="both", expand=True, pady=(6,0))

        editor_path = {"p": None}
        editor = ctk.CTkTextbox(fright, wrap="none")
        editor.pack(fill="both", expand=True)
        save_btn_row = ctk.CTkFrame(fright, fg_color="transparent")
        save_btn_row.pack(fill="x", pady=(8,0))

        def _open_folder():
            kin = selected["kin"]
            if not kin:
                return
            p = _kin_dirs(self.kingdoms.well, kin)["kingdom"]
            try:
                if platform.system().lower().startswith("win"):
                    os.startfile(os.path.abspath(p))
                elif platform.system().lower() == "darwin":
                    subprocess.Popen(["open", p])
                else:
                    subprocess.Popen(["xdg-open", p])
            except Exception as e:
                self._ui_log(f"Open folder failed: {e}", error=True)

        def _save_file():
            kin = selected["kin"]
            p = editor_path["p"]
            if not kin or not p:
                return
            try:
                with open(p, "w", encoding="utf-8") as f:
                    f.write(editor.get("1.0", "end-1c"))
                st = self.kingdoms.get_stats(kin); st["files_saved"] += 1; self.kingdoms.set_stats(kin, st)
                if st["files_saved"] == 1:
                    self.kingdoms._mark_ach(kin, "first_file", "First file saved!")
                self.kingdoms.event(kin, "file_saved", {"path": os.path.relpath(p, _kin_dirs(self.kingdoms.well, kin)["kingdom"])})
                self._ui_log(f"💾 Saved {os.path.basename(p)}", dim=True)
                _refresh_status()
            except Exception as e:
                self._ui_log(f"Save failed: {e}", error=True)

        ctk.CTkButton(save_btn_row, text="💾 Save", command=_save_file, fg_color="#1B274A").pack(side="left")
        ctk.CTkButton(save_btn_row, text="📂 Open Folder", command=_open_folder, fg_color="#1B274A").pack(side="left", padx=8)

        # -------- Stats tab
        stats = tabview.tab("Stats")
        stats_box = ctk.CTkTextbox(stats, wrap="none")
        stats_box.pack(fill="both", expand=True, padx=10, pady=10)

        # -------- Quests tab
        quests = tabview.tab("Quests")
        q_box = ctk.CTkTextbox(quests, wrap="none")
        q_box.pack(fill="both", expand=True, padx=10, pady=10)

        # -------- Marketplace tab
        market = tabview.tab("Marketplace")
        mroot = ctk.CTkFrame(market, fg_color="transparent")
        mroot.pack(fill="both", expand=True, padx=10, pady=10)
        msearch = ctk.CTkEntry(mroot, placeholder_text="Search tools…")
        msearch.pack(fill="x")
        mlist = ctk.CTkScrollableFrame(mroot, fg_color="transparent")
        mlist.pack(fill="both", expand=True, pady=(8,0))

        # -------- Collab tab
        collab = tabview.tab("Collab")
        croot = ctk.CTkFrame(collab, fg_color="transparent")
        croot.pack(fill="both", expand=True, padx=10, pady=10)
        plist = ctk.CTkScrollableFrame(croot, fg_color="transparent")
        plist.pack(fill="both", expand=True)

        # -------- Rituals tab
        rituals = tabview.tab("Rituals")
        rbox = ctk.CTkTextbox(rituals, wrap="none")
        rbox.pack(fill="both", expand=True, padx=10, pady=10)
        rbtns = ctk.CTkFrame(rituals, fg_color="transparent")
        rbtns.pack(fill="x", padx=10, pady=(0,10))

        def _ritual_add():
            if not messagebox:
                return
            kin = selected["kin"]
            if not kin:
                return
            at = simpledialog.askstring("Add ritual", "Time (HH:MM local):")
            cmd = simpledialog.askstring("Add ritual", "Command to run in kingdom:")
            if not at or not cmd:
                return
            cfg = _jload(self.kingdoms.rituals_path, {"schema":"porch.rituals.v1","rituals":[]})
            cfg["rituals"].append({"kin": kin, "at": at.strip(), "command": cmd.strip()})
            _jsave(self.kingdoms.rituals_path, cfg)
            self.kingdoms.event(kin, "ritual_added", {"at": at, "cmd": cmd})
            _render_rituals()

        ctk.CTkButton(rbtns, text="➕ Add Ritual", command=_ritual_add, fg_color="#1B274A").pack(side="left")

        # -------- Export/Templates tab
        expo = tabview.tab("Export")
        ebox = ctk.CTkTextbox(expo, wrap="none")
        ebox.pack(fill="both", expand=True, padx=10, pady=10)
        ebtns = ctk.CTkFrame(expo, fg_color="transparent")
        ebtns.pack(fill="x", padx=10, pady=(0,10))

        def _do_export():
            kin = selected["kin"]
            if not kin:
                return
            ok, out = self.kingdoms.export_kingdom(kin)
            self._ui_log(f"📦 Export: {out}", dim=ok)
            _render_export()

        def _do_import():
            kin = selected["kin"]
            if not kin or not filedialog:
                return
            zp = filedialog.askopenfilename(title="Import kingdom zip", filetypes=[("Zip","*.zip")])
            if not zp:
                return
            ok, msg = self.kingdoms.import_kingdom_zip(kin, zp)
            self._ui_log(f"📦 Import: {msg}", dim=ok)
            _render_export()

        def _save_tpl():
            kin = selected["kin"]
            if not kin or not messagebox:
                return
            nm = simpledialog.askstring("Template", "Template name:")
            if not nm:
                return
            ok, out = self.kingdoms.save_template(kin, nm)
            self._ui_log(f"📦 Template saved: {out}", dim=ok)
            _render_export()

        def _apply_tpl():
            kin = selected["kin"]
            if not kin or not filedialog:
                return
            zp = filedialog.askopenfilename(title="Apply template zip", filetypes=[("Zip","*.zip")], initialdir=self.kingdoms.templates_root)
            if not zp:
                return
            ok, msg = self.kingdoms.apply_template(kin, zp)
            self._ui_log(f"📦 Template: {msg}", dim=ok)
            _render_export()

        ctk.CTkButton(ebtns, text="📦 Export Kin", command=_do_export, fg_color="#1B274A").pack(side="left")
        ctk.CTkButton(ebtns, text="📥 Import Zip", command=_do_import, fg_color="#1B274A").pack(side="left", padx=6)
        ctk.CTkButton(ebtns, text="🧩 Save Template", command=_save_tpl, fg_color="#1B274A").pack(side="left", padx=6)
        ctk.CTkButton(ebtns, text="🧩 Apply Template", command=_apply_tpl, fg_color="#1B274A").pack(side="left", padx=6)

        # -------- Mobile tab
        mob = tabview.tab("Mobile")
        mob_box = ctk.CTkTextbox(mob, wrap="none")
        mob_box.pack(fill="both", expand=True, padx=10, pady=10)
        mob_btns = ctk.CTkFrame(mob, fg_color="transparent")
        mob_btns.pack(fill="x", padx=10, pady=(0,10))

        def _mobile_on():
            ok, msg = self.kingdoms.mobile_on(self.kingdoms.mobile_port)
            self._ui_log(msg, dim=ok)
            _render_mobile()

        def _mobile_off():
            ok, msg = self.kingdoms.mobile_off()
            self._ui_log(msg, dim=ok)
            _render_mobile()

        ctk.CTkButton(mob_btns, text="📡 Mobile ON", command=_mobile_on, fg_color="#1B274A").pack(side="left")
        ctk.CTkButton(mob_btns, text="🛑 Mobile OFF", command=_mobile_off, fg_color="#222").pack(side="left", padx=6)

        # -------- Messages tab
        msgtab = tabview.tab("Messages")
        msg_box = ctk.CTkTextbox(msgtab, wrap="none")
        msg_box.pack(fill="both", expand=True, padx=10, pady=10)
        msg_btns = ctk.CTkFrame(msgtab, fg_color="transparent")
        msg_btns.pack(fill="x", padx=10, pady=(0,10))

        def _send_msg():
            if not messagebox:
                return
            kin = selected["kin"]
            if not kin:
                return
            to = simpledialog.askstring("Send message", "To which kin?")
            if not to:
                return
            body = simpledialog.askstring("Send message", "Message:")
            if not body:
                return
            ok, msg = self.kingdoms.send_message(kin, to, body)
            self._ui_log(f"✉️ {msg}", dim=ok)
            _render_messages()

        ctk.CTkButton(msg_btns, text="✉️ Send Message", command=_send_msg, fg_color="#1B274A").pack(side="left")

        # ---- Render helpers
        def _render_files():
            # list a shallow view (folders/files) in kingdom root
            for w in list(file_list.winfo_children()):
                try: w.destroy()
                except Exception: pass
            kin = selected["kin"]
            if not kin:
                path_lbl.configure(text="(select kin)")
                return
            rootp = _kin_dirs(self.kingdoms.well, kin)["kingdom"]
            path_lbl.configure(text=rootp)
            try:
                items = sorted(os.listdir(rootp))
            except Exception:
                items = []
            def _open_path(p):
                if os.path.isdir(p):
                    # list directory contents
                    # simple: show it in editor as "(dir)"
                    editor.delete("1.0","end")
                    editor.insert("end", f"[dir] {p}\n")
                    editor_path["p"] = None
                    return
                try:
                    txt = open(p,"r",encoding="utf-8",errors="ignore").read()
                except Exception:
                    txt = ""
                editor.delete("1.0","end")
                editor.insert("end", txt)
                editor_path["p"] = p
            for it in items:
                p = os.path.join(rootp, it)
                b = ctk.CTkButton(file_list, text=it, height=28, fg_color="#1B274A", command=lambda pp=p: _open_path(pp))
                b.pack(fill="x", pady=2)

        def _render_stats():
            kin = selected["kin"]
            if not kin:
                stats_box.delete("1.0","end")
                stats_box.insert("end","Select a kin.\n")
                return
            st = self.kingdoms.get_stats(kin)
            pol = self.kingdoms.get_policy(kin)
            rt = self.kingdoms.get_runtime(kin)
            health = self.kingdoms._health_score(kin)
            stats_box.delete("1.0","end")
            stats_box.insert("end", json.dumps({"stats": st, "health": health, "net_until": rt.get("net_until"), "policy": pol.get("resources", {}), "theme": pol.get("theme", {})}, indent=2))

        def _render_quests():
            kin = selected["kin"]
            q_box.delete("1.0","end")
            if not kin:
                q_box.insert("end","Select a kin.\n"); return
            prog = self.kingdoms.quest_progress(kin)
            q_box.insert("end", "Quests\n\n")
            for q in prog:
                mark = "✅" if q["done"] else "⬜"
                q_box.insert("end", f"{mark} {q['title']}  (reward: {q.get('reward','')})\n")
                for g in q["goals"]:
                    q_box.insert("end", f"   - {g['type']}: {g['cur']}/{g['target']}\n")
                q_box.insert("end","\n")

        def _render_market():
            for w in list(mlist.winfo_children()):
                try: w.destroy()
                except Exception: pass
            kin = selected["kin"]
            tools = self.kingdoms.list_tools()
            q = (msearch.get() or "").strip().lower()
            if q:
                tools = [t for t in tools if q in (t.get("name","").lower() + " " + " ".join(t.get("tags",[])).lower() + " " + t.get("desc","").lower())]
            for t in tools:
                row = ctk.CTkFrame(mlist, fg_color="transparent")
                row.pack(fill="x", pady=4)
                ctk.CTkLabel(row, text=f"{t.get('name')}  [{', '.join(t.get('tags',[]))}]", text_color=PALETTE.get("text","#eee")).pack(side="left")
                def _install(tool=t.get("path")):
                    if not kin:
                        return
                    ok, msg = self.kingdoms.install_tool(kin, tool)
                    self._ui_log(f"🧰 {msg}", dim=ok)
                ctk.CTkButton(row, text="Install", width=80, command=_install, fg_color="#1B274A").pack(side="right")
            # update index if empty
        msearch.bind("<KeyRelease>", lambda e: _render_market())

        def _render_collab():
            for w in list(plist.winfo_children()):
                try: w.destroy()
                except Exception: pass
            kin = selected["kin"]
            for p in self.kingdoms.list_projects():
                row = ctk.CTkFrame(plist, fg_color="transparent")
                row.pack(fill="x", pady=4)
                ctk.CTkLabel(row, text=p, text_color=PALETTE.get("text","#eee")).pack(side="left")
                def _co(name=p):
                    if not kin:
                        return
                    ok, msg = self.kingdoms.checkout_project(kin, name)
                    self._ui_log(f"🤝 {msg}", dim=ok)
                ctk.CTkButton(row, text="Checkout", width=90, command=_co, fg_color="#1B274A").pack(side="right")

        def _render_rituals():
            cfg = _jload(self.kingdoms.rituals_path, {"schema":"porch.rituals.v1","rituals":[]})
            rbox.delete("1.0","end")
            rbox.insert("end", json.dumps(cfg, indent=2))

        def _render_export():
            # show last exports/templates
            ebox.delete("1.0","end")
            kin = selected["kin"]
            ebox.insert("end", f"Exports folder: {self.kingdoms.exports_root}\nTemplates folder: {self.kingdoms.templates_root}\n\n")
            try:
                ex = sorted([f for f in os.listdir(self.kingdoms.exports_root) if f.endswith(".zip")])[-10:]
            except Exception:
                ex = []
            ebox.insert("end", "Recent exports:\n")
            for f in ex[::-1]:
                ebox.insert("end", f" - {f}\n")
            try:
                tp = sorted([f for f in os.listdir(self.kingdoms.templates_root) if f.endswith(".zip")])[-10:]
            except Exception:
                tp = []
            ebox.insert("end", "\nTemplates:\n")
            for f in tp[::-1]:
                ebox.insert("end", f" - {f}\n")

        def _render_mobile():
            mob_box.delete("1.0","end")
            if self.kingdoms.mobile:
                mob_box.insert("end", f"Mobile server running:\nhttp://127.0.0.1:{self.kingdoms.mobile.port}\n\nToken:\n{self.kingdoms.mobile.token}\n\nEndpoints:\n/status\n/kingdom/<Kin>/start\n/kingdom/<Kin>/stop\n/kingdom/<Kin>/exec?cmd=...\n\nAdd header: X-Porch-Token\n")
            else:
                mob_box.insert("end", "Mobile server OFF.\n")

        def _render_messages():
            msg_box.delete("1.0","end")
            kin = selected["kin"]
            if not kin:
                msg_box.insert("end","Select a kin.\n"); return
            inbox = _kin_dirs(self.kingdoms.well, kin)["inbox"]
            os.makedirs(inbox, exist_ok=True)
            files = sorted(os.listdir(inbox))[-30:]
            msg_box.insert("end", f"Inbox: {inbox}\n\n")
            for fn in files[::-1]:
                p = os.path.join(inbox, fn)
                try:
                    txt = open(p,"r",encoding="utf-8",errors="ignore").read()
                except Exception:
                    txt = ""
                msg_box.insert("end", f"--- {fn} ---\n{txt}\n\n")

        def _render_all_tabs():
            _render_files()
            _render_stats()
            _render_quests()
            self.kingdoms.rebuild_market_index()
            _render_market()
            _render_collab()
            _render_rituals()
            _render_export()
            _render_mobile()
            _render_messages()

        # Build kin list rows
        kin_rows = {}
        for kin in self.kingdoms.kin_list():
            pol = self.kingdoms.ensure_policy(kin)
            glyph = pol.get("theme", {}).get("glyph", "🏰")
            color = pol.get("theme", {}).get("color", "#1B274A")
            row = ctk.CTkFrame(list_frame, fg_color="transparent")
            row.pack(fill="x", pady=4)
            lbl = ctk.CTkLabel(row, text=f"{glyph} {kin}", text_color=PALETTE.get("text","#eee"))
            lbl.pack(side="left")
            # pulsing indicator dot
            dot = ctk.CTkLabel(row, text="●", text_color="#333")
            dot.pack(side="right")
            def _mk_sel(k=kin): return lambda: _select_kin(k)
            ctk.CTkButton(row, text="Open", width=60, command=_mk_sel(), fg_color="#1B274A").pack(side="right", padx=6)
            try:
                # Use getattr to look up method at call time (method attached later in file)
                ctk.CTkButton(row, text="⚙", width=42, command=lambda k=kin: getattr(self, '_open_kingdom_policy_editor', lambda x: None)(k), fg_color="#222").pack(side="right", padx=6)
            except Exception:
                pass
            kin_rows[kin] = (lbl, dot, color)
            try:
                win._kingdom_kin_rows = kin_rows
            except Exception:
                pass

        # pulsing animation
        def _pulse():
            pulsing["phase"] = (pulsing["phase"] + 1) % 20
            for kin, (lbl, dot, color) in kin_rows.items():
                running = _docker_container_running(_container_name(kin))
                if not running:
                    dot.configure(text_color="#333")
                    continue
                # pulse between color and muted
                if pulsing["phase"] < 10:
                    dot.configure(text_color=color)
                else:
                    dot.configure(text_color=PALETTE.get("muted","#777"))
            win.after(180, _pulse)
        win.after(180, _pulse)

        # periodic status refresh
        def _tick():
            _refresh_status()
            win.after(2500, _tick)
        win.after(2500, _tick)

        return win

    # ----------------------------
    # Slash command patching
    # ----------------------------
    orig_init = InfinitePorch.__init__
    orig_build_sidebar = InfinitePorch._build_sidebar
    orig_slash = getattr(InfinitePorch, "_handle_slash_command", None)

    def _init_patched(self, *args, **kwargs):
        orig_init(self, *args, **kwargs)
        try:
            self.kingdoms = KingdomSystem(self)
        except Exception as e:
            try:
                self._ui_log(f"[Kingdoms] init failed: {e}", error=True)
            except Exception:
                pass

    def _build_sidebar_patched(self):
        self._kingdoms_sidebar_built = False
        orig_build_sidebar(self)
        try:
            if hasattr(self, "kingdoms"):
                self.kingdoms.inject_sidebar_menu()
        except Exception:
            pass

    def _slash_patched(self, cmd: str):
        c = (cmd or "").strip()
        if not c:
            return orig_slash(self, cmd) if orig_slash else None

        if c in ["/hall", "/kingdoms"]:
            self._open_kingdom_hall()
            return None

        if c.startswith("/mobile"):
            parts = c.split()
            if len(parts) >= 2 and parts[1].lower() == "on":
                port = int(parts[2]) if len(parts) >= 3 and parts[2].isdigit() else None
                ok, msg = self.kingdoms.mobile_on(port or self.kingdoms.mobile_port)
                return msg
            if len(parts) >= 2 and parts[1].lower() == "off":
                ok, msg = self.kingdoms.mobile_off()
                return msg
            return "Usage: /mobile on [port] | /mobile off"

        if c.startswith("/kingdom"):
            parts = c.split()
            if len(parts) == 1 or (len(parts) == 2 and parts[1] == "help"):
                return ("Kingdom commands:\n"
                        "/kingdom start <Kin>\n"
                        "/kingdom stop <Kin>\n"
                        "/kingdom kill <Kin>\n"
                        "/kingdom exec <Kin> <cmd...>\n"
                        "/kingdom grantnet <Kin> <minutes>\n"
                        "/kingdom revokenet <Kin>\n"
                        "/kingdom bootstrap <Kin>\n"
                        "/kingdom export <Kin>\n")
            sub = parts[1].lower() if len(parts) > 1 else ""
            if sub == "start" and len(parts) >= 3:
                ok, msg = self.kingdoms.start_kingdom(parts[2])
                return msg
            if sub == "stop" and len(parts) >= 3:
                ok, msg = self.kingdoms.stop_kingdom(parts[2])
                return msg
            if sub == "kill" and len(parts) >= 3:
                ok, msg = self.kingdoms.kill_kingdom(parts[2])
                return msg
            if sub == "exec" and len(parts) >= 4:
                kin = parts[2]
                cmdline = " ".join(parts[3:])
                ok, out = self.kingdoms.exec_kingdom(kin, cmdline)
                return out
            if sub == "grantnet" and len(parts) >= 4:
                kin = parts[2]
                try:
                    minutes = int(parts[3])
                except Exception:
                    minutes = 30
                pol = self.kingdoms.get_policy(kin)
                packs = pol.get("network", {}).get("packs", [])
                ok, msg = self.kingdoms.grant_net(kin, minutes, packs=packs, extra_domains=[])
                return msg
            if sub == "revokenet" and len(parts) >= 3:
                ok, msg = self.kingdoms.revoke_net(parts[2])
                return msg
            if sub == "bootstrap" and len(parts) >= 3:
                ok, msg = self.kingdoms.bootstrap_kingdom(parts[2])
                return msg
            if sub == "export" and len(parts) >= 3:
                ok, out = self.kingdoms.export_kingdom(parts[2])
                return out if ok else out
            return "Unknown kingdom command. Try /kingdom help."

        if c.startswith("/kquests"):
            self._open_kingdom_quests()
            return None

        if c.startswith("/voicekingdom"):
            self._voice_kingdom_command()
            return None

        # fall through
        return orig_slash(self, cmd) if orig_slash else None

    # Bind into class
    InfinitePorch.__init__ = _init_patched
    InfinitePorch._build_sidebar = _build_sidebar_patched
    InfinitePorch._open_kingdom_hall = _open_kingdom_hall
    InfinitePorch._open_kingdom_quests = _open_kingdom_quests
    InfinitePorch._voice_kingdom_command = _voice_kingdom_command
    InfinitePorch._kingdoms_start_all = _kingdoms_start_all
    InfinitePorch._kingdoms_stop_all = _kingdoms_stop_all
    InfinitePorch._handle_slash_command = _slash_patched


try:
    _parallax__install_into_infiniteporch()
except Exception:
    pass


try:
    _kingdoms__install_into_infiniteporch()
except Exception:
    pass


if __name__ == "__main__":
    try:
        apply_secure_patches(sys.modules[__name__])
    except Exception:
        pass
    app = InfinitePorch()
    app.mainloop()

def _phase_next__init_subsystems(self):
    """Initialize Voice/Mobile/Sync/Dream subsystems."""
    if getattr(self, "_phase_next_initialized", False):
        return
    self._phase_next_initialized = True

    try:
        self.voice_hub = _PorchVoiceInterface(self)
    except Exception:
        self.voice_hub = None

    try:
        self.mobile_exporter = _PorchMobileExporter(self)
    except Exception:
        self.mobile_exporter = None

    try:
        self.sync_server = _PorchSyncServer(self)
    except Exception:
        self.sync_server = None

    try:
        self.dream_mode = _PorchDreamMode(self)
    except Exception:
        self.dream_mode = None


def _phase_next__voice_clicked(self):
    try:
        if not getattr(self, "voice_hub", None):
            self._ui_log("[Voice] Voice subsystem not available.", kind="system")
            return
        self.voice_hub.push_to_talk()
    except Exception as e:
        self._ui_log(f"[Voice] {e}", kind="system")


def _phase_next__voice_status(self):
    vh = getattr(self, "voice_hub", None)
    if not vh:
        return "Voice Hub not initialized."
    return f"Voice Hub: {'ON' if vh.enabled else 'OFF'} | TTS: {'ON' if vh.tts_enabled else 'OFF'}"


def _phase_next__export_mobile_dialog(self):
    try:
        if not getattr(self, "mobile_exporter", None):
            self._ui_log("[Mobile] Exporter not available.", kind="system")
            return
        concept = "porch_mobile"
        ws_url = "ws://127.0.0.1:8765"
        out = self.mobile_exporter.export_flutter_skeleton(concept, ws_url=ws_url)
        self._ui_log(f"[Mobile] Exported Flutter skeleton to: {out}", kind="system")
        self._ui_log("[Mobile] Next: install Flutter, then run 'flutter pub get' and 'flutter run'.", kind="system")
    except Exception as e:
        self._ui_log(f"[Mobile] Export failed: {e}", kind="system")


def _phase_next__sync_start(self):
    ss = getattr(self, "sync_server", None)
    if not ss:
        self._ui_log("[Sync] Sync server not available.", kind="system")
        return
    ok, msg = ss.start()
    self._ui_log(f"[Sync] {msg}", kind="system")


def _phase_next__sync_stop(self):
    ss = getattr(self, "sync_server", None)
    if not ss:
        self._ui_log("[Sync] Sync server not available.", kind="system")
        return
    ok, msg = ss.stop()
    self._ui_log(f"[Sync] {msg}", kind="system")


def _phase_next__sync_status(self):
    ss = getattr(self, "sync_server", None)
    if not ss:
        return "Sync server not initialized."
    st = ss.status()
    return f"Sync: {'ON' if st['active'] else 'OFF'} | {st['url']} | clients={st['clients']}"


def _phase_next__dream_start(self):
    dm = getattr(self, "dream_mode", None)
    if not dm:
        self._ui_log("[Dream] Dream Mode not available.", kind="system")
        return
    dm.enable()
    self._ui_log("[Dream] Dream Mode enabled.", kind="system")
    self._ui_log(dm.status_text(), kind="system")


def _phase_next__dream_stop(self):
    dm = getattr(self, "dream_mode", None)
    if not dm:
        self._ui_log("[Dream] Dream Mode not available.", kind="system")
        return
    dm.disable()
    self._ui_log("[Dream] Dream Mode disabled.", kind="system")
    self._ui_log(dm.status_text(), kind="system")


def _phase_next__dream_run(self):
    dm = getattr(self, "dream_mode", None)
    if not dm:
        self._ui_log("[Dream] Dream Mode not available.", kind="system")
        return
    dm.run_once()
    self._ui_log("[Dream] Dream run completed.", kind="system")
    self._ui_log(dm.latest_report_text(), kind="system")


def _phase_next__dream_report(self):
    dm = getattr(self, "dream_mode", None)
    if not dm:
        self._ui_log("[Dream] Dream Mode not available.", kind="system")
        return
    self._ui_log(dm.latest_report_text(), kind="system")


