if not getattr(InfinitePorch, "_phase_next_patch_applied", False):
    InfinitePorch._phase_next_patch_applied = True

    _phase_next__init__orig = InfinitePorch.__init__

    def _phase_next__init__patched(self, *a, **kw):
        _phase_next__init__orig(self, *a, **kw)
        try:
            _phase_next__init_subsystems(self)
        except Exception as e:
            try:
                self._ui_log(f"[Init] Phase-next subsystems failed: {e}", kind="system")
            except Exception:
                pass

    InfinitePorch.__init__ = _phase_next__init__patched

    # Bind methods
    InfinitePorch._voice_clicked = _phase_next__voice_clicked
    InfinitePorch._voice_status = _phase_next__voice_status
    InfinitePorch.export_mobile_dialog = _phase_next__export_mobile_dialog
    InfinitePorch.sync_start = _phase_next__sync_start
    InfinitePorch.sync_stop = _phase_next__sync_stop
    InfinitePorch.sync_status = _phase_next__sync_status
    InfinitePorch.dream_start = _phase_next__dream_start
    InfinitePorch.dream_stop = _phase_next__dream_stop
    InfinitePorch.dream_run = _phase_next__dream_run
    InfinitePorch.dream_report = _phase_next__dream_report

    # Patch sidebar to add Voice + Mobile/Sync + Dream sections (no duplicates)
    _phase_next__build_sidebar__orig = getattr(InfinitePorch, "_build_sidebar", None)

    def _phase_next__build_sidebar__patched(self, *a, **kw):
        if _phase_next__build_sidebar__orig:
            _phase_next__build_sidebar__orig(self, *a, **kw)

        try:
            _phase_next__init_subsystems(self)
        except Exception:
            pass

        try:
            import customtkinter as ctk  # type: ignore
        except Exception:
            return

        parent = getattr(self, "sidebar", None) or getattr(self, "sidebar_frame", None)
        if parent is None:
            return

        if getattr(self, "_phase_next_sidebar_added", False):
            return
        self._phase_next_sidebar_added = True

        def add_section(title, default_open=False):
            sec = ctk.CTkFrame(parent, fg_color="transparent")
            sec.pack(fill="x", padx=8, pady=(8, 0))

            header = ctk.CTkButton(
                sec, text=title, height=28,
                fg_color="#1b1f2a", hover_color="#242a3a",
                corner_radius=8
            )
            header.pack(fill="x")

            body = ctk.CTkFrame(sec, fg_color="transparent")
            body.pack(fill="x", pady=(6, 0))

            state = {"open": default_open}

            def toggle():
                state["open"] = not state["open"]
                if state["open"]:
                    body.pack(fill="x", pady=(6, 0))
                else:
                    body.pack_forget()

            header.configure(command=toggle)
            if not default_open:
                body.pack_forget()
            return body

        def add_btn(body, text, cmd):
            b = ctk.CTkButton(body, text=text, height=26, corner_radius=8, command=cmd)
            b.pack(fill="x", pady=4)
            return b

        # Voice
        body = add_section("🎤 Voice", default_open=False)
        add_btn(body, "🎙️ Push-to-Talk", self._voice_clicked)
        add_btn(body, "ℹ️ Voice Status", lambda: self._ui_log(self._voice_status(), kind="system"))

        # Mobile + Sync
        body = add_section("📱 Mobile + Sync", default_open=False)
        add_btn(body, "📱 Export Flutter Skeleton", self.export_mobile_dialog)
        add_btn(body, "🛰️ Start Sync Server", self.sync_start)
        add_btn(body, "🛑 Stop Sync Server", self.sync_stop)
        add_btn(body, "ℹ️ Sync Status", lambda: self._ui_log(self.sync_status(), kind="system"))

        # Dream
        body = add_section("💭 Dream Mode", default_open=False)
        add_btn(body, "🌙 Enable Dream Mode", self.dream_start)
        add_btn(body, "🛑 Disable Dream Mode", self.dream_stop)
        add_btn(body, "⚡ Run Dream Now", self.dream_run)
        add_btn(body, "📜 Morning Report", self.dream_report)
        add_btn(body, "ℹ️ Dream Status", lambda: self._ui_log(self.dream_mode.status_text() if self.dream_mode else "Dream Mode not initialized.", kind="system"))

    InfinitePorch._build_sidebar = _phase_next__build_sidebar__patched

    # Patch slash commands
    _phase_next__handle_slash__orig = getattr(InfinitePorch, "_handle_slash_command", None)

    def _phase_next__handle_slash_command(self, cmdline: str):
        handled = False
        if _phase_next__handle_slash__orig:
            try:
                handled = _phase_next__handle_slash__orig(self, cmdline)
            except Exception:
                handled = False
        if handled:
            return True

        parts = (cmdline or "").strip().split()
        if not parts:
            return False
        cmd = parts[0].lower()
        args = parts[1:]

        if cmd in ("/voice", "/mic"):
            sub = (args[0].lower() if args else "status")
            if sub in ("on", "start", "enable"):
                if self.voice_hub:
                    self.voice_hub.enable()
                self._ui_log(self._voice_status(), kind="system")
            elif sub in ("off", "stop", "disable"):
                if self.voice_hub:
                    self.voice_hub.disable()
                self._ui_log(self._voice_status(), kind="system")
            elif sub in ("talk", "ptt", "listen"):
                self._voice_clicked()
            else:
                self._ui_log(self._voice_status(), kind="system")
            return True

        if cmd == "/sync":
            sub = (args[0].lower() if args else "status")
            if sub in ("start", "on", "enable"):
                self.sync_start()
            elif sub in ("stop", "off", "disable"):
                self.sync_stop()
            else:
                self._ui_log(self.sync_status(), kind="system")
            return True

        if cmd == "/mobile":
            self.export_mobile_dialog()
            return True

        if cmd == "/dream":
            sub = (args[0].lower() if args else "status")
            if sub in ("on", "start", "enable"):
                self.dream_start()
            elif sub in ("off", "stop", "disable"):
                self.dream_stop()
            elif sub in ("run", "now"):
                self.dream_run()
            elif sub in ("report", "morning"):
                self.dream_report()
            else:
                dm = getattr(self, "dream_mode", None)
                self._ui_log(dm.status_text() if dm else "Dream Mode not initialized.", kind="system")
            return True

        return False

    InfinitePorch._handle_slash_command = _phase_next__handle_slash_command

