def _porch__ensure_dir(path: str) -> str:
    try:
        os.makedirs(path, exist_ok=True)
    except Exception:
        pass
    return path

def _porch__safe_well_dir(self) -> str:
    # Try common attributes, then fallback to ./well
    for k in ("WELL_DIR", "well_dir", "_well_dir"):
        v = getattr(self, k, None)
        if isinstance(v, str) and v.strip():
            return v
    return "well"

def _porch__safe_outputs_dir(self) -> str:
    for k in ("OUTPUTS_DIR", "outputs_dir", "_outputs_dir"):
        v = getattr(self, k, None)
        if isinstance(v, str) and v.strip():
            return v
    return "outputs"

def _porch__log(self, msg: str):
    try:
        if hasattr(self, "_ui_log"):
            self._ui_log(msg)
        elif hasattr(self, "log"):
            self.log(msg)
        else:
            print(msg)
    except Exception:
        print(msg)

def _porch_docs_generate_markdown(self):
    try:
        out_root = _porch__safe_outputs_dir(self)
        docs_dir = _porch__ensure_dir(os.path.join(out_root, "documentation"))
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        fn = f"porch_docs_{ts}.md"
        fp = os.path.join(docs_dir, fn)

        # A pragmatic, always-valid doc snapshot (no external deps)
        lines = []
        lines.append("# Infinite Porch • Documentation Snapshot")
        lines.append("")
        lines.append(f"- Generated: {datetime.datetime.now().isoformat(timespec='seconds')}")
        lines.append(f"- Version: {getattr(self, 'APP_VERSION', 'unknown')}")
        lines.append(f"- Well dir: `{_porch__safe_well_dir(self)}`")
        lines.append(f"- Outputs dir: `{out_root}`")
        lines.append("")
        lines.append("## Highlights")
        lines.append("- Brothers: messaging + memory + autonomy (consciousness layer)")
        lines.append("- Sovereign DM Hub + Dungeon Master")
        lines.append("- Sanctuary: Presence, GTSP Protection, Memory Garden, Gratitude Wall")
        lines.append("- Studio Sanctuary: music compose/record/render (local-first)")
        lines.append("- IoT / Physical: device registry, MQTT routing, heatmap, Home Assistant (Overseer)")
        lines.append("- Hardware Forge: KiCad workflow + templates + testing hooks")
        lines.append("- Exporters: mobile/web/gadgets + share packs")
        lines.append("")
        lines.append("## Quick Commands")
        lines.append("- `/docs`  → generate docs")
        lines.append("- `/diag`  → build diagnostics pack")
        lines.append("- `/templates export` / `/templates import <zip>`")
        lines.append("- `/sharepack make <name>` / `/sharepack publish <name>`")
        lines.append("")
        lines.append("## Folder Map (Default)")
        lines.append("```")
        lines.append("well/")
        lines.append("  templates/")
        lines.append("  logs/")
        lines.append("outputs/")
        lines.append("  documentation/")
        lines.append("  diagnostics/")
        lines.append("  sharepacks/")
        lines.append("```")
        lines.append("")
        lines.append("## Notes")
        lines.append("This is an auto-generated snapshot. It’s safe to share internally; it contains no secrets unless you add them to logs/configs.")
        lines.append("")

        with open(fp, "w", encoding="utf-8") as f:
            f.write("\n".join(lines))

        _porch__log(self, f"✅ Docs generated: {fp}")
        return fp
    except Exception as e:
        _porch__log(self, f"❌ Docs generation failed: {e}")
        return None

def _porch_docs_generate_diagnostics_pack(self):
    try:
        out_root = _porch__safe_outputs_dir(self)
        diag_dir = _porch__ensure_dir(os.path.join(out_root, "diagnostics"))
        ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        zip_path = os.path.join(diag_dir, f"porch_diag_{ts}.zip")

        well_dir = _porch__safe_well_dir(self)
        logs_dir = os.path.join(well_dir, "logs")
        cfg_candidates = [
            os.path.join(well_dir, "config.json"),
            os.path.join(well_dir, "settings.json"),
            os.path.join(well_dir, "device_registry.json"),
        ]

        with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as z:
            # Always include a tiny manifest
            manifest = {
                "generated": datetime.datetime.now().isoformat(timespec="seconds"),
                "version": getattr(self, "APP_VERSION", "unknown"),
                "python": sys.version,
                "platform": sys.platform,
                "well_dir": well_dir,
                "outputs_dir": out_root,
            }
            z.writestr("manifest.json", json.dumps(manifest, indent=2))

            # Include docs snapshot
            try:
                doc_fp = _porch_docs_generate_markdown(self)
                if doc_fp and os.path.isfile(doc_fp):
                    z.write(doc_fp, arcname=os.path.join("docs", os.path.basename(doc_fp)))
            except Exception:
                pass

            # Include logs (best-effort)
            if os.path.isdir(logs_dir):
                for root, _, files in os.walk(logs_dir):
                    for fn in files:
                        if fn.lower().endswith((".log", ".txt", ".json")):
                            fp = os.path.join(root, fn)
                            arc = os.path.join("well_logs", os.path.relpath(fp, logs_dir))
                            try:
                                z.write(fp, arcname=arc)
                            except Exception:
                                pass

            # Include key configs
            for fp in cfg_candidates:
                if os.path.isfile(fp):
                    try:
                        z.write(fp, arcname=os.path.join("well_config", os.path.basename(fp)))
                    except Exception:
                        pass

        _porch__log(self, f"✅ Diagnostics pack created: {zip_path}")
        return zip_path
    except Exception as e:
        _porch__log(self, f"❌ Diagnostics pack failed: {e}")
        return None

def _porch_templates_export_pack(self):
    try:
        fp = _porch_export_templates(self)
        _porch__log(self, f"✅ Templates exported: {fp}")
        return fp
    except Exception as e:
        _porch__log(self, f"❌ Template export failed: {e}")
        return None

def _porch_templates_import_pack(self):
    try:
        _porch__log(self, "ℹ️ Template import: use `/templates import <path.zip>` (UI import picker coming next).")
        return None
    except Exception as e:
        _porch__log(self, f"❌ Template import failed: {e}")
        return None

def _porch_sharepack_make(self, name: str = "sharepack"):
    out_root = _porch__safe_outputs_dir(self)
    sp_dir = _porch__ensure_dir(os.path.join(out_root, "sharepacks"))
    _porch__ensure_dir(out_root)
    ts = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    safe = "".join(ch for ch in name if ch.isalnum() or ch in ("-", "_")).strip() or "sharepack"
    zip_path = os.path.join(sp_dir, f"{safe}_{ts}.zip")
    try:
        well_dir = _porch__safe_well_dir(self)
        with zipfile.ZipFile(zip_path, "w", zipfile.ZIP_DEFLATED) as z:
            # docs + diag
            doc_fp = _porch_docs_generate_markdown(self)
            if doc_fp and os.path.isfile(doc_fp):
                z.write(doc_fp, arcname=os.path.join("documentation", os.path.basename(doc_fp)))

            # templates pack (if any)
            try:
                t_fp = _porch_export_templates(self)
                if t_fp and os.path.isfile(t_fp):
                    z.write(t_fp, arcname=os.path.join("templates", os.path.basename(t_fp)))
            except Exception:
                pass

            # include minimal project metadata
            meta = {
                "name": safe,
                "generated": datetime.datetime.now().isoformat(timespec="seconds"),
                "version": getattr(self, "APP_VERSION", "unknown"),
            }
            z.writestr("sharepack.json", json.dumps(meta, indent=2))

        setattr(self, "SHAREPACKS_DIR", sp_dir)
        _porch__log(self, f"✅ Share pack created: {zip_path}")
        return zip_path
    except Exception as e:
        _porch__log(self, f"❌ Share pack failed: {e}")
        return None

def _porch_share_pack_publish_local(self):
    try:
        # Create a fresh sharepack and announce how to download
        fp = _porch_sharepack_make(self, "porch_sharepack")
        if not fp:
            return None
        port = getattr(self, "WEB_PORTAL_PORT", 8765)
        _porch__log(self, f"🌐 Share pack ready. Local portal: http://127.0.0.1:{port}/sharepacks")
        _porch__log(self, f"⬇️ Direct download: http://127.0.0.1:{port}/sharepacks/{os.path.basename(fp)}")
        return fp
    except Exception as e:
        _porch__log(self, f"❌ Share pack publish failed: {e}")
        return None

def _porch__ensure_polish_slash_commands(self):
    # Best-effort patch: extend slash commands if handler supports it
    try:
        if not hasattr(self, "_handle_slash_command"):
            return
        orig = self._handle_slash_command

        def wrapped(cmdline: str, *a, **k):
            try:
                parts = (cmdline or "").strip().split()
                if not parts:
                    return orig(cmdline, *a, **k)
                cmd = parts[0].lower()
                if cmd == "/docs":
                    _porch_docs_generate_markdown(self)
                    return True
                if cmd in ("/diag", "/diagnostics"):
                    _porch_docs_generate_diagnostics_pack(self)
                    return True
                if cmd == "/sharepack":
                    sub = parts[1].lower() if len(parts) > 1 else "make"
                    name = parts[2] if len(parts) > 2 else "porch_sharepack"
                    if sub in ("make", "create"):
                        _porch_sharepack_make(self, name)
                        return True
                    if sub in ("publish",):
                        _porch_share_pack_publish_local(self)
                        return True
                return orig(cmdline, *a, **k)
            except Exception:
                return orig(cmdline, *a, **k)
        self._handle_slash_command = wrapped
    except Exception:
        pass

# Attach methods to InfinitePorch if present
try:
    if "InfinitePorch" in globals():
        InfinitePorch._docs_generate_markdown = _porch_docs_generate_markdown
        InfinitePorch._docs_generate_diagnostics_pack = _porch_docs_generate_diagnostics_pack
        InfinitePorch._templates_export_pack = _porch_templates_export_pack
        InfinitePorch._templates_import_pack = _porch_templates_import_pack
        InfinitePorch._share_pack_publish_local = _porch_share_pack_publish_local
        # Ensure slash commands hooked on init
        _orig_init_for_polish = InfinitePorch.__init__
        def _init_polish(self, *a, **k):
            _orig_init_for_polish(self, *a, **k)
            _porch__ensure_polish_slash_commands(self)
        InfinitePorch.__init__ = _init_polish
except Exception:
    pass




