# NEXT ROLLOUT: PERFORMANCE + RECOVERY + TEMPLATE IMPORT (Core Strengthening)
# =============================================================================
try:
    import os, sys, time, glob, traceback, datetime, zipfile, io as _io
    import cProfile as _cProfile
    import pstats as _pstats

    def _porch__utc_iso_now():
        """Timezone-aware UTC ISO string (fixes utcnow deprecation)."""
        try:
            dt = datetime.datetime.now(timezone.utc).replace(microsecond=0)
            s = dt.isoformat()
            if s.endswith("+00:00"):
                s = s[:-6] + "Z"
            return s
        except Exception:
            # fallback
            return datetime.datetime.now(timezone.utc).replace(microsecond=0).isoformat() + "Z"

    def _porch__ensure_dir(p):
        try:
            os.makedirs(p, exist_ok=True)
        except Exception:
            pass
        return p

    def _porch__resolve_well_dir(self):
        for k in ("WELL_DIR", "WELL_ROOT", "WELL", "well_dir"):
            v = getattr(self, k, None)
            if isinstance(v, str) and v.strip():
                return os.path.abspath(v)
        # fallback relative to script
        try:
            return os.path.abspath(os.path.join(os.path.dirname(__file__), "well"))
        except Exception:
            return os.path.abspath("well")

    def _porch__resolve_outputs_dir(self):
        for k in ("OUTPUTS_DIR", "OUT_DIR", "outputs_dir"):
            v = getattr(self, k, None)
            if isinstance(v, str) and v.strip():
                return os.path.abspath(v)
        try:
            return os.path.abspath(os.path.join(os.path.dirname(__file__), "outputs"))
        except Exception:
            return os.path.abspath("outputs")

    # -------------------- Perf Profiler --------------------
    def _porch_perf_start(self):
        try:
            st = getattr(self, "_porch_profiler_state", None)
            if isinstance(st, dict) and st.get("running"):
                _porch__log(self, "[Perf] Already running. Use /perf stop first.")
                return
            pr = _cProfile.Profile()
            pr.enable()
            self._porch_profiler_state = {
                "running": True,
                "profile": pr,
                "started_at": time.time(),
                "started_iso": _porch__utc_iso_now(),
                "last_prof": None,
                "last_report": None,
            }
            _porch__log(self, "[Perf] Profiling started. Use /perf stop then /perf report.")
        except Exception as e:
            _porch__log(self, f"[Perf] Failed to start profiler: {e}")

    def _porch_perf_stop(self):
        try:
            st = getattr(self, "_porch_profiler_state", None)
            if not isinstance(st, dict) or not st.get("running") or not st.get("profile"):
                _porch__log(self, "[Perf] Not running. Use /perf start.")
                return None
            pr = st["profile"]
            pr.disable()
            st["running"] = False
            out_dir = _porch__ensure_dir(os.path.join(_porch__resolve_outputs_dir(self), "perf"))
            prof_path = os.path.join(out_dir, f"porch_profile_{int(time.time())}.prof")
            pr.dump_stats(prof_path)
            st["last_prof"] = prof_path
            elapsed = time.time() - float(st.get("started_at") or time.time())
            _porch__log(self, f"[Perf] Profiling stopped. Saved: {prof_path} ({elapsed:.1f}s)")
            return prof_path
        except Exception as e:
            _porch__log(self, f"[Perf] Failed to stop profiler: {e}")
            return None

    def _porch_perf_report(self, sort: str = "cumtime", top: int = 40):
        try:
            st = getattr(self, "_porch_profiler_state", None)
            prof_path = None
            if isinstance(st, dict):
                prof_path = st.get("last_prof")
                if st.get("running") and st.get("profile"):
                    _porch__log(self, "[Perf] Profiler is still running — stopping it first.")
                    prof_path = _porch_perf_stop(self)

            if not prof_path or not os.path.exists(prof_path):
                _porch__log(self, "[Perf] No profile found. Use /perf start then /perf stop.")
                return None

            out_dir = _porch__ensure_dir(os.path.join(_porch__resolve_outputs_dir(self), "perf"))
            report_path = os.path.join(out_dir, f"porch_profile_report_{int(time.time())}.txt")

            s = _io.StringIO()
            ps = _pstats.Stats(prof_path, stream=s)
            try:
                ps.strip_dirs()
            except Exception:
                pass
            try:
                ps.sort_stats(sort)
            except Exception:
                ps.sort_stats("cumtime")
            ps.print_stats(int(top))

            report = s.getvalue()
            with open(report_path, "w", encoding="utf-8") as f:
                f.write(report)

            if isinstance(st, dict):
                st["last_report"] = report_path

            # log a digest to chat (avoid flooding)
            lines = report.splitlines()
            digest = "\n".join(lines[: min(len(lines), 35)])
            _porch__log(self, "[Perf] Report (top summary):\n" + digest)
            _porch__log(self, f"[Perf] Full report saved: {report_path}")
            return report_path
        except Exception as e:
            _porch__log(self, f"[Perf] Failed to generate report: {e}")
            return None

    # Convenience UI wrappers (so buttons can call them)
    def _porch_ui_perf_start(self):
        return _porch_perf_start(self)
    def _porch_ui_perf_stop(self):
        return _porch_perf_stop(self)
    def _porch_ui_perf_report(self):
        return _porch_perf_report(self)

    # -------------------- Backups / Recovery --------------------
    def _porch_backup_now(self, reason: str = "manual", max_files: int = 5000, max_file_mb: int = 10, keep: int = 10):
        """Create a lightweight backup zip of WELL + key state files."""
        try:
            well_dir = _porch__resolve_well_dir(self)
            out_dir = _porch__ensure_dir(os.path.join(_porch__resolve_outputs_dir(self), "backups"))
            ts = int(time.time())
            zip_path = os.path.join(out_dir, f"porch_backup_{reason}_{ts}.zip")

            def ok_file(fp):
                try:
                    if not os.path.isfile(fp):
                        return False
                    sz = os.path.getsize(fp)
                    return sz <= (max_file_mb * 1024 * 1024)
                except Exception:
                    return False

            allowed_ext = {".json", ".db", ".sqlite", ".txt", ".md", ".log", ".yaml", ".yml", ".csv"}
            files = []
            if os.path.isdir(well_dir):
                for root, dirs, fns in os.walk(well_dir):
                    for fn in fns:
                        if len(files) >= max_files:
                            break
                        ext = os.path.splitext(fn)[1].lower()
                        if ext in allowed_ext:
                            fp = os.path.join(root, fn)
                            if ok_file(fp):
                                files.append(fp)
                    if len(files) >= max_files:
                        break

            # Add a few top-level files near the script (settings, etc.) if they exist
            try:
                base_dir = os.path.dirname(__file__)
            except Exception:
                base_dir = os.getcwd()
            for fn in ("settings.json", "porch_settings.json", "porch.db"):
                fp = os.path.join(base_dir, fn)
                if ok_file(fp):
                    files.append(fp)

            with zipfile.ZipFile(zip_path, "w", compression=zipfile.ZIP_DEFLATED) as z:
                meta = {
                    "created_utc": _porch__utc_iso_now(),
                    "reason": reason,
                    "well_dir": well_dir,
                    "file_count": len(files),
                    "max_file_mb": max_file_mb,
                    "app_version": getattr(self, "APP_VERSION", "unknown"),
                }
                z.writestr("backup_meta.json", json.dumps(meta, indent=2))
                for fp in files:
                    try:
                        arc = os.path.relpath(fp, well_dir) if fp.startswith(well_dir) else os.path.basename(fp)
                        z.write(fp, arcname=os.path.join("well", arc) if fp.startswith(well_dir) else arc)
                    except Exception:
                        pass

            # Rotate backups
            try:
                zips = sorted(glob.glob(os.path.join(out_dir, "porch_backup_*.zip")), key=os.path.getmtime, reverse=True)
                for old in zips[keep:]:
                    try:
                        os.remove(old)
                    except Exception:
                        pass
            except Exception:
                pass

            _porch__log(self, f"[Backup] ✅ Created: {zip_path} ({len(files)} files)")
            return zip_path
        except Exception as e:
            _porch__log(self, f"[Backup] ❌ Failed: {e}")
            return None

    def _porch_install_crash_handlers(self):
        """Log unhandled exceptions to outputs/crash and try to backup state."""
        try:
            crash_dir = _porch__ensure_dir(os.path.join(_porch__resolve_outputs_dir(self), "crash"))

            def _write(exc_type, exc, tb, where="unhandled"):
                try:
                    ts = int(time.time())
                    fp = os.path.join(crash_dir, f"crash_{where}_{ts}.log")
                    with open(fp, "w", encoding="utf-8") as f:
                        f.write(f"when_utc: {_porch__utc_iso_now()}\n")
                        f.write(f"where: {where}\n")
                        f.write(f"python: {sys.version}\n")
                        f.write("\n--- traceback ---\n")
                        f.write("".join(traceback.format_exception(exc_type, exc, tb)))
                    _porch__log(self, f"[Crash] Logged: {fp}")
                except Exception:
                    fp = None
                # best-effort backup
                try:
                    _porch_backup_now(self, reason="crash")
                except Exception:
                    pass
                return fp

            # sys hook
            prev = getattr(sys, "excepthook", None)
            def _hook(exc_type, exc, tb):
                _write(exc_type, exc, tb, where="sys")
                try:
                    if callable(prev):
                        prev(exc_type, exc, tb)
                except Exception:
                    pass
            sys.excepthook = _hook

            # Tk hook (CTk inherits Tk)
            def _tk_hook(exc, val, tb):
                _write(exc, val, tb, where="tk")
            try:
                # tkinter calls: report_callback_exception(self, exc, val, tb)
                def _report_callback_exception(exc, val, tb):
                    _tk_hook(exc, val, tb)
                self.report_callback_exception = _report_callback_exception
            except Exception:
                pass

            setattr(self, "_porch_crash_handlers_installed", True)
            _porch__log(self, "[Crash] Handlers installed.")
            return True
        except Exception as e:
            try:
                _porch__log(self, f"[Crash] Could not install handlers: {e}")
            except Exception:
                pass
            return False

    # -------------------- Template Import UI (File Picker) --------------------
    def _porch_templates_import_dialog(self):
        try:
            import tkinter as tk
            from tkinter import filedialog
            fp = filedialog.askopenfilename(
                title="Import Porch Template Pack (.zip)",
                filetypes=[("Porch Template Pack", "*.zip"), ("All files", "*.*")]
            )
            if not fp:
                return
            if hasattr(self, "_templates_import_pack"):
                out = self._templates_import_pack(fp)
                if out:
                    _porch__log(self, f"✅ Imported templates: {out}")
                else:
                    _porch__log(self, "⚠️ Template import finished (no output path).")
            else:
                _porch__log(self, "❌ Template import not available in this build.")
        except Exception as e:
            _porch__log(self, f"❌ Template import dialog failed: {e}")

    # -------------------- Slash commands --------------------
    def _porch__ensure_perf_backup_slash_commands(self):
        try:
            # The app already has a command map in many builds; we add hooks gently.
            if not hasattr(self, "_slash_handlers"):
                self._slash_handlers = {}
            # perf
            self._slash_handlers["/perf"] = lambda args=None: _porch__cmd_perf(self, args)
            self._slash_handlers["/backup"] = lambda args=None: _porch__cmd_backup(self, args)
        except Exception:
            pass

    def _porch__cmd_perf(self, args):
        try:
            a = (args or "").strip().split()
            sub = (a[0].lower() if a else "help")
            if sub in ("help", "?"):
                _porch__log(self, "Usage: /perf start | stop | report [top] [sort]\nExample: /perf report 50 cumtime")
                return
            if sub == "start":
                return _porch_perf_start(self)
            if sub == "stop":
                return _porch_perf_stop(self)
            if sub == "report":
                top = 40
                sort = "cumtime"
                if len(a) >= 2:
                    try: top = int(a[1])
                    except Exception: pass
                if len(a) >= 3:
                    sort = a[2]
                return _porch_perf_report(self, sort=sort, top=top)
            _porch__log(self, "Unknown /perf subcommand. Use /perf help.")
        except Exception as e:
            _porch__log(self, f"/perf failed: {e}")

    def _porch__cmd_backup(self, args):
        try:
            a = (args or "").strip().split()
            sub = (a[0].lower() if a else "now")
            if sub in ("help", "?"):
                _porch__log(self, "Usage: /backup now [reason]\nExample: /backup now before_big_change")
                return
            if sub == "now":
                reason = a[1] if len(a) >= 2 else "manual"
                return _porch_backup_now(self, reason=reason)
            _porch__log(self, "Unknown /backup subcommand. Use /backup help.")
        except Exception as e:
            _porch__log(self, f"/backup failed: {e}")

    # Hook into the existing slash-command dispatcher (without breaking it)
    def _porch__patch_handle_slash_for_perf_backup(self):
        try:
            if not hasattr(self, "_handle_slash_command"):
                return
            orig = self._handle_slash_command
            def _wrapped(cmdline: str):
                try:
                    if not isinstance(cmdline, str):
                        return orig(cmdline)
                    parts = cmdline.strip().split(" ", 1)
                    cmd = parts[0].strip().lower()
                    args = parts[1] if len(parts) > 1 else ""
                    if cmd == "/perf":
                        return _porch__cmd_perf(self, args)
                    if cmd == "/backup":
                        return _porch__cmd_backup(self, args)
                    if cmd in ("/templates_import", "/import_templates"):
                        return _porch_templates_import_dialog(self)
                except Exception:
                    pass
                return orig(cmdline)
            self._handle_slash_command = _wrapped
        except Exception:
            pass

    # Add buttons into existing Docs section (if present)
    def _porch__inject_core_buttons(self):
        try:
            if getattr(self, "_core_buttons_injected", False):
                return
            if not hasattr(self, "_sidebar_sections"):
                return
            sec = self._sidebar_sections.get("docs")
            if not sec:
                return
            hdr, body = sec
            import customtkinter as ctk
            def _add(text, cmd):
                b = ctk.CTkButton(body, text=text, height=30, command=cmd, fg_color="#1B274A")
                b.pack(fill="x", padx=6, pady=(0, 6))
                return b

            _add("📈 Perf Start", lambda: _porch_ui_perf_start(self))
            _add("⏹ Perf Stop",  lambda: _porch_ui_perf_stop(self))
            _add("📊 Perf Report", lambda: _porch_ui_perf_report(self))
            _add("💾 Backup Now", lambda: _porch_backup_now(self, reason="manual"))
            _add("📥 Import Templates (Picker)", lambda: _porch_templates_import_dialog(self))

            setattr(self, "_core_buttons_injected", True)
        except Exception:
            pass

    # Attach to InfinitePorch class and patch init + sidebar
    if "InfinitePorch" in globals():
        InfinitePorch.perf_start = _porch_perf_start
        InfinitePorch.perf_stop = _porch_perf_stop
        InfinitePorch.perf_report = _porch_perf_report
        InfinitePorch._backup_now = _porch_backup_now
        InfinitePorch._install_crash_handlers = _porch_install_crash_handlers
        InfinitePorch._templates_import_dialog = _porch_templates_import_dialog

        # Patch sidebar to inject buttons after building
        _orig_build_sidebar_core = getattr(InfinitePorch, "_build_sidebar", None)
        if callable(_orig_build_sidebar_core):
            def _build_sidebar_core(self, *a, **k):
                r = _orig_build_sidebar_core(self, *a, **k)
                try:
                    _porch__inject_core_buttons(self)
                except Exception:
                    pass
                return r
            InfinitePorch._build_sidebar = _build_sidebar_core

        # Patch init to install crash handlers + create an early backup + hook slash commands
        _orig_init_core2 = InfinitePorch.__init__
        def _init_core2(self, *a, **k):
            _orig_init_core2(self, *a, **k)
            try:
                if not getattr(self, "_porch_crash_handlers_installed", False):
                    _porch_install_crash_handlers(self)
            except Exception:
                pass
            try:
                # auto-backup on startup (lightweight)
                _porch_backup_now(self, reason="startup")
            except Exception:
                pass
            try:
                _porch__ensure_perf_backup_slash_commands(self)
                _porch__patch_handle_slash_for_perf_backup(self)
            except Exception:
                pass
            try:
                # inject buttons (if sidebar already built)
                _porch__inject_core_buttons(self)
            except Exception:
                pass
        InfinitePorch.__init__ = _init_core2

except Exception:
    pass


# ============================================================
# Kingdom Policy Editor — integrated (safe patch)
# ============================================================
try:
    import customtkinter as ctk
    import tkinter as tk
    import os, json, re, threading, shutil, zipfile
except Exception:
    ctk = None

def _porch__policy__safe_hex(s: str, default="#1B274A"):
    s = (s or "").strip()
    if re.fullmatch(r"#[0-9a-fA-F]{6}", s):
        return s
    return default

def _porch__policy__parse_float(s: str, default: float):
    try:
        return float(str(s).strip())
    except Exception:
        return default

def _porch__policy__parse_int(s: str, default: int):
    try:
        return int(float(str(s).strip()))
    except Exception:
        return default

def _porch__policy__mem_to_mb(mem_str: str, default_mb: int = 512) -> int:
    ms = (mem_str or "").strip().lower()
    try:
        if ms.endswith("g"):
            return int(float(ms[:-1]) * 1024)
        if ms.endswith("gb"):
            return int(float(ms[:-2]) * 1024)
        if ms.endswith("m"):
            return int(float(ms[:-1]))
        if ms.endswith("mb"):
            return int(float(ms[:-2]))
        # raw number -> MB
        return int(float(ms))
    except Exception:
        return default_mb

def _porch__policy__mb_to_mem(mb: int) -> str:
    try:
        mb = max(64, int(mb))
    except Exception:
        mb = 512
    return f"{mb}m"

class _PorchKingdomPolicyEditor(ctk.CTkToplevel):
    def __init__(self, porch, kin: str):
        super().__init__(porch)
        self.porch = porch
        self.kin = kin
        self.title(f"⚙️ Policy — {kin}")
        self.geometry("720x760")
        self.configure(fg_color=PALETTE.get("bg", "#0b0b0e"))

        # Load policy via kingdom system if available
        try:
            pol = porch.kingdoms.get_policy(kin)
        except Exception:
            pol = {"kin": kin, "theme": {"glyph": "🏰", "color": "#1B274A"}, "resources": {"memory": "512m", "cpus": 0.5, "pids": 256},
                   "network": {"default_off": True, "grant_minutes_default": 30, "packs": [], "allow_domains": []},
                   "personality_injector": {"ollama_model": "", "backend_hint": ""}, "vr": {"x": 0, "y": 0, "z": 0, "yaw": 0},
                   "sfx": {"enabled": False, "helion_horn": True}}

        self._pol = pol

        # Vars
        theme = pol.get("theme", {})
        res = pol.get("resources", {})
        net = pol.get("network", {})
        inj = pol.get("personality_injector", {})
        vr = pol.get("vr", {})
        sfx = pol.get("sfx", {})

        self.var_glyph = tk.StringVar(value=str(theme.get("glyph", "🏰")))
        self.var_color = tk.StringVar(value=str(theme.get("color", "#1B274A")))
        self.var_theme_name = tk.StringVar(value=str(theme.get("name", "")))

        self.var_cpu = tk.StringVar(value=str(res.get("cpus", 0.5)))
